-- ───────────────────────────── Rede Lúcia v2: integração ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Roda DEPOIS de todas as outras migrações rede
-- (fundacao, consertos, perfil, publicar, conversa, descoberta, comunidades, avisos, moderacao). Só amarra pontas soltas que os
-- pacotes deixaram entre si; nenhuma tabela nova. Documento: docs/rede/V2.md (seção "Pendências para a coordenação").
--
-- 1. Idade mínima (18) também em seguir, bloquear e seguir comunidade, na Rede de hoje e na v2: os pacotes que redefinem
--    rede_seguir, rede_bloquear e rede_comunidade_seguir não receberam interno.rede_fix_idade; o gatilho vale para qualquer
--    versão dessas funções. Quem declarou menos de 18 anos não grava nada na Rede (LGPD art. 14; ECA Digital art. 9º).
--    Visitante (sem conta) e gravação feita pelo banco (migração, serviço) passam: interno.rede_fix_idade deixa passar
--    quando não há sessão.

create or replace function interno.rede_int_idade() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.rede_fix_idade(false);
  return new;
end $$;
revoke all on function interno.rede_int_idade() from public, anon, authenticated;

do $$ begin
  if to_regprocedure('interno.rede_fix_idade(boolean)') is not null then
    drop trigger if exists rede_int_idade on interno.rede_seguindo;
    create trigger rede_int_idade before insert on interno.rede_seguindo for each row execute function interno.rede_int_idade();
    drop trigger if exists rede_int_idade on interno.rede_bloqueios;
    create trigger rede_int_idade before insert on interno.rede_bloqueios for each row execute function interno.rede_int_idade();
    drop trigger if exists rede_int_idade on interno.rede_comunidades_seguidas;
    create trigger rede_int_idade before insert on interno.rede_comunidades_seguidas for each row execute function interno.rede_int_idade();
  end if;
end $$;

-- ───────────────────────────── Departamentos e termos, novembro de 2026 (etapa 8, B10 e B15) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Vai no fim do install.sql (a integração junta).
-- Documentação: docs/DEPARTAMENTOS-TERMOS.md.
--
-- B10. "Design" e "Desenvolvimento" viram um departamento só: UI/UX e Desenvolvimento (o id interno continua
--      'desenvolvimento'). Arte e design gráfico passam a ser da Comunicação (marketing e divulgação):
--        - quem tinha a função 'design' passa a ter 'marketing' (que já valia por 'design': materiais, imagens, Estúdio
--          de design, podcast), com a mesma data de entrada; ninguém perde acesso e ninguém ganha acesso novo ao código;
--        - quem era representante do departamento 'design' passa a representar a Comunicação ('jornalismo');
--        - o quadro, os pedidos e as passagens de bastão do departamento Design vão para a Comunicação;
--        - o canal e o grupo "design" do mural e das conversas ficam como estão (o texto já cifrado só abre com a chave
--          do grupo), agora com o nome "Arte e design (Comunicação)", e quem é da Comunicação (marketing) segue dentro;
--        - pedido, convite, candidatura, inscrição e aviso endereçados a 'design' são mapeados para a Comunicação, também
--          quando chegarem depois, de um navegador ou de uma versão antiga do site (gatilho de apelido).
-- B15. Termo de voluntário: quem aceitou e tem o texto guardado (interno.termos_aceites) continua. Quem aceitou "sem o
--      texto" (só a data no perfil) volta a ver o termo ao abrir o painel, para ler e aceitar; o aceite passa a exigir o
--      texto guardado. Ninguém fica sem texto. O termo de adesão das Horas também diz quando não tem texto guardado.
--
-- Dado de pessoa: nenhum dado novo. Só muda o nome da função de quem já tinha uma, e o aviso único que a pessoa recebe.

-- 1. Apelido: o que ainda chegar como 'design' vira Comunicação ─────────────────────────────────────────────
/** 'design' (valor antigo) vale como 'marketing'. Qualquer outro valor passa como veio. */
create or replace function interno.papel_sem_design(p text) returns text language sql immutable as $$
  select case when p = 'design' then 'marketing' else p end
$$;
/** A lista de funções de um aviso, sem 'design' e sem repetição. */
create or replace function interno.lista_sem_design(p text[]) returns text[] language sql immutable as $$
  select coalesce(array(select distinct interno.papel_sem_design(x) from unnest(coalesce(p, '{}')) x), '{}')
$$;

create or replace function interno.unificar_design_gatilho() returns trigger language plpgsql as $$
begin
  if tg_table_name = 'papeis' then
    new.papel := interno.papel_sem_design(new.papel);
    if new.papel = 'representante' and new.disciplina = 'design' then new.disciplina := 'jornalismo'; end if;
  elsif tg_table_name in ('candidaturas', 'inscricoes', 'convites') then
    new.papel := interno.papel_sem_design(new.papel);
  elsif tg_table_name = 'equipe_mensagens' then
    new.para := interno.papel_sem_design(new.para);
  elsif tg_table_name = 'avisos_gerais' then
    new.para := interno.lista_sem_design(new.para);
  end if;
  return new;
end $$;

drop trigger if exists lucia_unificar_design on interno.papeis;
create trigger lucia_unificar_design before insert or update on interno.papeis for each row execute function interno.unificar_design_gatilho();
drop trigger if exists lucia_unificar_design on interno.candidaturas;
create trigger lucia_unificar_design before insert or update on interno.candidaturas for each row execute function interno.unificar_design_gatilho();
drop trigger if exists lucia_unificar_design on interno.inscricoes;
create trigger lucia_unificar_design before insert or update on interno.inscricoes for each row execute function interno.unificar_design_gatilho();
drop trigger if exists lucia_unificar_design on interno.convites;
create trigger lucia_unificar_design before insert or update on interno.convites for each row execute function interno.unificar_design_gatilho();
drop trigger if exists lucia_unificar_design on interno.equipe_mensagens;
create trigger lucia_unificar_design before insert or update of para on interno.equipe_mensagens for each row execute function interno.unificar_design_gatilho();
drop trigger if exists lucia_unificar_design on interno.avisos_gerais;
create trigger lucia_unificar_design before insert or update of para on interno.avisos_gerais for each row execute function interno.unificar_design_gatilho();

-- 2. Os dados que já existem ───────────────────────────────────────────────────────────────────────────────
-- Funções: primeiro entra a nova, depois sai a antiga (a pessoa nunca fica sem função, e o lembrete de "saiu do painel"
-- não dispara). O histórico de cargos registra as duas linhas como feitas pelo sistema.
do $$
declare r record;
begin
  perform set_config('lucia.sistema', '1', true);
  for r in select * from interno.papeis where papel = 'design' order by criado_em loop
    insert into interno.papeis (usuario, papel, disciplina, concedido_por, criado_em)
    values (r.usuario, 'marketing', r.disciplina, r.concedido_por, r.criado_em) on conflict do nothing;
    delete from interno.papeis where id = r.id;
    perform interno.avisar(r.usuario, 'O departamento Design mudou: a arte e o design gráfico agora são da Comunicação (marketing e divulgação). Você continua com o Estúdio de design, os materiais e as imagens, e a sua data de entrada foi mantida. O design da interface (UI/UX) foi para o departamento UI/UX e Desenvolvimento: se quiser trabalhar nele, peça à coordenação.');
  end loop;
  for r in select * from interno.papeis where papel = 'representante' and disciplina = 'design' order by criado_em loop
    insert into interno.papeis (usuario, papel, disciplina, concedido_por, criado_em)
    values (r.usuario, 'representante', 'jornalismo', r.concedido_por, r.criado_em) on conflict do nothing;
    delete from interno.papeis where id = r.id;
  end loop;
end $$;

update interno.candidaturas set papel = 'marketing' where papel = 'design';
update interno.inscricoes set papel = 'marketing' where papel = 'design';
update interno.convites set papel = 'marketing' where papel = 'design';
update interno.equipe_mensagens set para = 'marketing' where para = 'design';
update interno.avisos_gerais set para = interno.lista_sem_design(para) where 'design' = any(para);

-- O departamento Design deixa de existir como página: o que era dele passa à Comunicação (os textos de ambos ficam).
do $$
begin
  if exists (select 1 from interno.departamentos_info where id = 'design') then
    update interno.departamento_quadro set departamento = 'jornalismo' where departamento = 'design';
    update interno.departamento_pedidos set para = 'jornalismo' where para = 'design';
    update interno.departamento_pedidos set de = 'jornalismo' where de = 'design';
    update interno.departamento_bastoes set departamento = 'jornalismo' where departamento = 'design';
    delete from interno.departamentos_info where id = 'design';
  end if;
end $$;

-- Os textos de apresentação, só onde ainda estão como no início (o que a coordenação editou não é tocado).
update interno.departamentos_info
   set descricao = 'O design da interface (UI/UX), o site e o painel: telas, acessibilidade, erros, melhorias e segurança.'
 where id = 'desenvolvimento' and descricao = 'O site e o painel: erros, melhorias e segurança.';
update interno.departamentos_info
   set descricao = descricao || ' Também a arte e o design gráfico: cartazes, capas, posts e a identidade do instituto, sempre com a marca de sempre.'
 where id = 'jornalismo' and descricao not like '%design gráfico%' and char_length(descricao) <= 200;
update interno.conversas set nome = 'Arte e design (Comunicação)' where tipo = 'departamento' and departamento = 'design' and nome = 'Design';
update interno.conversas set nome = 'UI/UX e Desenvolvimento' where tipo = 'departamento' and departamento = 'desenvolvimento' and nome = 'Desenvolvimento';

-- 3. Textos do banco ───────────────────────────────────────────────────────────────────────────────────────
create or replace function interno.nome_papel(p text) returns text language sql immutable as $$
  select case p when 'coordenacao' then 'coordenação' when 'vice' then 'coordenação pedagógica' when 'supervisao' then 'supervisão' when 'curadoria' then 'curadoria'
    when 'mediacao' then 'mediação' when 'educacao' then 'educação' when 'educacao_secundaria' then 'educação secundária' when 'revisao' then 'revisão'
    when 'traducao' then 'tradução' when 'jornalismo' then 'comunicação (jornal, rádio e podcast)' when 'mentoria' then 'aula de reforço'
    when 'design' then 'comunicação (arte e design gráfico)'
    when 'marketing' then 'comunicação (marketing, divulgação, arte e design gráfico)' when 'desenvolvimento' then 'UI/UX e desenvolvimento'
    when 'representante' then 'representante do departamento' when 'porta_voz' then 'porta-voz' when 'saude' then 'profissional de saúde'
    else coalesce(p, '') end
$$;

-- O pedido de arte do podcast agora avisa a Comunicação (quem faz arte), não mais uma função 'design' que não existe.
create or replace function public.podcast_design_pedir(p_episodio uuid, p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_id uuid; v_titulo text; r record;
begin
  if not interno.podcaster() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('podcast_design', 20, 1440);
  select titulo into v_titulo from podcast_episodios where id = p_episodio;
  if not found then perform interno.erro('nao_encontrado'); end if;
  insert into podcast_pedidos (episodio, texto, pedido_por) values (p_episodio, interno.txt(p_texto, 'texto', 5, 1000), v) returning id into v_id;
  for r in select distinct usuario from papeis where papel in ('marketing', 'design') and usuario <> v loop
    perform interno.avisar(r.usuario, format('Pedido de arte para o podcast: episódio "%s". Veja em Podcast → Pedidos de arte.', v_titulo));
  end loop;
  return jsonb_build_object('id', v_id);
end $$;

-- 4. Termo de voluntário: ninguém fica sem texto ────────────────────────────────────────────────────────────
-- Quem aceitou sem o texto guardado (só a data no perfil, ou a versão vigente sem linha em termos_aceites) volta a ver o
-- termo ao abrir o painel. A versão "anterior" nunca é igual à vigente, então o painel pede o aceite; o aceite antigo
-- continua listado para a coordenação como "antigo" até a pessoa aceitar de novo (public.termos_aceites_listar).
update interno.perfis f set termo_voluntario_versao = 'anterior'
 where f.termo_voluntario_em is not null
   and (f.termo_voluntario_versao is null or f.termo_voluntario_versao = interno.termo_voluntario_vigente())
   and not exists (select 1 from interno.termos_aceites t
                    where t.usuario = f.id and t.termo = 'voluntario' and t.versao = interno.termo_voluntario_vigente());

/** Confirma que a pessoa está aqui como voluntária (Lei nº 9.608/1998). Só vale com o texto guardado da versão vigente. */
create or replace function public.termo_voluntario_aceitar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not exists (select 1 from termos_aceites t where t.usuario = v and t.termo = 'voluntario' and t.versao = interno.termo_voluntario_vigente()) then
    perform interno.erro('falta_termo');
  end if;
  update perfis set termo_voluntario_em = coalesce(termo_voluntario_em, now()), termo_voluntario_versao = interno.termo_voluntario_vigente() where id = v;
  perform interno.registrar('termo_voluntario', v::text, jsonb_build_object('versao', interno.termo_voluntario_vigente()));
  return jsonb_build_object('ok', true);
end $$;

/** O termo de adesão das Horas da pessoa; "sem_texto" quando o aceite é de antes de o texto ser guardado. */
create or replace function public.termo_meu() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select (select jsonb_build_object('nome_completo', t.nome_completo, 'versao', t.versao, 'aceito_em', t.aceito_em,
            'sem_texto', not exists (select 1 from termos_aceites a where a.usuario = t.usuario and a.termo = 'adesao' and a.versao = t.versao))
            from termos_adesao t where t.usuario = auth.uid())
$$;

revoke all on function interno.papel_sem_design(text) from public, anon, authenticated;
revoke all on function interno.lista_sem_design(text[]) from public, anon, authenticated;
revoke all on function interno.unificar_design_gatilho() from public, anon, authenticated;
revoke all on function public.podcast_design_pedir(uuid, text) from public;
grant execute on function public.podcast_design_pedir(uuid, text) to anon, authenticated, service_role;
revoke all on function public.termo_voluntario_aceitar() from public;
grant execute on function public.termo_voluntario_aceitar() to anon, authenticated, service_role;
revoke all on function public.termo_meu() from public;
grant execute on function public.termo_meu() to anon, authenticated, service_role;

-- ───────────────────────── Pesquisa dos 12 eixos da equipe, novembro de 2026 ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Ainda NÃO está no install.sql (a integração junta).
-- Texto do pacote e da base legal: docs/eixos-equipe.md.
--
-- O que guarda: SÓ o agregado. A função recebe os 12 números (0 a 100, na ordem fixa de interno.eixos_equipe_ids abaixo),
-- soma em baldes (cinco faixas por eixo) e esquece os números. Não guarda a resposta de ninguém, nem data, nem tamanho de
-- teste. A marca "já respondeu" fica em outra tabela, só com a conta e a versão do aviso aceito (prova do consentimento), sem
-- nenhuma ligação com o valor.
--
-- Opinião política é dado pessoal sensível (LGPD, Lei 13.709/2018, art. 5º, II); o tratamento exige o consentimento específico
-- e destacado do art. 11, I, para finalidade determinada (art. 8º, § 4º). O agregado anonimizado deixa de ser dado pessoal
-- (art. 12), desde que não possa ser revertido: por isso a coordenação só vê o resultado quando há pelo menos 5 respostas e só
-- em degraus de 5 em 5 (o que se vê é uma "foto" tirada quando o total chega a 5, 10, 15...), para que a diferença entre duas
-- consultas não revele a resposta de uma pessoa.
--
-- Nenhuma tabela no esquema public; acesso só pelas funções public.* abaixo (security definer, search_path = interno, pg_temp).

create table if not exists interno.eixos_equipe_vivo (
  id boolean primary key default true check (id),
  n integer not null default 0,
  soma bigint[] not null default array_fill(0::bigint, array[12]),
  baldes integer[] not null default array_fill(0, array[60])   -- eixo * 5 + faixa (eixo de 0 a 11, faixa de 0 a 4)
);
create table if not exists interno.eixos_equipe_publicado (
  id boolean primary key default true check (id),
  n integer not null default 0,
  soma bigint[] not null default array_fill(0::bigint, array[12]),
  baldes integer[] not null default array_fill(0, array[60])
);
create table if not exists interno.eixos_equipe_marcas (
  usuario uuid primary key,
  versao text not null check (char_length(versao) between 1 and 40)
);
insert into interno.eixos_equipe_vivo (id) values (true) on conflict do nothing;
insert into interno.eixos_equipe_publicado (id) values (true) on conflict do nothing;

alter table interno.eixos_equipe_vivo enable row level security;
alter table interno.eixos_equipe_publicado enable row level security;
alter table interno.eixos_equipe_marcas enable row level security;
revoke all on interno.eixos_equipe_vivo, interno.eixos_equipe_publicado, interno.eixos_equipe_marcas from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on interno.eixos_equipe_vivo, interno.eixos_equipe_publicado, interno.eixos_equipe_marcas from anon, authenticated;
  end if;
end $$;

/** Os 12 eixos, na ordem em que o teste manda os números (a mesma de content/eixos.json). */
create or replace function interno.eixos_equipe_ids() returns text[] language sql immutable as $$
  select array['propriedade','planejamento','comercio','poder','liberdades','territorio','soberania','conflito','diversidade','religiao','costumes','tecnologia']
$$;
revoke all on function interno.eixos_equipe_ids() from public;

/** A pessoa (da equipe) já respondeu? Só diz sim ou não. */
create or replace function public.eixos_equipe_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('respondeu', exists (select 1 from eixos_equipe_marcas where usuario = v));
end $$;
revoke all on function public.eixos_equipe_estado() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.eixos_equipe_estado() to authenticated; end if;
end $$;

/**
 * Soma uma resposta ao agregado. Recebe SÓ os 12 números; exige o consentimento marcado e a versão do aviso. Uma resposta por
 * conta (a marca fica separada). Não devolve nada além de "ok".
 */
create or replace function public.eixos_equipe_enviar(p_pontos integer[], p_consentimento boolean, p_versao text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  i integer;
  f integer;
  r eixos_equipe_vivo%rowtype;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if p_consentimento is distinct from true then perform interno.erro('invalido:consentimento'); end if;
  if p_versao is null or char_length(p_versao) not between 1 and 40 then perform interno.erro('invalido:versao'); end if;
  if p_pontos is null or array_ndims(p_pontos) is distinct from 1 or array_length(p_pontos, 1) is distinct from 12 then perform interno.erro('invalido:pontos'); end if;
  for i in 1..12 loop
    if p_pontos[i] is null or p_pontos[i] < 0 or p_pontos[i] > 100 then perform interno.erro('invalido:pontos'); end if;
  end loop;

  -- Trava a linha do agregado: duas respostas ao mesmo tempo não se perdem.
  select * into r from eixos_equipe_vivo where id for update;
  insert into eixos_equipe_marcas (usuario, versao) values (v, p_versao) on conflict (usuario) do nothing;
  if not found then perform interno.erro('ja_respondeu'); end if;

  r.n := r.n + 1;
  for i in 1..12 loop
    r.soma[i] := r.soma[i] + p_pontos[i];
    f := least(4, greatest(0, floor(p_pontos[i] / 20.0)::integer));
    r.baldes[(i - 1) * 5 + f + 1] := r.baldes[(i - 1) * 5 + f + 1] + 1;
  end loop;
  update eixos_equipe_vivo set n = r.n, soma = r.soma, baldes = r.baldes where id;
  -- A "foto" que a coordenação enxerga só muda de 5 em 5 respostas.
  if r.n >= 5 and r.n % 5 = 0 then
    update eixos_equipe_publicado set n = r.n, soma = r.soma, baldes = r.baldes where id;
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.eixos_equipe_enviar(integer[], boolean, text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.eixos_equipe_enviar(integer[], boolean, text) to authenticated; end if;
end $$;

/** Só a coordenação: média e distribuição da equipe, ou "liberado: false" enquanto houver menos de 5 respostas. */
create or replace function public.eixos_equipe_resultado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  p eixos_equipe_publicado%rowtype;
  ids text[] := interno.eixos_equipe_ids();
  media jsonb := '{}'::jsonb;
  dist jsonb := '{}'::jsonb;
  i integer;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into p from eixos_equipe_publicado where id;
  if p.n < 5 then return jsonb_build_object('liberado', false, 'minimo', 5); end if;
  for i in 1..12 loop
    media := media || jsonb_build_object(ids[i], round(p.soma[i]::numeric / p.n));
    dist := dist || jsonb_build_object(ids[i], to_jsonb(p.baldes[(i - 1) * 5 + 1 : (i - 1) * 5 + 5]));
  end loop;
  return jsonb_build_object('liberado', true, 'minimo', 5, 'n', p.n, 'media', media, 'distribuicao', dist);
end $$;
revoke all on function public.eixos_equipe_resultado() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.eixos_equipe_resultado() to authenticated; end if;
end $$;

-- ───────────────────────── Controles do coordenador, novembro de 2026 (Etapa 8, pacote controles) ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Ainda NÃO está no install.sql (a integração junta).
-- Texto do pacote: docs/PAINEL-CONTROLES.md.
--
-- Os sete controles "só falta tela" já tinham função no banco (canais_salvar, equipe_sala_salvar, radio_*, rede_moderador_definir,
-- rede_com_nucleo_abrir, arquivo_bloquear, curriculo_publicar_agora). Aqui só entram as funções de LEITURA que faltavam para a tela
-- mostrar o que já está valendo, "publicar agora" para quem não decide o currículo e o resumo do Centro de controle.
-- Nada daqui guarda dado novo de pessoa: moderadores são pessoas da própria equipe (nome já visível a quem cuida) e o resto é contagem.
--
-- Nenhuma tabela no esquema public; acesso só pelas funções public.* (security definer, search_path = interno, pg_temp).
-- Nenhuma função do esquema interno é liberada a anon/authenticated por este arquivo.

-- Quem modera cada comunidade da Rede (a mediação nomeia; pôr e tirar usam rede_moderador_definir, que já existe).
create or replace function public.rede_moderadores_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.cuida() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'comunidades', (select coalesce(jsonb_agg(jsonb_build_object('slug', c.slug, 'nome', c.nome, 'categoria', c.categoria, 'tipo', c.tipo) order by c.categoria, c.nome), '[]'::jsonb) from rede_comunidades c),
    'moderadores', (select coalesce(jsonb_agg(jsonb_build_object('comunidade', m.comunidade, 'usuario', m.usuario, 'nome', interno.nome_visto(f.nome)) order by m.comunidade, f.nome), '[]'::jsonb)
                    from rede_moderadores m join perfis f on f.id = m.usuario));
end $$;
revoke all on function public.rede_moderadores_listar() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.rede_moderadores_listar() to authenticated; end if;
end $$;

-- Núcleos de estudo ativos e se já têm o espaço fechado da Rede (só a contagem de gente; nunca quem é).
create or replace function public.rede_nucleos_fechados_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'nucleo', n.id, 'nome', n.nome, 'cidade', n.cidade, 'uf', n.uf,
      'acompanha', coalesce((select interno.nome_visto(p.nome) from perfis p where p.id = n.acompanha), ''),
      'aberto', r.id is not null,
      'rede', r.id,
      'pessoas', case when r.id is null then 0 else (select count(*) from rede_nucleo_membros m where m.nucleo = r.id) end) order by n.uf, n.cidade, n.nome)
    from nucleos n left join rede_nucleos r on r.nucleo = n.id where n.ativo), '[]'::jsonb);
end $$;
revoke all on function public.rede_nucleos_fechados_listar() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.rede_nucleos_fechados_listar() to authenticated; end if;
end $$;

-- Arquivos bloqueados: a lista (impressão digital, motivo, data) para a curadoria ver e, se foi engano, desfazer.
-- A função arquivos_bloqueados() que já existe é só da rotina de publicação (chave de serviço).
create or replace function public.arquivos_bloqueados_ver() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('sha256', b.sha256, 'motivo', b.motivo, 'criado_em', b.criado_em) order by b.criado_em desc), '[]'::jsonb)
          from (select * from arquivos_bloqueados order by criado_em desc limit 300) b);
end $$;

create or replace function public.arquivo_desbloquear(p_sha256 text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_sha256, '') !~ '^[a-f0-9]{64}$' then perform interno.erro('invalido:sha256'); end if;
  delete from arquivos_bloqueados where sha256 = p_sha256;
  if found then perform interno.registrar('arquivo_desbloqueado', p_sha256); end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.arquivos_bloqueados_ver() from public;
revoke all on function public.arquivo_desbloquear(text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    grant execute on function public.arquivos_bloqueados_ver() to authenticated;
    grant execute on function public.arquivo_desbloquear(text) to authenticated;
  end if;
end $$;

-- "Publicar agora" para quem cuida do site (coordenação, vice, curadoria, desenvolvimento, quem decide o currículo).
-- Divide o limite de 6 por hora com curriculo_publicar_agora. A rota /api/painel/publicar-agora chama esta e, se o banco
-- ainda não a tiver, cai na antiga.
create or replace function public.publicar_agora_pedir() returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not (interno.coord() or interno.curador() or interno.tem('desenvolvimento') or interno.curriculo_decide()) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('publicar_agora', 6, 60);
  perform interno.registrar('publicar_agora', '', '{}'::jsonb);
  return true;
end $$;
revoke all on function public.publicar_agora_pedir() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.publicar_agora_pedir() to authenticated; end if;
end $$;

-- O Centro de controle: uma olhada em tudo (só contagens e liga/desliga; nenhum endereço, nenhuma pessoa).
create or replace function public.controles_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  c jsonb := coalesce((select valor from configuracoes where chave = 'canais'), '{}'::jsonb);
  r jsonb := coalesce((select valor from configuracoes where chave = 'radio'), '{}'::jsonb);
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'whatsapp', coalesce(c ->> 'whatsapp', '') <> '',
    'telegram', coalesce(c ->> 'telegram', '') <> '',
    'sala', coalesce((select valor ->> 'sala' from configuracoes where chave = 'equipe'), '') <> '',
    'radio_no_ar', coalesce((r ->> 'no_ar')::boolean, false),
    'radio_canais', (select count(*) from radio_canais),
    'radio_faixas', (select count(*) from radio_faixas),
    'moderadores', (select count(*) from rede_moderadores),
    'nucleos_fechados', (select count(*) from rede_nucleos),
    'arquivos_bloqueados', (select count(*) from arquivos_bloqueados));
end $$;
revoke all on function public.controles_resumo() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then grant execute on function public.controles_resumo() to authenticated; end if;
end $$;

-- ───────────────────────── Back-end novo, parte 1 (Etapa 8), novembro de 2026 ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Ainda NÃO está no install.sql (a integração junta;
-- rode DEPOIS do install.sql, porque este arquivo troca interno.limite por uma versão que lê os limites ajustados).
-- Texto do pacote: docs/backend-1.md.
--
-- Itens (cada um com função SQL, tela em components/painel/BackendUm.tsx e teste em scripts/testar-backend-1.mjs):
--   1. recursos ligados sem publicar de novo           public.recursos_lidos / recursos_estado / recurso_ajustar
--   2. confirmação de segunda pessoa                    public.confirmacoes_listar / confirmacao_decidir / confirmacao_cancelar
--   3. zerar segundo fator e aparelhos                  public.zerar_2fa_pedir / zerar_aparelhos_pedir
--   4. segunda avaliação externa pelo painel            public.avaliacao_externa_estado / avaliacao_externa_pedir
--   5. limites ajustáveis                               public.limites_listar / limite_ajustar / limite_restaurar
--   6. constantes do site no banco                      public.site_constantes_ler / _listar / _gravar
--   7. aula da semana e destaques da home               public.destaques_ler / destaque_* / aula_semana_*
--   8. texto de apresentação da trilha                  public.trilha_apresentacao_*
--   9. editar conteúdo em arquivo (PR no GitHub)        public.conteudo_pode_editar / conteudo_pr_registrar / conteudo_prs_listar
--  10. correções aprovadas aplicadas por PR             public.correcao_propor / correcoes_listar / correcao_decidir / correcao_para_aplicar / correcao_aplicada
--
-- Nenhuma tabela no esquema public; acesso só pelas funções public.* (security definer, search_path = interno, pg_temp).
-- Nenhuma função de interno.* é executável por anon nem authenticated.
-- Privacidade (LGPD, Lei 13.709/2018, art. 6º, III e VII): o PR aberto no GitHub não leva nome de ninguém; guardamos só a conta
-- que pediu, no banco, para o registro de atividades.

-- ───────────────────────── Tabelas ─────────────────────────

/** Catálogo dos recursos do site (a mesma lista de lib/recursos.ts; o teste confere). so_pelo_nome: "todos" não liga. */
create table if not exists interno.recursos_catalogo (
  nome text primary key check (nome ~ '^[a-z0-9-]{2,40}$'),
  so_pelo_nome boolean not null default false
);
insert into interno.recursos_catalogo (nome, so_pelo_nome) values
  ('meu-estudo', false), ('exercicios', false), ('revisoes', false), ('turma', false), ('professores', false),
  ('mapa-curricular', false), ('nivelamento', false), ('metas', false), ('vlibras', false), ('ajudou', false),
  ('guia-contribuir', false), ('pratica-sem-placar', false), ('enem-video', false), ('enem-curso', false),
  ('escola', true), ('vale-o-escrito', true), ('rede-v2', true),
  ('alumia-2', true), ('alumia-stories', true), ('alumia-modo-ato', true), ('alumia-org', true), ('alumia-chat-grupo', true), ('alumia-proximas', true), ('alumia-entrada', true), ('alumia-linha-aberta', true), ('alumia-convites', true), ('alumia-fui-detido', true), ('alumia-estudo', true), ('alumia-coautoria', true), ('alumia-video-post', true), ('alumia-mapa', true), ('alumia-ao-vivo', true), ('alumia-alcance', true), ('alumia-leve', true), ('alumia-traducao', true), ('alumia-telegram', true), ('alumia-aberta', true), -- Alumia, Onda 5 (F0), a entrada com triagem (20261110-alumia-entrada.sql), os convites (20261114-alumia-o8-porta.sql), o Fui detido (20261115-alumia-o9-modoato.sql), o estudo da onda 11 (20261117-alumia-o11-*.sql), assinar junto e o vídeo curto da onda 12 (20261118-alumia-o12-coautoria.sql e -midia.sql), o mapa, o ao vivo, levar para fora, o leve, a tradução e o Telegram da onda 13 (20261119-alumia-o13-*.sql), a Alumia aberta da integração (20261121-alumia-integracao-fim.sql)
  ('turmas', false), -- em pausa (T08): "todos" não liga (lib/recursos.ts, EM_PAUSA); ligar pelo painel vale na hora
  ('assistente-publico', false), -- T03: o assistente em todo o site, sem conta (app/api/assistente); ligado por padrão
  ('fediverso-total', true), ('fediverso-grupos', true) -- Alumia mesclada ao Fediverso (PLANO-FEDIVERSO): só pelo nome, desligadas
on conflict (nome) do update set so_pelo_nome = excluded.so_pelo_nome;

/** O que a coordenação decidiu pelo painel. Linha existe = decisão explícita (ligado true liga, false desliga). */
create table if not exists interno.recursos_vivos (
  nome text primary key references interno.recursos_catalogo (nome) on delete cascade,
  ligado boolean not null,
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Pedidos que esperam uma segunda pessoa da coordenação (ou da vice-coordenação). */
create table if not exists interno.confirmacoes (
  id uuid primary key default gen_random_uuid(),
  tipo text not null check (tipo in ('recurso', 'zerar_2fa', 'zerar_aparelhos', 'avaliacao_externa')),
  alvo text not null default '' check (char_length(alvo) <= 80),
  motivo text not null default '' check (char_length(motivo) <= 500),
  pedido_por uuid references interno.perfis (id) on delete set null,
  pedido_em timestamptz not null default now(),
  expira_em timestamptz not null default now() + interval '48 hours',
  status text not null default 'aguardando' check (status in ('aguardando', 'confirmada', 'recusada', 'cancelada', 'expirada')),
  decidido_por uuid references interno.perfis (id) on delete set null,
  decidido_em timestamptz
);
create index if not exists confirmacoes_status on interno.confirmacoes (status, pedido_em desc);

/** Limites ajustados pela coordenação. Sem linha, vale o que o código da função pede. */
create table if not exists interno.limites_config (
  acao text primary key check (acao ~ '^[a-z0-9_]{2,60}$'),
  maximo integer not null check (maximo between 1 and 5000),
  minutos integer not null check (minutos between 1 and 1440),
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Constantes do site: só as chaves conhecidas (interno.site_constantes_modelo). */
create table if not exists interno.site_constantes (
  chave text primary key check (chave ~ '^[a-z_]{2,40}$'),
  valor text not null check (char_length(valor) <= 300),
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Destaques da home: até 6 posições, apontando para páginas do próprio site. */
create table if not exists interno.destaques_home (
  posicao smallint primary key check (posicao between 1 and 6),
  caminho text not null check (caminho ~ '^/[a-z0-9/_-]{1,160}$'),
  titulo text not null check (char_length(titulo) between 3 and 120),
  resumo text not null default '' check (char_length(resumo) <= 240),
  ate date,
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Aula da semana escolhida à mão (a semana é o número usado em lib/lambe-do-dia.ts). Sem linha, o site sorteia como sempre. */
create table if not exists interno.aula_semana (
  semana integer primary key check (semana between 1 and 100000),
  trilha text not null check (trilha ~ '^[a-z0-9-]{2,80}$'),
  aula text not null check (aula ~ '^[a-z0-9-]{1,100}$'),
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Texto de apresentação de cada trilha, por idioma. */
create table if not exists interno.trilhas_apresentacao (
  slug text not null check (slug ~ '^[a-z0-9-]{2,80}$'),
  idioma text not null check (idioma in ('pt', 'en', 'es', 'fr', 'ru', 'zh')),
  texto text not null check (char_length(texto) between 10 and 1200),
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now(),
  primary key (slug, idioma)
);

/** PRs abertos pelo painel (edição de conteúdo em arquivo ou correção aprovada). */
create table if not exists interno.conteudo_prs (
  id uuid primary key default gen_random_uuid(),
  caminho text not null check (caminho ~ '^content/[a-z0-9/_.-]{3,200}$'),
  numero integer not null check (numero > 0),
  url text not null check (url ~ '^https://github\.com/[A-Za-z0-9._-]+/[A-Za-z0-9._-]+/pull/[0-9]+$'),
  tipo text not null default 'edicao' check (tipo in ('edicao', 'correcao')),
  por uuid references interno.perfis (id) on delete set null,
  em timestamptz not null default now()
);

/** Correções propostas: trocar um trecho exato de um arquivo de conteúdo. Aprovada por OUTRA pessoa e aplicada por PR. */
create table if not exists interno.correcoes_conteudo (
  id uuid primary key default gen_random_uuid(),
  caminho text not null check (caminho ~ '^content/[a-z0-9/_.-]{3,200}[.]md$' and caminho !~ '[.][.]'),
  trecho text not null check (char_length(trecho) between 3 and 2000),
  troca text not null check (char_length(troca) <= 2000),
  motivo text not null default '' check (char_length(motivo) <= 500),
  erro_relatado uuid references interno.erros_relatados (id) on delete set null,
  status text not null default 'proposta' check (status in ('proposta', 'aprovada', 'aplicada', 'recusada')),
  proposta_por uuid references interno.perfis (id) on delete set null,
  proposta_em timestamptz not null default now(),
  decidida_por uuid references interno.perfis (id) on delete set null,
  decidida_em timestamptz,
  nota text not null default '' check (char_length(nota) <= 500),
  pr_url text not null default '' check (pr_url = '' or pr_url ~ '^https://github\.com/[A-Za-z0-9._-]+/[A-Za-z0-9._-]+/pull/[0-9]+$')
);
create index if not exists correcoes_conteudo_status on interno.correcoes_conteudo (status, proposta_em desc);

do $$
declare t text;
begin
  foreach t in array array['recursos_catalogo', 'recursos_vivos', 'confirmacoes', 'limites_config', 'site_constantes', 'destaques_home', 'aula_semana', 'trilhas_apresentacao', 'conteudo_prs', 'correcoes_conteudo'] loop
    execute format('alter table interno.%I enable row level security', t);
    execute format('revoke all on interno.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on interno.%I from anon, authenticated', t); end if;
  end loop;
end $$;

-- ───────────────────────── Funções internas ─────────────────────────

/** As constantes que o painel pode mudar, com o tipo de cada uma. O site continua com o valor de lib/site.ts enquanto não houver linha. */
create or replace function interno.site_constantes_modelo() returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'apoio_url', 'https',
    'instagram_usuario', 'usuario',
    'contato_email', 'email',
    'historico_desde', 'data')
$$;

/** Confere o valor de uma constante conforme o tipo dela no modelo. */
create or replace function interno.valida_constante(p_chave text, p_valor text) returns boolean language sql immutable as $$
  select case interno.site_constantes_modelo() ->> p_chave
    when 'https' then p_valor ~ '^https://[A-Za-z0-9.-]+\.[A-Za-z]{2,}(/[A-Za-z0-9._~:/?#@!$&''()*+,;=%-]*)?$'
    when 'usuario' then p_valor ~ '^[A-Za-z0-9._]{1,30}$'
    when 'email' then p_valor ~ '^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,120}\.[A-Za-z]{2,}$'
    when 'data' then p_valor ~ '^\d{4}-\d{2}-\d{2}$' and p_valor::date is not null
    else false end
$$;

/** Aplica o efeito de um pedido já confirmado. */
create or replace function interno.executar_confirmacao(c interno.confirmacoes) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_alvo uuid;
begin
  if c.tipo = 'recurso' then
    insert into recursos_vivos (nome, ligado, por) values (c.alvo, true, c.decidido_por)
    on conflict (nome) do update set ligado = true, por = excluded.por, em = now();
    perform interno.registrar('recurso_ligado', c.alvo, jsonb_build_object('confirmada_por_segunda_pessoa', true));
  elsif c.tipo = 'avaliacao_externa' then
    insert into configuracoes (chave, valor) values ('comunidade', jsonb_build_object('avaliacao_externa', true))
    on conflict (chave) do update set valor = configuracoes.valor || excluded.valor;
    perform interno.registrar('avaliacao_externa_ligada', '', jsonb_build_object('confirmada_por_segunda_pessoa', true));
  elsif c.tipo in ('zerar_2fa', 'zerar_aparelhos') then
    v_alvo := c.alvo::uuid;
    if c.tipo = 'zerar_2fa' then
      if to_regclass('auth.mfa_factors') is not null then execute 'delete from auth.mfa_factors where user_id = $1' using v_alvo; end if;
      -- Sessões abertas saem junto: quem tinha a senha roubada perde o acesso também.
      if to_regclass('auth.sessions') is not null then execute 'delete from auth.sessions where user_id = $1' using v_alvo; end if;
      perform interno.avisar(v_alvo, 'O segundo fator da sua conta foi zerado pela coordenação (duas pessoas confirmaram). Entre de novo e cadastre o aplicativo autenticador.');
      perform interno.registrar('segundo_fator_zerado', v_alvo::text, '{}'::jsonb);
    else
      delete from aparelhos where usuario = v_alvo;
      perform interno.avisar(v_alvo, 'A lista de aparelhos da sua conta foi zerada pela coordenação. O próximo acesso de cada aparelho será avisado como aparelho novo.');
      perform interno.registrar('aparelhos_zerados', v_alvo::text, '{}'::jsonb);
    end if;
  end if;
end $$;

/** Abre um pedido de segunda pessoa e avisa a liderança. Não deixa dois pedidos iguais abertos. */
create or replace function interno.pedir_confirmacao(p_tipo text, p_alvo text, p_motivo text) returns uuid language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_id uuid;
begin
  update confirmacoes set status = 'expirada' where status = 'aguardando' and expira_em < now();
  select id into v_id from confirmacoes where status = 'aguardando' and tipo = p_tipo and alvo = p_alvo;
  if v_id is not null then perform interno.erro('ja_pedido'); end if;
  insert into confirmacoes (tipo, alvo, motivo, pedido_por) values (p_tipo, p_alvo, p_motivo, v) returning id into v_id;
  perform interno.registrar('confirmacao_pedida', v_id::text, jsonb_build_object('tipo', p_tipo));
  perform interno.avisar_lideranca('Há um pedido esperando a confirmação de uma segunda pessoa (Segurança › Confirmações).', v);
  return v_id;
end $$;

/** Troca interno.limite por uma versão que respeita os limites ajustados. O resto é igual ao do install.sql. */
create or replace function interno.limite(p_acao text, p_maximo integer, p_minutos integer) returns void
language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_max integer := p_maximo;
  v_min integer := p_minutos;
  v_chave text;
  v_janela timestamptz;
  v_total integer;
begin
  select maximo, minutos into v_max, v_min from limites_config where acao = p_acao;
  if not found then v_max := p_maximo; v_min := p_minutos; end if;
  v_chave := p_acao || ':' || coalesce(auth.uid()::text, interno.origem());
  v_janela := to_timestamp(floor(extract(epoch from now()) / (v_min * 60)) * v_min * 60);
  insert into limites (chave, janela, total) values (v_chave, v_janela, 1)
  on conflict (chave, janela) do update set total = limites.total + 1
  returning total into v_total;
  if random() < 0.02 then delete from limites where janela < now() - interval '2 days'; end if;
  if v_total > v_max then perform interno.erro('muitos_pedidos'); end if;
end $$;

/** Quem edita conteúdo: coordenação, vice, curadoria e desenvolvimento. */
create or replace function interno.edita_conteudo() returns boolean language sql stable as $$
  select interno.curador() or interno.tem('desenvolvimento')
$$;

do $$
declare f text;
begin
  foreach f in array array['site_constantes_modelo()', 'valida_constante(text, text)', 'executar_confirmacao(interno.confirmacoes)', 'pedir_confirmacao(text, text, text)', 'edita_conteudo()'] loop
    execute format('revoke all on function interno.%s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function interno.%s from anon, authenticated', f); end if;
  end loop;
end $$;

-- ───────────────────────── 1. Recursos ligados sem publicar de novo ─────────────────────────

/** Público (o site lê com cache curto): só os nomes. Nunca quem decidiu nem quando. */
create or replace function public.recursos_lidos() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'ligados', coalesce((select jsonb_agg(nome order by nome) from recursos_vivos where ligado), '[]'::jsonb),
    'desligados', coalesce((select jsonb_agg(nome order by nome) from recursos_vivos where not ligado), '[]'::jsonb))
$$;

create or replace function public.recursos_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('recursos', coalesce((
    select jsonb_agg(jsonb_build_object(
      'nome', k.nome, 'so_pelo_nome', k.so_pelo_nome, 'decisao', v.ligado, 'em', v.em,
      'aguardando', exists (select 1 from confirmacoes c where c.tipo = 'recurso' and c.alvo = k.nome and c.status = 'aguardando' and c.expira_em > now()))
      order by k.nome)
    from recursos_catalogo k left join recursos_vivos v on v.nome = k.nome), '[]'::jsonb));
end $$;

/**
 * Liga ou desliga um recurso sem publicar de novo. Desligar é sempre imediato. Ligar um recurso comum também. Ligar um dos que só
 * ligam pelo nome (escola, vale-o-escrito, rede-v2) abre um pedido que OUTRA pessoa da coordenação precisa confirmar.
 * p_ligar null apaga a decisão (volta ao que a variável de montagem diz).
 */
create or replace function public.recurso_ajustar(p_nome text, p_ligar boolean, p_motivo text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); k recursos_catalogo; v_id uuid;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('recurso_ajustar', 60, 60);
  select * into k from recursos_catalogo where nome = p_nome;
  if not found then perform interno.erro('invalido:nome'); end if;
  if p_ligar is null then
    delete from recursos_vivos where nome = p_nome;
    perform interno.registrar('recurso_decisao_apagada', p_nome, '{}'::jsonb);
    return jsonb_build_object('ok', true);
  end if;
  if p_ligar and k.so_pelo_nome then
    v_id := interno.pedir_confirmacao('recurso', p_nome, interno.txt(p_motivo, 'motivo', 5, 500));
    return jsonb_build_object('aguardando', true, 'id', v_id);
  end if;
  insert into recursos_vivos (nome, ligado, por) values (p_nome, p_ligar, v)
  on conflict (nome) do update set ligado = excluded.ligado, por = excluded.por, em = now();
  perform interno.registrar(case when p_ligar then 'recurso_ligado' else 'recurso_desligado' end, p_nome, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 2. Confirmação de segunda pessoa ─────────────────────────

create or replace function public.confirmacoes_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  update confirmacoes set status = 'expirada' where status = 'aguardando' and expira_em < now();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id, 'tipo', c.tipo, 'alvo', c.alvo,
      'alvo_nome', case when c.tipo in ('zerar_2fa', 'zerar_aparelhos') then coalesce((select nome from perfis where id = c.alvo::uuid), '') else '' end,
      'motivo', c.motivo, 'pedido_por', coalesce((select nome from perfis where id = c.pedido_por), ''), 'meu', c.pedido_por = v,
      'pedido_em', c.pedido_em, 'expira_em', c.expira_em, 'status', c.status) order by c.pedido_em desc)
    from (select * from confirmacoes order by pedido_em desc limit 60) c), '[]'::jsonb);
end $$;

create or replace function public.confirmacao_decidir(p_id uuid, p_aceitar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c confirmacoes;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into c from confirmacoes where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'aguardando' then perform interno.erro('ja_decidida'); end if;
  if c.expira_em < now() then
    update confirmacoes set status = 'expirada' where id = p_id;
    perform interno.erro('expirada');
  end if;
  -- A regra inteira: quem pediu não confirma o próprio pedido.
  if c.pedido_por = v then perform interno.erro('segunda_pessoa'); end if;
  c.decidido_por := v;
  update confirmacoes set status = case when p_aceitar then 'confirmada' else 'recusada' end, decidido_por = v, decidido_em = now() where id = p_id;
  if p_aceitar then perform interno.executar_confirmacao(c); end if;
  perform interno.registrar('confirmacao_decidida', p_id::text, jsonb_build_object('tipo', c.tipo, 'aceita', coalesce(p_aceitar, false)));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.confirmacao_cancelar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c confirmacoes;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into c from confirmacoes where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'aguardando' then perform interno.erro('ja_decidida'); end if;
  if c.pedido_por is distinct from v then perform interno.erro('sem_permissao'); end if;
  update confirmacoes set status = 'cancelada', decidido_por = v, decidido_em = now() where id = p_id;
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 3. Zerar segundo fator e aparelhos ─────────────────────────

create or replace function interno.pedir_zerar(p_tipo text, p_usuario uuid, p_motivo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_id uuid;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('zerar_pedir', 10, 60);
  if p_usuario is null or not exists (select 1 from perfis where id = p_usuario) then perform interno.erro('nao_encontrado'); end if;
  -- Quem tem a coordenação ou a vice-coordenação só tem a conta mexida por quem lidera.
  if exists (select 1 from papeis where usuario = p_usuario and papel in ('coordenacao', 'vice')) and not interno.lider() then perform interno.erro('sem_permissao'); end if;
  v_id := interno.pedir_confirmacao(p_tipo, p_usuario::text, interno.txt(p_motivo, 'motivo', 10, 500));
  return jsonb_build_object('aguardando', true, 'id', v_id);
end $$;
revoke all on function interno.pedir_zerar(text, uuid, text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on function interno.pedir_zerar(text, uuid, text) from anon, authenticated; end if;
end $$;

create or replace function public.zerar_2fa_pedir(p_usuario uuid, p_motivo text) returns jsonb language sql security definer set search_path = interno, pg_temp as $$
  select interno.pedir_zerar('zerar_2fa', p_usuario, p_motivo)
$$;
create or replace function public.zerar_aparelhos_pedir(p_usuario uuid, p_motivo text) returns jsonb language sql security definer set search_path = interno, pg_temp as $$
  select interno.pedir_zerar('zerar_aparelhos', p_usuario, p_motivo)
$$;

/** Pessoas que a coordenação pode escolher para zerar (nome e id; sem e-mail). */
create or replace function public.zerar_pessoas() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'nome', f.nome) order by f.nome)
                   from (select id, nome from perfis where exists (select 1 from papeis where usuario = perfis.id) order by nome limit 300) f), '[]'::jsonb);
end $$;

-- ───────────────────────── 4. Segunda avaliação externa pelo painel ─────────────────────────

create or replace function public.avaliacao_externa_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'ligada', coalesce((select (valor ->> 'avaliacao_externa')::boolean from configuracoes where chave = 'comunidade'), false),
    'aguardando', exists (select 1 from confirmacoes where tipo = 'avaliacao_externa' and status = 'aguardando' and expira_em > now()));
end $$;

/**
 * Desligar é imediato. Ligar exige a caixa "a página de privacidade já foi atualizada" (o texto de cada mensagem passa a ir a uma
 * empresa de fora do país: LGPD, art. 33; docs/privacidade-avaliacao-automatica.md) e a confirmação de uma segunda pessoa.
 */
create or replace function public.avaliacao_externa_pedir(p_ligar boolean, p_privacidade_ok boolean default false) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_id uuid;
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if not coalesce(p_ligar, false) then
    insert into configuracoes (chave, valor) values ('comunidade', jsonb_build_object('avaliacao_externa', false))
    on conflict (chave) do update set valor = configuracoes.valor || excluded.valor;
    perform interno.registrar('avaliacao_externa_desligada', '', '{}'::jsonb);
    return jsonb_build_object('ok', true);
  end if;
  if p_privacidade_ok is distinct from true then perform interno.erro('invalido:privacidade'); end if;
  v_id := interno.pedir_confirmacao('avaliacao_externa', '', 'Ligar a segunda avaliação externa (privacidade já atualizada).');
  return jsonb_build_object('aguardando', true, 'id', v_id);
end $$;

-- ───────────────────────── 5. Limites ajustáveis ─────────────────────────

create or replace function public.limites_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'ajustados', coalesce((select jsonb_agg(jsonb_build_object('acao', acao, 'maximo', maximo, 'minutos', minutos, 'em', em) order by acao) from limites_config), '[]'::jsonb),
    -- Ações vistas nos últimos 2 dias, com o total de pessoas (agregado, sem identificar ninguém).
    'vistos', coalesce((select jsonb_agg(jsonb_build_object('acao', a.acao, 'pessoas', a.pessoas, 'maior', a.maior) order by a.acao)
                        from (select split_part(chave, ':', 1) acao, count(*) pessoas, max(total) maior from limites group by 1 order by 1 limit 200) a), '[]'::jsonb));
end $$;

create or replace function public.limite_ajustar(p_acao text, p_maximo integer, p_minutos integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_acao, '') !~ '^[a-z0-9_]{2,60}$' then perform interno.erro('invalido:acao'); end if;
  if p_maximo is null or p_maximo not between 1 and 5000 then perform interno.erro('invalido:maximo'); end if;
  if p_minutos is null or p_minutos not between 1 and 1440 then perform interno.erro('invalido:minutos'); end if;
  insert into limites_config (acao, maximo, minutos, por) values (p_acao, p_maximo, p_minutos, v)
  on conflict (acao) do update set maximo = excluded.maximo, minutos = excluded.minutos, por = excluded.por, em = now();
  perform interno.registrar('limite_ajustado', p_acao, jsonb_build_object('maximo', p_maximo, 'minutos', p_minutos));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.limite_restaurar(p_acao text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  delete from limites_config where acao = p_acao;
  perform interno.registrar('limite_restaurado', coalesce(p_acao, ''), '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 6. Constantes do site no banco ─────────────────────────

create or replace function public.site_constantes_ler() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_object_agg(chave, valor), '{}'::jsonb) from site_constantes
$$;

create or replace function public.site_constantes_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('modelo', interno.site_constantes_modelo(), 'valores', public.site_constantes_ler());
end $$;

/** p_valor vazio apaga a constante (o site volta ao valor do código). */
create or replace function public.site_constante_gravar(p_chave text, p_valor text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); t text := btrim(coalesce(p_valor, ''));
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('site_constante', 60, 60);
  if not (interno.site_constantes_modelo() ? coalesce(p_chave, '')) then perform interno.erro('invalido:chave'); end if;
  if t = '' then
    delete from site_constantes where chave = p_chave;
  else
    if not interno.valida_constante(p_chave, t) then perform interno.erro('invalido:valor'); end if;
    insert into site_constantes (chave, valor, por) values (p_chave, t, v)
    on conflict (chave) do update set valor = excluded.valor, por = excluded.por, em = now();
  end if;
  perform interno.registrar('site_constante', p_chave, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 7. Aula da semana e destaques da home ─────────────────────────

create or replace function public.destaques_ler() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'destaques', coalesce((select jsonb_agg(jsonb_build_object('posicao', posicao, 'caminho', caminho, 'titulo', titulo, 'resumo', resumo) order by posicao)
                           from destaques_home where ate is null or ate >= current_date), '[]'::jsonb),
    'aulas', coalesce((select jsonb_agg(jsonb_build_object('semana', semana, 'trilha', trilha, 'aula', aula) order by semana)
                       from aula_semana where semana >= ((((now() at time zone 'America/Sao_Paulo')::date - date '1970-01-01') + 3) / 7) - 1), '[]'::jsonb))
$$;

create or replace function public.destaques_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'destaques', coalesce((select jsonb_agg(jsonb_build_object('posicao', posicao, 'caminho', caminho, 'titulo', titulo, 'resumo', resumo, 'ate', ate) order by posicao) from destaques_home), '[]'::jsonb),
    'aulas', coalesce((select jsonb_agg(jsonb_build_object('semana', semana, 'trilha', trilha, 'aula', aula) order by semana desc) from (select * from aula_semana order by semana desc limit 30) x), '[]'::jsonb));
end $$;

create or replace function public.destaque_salvar(p_posicao integer, p_caminho text, p_titulo text, p_resumo text default '', p_ate date default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('destaque', 120, 60);
  if p_posicao is null or p_posicao not between 1 and 6 then perform interno.erro('invalido:posicao'); end if;
  if coalesce(p_caminho, '') !~ '^/[a-z0-9/_-]{1,160}$' then perform interno.erro('invalido:caminho'); end if;
  insert into destaques_home (posicao, caminho, titulo, resumo, ate, por)
  values (p_posicao, p_caminho, interno.txt(p_titulo, 'titulo', 3, 120), interno.txt(p_resumo, 'resumo', 0, 240), p_ate, v)
  on conflict (posicao) do update set caminho = excluded.caminho, titulo = excluded.titulo, resumo = excluded.resumo, ate = excluded.ate, por = excluded.por, em = now();
  perform interno.registrar('destaque_salvo', p_posicao::text, jsonb_build_object('caminho', p_caminho));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.destaque_remover(p_posicao integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  delete from destaques_home where posicao = p_posicao;
  perform interno.registrar('destaque_removido', coalesce(p_posicao, 0)::text, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.aula_semana_definir(p_semana integer, p_trilha text, p_aula text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('aula_semana', 60, 60);
  if p_semana is null or p_semana not between 1 and 100000 then perform interno.erro('invalido:semana'); end if;
  if coalesce(p_trilha, '') !~ '^[a-z0-9-]{2,80}$' or coalesce(p_aula, '') !~ '^[a-z0-9-]{1,100}$' then perform interno.erro('invalido:aula'); end if;
  insert into aula_semana (semana, trilha, aula, por) values (p_semana, p_trilha, p_aula, v)
  on conflict (semana) do update set trilha = excluded.trilha, aula = excluded.aula, por = excluded.por, em = now();
  perform interno.registrar('aula_semana_definida', p_semana::text, jsonb_build_object('trilha', p_trilha, 'aula', p_aula));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.aula_semana_limpar(p_semana integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  delete from aula_semana where semana = p_semana;
  perform interno.registrar('aula_semana_limpa', coalesce(p_semana, 0)::text, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 8. Texto de apresentação da trilha ─────────────────────────

create or replace function public.trilha_apresentacao_ler(p_slug text, p_idioma text default 'pt') returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce((select texto from trilhas_apresentacao where slug = p_slug and idioma = p_idioma), '')
$$;

create or replace function public.trilhas_apresentacao_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('slug', slug, 'idioma', idioma, 'texto', texto, 'em', em) order by slug, idioma) from trilhas_apresentacao), '[]'::jsonb);
end $$;

/** p_texto vazio apaga. */
create or replace function public.trilha_apresentacao_salvar(p_slug text, p_idioma text, p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); t text := btrim(coalesce(p_texto, ''));
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('trilha_apresentacao', 60, 60);
  if coalesce(p_slug, '') !~ '^[a-z0-9-]{2,80}$' then perform interno.erro('invalido:slug'); end if;
  if p_idioma not in ('pt', 'en', 'es', 'fr', 'ru', 'zh') then perform interno.erro('invalido:idioma'); end if;
  if t = '' then
    delete from trilhas_apresentacao where slug = p_slug and idioma = p_idioma;
  else
    insert into trilhas_apresentacao (slug, idioma, texto, por) values (p_slug, p_idioma, interno.txt(t, 'texto', 10, 1200), v)
    on conflict (slug, idioma) do update set texto = excluded.texto, por = excluded.por, em = now();
  end if;
  perform interno.registrar('trilha_apresentacao', p_slug || '/' || p_idioma, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── 9. Editar conteúdo em arquivo (PR) ─────────────────────────

/** A rota do servidor pergunta antes de abrir o PR: a pessoa pode editar conteúdo e ainda está dentro do ritmo (20 por hora)? */
create or replace function public.conteudo_pode_editar() returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('conteudo_pr', 20, 60);
  return true;
end $$;

create or replace function public.conteudo_pr_registrar(p_caminho text, p_numero integer, p_url text, p_tipo text default 'edicao') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  if p_tipo not in ('edicao', 'correcao') then perform interno.erro('invalido:tipo'); end if;
  insert into conteudo_prs (caminho, numero, url, tipo, por) values (p_caminho, p_numero, p_url, p_tipo, v);
  perform interno.registrar('conteudo_pr_aberto', p_caminho, jsonb_build_object('numero', p_numero, 'tipo', p_tipo));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.conteudo_prs_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'caminho', caminho, 'numero', numero, 'url', url, 'tipo', tipo, 'em', em) order by em desc)
                   from (select * from conteudo_prs order by em desc limit 40) x), '[]'::jsonb);
end $$;

-- ───────────────────────── 10. Correções aprovadas, aplicadas por PR ─────────────────────────

create or replace function public.correcao_propor(p_caminho text, p_trecho text, p_troca text, p_motivo text default '', p_erro uuid default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_id uuid;
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('correcao_propor', 60, 60);
  if coalesce(p_caminho, '') !~ '^content/[a-z0-9/_.-]{3,200}[.]md$' or p_caminho like '%//%' or p_caminho like '%..%' or p_caminho !~ '^content/(trilhas|paginas|glossario|professores|contribuir|falacias|debates|memorial)/' or p_caminho ~ '(^|/)[.]' then perform interno.erro('invalido:caminho'); end if;
  if char_length(coalesce(p_trecho, '')) not between 3 and 2000 then perform interno.erro('invalido:trecho'); end if;
  if char_length(coalesce(p_troca, '')) > 2000 or p_troca = p_trecho then perform interno.erro('invalido:troca'); end if;
  insert into correcoes_conteudo (caminho, trecho, troca, motivo, erro_relatado, proposta_por)
  values (p_caminho, p_trecho, p_troca, interno.txt(p_motivo, 'motivo', 0, 500), p_erro, v) returning id into v_id;
  perform interno.registrar('correcao_proposta', v_id::text, jsonb_build_object('caminho', p_caminho));
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.correcoes_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.edita_conteudo() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'caminho', c.caminho, 'trecho', c.trecho, 'troca', c.troca, 'motivo', c.motivo, 'status', c.status,
                                                       'minha', c.proposta_por = v, 'proposta_em', c.proposta_em, 'nota', c.nota, 'pr_url', c.pr_url) order by c.proposta_em desc)
                   from (select * from correcoes_conteudo order by proposta_em desc limit 60) c), '[]'::jsonb);
end $$;

/** Aprovar é com a curadoria (ou coordenação) e NUNCA de quem propôs: a segunda pessoa de sempre. */
create or replace function public.correcao_decidir(p_id uuid, p_aprovar boolean, p_nota text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c correcoes_conteudo;
begin
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  select * into c from correcoes_conteudo where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'proposta' then perform interno.erro('ja_decidida'); end if;
  if c.proposta_por = v then perform interno.erro('segunda_pessoa'); end if;
  update correcoes_conteudo set status = case when p_aprovar then 'aprovada' else 'recusada' end, decidida_por = v, decidida_em = now(), nota = interno.txt(p_nota, 'nota', 0, 500) where id = p_id;
  perform interno.registrar('correcao_decidida', p_id::text, jsonb_build_object('aprovada', coalesce(p_aprovar, false)));
  return jsonb_build_object('ok', true);
end $$;

/** Para a rota do servidor: devolve o que aplicar, só se estiver aprovada e a pessoa for da curadoria. */
create or replace function public.correcao_para_aplicar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare c correcoes_conteudo;
begin
  perform interno.eu();
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('correcao_aplicar', 30, 60);
  select * into c from correcoes_conteudo where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'aprovada' then perform interno.erro('nao_aprovada'); end if;
  return jsonb_build_object('id', c.id, 'caminho', c.caminho, 'trecho', c.trecho, 'troca', c.troca, 'motivo', c.motivo);
end $$;

create or replace function public.correcao_aplicada(p_id uuid, p_numero integer, p_url text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare c correcoes_conteudo;
begin
  perform interno.eu();
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  select * into c from correcoes_conteudo where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'aprovada' then perform interno.erro('nao_aprovada'); end if;
  update correcoes_conteudo set status = 'aplicada', pr_url = p_url where id = p_id;
  insert into conteudo_prs (caminho, numero, url, tipo, por) values (c.caminho, p_numero, p_url, 'correcao', auth.uid());
  perform interno.registrar('correcao_aplicada', p_id::text, jsonb_build_object('numero', p_numero));
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── Permissões das funções public.* ─────────────────────────

do $$
declare f text;
begin
  -- Quem lê sem conta (o site): só as de leitura pública.
  foreach f in array array['recursos_lidos()', 'site_constantes_ler()', 'destaques_ler()', 'trilha_apresentacao_ler(text, text)'] loop
    execute format('revoke all on function public.%s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('grant execute on function public.%s to anon, authenticated', f); end if;
  end loop;
  -- Quem entrou na conta: o próprio corpo da função confere o papel.
  foreach f in array array[
    'recursos_estado()', 'recurso_ajustar(text, boolean, text)',
    'confirmacoes_listar()', 'confirmacao_decidir(uuid, boolean)', 'confirmacao_cancelar(uuid)',
    'zerar_2fa_pedir(uuid, text)', 'zerar_aparelhos_pedir(uuid, text)', 'zerar_pessoas()',
    'avaliacao_externa_estado()', 'avaliacao_externa_pedir(boolean, boolean)',
    'limites_listar()', 'limite_ajustar(text, integer, integer)', 'limite_restaurar(text)',
    'site_constantes_listar()', 'site_constante_gravar(text, text)',
    'destaques_listar()', 'destaque_salvar(integer, text, text, text, date)', 'destaque_remover(integer)', 'aula_semana_definir(integer, text, text)', 'aula_semana_limpar(integer)',
    'trilhas_apresentacao_listar()', 'trilha_apresentacao_salvar(text, text, text)',
    'conteudo_pode_editar()', 'conteudo_pr_registrar(text, integer, text, text)', 'conteudo_prs_listar()',
    'correcao_propor(text, text, text, text, uuid)', 'correcoes_listar()', 'correcao_decidir(uuid, boolean, text)', 'correcao_para_aplicar(uuid)', 'correcao_aplicada(uuid, integer, text)'] loop
    execute format('revoke all on function public.%s from public', f);
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke all on function public.%s from anon', f);
      execute format('grant execute on function public.%s to authenticated', f);
    end if;
  end loop;
end $$;

-- ───────────────────────────── Back-end novo, parte 2 (Etapa 8, pacote backend-2) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Ainda NÃO está no install.sql (a integração junta).
-- Texto do pacote, base legal e como ligar cada item: docs/backend-2.md.
--
-- Oito itens, cada um com função SQL, tela e teste:
--   1. Operação do site: pedir limpeza do cache, ver publicação e ver backup (o banco confere quem pode e segura o ritmo;
--      quem fala com a Vercel, o GitHub e o Cloudflare é a rota app/api/painel/operacao, com os tokens só no servidor).
--   2. Regras do Mural de Saúde ajustáveis: a coordenação só ACRESCENTA termos ao filtro e PAUSA categorias; nunca afrouxa o
--      que está em content/saude/regras.json (a publicidade de profissional de saúde segue as regras dos conselhos).
--   3. Aviso de vencimento do token do Instagram: guarda SÓ a data de vencimento, nunca o token.
--   4. Lacunas da disciplina no banco: o que falta cobrir em cada disciplina, por quem ensina.
--   5. Resultado das aulas para quem ensina: somas anônimas por aula (já existentes em contagens), escondendo o que tem
--      menos de 5 testes e mostrando a tendência.
--   6. Caixa de imprensa para o porta-voz: pedidos de jornalistas, com consentimento e prazo de guarda.
--   7. Prévia com dados de exemplo: telas novas mostradas com dados inventados e marcados como exemplo.
--   8. Resumo diário opcional por e-mail: só contagens, só para quem ligou, pela fila de e-mails de sempre.
--
-- Base legal do item 6 (Lei 13.709/2018, conferida no planalto.gov.br): art. 6º, I e III (finalidade e necessidade: só nome,
-- veículo, e-mail e o pedido), art. 7º, I (consentimento marcado no formulário) e arts. 15, I, e 16 (acabado o atendimento,
-- o dado é eliminado: 180 dias depois de respondido ou arquivado). Nada de telefone, documento nem rede social.
--
-- Nenhuma tabela no esquema public; acesso só pelas funções public.* (security definer, search_path = interno, pg_temp).
-- Nenhuma função interna é executável por anon nem por authenticated.

-- ───────────────────────────── Tabelas (esquema interno) ─────────────────────────────

create table if not exists interno.operacao_registro (
  id bigint generated always as identity primary key,
  quando timestamptz not null default now(),
  quem uuid references interno.perfis (id) on delete set null,
  acao text not null check (acao in ('limpar_cache', 'ver_publicacao', 'ver_backup')),
  fase text not null check (fase in ('pedida', 'ok', 'falhou')),
  detalhe text not null default '' check (char_length(detalhe) <= 300)
);
create index if not exists operacao_registro_quando on interno.operacao_registro (acao, quando desc);

create table if not exists interno.saude_regras_extra (
  id boolean primary key default true check (id),
  grupos jsonb not null default '[]'::jsonb check (jsonb_typeof(grupos) = 'array'),
  categorias_pausadas text[] not null default '{}',
  por uuid references interno.perfis (id) on delete set null,
  atualizado_em timestamptz not null default now()
);
insert into interno.saude_regras_extra (id) values (true) on conflict do nothing;

create table if not exists interno.disciplina_lacunas (
  id uuid primary key default gen_random_uuid(),
  disciplina text not null check (disciplina ~ '^[a-z0-9-]{2,40}$'),
  titulo text not null check (char_length(titulo) between 3 and 160),
  descricao text not null default '' check (char_length(descricao) <= 1500),
  aula text not null default '' check (char_length(aula) <= 120),
  prioridade text not null default 'media' check (prioridade in ('baixa', 'media', 'alta')),
  status text not null default 'aberta' check (status in ('aberta', 'em_andamento', 'coberta', 'descartada')),
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists disciplina_lacunas_disc on interno.disciplina_lacunas (disciplina, status);

create table if not exists interno.imprensa_pedidos (
  id uuid primary key default gen_random_uuid(),
  nome text not null check (char_length(nome) between 2 and 100),
  veiculo text not null default '' check (char_length(veiculo) <= 100),
  email text not null check (email ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' and char_length(email) <= 200),
  assunto text not null check (char_length(assunto) between 3 and 150),
  mensagem text not null check (char_length(mensagem) between 10 and 3000),
  prazo date,
  status text not null default 'novo' check (status in ('novo', 'em_andamento', 'respondido', 'arquivado')),
  nota text not null default '' check (char_length(nota) <= 1000),
  responsavel uuid references interno.perfis (id) on delete set null,
  consentimento_em timestamptz not null default now(),
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  apagar_em timestamptz
);
create index if not exists imprensa_pedidos_status on interno.imprensa_pedidos (status, criado_em desc);

create table if not exists interno.resumo_diario (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  ativo boolean not null default true,
  ultimo date
);

do $$
declare t text;
begin
  foreach t in array array['operacao_registro', 'saude_regras_extra', 'disciplina_lacunas', 'imprensa_pedidos', 'resumo_diario'] loop
    execute format('alter table interno.%I enable row level security', t);
    execute format('revoke all on interno.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on interno.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- ───────────────────────────── Ajudas internas ─────────────────────────────

/** A pessoa (qualquer uma, não só quem chama) tem um destes papéis e não está suspensa? Para o resumo diário. */
create or replace function interno.backend2_papel_de(p_usuario uuid, p_papeis text[]) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from papeis p join perfis f on f.id = p.usuario where p.usuario = p_usuario and not f.suspenso and p.papel = any (p_papeis))
$$;
revoke all on function interno.backend2_papel_de(uuid, text[]) from public;

/** Quem lida com a imprensa: porta-voz, coordenação e vice-coordenação. */
create or replace function interno.imprensa_pode() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.coord() or interno.tem('porta_voz')
$$;
revoke all on function interno.imprensa_pode() from public;

/** Quem ensina esta disciplina: educação (e secundária) da disciplina, ou a curadoria e a coordenação. */
create or replace function interno.ensina(p_disciplina text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.curador() or interno.tem('educacao', p_disciplina)
$$;
revoke all on function interno.ensina(text) from public;

-- ───────────────────────────── 1. Operação do site ─────────────────────────────

/**
 * Antes de a rota falar com a Vercel, o GitHub ou o Cloudflare: só a coordenação, e a limpeza do cache no máximo 3 vezes por
 * hora (limpar tudo obriga a Vercel a refazer o site para os robôs). Anota o pedido.
 */
create or replace function public.operacao_pedir(p_acao text) returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if p_acao not in ('limpar_cache', 'ver_publicacao', 'ver_backup') then perform interno.erro('invalido:acao'); end if;
  perform interno.limite('operacao_' || p_acao, case p_acao when 'limpar_cache' then 3 else 30 end, 60);
  insert into operacao_registro (quem, acao, fase) values (auth.uid(), p_acao, 'pedida');
  if p_acao = 'limpar_cache' then perform interno.registrar('operacao_limpar_cache', '', '{}'::jsonb); end if;
  if random() < 0.02 then delete from operacao_registro where quando < now() - interval '180 days'; end if;
  return true;
end $$;

/** Depois da chamada: o que deu (só uma frase curta, nunca token nem corpo de resposta). */
create or replace function public.operacao_resultado(p_acao text, p_ok boolean, p_detalhe text default '') returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if p_acao not in ('limpar_cache', 'ver_publicacao', 'ver_backup') then perform interno.erro('invalido:acao'); end if;
  insert into operacao_registro (quem, acao, fase, detalhe) values (auth.uid(), p_acao, case when coalesce(p_ok, false) then 'ok' else 'falhou' end, left(coalesce(p_detalhe, ''), 300));
  return true;
end $$;

/** O que a tela de operação mostra do banco: os últimos 20 registros (sem nome de ninguém) e a situação do token do Instagram. */
create or replace function public.operacao_situacao() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'registros', (select coalesce(jsonb_agg(jsonb_build_object('quando', r.quando, 'acao', r.acao, 'fase', r.fase, 'detalhe', r.detalhe) order by r.id desc), '[]'::jsonb)
                  from (select * from operacao_registro order by id desc limit 20) r),
    'ultima_limpeza', (select max(quando) from operacao_registro where acao = 'limpar_cache' and fase = 'ok'),
    'instagram', interno.instagram_token_estado());
end $$;

-- ───────────────────────────── 3. Aviso de vencimento do token do Instagram ─────────────────────────────

/** {definido, expira, dias, nivel}: nivel é ok (mais de 14 dias), aviso (14 ou menos), urgente (3 ou menos) ou vencido. */
create or replace function interno.instagram_token_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_expira date; v_dias integer;
begin
  select (valor ->> 'expira')::date into v_expira from configuracoes where chave = 'instagram_token';
  if v_expira is null then return jsonb_build_object('definido', false, 'nivel', 'indefinido'); end if;
  v_dias := v_expira - (now() at time zone 'America/Sao_Paulo')::date;
  return jsonb_build_object('definido', true, 'expira', v_expira, 'dias', v_dias,
    'nivel', case when v_dias < 0 then 'vencido' when v_dias <= 3 then 'urgente' when v_dias <= 14 then 'aviso' else 'ok' end);
end $$;
revoke all on function interno.instagram_token_estado() from public;

/** A coordenação e quem divulga leem a situação (nunca o token: ele só existe na Vercel). */
create or replace function public.instagram_token_situacao() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.divulga() then perform interno.erro('sem_permissao'); end if;
  return interno.instagram_token_estado();
end $$;

/** A coordenação anota até quando o token vale (a data que a Meta mostra ao gerá-lo). Entre hoje e 400 dias. */
create or replace function public.instagram_token_validade_salvar(p_expira date) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if p_expira is null or p_expira < v_hoje or p_expira > v_hoje + 400 then perform interno.erro('invalido:expira'); end if;
  insert into configuracoes (chave, valor) values ('instagram_token', jsonb_build_object('expira', p_expira, 'avisado', 999))
  on conflict (chave) do update set valor = excluded.valor;
  perform interno.registrar('instagram_token_validade', '', jsonb_build_object('expira', p_expira));
  return interno.instagram_token_estado();
end $$;

/**
 * Diária: quando faltam 14, 7, 3 ou 1 dia (ou venceu), manda UM e-mail à coordenação por faixa. "avisado" guarda a menor faixa
 * já avisada; ao anotar uma data nova, volta a valer tudo.
 */
create or replace function interno.instagram_token_vigiar() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare e jsonb := interno.instagram_token_estado(); v_dias integer; v_faixa integer; v_ult integer;
begin
  if not coalesce((e ->> 'definido')::boolean, false) then return 0; end if;
  v_dias := (e ->> 'dias')::integer;
  v_faixa := case when v_dias < 0 then 0 when v_dias <= 1 then 1 when v_dias <= 3 then 3 when v_dias <= 7 then 7 when v_dias <= 14 then 14 else 999 end;
  if v_faixa = 999 then return 0; end if;
  select coalesce((valor ->> 'avisado')::integer, 999) into v_ult from configuracoes where chave = 'instagram_token';
  if v_faixa >= v_ult then return 0; end if;
  perform interno.email_lideranca('instagram_token', 'O token do Instagram ' || case when v_dias < 0 then 'venceu' else 'vence em ' || v_dias || ' dia(s)' end,
    'O token usado pelo estúdio de design para publicar no Instagram ' || case when v_dias < 0 then 'já venceu: as publicações agendadas vão falhar.' else 'vence em ' || v_dias || ' dia(s).' end ||
    E'\n\nGere um novo na Meta, troque INSTAGRAM_TOKEN na Vercel e anote a data nova em Painel, Operação do site. O passo a passo está em docs/ESTUDIO-INSTAGRAM.md.');
  update configuracoes set valor = valor || jsonb_build_object('avisado', v_faixa) where chave = 'instagram_token';
  return 1;
end $$;
revoke all on function interno.instagram_token_vigiar() from public;

-- ───────────────────────────── 2. Regras do Mural de Saúde ─────────────────────────────

/** O que a coordenação vê: as categorias do arquivo de regras (só nome, conselho e se está ligada) e os ajustes feitos no banco. */
create or replace function public.saude_regras_ajustes_ver() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare x saude_regras_extra%rowtype; r jsonb := interno.saude_regras();
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into x from saude_regras_extra where id;
  return jsonb_build_object(
    'termo_versao', r ->> 'termoVersao',
    'sobre_maximo', (r ->> 'sobreMaximo')::int,
    'grupos_do_arquivo', jsonb_array_length(coalesce(r -> 'bloqueio', '[]'::jsonb)),
    'categorias', (select coalesce(jsonb_agg(jsonb_build_object('id', c.key, 'conselho', c.value ->> 'conselho', 'ligada_no_arquivo', coalesce((c.value ->> 'ligada')::boolean, false),
                     'pausada', c.key = any (x.categorias_pausadas)) order by c.key), '[]'::jsonb) from jsonb_each(r -> 'categorias') c),
    'grupos', x.grupos, 'atualizado_em', x.atualizado_em);
end $$;

/**
 * Salva os ajustes: grupos de termos a mais no filtro ([{grupo, termos[], motivo, sugestao}]) e as categorias pausadas. Só aperta
 * a regra: não existe jeito de tirar um termo do arquivo nem de ligar uma categoria que o arquivo deixa desligada.
 */
create or replace function public.saude_regras_ajustes_salvar(p_grupos jsonb, p_pausadas text[]) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare g jsonb; t text; v_grupos jsonb := '[]'::jsonb; v_termos text[]; v_pausadas text[] := '{}'; k text; r jsonb := interno.saude_regras();
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if jsonb_typeof(coalesce(p_grupos, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_grupos, '[]'::jsonb)) > 30 then perform interno.erro('invalido:grupos'); end if;
  for g in select x from jsonb_array_elements(coalesce(p_grupos, '[]'::jsonb)) x loop
    if jsonb_typeof(g -> 'termos') <> 'array' or jsonb_array_length(g -> 'termos') not between 1 and 30 then perform interno.erro('invalido:termos'); end if;
    v_termos := '{}';
    for t in select jsonb_array_elements_text(g -> 'termos') loop
      t := btrim(t);
      if char_length(t) not between 2 and 60 then perform interno.erro('invalido:termos'); end if;
      v_termos := v_termos || t;
    end loop;
    v_grupos := v_grupos || jsonb_build_object('grupo', interno.txt(g ->> 'grupo', 'grupo', 2, 40), 'termos', to_jsonb(v_termos),
      'motivo', interno.txt(g ->> 'motivo', 'motivo', 5, 200), 'sugestao', interno.txt(coalesce(g ->> 'sugestao', ''), 'sugestao', 0, 200));
  end loop;
  foreach k in array coalesce(p_pausadas, '{}') loop
    if not (r -> 'categorias') ? k then perform interno.erro('invalido:categoria'); end if;
    v_pausadas := v_pausadas || k;
  end loop;
  update saude_regras_extra set grupos = v_grupos, categorias_pausadas = v_pausadas, por = auth.uid(), atualizado_em = now() where id;
  perform interno.registrar('saude_regras_ajustes', '', jsonb_build_object('grupos', jsonb_array_length(v_grupos), 'pausadas', to_jsonb(v_pausadas)));
  return public.saude_regras_ajustes_ver();
end $$;

-- O filtro e a chave de categoria passam a enxergar os ajustes. Só se o mural já existe neste banco; as duas funções ficam
-- "stable" (leem uma tabela). Ao juntar no install.sql, estas duas definições substituem as do bloco do Mural de Saúde.
do $$
begin
  if to_regprocedure('interno.saude_conferir(jsonb)') is not null and to_regprocedure('interno.saude_regras()') is not null then
    execute $f$
      create or replace function interno.saude_conferir(p_campos jsonb) returns jsonb language plpgsql stable set search_path = interno, pg_temp as $g$
      declare r jsonb := interno.saude_regras(); c record; e jsonb; g jsonb; t text; cru text; n1 text; n2 text; pad text; x jsonb;
      begin
        select coalesce(grupos, '[]'::jsonb) into x from saude_regras_extra where id;
        for c in select key, value from jsonb_each_text(coalesce(p_campos, '{}'::jsonb)) loop
          continue when coalesce(btrim(c.value), '') = '';
          cru := interno.saude_sem_acento(c.value);
          for e in select y from jsonb_array_elements(r -> 'padroesEspeciais') y loop
            if cru ~ (e ->> 'regex') then return jsonb_build_object('grupo', e ->> 'grupo', 'campo', c.key, 'motivo', e ->> 'motivo', 'sugestao', e ->> 'sugestao'); end if;
          end loop;
          n1 := interno.saude_normalizar(c.value, false);
          n2 := interno.saude_normalizar(c.value, true);
          for g in select y from jsonb_array_elements((r -> 'bloqueio') || coalesce(x, '[]'::jsonb)) y loop
            for t in select jsonb_array_elements_text(g -> 'termos') loop
              pad := interno.saude_padrao(t);
              if n1 ~ pad or n2 ~ pad then return jsonb_build_object('grupo', g ->> 'grupo', 'campo', c.key, 'motivo', g ->> 'motivo', 'sugestao', g ->> 'sugestao'); end if;
            end loop;
          end loop;
        end loop;
        return null;
      end $g$
    $f$;
    execute $f$
      create or replace function interno.saude_categoria_ligada(p_conselho text) returns boolean language sql stable set search_path = interno, pg_temp as $g$
        select coalesce((interno.saude_regras() -> 'categorias' -> interno.saude_categoria(p_conselho) ->> 'ligada')::boolean, false)
          and not coalesce(interno.saude_categoria(p_conselho) = any (select unnest(categorias_pausadas) from saude_regras_extra where id), false)
      $g$
    $f$;
  end if;
end $$;

-- ───────────────────────────── 4. Lacunas da disciplina ─────────────────────────────

create or replace function public.lacunas_listar(p_disciplina text default null) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_disc text := interno.disciplina_ok(nullif(btrim(coalesce(p_disciplina, '')), ''));
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if v_disc is not null and not interno.ensina(v_disc) then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'disciplina', l.disciplina, 'titulo', l.titulo, 'descricao', l.descricao, 'aula', l.aula,
            'prioridade', l.prioridade, 'status', l.status, 'atualizado_em', l.atualizado_em)
            order by (l.status in ('coberta', 'descartada')), case l.prioridade when 'alta' then 0 when 'media' then 1 else 2 end, l.atualizado_em desc), '[]'::jsonb)
          from (select * from disciplina_lacunas d
                where (v_disc is null or d.disciplina = v_disc)
                  and (interno.curador() or interno.tem('educacao', d.disciplina))
                order by d.atualizado_em desc limit 300) l);
end $$;

create or replace function public.lacunas_salvar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_disc text := interno.disciplina_ok(p ->> 'disciplina');
  v_prio text := coalesce(nullif(p ->> 'prioridade', ''), 'media');
  v_status text := coalesce(nullif(p ->> 'status', ''), 'aberta');
  v_antiga text;
begin
  if v_disc is null then perform interno.erro('invalido:disciplina'); end if;
  if not interno.ensina(v_disc) then perform interno.erro('sem_permissao'); end if;
  if v_prio not in ('baixa', 'media', 'alta') then perform interno.erro('invalido:prioridade'); end if;
  if v_status not in ('aberta', 'em_andamento', 'coberta', 'descartada') then perform interno.erro('invalido:status'); end if;
  if v_id is null then
    insert into disciplina_lacunas (disciplina, titulo, descricao, aula, prioridade, status, criado_por)
    values (v_disc, interno.txt(p ->> 'titulo', 'titulo', 3, 160), interno.txt(coalesce(p ->> 'descricao', ''), 'descricao', 0, 1500), interno.txt(coalesce(p ->> 'aula', ''), 'aula', 0, 120), v_prio, v_status, v)
    returning id into v_id;
  else
    select disciplina into v_antiga from disciplina_lacunas where id = v_id;
    if not found then perform interno.erro('nao_encontrado'); end if;
    -- Mudar de disciplina exige poder nas duas.
    if v_antiga <> v_disc and not interno.ensina(v_antiga) then perform interno.erro('sem_permissao'); end if;
    update disciplina_lacunas set disciplina = v_disc, titulo = interno.txt(p ->> 'titulo', 'titulo', 3, 160), descricao = interno.txt(coalesce(p ->> 'descricao', ''), 'descricao', 0, 1500),
      aula = interno.txt(coalesce(p ->> 'aula', ''), 'aula', 0, 120), prioridade = v_prio, status = v_status, atualizado_em = now() where id = v_id;
  end if;
  return jsonb_build_object('id', v_id);
end $$;

/** Só a coordenação apaga de vez; quem ensina marca como "descartada". */
create or replace function public.lacunas_apagar(p_id uuid) returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
declare n integer;
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  delete from disciplina_lacunas where id = p_id;
  get diagnostics n = row_count;
  perform interno.registrar('lacuna_apagada', p_id::text, '{}'::jsonb);
  return n > 0;
end $$;

/** A coordenação vê, por disciplina, quantas lacunas estão abertas, em andamento e cobertas. */
create or replace function public.lacunas_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.curador() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('disciplina', disciplina, 'abertas', abertas, 'em_andamento', andamento, 'cobertas', cobertas, 'altas', altas) order by abertas desc, disciplina), '[]'::jsonb)
          from (select disciplina, count(*) filter (where status = 'aberta') abertas, count(*) filter (where status = 'em_andamento') andamento,
                       count(*) filter (where status = 'coberta') cobertas, count(*) filter (where status in ('aberta', 'em_andamento') and prioridade = 'alta') altas
                from disciplina_lacunas group by disciplina) x);
end $$;

-- ───────────────────────────── 5. Resultado das aulas para quem ensina ─────────────────────────────

/** As disciplinas (trilhas) que esta pessoa pode ver: "todas" para curadoria, coordenação e quem tem a função sem disciplina. */
create or replace function public.aulas_resultado_minhas() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if interno.curador() or exists (select 1 from papeis p where p.usuario = auth.uid() and p.papel in ('educacao', 'educacao_secundaria') and p.disciplina is null) then
    return jsonb_build_object('todas', true, 'disciplinas', '[]'::jsonb);
  end if;
  return jsonb_build_object('todas', false, 'disciplinas',
    (select coalesce(jsonb_agg(distinct p.disciplina), '[]'::jsonb) from papeis p where p.usuario = auth.uid() and p.papel in ('educacao', 'educacao_secundaria') and p.disciplina is not null));
end $$;

/**
 * Por aula de UMA trilha: testes e acertos (70% ou mais) nos últimos p_dias, e a tendência dos últimos 30 dias contra os 30
 * anteriores. Soma de contagens anônimas (tabela contagens, sem conta nem aparelho). Aula com menos de 5 testes aparece sem os
 * números ("poucos testes"), para um número pequeno não apontar ninguém.
 */
create or replace function public.aulas_resultado_ensino(p_trilha text, p_dias integer default 90) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_hoje date := (now() at time zone 'America/Sao_Paulo')::date; v_dias integer := least(greatest(coalesce(p_dias, 90), 30), 400);
begin
  perform interno.eu();
  if coalesce(p_trilha, '') !~ '^[a-z0-9-]{1,80}$' then perform interno.erro('invalido:trilha'); end if;
  if not interno.ensina(p_trilha) then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('minimo', 5, 'dias', v_dias, 'aulas', (
    select coalesce(jsonb_agg(case when x.testes < 5
        then jsonb_build_object('alvo', x.alvo, 'poucos', true)
        else jsonb_build_object('alvo', x.alvo, 'poucos', false, 'testes', x.testes, 'acertos', x.acertos, 'pct', round(100.0 * x.acertos / x.testes),
          'dificil', x.testes >= 10 and 100.0 * x.acertos / x.testes < 40,
          'recente_testes', x.t_rec, 'recente_pct', case when x.t_rec >= 5 then round(100.0 * x.a_rec / x.t_rec) end,
          'anterior_testes', x.t_ant, 'anterior_pct', case when x.t_ant >= 5 then round(100.0 * x.a_ant / x.t_ant) end) end order by x.alvo), '[]'::jsonb)
    from (
      select alvo,
        coalesce(sum(total) filter (where tipo = 'aula_teste'), 0)::bigint testes,
        coalesce(sum(total) filter (where tipo = 'aula_acertou'), 0)::bigint acertos,
        coalesce(sum(total) filter (where tipo = 'aula_teste' and dia > v_hoje - 30), 0)::bigint t_rec,
        coalesce(sum(total) filter (where tipo = 'aula_acertou' and dia > v_hoje - 30), 0)::bigint a_rec,
        coalesce(sum(total) filter (where tipo = 'aula_teste' and dia <= v_hoje - 30 and dia > v_hoje - 60), 0)::bigint t_ant,
        coalesce(sum(total) filter (where tipo = 'aula_acertou' and dia <= v_hoje - 30 and dia > v_hoje - 60), 0)::bigint a_ant
      from contagens
      where tipo in ('aula_teste', 'aula_acertou') and left(alvo, length(p_trilha) + 1) = p_trilha || '/' and dia > v_hoje - v_dias
      group by alvo
    ) x));
end $$;

-- ───────────────────────────── 6. Caixa de imprensa ─────────────────────────────

/**
 * Qualquer pessoa (jornalista) pede uma resposta ou entrevista. Exige o consentimento marcado; segura spam (3 por hora por
 * origem, 3 por dia por e-mail, campo-isca "site" vazio). Avisa quem lida com a imprensa por e-mail, SEM dado do pedido.
 */
create or replace function public.imprensa_enviar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_prazo date := nullif(p ->> 'prazo', '')::date;
  v_id uuid; r record;
begin
  -- Campo-isca preenchido: finge que deu certo e não guarda nada.
  if coalesce(p ->> 'site', '') <> '' then return jsonb_build_object('ok', true); end if;
  perform interno.limite('imprensa_enviar', 3, 60);
  if coalesce((p ->> 'consentimento')::boolean, false) is not true then perform interno.erro('invalido:consentimento'); end if;
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or char_length(v_email) > 200 then perform interno.erro('invalido:email'); end if;
  if v_prazo is not null and (v_prazo < (now() at time zone 'America/Sao_Paulo')::date or v_prazo > (now() at time zone 'America/Sao_Paulo')::date + 365) then perform interno.erro('invalido:prazo'); end if;
  if (select count(*) from imprensa_pedidos where email = v_email and criado_em > now() - interval '1 day') >= 3 then perform interno.erro('muitos_pedidos'); end if;
  if (select count(*) from imprensa_pedidos where status = 'novo') >= 300 then perform interno.erro('caixa_cheia'); end if;
  insert into imprensa_pedidos (nome, veiculo, email, assunto, mensagem, prazo)
  values (interno.txt(p ->> 'nome', 'nome', 2, 100), interno.txt(coalesce(p ->> 'veiculo', ''), 'veiculo', 0, 100), v_email,
          interno.txt(p ->> 'assunto', 'assunto', 3, 150), interno.txt(p ->> 'mensagem', 'mensagem', 10, 3000), v_prazo)
  returning id into v_id;
  for r in select distinct u.email from papeis pp join auth.users u on u.id = pp.usuario join perfis f on f.id = pp.usuario
           where pp.papel in ('porta_voz', 'coordenacao', 'vice') and not f.suspenso and coalesce(u.email, '') <> '' loop
    perform interno.email(r.email, 'imprensa_nova', 'Novo pedido na caixa de imprensa', 'Chegou um pedido na caixa de imprensa. Abra o painel, em Caixa de imprensa, para ler e responder.' || case when v_prazo is not null then E'\nO pedido tem prazo.' else '' end, '', 10);
  end loop;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.imprensa_listar(p_status text default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.imprensa_pode() then perform interno.erro('sem_permissao'); end if;
  perform interno.registrar_acesso('imprensa', '');
  return (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'nome', i.nome, 'veiculo', i.veiculo, 'email', i.email, 'assunto', i.assunto, 'mensagem', i.mensagem,
            'prazo', i.prazo, 'status', i.status, 'nota', i.nota, 'criado_em', i.criado_em, 'apagar_em', i.apagar_em,
            'responsavel', coalesce((select f.nome from perfis f where f.id = i.responsavel), ''))
            order by (i.status in ('respondido', 'arquivado')), i.prazo nulls last, i.criado_em desc), '[]'::jsonb)
          from (select * from imprensa_pedidos where coalesce(p_status, '') = '' or status = p_status order by criado_em desc limit 200) i);
end $$;

/** Muda o andamento e anota (só para a equipe). Respondido ou arquivado: marca a eliminação para daqui a 180 dias (LGPD, arts. 15, I, e 16). */
create or replace function public.imprensa_atender(p_id uuid, p_status text, p_nota text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.imprensa_pode() then perform interno.erro('sem_permissao'); end if;
  if p_status not in ('novo', 'em_andamento', 'respondido', 'arquivado') then perform interno.erro('invalido:status'); end if;
  update imprensa_pedidos set status = p_status, nota = interno.txt(coalesce(p_nota, ''), 'nota', 0, 1000), responsavel = v, atualizado_em = now(),
    apagar_em = case when p_status in ('respondido', 'arquivado') then now() + interval '180 days' else null end
  where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  perform interno.registrar('imprensa_atendida', p_id::text, jsonb_build_object('status', p_status));
  return jsonb_build_object('ok', true);
end $$;

/** Quantos pedidos novos esperam (para o número no menu e no resumo). */
create or replace function public.imprensa_contar() returns integer language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.imprensa_pode() then return 0; end if;
  return (select count(*)::integer from imprensa_pedidos where status = 'novo');
end $$;

/** Faxina diária: elimina o que passou do prazo, e o que ficou 365 dias sem ninguém olhar. */
create or replace function interno.imprensa_limpeza() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare n integer;
begin
  delete from imprensa_pedidos where (apagar_em is not null and apagar_em < now()) or (status = 'novo' and criado_em < now() - interval '365 days');
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function interno.imprensa_limpeza() from public;

-- ───────────────────────────── 7. Prévia com dados de exemplo ─────────────────────────────

/**
 * Dados inventados e marcados como exemplo, para a pessoa ver como a tela fica (e a coordenação testar o texto) sem tocar em dado
 * real. Telas: imprensa, lacunas, resultado_aulas, resumo_diario, operacao. Nenhum nome, e-mail ou número aqui existe de verdade.
 */
create or replace function public.previa_exemplo(p_tela text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if auth.uid() is null then perform interno.erro('entre_primeiro'); end if;
  return jsonb_build_object('exemplo', true, 'tela', p_tela, 'dados', case p_tela
    when 'imprensa' then jsonb_build_array(
      jsonb_build_object('nome', 'Pessoa de Exemplo', 'veiculo', 'Jornal de Exemplo', 'assunto', 'Pedido de entrevista (exemplo)', 'mensagem', 'Texto inventado para mostrar a tela.', 'status', 'novo', 'prazo', '2099-01-10'),
      jsonb_build_object('nome', 'Outra Pessoa de Exemplo', 'veiculo', 'Rádio de Exemplo', 'assunto', 'Nota sobre um projeto (exemplo)', 'mensagem', 'Outro texto inventado.', 'status', 'respondido', 'prazo', null))
    when 'lacunas' then jsonb_build_array(
      jsonb_build_object('disciplina', 'disciplina-exemplo', 'titulo', 'Falta uma aula sobre um tema de exemplo', 'prioridade', 'alta', 'status', 'aberta'),
      jsonb_build_object('disciplina', 'disciplina-exemplo', 'titulo', 'Exercícios de revisão de exemplo', 'prioridade', 'media', 'status', 'em_andamento'))
    when 'resultado_aulas' then jsonb_build_array(
      jsonb_build_object('alvo', 'trilha-exemplo/aula-1', 'poucos', false, 'testes', 42, 'acertos', 31, 'pct', 74, 'dificil', false, 'recente_pct', 78, 'anterior_pct', 70),
      jsonb_build_object('alvo', 'trilha-exemplo/aula-2', 'poucos', false, 'testes', 18, 'acertos', 5, 'pct', 28, 'dificil', true, 'recente_pct', 25, 'anterior_pct', 33),
      jsonb_build_object('alvo', 'trilha-exemplo/aula-3', 'poucos', true))
    when 'resumo_diario' then jsonb_build_object('assunto', 'Seu resumo de hoje (exemplo)', 'texto', E'Bom dia.\n\n- 3 contribuições esperam revisão\n- 1 pedido novo na caixa de imprensa\n- O token do Instagram vence em 12 dia(s)\n\nAbra o painel para ver tudo.')
    when 'operacao' then jsonb_build_object('publicacao', jsonb_build_object('estado', 'pronta', 'ha_minutos', 25), 'backup', jsonb_build_object('conclusao', 'success', 'ha_dias', 3), 'instagram', jsonb_build_object('dias', 12, 'nivel', 'aviso'))
    else null end);
end $$;

-- ───────────────────────────── 8. Resumo diário opcional por e-mail ─────────────────────────────

create or replace function public.resumo_diario_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('ativo', coalesce((select ativo from resumo_diario where usuario = v), false), 'ultimo', (select ultimo from resumo_diario where usuario = v));
end $$;

/** Opcional: começa desligado. Ligar e desligar é com cada pessoa. */
create or replace function public.resumo_diario_definir(p_ativo boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  insert into resumo_diario (usuario, ativo) values (v, coalesce(p_ativo, false)) on conflict (usuario) do update set ativo = excluded.ativo;
  return jsonb_build_object('ativo', coalesce(p_ativo, false));
end $$;

/**
 * O texto do resumo de uma pessoa: SÓ contagens do que as funções dela enxergam, nunca nome, e-mail nem conteúdo. Devolve null
 * quando não há nada a dizer (dia sem aviso, dia sem e-mail).
 */
create or replace function interno.resumo_diario_montar(p_usuario uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_linhas text[] := '{}'; n integer; e jsonb;
begin
  if interno.backend2_papel_de(p_usuario, array['coordenacao', 'vice', 'curadoria']) then
    select count(*) into n from contribuicoes where status = 'pendente';
    if n > 0 then v_linhas := v_linhas || (n || case when n = 1 then ' contribuição espera revisão' else ' contribuições esperam revisão' end); end if;
  end if;
  if interno.backend2_papel_de(p_usuario, array['coordenacao', 'vice', 'porta_voz']) then
    select count(*) into n from imprensa_pedidos where status = 'novo';
    if n > 0 then v_linhas := v_linhas || (n || case when n = 1 then ' pedido novo na caixa de imprensa' else ' pedidos novos na caixa de imprensa' end); end if;
  end if;
  if interno.backend2_papel_de(p_usuario, array['coordenacao', 'vice', 'curadoria', 'educacao', 'educacao_secundaria']) then
    select count(*) into n from disciplina_lacunas d where d.status = 'aberta' and d.prioridade = 'alta'
      and (interno.backend2_papel_de(p_usuario, array['coordenacao', 'vice', 'curadoria'])
           or exists (select 1 from papeis p where p.usuario = p_usuario and p.papel in ('educacao', 'educacao_secundaria') and (p.disciplina is null or p.disciplina = d.disciplina)));
    if n > 0 then v_linhas := v_linhas || (n || case when n = 1 then ' lacuna de prioridade alta aberta' else ' lacunas de prioridade alta abertas' end); end if;
  end if;
  if interno.backend2_papel_de(p_usuario, array['coordenacao', 'vice']) then
    e := interno.instagram_token_estado();
    if e ->> 'nivel' in ('aviso', 'urgente') then v_linhas := v_linhas || ('O token do Instagram vence em ' || (e ->> 'dias') || ' dia(s)'); end if;
    if e ->> 'nivel' = 'vencido' then v_linhas := v_linhas || 'O token do Instagram venceu'; end if;
  end if;
  if coalesce(array_length(v_linhas, 1), 0) = 0 then return null; end if;
  return jsonb_build_object('assunto', 'Seu resumo de hoje no painel', 'texto',
    E'Bom dia.\n\n- ' || array_to_string(v_linhas, E'\n- ') || E'\n\nAbra o painel para ver tudo: ' || interno.endereco() || E'/pt/painel\n\nVocê recebe este resumo porque ligou a opção em Painel, Resumo diário. Desligue lá quando quiser.');
end $$;
revoke all on function interno.resumo_diario_montar(uuid) from public;

/** Diária: um e-mail por pessoa que ligou, no máximo um por dia, pela fila de sempre (a rotina de envio é a mesma). Devolve quantos entraram na fila. */
create or replace function interno.resumo_diario_enviar() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare r record; v jsonb; v_email text; v_hoje date := (now() at time zone 'America/Sao_Paulo')::date; v_n integer := 0;
begin
  for r in select d.usuario from resumo_diario d join perfis f on f.id = d.usuario
           where d.ativo and not f.suspenso and d.ultimo is distinct from v_hoje order by d.usuario limit 500 loop
    if not interno.voluntario_e(r.usuario) then continue; end if;
    v_email := lower(coalesce(interno.email_da_conta(r.usuario), ''));
    if v_email = '' then continue; end if;
    v := interno.resumo_diario_montar(r.usuario);
    if v is null then continue; end if;
    if interno.email(v_email, 'resumo_diario', v ->> 'assunto', v ->> 'texto', '', 1) then
      v_n := v_n + 1;
      update resumo_diario set ultimo = v_hoje where usuario = r.usuario;
    end if;
  end loop;
  perform interno.instagram_token_vigiar();
  perform interno.imprensa_limpeza();
  return v_n;
end $$;
revoke all on function interno.resumo_diario_enviar() from public;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    -- 10h UTC = 7h em Brasília.
    perform cron.schedule('lucia-resumo-diario', '0 10 * * *', 'select interno.resumo_diario_enviar()');
  end if;
exception when others then null;
end $$;

-- ───────────────────────────── Acesso ─────────────────────────────

-- Só quem entrou (authenticated) chama; a caixa de imprensa também aceita visitante (anon), com a proteção acima.
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('operacao_pedir', 'operacao_resultado', 'operacao_situacao', 'instagram_token_situacao', 'instagram_token_validade_salvar',
             'saude_regras_ajustes_ver', 'saude_regras_ajustes_salvar', 'lacunas_listar', 'lacunas_salvar', 'lacunas_apagar', 'lacunas_resumo',
             'aulas_resultado_minhas', 'aulas_resultado_ensino', 'imprensa_enviar', 'imprensa_listar', 'imprensa_atender', 'imprensa_contar',
             'previa_exemplo', 'resumo_diario_estado', 'resumo_diario_definir') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon', f.assinatura);
      execute format('grant execute on function %s to authenticated', f.assinatura);
      if f.proname = 'imprensa_enviar' then execute format('grant execute on function %s to anon', f.assinatura); end if;
    end if;
  end loop;
end $$;

-- ───────────────────────────── Progresso por QR (Etapa 3, pacote progresso-qr) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. O mesmo bloco está no fim do install.sql.
-- Texto e regras: docs/PROGRESSO-QR.md e a página de privacidade (parágrafo "Levar o progresso para outro aparelho (por QR)").
--
-- Para levar o progresso e as anotações de um aparelho a outro SEM conta, o aparelho de origem monta o pacote, cifra com uma
-- chave aleatória (AES-GCM, no próprio aparelho) e, quando o pacote cabe no QR, o QR leva o pacote e a chave e o servidor não
-- participa. Quando não cabe, o pacote JÁ CIFRADO vem para cá, e o QR leva só o código do pacote e a chave. A chave nunca
-- chega ao servidor: aqui só existe um texto cifrado que ninguém daqui consegue abrir.
--
-- Regras do banco:
--   * só guarda o texto cifrado, até 400 mil caracteres (uns 300 KB), e no máximo 100 pacotes guardados ao mesmo tempo;
--   * quem guarda: no máximo 6 pedidos por hora por origem; quem lê: no máximo 30 por 10 minutos por origem (interno.limite);
--   * o pacote some assim que é lido (a leitura já o apaga) ou em até 1 dia, o que vier primeiro; a limpeza roda a cada
--     chamada e, quando existe pg_cron, também de hora em hora;
--   * a tabela do pacote não guarda quem enviou, nem endereço, nem data de leitura: só o código, o texto cifrado e o prazo. O limite de
--     pedidos usa o contador comum do projeto (interno.limite), que guarda só um hash da origem e some em até 2 dias.
--
-- Nenhuma tabela no esquema public (trava do projeto: npm run testar:banco); a tabela fica em interno e só as duas funções
-- public.* (security definer, search_path = interno, pg_temp) abrem. Teste: npm run testar:progresso-qr.

create table if not exists interno.progresso_qr (
  id text primary key check (id ~ '^[A-HJ-NP-Z2-9]{10}$'),
  blob text not null check (char_length(blob) between 40 and 400000 and blob ~ '^[A-Za-z0-9_-]+$'),
  criado_em timestamptz not null default now(),
  expira_em timestamptz not null default now() + interval '1 day'
);
create index if not exists progresso_qr_expira_idx on interno.progresso_qr (expira_em);
alter table interno.progresso_qr enable row level security;
revoke all on interno.progresso_qr from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on interno.progresso_qr from anon, authenticated; end if;
end $$;

/** Apaga os pacotes vencidos. Só o banco chama (função interna, sem permissão para anon nem authenticated). */
create or replace function interno.progresso_qr_limpar() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare n integer;
begin
  delete from interno.progresso_qr where expira_em <= now();
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function interno.progresso_qr_limpar() from public;

/**
 * Guarda um pacote JÁ CIFRADO no aparelho de origem. O código (p_id) é sorteado pelo aparelho: 10 letras e números sem 0, 1, I e O.
 * Devolve {ok, expira_em}. Erros: invalido:id, invalido:pacote, pacote_grande, servico_cheio, id_em_uso, muitos_pedidos.
 */
create or replace function public.progresso_qr_guardar(p_id text, p_blob text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_expira timestamptz;
begin
  perform interno.limite('progresso_qr_guardar', 6, 60);
  if p_id is null or p_id !~ '^[A-HJ-NP-Z2-9]{10}$' then perform interno.erro('invalido:id'); end if;
  if p_blob is null or char_length(p_blob) < 40 then perform interno.erro('invalido:pacote'); end if;
  if char_length(p_blob) > 400000 then perform interno.erro('pacote_grande'); end if;
  if p_blob !~ '^[A-Za-z0-9_-]+$' then perform interno.erro('invalido:pacote'); end if;
  perform interno.progresso_qr_limpar();
  if (select count(*) from interno.progresso_qr) >= 100 then perform interno.erro('servico_cheio'); end if;
  insert into interno.progresso_qr (id, blob) values (p_id, p_blob) on conflict (id) do nothing returning expira_em into v_expira;
  if v_expira is null then perform interno.erro('id_em_uso'); end if;
  return jsonb_build_object('ok', true, 'expira_em', v_expira);
end $$;

/**
 * Entrega o pacote cifrado e o apaga NA MESMA HORA: quem lê primeiro leva, ninguém lê duas vezes. Devolve {achou: false}
 * para código errado, já lido ou vencido (sem distinguir, para não dar pista). Erro: muitos_pedidos.
 */
create or replace function public.progresso_qr_buscar(p_id text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_blob text;
begin
  perform interno.limite('progresso_qr_buscar', 30, 10);
  if p_id is null or p_id !~ '^[A-HJ-NP-Z2-9]{10}$' then return jsonb_build_object('achou', false); end if;
  perform interno.progresso_qr_limpar();
  delete from interno.progresso_qr where id = p_id returning blob into v_blob;
  if v_blob is null then return jsonb_build_object('achou', false); end if;
  return jsonb_build_object('achou', true, 'blob', v_blob);
end $$;

revoke all on function public.progresso_qr_guardar(text, text) from public;
revoke all on function public.progresso_qr_buscar(text) from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.progresso_qr_guardar(text, text) from anon, authenticated;
    revoke all on function public.progresso_qr_buscar(text) from anon, authenticated;
    revoke all on function interno.progresso_qr_limpar() from anon, authenticated;
    grant execute on function public.progresso_qr_guardar(text, text) to anon, authenticated, service_role;
    grant execute on function public.progresso_qr_buscar(text) to anon, authenticated, service_role;
  end if;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-progresso-qr-limpar', '17 * * * *', 'select interno.progresso_qr_limpar()');
  end if;
exception when others then null;
end $$;

-- ───────────────────────────── Alumia: nome, Salvos e federação (Fediverso / ActivityPub) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. O mesmo bloco está no fim do install.sql. Roda
-- DEPOIS das migrações da Rede v2 (2026-11-rede-*.sql). Documentos: docs/rede/FEDIVERSO.md, docs/rede/ALUMIA-DOMINIO.md, docs/rede/V2.md.
--
-- 1. Nome: a rede passa a se chamar Alumia nos textos que o banco escreve (avisos, e-mails do resumo semanal). As funções que
--    escreviam "Rede Lúcia" são recriadas com "Alumia" no lugar; os padrões que reconhecem avisos antigos aceitam os dois nomes.
-- 2. Salvos: public.rede_alumia_salvos lista o que a pessoa guardou (só o que ela ainda pode ver, pela mesma matriz de sempre).
-- 3. Fediverso: federação opcional e desligada por padrão. Só sai o que qualquer pessoa já lê sem conta (interno.rede_ve(p, null)),
--    de quem ligou a federação no próprio perfil (consentimento específico e destacado, com versão e data: LGPD art. 7º, I, e
--    art. 8º; revogável a qualquer momento, art. 8º, § 5º), e só posts escritos depois de ligar. Núcleo, comunidade fechada ou
--    restrita, alcance "membros", "seguidores", "comunidade", "equipe" e aviso do instituto nunca saem. As chaves privadas ficam
--    em interno.rede_fed_atores, cifradas pelo servidor do site (o banco nunca vê a chave aberta). As funções do servidor só
--    respondem a quem traz o segredo da federação (o hash fica em interno.configuracoes, chave 'fediverso').
--
-- Para ligar (passo a passo em docs/rede/FEDIVERSO.md):
--   insert into interno.configuracoes (chave, valor) values ('fediverso', jsonb_build_object(
--     'segredo_hash', encode(sha256(convert_to('<o mesmo valor de ALUMIA_FEDIVERSO_SEGREDO>', 'UTF8')), 'hex'),
--     'url_entrega', 'https://alumia.institutolucia.org/api/fediverso/entregar'))
--   on conflict (chave) do update set valor = excluded.valor;

-- ── 1. O nome: Alumia ───────────────────────────────────────────────────────────────────────────────────────────────────
-- Recria, com o nome novo, toda função dos esquemas interno e public que escrevia "Rede Lúcia" num texto (avisos e e-mails).
-- Primeiro os dois padrões que reconhecem avisos já gravados passam a aceitar os dois nomes (sem isso, um aviso antigo deixaria
-- de ser reconhecido e mostraria o trecho do post); depois o resto do texto troca de nome. Roda de novo sem efeito: o padrão
-- novo é escrito "Rede L[úu]cia", que não contém mais o nome antigo.
do $$
declare
  f record;
  v_def text;
begin
  for f in
    select p.oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('interno', 'public') and p.prokind = 'f' and p.prosrc like '%Rede Lúcia%'
  loop
    v_def := pg_get_functiondef(f.oid);
    v_def := replace(v_def, 'respondeu ao seu post na Rede Lúcia: “(.*)”$', 'respondeu ao seu post na (?:Rede L[úu]cia|Alumia): “(.*)”$');
    v_def := replace(v_def, ' respondeu ao seu post na Rede Lúcia: “''', ' respondeu ao seu post na (?:Rede L[úu]cia|Alumia): “''');
    v_def := replace(v_def, 'Rede Lúcia', 'Alumia');
    execute v_def;
  end loop;
end $$;

-- ── 2. Salvos ───────────────────────────────────────────────────────────────────────────────────────────────────────────

/** O que a pessoa guardou para ler depois, do mais novo para o mais antigo. Cursor = "<quando salvou>|<post>". Só o que ela ainda vê. */
create or replace function public.rede_alumia_salvos(p_cursor text default null, p_limite integer default 20) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_limite integer := least(greatest(coalesce(p_limite, 20), 1), 50);
  v_t timestamptz; v_id uuid;
  v_itens jsonb := '[]'::jsonb; v_proximo text; v_n integer := 0;
  r record;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  if nullif(p_cursor, '') is not null then
    begin
      v_t := split_part(p_cursor, '|', 1)::timestamptz;
      v_id := split_part(p_cursor, '|', 2)::uuid;
    exception when others then
      perform interno.erro('invalido:cursor');
    end;
  end if;
  for r in
    select s.criado_em as salvo_em, p.* from rede_salvos s join rede_posts p on p.id = s.post
    where s.usuario = v and (v_t is null or (s.criado_em, s.post) < (v_t, v_id)) and interno.rede_ve(p, v)
    order by s.criado_em desc, s.post desc
    limit v_limite + 1
  loop
    v_n := v_n + 1;
    if v_n > v_limite then exit; end if;
    v_itens := v_itens || jsonb_build_array(interno.rede_post_v2((select x from rede_posts x where x.id = r.id), v));
    v_proximo := r.salvo_em::text || '|' || r.id::text;
  end loop;
  return jsonb_build_object('itens', v_itens, 'proximo', case when v_n > v_limite then v_proximo end);
end $$;

-- ── 3. Fediverso: tabelas ───────────────────────────────────────────────────────────────────────────────────────────────

-- Quem ligou a federação. A chave privada vem CIFRADA pelo servidor do site (AES-256-GCM, chave derivada de ALUMIA_FEDIVERSO_SEGREDO).
-- Sem chave estrangeira para interno.perfis DE PROPÓSITO (como a fila, abaixo): quem apaga a conta com a federação ligada precisa
-- que os pedidos de apagar (Delete, Reject, Undo) ainda saiam assinados depois que o perfil sumiu (interno.rede_fed_conta_apagada);
-- a faxina (interno.rede_fed_limpar) apaga a linha e as chaves assim que a fila dessa pessoa esvazia (LGPD art. 18, VI).
create table if not exists interno.rede_fed_atores (
  perfil uuid primary key,
  handle text not null check (handle ~ '^[a-z0-9_]{3,20}$'),
  ligado boolean not null default false,
  consentimento_versao integer,
  ligado_em timestamptz,
  desligado_em timestamptz,
  chave_publica text check (chave_publica is null or char_length(chave_publica) <= 2000),
  chave_privada text check (chave_privada is null or char_length(chave_privada) <= 6000),
  criado_em timestamptz not null default now()
);
create unique index if not exists rede_fed_atores_handle on interno.rede_fed_atores (handle) where ligado;

-- Quem segue, de outra instância, uma pessoa daqui (só o endereço público do ator remoto e da caixa de entrada dele).
create table if not exists interno.rede_fed_seguidores (
  perfil uuid not null references interno.perfis (id) on delete cascade,
  ator text not null check (ator ~ '^https://' and char_length(ator) <= 500),
  inbox text not null check (inbox ~ '^https://' and char_length(inbox) <= 500),
  inbox_compartilhada text check (inbox_compartilhada is null or (inbox_compartilhada ~ '^https://' and char_length(inbox_compartilhada) <= 500)),
  pedido text not null default '' check (char_length(pedido) <= 500),
  criado_em timestamptz not null default now(),
  primary key (perfil, ator)
);

-- Quem uma pessoa daqui segue em outra instância (pedido = id da atividade Follow; aceito quando chega o Accept).
create table if not exists interno.rede_fed_seguindo (
  perfil uuid not null references interno.perfis (id) on delete cascade,
  ator text not null check (ator ~ '^https://' and char_length(ator) <= 500),
  pedido text not null check (char_length(pedido) <= 500),
  aceito boolean not null default false,
  criado_em timestamptz not null default now(),
  primary key (perfil, ator)
);

-- O que já se sabe de um ator remoto (público: chave, caixas, @nome). Serve para conferir assinaturas sem buscar toda vez.
create table if not exists interno.rede_fed_remotos (
  ator text primary key check (ator ~ '^https://' and char_length(ator) <= 500),
  chave_id text check (chave_id is null or char_length(chave_id) <= 600),
  chave_publica text check (chave_publica is null or char_length(chave_publica) <= 4000),
  inbox text check (inbox is null or char_length(inbox) <= 500),
  inbox_compartilhada text check (inbox_compartilhada is null or char_length(inbox_compartilhada) <= 500),
  handle text check (handle is null or char_length(handle) <= 200),
  nome text check (nome is null or char_length(nome) <= 200),
  resumo text check (resumo is null or char_length(resumo) <= 1000),
  url text check (url is null or char_length(url) <= 500),
  buscado_em timestamptz not null default now()
);

-- A fila de entrega (uma linha por atividade e caixa de destino). O servidor do site monta e assina na hora de entregar,
-- conferindo de novo se o post ainda pode sair.
create table if not exists interno.rede_fed_fila (
  id bigserial primary key,
  perfil uuid not null,
  tipo text not null check (tipo in ('create', 'update', 'delete', 'accept', 'reject', 'follow', 'undo-follow')),
  objeto text not null check (char_length(objeto) <= 500),
  destino text not null check (destino ~ '^https://' and char_length(destino) <= 500),
  extra jsonb not null default '{}'::jsonb,
  tentativas smallint not null default 0,
  proxima timestamptz not null default now(),
  criado_em timestamptz not null default now(),
  feito_em timestamptz,
  erro text not null default '' check (char_length(erro) <= 300)
);
create index if not exists rede_fed_fila_pendentes on interno.rede_fed_fila (proxima) where feito_em is null;

-- Os posts que já saíram (para mandar "Update" quando editados e "Delete" quando apagados, ocultados ou fechados).
create table if not exists interno.rede_fed_enviados (
  post uuid primary key,
  perfil uuid not null references interno.perfis (id) on delete cascade,
  enviado_em timestamptz not null default now(),
  apagado_em timestamptz
);

-- Posts públicos de quem alguém daqui segue em outra instância: só texto (sem HTML, sem imagem), guardados 30 dias.
create table if not exists interno.rede_fed_recebidos (
  id text primary key check (id ~ '^https://' and char_length(id) <= 500),
  ator text not null check (char_length(ator) <= 500),
  url text check (url is null or char_length(url) <= 500),
  texto text not null check (char_length(texto) <= 3000),
  aviso text not null default '' check (char_length(aviso) <= 200),
  publicado timestamptz,
  recebido_em timestamptz not null default now()
);
create index if not exists rede_fed_recebidos_ator on interno.rede_fed_recebidos (ator, publicado desc);

-- Instâncias que a mediação bloqueou (desfederação): nada entra delas e nada sai para elas.
create table if not exists interno.rede_fed_bloqueados (
  dominio text primary key check (dominio ~ '^[a-z0-9.-]{3,253}$'),
  motivo text not null default '' check (char_length(motivo) <= 300),
  por uuid,
  criado_em timestamptz not null default now()
);

-- Quem rodou uma versão anterior deste bloco tem a chave estrangeira com "on delete cascade" nas duas tabelas: sai aqui.
do $$
declare c record;
begin
  for c in select r.conname, r.conrelid::regclass::text as tabela from pg_constraint r
           where r.contype = 'f' and r.confrelid = 'interno.perfis'::regclass
             and r.conrelid in ('interno.rede_fed_atores'::regclass, 'interno.rede_fed_fila'::regclass) loop
    execute format('alter table %s drop constraint %I', c.tabela, c.conname);
  end loop;
end $$;

alter table interno.rede_fed_atores enable row level security;
alter table interno.rede_fed_seguidores enable row level security;
alter table interno.rede_fed_seguindo enable row level security;
alter table interno.rede_fed_remotos enable row level security;
alter table interno.rede_fed_fila enable row level security;
alter table interno.rede_fed_enviados enable row level security;
alter table interno.rede_fed_recebidos enable row level security;
alter table interno.rede_fed_bloqueados enable row level security;
revoke all on interno.rede_fed_atores, interno.rede_fed_seguidores, interno.rede_fed_seguindo, interno.rede_fed_remotos, interno.rede_fed_fila,
  interno.rede_fed_enviados, interno.rede_fed_recebidos, interno.rede_fed_bloqueados from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on interno.rede_fed_atores, interno.rede_fed_seguidores, interno.rede_fed_seguindo, interno.rede_fed_remotos, interno.rede_fed_fila,
      interno.rede_fed_enviados, interno.rede_fed_recebidos, interno.rede_fed_bloqueados from anon, authenticated;
    revoke all on sequence interno.rede_fed_fila_id_seq from anon, authenticated;
  end if;
end $$;

-- ── 4. Fediverso: regras ────────────────────────────────────────────────────────────────────────────────────────────────

/** Versão do texto do consentimento da federação (components/rede/alumia/Fediverso.tsx). Mudou o texto, sobe a versão. */
create or replace function interno.rede_fed_versao() returns integer language sql immutable as $$ select 1 $$;

/** O domínio (minúsculo) de um endereço https. */
create or replace function interno.rede_fed_dominio(p_url text) returns text language sql immutable as $$
  select lower(substring(coalesce(p_url, '') from '^https://([^/:?#]+)'))
$$;

/** A instância deste endereço foi bloqueada pela mediação (ela ou um subdomínio dela)? */
create or replace function interno.rede_fed_bloqueado(p_url text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_fed_bloqueados b, lateral (select interno.rede_fed_dominio(p_url) as d) x
                 where x.d = b.dominio or x.d like '%.' || b.dominio)
$$;

/** Confere o segredo da federação (o servidor do site o manda em toda chamada). Sem a configuração, nada responde. */
create or replace function interno.rede_fed_segredo(p_segredo text) returns void language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_hash text := (select valor ->> 'segredo_hash' from configuracoes where chave = 'fediverso');
begin
  if coalesce(v_hash, '') !~ '^[0-9a-f]{64}$' or char_length(coalesce(p_segredo, '')) < 32
     or encode(sha256(convert_to(p_segredo, 'UTF8')), 'hex') <> v_hash then
    perform interno.erro('sem_permissao');
  end if;
end $$;

/** A pessoa pode ligar a federação? Devolve o motivo do "não" ou nulo. */
create or replace function interno.rede_fed_impedimento(p_perfil uuid) returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select case
    when f.id is null then 'entre_primeiro'
    when f.suspenso then 'conta_suspensa'
    when not interno.rede2_membro(f.id) then 'consentimento'
    when f.rede_handle is null then 'sem_handle'
    when f.rede_modo <> 'aberto' or f.rede_invisivel then 'perfil_fechado'
    else null end
  from (select 1) um left join perfis f on f.id = p_perfil
$$;

/**
 * Este post pode sair para o Fediverso? Só o que qualquer pessoa lê sem conta (a mesma matriz de sempre, com visitante), de quem
 * ligou a federação e escrito depois de ligar; nunca núcleo, comunidade fechada ou restrita, equipe, aviso do instituto ou
 * compartilhamento. Resposta só sai se o post respondido também pode sair (a conversa não vaza pela metade).
 */
create or replace function interno.rede_fed_federavel(p interno.rede_posts, p_nivel integer default 0) returns boolean
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare a rede_fed_atores; pai rede_posts;
begin
  if p.id is null or p.autor is null or p_nivel > 8 then return false; end if;
  select * into a from rede_fed_atores where perfil = p.autor;
  if not found or not a.ligado or a.ligado_em is null or p.criado_em < a.ligado_em then return false; end if;
  if interno.rede_fed_impedimento(p.autor) is not null then return false; end if;
  if (select rede_handle from perfis where id = p.autor) is distinct from a.handle then return false; end if;
  if p.tipo = 'aviso' or p.nucleo is not null or p.repost_de is not null then return false; end if;
  if coalesce(p.publico, 'internet') <> 'internet' then return false; end if;
  if interno.rede2_publico(p) <> 'internet' or not interno.rede_ve(p, null) then return false; end if;
  if p.resposta_a is not null then
    select * into pai from rede_posts where id = p.resposta_a;
    if not found or not interno.rede_fed_federavel(pai, p_nivel + 1) then return false; end if;
  end if;
  return true;
end $$;

/** Põe na fila uma atividade para cada caixa de entrada dos seguidores remotos (a caixa compartilhada da instância, quando há). */
create or replace function interno.rede_fed_espalhar(p_perfil uuid, p_tipo text, p_objeto text) returns integer
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_n integer;
begin
  insert into rede_fed_fila (perfil, tipo, objeto, destino)
  select distinct p_perfil, p_tipo, p_objeto, coalesce(s.inbox_compartilhada, s.inbox)
  from rede_fed_seguidores s where s.perfil = p_perfil and not interno.rede_fed_bloqueado(s.inbox);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

/** Um post mudou: sai (Create), muda (Update) ou é retirado (Delete) do Fediverso, conforme pode ou não sair agora. */
create or replace function interno.rede_fed_post_mudou() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_p rede_posts; v_fed boolean := false; v_env rede_fed_enviados;
begin
  -- O caminho rápido: ninguém ligou a federação e nada foi enviado. Custa uma consulta a uma tabela quase sempre vazia.
  if not exists (select 1 from rede_fed_atores) then return null; end if;
  if tg_op = 'DELETE' then v_p := old; else v_p := new; v_fed := interno.rede_fed_federavel(new); end if;
  select * into v_env from rede_fed_enviados where post = v_p.id;
  if v_fed and (v_env.post is null or v_env.apagado_em is not null) then
    insert into rede_fed_enviados (post, perfil) values (v_p.id, v_p.autor) on conflict (post) do update set apagado_em = null, enviado_em = now();
    perform interno.rede_fed_espalhar(v_p.autor, 'create', v_p.id::text);
  elsif v_fed and tg_op = 'UPDATE' and (new.texto, coalesce(new.titulo, ''), coalesce(new.corpo, ''), new.aviso) is distinct from (old.texto, coalesce(old.titulo, ''), coalesce(old.corpo, ''), old.aviso) then
    perform interno.rede_fed_espalhar(v_p.autor, 'update', v_p.id::text);
  elsif not v_fed and v_env.post is not null and v_env.apagado_em is null then
    update rede_fed_enviados set apagado_em = now() where post = v_p.id;
    perform interno.rede_fed_espalhar(v_env.perfil, 'delete', v_p.id::text);
  end if;
  return null;
end $$;

drop trigger if exists rede_fed_post on interno.rede_posts;
create trigger rede_fed_post after insert or update or delete on interno.rede_posts for each row execute function interno.rede_fed_post_mudou();

/**
 * Desliga a federação de uma pessoa: retira do Fediverso cada post que saiu (Delete), desfaz quem a seguia de lá (Reject) e o que
 * ela seguia (Undo), e apaga as listas. As chaves ficam até a fila esvaziar (as instâncias conferem a assinatura dessas retiradas).
 */
create or replace function interno.rede_fed_desligar(p_perfil uuid) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare e record;
begin
  if not exists (select 1 from rede_fed_atores where perfil = p_perfil and ligado) then return; end if;
  for e in select post from rede_fed_enviados where perfil = p_perfil and apagado_em is null loop
    perform interno.rede_fed_espalhar(p_perfil, 'delete', e.post::text);
  end loop;
  update rede_fed_enviados set apagado_em = now() where perfil = p_perfil and apagado_em is null;
  insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
  select p_perfil, 'reject', s.ator, s.inbox, jsonb_build_object('pedido', s.pedido) from rede_fed_seguidores s
  where s.perfil = p_perfil and s.pedido <> '' and not interno.rede_fed_bloqueado(s.inbox);
  insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
  select p_perfil, 'undo-follow', s.ator, coalesce(r.inbox, s.ator), jsonb_build_object('pedido', s.pedido)
  from rede_fed_seguindo s join rede_fed_remotos r on r.ator = s.ator
  where s.perfil = p_perfil and r.inbox is not null and not interno.rede_fed_bloqueado(r.inbox);
  delete from rede_fed_seguidores where perfil = p_perfil;
  delete from rede_fed_seguindo where perfil = p_perfil;
  update rede_fed_atores set ligado = false, desligado_em = now() where perfil = p_perfil;
end $$;

/** A conta mudou de um jeito que fecha a federação (suspensa, perfil trancado ou invisível, @nome trocado, consentimento da rede revogado)? */
create or replace function interno.rede_fed_perfil_mudou() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if not exists (select 1 from rede_fed_atores where perfil = new.id and ligado) then return null; end if;
  if interno.rede_fed_impedimento(new.id) is not null or new.rede_handle is distinct from (select handle from rede_fed_atores where perfil = new.id) then
    perform interno.rede_fed_desligar(new.id);
  end if;
  return null;
end $$;

drop trigger if exists rede_fed_perfil on interno.perfis;
create trigger rede_fed_perfil after update of suspenso, rede_modo, rede_invisivel, rede_handle, rede_18, rede_consentimento on interno.perfis
  for each row execute function interno.rede_fed_perfil_mudou();

-- A revogação do consentimento da rede (rede_consentimentos.revogado_em) também desliga a federação.
create or replace function interno.rede_fed_consentimento_mudou() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if exists (select 1 from rede_fed_atores where perfil = new.usuario and ligado) and interno.rede_fed_impedimento(new.usuario) is not null then
    perform interno.rede_fed_desligar(new.usuario);
  end if;
  return null;
end $$;

drop trigger if exists rede_fed_consentimento on interno.rede_consentimentos;
create trigger rede_fed_consentimento after update on interno.rede_consentimentos for each row execute function interno.rede_fed_consentimento_mudou();

/**
 * A conta vai ser apagada (LGPD art. 18, VI): antes de o perfil sumir, a federação se desliga como num "desligar" normal (Delete de
 * cada post que saiu, Reject para quem seguia de fora, Undo do que ela seguia). A linha do ator e a fila não dependem do perfil,
 * então essas retiradas ainda saem assinadas; sem nada na fila, a linha sai já. O resto some com a faxina (rede_fed_limpar).
 */
create or replace function interno.rede_fed_conta_apagada() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if not exists (select 1 from rede_fed_atores where perfil = old.id) then return old; end if;
  perform interno.rede_fed_desligar(old.id);
  delete from rede_fed_atores a where a.perfil = old.id
    and not exists (select 1 from rede_fed_fila q where q.perfil = old.id and q.feito_em is null);
  return old;
end $$;

drop trigger if exists rede_fed_conta on interno.perfis;
create trigger rede_fed_conta before delete on interno.perfis for each row execute function interno.rede_fed_conta_apagada();

-- ── 5. Fediverso: o que a pessoa chama (com a sessão dela) ─────────────────────────────────────────────────────────────

/** A situação da federação para quem está na sessão: pode ligar? está ligada? quantas pessoas de fora seguem e são seguidas. */
create or replace function public.rede_fed_situacao() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); a rede_fed_atores;
begin
  if v is null then return jsonb_build_object('logado', false, 'ligado', false, 'pode', false, 'motivo', 'entre_primeiro', 'versao', interno.rede_fed_versao()); end if;
  select * into a from rede_fed_atores where perfil = v;
  return jsonb_build_object(
    'logado', true,
    'handle', (select rede_handle from perfis where id = v),
    'motivo', interno.rede_fed_impedimento(v),
    'pode', interno.rede_fed_impedimento(v) is null,
    'ligado', coalesce(a.ligado, false),
    'desde', case when a.ligado then a.ligado_em end,
    'seguidores', (select count(*)::integer from rede_fed_seguidores where perfil = v),
    'seguindo', (select count(*)::integer from rede_fed_seguindo where perfil = v),
    'versao', interno.rede_fed_versao());
end $$;

/** Liga (com o consentimento da versão em vigor) ou desliga a federação do próprio perfil. Desligar retira o que saiu. */
create or replace function public.rede_fed_ligar(p_sim boolean, p_versao integer default null) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_motivo text; v_handle text;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede_fed_ligar', 10, 60);
  if coalesce(p_sim, false) then
    v_motivo := interno.rede_fed_impedimento(v);
    if v_motivo is not null then perform interno.erro(v_motivo); end if;
    if p_versao is distinct from interno.rede_fed_versao() then perform interno.erro('invalido:versao'); end if;
    v_handle := (select rede_handle from perfis where id = v);
    if exists (select 1 from rede_fed_atores where handle = v_handle and ligado and perfil <> v) then perform interno.erro('invalido:handle'); end if;
    insert into rede_fed_atores (perfil, handle, ligado, consentimento_versao, ligado_em, desligado_em)
    values (v, v_handle, true, interno.rede_fed_versao(), now(), null)
    on conflict (perfil) do update set
      ligado_em = case when rede_fed_atores.ligado and rede_fed_atores.handle = excluded.handle then rede_fed_atores.ligado_em else now() end,
      -- Trocou de @nome desde a última vez: as chaves antigas não servem para o endereço novo.
      chave_publica = case when rede_fed_atores.handle = excluded.handle then rede_fed_atores.chave_publica end,
      chave_privada = case when rede_fed_atores.handle = excluded.handle then rede_fed_atores.chave_privada end,
      handle = excluded.handle, ligado = true, consentimento_versao = excluded.consentimento_versao, desligado_em = null;
  else
    perform interno.rede_fed_desligar(v);
  end if;
  return public.rede_fed_situacao();
end $$;

/** Quem a pessoa segue em outras instâncias. */
create or replace function public.rede_fed_seguindo_lista() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  return coalesce((select jsonb_agg(jsonb_build_object('ator', s.ator, 'aceito', s.aceito, 'handle', r.handle, 'nome', r.nome, 'url', r.url, 'desde', s.criado_em) order by s.criado_em desc)
    from rede_fed_seguindo s left join rede_fed_remotos r on r.ator = s.ator where s.perfil = v), '[]'::jsonb);
end $$;

/** Os posts recentes (até 30 dias) de quem a pessoa segue em outras instâncias, só texto. Cursor = data de publicação do último. */
create or replace function public.rede_fed_linha(p_antes timestamptz default null) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  return coalesce((select jsonb_agg(x order by x ->> 'publicado' desc) from (
    select jsonb_build_object('id', c.id, 'url', c.url, 'texto', c.texto, 'aviso', c.aviso, 'publicado', coalesce(c.publicado, c.recebido_em),
                              'ator', c.ator, 'handle', r.handle, 'nome', r.nome) as x
    from rede_fed_recebidos c join rede_fed_seguindo s on s.ator = c.ator and s.perfil = v and s.aceito
    left join rede_fed_remotos r on r.ator = c.ator
    where p_antes is null or coalesce(c.publicado, c.recebido_em) < p_antes
    order by coalesce(c.publicado, c.recebido_em) desc limit 30) y), '[]'::jsonb);
end $$;

/**
 * Quem está pedindo, para as rotas do servidor que agem em nome da pessoa (buscar e seguir alguém de fora). Confere a sessão,
 * a adesão à rede e o limite por pessoa; devolve o perfil e o estado da federação. O servidor chama com o token da própria pessoa.
 */
create or replace function public.rede_fed_eu(p_acao text) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); a rede_fed_atores;
begin
  perform interno.aberta('comunidade');
  if p_acao not in ('buscar', 'seguir') then perform interno.erro('invalido:acao'); end if;
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('rede_fed_' || p_acao, case p_acao when 'buscar' then 30 else 20 end, 60);
  select * into a from rede_fed_atores where perfil = v;
  return jsonb_build_object('perfil', v, 'handle', (select rede_handle from perfis where id = v), 'ligado', coalesce(a.ligado, false));
end $$;

/**
 * A mediação bloqueia (ou desbloqueia) uma instância inteira: nada entra dela, nada sai para ela, e o que havia dela some.
 * Com domínio vazio e p_sim nulo, só devolve a lista (a tela da mediação abre com ela).
 */
create or replace function public.rede_fed_bloquear(p_dominio text, p_sim boolean, p_motivo text default '') returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_d text := lower(btrim(coalesce(p_dominio, '')));
begin
  if not (interno.media() or interno.cuida()) then perform interno.erro('sem_permissao'); end if;
  if v_d = '' and p_sim is null then
    return coalesce((select jsonb_agg(jsonb_build_object('dominio', dominio, 'motivo', motivo, 'desde', criado_em) order by dominio) from rede_fed_bloqueados), '[]'::jsonb);
  end if;
  if v_d !~ '^[a-z0-9.-]{3,253}$' or v_d !~ '\.' then perform interno.erro('invalido:dominio'); end if;
  if coalesce(p_sim, true) then
    insert into rede_fed_bloqueados (dominio, motivo, por) values (v_d, left(coalesce(p_motivo, ''), 300), v)
    on conflict (dominio) do update set motivo = excluded.motivo, por = excluded.por, criado_em = now();
    delete from rede_fed_seguidores where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_seguindo where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_recebidos where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_remotos where interno.rede_fed_bloqueado(ator);
    update rede_fed_fila set feito_em = now(), erro = 'instancia_bloqueada' where feito_em is null and interno.rede_fed_bloqueado(destino);
  else
    delete from rede_fed_bloqueados where dominio = v_d;
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('dominio', dominio, 'motivo', motivo, 'desde', criado_em) order by dominio) from rede_fed_bloqueados), '[]'::jsonb);
end $$;

-- ── 6. Fediverso: o que o servidor do site chama (com o segredo da federação) ───────────────────────────────────────────

/** O post como sai para o Fediverso: só o que pode sair agora (confere de novo na hora de entregar). */
create or replace function interno.rede_fed_post_json(p interno.rede_posts) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', p.id, 'tipo', p.tipo, 'titulo', p.titulo, 'texto', p.texto, 'corpo', p.corpo, 'aviso', p.aviso,
    'criado_em', p.criado_em, 'editado_em', p.editado_em, 'resposta_a', p.resposta_a, 'comunidade', p.comunidade,
    'handle', (select handle from rede_fed_atores where perfil = p.autor))
$$;

/**
 * As ações do servidor do site para a federação, numa função só, todas atrás do segredo (interno.rede_fed_segredo). O servidor
 * chama com a chave pública do banco e o segredo; nenhuma chave de serviço é usada. Ações:
 *   ator {handle}                 → {estado: ligado|saindo|desligado|inexistente, perfil, handle, nome, bio, ligado_em, chave_publica, chave_privada}
 *   chaves {perfil, publica, privada} → guarda o par se ainda não há (a privada já vem cifrada); devolve o par guardado
 *   instancia {publica?, privada?} → o par da instância (para buscar com assinatura); grava se ainda não há
 *   outbox {handle, antes?, limite?} → {total, itens: post[]}       post {id} → post ou nulo
 *   seguidores {handle} → {total}
 *   seguidor {handle, ator, inbox, compartilhada?, pedido, sim} → grava/apaga quem segue de fora; ao gravar, põe o Accept na fila
 *   remoto {ator} → o que se sabe do ator; remoto_salvar {ator, chave_id, chave_publica, inbox, compartilhada, handle, nome, resumo, url}
 *   resposta_follow {ator, pedido, aceito} → Accept/Reject de quem alguém daqui pediu para seguir
 *   ator_apagado {ator} → esquece um ator que foi apagado na instância dele
 *   recebido {id, ator, url, texto, aviso, publicado} → guarda o post de quem alguém daqui segue (e só nesse caso)
 *   seguir {perfil, ator, pedido, sim} → alguém daqui segue (ou deixa de seguir) um ator de fora: grava e põe Follow/Undo na fila
 *   fila_pegar {limite} → reserva até N entregas vencidas; fila_feito {id, ok, definitivo, erro}
 *   contagem → {usuarios, posts} (NodeInfo)      bloqueado {url} → boolean
 */
create or replace function public.rede_fed_servidor(p_segredo text, p_acao text, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  a rede_fed_atores;
  f perfis;
  x rede_posts;
  v_limite integer;
  v_antes timestamptz;
  v_res jsonb;
  v_n integer;
  v_t smallint;
  v_ator text := left(coalesce(p ->> 'ator', ''), 500);
begin
  perform interno.rede_fed_segredo(p_segredo);
  p := coalesce(p, '{}'::jsonb);
  if v_ator <> '' and v_ator !~ '^https://[^\s]+$' then perform interno.erro('invalido:ator'); end if;

  case p_acao
  when 'ator' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) order by ligado desc, desligado_em desc nulls first limit 1;
    if not found then return jsonb_build_object('estado', 'inexistente'); end if;
    select * into f from perfis where id = a.perfil;
    if a.ligado and interno.rede_fed_impedimento(a.perfil) is null then
      return jsonb_build_object('estado', 'ligado', 'perfil', a.perfil, 'handle', a.handle, 'nome', coalesce(nullif(f.rede_codinome, ''), a.handle),
        'bio', case when f.rede_codinome_ok then left(coalesce(f.rede_bio, ''), 500) else '' end, 'ligado_em', a.ligado_em,
        'chave_publica', a.chave_publica, 'chave_privada', a.chave_privada);
    end if;
    -- Desligado com entregas ainda na fila (as retiradas): o ator continua com a chave, sem nada mais.
    if exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null) and a.chave_publica is not null then
      return jsonb_build_object('estado', 'saindo', 'perfil', a.perfil, 'handle', a.handle, 'chave_publica', a.chave_publica, 'chave_privada', a.chave_privada);
    end if;
    return jsonb_build_object('estado', 'desligado');

  when 'chaves' then
    if coalesce(p ->> 'publica', '') !~ '^-----BEGIN PUBLIC KEY-----' or char_length(coalesce(p ->> 'privada', '')) < 100 then perform interno.erro('invalido:chave'); end if;
    update rede_fed_atores set chave_publica = p ->> 'publica', chave_privada = p ->> 'privada'
    where perfil = (p ->> 'perfil')::uuid and chave_publica is null;
    select * into a from rede_fed_atores where perfil = (p ->> 'perfil')::uuid;
    return jsonb_build_object('chave_publica', a.chave_publica, 'chave_privada', a.chave_privada);

  when 'instancia' then
    if (p ->> 'publica') is not null then
      if (p ->> 'publica') !~ '^-----BEGIN PUBLIC KEY-----' or char_length(coalesce(p ->> 'privada', '')) < 100 then perform interno.erro('invalido:chave'); end if;
      insert into configuracoes (chave, valor) values ('fediverso_instancia', jsonb_build_object('publica', p ->> 'publica', 'privada', p ->> 'privada'))
      on conflict (chave) do nothing;
    end if;
    return coalesce((select valor from configuracoes where chave = 'fediverso_instancia'), '{}'::jsonb);

  when 'outbox' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found then return jsonb_build_object('total', 0, 'itens', '[]'::jsonb); end if;
    v_limite := least(greatest(coalesce((p ->> 'limite')::integer, 20), 1), 40);
    v_antes := nullif(p ->> 'antes', '')::timestamptz;
    select count(*)::integer into v_n from rede_fed_enviados e where e.perfil = a.perfil and e.apagado_em is null;
    select coalesce(jsonb_agg(interno.rede_fed_post_json(r) order by r.criado_em desc), '[]'::jsonb) into v_res
    from (select r.* from rede_fed_enviados e join rede_posts r on r.id = e.post
          where e.perfil = a.perfil and e.apagado_em is null and (v_antes is null or r.criado_em < v_antes) and interno.rede_fed_federavel(r)
          order by r.criado_em desc limit v_limite) r;
    return jsonb_build_object('total', v_n, 'itens', v_res);

  when 'post' then
    begin
      select * into x from rede_posts where id = (p ->> 'id')::uuid;
    exception when others then
      return 'null'::jsonb;
    end;
    if not found or not interno.rede_fed_federavel(x) then
      -- Já saiu e foi retirado: a federação responde 410 (Gone) em vez de 404.
      if exists (select 1 from rede_fed_enviados e where e.post::text = p ->> 'id' and e.apagado_em is not null) then return jsonb_build_object('apagado', true); end if;
      return 'null'::jsonb;
    end if;
    return interno.rede_fed_post_json(x);

  when 'seguidores' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found then return jsonb_build_object('total', 0); end if;
    return jsonb_build_object('total', (select count(*)::integer from rede_fed_seguidores where perfil = a.perfil));

  when 'seguidor' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found or interno.rede_fed_impedimento(a.perfil) is not null then return jsonb_build_object('ok', false, 'motivo', 'desligado'); end if;
    if interno.rede_fed_bloqueado(v_ator) or interno.rede_fed_bloqueado(p ->> 'inbox') then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    if coalesce((p ->> 'sim')::boolean, true) then
      if coalesce(p ->> 'inbox', '') !~ '^https://[^\s]+$' or interno.rede_fed_dominio(p ->> 'inbox') <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:inbox'); end if;
      insert into rede_fed_seguidores (perfil, ator, inbox, inbox_compartilhada, pedido)
      values (a.perfil, v_ator, p ->> 'inbox',
              case when coalesce(p ->> 'compartilhada', '') ~ '^https://[^\s]+$' and interno.rede_fed_dominio(p ->> 'compartilhada') = interno.rede_fed_dominio(v_ator) then p ->> 'compartilhada' end,
              left(coalesce(p ->> 'pedido', ''), 500))
      on conflict (perfil, ator) do update set inbox = excluded.inbox, inbox_compartilhada = excluded.inbox_compartilhada, pedido = excluded.pedido;
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra) values (a.perfil, 'accept', v_ator, p ->> 'inbox', jsonb_build_object('pedido', left(coalesce(p ->> 'pedido', ''), 500)));
    else
      delete from rede_fed_seguidores where perfil = a.perfil and ator = v_ator;
    end if;
    return jsonb_build_object('ok', true, 'perfil', a.perfil);

  when 'remoto' then
    return coalesce((select to_jsonb(r) from rede_fed_remotos r where r.ator = v_ator or r.chave_id = left(coalesce(p ->> 'chave_id', ''), 600) limit 1), 'null'::jsonb);

  when 'remoto_salvar' then
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if interno.rede_fed_bloqueado(v_ator) then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    insert into rede_fed_remotos (ator, chave_id, chave_publica, inbox, inbox_compartilhada, handle, nome, resumo, url, buscado_em)
    values (v_ator, left(p ->> 'chave_id', 600), left(p ->> 'chave_publica', 4000),
            case when coalesce(p ->> 'inbox', '') ~ '^https://[^\s]+$' then left(p ->> 'inbox', 500) end,
            case when coalesce(p ->> 'compartilhada', '') ~ '^https://[^\s]+$' then left(p ->> 'compartilhada', 500) end,
            left(p ->> 'handle', 200), left(p ->> 'nome', 200), left(p ->> 'resumo', 1000),
            case when coalesce(p ->> 'url', '') ~ '^https://[^\s]+$' then left(p ->> 'url', 500) end, now())
    on conflict (ator) do update set chave_id = excluded.chave_id, chave_publica = excluded.chave_publica, inbox = excluded.inbox,
      inbox_compartilhada = excluded.inbox_compartilhada, handle = excluded.handle, nome = excluded.nome, resumo = excluded.resumo,
      url = excluded.url, buscado_em = now();
    return jsonb_build_object('ok', true);

  when 'resposta_follow' then
    if coalesce((p ->> 'aceito')::boolean, false) then
      update rede_fed_seguindo set aceito = true where ator = v_ator and (pedido = coalesce(p ->> 'pedido', '') or coalesce(p ->> 'pedido', '') = '');
    else
      delete from rede_fed_seguindo where ator = v_ator and (pedido = coalesce(p ->> 'pedido', '') or coalesce(p ->> 'pedido', '') = '');
    end if;
    get diagnostics v_n = row_count;
    return jsonb_build_object('ok', v_n > 0);

  when 'ator_apagado' then
    delete from rede_fed_seguidores where ator = v_ator;
    delete from rede_fed_seguindo where ator = v_ator;
    delete from rede_fed_recebidos where ator = v_ator;
    delete from rede_fed_remotos where ator = v_ator;
    return jsonb_build_object('ok', true);

  when 'recebido' then
    if not exists (select 1 from rede_fed_seguindo s where s.ator = v_ator and s.aceito) or interno.rede_fed_bloqueado(v_ator) then
      return jsonb_build_object('guardado', false);
    end if;
    if coalesce(p ->> 'id', '') !~ '^https://[^\s]+$' or interno.rede_fed_dominio(p ->> 'id') <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:id'); end if;
    insert into rede_fed_recebidos (id, ator, url, texto, aviso, publicado)
    values (left(p ->> 'id', 500), v_ator, case when coalesce(p ->> 'url', '') ~ '^https://[^\s]+$' then left(p ->> 'url', 500) end,
            left(coalesce(p ->> 'texto', ''), 3000), left(coalesce(p ->> 'aviso', ''), 200),
            least(coalesce(nullif(p ->> 'publicado', '')::timestamptz, now()), now()))
    on conflict (id) do update set texto = excluded.texto, aviso = excluded.aviso;
    return jsonb_build_object('guardado', true);

  when 'recebido_apagado' then
    delete from rede_fed_recebidos where id = left(coalesce(p ->> 'id', ''), 500) and ator = v_ator;
    return jsonb_build_object('ok', true);

  when 'seguir' then
    select * into a from rede_fed_atores where perfil = (p ->> 'perfil')::uuid and ligado;
    if not found then perform interno.erro('fediverso_desligado'); end if;
    if interno.rede_fed_bloqueado(v_ator) then perform interno.erro('instancia_bloqueada'); end if;
    if coalesce((p ->> 'sim')::boolean, true) then
      if not exists (select 1 from rede_fed_remotos r where r.ator = v_ator and r.inbox is not null) then perform interno.erro('nao_encontrado'); end if;
      if (select count(*) from rede_fed_seguindo where perfil = a.perfil) >= 2000 then perform interno.erro('muitos_pedidos'); end if;
      insert into rede_fed_seguindo (perfil, ator, pedido) values (a.perfil, v_ator, left(coalesce(p ->> 'pedido', ''), 500))
      on conflict (perfil, ator) do update set pedido = excluded.pedido, aceito = false;
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select a.perfil, 'follow', v_ator, r.inbox, jsonb_build_object('pedido', left(coalesce(p ->> 'pedido', ''), 500)) from rede_fed_remotos r where r.ator = v_ator;
    else
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select a.perfil, 'undo-follow', v_ator, r.inbox, jsonb_build_object('pedido', s.pedido)
      from rede_fed_seguindo s join rede_fed_remotos r on r.ator = s.ator where s.perfil = a.perfil and s.ator = v_ator and r.inbox is not null;
      delete from rede_fed_seguindo where perfil = a.perfil and ator = v_ator;
    end if;
    return jsonb_build_object('ok', true);

  when 'fila_pegar' then
    v_limite := least(greatest(coalesce((p ->> 'limite')::integer, 20), 1), 100);
    if random() < 0.05 then perform interno.rede_fed_limpar(); end if;
    with escolhidos as (
      select q.id from rede_fed_fila q where q.feito_em is null and q.proxima <= now() order by q.proxima, q.id limit v_limite for update skip locked
    ), reservados as (
      update rede_fed_fila q set proxima = now() + interval '3 minutes', tentativas = q.tentativas + 1 from escolhidos e where q.id = e.id returning q.*
    )
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'tipo', r.tipo, 'objeto', r.objeto, 'destino', r.destino, 'extra', r.extra,
      'tentativas', r.tentativas, 'handle', t.handle, 'chave_publica', t.chave_publica, 'chave_privada', t.chave_privada) order by r.id), '[]'::jsonb)
    into v_res from reservados r join rede_fed_atores t on t.perfil = r.perfil;
    return v_res;

  when 'fila_feito' then
    select tentativas into v_t from rede_fed_fila where id = (p ->> 'id')::bigint;
    if coalesce((p ->> 'ok')::boolean, false) then
      update rede_fed_fila set feito_em = now(), erro = '' where id = (p ->> 'id')::bigint;
    elsif coalesce((p ->> 'definitivo')::boolean, false) or coalesce(v_t, 0) >= 8 then
      update rede_fed_fila set feito_em = now(), erro = left(coalesce(p ->> 'erro', 'falha'), 300) where id = (p ->> 'id')::bigint;
    else
      update rede_fed_fila set erro = left(coalesce(p ->> 'erro', 'falha'), 300),
        proxima = now() + least(interval '12 hours', interval '1 minute' * power(2, greatest(coalesce(v_t, 1), 1)))
      where id = (p ->> 'id')::bigint;
    end if;
    return jsonb_build_object('ok', true);

  when 'contagem' then
    return jsonb_build_object('usuarios', (select count(*)::integer from rede_fed_atores where ligado),
                              'posts', (select count(*)::integer from rede_fed_enviados where apagado_em is null));

  when 'bloqueado' then
    return to_jsonb(interno.rede_fed_bloqueado(coalesce(p ->> 'url', '')));

  else
    perform interno.erro('invalido:acao');
  end case;
  return null;
end $$;

/** A faxina da federação: entregas feitas há mais de 14 dias, posts recebidos há mais de 30 dias e atores remotos esquecidos. */
create or replace function interno.rede_fed_limpar() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_fed_fila where feito_em is not null and feito_em < now() - interval '14 days';
  delete from rede_fed_recebidos where recebido_em < now() - interval '30 days';
  delete from rede_fed_remotos r where r.buscado_em < now() - interval '60 days'
    and not exists (select 1 from rede_fed_seguidores s where s.ator = r.ator) and not exists (select 1 from rede_fed_seguindo s where s.ator = r.ator);
  -- Chaves de quem desligou e já não tem nada na fila: apagadas (religar gera um par novo).
  update rede_fed_atores a set chave_publica = null, chave_privada = null
  where not a.ligado and a.chave_privada is not null and a.desligado_em < now() - interval '1 day'
    and not exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null);
  -- Conta apagada (interno.rede_fed_conta_apagada): as retiradas já saíram ou desistiram; a linha e a fila dela somem.
  delete from rede_fed_atores a where not exists (select 1 from perfis f where f.id = a.perfil)
    and not exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null);
  delete from rede_fed_fila q where q.feito_em is not null and not exists (select 1 from perfis f where f.id = q.perfil);
end $$;

/**
 * Cutuca o servidor do site para entregar a fila (pg_net), se há entrega vencida e a configuração tem 'url_entrega'
 * (interno.configuracoes, chave 'fediverso'). O pedido não leva segredo: a rota só entrega o que já está na fila.
 */
create or replace function interno.rede_fed_cutucar() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_url text := (select valor ->> 'url_entrega' from configuracoes where chave = 'fediverso');
begin
  if coalesce(v_url, '') !~ '^https://[a-z0-9.-]+/api/fediverso/entregar$' then return; end if;
  if not exists (select 1 from rede_fed_fila where feito_em is null and proxima <= now()) then return; end if;
  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := $2, timeout_milliseconds := 30000)'
    using v_url, jsonb_build_object('Content-Type', 'application/json');
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-fediverso-limpar', '41 4 * * *', 'select interno.rede_fed_limpar()');
    if exists (select 1 from pg_extension where extname = 'pg_net') then
      perform cron.schedule('lucia-fediverso-entregar', '* * * * *', 'select interno.rede_fed_cutucar()');
    end if;
  end if;
exception when others then null;
end $$;

-- ── 7. Permissões ───────────────────────────────────────────────────────────────────────────────────────────────────────
-- Nenhuma função interna é chamável de fora. As da pessoa pedem conta (a própria função confere a sessão); a do servidor
-- (rede_fed_servidor) é chamada com a chave pública, mas só responde a quem traz o segredo da federação.
revoke all on function interno.rede_fed_versao(), interno.rede_fed_dominio(text), interno.rede_fed_bloqueado(text), interno.rede_fed_segredo(text),
  interno.rede_fed_impedimento(uuid), interno.rede_fed_federavel(interno.rede_posts, integer), interno.rede_fed_espalhar(uuid, text, text),
  interno.rede_fed_post_mudou(), interno.rede_fed_desligar(uuid), interno.rede_fed_perfil_mudou(), interno.rede_fed_consentimento_mudou(),
  interno.rede_fed_conta_apagada(), interno.rede_fed_post_json(interno.rede_posts), interno.rede_fed_limpar(), interno.rede_fed_cutucar() from public;
revoke all on function public.rede_alumia_salvos(text, integer), public.rede_fed_situacao(), public.rede_fed_ligar(boolean, integer),
  public.rede_fed_seguindo_lista(), public.rede_fed_linha(timestamptz), public.rede_fed_eu(text), public.rede_fed_bloquear(text, boolean, text),
  public.rede_fed_servidor(text, text, jsonb) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_fed_versao(), interno.rede_fed_dominio(text), interno.rede_fed_bloqueado(text), interno.rede_fed_segredo(text),
      interno.rede_fed_impedimento(uuid), interno.rede_fed_federavel(interno.rede_posts, integer), interno.rede_fed_espalhar(uuid, text, text),
      interno.rede_fed_post_mudou(), interno.rede_fed_desligar(uuid), interno.rede_fed_perfil_mudou(), interno.rede_fed_consentimento_mudou(),
      interno.rede_fed_conta_apagada(), interno.rede_fed_post_json(interno.rede_posts), interno.rede_fed_limpar(), interno.rede_fed_cutucar() from anon, authenticated;
    revoke all on function public.rede_alumia_salvos(text, integer), public.rede_fed_situacao(), public.rede_fed_ligar(boolean, integer),
      public.rede_fed_seguindo_lista(), public.rede_fed_linha(timestamptz), public.rede_fed_eu(text), public.rede_fed_bloquear(text, boolean, text),
      public.rede_fed_servidor(text, text, jsonb) from anon, authenticated;
    grant execute on function public.rede_alumia_salvos(text, integer), public.rede_fed_ligar(boolean, integer), public.rede_fed_seguindo_lista(),
      public.rede_fed_linha(timestamptz), public.rede_fed_eu(text), public.rede_fed_bloquear(text, boolean, text) to authenticated, service_role;
    grant execute on function public.rede_fed_situacao(), public.rede_fed_servidor(text, text, jsonb) to anon, authenticated, service_role;
  end if;
end $$;

-- ───────────────────────────── Frente Revolucionária Lúcia: inscrição de militantes (T15, novembro de 2026) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. O mesmo bloco está no fim do install.sql.
-- Explicação e decisões: docs/escola-revolucionaria/LEIA-ME.md. Teste: npm run testar:militantes.
--
-- A Escola Revolucionária Lúcia Maria chama voluntários militantes da Frente Revolucionária Lúcia. A inscrição usa a
-- MESMA fila do voluntariado (interno.inscricoes, public.voluntariar), para chegar no mesmo lugar do painel interno
-- (Pessoas, "Candidaturas"). Só acréscimos:
--
-- 1. interno.inscricoes ganha `tipo` ('voluntario' | 'militante', padrão 'voluntario': nada do que já existe muda),
--    `consentimento_em` e `maior_idade`.
-- 2. public.voluntariar passa a aceitar p.tipo = 'militante'. Tudo o que já valia continua valendo (mesmas regras, mesmo
--    freio, mesmo campo-isca). Para militante, exige também:
--      - consentimento específico e destacado (p.consentimento = true): dizer que quer militar numa frente política
--        revela OPINIÃO POLÍTICA e FILIAÇÃO A ORGANIZAÇÃO DE CARÁTER POLÍTICO, que a LGPD chama de dado pessoal
--        sensível (Lei 13.709/2018, art. 5º, II). O tratamento só pode ser feito com consentimento "de forma específica
--        e destacada, para finalidades específicas" (art. 11, I). O momento do consentimento fica guardado
--        (`consentimento_em`), porque cabe ao controlador provar que ele foi dado (art. 8º, § 2º).
--      - maioridade declarada (p.maior_idade = true): a inscrição militante é só para quem tem 18 anos ou mais. Dado
--        sensível de adolescente pediria o consentimento de um dos pais ou responsável e o melhor interesse (art. 14 da
--        LGPD; ECA, Lei 8.069/1990, arts. 17 e 18, e ECA Digital, Lei 15.211/2025). Sem vínculo de contas com
--        responsável, a decisão conservadora é não receber. Quem tem menos de 18 continua estudando na Escola.
--    O tipo militante entra também no "já pediu" (a mesma pessoa pode ter um pedido de voluntário e outro de militante).
--    Os e-mails de confirmação e de aviso à coordenação dizem que é inscrição militante.
-- 3. public.inscricoes_listar devolve também `tipo` e `consentimento_em` (o painel mostra a marca "Militante").
--
-- Nada de rastreio: o banco não guarda endereço de rede na inscrição; o freio (interno.limite) é o mesmo do voluntariado.

-- 1. Colunas novas ────────────────────────────────────────────────────────────────────────────────────────────────────────
alter table interno.inscricoes add column if not exists tipo text not null default 'voluntario';
alter table interno.inscricoes drop constraint if exists inscricoes_tipo_check;
alter table interno.inscricoes add constraint inscricoes_tipo_check check (tipo in ('voluntario', 'militante'));
alter table interno.inscricoes add column if not exists consentimento_em timestamptz;
alter table interno.inscricoes add column if not exists maior_idade boolean;
-- Militante sem consentimento ou sem maioridade declarada não entra, nem por fora da função (LGPD, art. 11, I).
alter table interno.inscricoes drop constraint if exists inscricoes_militante_check;
alter table interno.inscricoes add constraint inscricoes_militante_check
  check (tipo <> 'militante' or (consentimento_em is not null and coalesce(maior_idade, false)));
create index if not exists inscricoes_tipo on interno.inscricoes (tipo, status, criado_em);

-- 2. A candidatura pública, agora também militante ────────────────────────────────────────────────────────────────────────
/**
 * Quem quer ser voluntário preenche o formulário, sem precisar de conta: nome completo, e-mail de contato, função
 * pretendida e uma apresentação. A coordenação lê no painel e responde por e-mail.
 * T15: com p.tipo = 'militante', a inscrição é da Frente Revolucionária Lúcia (Escola Revolucionária Lúcia Maria) e
 * exige o consentimento destacado (dado sensível, LGPD art. 11, I) e a maioridade declarada (LGPD art. 14).
 */
create or replace function public.voluntariar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_papel text := coalesce(p ->> 'papel', '');
  v_disc text := interno.disciplina_ok(p ->> 'disciplina');
  v_tipo text := coalesce(nullif(p ->> 'tipo', ''), 'voluntario');
  v_militante boolean;
  v_nome text; v_mensagem text; v_id uuid;
  v_instagram text := nullif(regexp_replace(btrim(coalesce(p ->> 'instagram', '')), '^@', ''), '');
begin
  perform interno.aberta('voluntariado');
  -- Campo-isca: gente não vê, robô preenche. Finge que deu certo e não guarda nada.
  if coalesce(p ->> 'site', '') <> '' then return jsonb_build_object('id', gen_random_uuid()); end if;
  perform interno.limite('voluntariar', 3, 1440);
  if v_tipo not in ('voluntario', 'militante') then perform interno.erro('invalido:tipo'); end if;
  v_militante := v_tipo = 'militante';
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or char_length(v_email) > 200 then perform interno.erro('invalido:email'); end if;
  if v_papel not in ('curadoria', 'mediacao', 'educacao', 'educacao_secundaria', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'marketing', 'desenvolvimento', 'porta_voz', 'saude') then perform interno.erro('invalido:papel'); end if;
  if v_papel in ('educacao', 'educacao_secundaria', 'mentoria') and v_disc is null then perform interno.erro('invalido:disciplina'); end if;
  if v_papel not in ('educacao', 'educacao_secundaria', 'mentoria') then v_disc := null; end if;
  -- Militante: consentimento destacado para o dado sensível (LGPD, art. 11, I) e 18 anos ou mais (LGPD, art. 14).
  if v_militante and coalesce(p ->> 'consentimento', '') <> 'true' then perform interno.erro('invalido:consentimento'); end if;
  if v_militante and coalesce(p ->> 'maior_idade', '') <> 'true' then perform interno.erro('invalido:idade'); end if;
  v_nome := interno.txt(p ->> 'nome', 'nome', 5, 120);
  -- Nome e sobrenome: a coordenação precisa saber quem está pedindo acesso.
  if array_length(regexp_split_to_array(btrim(v_nome), '\s+'), 1) < 2 then perform interno.erro('invalido:nome'); end if;
  if v_instagram is not null and v_instagram !~ '^[A-Za-z0-9._]{1,30}$' then perform interno.erro('invalido:instagram'); end if;
  v_mensagem := interno.txt(p ->> 'mensagem', 'mensagem', 30, 2000);
  if interno.vetado(v_nome || ' ' || v_mensagem) then perform interno.erro('conteudo_recusado'); end if;
  if exists (select 1 from inscricoes where email = v_email and papel = v_papel and tipo = v_tipo and status = 'pendente') then perform interno.erro('ja_pediu'); end if;
  insert into inscricoes (nome, email, papel, disciplina, mensagem, instagram, tipo, consentimento_em, maior_idade)
    values (v_nome, v_email, v_papel, v_disc, v_mensagem, v_instagram, v_tipo, case when v_militante then now() end, case when v_militante then true end)
    returning id into v_id;
  if v_militante then
    perform interno.email(v_email, 'inscricao_recebida', 'Recebemos sua inscrição de militante',
      'Olá, ' || coalesce(nullif(left(split_part(interno.sem_link(v_nome), ' ', 1), 40), ''), 'tudo bem') || E'.\n\nRecebemos sua inscrição como militante voluntário(a) da Frente Revolucionária Lúcia, na frente de trabalho de ' || interno.nome_papel(v_papel) || E'.\n\n'
      || E'A coordenação lê cada inscrição e responde por este mesmo endereço. Os seus dados são vistos só pela coordenação e servem só para responder a você.\n\n'
      || E'Você pode pedir a qualquer momento que a sua inscrição seja apagada, respondendo a este e-mail.\n\n'
      || 'Se não foi você quem enviou esta inscrição, é só ignorar esta mensagem.');
    perform interno.email_lideranca('inscricao_nova', 'Nova inscrição militante: ' || left(interno.sem_link(v_nome), 60),
      interno.sem_link(v_nome) || ' (' || v_email || coalesce(', Instagram @' || v_instagram, '') || ') quer militar na Frente Revolucionária Lúcia, na frente de ' || interno.nome_papel(v_papel) || E'.\n\nLeia a inscrição e decida no painel: ' || interno.endereco() || '/pt/painel?aba=pessoas');
  else
    perform interno.email(v_email, 'inscricao_recebida', 'Recebemos seu pedido de voluntariado',
      'Olá, ' || coalesce(nullif(left(split_part(interno.sem_link(v_nome), ' ', 1), 40), ''), 'tudo bem') || E'.\n\nRecebemos seu pedido para atuar como voluntário(a) no Instituto Lúcia, na função de ' || interno.nome_papel(v_papel) || E'.\n\n'
      || E'A coordenação lê cada pedido e responde por este mesmo endereço. Se o pedido for aceito, chega aqui o link para você criar a sua conta e entrar no painel da equipe.\n\n'
      || 'Se não foi você quem enviou este pedido, é só ignorar esta mensagem.');
    perform interno.email_lideranca('inscricao_nova', 'Novo pedido de voluntariado: ' || left(interno.sem_link(v_nome), 60),
      interno.sem_link(v_nome) || ' (' || v_email || coalesce(', Instagram @' || v_instagram, '') || ') quer atuar na função de ' || interno.nome_papel(v_papel) || E'.\n\nLeia o pedido e decida no painel: ' || interno.endereco() || '/pt/painel?aba=pessoas');
  end if;
  return jsonb_build_object('id', v_id);
end $$;

-- 3. A lista do painel, com o tipo ────────────────────────────────────────────────────────────────────────────────────────
create or replace function public.inscricoes_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'nome', i.nome, 'email', i.email, 'papel', i.papel, 'disciplina', i.disciplina, 'instagram', i.instagram,
            'mensagem', i.mensagem, 'status', i.status, 'criado_em', i.criado_em, 'tem_conta', exists (select 1 from auth.users u where lower(u.email) = i.email),
            'tipo', i.tipo, 'consentimento_em', i.consentimento_em)
            order by (i.status = 'pendente') desc, i.criado_em desc), '[]'::jsonb)
          from (select * from inscricoes order by criado_em desc limit 300) i);
end $$;
-- ───────────────────────────── Pessoas no painel: várias funções, departamentos de hoje e troca de e-mail (T28, T29, T30) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Vai no fim do install.sql.
-- Documentação: docs/DEPARTAMENTOS-TERMOS.md (seção "Novembro, 6: pessoas no painel").
--
-- T28. Várias funções e várias disciplinas de uma vez. As funções já moram numa tabela de ligação (interno.papeis: uma linha
--      por pessoa, função e disciplina), então nada precisa migrar: o que muda é que a coordenação confia tudo numa ação
--      só (public.papeis_conceder_varios), com as mesmas regras de nível de public.papel_conceder, e a pessoa recebe um
--      recado só. O convite pessoal também passa a levar mais de uma função e departamentos (convites.extras).
-- T29. Convites: a lista diz a situação de cada um (valendo, usado, vencido, cancelado) e quem usou. Troca do e-mail de uma
--      conta (public.usuario_email_trocar): só a coordenação comunitária, com motivo, registro no histórico (com o
--      e-mail mascarado) e aviso por e-mail ao endereço antigo e ao novo. Feita dentro do banco, como a redefinição de
--      senha: a chave de serviço não fica no servidor do site (veja .env.example), e nenhuma chave nova foi criada.
-- T30. Os departamentos de hoje (os grupos do instituto): entram Parcerias (coletivos parceiros), Influenciadores,
--      Representantes, RH (Recursos Humanos) e Revolucionários (militantes da Frente Revolucionária Lúcia). Os que já
--      existiam mantêm o id interno (nada se perde); só o nome que aparece muda, na tela. A participação nesses
--      departamentos fica numa tabela de ligação própria (interno.departamento_membros): uma pessoa pode estar em vários.
--
-- Dado sensível: participar do departamento Revolucionários revela opinião e filiação política, dado pessoal sensível
-- (LGPD, art. 5º, II, e art. 11). Por isso a lista de quem participa só aparece para a coordenação (comunitária e
-- pedagógica) e para quem é do próprio departamento; a supervisão não entra no grupo de conversa dele, e só a
-- coordenação põe ou tira alguém dele.

-- 1. Os departamentos novos ──────────────────────────────────────────────────────────────────────────────────
alter table interno.departamentos_info drop constraint if exists departamentos_info_id_check;
alter table interno.departamentos_info add constraint departamentos_info_id_check check (id in
  ('jornalismo', 'design', 'educacao', 'mentoria', 'curadoria', 'revisao', 'traducao', 'mediacao', 'desenvolvimento', 'saude', 'coordenacao',
   'parcerias', 'influenciadores', 'representantes', 'rh', 'revolucionarios'));

insert into interno.departamentos_info (id, descricao) values
  ('parcerias', 'Os coletivos parceiros do instituto: quem constrói junto com a gente, cada um no seu território.'),
  ('influenciadores', 'Quem leva o instituto para as redes com a própria voz: criadores de conteúdo e perfis parceiros.'),
  ('representantes', 'Os representantes de todos os departamentos juntos: combinar o que é de mais de um departamento e levar as questões à coordenação.'),
  ('rh', 'Recursos Humanos: acolher quem chega, acompanhar os voluntários (termos, horas, férias) e cuidar da equipe.'),
  ('revolucionarios', 'Os militantes da Frente Revolucionária Lúcia. Quem participa só aparece para a coordenação e para o próprio departamento.')
on conflict (id) do nothing;

/** Os departamentos em que se entra por participação (não por uma função de trabalho). */
create or replace function interno.departamentos_de_participacao() returns text[] language sql immutable as $$
  select array['parcerias', 'influenciadores', 'representantes', 'rh', 'revolucionarios']
$$;

-- A tabela de ligação pessoa ↔ departamento (a participação). Uma linha por pessoa e departamento.
create table if not exists interno.departamento_membros (
  departamento text not null references interno.departamentos_info (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  incluido_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  primary key (departamento, usuario)
);
create index if not exists departamento_membros_usuario on interno.departamento_membros (usuario);
-- Trancada duas vezes, como as outras: sem permissões e com segurança por linha ligada (sem regra = ninguém passa).
-- Só as funções do banco (security definer) leem e escrevem.
alter table interno.departamento_membros enable row level security;
revoke all on interno.departamento_membros from public, anon, authenticated;

/** O departamento existe e aceita representante (uma função, um grupo de disciplinas ou um departamento de participação). */
create or replace function interno.departamento_valido(p text) returns boolean language sql immutable as $$
  select coalesce(p, '') in ('educacao', 'curadoria', 'mediacao', 'revisao', 'traducao', 'jornalismo', 'marketing', 'mentoria', 'design', 'desenvolvimento', 'saude',
                             'parcerias', 'influenciadores', 'representantes', 'rh', 'revolucionarios')
      or coalesce(p, '') ~ '^grupo-(percursos|linguagens|ciencias|tecnologia|humanidades|teoria|lutas|oficios|hobbies)$'
$$;

/** Quem é do departamento de fato (sem a coordenação e a supervisão, que entram em todos). Agora também pela participação. */
create or replace function interno.membro_direto(p_usuario uuid, p_departamento text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from papeis p join perfis f on f.id = p.usuario where p.usuario = p_usuario and not f.suspenso and (
    p.papel = p_departamento or (p.papel = 'representante' and p.disciplina = p_departamento)
    or (p_departamento = 'jornalismo' and p.papel = 'marketing') or (p_departamento = 'design' and p.papel = 'marketing')
    or (p_departamento = 'educacao' and p.papel = 'educacao_secundaria') or (p_departamento = 'coordenacao' and p.papel in ('coordenacao', 'vice'))
    -- Quem representa algum departamento é do departamento dos Representantes.
    or (p_departamento = 'representantes' and p.papel = 'representante')))
  or exists (select 1 from departamento_membros m join perfis f on f.id = m.usuario where m.usuario = p_usuario and m.departamento = p_departamento and not f.suspenso)
$$;

-- Os grupos de conversa dos departamentos novos. O install.sql já aceita estes ids nos grupos fixos (conversas_departamento_check).
alter table interno.conversas drop constraint if exists conversas_departamento_check;
alter table interno.conversas add constraint conversas_departamento_check check (departamento is null or departamento in
  ('geral', 'coordenacao', 'supervisao', 'curadoria', 'mediacao', 'educacao', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'desenvolvimento', 'marketing',
   'parcerias', 'influenciadores', 'representantes', 'rh', 'revolucionarios'));

/** Quem entra no grupo de conversa do departamento: as regras de antes, mais a participação e os Representantes. */
create or replace function interno.no_departamento(p_usuario uuid, p_departamento text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from papeis p join perfis f on f.id = p.usuario
                 where p.usuario = p_usuario and not f.suspenso
                   and ((p_departamento = 'geral' and p.papel <> 'saude') or p.papel in ('coordenacao', 'vice') or p.papel = p_departamento or (p.papel = 'representante' and p.disciplina = p_departamento)
                        -- Representante de um grupo de disciplinas (Tecnologia, Ciências…) é do departamento de educação.
                        or (p_departamento = 'educacao' and p.papel = 'representante' and p.disciplina like 'grupo-%')
                        -- A educação secundária conversa com a educação; o marketing, com o design (como no resto do painel).
                        or (p_departamento = 'educacao' and p.papel = 'educacao_secundaria') or (p_departamento = 'design' and p.papel = 'marketing')
                        -- O marketing faz parte do Departamento de Comunicação (o grupo "jornalismo", nome interno que não muda).
                        or (p_departamento = 'jornalismo' and p.papel = 'marketing')
                        or (p_departamento = 'jornalismo' and p.papel = 'representante' and p.disciplina = 'marketing')
                        -- Todo representante conversa no grupo dos Representantes.
                        or (p_departamento = 'representantes' and p.papel = 'representante')
                        -- A supervisão acompanha os grupos das funções para manter a conversa em ordem; o da coordenação e o dos
                        -- Revolucionários (dado sensível, LGPD art. 11), não.
                        or (p.papel = 'supervisao' and p_departamento not in ('coordenacao', 'revolucionarios'))))
  or exists (select 1 from departamento_membros m join perfis f on f.id = m.usuario where m.usuario = p_usuario and m.departamento = p_departamento and not f.suspenso)
$$;

insert into interno.conversas (tipo, nome, departamento) values
  ('departamento', 'Parcerias', 'parcerias'), ('departamento', 'Influenciadores', 'influenciadores'), ('departamento', 'Representantes', 'representantes'),
  ('departamento', 'RH · Recursos Humanos', 'rh'), ('departamento', 'Revolucionários', 'revolucionarios')
on conflict (departamento) do nothing;

-- Entrar ou sair de um departamento põe ou tira a pessoa do grupo de conversa dele (como já acontece com as funções).
drop trigger if exists lucia_departamentos on interno.departamento_membros;
create trigger lucia_departamentos after insert or update or delete on interno.departamento_membros for each row execute function interno.departamentos_gatilho();

-- Quem já representa algum departamento entra no grupo dos Representantes. Rodar de novo não muda nada.
do $$
declare u uuid;
begin
  for u in select distinct usuario from interno.papeis where papel in ('representante', 'supervisao', 'coordenacao', 'vice') loop
    perform interno.departamentos_sincronizar(u);
  end loop;
end $$;

-- 2. Confiar várias funções de uma vez ─────────────────────────────────────────────────────────────────────────
/**
 * Confia uma função (já conferido quem confia e a quem). As regras são as de sempre de public.papel_conceder: só papel de
 * nível menor que o de quem confia; educação, educação secundária e reforço exigem disciplina; o representante, um
 * departamento. Devolve true quando a função é nova para a pessoa.
 */
create or replace function interno.papel_conceder_um(p_usuario uuid, p_papel text, p_disciplina text) returns boolean
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_linhas integer;
begin
  if coalesce(p_papel, '') not in ('vice', 'supervisao', 'curadoria', 'mediacao', 'educacao', 'educacao_secundaria', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'marketing', 'desenvolvimento', 'representante', 'porta_voz', 'saude') then perform interno.erro('invalido:papel'); end if;
  if p_papel = 'representante' and not interno.departamento_valido(p_disciplina) then perform interno.erro('invalido:departamento'); end if;
  -- Representar os Revolucionários é saber quem são: só a coordenação nomeia (LGPD, art. 11).
  if p_papel = 'representante' and p_disciplina = 'revolucionarios' and not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if not interno.pode_conceder(p_papel) then perform interno.erro('sem_permissao'); end if;
  -- Educação, educação secundária e reforço são por disciplina: sem ela, a pessoa enxergaria a fila de todas.
  if p_papel in ('educacao', 'educacao_secundaria', 'mentoria') and coalesce(p_disciplina, '') = '' then perform interno.erro('invalido:disciplina'); end if;
  insert into papeis (usuario, papel, disciplina, concedido_por)
  values (p_usuario, p_papel, case when p_papel in ('vice', 'supervisao', 'marketing') then null else interno.disciplina_ok(p_disciplina) end, auth.uid()) on conflict do nothing;
  get diagnostics v_linhas = row_count;
  perform interno.registrar('papel_confiado', p_usuario::text, jsonb_build_object('papel', p_papel, 'disciplina', p_disciplina));
  return v_linhas > 0;
end $$;

/**
 * Confiar um papel (uma função). Mesmo comportamento de antes; agora também aceita representante dos departamentos novos.
 * Coordenação, vice-coordenação e supervisão confiam papéis de nível menor que o próprio (interno.pode_conceder), só a
 * quem está abaixo de si na hierarquia (interno.pode_mexer). Uma pessoa acumula quantos papéis forem confiados.
 */
create or replace function public.papel_conceder(p_usuario uuid, p_papel text, p_disciplina text) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.gere_cargos() then perform interno.erro('sem_permissao'); end if;
  if not exists (select 1 from perfis where id = p_usuario) then perform interno.erro('nao_encontrado'); end if;
  if not interno.pode_mexer(p_usuario) then perform interno.erro('sem_permissao'); end if;
  perform interno.papel_conceder_um(p_usuario, p_papel, p_disciplina);
  perform interno.avisar(p_usuario, 'Você recebeu um novo papel no instituto. Abra o painel para ver as ferramentas dele.');
  return jsonb_build_object('ok', true);
end $$;

/** Pôr a pessoa num departamento de participação (já conferido a quem). Devolve true quando é nova nele. */
create or replace function interno.departamento_membro_por(p_usuario uuid, p_departamento text) returns boolean
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_linhas integer;
begin
  if not (coalesce(p_departamento, '') = any(interno.departamentos_de_participacao())) then perform interno.erro('invalido:departamento'); end if;
  if p_departamento = 'revolucionarios' and not interno.coord() then perform interno.erro('sem_permissao'); end if;
  insert into departamento_membros (departamento, usuario, incluido_por) values (p_departamento, p_usuario, auth.uid()) on conflict do nothing;
  get diagnostics v_linhas = row_count;
  -- No registro, o departamento sensível não aparece pelo nome (quem lê o registro nem sempre é da coordenação).
  perform interno.registrar('departamento_incluido', p_usuario::text, jsonb_build_object('departamento', case when p_departamento = 'revolucionarios' then 'reservado' else p_departamento end));
  return v_linhas > 0;
end $$;

/**
 * Várias funções, várias disciplinas e vários departamentos para a mesma pessoa, numa ação só (T28). p_itens é uma lista
 * de {papel, disciplina}; p_departamentos, os departamentos de participação. Tudo ou nada: se uma função for recusada,
 * nenhuma entra (a tela diz qual). A pessoa recebe um recado só.
 */
create or replace function public.papeis_conceder_varios(p_usuario uuid, p_itens jsonb, p_departamentos text[] default '{}') returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare x jsonb; v_novas integer := 0; v_deps integer := 0; d text;
begin
  perform interno.eu();
  if not interno.gere_cargos() then perform interno.erro('sem_permissao'); end if;
  if jsonb_typeof(coalesce(p_itens, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_itens, '[]'::jsonb)) > 60 then perform interno.erro('invalido:itens'); end if;
  if cardinality(coalesce(p_departamentos, '{}')) > 20 then perform interno.erro('invalido:departamentos'); end if;
  if jsonb_array_length(coalesce(p_itens, '[]'::jsonb)) + cardinality(coalesce(p_departamentos, '{}')) = 0 then perform interno.erro('invalido:itens'); end if;
  if not exists (select 1 from perfis where id = p_usuario) then perform interno.erro('nao_encontrado'); end if;
  if not interno.pode_mexer(p_usuario) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('papeis_varios', 120, 60);
  for x in select * from jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) loop
    if jsonb_typeof(x) <> 'object' then perform interno.erro('invalido:itens'); end if;
    if interno.papel_conceder_um(p_usuario, x ->> 'papel', nullif(x ->> 'disciplina', '')) then v_novas := v_novas + 1; end if;
  end loop;
  foreach d in array coalesce(p_departamentos, '{}') loop
    if interno.departamento_membro_por(p_usuario, d) then v_deps := v_deps + 1; end if;
  end loop;
  if v_novas + v_deps > 0 then
    perform interno.avisar(p_usuario, format('Você recebeu %s no instituto. Abra o painel para ver as ferramentas e os grupos.',
      concat_ws(' e ', case when v_novas = 1 then 'uma função nova' when v_novas > 1 then v_novas || ' funções novas' end,
                       case when v_deps = 1 then 'um departamento' when v_deps > 1 then v_deps || ' departamentos' end)));
  end if;
  return jsonb_build_object('ok', true, 'novas', v_novas, 'departamentos', v_deps);
end $$;

/** Tirar a pessoa de um departamento de participação: a própria pessoa sai quando quiser; os outros, quem gere cargos. */
create or replace function public.departamento_membro_remover(p_departamento text, p_usuario uuid) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if p_usuario is distinct from v then
    if not interno.gere_cargos() or not interno.pode_mexer(p_usuario) then perform interno.erro('sem_permissao'); end if;
    if p_departamento = 'revolucionarios' and not interno.coord() then perform interno.erro('sem_permissao'); end if;
  end if;
  delete from departamento_membros where departamento = p_departamento and usuario = p_usuario;
  if not found then perform interno.erro('nao_encontrado'); end if;
  perform interno.registrar('departamento_retirado', p_usuario::text, jsonb_build_object('departamento', case when p_departamento = 'revolucionarios' then 'reservado' else p_departamento end));
  return jsonb_build_object('ok', true);
end $$;

/** A equipe para quem gere cargos: agora com os departamentos de participação de cada pessoa (Revolucionários, só para a coordenação). */
create or replace function public.voluntarios_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_coord boolean := interno.coord();
begin
  if not interno.gere_cargos() then perform interno.erro('sem_permissao'); end if;
  if interno.lider() then perform interno.registrar_acesso('emails_da_equipe'); end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', f.id, 'nome', interno.nome_visto(f.nome), 'bio', f.bio, 'email', case when interno.lider() then u.email else '' end, 'suspenso', f.suspenso, 'suspensao', f.suspensao, 'trocar_senha', f.trocar_senha,
      'criado_em', f.criado_em, 'visto_em', f.visto_em, 'nivel', interno.nivel_de(f.id),
      'papeis', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'papel', p.papel, 'disciplina', p.disciplina) order by interno.nivel(p.papel) desc, p.papel, p.disciplina) from papeis p where p.usuario = f.id), '[]'::jsonb),
      'departamentos', coalesce((select jsonb_agg(m.departamento order by m.departamento) from departamento_membros m where m.usuario = f.id and (v_coord or m.departamento <> 'revolucionarios')), '[]'::jsonb))
      order by f.nome), '[]'::jsonb)
    from perfis f join auth.users u on u.id = f.id);
end $$;

/** Tudo de um departamento. Igual a antes; nos Revolucionários, quem participa só aparece para a coordenação e para o próprio departamento. */
create or replace function public.departamento_ver(p_id text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare d departamentos_info; v_ve_pessoas boolean;
begin
  perform interno.eu();
  -- Quem só participa do departamento (sem função de trabalho, como um militante ou um coletivo parceiro) também abre o dele.
  if not (interno.voluntario() or ((interno.aal2() or not interno.tem_fator()) and interno.membro_direto(auth.uid(), p_id))) then perform interno.erro('sem_permissao'); end if;
  select * into d from departamentos_info where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  v_ve_pessoas := d.id <> 'revolucionarios' or interno.coord() or interno.membro_direto(auth.uid(), d.id);
  return jsonb_build_object(
    'id', d.id, 'descricao', d.descricao, 'como', d.como, 'meta_titulo', d.meta_titulo, 'meta_alvo', d.meta_alvo, 'meta_feito', d.meta_feito, 'atualizado_em', d.atualizado_em,
    'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id), 'reservado', not v_ve_pessoas,
    'pessoas', case when not v_ve_pessoas then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar,
                  'responde', exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id),
                  'ferias_ate', case when f.ferias_ate >= current_date then f.ferias_ate end,
                  'oficios', to_jsonb(f.oficios),
                  -- Desde quando a pessoa está neste departamento (para o rodízio: depois de um ano, ensinar alguém).
                  'desde', least((select min(p.criado_em) from papeis p where p.usuario = f.id and (p.papel = d.id or p.disciplina = d.id or (d.id = 'jornalismo' and p.papel = 'marketing')
                                   or (d.id = 'coordenacao' and p.papel in ('coordenacao', 'vice')) or (d.id = 'representantes' and p.papel = 'representante'))),
                                 (select m.criado_em from departamento_membros m where m.usuario = f.id and m.departamento = d.id)),
                  'papeis', (select jsonb_agg(jsonb_build_object('papel', p.papel, 'disciplina', p.disciplina)) from papeis p where p.usuario = f.id))
                  order by exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id) desc, f.nome), '[]'::jsonb)
                from perfis f where interno.membro_direto(f.id, d.id)) end,
    'recebidos', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.status = 'aberto' desc, x.prazo nulls last, x.criado_em desc), '[]'::jsonb)
                  from (select * from departamento_pedidos where para = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'enviados', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.criado_em desc), '[]'::jsonb)
                 from (select * from departamento_pedidos where de = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'quadro', (select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'titulo', q.titulo, 'etiqueta', q.etiqueta, 'coluna', q.coluna, 'prazo', q.prazo, 'pedido', q.pedido,
                 'dono', q.dono, 'dono_nome', coalesce((select interno.nome_visto(nome) from perfis where id = q.dono), ''), 'atualizado_em', q.atualizado_em)
                 order by q.coluna, q.prazo nulls last, q.atualizado_em desc), '[]'::jsonb)
               from departamento_quadro q where q.departamento = d.id and (q.coluna <> 'feito' or q.atualizado_em > now() - interval '14 days')),
    'feitos_no_mes', (select count(*) from departamento_quadro q where q.departamento = d.id and q.coluna = 'feito' and q.atualizado_em >= date_trunc('month', now())),
    'bastoes', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'texto', b.texto, 'criado_em', b.criado_em, 'meu', b.autor = auth.uid(),
                  'autor', coalesce((select interno.nome_visto(nome) from perfis where id = b.autor), '')) order by b.criado_em desc), '[]'::jsonb)
                from (select * from departamento_bastoes where departamento = d.id order by criado_em desc limit 20) b));
end $$;

/** A lista dos departamentos. Igual a antes; quem só participa de um departamento (sem função) vê só os seus. */
create or replace function public.departamentos_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_equipe boolean;
begin
  perform interno.eu();
  v_equipe := interno.voluntario();
  if not v_equipe and not ((interno.aal2() or not interno.tem_fator()) and exists (select 1 from departamento_membros where usuario = auth.uid())) then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'descricao', d.descricao,
            'pessoas', (select count(*) from perfis f where interno.membro_direto(f.id, d.id)),
            'pedidos', (select count(*) from departamento_pedidos p where p.para = d.id and p.status in ('aberto', 'aceito')),
            'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id)) order by d.id), '[]'::jsonb)
          from departamentos_info d where v_equipe or interno.membro_direto(auth.uid(), d.id));
end $$;


-- 3. Convites com várias funções e com departamentos ───────────────────────────────────────────────────────────
alter table interno.convites add column if not exists extras jsonb not null default '[]'::jsonb;
alter table interno.convites add column if not exists departamentos text[] not null default '{}';
alter table interno.convites drop constraint if exists convites_extras_check;
alter table interno.convites add constraint convites_extras_check check (jsonb_typeof(extras) = 'array' and jsonb_array_length(extras) <= 40 and cardinality(departamentos) <= 10);

/** Uma função que um convite pode trazer: valida e devolve a disciplina como fica guardada. */
create or replace function interno.convite_funcao_ok(p_papel text, p_disciplina text) returns text language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_disc text := interno.disciplina_ok(p_disciplina);
begin
  if coalesce(p_papel, '') not in ('vice', 'supervisao', 'curadoria', 'mediacao', 'educacao', 'educacao_secundaria', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'marketing', 'desenvolvimento', 'porta_voz', 'saude') then perform interno.erro('invalido:papel'); end if;
  if p_papel in ('vice', 'curadoria') and not interno.lider() then perform interno.erro('sem_permissao'); end if;
  -- O convite confia o papel na entrada: valem as regras de nível de papel_conceder.
  if not interno.pode_conceder(p_papel) then perform interno.erro('sem_permissao'); end if;
  if p_papel in ('educacao', 'educacao_secundaria', 'mentoria') and v_disc is null then perform interno.erro('invalido:disciplina'); end if;
  if p_papel not in ('educacao', 'educacao_secundaria', 'mentoria') then v_disc := null; end if;
  return v_disc;
end $$;

/**
 * A coordenação gera um convite e recebe o código uma única vez. Com e-mail, o convite é pessoal (um uso) e pode já trazer
 * uma ou mais funções (p.papel e p.extras: [{papel, disciplina}]) e departamentos de participação (p.departamentos). Sem
 * e-mail, é um convite da comunidade: vale para várias pessoas, sem função nenhuma.
 */
create or replace function public.convite_criar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_papel text := nullif(p ->> 'papel', '');
  v_disc text := nullif(p ->> 'disciplina', '');
  v_usos integer := coalesce(nullif(p ->> 'usos', '')::integer, 1);
  v_dias integer := coalesce(nullif(p ->> 'dias', '')::integer, 7);
  v_codigo text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_extras jsonb := '[]'::jsonb;
  v_deps text[] := '{}';
  v_nomes text[] := '{}';
  x jsonb; d text; v_id uuid;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('convite_criar', 60, 1440);
  if v_email <> '' and (v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or char_length(v_email) > 200) then perform interno.erro('invalido:email'); end if;
  if jsonb_typeof(coalesce(p -> 'extras', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p -> 'extras', '[]'::jsonb)) > 40 then perform interno.erro('invalido:extras'); end if;
  if jsonb_typeof(coalesce(p -> 'departamentos', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p -> 'departamentos', '[]'::jsonb)) > 10 then perform interno.erro('invalido:departamentos'); end if;
  -- Sem função principal, a primeira das extras passa a ser a principal (a que o convite antigo já sabia guardar).
  if v_papel is null and jsonb_array_length(coalesce(p -> 'extras', '[]'::jsonb)) > 0 then
    v_papel := nullif(p -> 'extras' -> 0 ->> 'papel', '');
    v_disc := nullif(p -> 'extras' -> 0 ->> 'disciplina', '');
  end if;
  if v_papel is not null then
    if v_email = '' then perform interno.erro('invalido:email'); end if;
    v_disc := interno.convite_funcao_ok(v_papel, v_disc);
    v_nomes := v_nomes || (interno.nome_papel(v_papel) || coalesce(' (' || v_disc || ')', ''));
    for x in select * from jsonb_array_elements(coalesce(p -> 'extras', '[]'::jsonb)) loop
      if jsonb_typeof(x) <> 'object' then perform interno.erro('invalido:extras'); end if;
      if x ->> 'papel' = v_papel and interno.disciplina_ok(nullif(x ->> 'disciplina', '')) is not distinct from v_disc then continue; end if;
      v_extras := v_extras || jsonb_build_array(jsonb_build_object('papel', x ->> 'papel', 'disciplina', interno.convite_funcao_ok(x ->> 'papel', nullif(x ->> 'disciplina', ''))));
      v_nomes := v_nomes || (interno.nome_papel(x ->> 'papel') || coalesce(' (' || nullif(x ->> 'disciplina', '') || ')', ''));
    end loop;
  else
    v_disc := null;
  end if;
  for d in select jsonb_array_elements_text(coalesce(p -> 'departamentos', '[]'::jsonb)) loop
    if v_email = '' then perform interno.erro('invalido:email'); end if;
    if not (d = any(interno.departamentos_de_participacao())) then perform interno.erro('invalido:departamento'); end if;
    if not (d = any(v_deps)) then v_deps := v_deps || d; end if;
  end loop;
  if v_email <> '' then v_usos := 1; end if;
  if v_usos not between 1 and 200 then perform interno.erro('invalido:usos'); end if;
  if v_dias not between 1 and 30 then perform interno.erro('invalido:dias'); end if;
  insert into convites (selo, email, papel, disciplina, usos_max, nota, criado_por, expira_em, extras, departamentos)
  values (interno.selo(v_codigo), v_email, v_papel, v_disc, v_usos, interno.txt(p ->> 'nota', 'nota', 0, 120), v, now() + make_interval(days => v_dias), v_extras, v_deps)
  returning id into v_id;
  perform interno.registrar('convite_criado', v_id::text, jsonb_build_object('papel', v_papel, 'usos', v_usos, 'extras', jsonb_array_length(v_extras), 'departamentos', cardinality(v_deps)));
  -- Convite pessoal vai sozinho para o e-mail da pessoa; o da comunidade (sem e-mail) a coordenação espalha como quiser.
  -- O e-mail diz as funções, nunca os departamentos (o dos Revolucionários é dado sensível e o e-mail passa por terceiros).
  if v_email <> '' then
    perform interno.email(v_email, 'convite', 'Seu convite para o Instituto Lúcia',
      E'Olá.\n\nA coordenação do Instituto Lúcia convidou você para criar uma conta'
      || case when cardinality(v_nomes) = 1 then ' e atuar na função de ' || v_nomes[1] when cardinality(v_nomes) > 1 then ' e atuar nas funções de ' || array_to_string(v_nomes, ', ') else '' end
      || E'.\n\nAbra o endereço abaixo. Ele é pessoal, só funciona com este e-mail e vale por ' || v_dias || E' dia(s):\n\n'
      || interno.endereco() || '/pt/entrar?convite=' || v_codigo || E'\n\nSe você não esperava este convite, é só ignorar esta mensagem.', '', 5);
  end if;
  return jsonb_build_object('id', v_id, 'codigo', v_codigo, 'email_enviado', v_email <> '');
end $$;

/**
 * Ao nascer a conta de um convite (public.lucia_conta_nova grava o uso e depois o perfil), as funções extras e os
 * departamentos do convite entram junto. Fica num gatilho próprio para não mexer na criação de conta.
 */
create or replace function interno.convite_extras_gatilho() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare c convites; x jsonb; d text;
begin
  select k.* into c from convites_usos u join convites k on k.id = u.convite where u.usuario = new.id;
  if not found then return null; end if;
  for x in select * from jsonb_array_elements(coalesce(c.extras, '[]'::jsonb)) loop
    insert into papeis (usuario, papel, disciplina, concedido_por) values (new.id, x ->> 'papel', nullif(x ->> 'disciplina', ''), c.criado_por) on conflict do nothing;
  end loop;
  foreach d in array coalesce(c.departamentos, '{}') loop
    insert into departamento_membros (departamento, usuario, incluido_por) values (d, new.id, c.criado_por) on conflict do nothing;
  end loop;
  return null;
end $$;
drop trigger if exists lucia_convite_extras on interno.perfis;
create trigger lucia_convite_extras after insert on interno.perfis for each row execute function interno.convite_extras_gatilho();

/** A lista de convites, organizada: a situação de cada um, as funções extras, os departamentos e quem usou. */
create or replace function public.convites_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'email', c.email, 'papel', c.papel, 'disciplina', c.disciplina, 'usos', c.usos,
            'usos_max', c.usos_max, 'nota', c.nota, 'criado_em', c.criado_em, 'expira_em', c.expira_em, 'de', coalesce(f.nome, ''),
            'valido', not c.revogado and c.expira_em > now() and c.usos < c.usos_max, 'revogado', c.revogado,
            'situacao', case when c.usos >= c.usos_max then 'usado' when c.revogado then 'cancelado' when c.expira_em <= now() then 'vencido' else 'valendo' end,
            'extras', c.extras, 'departamentos', to_jsonb(c.departamentos),
            'usado_por', coalesce((select jsonb_agg(interno.nome_visto(p.nome) order by u.criado_em) from convites_usos u join perfis p on p.id = u.usuario where u.convite = c.id), '[]'::jsonb))
            order by c.criado_em desc), '[]'::jsonb)
          from (select * from convites order by criado_em desc limit 300) c left join perfis f on f.id = c.criado_por);
end $$;

-- 4. Trocar o e-mail de uma conta ──────────────────────────────────────────────────────────────────────────────
/** O e-mail com o meio escondido (j***@gmail.com), para o registro e para os avisos. */
create or replace function interno.email_mascarado(p text) returns text language sql immutable as $$
  select case when position('@' in coalesce(p, '')) > 1 then left(p, 1) || '***' || substr(p, position('@' in p)) else '***' end
$$;

/**
 * A coordenação comunitária troca o e-mail de uma conta, a pedido da pessoa (T29). Regras:
 *  - só a coordenação comunitária (é quem vê os e-mails da equipe), com o segundo fator quando exigido, nunca a própria
 *    conta nem a de outra coordenação (interno.ao_alcance), no máximo 10 trocas por dia;
 *  - o e-mail novo não pode ser de outra conta; o motivo é obrigatório e vai para o registro;
 *  - o registro guarda o e-mail mascarado, nunca o endereço inteiro (quem lê o registro não precisa dele);
 *  - o endereço antigo e o novo recebem um aviso por e-mail (o antigo fica sabendo, se não foi a pessoa que pediu);
 *  - a pessoa recebe também um recado no painel. A senha e as sessões não mudam.
 * É feito no banco, como a redefinição de senha (public.usuario_senha_redefinir), e não pela API administrativa do serviço:
 * a chave de serviço não fica no servidor do site. O e-mail é dado pessoal (LGPD, art. 6º, III e VII: o mínimo e com segurança).
 */
create or replace function public.usuario_email_trocar(p_usuario uuid, p_email text, p_motivo text) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_novo text := lower(btrim(coalesce(p_email, ''))); v_antigo text; v_motivo text := btrim(coalesce(p_motivo, '')); v_nome text;
begin
  perform interno.eu();
  if not interno.lider() then perform interno.erro('sem_permissao'); end if;
  perform interno.ao_alcance(p_usuario);
  if exists (select 1 from papeis where usuario = p_usuario and papel = 'coordenacao') then perform interno.erro('sem_permissao'); end if;
  if v_novo !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or char_length(v_novo) > 200 then perform interno.erro('invalido:email'); end if;
  if char_length(v_motivo) < 5 or char_length(v_motivo) > 300 then perform interno.erro('invalido:motivo'); end if;
  perform interno.limite('email_trocar', 10, 1440);
  select lower(email) into v_antigo from auth.users where id = p_usuario;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if v_antigo = v_novo then perform interno.erro('email_igual'); end if;
  if exists (select 1 from auth.users where lower(email) = v_novo and id <> p_usuario) then perform interno.erro('email_em_uso'); end if;
  update auth.users set email = v_novo where id = p_usuario;
  -- Um pedido de troca que a pessoa tenha começado sozinha (e não confirmou) deixa de valer. As colunas existem no serviço real.
  begin
    execute 'update auth.users set email_change = '''', email_change_token_new = '''', email_change_token_current = '''', email_change_confirm_status = 0 where id = $1' using p_usuario;
  exception when others then null;
  end;
  begin
    if to_regclass('auth.identities') is not null then
      execute 'update auth.identities set identity_data = jsonb_set(coalesce(identity_data, ''{}''::jsonb), ''{email}'', to_jsonb($2::text)), updated_at = now() where user_id = $1 and provider = ''email'''
        using p_usuario, v_novo;
    end if;
  exception when others then null;
  end;
  select interno.nome_visto(nome) into v_nome from perfis where id = p_usuario;
  perform interno.registrar('email_trocado', p_usuario::text, jsonb_build_object('de', interno.email_mascarado(v_antigo), 'para', interno.email_mascarado(v_novo), 'motivo', left(v_motivo, 300)));
  perform interno.avisar_em(p_usuario, format('A coordenação trocou o e-mail da sua conta para %s. A senha continua a mesma. Se não foi você que pediu, fale com a coordenação.', interno.email_mascarado(v_novo)), 'conta');
  if v_antigo is not null and v_antigo <> '' then
    perform interno.email(v_antigo, 'conta_email', 'O e-mail da sua conta no Instituto Lúcia mudou',
      E'Olá.\n\nA pedido, a coordenação do Instituto Lúcia trocou o e-mail da sua conta para ' || interno.email_mascarado(v_novo)
      || E'. A partir de agora, entre com o endereço novo; a senha continua a mesma.\n\nSe não foi você que pediu, responda a coordenação por outro canal o quanto antes.', '', 5);
  end if;
  perform interno.email(v_novo, 'conta_email', 'Este é o novo e-mail da sua conta no Instituto Lúcia',
    E'Olá' || coalesce(', ' || v_nome, '') || E'.\n\nA coordenação do Instituto Lúcia pôs este endereço na sua conta. A partir de agora, entre no painel com ele; a senha continua a mesma.\n\n'
    || interno.endereco() || E'/pt/entrar\n\nSe você não conhece o Instituto Lúcia, ignore esta mensagem e, se quiser, avise a coordenação.', '', 5);
  return jsonb_build_object('ok', true, 'email', v_novo);
end $$;

-- Permissões: as funções novas da API, só pela API; as internas, ninguém de fora chama.
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('papel_conceder', 'papeis_conceder_varios', 'departamento_membro_remover', 'voluntarios_listar', 'departamento_ver', 'departamentos_resumo',
             'convite_criar', 'convites_listar', 'usuario_email_trocar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;
revoke all on function interno.departamentos_de_participacao() from public, anon, authenticated;
revoke all on function interno.departamento_valido(text) from public, anon, authenticated;
revoke all on function interno.papel_conceder_um(uuid, text, text) from public, anon, authenticated;
revoke all on function interno.departamento_membro_por(uuid, text) from public, anon, authenticated;
revoke all on function interno.convite_funcao_ok(text, text) from public, anon, authenticated;
revoke all on function interno.convite_extras_gatilho() from public, anon, authenticated;
revoke all on function interno.email_mascarado(text) from public, anon, authenticated;

-- ───────────────────────── Podcast ao vivo (T17, 06/11/2026) ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Rode depois do install.sql (usa
-- interno.podcaster(), interno.eu(), interno.limite() e interno.erro() de lá). Explicação: docs/PODCAST-AO-VIVO.md.
--
-- Quem faz o podcast (interno.podcaster(): coordenação, comunicação/jornalismo e quem tem função no podcast) pode pôr no ar
-- uma transmissão com vídeo que todo mundo vê na página /podcasts. Uma transmissão por vez, numa linha só.
--
-- O que fica guardado, e só enquanto está no ar: título, modo, endereço da transmissão aberta (se houver), a sala sorteada
-- do WebRTC, a chave pública da aba de quem transmite e quem começou (para só essa pessoa ou a coordenação encerrar).
-- Ao encerrar, a sala, a chave e o endereço são apagados. Nada de quem assiste é guardado, e o site não grava a
-- transmissão (LGPD, Lei 13.709/2018, art. 6º, III: necessidade).
--
-- Consentimento de imagem e voz: começar exige confirmar que todas as pessoas que aparecem ou falam concordaram, e que
-- ninguém menor de 18 anos aparece sem autorização de quem responde por ela (LGPD, art. 7º, I, e art. 14; ECA,
-- Lei 8.069/1990, art. 17). O banco guarda só a hora dessa confirmação, como registro de que ela foi feita.

create table if not exists interno.podcast_ao_vivo (
  id boolean primary key default true check (id),
  no_ar boolean not null default false,
  titulo text not null default '',
  modo text not null default 'navegador' check (modo in ('navegador', 'link')),
  endereco text not null default '',
  sala uuid,
  chave_publica text not null default '',
  iniciado_por uuid references interno.perfis (id) on delete set null,
  iniciado_em timestamptz,
  consentimento_em timestamptz,
  visto_em timestamptz
);
alter table interno.podcast_ao_vivo enable row level security;
revoke all on interno.podcast_ao_vivo from public, anon, authenticated;
insert into interno.podcast_ao_vivo (id) values (true) on conflict do nothing;

/**
 * Está no ar? Pelo navegador, só enquanto quem transmite dá sinal de vida (podcast_ao_vivo_pulso, a cada minuto; três
 * minutos sem sinal = encerrada); por link, até 12 horas depois de começar (esqueceram de encerrar).
 */
create or replace function interno.podcast_ao_vivo_no_ar(r interno.podcast_ao_vivo) returns boolean language sql stable set search_path = interno, pg_temp as $$
  select r.no_ar and case when r.modo = 'navegador' then coalesce(r.visto_em, r.iniciado_em) > now() - interval '3 minutes'
                          else r.iniciado_em > now() - interval '12 hours' end
$$;

/** O que a página do podcast mostra. Sem dizer quem começou; "pode" e "minha" só dizem respeito a quem pergunta. */
create or replace function public.podcast_ao_vivo_estado() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select case when interno.podcast_ao_vivo_no_ar(r) then
           jsonb_build_object('no_ar', true, 'titulo', r.titulo, 'modo', r.modo, 'endereco', r.endereco, 'sala', r.sala,
             'chaves', case when r.chave_publica = '' then '[]'::jsonb else jsonb_build_array(r.chave_publica) end,
             'desde', r.iniciado_em, 'pode', interno.podcaster(), 'minha', auth.uid() is not null and r.iniciado_por = auth.uid())
         else jsonb_build_object('no_ar', false, 'pode', interno.podcaster()) end
  from podcast_ao_vivo r where r.id
$$;

/** Começa (ou recomeça, para quem já transmitia) a transmissão. */
create or replace function public.podcast_ao_vivo_iniciar(p_titulo text, p_modo text, p_endereco text, p_consentimento boolean) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r podcast_ao_vivo; v_sala uuid := gen_random_uuid(); v_endereco text := btrim(coalesce(p_endereco, ''));
begin
  if not interno.podcaster() then perform interno.erro('sem_permissao'); end if;
  if p_consentimento is not true then perform interno.erro('consentimento'); end if;
  if p_modo not in ('navegador', 'link') then perform interno.erro('invalido:modo'); end if;
  if v_endereco <> '' and (length(v_endereco) > 500 or v_endereco !~ '^https://[^\s/@]+(/\S*)?$') then perform interno.erro('invalido:endereco'); end if;
  if p_modo = 'link' and v_endereco = '' then perform interno.erro('invalido:endereco'); end if;
  perform interno.limite('podcast_ao_vivo', 30, 1440);
  select * into r from podcast_ao_vivo where id for update;
  -- Uma transmissão por vez: outra pessoa só toma o lugar quando a de agora já caiu (ou pela coordenação).
  if interno.podcast_ao_vivo_no_ar(r) and r.iniciado_por is distinct from v and not interno.coord() then perform interno.erro('ocupado'); end if;
  update podcast_ao_vivo set no_ar = true, titulo = left(btrim(coalesce(p_titulo, '')), 120), modo = p_modo, endereco = v_endereco,
    sala = v_sala, chave_publica = '', iniciado_por = v, iniciado_em = now(), consentimento_em = now(), visto_em = now()
  where id;
  return jsonb_build_object('ok', true, 'sala', v_sala);
end $$;

/** A chave pública da aba de quem transmite pelo navegador (quem assiste só aceita vídeo assinado por ela). */
create or replace function public.podcast_ao_vivo_chave(p_sala uuid, p_publica text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if coalesce(p_publica, '') !~ '^B[A-Za-z0-9_-]{86}$' then perform interno.erro('invalido:publica'); end if;
  perform interno.limite('podcast_ao_vivo_chave', 60, 60);
  update podcast_ao_vivo set chave_publica = p_publica, visto_em = now() where id and no_ar and sala = p_sala and iniciado_por = v and interno.podcaster();
  if not found then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('ok', true);
end $$;

/** Sinal de vida de quem transmite pelo navegador (a cada minuto). */
create or replace function public.podcast_ao_vivo_pulso(p_sala uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  update podcast_ao_vivo set visto_em = now() where id and no_ar and sala = p_sala and iniciado_por = v and interno.podcaster();
  return jsonb_build_object('ok', found);
end $$;

/** Encerra: quem começou ou a coordenação. Apaga a sala, a chave e o endereço. */
create or replace function public.podcast_ao_vivo_encerrar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.podcaster() then perform interno.erro('sem_permissao'); end if;
  update podcast_ao_vivo set no_ar = false, sala = null, chave_publica = '', endereco = '', visto_em = null
  where id and (iniciado_por = v or interno.coord() or not interno.podcast_ao_vivo_no_ar(podcast_ao_vivo));
  if not found then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('ok', true);
end $$;

revoke all on function interno.podcast_ao_vivo_no_ar(interno.podcast_ao_vivo) from public, anon, authenticated;
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('podcast_ao_vivo_estado', 'podcast_ao_vivo_iniciar', 'podcast_ao_vivo_chave', 'podcast_ao_vivo_pulso', 'podcast_ao_vivo_encerrar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- T18 (Alumia): a primeira entrada fica curta. O essencial continua obrigatório e gravado como antes, em rede_aderir:
-- consentimento destacado para dado sensível (LGPD, art. 11, I, com a versão das regras), a declaração de 18 anos ou mais
-- (LGPD, art. 14; ECA Digital, Lei 15.211/2025) e o codinome. As 3 lutas + 3 trilhas e o guia de segurança passam a ser
-- OPCIONAIS: a pessoa pode deixar para depois (Explorar) e entra na Alumia na hora.
--
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Roda DEPOIS de 2026-11-rede-descoberta.sql.
-- O mesmo bloco está no fim do install.sql.

alter table interno.rede_desc_entrada add column if not exists escolhas_adiadas_em timestamptz;

/**
 * Em que passo a pessoa está: entrar (sem conta), regras (consentimento, 18+ e regras: tudo isso grava em rede_aderir),
 * codinome, escolhas (opcional: some quando a pessoa escolhe ou deixa para depois), guia (opcional) ou pronto.
 */
create or replace function public.rede_desc_entrada_estado() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); f perfis; e rede_desc_entrada; v_passo text; v_regras integer := coalesce((select max(versao) from rede_regras), 1);
begin
  if v is null then return jsonb_build_object('passo', 'entrar', 'regras_versao', v_regras); end if;
  select * into f from perfis where id = v;
  if not found then return jsonb_build_object('passo', 'entrar', 'regras_versao', v_regras); end if;
  select * into e from rede_desc_entrada where usuario = v;
  v_passo := case
    when f.suspenso then 'suspensa'
    when not interno.rede2_membro(v) then 'regras'
    when not (f.rede_codinome_ok and f.rede_codinome is not null) then 'codinome'
    when e.escolhas_adiadas_em is not null then 'pronto'
    when e.escolhas_em is null then 'escolhas'
    when e.guia_em is null and not coalesce(e.guia_pulado, false) then 'guia'
    else 'pronto' end;
  return jsonb_build_object(
    'passo', v_passo, 'regras_versao', v_regras, 'codinome', f.rede_codinome,
    'escolhas', e.escolhas_em is not null, 'guia', e.guia_em is not null or coalesce(e.guia_pulado, false),
    'adiou', e.escolhas_adiadas_em is not null,
    'aparece', coalesce(e.aparece, false),
    'lutas', (select coalesce(jsonb_agg(i.chave order by i.chave), '[]'::jsonb) from rede_desc_interesses i where i.usuario = v and i.tipo = 'luta'),
    'trilhas', (select coalesce(jsonb_agg(i.chave order by i.chave), '[]'::jsonb) from rede_desc_interesses i where i.usuario = v and i.tipo = 'trilha'));
end $$;

/**
 * "Agora não": as escolhas (lutas e trilhas) e o guia ficam para depois. Só quem já entrou na Alumia (consentimento, 18+ e
 * codinome continuam obrigatórios). Não apaga escolha nenhuma; a pessoa escolhe quando quiser em Explorar.
 */
create or replace function public.rede_desc_entrada_adiar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  insert into rede_desc_entrada (usuario, escolhas_adiadas_em, guia_pulado) values (v, now(), true)
    on conflict (usuario) do update set escolhas_adiadas_em = coalesce(rede_desc_entrada.escolhas_adiadas_em, now()),
                                        guia_pulado = rede_desc_entrada.guia_em is null or coalesce(rede_desc_entrada.guia_pulado, false);
  return public.rede_desc_entrada_estado();
end $$;

revoke all on function public.rede_desc_entrada_adiar() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.rede_desc_entrada_adiar() from anon;
    grant execute on function public.rede_desc_entrada_estado() to anon, authenticated, service_role;
    grant execute on function public.rede_desc_entrada_adiar() to authenticated, service_role;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- T32 (Alumia), itens 2b e 3: a vitrine das comunidades e o painel da semeadura.
--
-- Vitrine (rede_com_lista, redefinida): cada comunidade traz agora só contagens AGREGADAS e anônimas da última semana: quantos
-- posts e quantas pessoas escreveram ali nos últimos 7 dias. Nunca nome, nunca lista de quem é membro. Pessoas só aparecem a
-- partir de 3 (abaixo disso volta nulo, "poucas"), para que um número pequeno não aponte alguém numa comunidade de luta, que
-- pode revelar opinião política (dado sensível, LGPD, art. 5º, II e art. 11; minimização, art. 6º, III). Quem visita sem conta
-- passa a ver também uma AMOSTRA das lutas e do Instituto: só nome, descrição e regras (sem posts, sem contagens), para conhecer
-- antes de entrar. A ordem é pública e escrita na tela: mais posts na semana primeiro, depois a ordem alfabética.
--
-- Semeadura (rede_painel_semeadura, nova): para a coordenação, por comunidade, quantos posts reais existem (no total e na
-- semana) e quantas pessoas moderam (a meta do docs/rede/SEMEAR.md é 2). Só números; nenhum script publica nada.
--
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Roda DEPOIS de 2026-11-rede-comunidades.sql.
-- O mesmo bloco está no fim do install.sql.

create or replace function public.rede_com_lista() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  perform interno.aberta('comunidade');
  return jsonb_build_object('regra', 'atividade_7d', 'itens', (
    select coalesce(jsonb_agg(jsonb_build_object(
      'slug', x.slug, 'nome', x.nome, 'descricao', x.descricao, 'categoria', x.categoria, 'tipo', x.tipo, 'icone', x.icone, 'cor', x.cor,
      'situacao', interno.rede3_com_situacao(x.slug, v),
      'amostra', x.amostra,
      'posts_7d', case when x.amostra then null else x.posts end,
      'pessoas_7d', case when x.amostra or x.pessoas < 3 then null else x.pessoas end,
      'regras', case when x.amostra then (select coalesce(jsonb_agg(jsonb_build_object('numero', r.numero, 'titulo', r.titulo, 'texto', r.texto) order by r.numero), '[]'::jsonb)
                                          from rede_comunidade_regras r where r.comunidade = x.slug) end)
      order by case x.categoria when 'lutas' then 1 when 'disciplinas' then 2 else 3 end, x.posts desc, x.nome), '[]'::jsonb)
    from (
      select c.*, (v is null and c.categoria <> 'disciplinas') as amostra,
        (select count(*)::integer from rede_posts p where p.comunidade = c.slug and p.criado_em > now() - interval '7 days' and not p.oculto and not p.retido) as posts,
        (select count(distinct p.autor)::integer from rede_posts p where p.comunidade = c.slug and p.criado_em > now() - interval '7 days' and not p.oculto and not p.retido) as pessoas
      from rede_comunidades c
      where c.slug not like 'fechado-%'
        and (c.tipo <> 'fechada' or interno.rede2_na_comunidade(c.slug, v))
        -- Visitante: as disciplinas, inteiras; das lutas e do Instituto, só a amostra das abertas e restritas (nunca a fechada).
        and (v is not null or c.categoria = 'disciplinas' or c.tipo in ('aberta', 'restrita'))) x));
end $$;

/** O roteiro da semeadura em números, para a coordenação: posts reais por comunidade e se há 2 pessoas moderando. */
create or replace function public.rede_painel_semeadura() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object('itens', (
    select coalesce(jsonb_agg(jsonb_build_object(
      'slug', c.slug, 'nome', c.nome, 'categoria', c.categoria, 'tipo', c.tipo,
      'posts', (select count(*)::integer from rede_posts p where p.comunidade = c.slug and not p.oculto and not p.retido),
      'posts_7d', (select count(*)::integer from rede_posts p where p.comunidade = c.slug and not p.oculto and not p.retido and p.criado_em > now() - interval '7 days'),
      'moderacao', (select count(*)::integer from rede_comunidade_membros m where m.comunidade = c.slug and m.papel = 'moderacao' and m.situacao = 'ativo'))
      order by case c.categoria when 'lutas' then 1 when 'instituto' then 2 else 3 end, c.nome), '[]'::jsonb)
    from rede_comunidades c where c.slug not like 'fechado-%'));
end $$;

revoke all on function public.rede_painel_semeadura() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.rede_painel_semeadura() from anon;
    grant execute on function public.rede_com_lista() to anon, authenticated, service_role;
    grant execute on function public.rede_painel_semeadura() to authenticated, service_role;
  end if;
end $$;

-- ───────────────────────────── Alumia: chat privado cifrado de ponta a ponta (T19) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. O mesmo bloco está no fim do install.sql. Roda
-- DEPOIS das migrações da Rede v2 (2026-11-rede-*.sql) e da Alumia (2026-11-alumia.sql). Documento: docs/rede/CHAT-PRIVADO.md.
--
-- A mesma tecnologia das conversas da equipe (lib/sigilo.ts): cada pessoa tem uma chave de aparelho ECDH P-256 (privada não
-- exportável, só no navegador) certificada por uma identidade ECDSA P-256; cada conversa tem uma chave AES-GCM-256, embrulhada
-- (ECDH + HKDF-SHA-256 + AES-GCM) para a chave de cada participante; cada mensagem vai cifrada e assinada no aparelho. O banco
-- guarda só a parte pública das chaves, os embrulhos e o texto cifrado, e RECUSA texto aberto (check no formato "c2.").
--
-- Regras, todas conferidas aqui no servidor (o aparelho confere de novo o que é de cifra):
--   1. Só entre membros da Alumia (18+, consentimento em vigor, conta não suspensa: interno.rede2_membro). LGPD art. 14 e ECA:
--      a Alumia não tem menores; o chat privado também não.
--   2. Quem não segue não entra direto: se a outra pessoa não segue você, vira PEDIDO de conversa (só "fulana quer conversar",
--      sem mensagem) e só depois de aceito alguém escreve. Cada pessoa escolhe: aceitar pedidos (padrão), só de quem eu sigo, ou
--      ninguém. Perfil invisível não recebe pedido. Pedido recusado não se repete por 30 dias.
--   3. Bloqueio (interno.rede_bloqueios, o mesmo da Alumia) corta tudo: não pede, não envia, não lê a chave.
--   4. Denúncia com os trechos que a própria pessoa escolhe e decifra no aparelho dela (a moderação nunca tem a chave), na mesma
--      fila de denúncias da Alumia (alvo: o perfil).
--   5. Limite de envio por pessoa (interno.limite), metade para conta nova.
--   6. Nada de conteúdo, nem de "quem fala com quem", no registro de atividades (interno.registrar não é chamado aqui).
--   7. Retenção mínima: cada mensagem nasce com prazo (1, 7 ou 30 dias; padrão 7) e some sozinha; pedido sem resposta some em
--      30 dias; a faxina (interno.rede_dm_faxina) roda junto das próprias chamadas e as leituras já filtram o que venceu.
--   8. Apagar: a mensagem (quem escreveu), a conversa (qualquer participante; some para os dois), tudo do chat (a pessoa) e a
--      conta (chave estrangeira com on delete cascade): LGPD art. 18, VI.
--   9. Nada federado: as tabelas rede_dm_* não aparecem em nenhuma função do Fediverso (conferido em scripts/testar-rede-chat.mjs).
--  10. RLS ligada sem política nenhuma e nenhum privilégio direto: ninguém lê tabela, só as funções abaixo (que conferem que quem
--      chama é participante).
-- Leis conferidas em 06/11/2026: LGPD (13.709/2018) arts. 6º (finalidade, necessidade, segurança, prevenção), 7º, 11, 14, 18 e
-- 46; Marco Civil (12.965/2014) arts. 7º (sigilo das comunicações privadas), 10 e 19; ECA (8.069/1990) art. 241-D.

-- ── 1. Tabelas ──────────────────────────────────────────────────────────────────────────────────────────────────────────

-- A chave de cada pessoa no chat (uma por conta: o aparelho em que o chat foi ativado). Só a parte pública.
create table if not exists interno.rede_dm_chaves (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  identidade text not null check (identidade ~ '^B[A-Za-z0-9_-]{86}$'),
  publica text not null check (publica ~ '^B[A-Za-z0-9_-]{86}$'),
  certificado text not null check (certificado ~ '^[A-Za-z0-9_-]{86}$'),
  versao integer not null default 1 check (versao > 0),
  criado_em timestamptz not null default now(),
  trocada_em timestamptz not null default now()
);

-- Quem pode me chamar e o prazo padrão das minhas conversas novas.
create table if not exists interno.rede_dm_prefs (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  quem_pode text not null default 'pedidos' check (quem_pode in ('pedidos', 'seguidos', 'ninguem')),
  prazo_dias smallint not null default 7 check (prazo_dias in (1, 7, 30))
);

-- Uma conversa por par de pessoas (a < b). "pedido": só quem pediu e quem recebeu sabem; ninguém escreve até ser aceito.
create table if not exists interno.rede_dm_conversas (
  id uuid primary key default gen_random_uuid(),
  a uuid not null references interno.perfis (id) on delete cascade,
  b uuid not null references interno.perfis (id) on delete cascade,
  situacao text not null default 'pedido' check (situacao in ('pedido', 'aberta')),
  pediu uuid not null references interno.perfis (id) on delete cascade,
  versao integer not null default 0 check (versao >= 0),
  versao_em timestamptz,
  prazo_dias smallint not null default 7 check (prazo_dias in (1, 7, 30)),
  a_leu_em timestamptz,
  b_leu_em timestamptz,
  ultima_em timestamptz not null default now(),
  criado_em timestamptz not null default now(),
  unique (a, b),
  check (a < b),
  check (pediu = a or pediu = b)
);

-- A chave de cada versão da conversa, embrulhada para a chave de cada participante (para = usuario; chave_versao = a versão
-- da chave dele quando foi embrulhada). de_publica e de_certificado: a chave de quem embrulhou, para o outro conferir.
create table if not exists interno.rede_dm_embrulhos (
  conversa uuid not null references interno.rede_dm_conversas (id) on delete cascade,
  versao integer not null check (versao > 0),
  para uuid not null references interno.perfis (id) on delete cascade,
  chave_versao integer not null check (chave_versao > 0),
  embrulho text not null check (embrulho ~ '^w1\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{64}$'),
  de uuid not null references interno.perfis (id) on delete cascade,
  de_publica text not null check (de_publica ~ '^B[A-Za-z0-9_-]{86}$'),
  de_certificado text not null check (de_certificado ~ '^[A-Za-z0-9_-]{86}$'),
  criado_em timestamptz not null default now(),
  primary key (conversa, versao, para)
);

-- As mensagens: só o cifrado. O check recusa qualquer coisa fora do formato "c2.<versão>.<vetor>.<cifrado>".
create table if not exists interno.rede_dm_mensagens (
  id uuid primary key default gen_random_uuid(),
  conversa uuid not null references interno.rede_dm_conversas (id) on delete cascade,
  autor uuid not null references interno.perfis (id) on delete cascade,
  versao integer not null check (versao > 0),
  corpo text not null check (char_length(corpo) <= 12000 and corpo ~ '^c2\.[1-9][0-9]{0,6}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{23,}$'),
  criado_em timestamptz not null default now(),
  expira_em timestamptz not null
);
create index if not exists rede_dm_mensagens_conversa on interno.rede_dm_mensagens (conversa, criado_em desc);
create index if not exists rede_dm_mensagens_expira on interno.rede_dm_mensagens (expira_em);

-- Pedido recusado: quem recusou não recebe outro pedido da mesma pessoa até `ate`. Só isso; some depois do prazo.
create table if not exists interno.rede_dm_recusas (
  quem uuid not null references interno.perfis (id) on delete cascade,
  de uuid not null references interno.perfis (id) on delete cascade,
  ate timestamptz not null,
  primary key (quem, de)
);

alter table interno.rede_dm_chaves enable row level security;
alter table interno.rede_dm_prefs enable row level security;
alter table interno.rede_dm_conversas enable row level security;
alter table interno.rede_dm_embrulhos enable row level security;
alter table interno.rede_dm_mensagens enable row level security;
alter table interno.rede_dm_recusas enable row level security;
revoke all on interno.rede_dm_chaves, interno.rede_dm_prefs, interno.rede_dm_conversas, interno.rede_dm_embrulhos, interno.rede_dm_mensagens,
  interno.rede_dm_recusas from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on interno.rede_dm_chaves, interno.rede_dm_prefs, interno.rede_dm_conversas, interno.rede_dm_embrulhos, interno.rede_dm_mensagens,
      interno.rede_dm_recusas from anon, authenticated;
  end if;
end $$;

-- ── 2. Auxiliares internos ──────────────────────────────────────────────────────────────────────────────────────────────

/** A faxina do chat: mensagens vencidas, pedidos sem resposta há 30 dias, recusas vencidas. Roda junto das chamadas. */
create or replace function interno.rede_dm_faxina() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_dm_mensagens where expira_em <= now();
  delete from rede_dm_conversas where situacao = 'pedido' and criado_em < now() - interval '30 days';
  delete from rede_dm_recusas where ate <= now();
  -- Embrulhos de versões antigas, sem nenhuma mensagem viva que precise deles (a versão atual fica sempre).
  delete from rede_dm_embrulhos e using rede_dm_conversas c
  where c.id = e.conversa and e.versao < c.versao
    and not exists (select 1 from rede_dm_mensagens m where m.conversa = e.conversa and m.versao = e.versao);
end $$;

/** De vez em quando (2% das chamadas), a faxina. */
create or replace function interno.rede_dm_talvez_faxina() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if random() < 0.02 then perform interno.rede_dm_faxina(); end if;
end $$;

/** A conversa, se quem chama participa dela. Senão, "não encontrada" (o mesmo erro para quem não participa e para o que não existe). */
create or replace function interno.rede_dm_minha(p_conversa uuid, p_eu uuid) returns interno.rede_dm_conversas language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare c rede_dm_conversas;
begin
  select * into c from rede_dm_conversas where id = p_conversa and (a = p_eu or b = p_eu);
  if not found then perform interno.erro('nao_encontrado'); end if;
  return c;
end $$;

/** O outro participante. */
create or replace function interno.rede_dm_outro(c interno.rede_dm_conversas, p_eu uuid) returns uuid language sql immutable as $$
  select case when c.a = p_eu then c.b else c.a end
$$;

/** Limites do chat, por pessoa. Conta nova (menos de 3 dias) tem metade. */
create or replace function interno.rede_dm_limite(p_acao text) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_teto integer; v_minutos integer := 60;
  v_nova boolean := exists (select 1 from auth.users u where u.id = auth.uid() and u.created_at > now() - interval '3 days');
begin
  v_teto := case p_acao when 'enviar' then 120 when 'pedir' then 20 when 'ler' then 1200 when 'chave' then 10 when 'denunciar' then 10 when 'apagar' then 200 else null end;
  if v_teto is null then perform interno.erro('acao_desconhecida'); end if;
  if p_acao in ('pedir', 'chave', 'denunciar') then v_minutos := 1440; end if;
  if v_nova and p_acao <> 'ler' then v_teto := greatest(1, v_teto / 2); end if;
  perform interno.limite('rede_dm_' || p_acao, v_teto, v_minutos);
end $$;

/** A pessoa como o chat a mostra: só codinome, @handle e rosto (nunca nome do painel nem e-mail). */
create or replace function interno.rede_dm_pessoa(p_id uuid, p_quem uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', f.id, 'codinome', interno.rede_nome(f.id), 'handle', f.rede_handle, 'avatar', interno.rede3_perfil_imagem(f, 'avatar', p_quem))
  from perfis f where f.id = p_id
$$;

/** Uma conversa como quem chama a vê. */
create or replace function interno.rede_dm_json(c interno.rede_dm_conversas, p_eu uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', c.id,
    'com', interno.rede_dm_pessoa(interno.rede_dm_outro(c, p_eu), p_eu),
    'situacao', c.situacao,
    'pedi', c.pediu = p_eu,
    'versao', c.versao,
    'prazo_dias', c.prazo_dias,
    'ultima_em', c.ultima_em,
    'bloqueio', interno.rede_bloqueado(p_eu, interno.rede_dm_outro(c, p_eu)),
    'pode_escrever', c.situacao = 'aberta' and not interno.rede_bloqueado(p_eu, interno.rede_dm_outro(c, p_eu))
      and interno.rede2_membro(interno.rede_dm_outro(c, p_eu)),
    'nao_lidas', (select count(*)::int from rede_dm_mensagens m where m.conversa = c.id and m.autor <> p_eu and m.expira_em > now()
      and m.criado_em > coalesce(case when c.a = p_eu then c.a_leu_em else c.b_leu_em end, '-infinity'::timestamptz)))
$$;

-- ── 3. Situação, preferências e a chave ─────────────────────────────────────────────────────────────────────────────────

/** Onde estou no chat: minha chave (pública), preferências e quantas conversas têm algo novo e quantos pedidos esperam. */
create or replace function public.rede_dm_situacao() returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); k rede_dm_chaves; p rede_dm_prefs;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede_dm_limite('ler');
  perform interno.rede_dm_talvez_faxina();
  select * into k from rede_dm_chaves where usuario = v;
  select * into p from rede_dm_prefs where usuario = v;
  return jsonb_build_object(
    'eu', v,
    'chave', case when k.usuario is null then null else jsonb_build_object('identidade', k.identidade, 'publica', k.publica, 'certificado', k.certificado, 'versao', k.versao) end,
    'quem_pode', coalesce(p.quem_pode, 'pedidos'),
    'prazo_dias', coalesce(p.prazo_dias, 7),
    'pedidos', (select count(*)::int from rede_dm_conversas c where c.situacao = 'pedido' and c.pediu <> v and (c.a = v or c.b = v)
      and not interno.rede_bloqueado(v, c.pediu)),
    'novas', (select count(*)::int from rede_dm_conversas c where (c.a = v or c.b = v) and c.situacao = 'aberta'
      and exists (select 1 from rede_dm_mensagens m where m.conversa = c.id and m.autor <> v and m.expira_em > now()
        and m.criado_em > coalesce(case when c.a = v then c.a_leu_em else c.b_leu_em end, '-infinity'::timestamptz))));
end $$;

/** Quem pode me chamar ('pedidos', 'seguidos', 'ninguem') e o prazo padrão (1, 7 ou 30 dias) das conversas novas. */
create or replace function public.rede_dm_prefs(p_quem_pode text, p_prazo_dias integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if coalesce(p_quem_pode, '') not in ('pedidos', 'seguidos', 'ninguem') then perform interno.erro('invalido:quem_pode'); end if;
  if coalesce(p_prazo_dias, 0) not in (1, 7, 30) then perform interno.erro('invalido:prazo'); end if;
  insert into rede_dm_prefs (usuario, quem_pode, prazo_dias) values (v, p_quem_pode, p_prazo_dias)
  on conflict (usuario) do update set quem_pode = excluded.quem_pode, prazo_dias = excluded.prazo_dias;
  return jsonb_build_object('quem_pode', p_quem_pode, 'prazo_dias', p_prazo_dias);
end $$;

/**
 * Ativa o chat neste aparelho: grava a parte pública da chave do aparelho, a identidade e o certificado (a assinatura da chave
 * pela identidade). Trocar de aparelho troca a chave (versão + 1): as conversas ganham chave nova no próximo uso; o que foi
 * escrito antes fica legível só no aparelho antigo (a chave privada nunca sai de lá).
 */
create or replace function public.rede_dm_chave_publicar(p_identidade text, p_publica text, p_certificado text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); k rede_dm_chaves;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if coalesce(p_identidade, '') !~ '^B[A-Za-z0-9_-]{86}$' then perform interno.erro('invalido:identidade'); end if;
  if coalesce(p_publica, '') !~ '^B[A-Za-z0-9_-]{86}$' or p_publica = p_identidade then perform interno.erro('invalido:publica'); end if;
  if coalesce(p_certificado, '') !~ '^[A-Za-z0-9_-]{86}$' then perform interno.erro('invalido:certificado'); end if;
  select * into k from rede_dm_chaves where usuario = v;
  if found and k.publica = p_publica and k.identidade = p_identidade and k.certificado = p_certificado then
    return jsonb_build_object('versao', k.versao);
  end if;
  perform interno.rede_dm_limite('chave');
  insert into rede_dm_chaves (usuario, identidade, publica, certificado) values (v, p_identidade, p_publica, p_certificado)
  on conflict (usuario) do update set identidade = excluded.identidade, publica = excluded.publica, certificado = excluded.certificado,
    versao = rede_dm_chaves.versao + 1, trocada_em = now()
  returning * into k;
  return jsonb_build_object('versao', k.versao);
end $$;

-- ── 4. Conversas: abrir, pedido, aceitar, recusar, listar ───────────────────────────────────────────────────────────────

/**
 * Abrir conversa com @handle. Se a outra pessoa segue você, abre direto. Se não segue: com "pedidos" (padrão) vira pedido; com
 * "seguidos" ou "ninguem", não abre. Bloqueio, perfil invisível, quem não é membro (18+) e recusa recente: o mesmo "fechado",
 * sem dizer qual foi o motivo (não revela nada da outra pessoa).
 */
create or replace function public.rede_dm_abrir(p_handle text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); f perfis; c rede_dm_conversas; v_pode text; v_segue boolean; v_a uuid; v_b uuid; v_prazo smallint;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  select * into f from perfis where rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  if not found or f.id = v then perform interno.erro('dm_fechada'); end if;
  v_a := least(v, f.id); v_b := greatest(v, f.id);
  select * into c from rede_dm_conversas where a = v_a and b = v_b;
  if found then
    if interno.rede_bloqueado(v, f.id) then perform interno.erro('dm_fechada'); end if;
    return interno.rede_dm_json(c, v);
  end if;
  if not interno.rede2_membro(f.id) or interno.rede_bloqueado(v, f.id) or f.rede_invisivel or f.rede_modo = 'invisivel'
     or exists (select 1 from rede_dm_recusas r where r.quem = f.id and r.de = v and r.ate > now()) then
    perform interno.erro('dm_fechada');
  end if;
  v_pode := coalesce((select quem_pode from rede_dm_prefs where usuario = f.id), 'pedidos');
  v_segue := exists (select 1 from rede_seguindo s where s.quem = f.id and s.segue = v and not s.pendente);
  if v_pode = 'ninguem' or (v_pode = 'seguidos' and not v_segue) then perform interno.erro('dm_fechada'); end if;
  perform interno.rede_dm_limite('pedir');
  v_prazo := coalesce((select prazo_dias from rede_dm_prefs where usuario = v), 7);
  insert into rede_dm_conversas (a, b, situacao, pediu, prazo_dias) values (v_a, v_b, case when v_segue then 'aberta' else 'pedido' end, v, v_prazo)
  returning * into c;
  return interno.rede_dm_json(c, v);
end $$;

/** Responder a um pedido de conversa: aceitar abre; recusar apaga o pedido e impede outro da mesma pessoa por 30 dias. */
create or replace function public.rede_dm_responder(p_conversa uuid, p_aceitar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  if c.situacao <> 'pedido' or c.pediu = v then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_aceitar, false) then
    if interno.rede_bloqueado(v, c.pediu) or not interno.rede2_membro(c.pediu) then perform interno.erro('dm_fechada'); end if;
    update rede_dm_conversas set situacao = 'aberta', ultima_em = now() where id = c.id returning * into c;
    return interno.rede_dm_json(c, v);
  end if;
  insert into rede_dm_recusas (quem, de, ate) values (v, c.pediu, now() + interval '30 days')
  on conflict (quem, de) do update set ate = excluded.ate;
  delete from rede_dm_conversas where id = c.id;
  return jsonb_build_object('recusado', true);
end $$;

/** Minhas conversas e pedidos, da mais recente à mais antiga. Quem eu bloqueei (ou me bloqueou) com pedido pendente não aparece. */
create or replace function public.rede_dm_conversas() returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede_dm_limite('ler');
  perform interno.rede_dm_talvez_faxina();
  return coalesce((
    select jsonb_agg(interno.rede_dm_json(c, v) order by c.ultima_em desc)
    from rede_dm_conversas c
    where (c.a = v or c.b = v) and not (c.situacao = 'pedido' and interno.rede_bloqueado(v, interno.rede_dm_outro(c, v)))
  ), '[]'::jsonb);
end $$;

-- ── 5. Chaves da conversa ───────────────────────────────────────────────────────────────────────────────────────────────

/**
 * O que o aparelho precisa para cifrar e decifrar: a chave pública atual de cada participante (para conferir o certificado com
 * a identidade guardada no aparelho) e os embrulhos feitos PARA mim. Embrulho para o outro nunca sai.
 */
create or replace function public.rede_dm_chaves_da_conversa(p_conversa uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas; o uuid;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  o := interno.rede_dm_outro(c, v);
  if c.situacao <> 'aberta' or interno.rede_bloqueado(v, o) then perform interno.erro('dm_fechada'); end if;
  return jsonb_build_object(
    'versao', c.versao,
    'versao_em', c.versao_em,
    -- A versão atual foi embrulhada para a chave ATUAL de cada participante? Se não (alguém trocou de aparelho), o aparelho
    -- de quem abre faz uma versão nova. Só um sim/não: o embrulho do outro nunca sai.
    'atual_ok', c.versao > 0 and (select count(*) from rede_dm_embrulhos e join rede_dm_chaves k on k.usuario = e.para and k.versao = e.chave_versao
      where e.conversa = c.id and e.versao = c.versao) = 2,
    'participantes', coalesce((select jsonb_agg(jsonb_build_object('usuario', k.usuario, 'identidade', k.identidade, 'publica', k.publica,
      'certificado', k.certificado, 'versao', k.versao)) from rede_dm_chaves k where k.usuario in (c.a, c.b)), '[]'::jsonb),
    'embrulhos', coalesce((select jsonb_agg(jsonb_build_object('versao', e.versao, 'chave_versao', e.chave_versao, 'embrulho', e.embrulho,
      'de', e.de, 'de_publica', e.de_publica, 'de_certificado', e.de_certificado) order by e.versao) from rede_dm_embrulhos e
      where e.conversa = c.id and e.para = v), '[]'::jsonb));
end $$;

/**
 * Uma versão nova da chave da conversa (a primeira, ou porque alguém trocou de aparelho, ou porque passou uma semana). Quem
 * chama embrulha no aparelho para a chave ATUAL de cada participante (os dois), com a própria chave atual. p_embrulhos:
 * [{"para": uuid, "chave_versao": n, "embrulho": "w1..."}].
 */
create or replace function public.rede_dm_nova_versao(p_conversa uuid, p_versao integer, p_embrulhos jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); c rede_dm_conversas; o uuid; minha rede_dm_chaves; e jsonb; k rede_dm_chaves; v_para uuid; n integer := 0;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  select * into c from rede_dm_conversas where id = p_conversa and (a = v or b = v) for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  o := interno.rede_dm_outro(c, v);
  if c.situacao <> 'aberta' or interno.rede_bloqueado(v, o) or not interno.rede2_membro(o) then perform interno.erro('dm_fechada'); end if;
  if p_versao is distinct from c.versao + 1 then perform interno.erro('versao_desatualizada'); end if;
  select * into minha from rede_dm_chaves where usuario = v;
  if not found then perform interno.erro('dm_sem_chave'); end if;
  if jsonb_typeof(p_embrulhos) <> 'array' or jsonb_array_length(p_embrulhos) <> 2 then perform interno.erro('invalido:embrulhos'); end if;
  for e in select * from jsonb_array_elements(p_embrulhos) loop
    begin v_para := (e ->> 'para')::uuid; exception when others then perform interno.erro('invalido:embrulhos'); end;
    if v_para not in (c.a, c.b) then perform interno.erro('invalido:embrulhos'); end if;
    select * into k from rede_dm_chaves where usuario = v_para;
    if not found then perform interno.erro('dm_sem_chave'); end if;
    if (e ->> 'chave_versao')::integer is distinct from k.versao then perform interno.erro('versao_desatualizada'); end if;
    if coalesce(e ->> 'embrulho', '') !~ '^w1\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{64}$' then perform interno.erro('invalido:embrulho'); end if;
    insert into rede_dm_embrulhos (conversa, versao, para, chave_versao, embrulho, de, de_publica, de_certificado)
    values (c.id, p_versao, v_para, k.versao, e ->> 'embrulho', v, minha.publica, minha.certificado);
    n := n + 1;
  end loop;
  if n <> 2 or (select count(distinct para) from rede_dm_embrulhos where conversa = c.id and versao = p_versao) <> 2 then perform interno.erro('invalido:embrulhos'); end if;
  update rede_dm_conversas set versao = p_versao, versao_em = now() where id = c.id;
  return jsonb_build_object('versao', p_versao);
end $$;

-- ── 6. Mensagens ────────────────────────────────────────────────────────────────────────────────────────────────────────

/** Envia uma mensagem já cifrada no aparelho, na versão atual da chave. O banco não aceita texto aberto. */
create or replace function public.rede_dm_enviar(p_conversa uuid, p_versao integer, p_corpo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas; o uuid; m rede_dm_mensagens;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  o := interno.rede_dm_outro(c, v);
  if c.situacao <> 'aberta' or interno.rede_bloqueado(v, o) or not interno.rede2_membro(o) then perform interno.erro('dm_fechada'); end if;
  if c.versao < 1 or p_versao is distinct from c.versao then perform interno.erro('versao_desatualizada'); end if;
  if p_corpo is null or char_length(p_corpo) > 12000 or p_corpo !~ ('^c2\.' || p_versao || '\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{23,}$') then
    perform interno.erro('invalido:corpo');
  end if;
  perform interno.rede_dm_limite('enviar');
  insert into rede_dm_mensagens (conversa, autor, versao, corpo, expira_em) values (c.id, v, p_versao, p_corpo, now() + make_interval(days => c.prazo_dias))
  returning * into m;
  update rede_dm_conversas set ultima_em = m.criado_em,
    a_leu_em = case when a = v then m.criado_em else a_leu_em end, b_leu_em = case when b = v then m.criado_em else b_leu_em end
  where id = c.id;
  perform interno.rede_dm_talvez_faxina();
  return jsonb_build_object('id', m.id, 'criado_em', m.criado_em, 'expira_em', m.expira_em);
end $$;

/** As mensagens (cifradas), das mais novas para trás; `p_antes` pagina. Marca a conversa como lida para quem chama. */
create or replace function public.rede_dm_mensagens(p_conversa uuid, p_antes timestamptz default null, p_limite integer default 50) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas; v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 100);
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede_dm_limite('ler');
  c := interno.rede_dm_minha(p_conversa, v);
  if c.situacao <> 'aberta' then perform interno.erro('dm_fechada'); end if;
  if p_antes is null then
    update rede_dm_conversas set a_leu_em = case when a = v then now() else a_leu_em end, b_leu_em = case when b = v then now() else b_leu_em end where id = c.id;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'autor', x.autor, 'versao', x.versao, 'corpo', x.corpo, 'criado_em', x.criado_em, 'expira_em', x.expira_em) order by x.criado_em desc)
    from (select * from rede_dm_mensagens m where m.conversa = c.id and m.expira_em > now() and (p_antes is null or m.criado_em < p_antes)
          order by m.criado_em desc limit v_limite) x
  ), '[]'::jsonb);
end $$;

/** Apaga uma mensagem minha, de verdade (some para os dois). */
create or replace function public.rede_dm_apagar_mensagem(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.rede_dm_limite('apagar');
  delete from rede_dm_mensagens where id = p_id and autor = v;
  if not found then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('ok', true);
end $$;

/** Apaga a conversa inteira, para os dois: mensagens, chaves embrulhadas, tudo (LGPD art. 18, VI). */
create or replace function public.rede_dm_apagar(p_conversa uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas;
begin
  perform interno.rede_dm_limite('apagar');
  c := interno.rede_dm_minha(p_conversa, v);
  delete from rede_dm_conversas where id = c.id;
  return jsonb_build_object('ok', true);
end $$;

/** Prazo das mensagens desta conversa (1, 7 ou 30 dias). Encurtar vale também para o que já foi escrito; alongar, só para as novas. */
create or replace function public.rede_dm_prazo(p_conversa uuid, p_dias integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if coalesce(p_dias, 0) not in (1, 7, 30) then perform interno.erro('invalido:prazo'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  update rede_dm_conversas set prazo_dias = p_dias where id = c.id;
  update rede_dm_mensagens set expira_em = least(expira_em, criado_em + make_interval(days => p_dias)) where conversa = c.id;
  delete from rede_dm_mensagens where conversa = c.id and expira_em <= now();
  return jsonb_build_object('prazo_dias', p_dias);
end $$;

/**
 * Denunciar a outra pessoa da conversa. `p_trechos` é o que quem denuncia escolheu mostrar, já decifrado no aparelho dela (o
 * servidor e a moderação nunca têm a chave da conversa). Vai para a fila de denúncias da Alumia como denúncia de perfil, com a
 * mesma prioridade por categoria; quem denuncia nunca é revelado. Pode bloquear junto.
 */
create or replace function public.rede_dm_denunciar(p_conversa uuid, p_categoria text, p_trechos text default '', p_bloquear boolean default false) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas; o uuid; d rede_denuncias; v_texto text;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if p_categoria is null or p_categoria not in ('menores', 'ameaca', 'exposicao', 'violencia', 'autolesao', 'odio', 'assedio', 'golpe', 'spam', 'outro') then perform interno.erro('invalido:categoria'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  o := interno.rede_dm_outro(c, v);
  v_texto := left('[Chat privado] Trechos escolhidos e decifrados por quem denunciou: ' || interno.txt(coalesce(p_trechos, ''), 'trechos', 0, 1900), 2000);
  select * into d from rede_denuncias where quem = v and alvo_tipo = 'perfil' and alvo = o::text and situacao in ('aberta', 'em_analise') limit 1;
  if not found then
    perform interno.rede_dm_limite('denunciar');
    insert into rede_denuncias (alvo_tipo, alvo, categoria, prioridade, texto, quem)
    values ('perfil', o::text, p_categoria, interno.rede2_prioridade(p_categoria), v_texto, v) returning * into d;
  end if;
  if coalesce(p_bloquear, false) then
    insert into rede_bloqueios (quem, bloqueado) values (v, o) on conflict do nothing;
    delete from rede_seguindo where (quem = v and segue = o) or (quem = o and segue = v);
  end if;
  return jsonb_build_object('protocolo', d.protocolo, 'prioridade', d.prioridade, 'bloqueado', coalesce(p_bloquear, false));
end $$;

/** Apaga tudo o que é meu no chat (chave, preferências, todas as conversas e mensagens), sem apagar a conta (LGPD art. 18, VI). */
create or replace function public.rede_dm_apagar_tudo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); n integer;
begin
  perform interno.rede_dm_limite('apagar');
  delete from rede_dm_conversas where a = v or b = v;
  get diagnostics n = row_count;
  delete from rede_dm_chaves where usuario = v;
  delete from rede_dm_prefs where usuario = v;
  delete from rede_dm_recusas where quem = v or de = v;
  return jsonb_build_object('conversas', n);
end $$;

-- ── 7. Permissões ───────────────────────────────────────────────────────────────────────────────────────────────────────

revoke all on function interno.rede_dm_faxina(), interno.rede_dm_talvez_faxina(), interno.rede_dm_minha(uuid, uuid),
  interno.rede_dm_outro(interno.rede_dm_conversas, uuid), interno.rede_dm_limite(text), interno.rede_dm_pessoa(uuid, uuid),
  interno.rede_dm_json(interno.rede_dm_conversas, uuid) from public;
revoke all on function public.rede_dm_situacao(), public.rede_dm_prefs(text, integer), public.rede_dm_chave_publicar(text, text, text),
  public.rede_dm_abrir(text), public.rede_dm_responder(uuid, boolean), public.rede_dm_conversas(), public.rede_dm_chaves_da_conversa(uuid),
  public.rede_dm_nova_versao(uuid, integer, jsonb), public.rede_dm_enviar(uuid, integer, text), public.rede_dm_mensagens(uuid, timestamptz, integer),
  public.rede_dm_apagar_mensagem(uuid), public.rede_dm_apagar(uuid), public.rede_dm_prazo(uuid, integer),
  public.rede_dm_denunciar(uuid, text, text, boolean), public.rede_dm_apagar_tudo() from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_dm_faxina(), interno.rede_dm_talvez_faxina(), interno.rede_dm_minha(uuid, uuid),
      interno.rede_dm_outro(interno.rede_dm_conversas, uuid), interno.rede_dm_limite(text), interno.rede_dm_pessoa(uuid, uuid),
      interno.rede_dm_json(interno.rede_dm_conversas, uuid) from anon, authenticated;
    revoke all on function public.rede_dm_situacao(), public.rede_dm_prefs(text, integer), public.rede_dm_chave_publicar(text, text, text),
      public.rede_dm_abrir(text), public.rede_dm_responder(uuid, boolean), public.rede_dm_conversas(), public.rede_dm_chaves_da_conversa(uuid),
      public.rede_dm_nova_versao(uuid, integer, jsonb), public.rede_dm_enviar(uuid, integer, text), public.rede_dm_mensagens(uuid, timestamptz, integer),
      public.rede_dm_apagar_mensagem(uuid), public.rede_dm_apagar(uuid), public.rede_dm_prazo(uuid, integer),
      public.rede_dm_denunciar(uuid, text, text, boolean), public.rede_dm_apagar_tudo() from anon;
    -- Só quem entrou na conta chama; visitante (anon) nunca.
    grant execute on function public.rede_dm_situacao(), public.rede_dm_prefs(text, integer), public.rede_dm_chave_publicar(text, text, text),
      public.rede_dm_abrir(text), public.rede_dm_responder(uuid, boolean), public.rede_dm_conversas(), public.rede_dm_chaves_da_conversa(uuid),
      public.rede_dm_nova_versao(uuid, integer, jsonb), public.rede_dm_enviar(uuid, integer, text), public.rede_dm_mensagens(uuid, timestamptz, integer),
      public.rede_dm_apagar_mensagem(uuid), public.rede_dm_apagar(uuid), public.rede_dm_prazo(uuid, integer),
      public.rede_dm_denunciar(uuid, text, text, boolean), public.rede_dm_apagar_tudo() to authenticated;
  end if;
end $$;

-- ───────────────────────── Turmas em pausa (T08, 06/11/2026) ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Rode DEPOIS de 2026-11-backend-1.sql
-- (que cria interno.recursos_catalogo e interno.recursos_vivos). Texto: docs/RECURSOS.md, seção "turmas".
--
-- O que faz: põe o recurso "turmas" no catálogo dos recursos que a coordenação liga e desliga pelo painel
-- (Site › Controles avançados › Recursos). As turmas (por curso, na Escola, e a Turma do mês) ficam em pausa por decisão
-- da coordenação ("não temos gente o suficiente"); no código, "turmas" está em EM_PAUSA (lib/recursos.ts): a variável
-- "todos" não o liga. Ligar pelo painel vale na hora, sem segunda pessoa (so_pelo_nome = false).
--
-- Também grava a decisão explícita "desligado", para o painel mostrar a chave desligada desde o primeiro dia. Só grava se
-- ainda não houver decisão (não desfaz uma escolha que a coordenação já tenha feito).
--
-- Nenhuma tabela, função ou permissão nova; nenhum dado pessoal (LGPD, Lei 13.709/2018, art. 6º, III: necessidade).

insert into interno.recursos_catalogo (nome, so_pelo_nome) values ('turmas', false)
on conflict (nome) do update set so_pelo_nome = excluded.so_pelo_nome;

insert into interno.recursos_vivos (nome, ligado, por) values ('turmas', false, null)
on conflict (nome) do nothing;

-- ───────────────────────── Recados da Mesa em grupos (T27, 06/11/2026) ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Rode depois do install.sql (a coluna
-- interno.avisos.categoria já existe lá).
--
-- O que faz: public.avisos_meus() passa a devolver também a categoria do recado ('equipe', 'rede' ou 'conta'), para a
-- Mesa agrupar os recados por assunto (components/painel/recados-grupos.ts). Sem esta migração a Mesa agrupa só pelo texto,
-- então nada quebra se ela ainda não tiver rodado.
--
-- Mesma regra de antes: só os recados da própria pessoa (para = auth.uid()), os 40 mais novos. Nenhum dado novo é guardado
-- nem mostrado a outra pessoa (LGPD, Lei 13.709/2018, art. 6º, III: necessidade).

create or replace function public.avisos_meus() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'texto', a.texto, 'lido', a.lido, 'criado_em', a.criado_em, 'categoria', a.categoria) order by a.criado_em desc), '[]'::jsonb)
  from (select * from avisos where para = auth.uid() and auth.uid() is not null order by criado_em desc limit 40) a
$$;

-- ───────────────────────── Assistente em todo o site (T03, 06/11/2026) ─────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Rode DEPOIS de 2026-11-backend-1.sql
-- (que cria interno.recursos_catalogo). Texto: docs/RECURSOS.md, seção "assistente-publico", e docs/privacidade-assistente.md.
--
-- O que faz: põe o recurso "assistente-publico" no catálogo dos recursos que a coordenação liga e desliga pelo painel
-- (Site › Controles avançados › Recursos). No código ele está em PADRAO (lib/recursos.ts): nasce LIGADO, a pedido da
-- coordenação ("eu quero ligar o assistente em todo o site"). Desligar pelo painel vale na hora, sem segunda pessoa.
--
-- Não grava decisão em interno.recursos_vivos: sem decisão, vale o padrão do código (ligado).
--
-- O assistente aberto NÃO usa o banco: o limite por pessoa fica na memória do servidor do site, com um resumo do IP com
-- sal do dia (app/api/assistente/route.ts, lib/assistente/limite.ts). Nenhuma tabela, função ou permissão nova; nenhum dado
-- pessoal (LGPD, Lei 13.709/2018, art. 6º, III: necessidade).

insert into interno.recursos_catalogo (nome, so_pelo_nome) values ('assistente-publico', false)
on conflict (nome) do update set so_pelo_nome = excluded.so_pelo_nome;

-- ───────────────────────────── Auditoria de segurança T33 (07/11/2026) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado de ninguém além do que está dito em cada parte. O
-- mesmo bloco está no fim do install.sql (roda DEPOIS de todas as migrações de 6/11). Resumo: docs/AUDITORIA-2026-11-07.md.
--
--   1. O resumo do endereço de rede (interno.origem) deixa de ser md5 com sal público: passa a SHA-256 com um segredo
--      aleatório que fica só no banco (interno.origem_segredo, fora da cópia semanal) e que a API não lê. Os resumos
--      antigos (reversíveis) são apagados ou embaralhados de novo; perfis.origem some depois de 30 dias sem entrar.
--   2. Revolucionários (dado sensível, LGPD art. 11): a página do departamento, a contagem, os bastões, o quadro, os
--      pedidos, as listas da equipe e o registro de atividades deixam de mostrar quem participa ou representa, a quem
--      não é da coordenação nem do próprio departamento.
--   3. Inscrição militante: a supervisão não lê mais; pedido repetido não vira oráculo ("ja_pediu"); e a inscrição só
--      existe depois que a pessoa confirma o e-mail (link de uso único, 3 dias). Nenhum e-mail cita a Frente, e o aviso à
--      liderança não leva nome, e-mail nem Instagram.
--   4. Chat privado da Alumia: apagar a conversa sai só da lista de quem apaga (o outro lado guarda as provas até o prazo);
--      encurtar o prazo vale só para as mensagens novas; mensagem não se apaga depois de bloqueio ou denúncia; quem apaga
--      tudo não apaga as recusas que outras pessoas fizeram contra si; versão nova da chave tem limite.

-- ── 1. O resumo do endereço de rede ─────────────────────────────────────────────────────────────────────────────────

-- O segredo: uma linha só, fora do alcance da API (RLS sem política, nenhum privilégio) e fora da cópia semanal
-- (.github/workflows/backup.yml: --exclude-table-data). Restaurar uma cópia gera um segredo novo ao rodar o install.sql.
create table if not exists interno.origem_segredo (
  id boolean primary key default true check (id),
  segredo text not null check (char_length(segredo) >= 64),
  criado_em timestamptz not null default now()
);
alter table interno.origem_segredo enable row level security;
revoke all on interno.origem_segredo from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on interno.origem_segredo from anon, authenticated; end if;
end $$;
insert into interno.origem_segredo (segredo)
values (replace(gen_random_uuid()::text || gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
on conflict do nothing;

/**
 * O endereço que a borda da rede informa (não pode ser forjado por quem chama; sem ele, vale o primeiro da fila), virado
 * resumo: SHA-256 do segredo do banco com o endereço. Sem o segredo, o resumo não volta ao endereço (o md5 com sal público
 * de antes voltava em segundos, testando os 4 bilhões de IPv4).
 */
create or replace function interno.origem() returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select encode(sha256(convert_to(coalesce((select segredo from origem_segredo where id), '') || ':' || coalesce(
    nullif(nullif(current_setting('request.headers', true), '')::json ->> 'cf-connecting-ip', ''),
    split_part(nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for', ',', 1),
    'local'), 'UTF8')), 'hex')
$$;
revoke all on function interno.origem() from public;

-- Os resumos antigos (md5 de 32 letras) eram, na prática, o endereço: saem. Bloqueio de origem decidido antes desta data
-- deixa de valer (a conta banida continua suspensa); limites e tentativas de entrada recomeçam do zero.
update interno.perfis set origem = null where origem ~ '^[0-9a-f]{32}$';
update interno.banimentos set origem = null where origem ~ '^[0-9a-f]{32}$';
delete from interno.entradas_falhas where origem ~ '^[0-9a-f]{32}$';
delete from interno.limites where chave ~ ':[0-9a-f]{32}$';
-- O aceite do convidado do podcast guarda a origem como registro: fica, mas embaralhada de novo com o segredo.
update interno.podcast_convidados set aceite_origem = encode(sha256(convert_to((select segredo from interno.origem_segredo where id) || ':legado:' || aceite_origem, 'UTF8')), 'hex')
where aceite_origem ~ '^[0-9a-f]{32}$';
update interno.auditoria set detalhes = jsonb_set(detalhes, '{origem}', to_jsonb(encode(sha256(convert_to((select segredo from interno.origem_segredo where id) || ':legado:' || (detalhes ->> 'origem'), 'UTF8')), 'hex')))
where acao = 'armadilha' and detalhes ->> 'origem' ~ '^[0-9a-f]{32}$';

-- ── 2. Revolucionários: quem participa só aparece para a coordenação e para o próprio departamento ─────────────────────

/** Quem chama pode saber quem está nos Revolucionários? A coordenação e quem é do próprio departamento. */
create or replace function interno.ve_revolucionarios() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(interno.coord() or interno.membro_direto(auth.uid(), 'revolucionarios'), false)
$$;

/** Um papel de outra pessoa pode aparecer para quem chama? O de representante dos Revolucionários, só para quem vê o departamento. */
create or replace function interno.papel_visivel(p_dono uuid, p_disciplina text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_disciplina is distinct from 'revolucionarios' or p_dono = auth.uid() or interno.ve_revolucionarios()
$$;

/** Uma linha do registro que revela quem está nos Revolucionários (ou se inscreveu como militante). */
create or replace function interno.auditoria_reservada(a interno.auditoria) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(a.detalhes ->> 'disciplina', '') in ('revolucionarios', 'reservado')
      or coalesce(a.detalhes ->> 'departamento', '') in ('revolucionarios', 'reservado')
      or (a.acao in ('inscricao_aceita', 'inscricao_recusada') and exists (select 1 from inscricoes i where i.tipo = 'militante' and i.nome = a.alvo))
$$;

/** Os pedidos entre departamentos: o nome de quem pediu pelos Revolucionários, ou de quem cuidou lá, só para quem vê o departamento. */
create or replace function interno.departamento_pedido_json(x interno.departamento_pedidos) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', x.id, 'de', x.de, 'para', x.para, 'titulo', x.titulo, 'detalhe', x.detalhe, 'prazo', x.prazo, 'status', x.status, 'resposta', x.resposta,
    'criado_em', x.criado_em, 'atualizado_em', x.atualizado_em, 'meu', x.autor = auth.uid(),
    'autor', case when x.de = 'revolucionarios' and x.autor is distinct from auth.uid() and not interno.ve_revolucionarios() then ''
                  else coalesce((select interno.nome_visto(nome) from perfis where id = x.autor), '') end,
    'responsavel', case when x.para = 'revolucionarios' and x.responsavel is distinct from auth.uid() and not interno.ve_revolucionarios() then ''
                  else coalesce((select interno.nome_visto(nome) from perfis where id = x.responsavel), '') end)
$$;

/** Confia uma função. Igual a antes; no registro, a representação dos Revolucionários aparece como "reservado". */
create or replace function interno.papel_conceder_um(p_usuario uuid, p_papel text, p_disciplina text) returns boolean
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_linhas integer;
begin
  if coalesce(p_papel, '') not in ('vice', 'supervisao', 'curadoria', 'mediacao', 'educacao', 'educacao_secundaria', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'marketing', 'desenvolvimento', 'representante', 'porta_voz', 'saude') then perform interno.erro('invalido:papel'); end if;
  if p_papel = 'representante' and not interno.departamento_valido(p_disciplina) then perform interno.erro('invalido:departamento'); end if;
  -- Representar os Revolucionários é saber quem são: só a coordenação nomeia (LGPD, art. 11).
  if p_papel = 'representante' and p_disciplina = 'revolucionarios' and not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if not interno.pode_conceder(p_papel) then perform interno.erro('sem_permissao'); end if;
  -- Educação, educação secundária e reforço são por disciplina: sem ela, a pessoa enxergaria a fila de todas.
  if p_papel in ('educacao', 'educacao_secundaria', 'mentoria') and coalesce(p_disciplina, '') = '' then perform interno.erro('invalido:disciplina'); end if;
  insert into papeis (usuario, papel, disciplina, concedido_por)
  values (p_usuario, p_papel, case when p_papel in ('vice', 'supervisao', 'marketing') then null else interno.disciplina_ok(p_disciplina) end, auth.uid()) on conflict do nothing;
  get diagnostics v_linhas = row_count;
  perform interno.registrar('papel_confiado', p_usuario::text, jsonb_build_object('papel', p_papel, 'disciplina', case when p_disciplina = 'revolucionarios' then 'reservado' else p_disciplina end));
  return v_linhas > 0;
end $$;
revoke all on function interno.papel_conceder_um(uuid, text, text) from public;

/** Retirar um papel. Igual a antes; no registro, a representação dos Revolucionários aparece como "reservado". */
create or replace function public.papel_remover(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare r papeis;
begin
  perform interno.eu();
  if not interno.gere_cargos() then perform interno.erro('sem_permissao'); end if;
  select * into r from papeis where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  -- A vice-coordenação não mexe na coordenação nem em outra vice-coordenação.
  if r.papel in ('coordenacao', 'vice') and not interno.lider() then perform interno.erro('sem_permissao'); end if;
  -- A supervisão de quem também é vice-coordenação, só a coordenação retira (a mesma regra da própria vice-coordenação).
  if r.papel = 'supervisao' and not interno.lider() and exists (select 1 from papeis where usuario = r.usuario and papel = 'vice') then perform interno.erro('sem_permissao'); end if;
  if r.papel = 'coordenacao' and (select count(*) from papeis where papel = 'coordenacao') <= 1 then perform interno.erro('ultima_coordenacao'); end if;
  if not interno.pode_mexer(r.usuario) then perform interno.erro('sem_permissao'); end if;
  -- Quem não vê os Revolucionários também não descobre quem os representa tentando retirar o papel.
  if r.disciplina = 'revolucionarios' and not interno.coord() then perform interno.erro('sem_permissao'); end if;
  delete from papeis where id = p_id;
  perform interno.registrar('papel_retirado', r.usuario::text, jsonb_build_object('papel', r.papel, 'disciplina', case when r.disciplina = 'revolucionarios' then 'reservado' else r.disciplina end));
  return jsonb_build_object('ok', true);
end $$;

/** O registro de atividades. Igual a antes; o que revela quem está nos Revolucionários só aparece para quem vê o departamento. */
create or replace function public.auditoria_listar(p_pagina integer default 0, p_acao text default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_ve boolean;
begin
  perform interno.eu();
  if not interno.supervisor() then perform interno.erro('sem_permissao'); end if;
  v_ve := interno.ve_revolucionarios();
  return (
    select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'nome', a.nome, 'acao', a.acao, 'alvo', a.alvo, 'detalhes', a.detalhes, 'criado_em', a.criado_em,
      'alvo_nome', coalesce((select f.nome from perfis f where f.id::text = a.alvo), '')) order by a.id desc), '[]'::jsonb)
    from (select * from auditoria x where (coalesce(p_acao, '') = '' or x.acao = p_acao) and (v_ve or not interno.auditoria_reservada(x))
          order by x.id desc limit 100 offset greatest(coalesce(p_pagina, 0), 0) * 100) a);
end $$;

/** Quem faz o site: nome escolhido e papéis. Igual a antes, sem a representação dos Revolucionários. */
create or replace function public.equipe() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('nome', f.nome, 'papel', p.papel, 'disciplina', p.disciplina) order by p.papel, f.nome), '[]'::jsonb)
  from papeis p join perfis f on f.id = p.usuario where not f.suspenso and interno.papel_visivel(p.usuario, p.disciplina)
$$;

/** A equipe para a supervisão. Igual a antes, sem a representação dos Revolucionários para quem não vê o departamento. */
create or replace function public.equipe_supervisao() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.supervisor() then perform interno.erro('sem_permissao'); end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', f.id, 'nome', f.nome, 'suspenso', f.suspenso, 'suspensao', f.suspensao, 'visto_em', f.visto_em, 'eu', f.id = v,
      'protegida', exists (select 1 from papeis p where p.usuario = f.id and p.papel in ('coordenacao', 'vice', 'supervisao')),
      'papeis', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'papel', p.papel, 'disciplina', p.disciplina) order by p.papel, p.disciplina) from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)), '[]'::jsonb))
      order by f.nome), '[]'::jsonb)
    from perfis f where exists (select 1 from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)));
end $$;

/** Quem faz parte da equipe, para a rede interna. Igual a antes, sem a representação dos Revolucionários para quem não vê o departamento. */
create or replace function public.equipe_membros() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', f.id, 'nome', interno.nome_visto(f.nome), 'bio', f.bio, 'avatar', f.avatar, 'eu', f.id = auth.uid(), 'por_aqui', f.visto_em > now() - interval '90 minutes',
      'privado', interno.privado_permitido(f.id),
      -- Quem esconde o "visto por último" não o mostra e não vê o dos outros.
      'online', case when f.presenca = 'invisivel' and f.id <> auth.uid() then false when f.id = auth.uid() or (f.chat_visto and coalesce((select p.chat_visto from perfis p where p.id = auth.uid()), true)) then f.visto_em > now() - interval '2 minutes' end,
      'presenca', case when f.presenca = 'invisivel' and f.id <> auth.uid() then 'online' else f.presenca end, 'frase', f.frase, 'capa', f.capa,
      'desde', (select min(p.criado_em) from papeis p where p.usuario = f.id),
      'visto_em', case when f.id = auth.uid() or (f.chat_visto and coalesce((select p.chat_visto from perfis p where p.id = auth.uid()), true)) then f.visto_em end,
      'papeis', (select jsonb_agg(jsonb_build_object('papel', p.papel, 'disciplina', p.disciplina) order by p.papel, p.disciplina) from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)),
      'ferias_ate', case when f.ferias_ate >= current_date then f.ferias_ate end, 'oficios', to_jsonb(f.oficios))
      order by f.nome), '[]'::jsonb)
    from perfis f where not f.suspenso and exists (select 1 from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)));
end $$;

/** A equipe para quem gere cargos. Igual a antes; a representação dos Revolucionários some junto com o departamento. */
create or replace function public.voluntarios_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_coord boolean := interno.coord();
begin
  if not interno.gere_cargos() then perform interno.erro('sem_permissao'); end if;
  if interno.lider() then perform interno.registrar_acesso('emails_da_equipe'); end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', f.id, 'nome', interno.nome_visto(f.nome), 'bio', f.bio, 'email', case when interno.lider() then u.email else '' end, 'suspenso', f.suspenso, 'suspensao', f.suspensao, 'trocar_senha', f.trocar_senha,
      'criado_em', f.criado_em, 'visto_em', f.visto_em, 'nivel', interno.nivel_de(f.id),
      'papeis', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'papel', p.papel, 'disciplina', p.disciplina) order by interno.nivel(p.papel) desc, p.papel, p.disciplina) from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)), '[]'::jsonb),
      'departamentos', coalesce((select jsonb_agg(m.departamento order by m.departamento) from departamento_membros m where m.usuario = f.id and (v_coord or m.departamento <> 'revolucionarios')), '[]'::jsonb))
      order by f.nome), '[]'::jsonb)
    from perfis f join auth.users u on u.id = f.id);
end $$;

/**
 * Tudo de um departamento. Igual a antes, com dois cuidados: nos Revolucionários, quem não é da coordenação nem do
 * departamento vê só a descrição (nem pessoas, nem quadro, nem bastões, nem pedidos, que trazem nomes); nos outros, a
 * representação dos Revolucionários não aparece nos papéis de ninguém, e quem só representa os Revolucionários não
 * aparece entre os Representantes.
 */
create or replace function public.departamento_ver(p_id text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare d departamentos_info; v_ve_pessoas boolean;
begin
  perform interno.eu();
  -- Quem só participa do departamento (sem função de trabalho, como um militante ou um coletivo parceiro) também abre o dele.
  if not (interno.voluntario() or ((interno.aal2() or not interno.tem_fator()) and interno.membro_direto(auth.uid(), p_id))) then perform interno.erro('sem_permissao'); end if;
  select * into d from departamentos_info where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  v_ve_pessoas := d.id <> 'revolucionarios' or interno.coord() or interno.membro_direto(auth.uid(), d.id);
  if not v_ve_pessoas then
    return jsonb_build_object(
      'id', d.id, 'descricao', d.descricao, 'como', d.como, 'meta_titulo', d.meta_titulo, 'meta_alvo', d.meta_alvo, 'meta_feito', d.meta_feito, 'atualizado_em', d.atualizado_em,
      'meu', false, 'respondo', false, 'reservado', true, 'pessoas', '[]'::jsonb, 'recebidos', '[]'::jsonb, 'enviados', '[]'::jsonb,
      'quadro', '[]'::jsonb, 'feitos_no_mes', 0, 'bastoes', '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'id', d.id, 'descricao', d.descricao, 'como', d.como, 'meta_titulo', d.meta_titulo, 'meta_alvo', d.meta_alvo, 'meta_feito', d.meta_feito, 'atualizado_em', d.atualizado_em,
    'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id), 'reservado', false,
    'pessoas', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar,
                  'responde', exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id),
                  'ferias_ate', case when f.ferias_ate >= current_date then f.ferias_ate end,
                  'oficios', to_jsonb(f.oficios),
                  -- Desde quando a pessoa está neste departamento (para o rodízio: depois de um ano, ensinar alguém).
                  'desde', least((select min(p.criado_em) from papeis p where p.usuario = f.id and (p.papel = d.id or p.disciplina = d.id or (d.id = 'jornalismo' and p.papel = 'marketing')
                                   or (d.id = 'coordenacao' and p.papel in ('coordenacao', 'vice')) or (d.id = 'representantes' and p.papel = 'representante' and interno.papel_visivel(p.usuario, p.disciplina)))),
                                 (select m.criado_em from departamento_membros m where m.usuario = f.id and m.departamento = d.id)),
                  'papeis', (select jsonb_agg(jsonb_build_object('papel', p.papel, 'disciplina', p.disciplina)) from papeis p where p.usuario = f.id and interno.papel_visivel(p.usuario, p.disciplina)))
                  order by exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id) desc, f.nome), '[]'::jsonb)
                from perfis f where interno.membro_direto(f.id, d.id)
                  and (d.id <> 'representantes' or interno.ve_revolucionarios()
                       or exists (select 1 from departamento_membros m where m.usuario = f.id and m.departamento = 'representantes')
                       or exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina is distinct from 'revolucionarios'))),
    'recebidos', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.status = 'aberto' desc, x.prazo nulls last, x.criado_em desc), '[]'::jsonb)
                  from (select * from departamento_pedidos where para = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'enviados', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.criado_em desc), '[]'::jsonb)
                 from (select * from departamento_pedidos where de = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'quadro', (select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'titulo', q.titulo, 'etiqueta', q.etiqueta, 'coluna', q.coluna, 'prazo', q.prazo, 'pedido', q.pedido,
                 'dono', q.dono, 'dono_nome', coalesce((select interno.nome_visto(nome) from perfis where id = q.dono), ''), 'atualizado_em', q.atualizado_em)
                 order by q.coluna, q.prazo nulls last, q.atualizado_em desc), '[]'::jsonb)
               from departamento_quadro q where q.departamento = d.id and (q.coluna <> 'feito' or q.atualizado_em > now() - interval '14 days')),
    'feitos_no_mes', (select count(*) from departamento_quadro q where q.departamento = d.id and q.coluna = 'feito' and q.atualizado_em >= date_trunc('month', now())),
    'bastoes', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'texto', b.texto, 'criado_em', b.criado_em, 'meu', b.autor = auth.uid(),
                  'autor', coalesce((select interno.nome_visto(nome) from perfis where id = b.autor), '')) order by b.criado_em desc), '[]'::jsonb)
                from (select * from departamento_bastoes where departamento = d.id order by criado_em desc limit 20) b));
end $$;

/** A lista dos departamentos. Igual a antes; quantas pessoas há nos Revolucionários (e quem só os representa), só para quem vê o departamento. */
create or replace function public.departamentos_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_equipe boolean; v_ve boolean;
begin
  perform interno.eu();
  v_equipe := interno.voluntario();
  if not v_equipe and not ((interno.aal2() or not interno.tem_fator()) and exists (select 1 from departamento_membros where usuario = auth.uid())) then perform interno.erro('sem_permissao'); end if;
  v_ve := interno.ve_revolucionarios();
  return (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'descricao', d.descricao,
            'pessoas', case when d.id = 'revolucionarios' and not v_ve then null
                            else (select count(*) from perfis f where interno.membro_direto(f.id, d.id)
                                    and (d.id <> 'representantes' or v_ve
                                         or exists (select 1 from departamento_membros m where m.usuario = f.id and m.departamento = 'representantes')
                                         or exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina is distinct from 'revolucionarios'))) end,
            'pedidos', (select count(*) from departamento_pedidos p where p.para = d.id and p.status in ('aberto', 'aceito')),
            'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id)) order by d.id), '[]'::jsonb)
          from departamentos_info d where v_equipe or interno.membro_direto(auth.uid(), d.id));
end $$;

-- ── 3. Inscrições: militante só com e-mail confirmado, sem oráculo, sem nada sensível em e-mail ───────────────────────

/** Os pedidos de voluntariado que esperam a coordenação, para a supervisão acompanhar. A inscrição militante, não (dado sensível). */
create or replace function public.pedidos_supervisao() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.supervisor() then perform interno.erro('sem_permissao'); end if;
  return (
    select coalesce(jsonb_agg(x.j order by x.criado_em), '[]'::jsonb) from (
      select i.criado_em, jsonb_build_object('id', i.id, 'origem', 'formulario', 'nome', i.nome, 'papel', i.papel, 'disciplina', i.disciplina, 'mensagem', i.mensagem, 'criado_em', i.criado_em) as j
      from inscricoes i where i.status = 'pendente' and i.tipo <> 'militante'
      union all
      select c.criado_em, jsonb_build_object('id', c.id, 'origem', 'painel', 'nome', coalesce(f.nome, ''), 'papel', c.papel, 'disciplina', c.disciplina, 'mensagem', c.mensagem, 'criado_em', c.criado_em)
      from candidaturas c left join perfis f on f.id = c.usuario where c.status = 'pendente') x);
end $$;

-- A inscrição militante esperando a confirmação do e-mail. Só o resumo do código (interno.selo) fica guardado; some em 3
-- dias se ninguém confirmar. Sem consentimento_em: o consentimento só vale de quem provou ser dona do endereço.
create table if not exists interno.inscricoes_a_confirmar (
  id uuid primary key default gen_random_uuid(),
  selo text not null unique,
  nome text not null,
  email text not null,
  papel text not null,
  disciplina text,
  mensagem text not null,
  instagram text,
  criado_em timestamptz not null default now()
);
create index if not exists inscricoes_a_confirmar_email on interno.inscricoes_a_confirmar (email, criado_em);
alter table interno.inscricoes_a_confirmar enable row level security;
revoke all on interno.inscricoes_a_confirmar from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then revoke all on interno.inscricoes_a_confirmar from anon, authenticated; end if;
end $$;

/**
 * Quem quer ser voluntário (ou militante, T15) preenche o formulário, sem conta. Igual a antes, com três mudanças (T33):
 *  - pedido repetido, ou e-mail que já recebeu dois pedidos no dia, recebe a MESMA resposta de sucesso e nada é gravado
 *    nem enviado (antes, "ja_pediu" dizia a qualquer um se um e-mail tinha inscrição militante);
 *  - a inscrição militante fica esperando a confirmação do e-mail: vai só um e-mail neutro com o link (sem citar a Frente
 *    nem militância), e nada chega à coordenação antes do clique (public.inscricao_confirmar);
 *  - o aviso à liderança de inscrição militante não leva os dados da pessoa no corpo do e-mail (o de voluntariado segue igual).
 */
create or replace function public.voluntariar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_papel text := coalesce(p ->> 'papel', '');
  v_disc text := interno.disciplina_ok(p ->> 'disciplina');
  v_tipo text := coalesce(nullif(p ->> 'tipo', ''), 'voluntario');
  v_militante boolean;
  v_nome text; v_mensagem text; v_id uuid; v_codigo text;
  v_instagram text := nullif(regexp_replace(btrim(coalesce(p ->> 'instagram', '')), '^@', ''), '');
begin
  perform interno.aberta('voluntariado');
  -- Campo-isca: gente não vê, robô preenche. Finge que deu certo e não guarda nada.
  if coalesce(p ->> 'site', '') <> '' then return jsonb_build_object('id', gen_random_uuid()); end if;
  perform interno.limite('voluntariar', 3, 1440);
  if v_tipo not in ('voluntario', 'militante') then perform interno.erro('invalido:tipo'); end if;
  v_militante := v_tipo = 'militante';
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or char_length(v_email) > 200 then perform interno.erro('invalido:email'); end if;
  if v_papel not in ('curadoria', 'mediacao', 'educacao', 'educacao_secundaria', 'revisao', 'traducao', 'jornalismo', 'mentoria', 'design', 'marketing', 'desenvolvimento', 'porta_voz', 'saude') then perform interno.erro('invalido:papel'); end if;
  if v_papel in ('educacao', 'educacao_secundaria', 'mentoria') and v_disc is null then perform interno.erro('invalido:disciplina'); end if;
  if v_papel not in ('educacao', 'educacao_secundaria', 'mentoria') then v_disc := null; end if;
  -- Militante: consentimento destacado para o dado sensível (LGPD, art. 11, I) e 18 anos ou mais (LGPD, art. 14).
  if v_militante and coalesce(p ->> 'consentimento', '') <> 'true' then perform interno.erro('invalido:consentimento'); end if;
  if v_militante and coalesce(p ->> 'maior_idade', '') <> 'true' then perform interno.erro('invalido:idade'); end if;
  v_nome := interno.txt(p ->> 'nome', 'nome', 5, 120);
  -- Nome e sobrenome: a coordenação precisa saber quem está pedindo acesso.
  if array_length(regexp_split_to_array(btrim(v_nome), '\s+'), 1) < 2 then perform interno.erro('invalido:nome'); end if;
  if v_instagram is not null and v_instagram !~ '^[A-Za-z0-9._]{1,30}$' then perform interno.erro('invalido:instagram'); end if;
  v_mensagem := interno.txt(p ->> 'mensagem', 'mensagem', 30, 2000);
  if interno.vetado(v_nome || ' ' || v_mensagem) then perform interno.erro('conteudo_recusado'); end if;
  if random() < 0.05 then delete from inscricoes_a_confirmar where criado_em < now() - interval '3 days'; end if;
  -- Repetido, ou o mesmo e-mail com pedidos demais no dia: a resposta é igual à de sucesso, e nada é gravado nem enviado.
  if exists (select 1 from inscricoes where email = v_email and papel = v_papel and tipo = v_tipo and status = 'pendente')
     or (v_militante and exists (select 1 from inscricoes_a_confirmar where email = v_email and papel = v_papel and criado_em > now() - interval '3 days'))
     or (select count(*) from inscricoes where email = v_email and criado_em > now() - interval '1 day')
        + (select count(*) from inscricoes_a_confirmar where email = v_email and criado_em > now() - interval '1 day') >= 2 then
    return jsonb_build_object('id', gen_random_uuid());
  end if;
  if v_militante then
    v_codigo := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
    insert into inscricoes_a_confirmar (selo, nome, email, papel, disciplina, mensagem, instagram)
      values (interno.selo(v_codigo), v_nome, v_email, v_papel, v_disc, v_mensagem, v_instagram)
      returning id into v_id;
    -- Neutro de propósito: a caixa de e-mail pode ser do trabalho ou da família, e o endereço pode nem ser de quem preencheu.
    perform interno.email(v_email, 'inscricao_recebida', 'Confirme o seu e-mail no Instituto Lúcia',
      E'Olá.\n\nEste endereço foi informado num formulário do Instituto Lúcia. Para confirmar que foi você, abra o endereço abaixo (ele vale por 3 dias e só funciona uma vez):\n\n'
      || interno.endereco() || '/pt/voluntarios?confirmar=' || v_codigo
      || E'\n\nSe não foi você, é só ignorar esta mensagem: nada fica guardado, e o pedido some sozinho em 3 dias.');
    return jsonb_build_object('id', v_id);
  end if;
  insert into inscricoes (nome, email, papel, disciplina, mensagem, instagram, tipo)
    values (v_nome, v_email, v_papel, v_disc, v_mensagem, v_instagram, 'voluntario')
    returning id into v_id;
  perform interno.email(v_email, 'inscricao_recebida', 'Recebemos seu pedido de voluntariado',
    'Olá, ' || coalesce(nullif(left(split_part(interno.sem_link(v_nome), ' ', 1), 40), ''), 'tudo bem') || E'.\n\nRecebemos seu pedido para atuar como voluntário(a) no Instituto Lúcia, na função de ' || interno.nome_papel(v_papel) || E'.\n\n'
    || E'A coordenação lê cada pedido e responde por este mesmo endereço. Se o pedido for aceito, chega aqui o link para você criar a sua conta e entrar no painel da equipe.\n\n'
    || 'Se não foi você quem enviou este pedido, é só ignorar esta mensagem.');
  perform interno.email_lideranca('inscricao_nova', 'Novo pedido de voluntariado: ' || left(interno.sem_link(v_nome), 60),
    interno.sem_link(v_nome) || ' (' || v_email || coalesce(', Instagram @' || v_instagram, '') || ') quer atuar na função de ' || interno.nome_papel(v_papel) || E'.\n\nLeia o pedido e decida no painel: ' || interno.endereco() || '/pt/painel?aba=pessoas');
  return jsonb_build_object('id', v_id);
end $$;

/**
 * O clique no link do e-mail: a inscrição militante passa a existir, com o consentimento registrado agora (de quem provou
 * ser dona do endereço), e a liderança recebe um aviso sem dado nenhum da pessoa. Código errado, vencido ou já usado:
 * "nao_encontrado", sem dizer qual.
 */
create or replace function public.inscricao_confirmar(p_codigo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare c inscricoes_a_confirmar;
begin
  perform interno.aberta('voluntariado');
  perform interno.limite('inscricao_confirmar', 20, 60);
  if coalesce(p_codigo, '') !~ '^[0-9a-f]{64}$' then perform interno.erro('nao_encontrado'); end if;
  delete from inscricoes_a_confirmar where selo = interno.selo(p_codigo) returning * into c;
  if c.id is null or c.criado_em < now() - interval '3 days' then perform interno.erro('nao_encontrado'); end if;
  if not exists (select 1 from inscricoes where email = c.email and papel = c.papel and tipo = 'militante' and status = 'pendente') then
    insert into inscricoes (nome, email, papel, disciplina, mensagem, instagram, tipo, consentimento_em, maior_idade)
      values (c.nome, c.email, c.papel, c.disciplina, c.mensagem, c.instagram, 'militante', now(), true);
    perform interno.email_lideranca('inscricao_nova', 'Há uma inscrição nova no painel',
      E'Há uma inscrição nova esperando no painel. Leia e decida em: ' || interno.endereco() || '/pt/painel?aba=pessoas');
  end if;
  return jsonb_build_object('ok', true);
end $$;

-- ── 4. Chat privado da Alumia: provas guardadas, recusas respeitadas, versões com limite ─────────────────────────────

-- Quando cada participante apagou a conversa da própria lista. Mensagem anterior a essa hora some só para quem apagou; a
-- outra pessoa continua com ela até o prazo (e pode denunciar). Quando os dois apagam, o que os dois apagaram some de vez.
alter table interno.rede_dm_conversas add column if not exists a_apagou_em timestamptz;
alter table interno.rede_dm_conversas add column if not exists b_apagou_em timestamptz;

/** Limites do chat, por pessoa. Igual a antes, mais "versao" (versão nova da chave da conversa): 20 por hora. */
create or replace function interno.rede_dm_limite(p_acao text) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_teto integer; v_minutos integer := 60;
  v_nova boolean := exists (select 1 from auth.users u where u.id = auth.uid() and u.created_at > now() - interval '3 days');
begin
  v_teto := case p_acao when 'enviar' then 120 when 'pedir' then 20 when 'ler' then 1200 when 'chave' then 10 when 'denunciar' then 10 when 'apagar' then 200 when 'versao' then 20 else null end;
  if v_teto is null then perform interno.erro('acao_desconhecida'); end if;
  if p_acao in ('pedir', 'chave', 'denunciar') then v_minutos := 1440; end if;
  if v_nova and p_acao <> 'ler' then v_teto := greatest(1, v_teto / 2); end if;
  perform interno.limite('rede_dm_' || p_acao, v_teto, v_minutos);
end $$;

/** O que os dois participantes apagaram some de vez; a conversa que os dois apagaram e ficou vazia também. */
create or replace function interno.rede_dm_podar(p_conversa uuid) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_dm_mensagens m using rede_dm_conversas c
  where c.id = m.conversa and (p_conversa is null or c.id = p_conversa)
    and c.a_apagou_em is not null and c.b_apagou_em is not null and m.criado_em <= least(c.a_apagou_em, c.b_apagou_em);
  delete from rede_dm_conversas c
  where (p_conversa is null or c.id = p_conversa) and c.a_apagou_em is not null and c.b_apagou_em is not null
    and not exists (select 1 from rede_dm_mensagens m where m.conversa = c.id);
end $$;

/** A faxina do chat. Igual a antes, mais a poda do que os dois participantes apagaram. */
create or replace function interno.rede_dm_faxina() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_dm_mensagens where expira_em <= now();
  delete from rede_dm_conversas where situacao = 'pedido' and criado_em < now() - interval '30 days';
  delete from rede_dm_recusas where ate <= now();
  perform interno.rede_dm_podar(null);
  -- Embrulhos de versões antigas, sem nenhuma mensagem viva que precise deles (a versão atual fica sempre).
  delete from rede_dm_embrulhos e using rede_dm_conversas c
  where c.id = e.conversa and e.versao < c.versao
    and not exists (select 1 from rede_dm_mensagens m where m.conversa = e.conversa and m.versao = e.versao);
end $$;

/** Minhas conversas e pedidos. Igual a antes; a conversa que apaguei só volta à lista se chegar mensagem nova. */
create or replace function public.rede_dm_conversas() returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede_dm_limite('ler');
  perform interno.rede_dm_talvez_faxina();
  return coalesce((
    select jsonb_agg(interno.rede_dm_json(c, v) order by c.ultima_em desc)
    from rede_dm_conversas c
    where (c.a = v or c.b = v) and not (c.situacao = 'pedido' and interno.rede_bloqueado(v, interno.rede_dm_outro(c, v)))
      and not (case when c.a = v then c.a_apagou_em else c.b_apagou_em end is not null and c.ultima_em <= case when c.a = v then c.a_apagou_em else c.b_apagou_em end)
  ), '[]'::jsonb);
end $$;

/** As mensagens (cifradas). Igual a antes; quem apagou a conversa não vê mais o que veio antes de apagar. */
create or replace function public.rede_dm_mensagens(p_conversa uuid, p_antes timestamptz default null, p_limite integer default 50) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas; v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 100); v_desde timestamptz;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede_dm_limite('ler');
  c := interno.rede_dm_minha(p_conversa, v);
  if c.situacao <> 'aberta' then perform interno.erro('dm_fechada'); end if;
  v_desde := coalesce(case when c.a = v then c.a_apagou_em else c.b_apagou_em end, '-infinity'::timestamptz);
  if p_antes is null then
    update rede_dm_conversas set a_leu_em = case when a = v then now() else a_leu_em end, b_leu_em = case when b = v then now() else b_leu_em end where id = c.id;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'autor', x.autor, 'versao', x.versao, 'corpo', x.corpo, 'criado_em', x.criado_em, 'expira_em', x.expira_em) order by x.criado_em desc)
    from (select * from rede_dm_mensagens m where m.conversa = c.id and m.expira_em > now() and m.criado_em > v_desde and (p_antes is null or m.criado_em < p_antes)
          order by m.criado_em desc limit v_limite) x
  ), '[]'::jsonb);
end $$;

/**
 * Apaga uma mensagem minha, para os dois. Depois de bloqueio (de qualquer lado) ou com denúncia aberta da outra pessoa
 * contra mim, não: a mensagem é prova (ECA art. 241-D; Marco Civil art. 10) e some sozinha no prazo da conversa.
 */
create or replace function public.rede_dm_apagar_mensagem(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); m rede_dm_mensagens; c rede_dm_conversas; o uuid;
begin
  perform interno.rede_dm_limite('apagar');
  select * into m from rede_dm_mensagens where id = p_id and autor = v;
  if not found then perform interno.erro('nao_encontrado'); end if;
  select * into c from rede_dm_conversas where id = m.conversa;
  o := interno.rede_dm_outro(c, v);
  if interno.rede_bloqueado(v, o)
     or exists (select 1 from rede_denuncias d where d.quem = o and d.alvo_tipo = 'perfil' and d.alvo = v::text and d.situacao in ('aberta', 'em_analise')) then
    perform interno.erro('dm_fechada');
  end if;
  delete from rede_dm_mensagens where id = m.id;
  return jsonb_build_object('ok', true);
end $$;

/**
 * Apaga a conversa da MINHA lista (LGPD art. 18, VI): o que veio antes some para mim. A outra pessoa continua com as
 * mensagens até o prazo da conversa, e pode denunciar; quando ela também apagar, tudo some de vez. Pedido sem resposta: some.
 */
create or replace function public.rede_dm_apagar(p_conversa uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas;
begin
  perform interno.rede_dm_limite('apagar');
  c := interno.rede_dm_minha(p_conversa, v);
  if c.situacao = 'pedido' then
    delete from rede_dm_conversas where id = c.id;
    return jsonb_build_object('ok', true);
  end if;
  update rede_dm_conversas set
    a_apagou_em = case when a = v then now() else a_apagou_em end, b_apagou_em = case when b = v then now() else b_apagou_em end,
    a_leu_em = case when a = v then now() else a_leu_em end, b_leu_em = case when b = v then now() else b_leu_em end
  where id = c.id;
  perform interno.rede_dm_podar(c.id);
  return jsonb_build_object('ok', true);
end $$;

/** Prazo das mensagens desta conversa (1, 7 ou 30 dias). Vale para as mensagens NOVAS: encurtar não apaga o que já foi escrito. */
create or replace function public.rede_dm_prazo(p_conversa uuid, p_dias integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_dm_conversas;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if coalesce(p_dias, 0) not in (1, 7, 30) then perform interno.erro('invalido:prazo'); end if;
  c := interno.rede_dm_minha(p_conversa, v);
  update rede_dm_conversas set prazo_dias = p_dias where id = c.id;
  return jsonb_build_object('prazo_dias', p_dias);
end $$;

/**
 * Apaga tudo o que é meu no chat (chave, preferências, as recusas que EU fiz) e tira todas as conversas da minha lista,
 * sem apagar a conta (LGPD art. 18, VI). As recusas que outras pessoas fizeram contra mim ficam (são delas, até vencer),
 * e as mensagens ficam com a outra pessoa até o prazo de cada conversa.
 */
create or replace function public.rede_dm_apagar_tudo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); n integer;
begin
  perform interno.rede_dm_limite('apagar');
  select count(*) into n from rede_dm_conversas where a = v or b = v;
  delete from rede_dm_conversas where (a = v or b = v) and situacao = 'pedido';
  update rede_dm_conversas set
    a_apagou_em = case when a = v then now() else a_apagou_em end, b_apagou_em = case when b = v then now() else b_apagou_em end,
    a_leu_em = case when a = v then now() else a_leu_em end, b_leu_em = case when b = v then now() else b_leu_em end
  where a = v or b = v;
  perform interno.rede_dm_podar(null);
  delete from rede_dm_chaves where usuario = v;
  delete from rede_dm_prefs where usuario = v;
  delete from rede_dm_recusas where quem = v;
  return jsonb_build_object('conversas', n);
end $$;

/**
 * Uma versão nova da chave da conversa. Igual a antes, com freio: 20 por hora por pessoa, e nenhuma versão nova enquanto a
 * atual tem menos de 5 minutos e já está embrulhada para a chave atual dos dois (trocar de aparelho continua valendo na hora).
 */
create or replace function public.rede_dm_nova_versao(p_conversa uuid, p_versao integer, p_embrulhos jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); c rede_dm_conversas; o uuid; minha rede_dm_chaves; e jsonb; k rede_dm_chaves; v_para uuid; n integer := 0;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  select * into c from rede_dm_conversas where id = p_conversa and (a = v or b = v) for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  o := interno.rede_dm_outro(c, v);
  if c.situacao <> 'aberta' or interno.rede_bloqueado(v, o) or not interno.rede2_membro(o) then perform interno.erro('dm_fechada'); end if;
  if p_versao is distinct from c.versao + 1 then perform interno.erro('versao_desatualizada'); end if;
  if c.versao > 0 and c.versao_em > now() - interval '5 minutes'
     and (select count(*) from rede_dm_embrulhos x join rede_dm_chaves kk on kk.usuario = x.para and kk.versao = x.chave_versao
          where x.conversa = c.id and x.versao = c.versao) = 2 then
    perform interno.erro('versao_desatualizada');
  end if;
  perform interno.rede_dm_limite('versao');
  select * into minha from rede_dm_chaves where usuario = v;
  if not found then perform interno.erro('dm_sem_chave'); end if;
  if jsonb_typeof(p_embrulhos) <> 'array' or jsonb_array_length(p_embrulhos) <> 2 then perform interno.erro('invalido:embrulhos'); end if;
  for e in select * from jsonb_array_elements(p_embrulhos) loop
    begin v_para := (e ->> 'para')::uuid; exception when others then perform interno.erro('invalido:embrulhos'); end;
    if v_para not in (c.a, c.b) then perform interno.erro('invalido:embrulhos'); end if;
    select * into k from rede_dm_chaves where usuario = v_para;
    if not found then perform interno.erro('dm_sem_chave'); end if;
    if (e ->> 'chave_versao')::integer is distinct from k.versao then perform interno.erro('versao_desatualizada'); end if;
    if coalesce(e ->> 'embrulho', '') !~ '^w1\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{64}$' then perform interno.erro('invalido:embrulho'); end if;
    insert into rede_dm_embrulhos (conversa, versao, para, chave_versao, embrulho, de, de_publica, de_certificado)
    values (c.id, p_versao, v_para, k.versao, e ->> 'embrulho', v, minha.publica, minha.certificado);
    n := n + 1;
  end loop;
  if n <> 2 or (select count(distinct para) from rede_dm_embrulhos where conversa = c.id and versao = p_versao) <> 2 then perform interno.erro('invalido:embrulhos'); end if;
  update rede_dm_conversas set versao = p_versao, versao_em = now() where id = c.id;
  perform interno.rede_dm_talvez_faxina();
  return jsonb_build_object('versao', p_versao);
end $$;

-- ── 5. Faxina e permissões ──────────────────────────────────────────────────────────────────────────────────────────

/** A faxina desta auditoria: origem de quem não entra há 30 dias e inscrições militantes não confirmadas em 3 dias. */
create or replace function interno.t33_faxina() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  update perfis set origem = null where origem is not null and (visto_em is null or visto_em < now() - interval '30 days');
  delete from inscricoes_a_confirmar where criado_em < now() - interval '3 days';
end $$;
select interno.t33_faxina();
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-t33-faxina', '47 5 * * *', 'select interno.t33_faxina()');
  end if;
exception when others then null;
end $$;

revoke all on function interno.ve_revolucionarios(), interno.papel_visivel(uuid, text), interno.auditoria_reservada(interno.auditoria),
  interno.departamento_pedido_json(interno.departamento_pedidos), interno.rede_dm_podar(uuid), interno.rede_dm_limite(text),
  interno.rede_dm_faxina(), interno.t33_faxina() from public;
do $$
declare f record;
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.ve_revolucionarios(), interno.papel_visivel(uuid, text), interno.auditoria_reservada(interno.auditoria),
      interno.departamento_pedido_json(interno.departamento_pedidos), interno.rede_dm_podar(uuid), interno.rede_dm_limite(text),
      interno.rede_dm_faxina(), interno.t33_faxina(), interno.origem() from anon, authenticated;
  end if;
  -- As funções da API redefinidas aqui: as mesmas permissões de antes.
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('papel_remover', 'auditoria_listar', 'equipe', 'equipe_supervisao', 'equipe_membros', 'voluntarios_listar',
             'departamento_ver', 'departamentos_resumo', 'pedidos_supervisao', 'voluntariar', 'inscricao_confirmar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
    end if;
  end loop;
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('rede_dm_conversas', 'rede_dm_mensagens', 'rede_dm_apagar_mensagem', 'rede_dm_apagar', 'rede_dm_prazo',
             'rede_dm_apagar_tudo', 'rede_dm_nova_versao') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon', f.assinatura);
      execute format('grant execute on function %s to authenticated', f.assinatura);
    end if;
  end loop;
end $$;


-- ───────────────────────────── Escola de Formação (F1): militância e tabelas da Escola, novembro de 2026 ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Quem junta cola este bloco no fim do
-- install.sql (ordem da Escola: F1, F4, F5, F3, F6). Plano: docs/plano-2026-11/PLANO-ESCOLA.md, seção 4.1.
-- Teste: npm run testar:escola-acesso (Postgres de verdade dentro do Node, com o install.sql e esta migração).
--
-- O que nasce aqui (TODAS as tabelas da Escola fechada; as funções de cada tela vêm nas migrações das outras frentes):
--  1. interno.e_militante(p): quem está no departamento Revolucionários (ou a coordenação, para si mesma). Conta suspensa não é.
--  2. Tabelas: escola_militancia, escola_encontros, escola_encontro_tarefas, escola_perguntas, escola_recados,
--     escola_bancas, escola_conquistas; e perfis.escola_publico (padrão 'ninguem').
--  3. Gatilho em departamento_membros: entrar nos Revolucionários cria a militância e a conquista 'carteirinha'
--     verificada; sair apaga a militância, as conquistas e as bancas (direito de eliminação, LGPD art. 18, VI).
--  4. public.escola_eu(): a única função de leitura desta frente. Quem não é militante recebe só {militante:false}.
--
-- Segurança (mesma regra de migracoes/2026-11-escola.sql): toda tabela em "interno", com segurança por linha ligada e
-- sem permissão nenhuma para public, anon e authenticated. Só funções security definer, com search_path fixo, leem.
-- Ser militante revela opinião política (dado sensível, LGPD art. 5º, II e art. 11): nada de nome civil aqui (a
-- Escola mostra o codinome da Alumia, perfis.rede_codinome) e nada de militância no registro com o nome do departamento.

-- 1. Quem é militante ────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * Militante = do departamento Revolucionários (pela participação ou por representá-lo), com a conta ativa. A coordenação
 * também entra na Escola, mas só ela mesma (a checagem da coordenação olha a sessão de quem chama, com o segundo fator).
 */
create or replace function interno.e_militante(p uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p is not null and coalesce(interno.membro_direto(p, 'revolucionarios') or (p = auth.uid() and interno.coord()), false)
$$;

-- 2. As tabelas ──────────────────────────────────────────────────────────────────────────────────────────────────────────
-- Uma linha por militante: o degrau (1 Despertar, 2 Base, 3 Quadros), a frente de atuação, o núcleo da Alumia e quem acompanha.
create table if not exists interno.escola_militancia (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  degrau smallint not null default 1 check (degrau between 1 and 3),
  frente text check (frente is null or frente in ('estudantil', 'bairros', 'trabalho', 'agitprop', 'atos', 'cultura', 'solidariedade')),
  nucleo uuid references interno.rede_nucleos (id) on delete set null,
  acompanha uuid references interno.perfis (id) on delete set null,
  desde date not null default ((now() at time zone 'America/Sao_Paulo')::date),
  constraint escola_militancia_acompanha_outra check (acompanha is distinct from usuario)
);
create index if not exists escola_militancia_nucleo on interno.escola_militancia (nucleo);
create index if not exists escola_militancia_acompanha on interno.escola_militancia (acompanha);

-- Os encontros do núcleo: quando, a pauta (até 12 itens), a presença SOMADA (só o número) e o balanço.
create table if not exists interno.escola_encontros (
  id uuid primary key default gen_random_uuid(),
  nucleo uuid not null references interno.rede_nucleos (id) on delete cascade,
  quando timestamptz not null,
  pauta jsonb not null default '[]'::jsonb check (jsonb_typeof(pauta) = 'array' and jsonb_array_length(pauta) <= 12),
  presenca smallint check (presenca is null or presenca between 0 and 500),
  balanco text not null default '' check (char_length(balanco) <= 2000),
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now()
);
create index if not exists escola_encontros_nucleo on interno.escola_encontros (nucleo, quando);

-- Quem faz o quê (encaminhamentos do encontro, em rodízio).
create table if not exists interno.escola_encontro_tarefas (
  id uuid primary key default gen_random_uuid(),
  encontro uuid not null references interno.escola_encontros (id) on delete cascade,
  item text not null check (char_length(item) between 2 and 120),
  quem uuid references interno.perfis (id) on delete set null,
  feito boolean not null default false,
  criado_em timestamptz not null default now()
);
create index if not exists escola_encontro_tarefas_encontro on interno.escola_encontro_tarefas (encontro);

-- A pergunta geradora da semana (a semana começa na segunda-feira).
create table if not exists interno.escola_perguntas (
  semana date primary key check (extract(isodow from semana) = 1),
  texto text not null check (char_length(texto) between 3 and 300),
  por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now()
);

-- Recados da formação: para toda a Escola (nucleo nulo) ou para um núcleo, até uma data.
create table if not exists interno.escola_recados (
  id uuid primary key default gen_random_uuid(),
  texto text not null check (char_length(texto) between 3 and 400),
  ate date not null,
  nucleo uuid references interno.rede_nucleos (id) on delete cascade,
  por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now()
);
create index if not exists escola_recados_ate on interno.escola_recados (ate);

-- A banca de passagem de degrau (balanço coletivo, sem nota). O balanço só é lido pelo militante, quem acompanha e a coordenação.
create table if not exists interno.escola_bancas (
  id uuid primary key default gen_random_uuid(),
  militante uuid not null references interno.perfis (id) on delete cascade,
  degrau smallint not null check (degrau between 1 and 3),
  nucleo uuid references interno.rede_nucleos (id) on delete set null,
  quando timestamptz,
  situacao text not null default 'marcada' check (situacao in ('marcada', 'aprovada', 'refazer')),
  balanco text not null default '' check (char_length(balanco) <= 2000),
  por uuid references interno.perfis (id) on delete set null,
  decidida_em timestamptz,
  criado_em timestamptz not null default now()
);
create index if not exists escola_bancas_militante on interno.escola_bancas (militante);

-- Conquistas: a carteirinha e o degrau são verificados pelo servidor; aula e caderno são declarados pelo aparelho (F5).
create table if not exists interno.escola_conquistas (
  usuario uuid not null references interno.perfis (id) on delete cascade,
  tipo text not null check (tipo in ('carteirinha', 'aula', 'caderno', 'degrau')),
  alvo text not null check (alvo ~ '^[a-z0-9/-]{1,160}$'),
  verificada boolean not null default false,
  em timestamptz not null default now(),
  primary key (usuario, tipo, alvo)
);

-- Quem vê as conquistas da Escola no perfil da Alumia. Padrão: ninguém (o selo da Alumia nasce ligado; este, não).
alter table interno.perfis add column if not exists escola_publico text not null default 'ninguem';
do $$
begin
  alter table interno.perfis add constraint perfis_escola_publico check (escola_publico in ('ninguem', 'militantes', 'seguidores', 'todos'));
exception when duplicate_object then null;
end $$;

-- Trancadas duas vezes: segurança por linha ligada sem regra nenhuma (ninguém passa) e sem permissão para os papéis da API.
do $$
declare tabela text;
begin
  foreach tabela in array array['escola_militancia', 'escola_encontros', 'escola_encontro_tarefas', 'escola_perguntas', 'escola_recados', 'escola_bancas', 'escola_conquistas'] loop
    execute format('alter table interno.%I enable row level security', tabela);
    execute format('revoke all on interno.%I from public', tabela);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on interno.%I from anon, authenticated', tabela);
    end if;
  end loop;
  -- Com a pausa geral ligada, nada novo entra de quem não é da equipe (como no resto do site). A militância e as
  -- conquistas ficam de fora: nascem do gatilho do departamento, e a pausa não pode impedir alguém de ser tirado ou posto.
  foreach tabela in array array['escola_encontros', 'escola_encontro_tarefas', 'escola_perguntas', 'escola_recados', 'escola_bancas'] loop
    execute format('drop trigger if exists lucia_pausa on interno.%I', tabela);
    execute format('create trigger lucia_pausa before insert on interno.%I for each row execute function interno.pausa()', tabela);
  end loop;
end $$;

-- 3. Entrar e sair do departamento ───────────────────────────────────────────────────────────────────────────────────────
/** Cria a militância e a carteirinha (verificada). Rodar de novo não muda nada. */
create or replace function interno.escola_militancia_criar(p uuid) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if p is null then return; end if;
  insert into escola_militancia (usuario) values (p) on conflict (usuario) do nothing;
  insert into escola_conquistas (usuario, tipo, alvo, verificada) values (p, 'carteirinha', 'carteirinha', true)
  on conflict (usuario, tipo, alvo) do update set verificada = true;
end $$;

/** Sair da militância apaga o que a Escola guardou da pessoa no servidor (LGPD art. 18, VI) e solta quem ela acompanhava. */
create or replace function interno.escola_militancia_apagar(p uuid) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if p is null then return; end if;
  delete from escola_militancia where usuario = p;
  delete from escola_conquistas where usuario = p;
  delete from escola_bancas where militante = p;
  update escola_militancia set acompanha = null where acompanha = p;
  update escola_encontro_tarefas set quem = null where quem = p;
end $$;

create or replace function interno.escola_departamento_gatilho() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if tg_op in ('UPDATE', 'DELETE') and old.departamento = 'revolucionarios'
     and (tg_op = 'DELETE' or new.departamento is distinct from 'revolucionarios' or new.usuario is distinct from old.usuario) then
    -- Quem continua militante por outro caminho (representa o departamento) não perde nada.
    if not interno.membro_direto(old.usuario, 'revolucionarios') then perform interno.escola_militancia_apagar(old.usuario); end if;
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.departamento = 'revolucionarios' then
    perform interno.escola_militancia_criar(new.usuario);
  end if;
  return null;
end $$;
drop trigger if exists lucia_escola_militancia on interno.departamento_membros;
create trigger lucia_escola_militancia after insert or update or delete on interno.departamento_membros for each row execute function interno.escola_departamento_gatilho();

-- Representar o departamento (papeis: papel 'representante', disciplina 'revolucionarios') também faz militante, e tirar
-- esse papel apaga a militância como sair do departamento (LGPD art. 18, VI), a menos que a pessoa continue por outro caminho.
create or replace function interno.escola_papel_gatilho() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if tg_op in ('UPDATE', 'DELETE') and (old.papel = 'revolucionarios' or (old.papel = 'representante' and old.disciplina = 'revolucionarios')) then
    if not interno.membro_direto(old.usuario, 'revolucionarios') then perform interno.escola_militancia_apagar(old.usuario); end if;
  end if;
  if tg_op in ('INSERT', 'UPDATE') and (new.papel = 'revolucionarios' or (new.papel = 'representante' and new.disciplina = 'revolucionarios'))
     and interno.membro_direto(new.usuario, 'revolucionarios') then
    perform interno.escola_militancia_criar(new.usuario);
  end if;
  return null;
end $$;
drop trigger if exists lucia_escola_militancia on interno.papeis;
create trigger lucia_escola_militancia after insert or update or delete on interno.papeis for each row execute function interno.escola_papel_gatilho();

-- Faxina de quem já tinha perdido a militância antes deste gatilho (rodar de novo não apaga quem ainda é militante).
do $$
declare u uuid;
begin
  for u in select e.usuario from interno.escola_militancia e where not interno.membro_direto(e.usuario, 'revolucionarios') loop
    perform interno.escola_militancia_apagar(u);
  end loop;
end $$;

-- Quem já estava no departamento quando a migração rodou (rodar de novo não duplica nada).
insert into interno.escola_militancia (usuario)
select m.usuario from interno.departamento_membros m where m.departamento = 'revolucionarios'
on conflict (usuario) do nothing;
insert into interno.escola_conquistas (usuario, tipo, alvo, verificada)
select m.usuario, 'carteirinha', 'carteirinha', true from interno.departamento_membros m where m.departamento = 'revolucionarios'
on conflict (usuario, tipo, alvo) do nothing;

-- 4. Quem sou eu na Escola ───────────────────────────────────────────────────────────────────────────────────────────────
/**
 * A porta da Escola pergunta isto. Sem conta, conta suspensa ou sem militância: só {militante:false} (e "conta", para a
 * porta saber se oferece "Entrar"). Militante: o codinome da Alumia (nunca o nome civil), o degrau, a frente, o núcleo,
 * quem acompanha (pelo codinome e o @ da Alumia, se a pessoa não estiver invisível), desde quando e o público das conquistas.
 * Quem representa o departamento (sem a linha de participação) ganha a militância aqui, na primeira vez.
 */
create or replace function public.escola_eu() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := auth.uid();
  f perfis;
  m escola_militancia;
  n jsonb;
  a jsonb;
begin
  if v is null then return jsonb_build_object('militante', false, 'conta', false); end if;
  select * into f from perfis where id = v;
  if not found or f.suspenso or not interno.e_militante(v) then return jsonb_build_object('militante', false, 'conta', true); end if;
  perform interno.limite('escola_eu', 60, 1);
  if interno.membro_direto(v, 'revolucionarios') then perform interno.escola_militancia_criar(v); end if;
  select * into m from escola_militancia where usuario = v;
  if m.nucleo is not null then
    select jsonb_build_object('id', r.id, 'nome', r.nome) into n from rede_nucleos r where r.id = m.nucleo;
  end if;
  if m.acompanha is not null then
    select jsonb_build_object(
      'codinome', case when p.rede_codinome_ok then p.rede_codinome end,
      'handle', case when not coalesce(p.rede_modo = 'invisivel' or p.rede_invisivel, false) then p.rede_handle end)
    into a from perfis p where p.id = m.acompanha and not p.suspenso;
  end if;
  return jsonb_build_object(
    'militante', true,
    'conta', true,
    'codinome', case when f.rede_codinome_ok then f.rede_codinome end,
    'handle', f.rede_handle,
    'degrau', coalesce(m.degrau, 1),
    'frente', m.frente,
    'nucleo', n,
    'acompanha', a,
    'desde', m.desde,
    'publico', f.escola_publico,
    'coordena', interno.coord());
end $$;

-- 5. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
-- O install.sql dá USAGE em "interno" para anon e authenticated: sem isto, uma conta poderia criar ou apagar a militância de
-- qualquer uuid, ou saber se qualquer uuid é militante. As funções internas só rodam por dentro das security definer.
revoke all on function interno.e_militante(uuid), interno.escola_militancia_criar(uuid), interno.escola_militancia_apagar(uuid),
  interno.escola_departamento_gatilho(), interno.escola_papel_gatilho() from public;
revoke all on function public.escola_eu() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.e_militante(uuid), interno.escola_militancia_criar(uuid), interno.escola_militancia_apagar(uuid),
      interno.escola_departamento_gatilho(), interno.escola_papel_gatilho() from anon, authenticated;
    grant execute on function public.escola_eu() to anon, authenticated, service_role;
  end if;
end $$;


-- ───────────────────────────── Escola de Formação (F4): núcleo, acompanhamento, banca e painel, novembro de 2026 ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Precisa da F1 (20261108-escola-formacao-base.sql:
-- as tabelas nascem lá). Quem junta cola este bloco no fim do install.sql, DEPOIS da F1 (ordem: F1, F4, F5, F3, F6).
-- Plano: docs/plano-2026-11/PLANO-ESCOLA.md, seções 3 e 4.4. Teste: npm run testar:escola-nucleo.
--
-- O que nasce aqui (funções e um índice; nenhuma tabela nova):
--  1. O encontro do núcleo: escola_nucleo (o próximo encontro, a pauta, quem faz o quê, a presença SOMADA das 4 últimas
--     rodas), escola_encontro_salvar (só a mediação do núcleo na Alumia ou a coordenação), escola_tarefa_pegar ("Eu levo",
--     com rodízio: quem fez a mesma tarefa na roda anterior deixa para outra pessoa) e escola_levar_ao_nucleo (a dúvida
--     vira item da pauta, sem dizer de quem).
--  2. A pergunta geradora da semana (Paulo Freire, círculo de cultura) e os recados da formação.
--  3. Quem acompanha (só alguém do Degrau 3) e a banca de passagem: balanço coletivo, SEM nota. Aprovada, sobe o degrau e
--     grava a conquista verificada 'degrau-N' (N = o degrau que a pessoa fechou).
--  4. O painel da coordenação: militantes pelo codinome, ajuste de núcleo, frente e degrau.
--
-- Segurança (a mesma da F1): só funções security definer com search_path fixo; entrada por interno.eu(); freio por
-- interno.limite; nada de nome civil (codinome da Alumia, e só quando confirmado); no registro de atividades, nada diz
-- "revolucionários": o departamento aparece como 'reservado'. Quem não é militante não recebe nada.

-- 0. Ajudantes e a trava da banca ─────────────────────────────────────────────────────────────────────────────────────
/* Uma banca marcada por vez para cada pessoa, valendo também para pedidos ao mesmo tempo. Se já houver duas marcadas
   (só se alguém as criou antes deste índice), a criação falha: decida uma delas no painel e rode de novo. */
create unique index if not exists escola_bancas_uma_marcada on interno.escola_bancas (militante) where situacao = 'marcada';

/** Uma pessoa como a Escola mostra: o codinome confirmado da Alumia e o @ (que some se ela estiver invisível). */
create or replace function interno.escola_pessoa(p uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select case when p is null then null else (
    select jsonb_build_object(
      'codinome', case when f.rede_codinome_ok then f.rede_codinome end,
      'handle', case when not coalesce(f.rede_modo = 'invisivel' or f.rede_invisivel, false) then f.rede_handle end)
    from perfis f where f.id = p and not f.suspenso) end
$$;

/** Hoje em Brasília. */
create or replace function interno.escola_hoje() returns date language sql stable set search_path = interno, pg_temp as $$
  select (now() at time zone 'America/Sao_Paulo')::date
$$;

/** Quem chama, exigindo militância (ou coordenação). Devolve o id. */
create or replace function interno.escola_militante_eu() returns uuid language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.e_militante(v) then perform interno.erro('sem_permissao'); end if;
  return v;
end $$;

/** O núcleo da Escola de quem chama (nulo se ainda não tem). */
create or replace function interno.escola_meu_nucleo() returns uuid language sql stable security definer set search_path = interno, pg_temp as $$
  select nucleo from escola_militancia where usuario = auth.uid()
$$;

/**
 * Quem pode mexer no encontro, na pauta e nos recados deste núcleo: a coordenação, ou quem faz a MEDIAÇÃO do núcleo na
 * Alumia (rede_nucleo_membros.papel = 'mediacao') e é militante, em sessão confiável (com o segundo fator, se tiver).
 */
create or replace function interno.escola_medeia(p_nucleo uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_nucleo is not null and (interno.coord() or (
    interno.sessao_confiavel() and interno.e_militante(auth.uid())
    and exists (select 1 from rede_nucleo_membros m where m.nucleo = p_nucleo and m.usuario = auth.uid() and m.papel = 'mediacao')))
$$;

/** O encontro "seguinte" de um núcleo: o primeiro que ainda não acabou (até 3 horas depois do começo, a roda ainda vale). */
create or replace function interno.escola_encontro_seguinte(p_nucleo uuid) returns uuid language sql stable security definer set search_path = interno, pg_temp as $$
  select id from escola_encontros where nucleo = p_nucleo and quando >= now() - interval '3 hours' order by quando, criado_em limit 1
$$;

/** O encontro anterior a um momento (a roda que passou). */
create or replace function interno.escola_encontro_anterior(p_nucleo uuid, p_antes timestamptz) returns uuid language sql stable security definer set search_path = interno, pg_temp as $$
  select id from escola_encontros where nucleo = p_nucleo and quando < p_antes order by quando desc, criado_em desc limit 1
$$;

/** Os itens da pauta, limpos: até 12, cada um com 2 a 200 letras; "levado" só quando veio de uma dúvida. */
create or replace function interno.escola_pauta_limpa(p jsonb) returns jsonb language plpgsql immutable set search_path = interno, pg_temp as $$
declare x jsonb; t text; saida jsonb := '[]'::jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'array' then perform interno.erro('invalido:pauta'); end if;
  if jsonb_array_length(p) > 12 then perform interno.erro('invalido:pauta'); end if;
  for x in select value from jsonb_array_elements(p) loop
    t := btrim(regexp_replace(coalesce(case when jsonb_typeof(x) = 'object' then x ->> 'texto' else x #>> '{}' end, ''), '\s+', ' ', 'g'));
    if char_length(t) < 2 or char_length(t) > 200 then perform interno.erro('invalido:pauta'); end if;
    saida := saida || jsonb_build_array(case when jsonb_typeof(x) = 'object' and coalesce((x ->> 'levado')::boolean, false)
      then jsonb_build_object('texto', t, 'levado', true) else jsonb_build_object('texto', t) end);
  end loop;
  return saida;
end $$;

/** Um encontro como o militante vê: pauta, tarefas (quem pelo codinome; "minha"; "repete" = eu fiz esta na roda anterior). */
create or replace function interno.escola_encontro_json(p_id uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare e escola_encontros; v uuid := auth.uid(); antes uuid;
begin
  select * into e from escola_encontros where id = p_id;
  if not found then return null; end if;
  antes := interno.escola_encontro_anterior(e.nucleo, e.quando);
  return jsonb_build_object(
    'id', e.id,
    'quando', e.quando,
    'pauta', e.pauta,
    'tarefas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'item', t.item,
        'quem', interno.escola_pessoa(t.quem),
        'minha', t.quem is not distinct from v and v is not null,
        'feito', t.feito,
        'repete', t.quem is null and exists (select 1 from escola_encontro_tarefas a where a.encontro = antes and a.quem = v and lower(a.item) = lower(t.item)))
        order by t.criado_em, t.id)
      from escola_encontro_tarefas t where t.encontro = e.id), '[]'::jsonb));
end $$;

-- 1. O núcleo ────────────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * O núcleo de quem chama: o nome, o encontro seguinte (pauta e quem faz o quê), a roda que passou (presença e balanço, para
 * quem é do núcleo) e a presença das 4 últimas rodas, SÓ em números. Militante de outro núcleo não vê esta pauta: cada um
 * só recebe a do próprio núcleo.
 */
create or replace function public.escola_nucleo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); n uuid; v_nome text; seguinte uuid; anterior uuid; a escola_encontros;
begin
  perform interno.limite('escola_nucleo', 120, 10);
  n := interno.escola_meu_nucleo();
  if n is not null then select r.nome into v_nome from rede_nucleos r where r.id = n; end if;
  if n is null or v_nome is null then
    return jsonb_build_object('nucleo', null, 'proximo', null, 'presenca', '[]'::jsonb, 'medeia', false, 'anterior', null);
  end if;
  seguinte := interno.escola_encontro_seguinte(n);
  anterior := interno.escola_encontro_anterior(n, coalesce((select quando from escola_encontros where id = seguinte), now() - interval '3 hours'));
  if anterior is not null then select * into a from escola_encontros where id = anterior; end if;
  return jsonb_build_object(
    'nucleo', jsonb_build_object('id', n, 'nome', v_nome),
    'proximo', interno.escola_encontro_json(seguinte),
    'anterior', case when anterior is null then null else jsonb_build_object('id', a.id, 'quando', a.quando, 'presenca', a.presenca, 'balanco', a.balanco) end,
    'presenca', coalesce((
      select jsonb_agg(jsonb_build_object('quando', x.quando, 'presenca', x.presenca) order by x.quando)
      from (select quando, presenca from escola_encontros where nucleo = n and quando < now() - interval '3 hours' order by quando desc limit 4) x), '[]'::jsonb),
    'medeia', interno.escola_medeia(n));
end $$;

/**
 * Salvar o encontro (novo ou o mesmo): quando, a pauta, a presença somada, o balanço e quem faz o quê. Só a mediação do
 * núcleo ou a coordenação. Num encontro que já existe, o que não vier fica como estava (quando, pauta, presença, balanço). As tarefas, quando vêm, substituem a lista; a tarefa sem "quem" na entrada mantém quem já
 * tinha pegado a mesma tarefa neste encontro. "quem" dado tem de ser militante do mesmo núcleo.
 */
create or replace function public.escola_encontro_salvar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.escola_militante_eu();
  n uuid;
  e_id uuid;
  velho escola_encontros;
  q timestamptz;
  v_pauta jsonb;
  pres smallint;
  bal text;
  x jsonb;
  v_item text;
  v_quem uuid;
  v_feito boolean;
  antigas jsonb;
begin
  perform interno.limite('escola_encontro_salvar', 60, 60);
  if p is null or jsonb_typeof(p) <> 'object' then perform interno.erro('invalido:encontro'); end if;
  begin
    n := (p ->> 'nucleo')::uuid;
    e_id := nullif(p ->> 'id', '')::uuid;
    q := (p ->> 'quando')::timestamptz;
  exception when others then perform interno.erro('invalido:encontro');
  end;
  if n is null or (q is null and e_id is null) then perform interno.erro('invalido:encontro'); end if;
  if not interno.escola_medeia(n) then perform interno.erro('sem_permissao'); end if;
  if q is not null and (q < now() - interval '400 days' or q > now() + interval '400 days') then perform interno.erro('invalido:quando'); end if;
  -- Sem "pauta" na entrada, a pauta fica como está (fechar a roda que passou manda só presença e balanço).
  if p ? 'pauta' or e_id is null then v_pauta := interno.escola_pauta_limpa(coalesce(p -> 'pauta', '[]'::jsonb)); end if;
  if p ? 'presenca' and jsonb_typeof(p -> 'presenca') <> 'null' then
    begin pres := (p ->> 'presenca')::smallint; exception when others then perform interno.erro('invalido:presenca'); end;
    if pres < 0 or pres > 500 then perform interno.erro('invalido:presenca'); end if;
  end if;
  bal := left(btrim(coalesce(p ->> 'balanco', '')), 2000);
  if char_length(btrim(coalesce(p ->> 'balanco', ''))) > 2000 then perform interno.erro('invalido:balanco'); end if;

  if e_id is not null then
    select * into velho from escola_encontros where id = e_id;
    if not found or velho.nucleo <> n then perform interno.erro('nao_encontrado'); end if;
    update escola_encontros set quando = coalesce(q, velho.quando), pauta = coalesce(v_pauta, velho.pauta),
      presenca = case when p ? 'presenca' then pres else velho.presenca end,
      balanco = case when p ? 'balanco' then bal else velho.balanco end
    where id = e_id;
  else
    insert into escola_encontros (nucleo, quando, pauta, presenca, balanco, criado_por) values (n, q, v_pauta, pres, bal, v) returning id into e_id;
  end if;

  if p ? 'tarefas' then
    if jsonb_typeof(p -> 'tarefas') <> 'array' or jsonb_array_length(p -> 'tarefas') > 12 then perform interno.erro('invalido:tarefas'); end if;
    select coalesce(jsonb_agg(jsonb_build_object('item', lower(t.item), 'quem', t.quem, 'feito', t.feito)), '[]'::jsonb) into antigas
    from escola_encontro_tarefas t where t.encontro = e_id;
    delete from escola_encontro_tarefas where encontro = e_id;
    for x in select value from jsonb_array_elements(p -> 'tarefas') loop
      v_item := btrim(regexp_replace(coalesce(x ->> 'item', ''), '\s+', ' ', 'g'));
      if char_length(v_item) < 2 or char_length(v_item) > 120 then perform interno.erro('invalido:tarefas'); end if;
      if x ? 'quem' then
        if jsonb_typeof(x -> 'quem') = 'null' then v_quem := null;
        else
          begin v_quem := (x ->> 'quem')::uuid; exception when others then perform interno.erro('invalido:quem'); end;
          if not exists (select 1 from escola_militancia m where m.usuario = v_quem and m.nucleo = n) then perform interno.erro('invalido:quem'); end if;
        end if;
      else
        select (a ->> 'quem')::uuid into v_quem from jsonb_array_elements(antigas) a where a ->> 'item' = lower(v_item) and a ->> 'quem' is not null limit 1;
      end if;
      begin v_feito := (x ->> 'feito')::boolean; exception when others then perform interno.erro('invalido:tarefas'); end;
      insert into escola_encontro_tarefas (encontro, item, quem, feito)
      values (e_id, v_item, v_quem, coalesce(v_feito,
        (select (a ->> 'feito')::boolean from jsonb_array_elements(antigas) a where a ->> 'item' = lower(v_item) limit 1), false));
    end loop;
  end if;
  perform interno.registrar('escola_encontro_salvo', e_id::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true, 'id', e_id);
end $$;

/**
 * "Eu levo" (p_pegar = true) ou "soltar" (false) uma tarefa do encontro do PRÓPRIO núcleo. Rodízio: quem fez a mesma
 * tarefa na roda anterior deixa para outra pessoa (a mediação ainda pode pôr pelo salvar, se ninguém mais pegar).
 */
create or replace function public.escola_tarefa_pegar(p_id uuid, p_pegar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); t escola_encontro_tarefas; e escola_encontros; antes uuid;
begin
  perform interno.limite('escola_tarefa_pegar', 60, 60);
  select * into t from escola_encontro_tarefas where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  select * into e from escola_encontros where id = t.encontro;
  if e.nucleo is distinct from interno.escola_meu_nucleo() and not interno.escola_medeia(e.nucleo) then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_pegar, false) then
    if t.quem is not null and t.quem <> v then perform interno.erro('ja_tem_quem'); end if;
    antes := interno.escola_encontro_anterior(e.nucleo, e.quando);
    if t.quem is null and exists (select 1 from escola_encontro_tarefas a where a.encontro = antes and a.quem = v and lower(a.item) = lower(t.item)) then
      perform interno.erro('rodizio');
    end if;
    update escola_encontro_tarefas set quem = v where id = p_id;
  else
    if t.quem is distinct from v and not interno.escola_medeia(e.nucleo) then perform interno.erro('sem_permissao'); end if;
    update escola_encontro_tarefas set quem = null, feito = false where id = p_id;
  end if;
  return jsonb_build_object('ok', true);
end $$;

/** A dúvida (ou a resposta à pergunta da semana) vira item da pauta do próximo encontro do próprio núcleo, sem dizer de quem. */
create or replace function public.escola_levar_ao_nucleo(p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); n uuid; e uuid; t text; v_pauta jsonb;
begin
  perform interno.limite('escola_levar_ao_nucleo', 6, 60);
  t := btrim(regexp_replace(coalesce(p_texto, ''), '\s+', ' ', 'g'));
  if char_length(t) < 3 or char_length(t) > 200 then perform interno.erro('invalido:texto'); end if;
  n := interno.escola_meu_nucleo();
  if n is null then perform interno.erro('sem_nucleo'); end if;
  e := interno.escola_encontro_seguinte(n);
  if e is null then perform interno.erro('sem_encontro'); end if;
  select x.pauta into v_pauta from escola_encontros x where x.id = e for update;
  if jsonb_array_length(v_pauta) >= 12 then perform interno.erro('pauta_cheia'); end if;
  update escola_encontros set pauta = v_pauta || jsonb_build_array(jsonb_build_object('texto', t, 'levado', true)) where id = e;
  return jsonb_build_object('ok', true);
end $$;

-- 2. Pergunta geradora e recados ─────────────────────────────────────────────────────────────────────────────────────────
/** A pergunta geradora desta semana (a semana começa na segunda, em Brasília), ou nulo. */
create or replace function public.escola_pergunta_da_semana() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); r escola_perguntas;
begin
  select * into r from escola_perguntas where semana = date_trunc('week', interno.escola_hoje())::date;
  if not found then return null; end if;
  return jsonb_build_object('semana', r.semana, 'texto', r.texto);
end $$;

/** A coordenação define (ou apaga, com texto vazio) a pergunta de uma semana (a data é a segunda-feira). */
create or replace function public.escola_pergunta_definir(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); s date; t text;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('escola_pergunta_definir', 60, 60);
  begin s := (p ->> 'semana')::date; exception when others then perform interno.erro('invalido:semana'); end;
  if s is null or extract(isodow from s) <> 1 or s < date_trunc('week', interno.escola_hoje())::date - 7 or s > interno.escola_hoje() + 120 then
    perform interno.erro('invalido:semana');
  end if;
  t := btrim(regexp_replace(coalesce(p ->> 'texto', ''), '\s+', ' ', 'g'));
  if t = '' then
    delete from escola_perguntas where semana = s;
  else
    if char_length(t) < 3 or char_length(t) > 300 then perform interno.erro('invalido:texto'); end if;
    insert into escola_perguntas (semana, texto, por) values (s, t, v)
    on conflict (semana) do update set texto = excluded.texto, por = excluded.por, criado_em = now();
  end if;
  perform interno.registrar('escola_pergunta_definida', s::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true);
end $$;

/** Os recados que valem hoje: os de toda a Escola e os do próprio núcleo. */
create or replace function public.escola_recados() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); n uuid := interno.escola_meu_nucleo();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', r.id, 'texto', r.texto, 'ate', r.ate, 'nucleo', r.nucleo) order by r.nucleo nulls first, r.criado_em desc)
    from escola_recados r where r.ate >= interno.escola_hoje() and (r.nucleo is null or r.nucleo = n)), '[]'::jsonb);
end $$;

/** Criar, mudar ou apagar um recado. Para toda a Escola: só a coordenação. Para um núcleo: a coordenação ou a mediação dele. */
create or replace function public.escola_recado_salvar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r escola_recados; id_ uuid; n uuid; t text; ate_ date; apagar boolean;
begin
  perform interno.limite('escola_recado_salvar', 60, 60);
  if p is null or jsonb_typeof(p) <> 'object' then perform interno.erro('invalido:recado'); end if;
  begin
    id_ := nullif(p ->> 'id', '')::uuid;
    n := nullif(p ->> 'nucleo', '')::uuid;
    apagar := coalesce((p ->> 'apagar')::boolean, false);
  exception when others then perform interno.erro('invalido:recado');
  end;
  if id_ is not null then
    select * into r from escola_recados where id = id_;
    if not found then perform interno.erro('nao_encontrado'); end if;
    -- Quem não pode mexer no núcleo do recado não mexe, nem para mudar de núcleo.
    if not (interno.coord() or (r.nucleo is not null and interno.escola_medeia(r.nucleo))) then perform interno.erro('sem_permissao'); end if;
    if apagar then
      delete from escola_recados where id = id_;
      perform interno.registrar('escola_recado_apagado', id_::text, jsonb_build_object('departamento', 'reservado'));
      return jsonb_build_object('ok', true);
    end if;
    if not (p ? 'nucleo') then n := r.nucleo; end if;
  end if;
  if not (interno.coord() or (n is not null and interno.escola_medeia(n))) then perform interno.erro('sem_permissao'); end if;
  if n is not null and not exists (select 1 from rede_nucleos where id = n) then perform interno.erro('invalido:nucleo'); end if;
  t := btrim(regexp_replace(coalesce(p ->> 'texto', ''), '\s+', ' ', 'g'));
  if char_length(t) < 3 or char_length(t) > 400 then perform interno.erro('invalido:texto'); end if;
  begin ate_ := (p ->> 'ate')::date; exception when others then perform interno.erro('invalido:ate'); end;
  if ate_ is null or ate_ < interno.escola_hoje() or ate_ > interno.escola_hoje() + 366 then perform interno.erro('invalido:ate'); end if;
  if id_ is null then
    insert into escola_recados (texto, ate, nucleo, por) values (t, ate_, n, v) returning id into id_;
  else
    update escola_recados set texto = t, ate = ate_, nucleo = n, por = v where id = id_;
  end if;
  perform interno.registrar('escola_recado_salvo', id_::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true, 'id', id_);
end $$;

-- 3. Quem acompanha e a banca de passagem ────────────────────────────────────────────────────────────────────────────────
/** A coordenação indica quem acompanha a formação de um militante (só alguém do Degrau 3), ou tira (nulo). */
create or replace function public.escola_acompanhar(p_militante uuid, p_acompanha uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('escola_acompanhar', 120, 60);
  if not exists (select 1 from escola_militancia where usuario = p_militante) then perform interno.erro('nao_encontrado'); end if;
  if p_acompanha is not null then
    if p_acompanha = p_militante then perform interno.erro('invalido:acompanha'); end if;
    if not exists (select 1 from escola_militancia m join perfis f on f.id = m.usuario where m.usuario = p_acompanha and m.degrau = 3 and not f.suspenso) then
      perform interno.erro('acompanhante_degrau_3');
    end if;
  end if;
  update escola_militancia set acompanha = p_acompanha where usuario = p_militante;
  perform interno.registrar('escola_acompanhante', p_militante::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true);
end $$;

/** Quem pode marcar e decidir a banca de um militante: a coordenação ou quem o acompanha hoje (e não a própria pessoa). */
create or replace function interno.escola_decide_banca(p_militante uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_militante is not null and p_militante is distinct from auth.uid() and (interno.coord() or (
    interno.sessao_confiavel() and interno.e_militante(auth.uid())
    and exists (select 1 from escola_militancia m where m.usuario = p_militante and m.acompanha = auth.uid())))
$$;

/**
 * Marcar a banca de passagem: o degrau é o que a pessoa vai FECHAR (o dela hoje). Uma banca marcada por vez. O núcleo,
 * se não vier, é o da pessoa.
 */
create or replace function public.escola_banca_marcar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); mil uuid; d smallint; q timestamptz; n uuid; m escola_militancia; id_ uuid;
begin
  perform interno.limite('escola_banca_marcar', 30, 60);
  begin
    mil := (p ->> 'militante')::uuid;
    d := (p ->> 'degrau')::smallint;
    q := nullif(p ->> 'quando', '')::timestamptz;
    n := nullif(p ->> 'nucleo', '')::uuid;
  exception when others then perform interno.erro('invalido:banca');
  end;
  if not interno.escola_decide_banca(mil) then perform interno.erro('sem_permissao'); end if;
  select * into m from escola_militancia where usuario = mil;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if d is null or d <> m.degrau then perform interno.erro('invalido:degrau'); end if;
  if q is not null and (q < now() - interval '30 days' or q > now() + interval '400 days') then perform interno.erro('invalido:quando'); end if;
  if exists (select 1 from escola_bancas where militante = mil and situacao = 'marcada') then perform interno.erro('banca_ja_marcada'); end if;
  n := coalesce(n, m.nucleo);
  if n is not null and not exists (select 1 from rede_nucleos where id = n) then perform interno.erro('invalido:nucleo'); end if;
  -- O "exists" acima dá a mensagem certa no caso comum; o índice único escola_bancas_uma_marcada barra os dois cliques
  -- ao mesmo tempo (acompanhante e coordenação), que o "exists" sozinho deixaria passar.
  begin
    insert into escola_bancas (militante, degrau, nucleo, quando, por) values (mil, d, n, q, v) returning id into id_;
  exception when unique_violation then perform interno.erro('banca_ja_marcada');
  end;
  perform interno.registrar('escola_banca_marcada', id_::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true, 'id', id_);
end $$;

/**
 * Registrar o que a banca decidiu, com o BALANÇO COLETIVO (o que a pessoa trouxe, o que o núcleo viu, o que fica para o
 * próximo degrau). Sem nota: só "aprovada" (o degrau se abre) ou "refazer" (combinar de novo). Aprovada: sobe o degrau
 * (até 3) e grava a conquista verificada 'degrau-N', N = o degrau fechado.
 */
create or replace function public.escola_banca_decidir(p_id uuid, p_situacao text, p_balanco text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); b escola_bancas; t text;
begin
  perform interno.limite('escola_banca_decidir', 30, 60);
  select * into b from escola_bancas where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not interno.escola_decide_banca(b.militante) then perform interno.erro('sem_permissao'); end if;
  if b.situacao <> 'marcada' then perform interno.erro('banca_ja_decidida'); end if;
  if coalesce(p_situacao, '') not in ('aprovada', 'refazer') then perform interno.erro('invalido:situacao'); end if;
  t := btrim(coalesce(p_balanco, ''));
  if char_length(t) < 10 or char_length(t) > 2000 then perform interno.erro('invalido:balanco'); end if;
  update escola_bancas set situacao = p_situacao, balanco = t, decidida_em = now(), por = v where id = p_id;
  if p_situacao = 'aprovada' then
    update escola_militancia set degrau = least(3, degrau + 1) where usuario = b.militante and degrau = b.degrau;
    insert into escola_conquistas (usuario, tipo, alvo, verificada) values (b.militante, 'degrau', 'degrau-' || b.degrau, true)
    on conflict (usuario, tipo, alvo) do update set verificada = true, em = now();
  end if;
  perform interno.registrar('escola_banca_decidida', p_id::text, jsonb_build_object('departamento', 'reservado', 'situacao', p_situacao));
  return jsonb_build_object('ok', true);
end $$;

/**
 * As bancas que quem chama pode ver: as próprias, as de quem acompanha e, para a coordenação, todas (as 300 mais novas).
 * O balanço só vai a essas três pessoas (militante, quem acompanha, coordenação).
 */
create or replace function public.escola_bancas_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu(); c boolean := interno.coord();
begin
  perform interno.limite('escola_bancas_listar', 120, 10);
  return coalesce((
    select jsonb_agg(x.j order by x.ordem desc) from (
      select jsonb_build_object(
        'id', b.id,
        'militante', interno.escola_pessoa(b.militante),
        'usuario', b.militante,
        'degrau', b.degrau,
        'quando', b.quando,
        'situacao', b.situacao,
        'balanco', b.balanco,
        'minha', b.militante = v,
        'decido', interno.escola_decide_banca(b.militante)) j, coalesce(b.quando, b.criado_em) ordem
      from escola_bancas b left join escola_militancia m on m.usuario = b.militante
      where b.militante = v or m.acompanha = v or c
      order by coalesce(b.quando, b.criado_em) desc limit 300) x), '[]'::jsonb);
end $$;

/** Quem eu acompanho (para quem é do Degrau 3): codinome, degrau e o id (para marcar a banca). */
create or replace function public.escola_acompanho() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_militante_eu();
begin
  return coalesce((
    select jsonb_agg(interno.escola_pessoa(m.usuario) || jsonb_build_object('usuario', m.usuario, 'degrau', m.degrau,
      'banca_marcada', exists (select 1 from escola_bancas b where b.militante = m.usuario and b.situacao = 'marcada')) order by m.desde)
    from escola_militancia m join perfis f on f.id = m.usuario where m.acompanha = v and not f.suspenso), '[]'::jsonb);
end $$;

-- 4. O painel da coordenação ─────────────────────────────────────────────────────────────────────────────────────────────
/** Os militantes, pelo codinome (sem nome civil, sem e-mail): degrau, frente, núcleo, quem acompanha, desde quando. */
create or replace function public.escola_militantes_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.registrar_acesso('escola_militantes', 'reservado');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'usuario', m.usuario,
      'codinome', case when f.rede_codinome_ok then f.rede_codinome end,
      'degrau', m.degrau,
      'frente', m.frente,
      'nucleo', case when r.id is null then null else jsonb_build_object('id', r.id, 'nome', r.nome) end,
      'acompanha', interno.escola_pessoa(m.acompanha),
      'acompanha_id', m.acompanha,
      'desde', m.desde) order by m.degrau desc, lower(coalesce(f.rede_codinome, '')), m.desde)
    from escola_militancia m join perfis f on f.id = m.usuario left join rede_nucleos r on r.id = m.nucleo
    where not f.suspenso), '[]'::jsonb);
end $$;

/** A coordenação muda o núcleo, a frente e o degrau de um militante (só as chaves que vierem). */
create or replace function public.escola_militante_ajustar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); u uuid; n uuid; d smallint; fr text;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('escola_militante_ajustar', 120, 60);
  begin u := (p ->> 'usuario')::uuid; exception when others then perform interno.erro('invalido:usuario'); end;
  if u is null or not exists (select 1 from escola_militancia where usuario = u) then perform interno.erro('nao_encontrado'); end if;
  if p ? 'nucleo' then
    begin n := nullif(p ->> 'nucleo', '')::uuid; exception when others then perform interno.erro('invalido:nucleo'); end;
    if n is not null and not exists (select 1 from rede_nucleos where id = n) then perform interno.erro('invalido:nucleo'); end if;
    update escola_militancia set nucleo = n where usuario = u;
  end if;
  if p ? 'frente' then
    fr := nullif(p ->> 'frente', '');
    if fr is not null and fr not in ('estudantil', 'bairros', 'trabalho', 'agitprop', 'atos', 'cultura', 'solidariedade') then perform interno.erro('invalido:frente'); end if;
    update escola_militancia set frente = fr where usuario = u;
  end if;
  if p ? 'degrau' then
    begin d := (p ->> 'degrau')::smallint; exception when others then perform interno.erro('invalido:degrau'); end;
    if d is null or d not between 1 and 3 then perform interno.erro('invalido:degrau'); end if;
    update escola_militancia set degrau = d where usuario = u;
    -- Quem deixa o Degrau 3 deixa de acompanhar (só o Degrau 3 acompanha).
    if d < 3 then update escola_militancia set acompanha = null where acompanha = u; end if;
  end if;
  perform interno.registrar('escola_militante_ajustado', u::text, jsonb_build_object('departamento', 'reservado'));
  return jsonb_build_object('ok', true);
end $$;

/** O resto do painel: os núcleos da Alumia (com quantos militantes), os recados e as perguntas (as recentes e as marcadas). */
create or replace function public.escola_painel_resumo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'nucleos', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'nome', r.nome, 'cidade', r.cidade,
        'militantes', (select count(*) from escola_militancia m where m.nucleo = r.id)) order by r.nome) from rede_nucleos r), '[]'::jsonb),
    'recados', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'texto', x.texto, 'ate', x.ate, 'nucleo', x.nucleo) order by x.ate desc, x.criado_em desc)
        from escola_recados x where x.ate >= interno.escola_hoje() - 30), '[]'::jsonb),
    'perguntas', coalesce((select jsonb_agg(jsonb_build_object('semana', q.semana, 'texto', q.texto) order by q.semana desc)
        from escola_perguntas q where q.semana >= interno.escola_hoje() - 63), '[]'::jsonb),
    'semana', date_trunc('week', interno.escola_hoje())::date);
end $$;

-- 5. Permissões e faxina ─────────────────────────────────────────────────────────────────────────────────────────────────
-- As públicas: só para quem tem conta (anon fica de fora; com conta, cada função confere militância ou coordenação).
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and n.nspname = 'public' and p.proname in ('escola_nucleo', 'escola_encontro_salvar', 'escola_tarefa_pegar',
             'escola_levar_ao_nucleo', 'escola_pergunta_da_semana', 'escola_pergunta_definir', 'escola_recados', 'escola_recado_salvar',
             'escola_acompanhar', 'escola_banca_marcar', 'escola_banca_decidir', 'escola_bancas_listar', 'escola_acompanho',
             'escola_militantes_listar', 'escola_militante_ajustar', 'escola_painel_resumo') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon', f.assinatura);
      execute format('grant execute on function %s to authenticated, service_role', f.assinatura);
    end if;
  end loop;
  -- As internas não são chamáveis de fora.
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and n.nspname = 'interno' and p.proname in ('escola_pessoa', 'escola_hoje', 'escola_militante_eu', 'escola_meu_nucleo',
             'escola_medeia', 'escola_encontro_seguinte', 'escola_encontro_anterior', 'escola_pauta_limpa', 'escola_encontro_json',
             'escola_decide_banca') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon, authenticated', f.assinatura); end if;
  end loop;
end $$;

-- Faxina: recados vencidos há mais de 60 dias saem; perguntas com mais de 2 anos também. Os encontros ficam (são a
-- memória do núcleo, sem nome de ninguém além do codinome de quem pegou a tarefa).
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-escola-recados-faxina', '41 5 * * *',
      $c$delete from interno.escola_recados where ate < (now() at time zone 'America/Sao_Paulo')::date - 60; delete from interno.escola_perguntas where semana < (now() at time zone 'America/Sao_Paulo')::date - 730$c$);
  end if;
end $$;


-- ───────────────────────────── Escola de Formação (F5): conquistas e a ligação com a Alumia, novembro de 2026 ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Roda DEPOIS da 20261108-escola-formacao-base.sql
-- (F1, que cria interno.escola_conquistas, interno.escola_militancia e perfis.escola_publico) e da 2026-11-rede-perfil.sql
-- (Alumia, que cria interno.rede3_perfil_selos). Quem junta cola este bloco no fim do install.sql (ordem da Escola: F1, F4,
-- F5, F3, F6). Plano: docs/plano-2026-11/PLANO-ESCOLA.md, seção 4.5. Teste: npm run testar:escola-conquistas.
--
-- O que este arquivo faz, e só isto:
--  1. perfis.escola_publico_em: quando a pessoa ligou a exibição (passou pela tela de consentimento). Nulo = ninguém.
--  2. Quem vê: interno.escola_pode_ver(dono, quem) e interno.escola_conquistas_visiveis(dono, quem), o filtro de público
--     (ninguem: só o dono; militantes: quem é militante; seguidores: quem segue com pedido aceito; todos: quem abre o perfil).
--  3. interno.rede3_perfil_selos passa a acrescentar os selos da Escola ('escola:carteirinha', 'escola:degrau-N',
--     'escola:caderno-NN' e a CONTAGEM 'escola:aulas-N', nunca a lista de aulas), JÁ FILTRADOS no servidor por quem pede
--     (auth.uid()). O rede_selos_mostrar da Alumia não basta: o selo da Escola nasce escondido e só aparece para o público
--     escolhido. Contrato com a Onda 5 (perfil novo da Alumia): o campo "selos" de rede_perfil_de já vem filtrado.
--  4. Funções públicas: escola_publico_definir, escola_conquista_declarar e escola_conquistas_minhas (contrato em
--     lib/escola/contratos.ts).
--  5. Sair do departamento Revolucionários volta o público para 'ninguem' (a F1 já apaga as conquistas).
--
-- Privacidade: ser militante revela opinião política (dado sensível, LGPD art. 5º, II, e art. 11, I). Por isso: padrão
-- 'ninguem'; ligar exige a tela de consentimento (o banco guarda quando); desligar esconde na hora e APAGA o que o aparelho
-- declarou (aula e caderno), que só existia para ser mostrado (LGPD art. 6º, III, minimização; art. 18, VI, eliminação).
-- Aula e caderno são declarados pelo aparelho (verificada = false), como o selo de trilha da Alumia; carteirinha e degrau
-- são do servidor (gatilho do departamento, F1, e banca aprovada, F4). Nada de nome civil.

-- 1. Quando a pessoa ligou ────────────────────────────────────────────────────────────────────────────────────────────────
alter table interno.perfis add column if not exists escola_publico_em timestamptz;

-- 2. Quem vê ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * `p_quem` pode ver as conquistas da Escola de `p_dono`? O dono sempre vê as próprias. Os outros, só se o dono é militante
 * (tem a linha da militância), não está suspenso, não há bloqueio entre os dois e o público escolhido deixa.
 * Sem sessão (p_quem nulo), nunca.
 */
create or replace function interno.escola_pode_ver(p_dono uuid, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_dono is not null and p_quem is not null and (
    p_dono = p_quem
    or exists (
      select 1 from perfis f join escola_militancia m on m.usuario = f.id
      where f.id = p_dono and not f.suspenso and not interno.rede_bloqueado(p_dono, p_quem)
        and case f.escola_publico
              when 'todos' then true
              when 'militantes' then interno.e_militante(p_quem)
              when 'seguidores' then exists (select 1 from rede_seguindo s where s.quem = p_quem and s.segue = p_dono and not s.pendente)
              else false
            end))
$$;

/**
 * Os selos da Escola de `p_dono` que `p_quem` pode ver, na ordem: carteirinha, o maior degrau verificado, os cadernos
 * declarados e a contagem de aulas declaradas. Lista vazia quando não pode ver.
 */
create or replace function interno.escola_conquistas_visiveis(p_dono uuid, p_quem uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select case when not interno.escola_pode_ver(p_dono, p_quem) then '[]'::jsonb else coalesce((
    select jsonb_agg(x.s order by x.o, x.s)
    from (
      select 'escola:carteirinha' as s, 1 as o from escola_conquistas c
        where c.usuario = p_dono and c.tipo = 'carteirinha' and c.alvo = 'carteirinha' and c.verificada
      union all
      select 'escola:' || max(c.alvo), 2 from escola_conquistas c
        where c.usuario = p_dono and c.tipo = 'degrau' and c.verificada and c.alvo ~ '^degrau-[1-3]$' having count(*) > 0
      union all
      select 'escola:' || c.alvo, 3 from escola_conquistas c
        where c.usuario = p_dono and c.tipo = 'caderno' and c.alvo ~ '^caderno-(0[1-9]|1[01])$'
      union all
      select 'escola:aulas-' || count(*), 4 from escola_conquistas c
        where c.usuario = p_dono and c.tipo = 'aula' having count(*) > 0
    ) x), '[]'::jsonb) end
$$;

-- 3. Os selos do perfil da Alumia, com os da Escola já filtrados ─────────────────────────────────────────────────────────
/**
 * Os selos de trajetória de uma pessoa, como texto: 'equipe', 'educador', 'moderacao' (do papel), 'trilha:<slug>'
 * (declarado) e, desde a Escola de Formação, os 'escola:*' que QUEM PEDE (auth.uid()) pode ver. Mesmo corpo da
 * 2026-11-rede-perfil.sql, mais a última parte.
 */
create or replace function interno.rede3_perfil_selos(p_id uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(x.s order by x.o, x.s), '[]'::jsonb)
  from (
    select 'equipe' as s, 1 as o where interno.voluntario_e(p_id)
    union all
    select 'educador', 2 where exists (select 1 from papeis q where q.usuario = p_id and q.papel in ('educacao', 'educacao_secundaria'))
    union all
    select 'moderacao', 3 where exists (select 1 from papeis q where q.usuario = p_id and q.papel = 'mediacao')
      or exists (select 1 from rede_comunidade_membros m where m.usuario = p_id and m.papel = 'moderacao' and m.situacao = 'ativo')
    union all
    select t, 4 from perfis f, unnest(f.rede_selos) t where f.id = p_id and t ~ '^trilha:[a-z0-9-]{2,80}$'
    union all
    select e.s, (4 + e.n)::int from jsonb_array_elements_text(interno.escola_conquistas_visiveis(p_id, auth.uid())) with ordinality as e(s, n)
  ) x
$$;

-- 4. Funções públicas ────────────────────────────────────────────────────────────────────────────────────────────────────
/** A linha da militância de quem chama, ou erro: só militante (com a linha criada pelo departamento) tem conquistas. */
create or replace function interno.escola_exige_militancia() returns uuid language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.e_militante(v) or not exists (select 1 from escola_militancia where usuario = v) then perform interno.erro('sem_permissao'); end if;
  return v;
end $$;

/**
 * Quem vê as minhas conquistas da Escola no perfil da Alumia. A tela só chama com público diferente de 'ninguem' depois
 * da tela de consentimento; o banco guarda quando. 'ninguem' esconde na hora e apaga o que o aparelho declarou.
 */
create or replace function public.escola_publico_definir(p text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_exige_militancia();
begin
  if p is null or p not in ('ninguem', 'militantes', 'seguidores', 'todos') then perform interno.erro('invalido:publico'); end if;
  perform interno.limite('escola_publico', 30, 10);
  update perfis set escola_publico = p, escola_publico_em = case when p = 'ninguem' then null else now() end where id = v;
  if p = 'ninguem' then
    delete from escola_conquistas where usuario = v and not verificada and tipo in ('aula', 'caderno');
  end if;
  return jsonb_build_object('ok', true);
end $$;

/**
 * O aparelho declara (p_ligar = true) ou retira (false) uma aula ('trilha/aula', o mesmo lessonId de /trilhas) ou um
 * caderno ('caderno-01' a 'caderno-11') feito. Fica verificada = false: o servidor não confere o estudo, e o perfil só
 * mostra a CONTAGEM de aulas. Declarar só vale com a exibição ligada (sem público, não há para que guardar). Até 400 por pessoa.
 */
create or replace function public.escola_conquista_declarar(p_tipo text, p_alvo text, p_ligar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_exige_militancia(); n integer;
begin
  if p_tipo is null or p_tipo not in ('aula', 'caderno') then perform interno.erro('invalido:tipo'); end if;
  if p_tipo = 'aula' and not (coalesce(p_alvo, '') ~ '^[a-z0-9-]{2,80}/[a-z0-9-]{1,120}$' and char_length(p_alvo) <= 160) then perform interno.erro('invalido:alvo'); end if;
  if p_tipo = 'caderno' and coalesce(p_alvo, '') !~ '^caderno-(0[1-9]|1[01])$' then perform interno.erro('invalido:alvo'); end if;
  if p_ligar is null then perform interno.erro('invalido:ligar'); end if;
  perform interno.limite('escola_conquista', 600, 10);
  if p_ligar then
    if (select escola_publico from perfis where id = v) = 'ninguem' then perform interno.erro('invalido:publico'); end if;
    if not exists (select 1 from escola_conquistas where usuario = v and tipo = p_tipo and alvo = p_alvo) then
      select count(*) into n from escola_conquistas where usuario = v and not verificada;
      if n >= 400 then perform interno.erro('invalido:muitas'); end if;
      insert into escola_conquistas (usuario, tipo, alvo, verificada) values (v, p_tipo, p_alvo, false) on conflict do nothing;
    end if;
  else
    delete from escola_conquistas where usuario = v and tipo = p_tipo and alvo = p_alvo and not verificada;
  end if;
  return jsonb_build_object('ok', true);
end $$;

/** As minhas conquistas da Escola (todas, inclusive as que ninguém mais vê) e o público escolhido. Só militante. */
create or replace function public.escola_conquistas_minhas() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.escola_exige_militancia();
begin
  return jsonb_build_object(
    'publico', (select escola_publico from perfis where id = v),
    'conquistas', coalesce((
      select jsonb_agg(jsonb_build_object('tipo', c.tipo, 'alvo', c.alvo, 'verificada', c.verificada, 'em', c.em) order by c.tipo, c.alvo)
      from escola_conquistas c where c.usuario = v), '[]'::jsonb));
end $$;

-- 5. Sair do departamento volta o público para 'ninguem' ─────────────────────────────────────────────────────────────────
create or replace function interno.escola_publico_ao_sair() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if old.departamento = 'revolucionarios' and (tg_op = 'DELETE' or new.departamento is distinct from 'revolucionarios' or new.usuario is distinct from old.usuario)
     and not interno.membro_direto(old.usuario, 'revolucionarios') then
    update perfis set escola_publico = 'ninguem', escola_publico_em = null where id = old.usuario;
  end if;
  return null;
end $$;
drop trigger if exists lucia_escola_publico on interno.departamento_membros;
create trigger lucia_escola_publico after update or delete on interno.departamento_membros for each row execute function interno.escola_publico_ao_sair();

-- 6. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
-- Nenhuma função interna é chamável de fora; as públicas, só com conta.
revoke all on function interno.escola_pode_ver(uuid, uuid), interno.escola_conquistas_visiveis(uuid, uuid), interno.escola_exige_militancia(),
  interno.escola_publico_ao_sair() from public;
revoke all on function public.escola_publico_definir(text), public.escola_conquista_declarar(text, text, boolean), public.escola_conquistas_minhas() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.escola_pode_ver(uuid, uuid), interno.escola_conquistas_visiveis(uuid, uuid), interno.escola_exige_militancia(),
      interno.escola_publico_ao_sair() from anon, authenticated;
    revoke all on function public.escola_publico_definir(text), public.escola_conquista_declarar(text, text, boolean), public.escola_conquistas_minhas() from anon;
    grant execute on function public.escola_publico_definir(text), public.escola_conquista_declarar(text, text, boolean), public.escola_conquistas_minhas() to authenticated, service_role;
  end if;
end $$;


-- ───────────────────────────── Escola de Formação (F3): aulas ao vivo só da Escola, novembro de 2026 ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Precisa da F1 (20261108-escola-formacao-base.sql,
-- interno.e_militante). Quem junta cola este bloco no fim do install.sql (ordem da Escola: F1, F4, F5, F3, F6).
-- Plano: docs/plano-2026-11/PLANO-ESCOLA.md, seção 4.3. Teste: npm run testar:escola-aovivo.
--
-- O que muda:
--  1. interno.aulas_ao_vivo ganha "publico" ('site', o de sempre, ou 'escola') e "caderno_aula" ('caderno/aula').
--  2. Aula 'escola' NÃO aparece para quem não é militante: nem na agenda pública (aulas_ao_vivo_listar nunca a lista),
--     nem no calendário da equipe, nem no feed de atividade do painel; aula_ao_vivo_ver devolve nada; o bate-papo
--     devolve lista vazia e recusa quem escreve. Decisão de 08/11: quem não é militante não vê nem que há aula.
--  3. No bate-papo da Escola o nome gravado é o CODINOME da Alumia (rede_codinome confirmado), nunca perfis.nome; quem lê
--     não recebe o id de quem escreveu (só "minha"). A moderação é de quem conduz e da coordenação: nada vai para a fila
--     da mediação da Comunidade nem para a segunda avaliação externa (as regras do banco valem; o que fica em dúvida
--     espera quem conduz). Quem escreveu pode esconder a própria fala, mas não pode mostrar de novo o que foi retido.
--  4. public.escola_aulas_hoje() e public.escola_gravacoes(p_caderno) (contrato em lib/escola/contratos.ts).
--  5. O bate-papo da aula 'escola' é apagado 30 dias depois de encerrada (ou cancelada, ou abandonada): pg_cron, se
--     houver, e também a cada aula encerrada (para não depender só do agendador).
--  6. O registro (auditoria) das aulas da Escola sai com departamento 'reservado' (padrão de install.sql, departamento_incluir).
--
-- Limite honesto (também escrito na tela do painel): "não listada" não é secreta. Quem tiver o link assiste no YouTube.
-- O fechamento é o site só entregar o id do vídeo a militantes.

-- 1. As colunas ──────────────────────────────────────────────────────────────────────────────────────────────────────────
alter table interno.aulas_ao_vivo add column if not exists publico text not null default 'site';
alter table interno.aulas_ao_vivo add column if not exists caderno_aula text;
do $$
begin
  alter table interno.aulas_ao_vivo add constraint aulas_ao_vivo_publico_check check (publico in ('site', 'escola'));
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.aulas_ao_vivo add constraint aulas_ao_vivo_caderno_aula_check
    check (caderno_aula is null or (publico = 'escola' and caderno_aula ~ '^[a-z0-9-]{2,80}/[a-z0-9-]{2,120}$'));
exception when duplicate_object then null;
end $$;
create index if not exists aulas_ao_vivo_escola on interno.aulas_ao_vivo (inicio) where publico = 'escola';

-- 2. Quem vê ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
/** Quem chama é militante (ou a coordenação, para si mesma) com a conta ativa. */
create or replace function interno.escola_aovivo_pode() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select auth.uid() is not null and interno.e_militante(auth.uid())
     and coalesce((select not f.suspenso from perfis f where f.id = auth.uid()), false)
$$;

/** A aula aparece para quem chama? Aula do site: sempre. Aula da Escola: só para militante (ou coordenação). */
create or replace function interno.escola_aula_ve(a interno.aulas_ao_vivo) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select a.publico = 'site' or interno.escola_aovivo_pode()
$$;

/** O codinome confirmado da Alumia, ou vazio. Nunca o nome civil. */
create or replace function interno.escola_codinome(p uuid) returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce((select case when f.rede_codinome_ok then f.rede_codinome end from perfis f where f.id = p), '')
$$;

/** 'caderno/aula' de um dos 11 cadernos da Escola (lib/escola/contratos.ts, CADERNOS_DA_ESCOLA), ou nulo. */
create or replace function interno.escola_caderno_aula_ok(p text) returns text language plpgsql immutable
  set search_path = interno, pg_temp as $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  if p !~ '^[a-z0-9-]{2,80}/[a-z0-9-]{2,120}$' or split_part(p, '/', 1) <> all (array[
    'consciencia-de-classe', 'primeiros-passos-na-militancia', 'conversar-com-quem-pensa-diferente', 'organizacao-de-base',
    'organizacao-sindical-de-base', 'comunicacao-popular', 'seguranca-e-cuidado-na-militancia', 'analise-de-conjuntura',
    'formar-formadores', 'guardar-a-memoria', 'ano-de-formacao-politica']) then
    raise exception 'invalido:caderno_aula' using errcode = 'P0001';
  end if;
  return p;
end $$;

/** Pode dar aula da Escola junto: militante do departamento ou da coordenação/vice. */
create or replace function interno.escola_pode_conduzir(p uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p is not null and (interno.membro_direto(p, 'revolucionarios') or exists (select 1 from papeis x where x.usuario = p and x.papel in ('coordenacao', 'vice')))
$$;

-- 3. A aula em JSON (o mesmo de antes, com publico e caderno_aula; na Escola, codinomes) ─────────────────────────────────
create or replace function interno.aula_json(a interno.aulas_ao_vivo, p_completa boolean) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', a.id, 'titulo', a.titulo, 'descricao', a.descricao, 'disciplina', a.disciplina, 'trilha', a.trilha, 'inicio', a.inicio, 'duracao', a.duracao,
    'status', a.status, 'iniciada_em', a.iniciada_em, 'encerrada_em', a.encerrada_em, 'gravacao', a.gravacao, 'sala_externa', a.sala_externa, 'youtube', a.youtube,
    'publico', a.publico, 'caderno_aula', a.caderno_aula,
    'educador', case when a.publico = 'escola'
      then jsonb_build_object('id', case when interno.conduz(a) then a.educador end, 'nome', interno.escola_codinome(a.educador))
      else jsonb_build_object('id', a.educador, 'nome', coalesce((select nome from perfis where id = a.educador), '')) end,
    'co_educadores', case when a.publico = 'escola'
      then coalesce((select jsonb_agg(jsonb_build_object('id', case when interno.conduz(a) then x end, 'nome', interno.escola_codinome(x)) order by x) from unnest(a.co_educadores) x), '[]'::jsonb)
      else coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'nome', f.nome) order by f.nome) from perfis f where f.id = any (a.co_educadores)), '[]'::jsonb) end,
    'inscritos', (select count(*) from aulas_inscricoes i where i.aula = a.id),
    'inscrito', auth.uid() is not null and exists (select 1 from aulas_inscricoes i where i.aula = a.id and i.usuario = auth.uid()),
    'conduzo', interno.conduz(a),
    'chaves', coalesce((select jsonb_agg(k.publica order by k.criado_em) from aulas_sala_chaves k where k.aula = a.id), '[]'::jsonb),
    'mensagens', case when p_completa then (select count(*) from aulas_chat m where m.aula = a.id and not m.oculta) else null end)
$$;

-- 4. A agenda pública e a aula: a Escola fica de fora ───────────────────────────────────────────────────────────────────
/** A agenda pública: só as aulas do site (as da Escola moram em escola_aulas_hoje, só para militante). */
create or replace function public.aulas_ao_vivo_listar(p_disciplina text default null, p_dias integer default 60) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(interno.aula_json(a, false) order by a.inicio), '[]'::jsonb)
  from aulas_ao_vivo a
  where a.publico = 'site'
    and (p_disciplina is null or a.disciplina = p_disciplina)
    and ((a.status in ('agendada', 'ao_vivo') and a.inicio < now() + make_interval(days => greatest(1, least(coalesce(p_dias, 60), 180))) and a.inicio > now() - interval '12 hours')
         or (a.status = 'encerrada' and a.gravacao <> '' and a.inicio > now() - interval '30 days'))
$$;

create or replace function public.aula_ao_vivo_ver(p_id uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.aula_json(a, true) from aulas_ao_vivo a
  where a.id = p_id and (a.status <> 'cancelada' or interno.conduz(a)) and interno.escola_aula_ve(a)
$$;

/** Marca ou altera uma aula. Quem conduz edita; co-educadores recebem um recado ao serem chamados. Aula da Escola: só quem vê os Revolucionários marca. */
create or replace function public.aula_ao_vivo_salvar(p_id uuid, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  a aulas_ao_vivo;
  v_co uuid[] := coalesce((select array_agg((x #>> '{}')::uuid) from jsonb_array_elements(coalesce(p -> 'co_educadores', '[]'::jsonb)) x), '{}');
  v_inicio timestamptz;
  v_disc text;
  v_publico text := coalesce(nullif(p ->> 'publico', ''), 'site');
  v_caderno text := interno.escola_caderno_aula_ok(p ->> 'caderno_aula');
  v_reservado jsonb;
  c uuid;
begin
  if not interno.educador() then perform interno.erro('sem_permissao'); end if;
  if v_publico not in ('site', 'escola') then perform interno.erro('invalido:publico'); end if;
  if p_id is not null then
    select * into a from aulas_ao_vivo where id = p_id for update;
    if not found then perform interno.erro('nao_encontrado'); end if;
    if not interno.conduz(a) then perform interno.erro('sem_permissao'); end if;
    if a.publico = 'escola' and not interno.escola_aovivo_pode() then perform interno.erro('sem_permissao'); end if;
    if a.status = 'cancelada' or (a.status = 'encerrada' and a.publico = 'site') then perform interno.erro('ja_decidida'); end if;
    -- Aula da Escola encerrada: só a gravação e a ligação com a aula do caderno (o resto ficou no passado). A do site
    -- continua como antes (encerrada não se edita).
    if a.status = 'encerrada' then
      update aulas_ao_vivo set gravacao = coalesce(interno.txt(p ->> 'gravacao', 'gravacao', 0, 500), gravacao),
        caderno_aula = case when a.publico = 'escola' and p ? 'caderno_aula' then v_caderno else caderno_aula end, atualizado_em = now()
      where id = p_id returning * into a;
      return interno.aula_json(a, true);
    end if;
    v_publico := a.publico; -- o público nasce com a aula e não muda
  end if;
  v_reservado := case when v_publico = 'escola' then jsonb_build_object('departamento', 'reservado') else '{}'::jsonb end;
  if v_publico = 'site' then v_caderno := null; end if;
  -- Aula da Escola: a disciplina é sempre a do departamento (o registro e a supervisão já tratam 'revolucionarios' como
  -- reservado) e não há sala de fora: a aula passa pelo YouTube não listado, e só militante recebe o id.
  v_disc := case when v_publico = 'escola' then 'revolucionarios' else interno.disciplina_ok(p ->> 'disciplina') end;
  if v_publico = 'escola' then p := p || jsonb_build_object('sala_externa', '', 'trilha', null); end if;
  if v_disc is null then perform interno.erro('invalido:disciplina'); end if;
  begin
    v_inicio := (p ->> 'inicio')::timestamptz;
  exception when others then perform interno.erro('invalido:inicio');
  end;
  if v_inicio is null or v_inicio > now() + interval '365 days' then perform interno.erro('invalido:inicio'); end if;
  if cardinality(v_co) > 8 then perform interno.erro('invalido:co_educadores'); end if;
  v_co := array_remove(v_co, v);
  if exists (select 1 from unnest(v_co) x where not exists (select 1 from papeis p2 where p2.usuario = x and p2.papel in ('educacao', 'educacao_secundaria', 'coordenacao', 'vice', 'mentoria'))) then
    perform interno.erro('invalido:co_educadores');
  end if;
  -- Na Escola, quem dá a aula junto também tem de ser militante (ou da coordenação).
  if v_publico = 'escola' and exists (select 1 from unnest(v_co) x where not interno.escola_pode_conduzir(x)) then
    perform interno.erro('invalido:co_educadores');
  end if;
  if p_id is null then
    if v_publico = 'escola' and not (interno.ve_revolucionarios() and interno.escola_aovivo_pode()) then perform interno.erro('sem_permissao'); end if;
    if v_inicio < now() - interval '1 hour' then perform interno.erro('invalido:inicio'); end if;
    perform interno.limite('aula_ao_vivo', 20, 1440);
    insert into aulas_ao_vivo (titulo, descricao, disciplina, trilha, inicio, duracao, educador, co_educadores, sala_externa, publico, caderno_aula)
    values (interno.txt(p ->> 'titulo', 'titulo', 3, 140), interno.txt(p ->> 'descricao', 'descricao', 0, 2000), v_disc,
            nullif(interno.txt(p ->> 'trilha', 'trilha', 0, 80), ''), v_inicio, coalesce((p ->> 'duracao')::integer, 60), v, v_co,
            interno.txt(p ->> 'sala_externa', 'sala_externa', 0, 500), v_publico, v_caderno)
    returning * into a;
    perform interno.registrar('aula_ao_vivo_marcada', a.titulo, jsonb_build_object('id', a.id, 'inicio', a.inicio) || v_reservado);
    foreach c in array v_co loop
      perform interno.avisar(c, format('%s chamou você para dar junto a aula ao vivo "%s", em %s. Veja em Aulas ao vivo.',
        case when v_publico = 'escola' then coalesce(nullif(interno.escola_codinome(v), ''), 'Um colega') else coalesce((select nome from perfis where id = v), 'Um colega') end,
        left(a.titulo, 100), to_char(a.inicio at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI')));
    end loop;
  else
    foreach c in array v_co loop
      if not (c = any (a.co_educadores)) then
        perform interno.avisar(c, format('%s chamou você para dar junto a aula ao vivo "%s". Veja em Aulas ao vivo.',
          case when v_publico = 'escola' then coalesce(nullif(interno.escola_codinome(v), ''), 'Um colega') else coalesce((select nome from perfis where id = v), 'Um colega') end,
          left(p ->> 'titulo', 100)));
      end if;
    end loop;
    update aulas_ao_vivo set titulo = interno.txt(p ->> 'titulo', 'titulo', 3, 140), descricao = interno.txt(p ->> 'descricao', 'descricao', 0, 2000), disciplina = v_disc,
      trilha = nullif(interno.txt(p ->> 'trilha', 'trilha', 0, 80), ''), inicio = v_inicio, duracao = coalesce((p ->> 'duracao')::integer, a.duracao),
      co_educadores = v_co, sala_externa = interno.txt(p ->> 'sala_externa', 'sala_externa', 0, 500), gravacao = coalesce(interno.txt(p ->> 'gravacao', 'gravacao', 0, 500), a.gravacao),
      caderno_aula = case when a.publico = 'escola' and p ? 'caderno_aula' then v_caderno else a.caderno_aula end, atualizado_em = now()
    where id = p_id returning * into a;
  end if;
  return interno.aula_json(a, true);
end $$;

/** Começar, encerrar, cancelar ou voltar a "agendada" (o mesmo de antes; na Escola, registro reservado e faxina do bate-papo velho). */
create or replace function public.aula_ao_vivo_estado(p_id uuid, p_status text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); a aulas_ao_vivo; r record;
begin
  select * into a from aulas_ao_vivo where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not interno.conduz(a) then perform interno.erro('sem_permissao'); end if;
  if a.publico = 'escola' and not interno.escola_aovivo_pode() then perform interno.erro('sem_permissao'); end if;
  if p_status not in ('agendada', 'ao_vivo', 'encerrada', 'cancelada') then perform interno.erro('invalido:status'); end if;
  if a.status = p_status then return interno.aula_json(a, true); end if;
  if p_status = 'ao_vivo' then
    if a.inicio > now() + interval '2 hours' then perform interno.erro('invalido:inicio'); end if;
    update aulas_ao_vivo set status = 'ao_vivo', iniciada_em = coalesce(iniciada_em, now()), encerrada_em = null, atualizado_em = now() where id = p_id returning * into a;
    insert into aulas_chat (aula, autor, nome, corpo, tipo) values (a.id, v, '', 'A aula começou.', 'sistema');
    for r in select i.usuario from aulas_inscricoes i where i.aula = a.id and i.usuario <> v loop
      perform interno.avisar(r.usuario, case when a.publico = 'escola'
        then format('A aula ao vivo da Escola "%s" começou agora. Entre pela Escola.', left(a.titulo, 100))
        else format('A aula ao vivo "%s" começou agora. Entre pela agenda de aulas ao vivo.', left(a.titulo, 100)) end);
    end loop;
  elsif p_status = 'encerrada' then
    update aulas_ao_vivo set status = 'encerrada', encerrada_em = now(), atualizado_em = now(),
      gravacao = case when gravacao = '' and youtube is not null then 'https://www.youtube.com/watch?v=' || youtube else gravacao end
    where id = p_id returning * into a;
    insert into aulas_chat (aula, autor, nome, corpo, tipo) values (a.id, v, '', 'A aula terminou. Obrigado a quem participou.', 'sistema');
    perform interno.escola_aovivo_faxina();
  elsif p_status = 'cancelada' then
    update aulas_ao_vivo set status = 'cancelada', atualizado_em = now() where id = p_id returning * into a;
    for r in select i.usuario from aulas_inscricoes i where i.aula = a.id and i.usuario <> v loop
      perform interno.avisar(r.usuario, format('A aula ao vivo "%s" foi cancelada.', left(a.titulo, 100)));
    end loop;
  else
    update aulas_ao_vivo set status = 'agendada', iniciada_em = null, encerrada_em = null, atualizado_em = now() where id = p_id returning * into a;
  end if;
  perform interno.registrar('aula_ao_vivo_' || p_status, a.titulo, jsonb_build_object('id', a.id)
    || case when a.publico = 'escola' then jsonb_build_object('departamento', 'reservado') else '{}'::jsonb end);
  return interno.aula_json(a, true);
end $$;

create or replace function public.aula_ao_vivo_apagar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); a aulas_ao_vivo;
begin
  select * into a from aulas_ao_vivo where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not (interno.coord() or (a.educador = v and a.status <> 'ao_vivo')) then perform interno.erro('sem_permissao'); end if;
  delete from aulas_ao_vivo where id = p_id;
  perform interno.registrar('aula_ao_vivo_apagada', a.titulo, jsonb_build_object('id', p_id)
    || case when a.publico = 'escola' then jsonb_build_object('departamento', 'reservado') else '{}'::jsonb end);
  return jsonb_build_object('ok', true);
end $$;

/** Quem tem conta marca presença: recebe recado quando a aula começa. Aula da Escola: só militante. */
create or replace function public.aula_ao_vivo_inscrever(p_id uuid, p_inscrever boolean default true) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not exists (select 1 from aulas_ao_vivo a where a.id = p_id and a.status in ('agendada', 'ao_vivo') and interno.escola_aula_ve(a)) then perform interno.erro('nao_encontrado'); end if;
  if p_inscrever then
    perform interno.limite('aula_inscrever', 60, 60);
    insert into aulas_inscricoes (aula, usuario) values (p_id, v) on conflict do nothing;
  else
    delete from aulas_inscricoes where aula = p_id and usuario = v;
  end if;
  return jsonb_build_object('inscrito', p_inscrever, 'inscritos', (select count(*) from aulas_inscricoes where aula = p_id));
end $$;

-- 5. O bate-papo ─────────────────────────────────────────────────────────────────────────────────────────────────────────
/** A fala no bate-papo da Escola: sem o id de quem escreveu (só "minha"), com "esperando" quando espera quem conduz. */
create or replace function interno.escola_chat_json(m interno.aulas_chat) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', m.id, 'autor', null, 'minha', m.autor is not null and m.autor = auth.uid(), 'nome', m.nome, 'corpo', m.corpo, 'tipo', m.tipo,
    'oculta', m.oculta, 'retido', false, 'esperando', m.oculta and m.avaliacao = 'revisao', 'criado_em', m.criado_em)
$$;

/** Fala no bate-papo da aula (precisa de conta). Abre meia hora antes e fecha quando a aula termina. Na Escola: só militante, com o codinome. */
create or replace function public.aula_chat_enviar(p_aula uuid, p_corpo text, p_tipo text default 'fala') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); a aulas_ao_vivo; m aulas_chat; v_corpo text := interno.txt(p_corpo, 'corpo', 1, 500); v_nome text; v_av jsonb; v_veredito text;
begin
  select * into a from aulas_ao_vivo where id = p_aula;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if a.publico = 'escola' and not interno.escola_aovivo_pode() then perform interno.erro('sem_permissao'); end if;
  if a.status in ('encerrada', 'cancelada') then perform interno.erro('topico_trancado'); end if;
  if not (a.status = 'ao_vivo' or a.inicio < now() + interval '30 minutes' or interno.conduz(a)) then perform interno.erro('topico_trancado'); end if;
  if p_tipo not in ('fala', 'pergunta') then perform interno.erro('invalido:tipo'); end if;
  perform interno.limite('aula_chat', 40, 2);
  if a.publico = 'escola' then
    -- Na Escola só se fala pelo codinome da Alumia: sem ele confirmado, nada de nome nenhum (nem o civil).
    if interno.escola_codinome(v) = '' then perform interno.erro('confirme_codinome'); end if;
    -- Só as regras do banco: nada sai para a avaliação externa nem para a fila da mediação da Comunidade. O que fica em
    -- dúvida espera quem conduz a aula (escondido para os outros, visível para quem escreveu).
    v_av := interno.veredito(v_corpo, interno.conduz(a), v);
    v_veredito := v_av ->> 'veredito';
    if v_veredito = 'bloquear' then
      perform interno.registrar('comunidade_bloqueada', p_aula::text, jsonb_build_object('tipo', 'aula_chat', 'motivo', v_av ->> 'motivo', 'departamento', 'reservado'));
      perform interno.erro('conteudo_recusado');
    end if;
    insert into aulas_chat (aula, autor, nome, corpo, tipo, oculta, retido, avaliacao, motivo)
    values (p_aula, v, interno.escola_codinome(v), v_corpo, p_tipo, v_veredito <> 'publicar', false,
            case v_veredito when 'publicar' then 'publicada' else 'revisao' end, coalesce(v_av ->> 'motivo', '')) returning * into m;
    return interno.escola_chat_json(m) || jsonb_build_object('avaliando', false);
  end if;
  -- Aula do site: como sempre (a mesma avaliação da Comunidade; quem conduz fala direto).
  v_av := interno.moderar_texto(v_corpo, v, interno.conduz(a));
  v_veredito := v_av ->> 'veredito';
  if v_veredito = 'bloquear' then
    perform interno.registrar('comunidade_bloqueada', p_aula::text, jsonb_build_object('tipo', 'aula_chat', 'motivo', v_av ->> 'motivo'));
    perform interno.erro('conteudo_recusado');
  end if;
  select nome into v_nome from perfis where id = v;
  insert into aulas_chat (aula, autor, nome, corpo, tipo, oculta, retido, avaliacao, motivo)
  values (p_aula, v, coalesce(v_nome, ''), v_corpo, p_tipo, v_veredito <> 'publicar', v_veredito = 'revisar',
          case v_veredito when 'publicar' then 'publicada' else 'revisao' end, v_av ->> 'motivo') returning * into m;
  return interno.chat_aula_json(m) || jsonb_build_object('avaliando', coalesce((v_av ->> 'externa')::boolean, false));
end $$;

/** O bate-papo. Aula do site: qualquer visitante lê (como antes). Aula da Escola: só militante; os outros recebem lista vazia. */
create or replace function public.aula_chat_listar(p_aula uuid, p_depois timestamptz default null) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare a aulas_ao_vivo; v_conduzo boolean := false;
begin
  select * into a from aulas_ao_vivo where id = p_aula;
  if not found then return '[]'::jsonb; end if;
  v_conduzo := interno.conduz(a);
  if a.publico = 'escola' then
    if not interno.escola_aovivo_pode() then return '[]'::jsonb; end if;
    return coalesce((select jsonb_agg(interno.escola_chat_json(m) order by m.criado_em) from (
      select * from aulas_chat m where m.aula = p_aula
        and (not m.oculta or v_conduzo or (m.autor = auth.uid() and m.avaliacao = 'revisao'))
        and (p_depois is null or m.criado_em > p_depois) order by m.criado_em desc limit 300) m), '[]'::jsonb);
  end if;
  return coalesce((select jsonb_agg(interno.chat_aula_json(m) order by m.criado_em) from (
    select * from aulas_chat m where m.aula = p_aula and (not m.oculta or v_conduzo or (m.retido and m.autor = auth.uid()))
      and (p_depois is null or m.criado_em > p_depois) order by m.criado_em desc limit 300) m), '[]'::jsonb);
end $$;

/**
 * Esconder ou mostrar uma fala. Aula do site: quem conduz, a mediação, a coordenação e quem escreveu (como antes).
 * Aula da Escola: quem conduz (a coordenação conduz todas); quem escreveu só esconde a própria fala. A mediação da
 * Comunidade fica de fora (supervisão fora da Escola).
 */
create or replace function public.aula_chat_moderar(p_id uuid, p_ocultar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); m aulas_chat; a aulas_ao_vivo;
begin
  select * into m from aulas_chat where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  select * into a from aulas_ao_vivo where id = m.aula;
  if a.publico = 'escola' then
    if not interno.escola_aovivo_pode() then perform interno.erro('nao_encontrado'); end if;
    if not (interno.conduz(a) or (m.autor = v and coalesce(p_ocultar, true))) then perform interno.erro('sem_permissao'); end if;
    update aulas_chat set oculta = coalesce(p_ocultar, true),
      avaliacao = case when not coalesce(p_ocultar, true) and avaliacao = 'revisao' then 'revista' else avaliacao end
    where id = p_id;
    return jsonb_build_object('ok', true);
  end if;
  if not (interno.conduz(a) or interno.media() or m.autor = v) then perform interno.erro('sem_permissao'); end if;
  update aulas_chat set oculta = p_ocultar where id = p_id;
  return jsonb_build_object('ok', true);
end $$;

-- 6. A Escola lê as suas aulas (contrato: lib/escola/contratos.ts) ─────────────────────────────────────────────────────────
/** Uma aula da Escola no formato do contrato (AulaAoVivoDaEscola). "agendada" vira "marcada". */
create or replace function interno.escola_aula_json(a interno.aulas_ao_vivo) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', a.id, 'titulo', a.titulo, 'inicio', a.inicio,
    'status', case a.status when 'agendada' then 'marcada' else a.status end,
    'caderno_aula', a.caderno_aula, 'youtube', a.youtube)
$$;

/** As aulas da Escola de hoje, as dos próximos 7 dias (horário de Brasília) e as gravadas dos últimos 90 dias. Só militante. */
create or replace function public.escola_aulas_hoje() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if not interno.escola_aovivo_pode() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'hoje', coalesce((select jsonb_agg(interno.escola_aula_json(a) order by a.inicio) from aulas_ao_vivo a
                      where a.publico = 'escola' and a.status in ('agendada', 'ao_vivo', 'encerrada')
                        and ((a.inicio at time zone 'America/Sao_Paulo')::date = v_hoje or a.status = 'ao_vivo')), '[]'::jsonb),
    'proximas', coalesce((select jsonb_agg(interno.escola_aula_json(a) order by a.inicio) from aulas_ao_vivo a
                          where a.publico = 'escola' and a.status = 'agendada'
                            and (a.inicio at time zone 'America/Sao_Paulo')::date between v_hoje + 1 and v_hoje + 7), '[]'::jsonb),
    'gravadas', coalesce((select jsonb_agg(interno.escola_aula_json(g) order by g.inicio desc) from (
                          select * from aulas_ao_vivo a where a.publico = 'escola' and a.status = 'encerrada' and a.youtube is not null
                            and a.inicio > now() - interval '90 days' order by a.inicio desc limit 12) g), '[]'::jsonb));
end $$;

/**
 * As gravações da Escola ligadas a um caderno ("caderno") ou a uma aula dele ("caderno/aula"): as aulas encerradas com
 * vídeo no YouTube, da mais nova para a mais velha. Só militante.
 */
create or replace function public.escola_gravacoes(p_caderno text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if not interno.escola_aovivo_pode() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_caderno, '') !~ '^[a-z0-9-]{2,80}(/[a-z0-9-]{2,120})?$' then perform interno.erro('invalido:caderno'); end if;
  return coalesce((select jsonb_agg(interno.escola_aula_json(g) order by g.inicio desc) from (
    select * from aulas_ao_vivo a where a.publico = 'escola' and a.status = 'encerrada' and a.youtube is not null
      and (a.caderno_aula = p_caderno or (strpos(p_caderno, '/') = 0 and a.caderno_aula like p_caderno || '/%'))
    order by a.inicio desc limit 20) g), '[]'::jsonb);
end $$;

-- 7. O que mais lia as aulas: calendário da equipe, feed de atividade e a função do YouTube ───────────────────────────────
/** O calendário único da equipe (o mesmo de antes): aula da Escola só para quem vê os Revolucionários, com o codinome. */
create or replace function public.calendario_equipe(p_de date, p_ate date) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_de date := coalesce(p_de, current_date); v_ate date := least(coalesce(p_ate, current_date + 30), coalesce(p_de, current_date) + 120);
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(e order by e ->> 'dia', e ->> 'hora') from (
    select jsonb_build_object('tipo', 'pauta', 'subtipo', x.tipo, 'id', x.id, 'titulo', x.titulo, 'dia', x.data_prevista, 'hora', '', 'situacao', x.status,
             'quem', coalesce((select interno.nome_visto(nome) from perfis where id = x.responsavel), '')) as e
      from pautas x where x.data_prevista between v_de and v_ate and x.status <> 'descartada'
    union all
    select jsonb_build_object('tipo', 'post', 'subtipo', d.formato, 'id', d.id, 'titulo', d.titulo, 'dia', d.data_prevista, 'hora', '', 'situacao', d.situacao, 'quem', '')
      from divulgacao d where d.data_prevista between v_de and v_ate
    union all
    select jsonb_build_object('tipo', 'aula', 'subtipo', a.disciplina, 'id', a.id, 'titulo', a.titulo, 'dia', (a.inicio at time zone 'America/Sao_Paulo')::date,
             'hora', to_char(a.inicio at time zone 'America/Sao_Paulo', 'HH24:MI'), 'situacao', a.status,
             'quem', case when a.publico = 'escola' then interno.escola_codinome(a.educador) else coalesce((select interno.nome_visto(nome) from perfis where id = a.educador), '') end)
      from aulas_ao_vivo a where a.status <> 'cancelada' and (a.inicio at time zone 'America/Sao_Paulo')::date between v_de and v_ate
        and (a.publico = 'site' or interno.ve_revolucionarios())
    union all
    select jsonb_build_object('tipo', 'reuniao', 'subtipo', r.tipo, 'id', r.id, 'titulo', r.titulo, 'dia', (r.inicio at time zone 'America/Sao_Paulo')::date,
             'hora', to_char(r.inicio at time zone 'America/Sao_Paulo', 'HH24:MI'), 'situacao', r.status, 'quem', '')
      from reunioes r where r.status <> 'cancelada' and (r.inicio at time zone 'America/Sao_Paulo')::date between v_de and v_ate and (interno.reuniao_entra(r) or r.tipo = 'aberta')
  ) eventos), '[]'::jsonb);
end $$;

-- O feed de atividade do painel ("Aula ao vivo marcada: <título>") é lido pela equipe toda: aula da Escola não entra.
do $$
begin
  if to_regprocedure('interno.atividade_gatilho()') is not null then
    drop trigger if exists atividade on interno.aulas_ao_vivo;
    create trigger atividade after insert on interno.aulas_ao_vivo for each row when (new.publico = 'site') execute function interno.atividade_gatilho();
  end if;
end $$;

/** Para a função do serviço "youtube": o mesmo de antes, com o público (aula da Escola vai sempre não listada) e, na Escola, sem nome. */
create or replace function public.youtube_transmissao_dados(p_aula uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if not interno.servico() then perform interno.erro('sem_permissao'); end if;
  return (select jsonb_build_object('id', a.id, 'titulo', a.titulo, 'descricao', case when a.publico = 'escola' then '' else a.descricao end, 'disciplina', a.disciplina, 'inicio', a.inicio,
            'duracao', a.duracao, 'status', a.status, 'publico', a.publico,
            'educador', case when a.publico = 'escola' then '' else coalesce((select nome from perfis where id = a.educador), '') end,
            'youtube', t.broadcast, 'stream', t.stream, 'rtmp', t.rtmp, 'chave', t.chave)
          from aulas_ao_vivo a left join transmissoes t on t.aula = a.id where a.id = p_aula);
end $$;

-- 8. O bate-papo da Escola some 30 dias depois ───────────────────────────────────────────────────────────────────────────
/** Apaga o bate-papo das aulas da Escola encerradas (ou canceladas, ou abandonadas sem encerrar) há mais de 30 dias. */
create or replace function interno.escola_aovivo_faxina() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare n integer;
begin
  delete from aulas_chat m using aulas_ao_vivo a
  where a.id = m.aula and a.publico = 'escola'
    and ((a.status = 'encerrada' and coalesce(a.encerrada_em, a.inicio) < now() - interval '30 days')
      or (a.status = 'cancelada' and a.atualizado_em < now() - interval '30 days')
      or (a.status in ('agendada', 'ao_vivo') and a.inicio + make_interval(mins => a.duracao) < now() - interval '30 days'));
  get diagnostics n = row_count;
  return n;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-escola-aovivo-faxina', '41 5 * * *', $c$select interno.escola_aovivo_faxina()$c$);
  end if;
end $$;

-- 9. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
-- As de "public" abertas pela API (cada uma confere quem chama); as de "interno", fechadas.
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura, n.nspname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and (
             (n.nspname = 'public' and p.proname in ('aulas_ao_vivo_listar', 'aula_ao_vivo_ver', 'aula_ao_vivo_salvar', 'aula_ao_vivo_estado', 'aula_ao_vivo_apagar',
               'aula_ao_vivo_inscrever', 'aula_chat_enviar', 'aula_chat_listar', 'aula_chat_moderar', 'escola_aulas_hoje', 'escola_gravacoes', 'calendario_equipe', 'youtube_transmissao_dados'))
             or (n.nspname = 'interno' and p.proname in ('escola_aovivo_pode', 'escola_aula_ve', 'escola_codinome', 'escola_caderno_aula_ok', 'escola_pode_conduzir',
               'aula_json', 'escola_chat_json', 'escola_aula_json', 'escola_aovivo_faxina'))) loop
    execute format('revoke all on function %s from public', f.assinatura);
    if f.nspname = 'public' then
      execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
    elsif exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon, authenticated', f.assinatura);
    end if;
  end loop;
end $$;


-- ───────────────────────────── Escola de Formação (F6): a frente de atuação de cada militante, novembro de 2026 ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. Precisa da migração da F1
-- (20261108-escola-formacao-base.sql: interno.e_militante e interno.escola_militancia). Quem junta cola este bloco no fim do
-- install.sql, por último na ordem da Escola (F1, F4, F5, F3, F6). Plano: docs/plano-2026-11/PLANO-ESCOLA.md, seção 4.6.
-- Teste: npm run testar:escola-frente (Postgres de verdade dentro do Node, com o install.sql, a F1 e esta migração).
--
-- O que nasce aqui (nenhuma tabela nova; a coluna escola_militancia.frente já existe desde a F1):
--  1. public.escola_frente_escolher(p_frente): o militante escolhe (ou tira) a própria frente de atuação, entre as 7
--     confirmadas em 07/11. Só a própria: ninguém escolhe pelo outro aqui (a coordenação ajusta pelo painel, F4).
--  2. public.escola_frentes_somadas(): só a CONTAGEM de militantes por frente, para a página A Frente. Nunca nomes.
--     Frente com menos de 3 pessoas não aparece: número muito pequeno ajuda a descobrir quem é (ser militante revela
--     opinião política, dado sensível, LGPD art. 5º, II e art. 11).
--
-- Segurança (mesma regra das outras migrações da Escola): security definer, search_path fixo, entrada por interno.eu(),
-- freio por interno.limite. Quem não é militante recebe "sem_permissao" e não aprende nada.

-- 1. Escolher a frente ───────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * O militante escolhe a frente em que atua (ou null, para tirar). Valores: os mesmos do check de
 * interno.escola_militancia.frente (lib/escola/contratos.ts, FRENTES_DE_ATUACAO). Quem representa o departamento e ainda
 * não tinha a linha de militância ganha a linha aqui, como em escola_eu. A coordenação que não é do departamento não tem
 * frente própria (não é militante de base): recebe "sem_militancia".
 */
create or replace function public.escola_frente_escolher(p_frente text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  f text := nullif(btrim(coalesce(p_frente, '')), '');
begin
  if not interno.e_militante(v) then perform interno.erro('sem_permissao'); end if;
  if f is not null and f not in ('estudantil', 'bairros', 'trabalho', 'agitprop', 'atos', 'cultura', 'solidariedade') then
    perform interno.erro('invalido:frente');
  end if;
  perform interno.limite('escola_frente_escolher', 20, 60);
  if interno.membro_direto(v, 'revolucionarios') then perform interno.escola_militancia_criar(v); end if;
  update escola_militancia set frente = f where usuario = v;
  if not found then perform interno.erro('sem_militancia'); end if;
  return jsonb_build_object('ok', true);
end $$;

-- 2. Quantos em cada frente ──────────────────────────────────────────────────────────────────────────────────────────────
/**
 * {frente: quantos}, só de militantes de verdade (do departamento, conta ativa). Frente com menos de 3 fica de fora.
 * Só militante (ou a coordenação) pergunta; o resto recebe "sem_permissao".
 */
create or replace function public.escola_frentes_somadas() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  r jsonb;
begin
  if not interno.e_militante(v) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('escola_frentes_somadas', 60, 1);
  select coalesce(jsonb_object_agg(s.frente, s.n), '{}'::jsonb) into r
  from (
    select m.frente, count(*)::int as n
    from escola_militancia m
    join perfis p on p.id = m.usuario and not p.suspenso
    where m.frente is not null and interno.membro_direto(m.usuario, 'revolucionarios')
    group by m.frente
    having count(*) >= 3
  ) s;
  return r;
end $$;

-- 3. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
-- Só os papéis da API chamam (a própria função recusa quem não é militante); "public" não herda execute.
revoke all on function public.escola_frente_escolher(text), public.escola_frentes_somadas() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant execute on function public.escola_frente_escolher(text), public.escola_frentes_somadas() to anon, authenticated, service_role;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
-- Escola com menos metadados (docs/auditoria/ESCOLA-2026-11-09.md). Pode rodar sozinho no SQL Editor; o install.sql já traz o mesmo.

-- 9. Menos metadados da Escola (09/11/2026) ───────────────────────────────────────────────────────────────────────────
/**
 * Apaga o bate-papo das aulas da Escola encerradas (ou canceladas, ou abandonadas sem encerrar) há mais de 30 dias.
 * Desde 09/11/2026 (docs/auditoria/ESCOLA-2026-11-09.md, menos metadados), também some, 1 dia depois do fim da aula da
 * Escola, quem se inscreveu nela e as chaves de sala de cada um; e, todo dia, as contagens de pedidos da Escola
 * (interno.limites, que guardam a conta e a hora) da véspera para trás. O mapa "quem foi a qual aula" não fica.
 */
create or replace function interno.escola_aovivo_faxina() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare n integer; m integer;
begin
  delete from aulas_chat c using aulas_ao_vivo a
  where a.id = c.aula and a.publico = 'escola'
    and ((a.status = 'encerrada' and coalesce(a.encerrada_em, a.inicio) < now() - interval '30 days')
      or (a.status = 'cancelada' and a.atualizado_em < now() - interval '30 days')
      or (a.status in ('agendada', 'ao_vivo') and a.inicio + make_interval(mins => a.duracao) < now() - interval '30 days'));
  get diagnostics n = row_count;
  delete from aulas_inscricoes i using aulas_ao_vivo a
  where a.id = i.aula and a.publico = 'escola'
    and ((a.status = 'encerrada' and coalesce(a.encerrada_em, a.inicio) < now() - interval '1 day')
      or (a.status = 'cancelada' and a.atualizado_em < now() - interval '1 day')
      or (a.status in ('agendada', 'ao_vivo') and a.inicio + make_interval(mins => a.duracao) < now() - interval '1 day'));
  get diagnostics m = row_count; n := n + m;
  delete from aulas_sala_chaves k using aulas_ao_vivo a
  where a.id = k.aula and a.publico = 'escola'
    and (a.status in ('encerrada', 'cancelada') or a.inicio + make_interval(mins => a.duracao) < now() - interval '1 day');
  get diagnostics m = row_count; n := n + m;
  delete from limites where janela < now() - interval '1 day' and (chave like 'escola%' or chave like 'aula_sala_chave:%' or chave like 'aula_inscrever:%');
  return n;
end $$;

-- ───────────────────────────── Alumia no Fediverso: o modo total (servidor de verdade, sem aba à parte) ─────────────────────────────
-- Migração acrescentável: pode rodar mais de uma vez, sem apagar dado nenhum. O mesmo bloco está no fim do install.sql. Roda DEPOIS
-- de 2026-11-alumia.sql (a federação opcional) e de todas as migrações da Rede v2. Plano: PLANO-FEDIVERSO.md, frente F3 (banco),
-- contratos das seções 3.1, 3.2 e 3.4. Teste: scripts/testar-fediverso-banco.mjs.
--
-- DESLIGADO POR PADRÃO. Tudo o que muda de comportamento depende de interno.rede_fed_total() (recurso "fediverso-total") e, para as
-- comunidades como Group (Lemmy), de interno.rede_fed_grupos_ligado() (recurso "fediverso-grupos"). Com os dois desligados, a
-- federação continua exatamente como em 2026-11-alumia.sql: opt-in, versão 1 do consentimento, só "internet" nas disciplinas.
-- Para ligar (depois de publicar o site com a flag): pelo painel (Site › Controles avançados, tabela interno.recursos_vivos) ou
--   update interno.configuracoes set valor = valor || '{"total": true}'::jsonb where chave = 'fediverso';
-- ("grupos": true liga o Group; "comunidades_de_luta": true deixa sair também as comunidades abertas de lutas e do instituto.)
--
-- O que este arquivo faz:
--   1. Interruptores: rede_fed_total, rede_fed_grupos_ligado. Com o total ligado, a versão do consentimento passa a 2.
--   2. Consentimento (D2): rede_consentimentos.fediverso (o item destacado no consentimento de entrada da Alumia). Aceitar com o
--      item marcado liga a federação sozinho (gatilho); desmarcar desliga. Sem o item, nada sai. LGPD art. 7º, I e art. 8º
--      (consentimento livre, específico e destacado, com versão e data); art. 11, I (opinião política e filiação sindical são dado
--      sensível); art. 33, VIII (transferência internacional só com consentimento específico e em destaque, avisando que servidor de
--      fora não pode ser obrigado a apagar); art. 8º, § 5º e art. 18, VI (revogar e apagar a qualquer momento: desligar no perfil).
--      A regra de quem marcou o item com a flag desligada: rede_consentimentos.fediverso_versao guarda a versão em vigor quando a
--      pessoa respondeu o item (1 sem a flag, 2 com ela). Só o item marcado na versão 2 liga a federação. Quem marcou na versão 1 NÃO é ligado
--      sozinho quando a flag liga: a tela pede de novo (rede_fed_situacao devolve pedir_fediverso = true) e a pessoa aceita pelo
--      rede_aderir (ou rede_fed_ligar com a versão 2). A flag pode ter ficado desligada por meses e o texto da tela pode ter mudado:
--      consentimento é para a finalidade determinada que a pessoa leu (LGPD art. 8º, § 4º), então pedir de novo é o caminho seguro.
--   3. O que sai (D3): para quem consentiu na versão 2, sai todo post em que a PESSOA escolheu o público mais aberto ("internet"),
--      no perfil e nas comunidades abertas das disciplinas (e das de lutas e do instituto só com "comunidades_de_luta"), mesmo que a
--      matriz o tenha rebaixado para "membros" fora das disciplinas. O "membros" escolhido de propósito (a tela diz "Membros da
--      Alumia") NUNCA sai: a escolha da pessoa manda (LGPD art. 6º, I e III: finalidade e necessidade). DECISÃO PENDENTE (Jonathan,
--      F4): hoje public.rede_publicar recusa "internet" fora das disciplinas, então post de perfil escrito pela tela é sempre
--      "membros" e não sai; para o perfil federar, a junção precisa deixar rede_publicar aceitar "internet" no perfil no modo total
--      (rótulo "Internet e Fediverso"), ou mudar o rótulo de "membros". A resposta a nota de fora (rede_fed_responder_remoto) já
--      sai como "internet". Nunca saem também: núcleo,
--      comunidade fechada ou restrita, "seguidores", "comunidade", "equipe", aviso do instituto, compartilhamento, retido, oculto ou
--      apagado. Quem consentiu só na versão 1 continua com a regra antiga (só "internet" que a matriz mostra sem conta). D5:
--      "seguidores" nunca sai. Perfil trancado ou invisível continua fora (rede_fed_impedimento não muda, plano F3.1): a ação
--      'ator' devolve trancado = false sempre, e manuallyApprovesFollowers fica false.
--      Quem a pessoa menciona lá fora (e o autor da nota de fora que ela responde) recebe o Create, o Update e o Delete na própria
--      caixa, mesmo sem segui-la (sem isso a menção não notifica e a edição e a retirada não chegam).
--   4. O que entra: nota de fora guardada também quando responde ou menciona alguém daqui (não só de quem alguém segue), com HTML
--      já limpo pelo servidor do site e conferido de novo aqui (lista permitida; o que não passa fica só como texto), mídia só como
--      endereço https e metadados (o navegador busca pela rota-proxy, sem o IP de quem lê sair), visibilidade, fio e contexto.
--      Direto ou limitado NUNCA é guardado (a Alumia não tem DM federada). Só-seguidores só se alguém daqui segue o autor, e só
--      essa pessoa vê. A guarda de 30 dias vale para nota sem ligação com nada daqui; a que responde ou menciona algo daqui fica
--      enquanto o post local (ou a menção) existir (LGPD art. 15 e 16: término do tratamento quando acaba a finalidade).
--   5. Tabelas novas (todas em interno, com RLS e sem permissão direta): fediverso_interacoes (curtir e impulsionar, de fora e
--      daqui), fediverso_mencoes, fediverso_dominios (circuito por domínio), fediverso_denuncias (Flag de fora e para fora),
--      fediverso_bloqueios_recebidos, fediverso_filtros (a pessoa bloqueia ou silencia alguém de fora), fediverso_grupos e
--      fediverso_grupo_seguidores (Group). O nome começa com "fediverso_" para não se misturar às oito rede_fed_* de 2026-11-alumia.
--   6. Avisos: interno.avisos ganha ator_remoto e objeto_remoto; tipos fed_seguidor, fed_resposta, fed_mencao, fed_curtida,
--      fed_impulso, que respeitam a preferência do tipo de sempre (seguidor, resposta, mencao, apoio, citacao).
--   7. As ações novas de public.rede_fed_servidor (seção 3.1), as RPCs da tela (seção 3.2) e os tipos novos da fila (seção 3.4).
--      Com a flag desligada, as ações que já existiam respondem como antes (fila_pegar até 100 itens, fila_feito sem circuito, 410
--      ou 429); nota_recebida guarda só o que 'recebido' guardava (nota de quem alguém daqui segue); e interacao,
--      denuncia_recebida e bloqueio_recebido respondem {ok: false, motivo: 'desligado'} sem gravar nada.
--
-- Nomes (diferentes do PLANO-FEDIVERSO.md, de propósito): o arquivo é 20261109 (e não 20261108) e as tabelas novas são
-- interno.fediverso_* (e não rede_fed_*): fediverso_interacoes = rede_fed_interacoes, fediverso_mencoes = rede_fed_mencoes,
-- fediverso_dominios = rede_fed_dominios, fediverso_denuncias = rede_fed_denuncias, fediverso_bloqueios_recebidos =
-- rede_fed_bloqueios_recebidos. Nenhuma frente lê essas tabelas direto (só pelas RPCs e ações), então só o plano muda.
-- Contrato 3.1, ação 'interacao': o Announce de uma nota de FORA vem em objeto_remoto (o post_local continua aceito para isso, por
-- compatibilidade); post_local é só o endereço de um post daqui.
-- rede_aviso_listar é remendado no lugar (seção 4): quem recriar a função no pacote avisos precisa levar ator_remoto,
-- atores_remotos e objeto_remoto para a definição oficial. O teste do banco do Fediverso confere que os três estão lá.
--
-- Privacidade: nada de IP; nada de quem denunciou sai na Flag (ela sai assinada pela instância); DMs (rede_dm_*) e "seguidores"
-- nunca são lidos aqui; nada sai de quem não consentiu.

-- ── 1. Interruptores ────────────────────────────────────────────────────────────────────────────────────────────────────

/** Uma chave booleana da configuração 'fediverso' (interno.configuracoes). Qualquer coisa que não seja true vale false. */
create or replace function interno.rede_fed_config_bool(p_chave text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce((select valor ->> p_chave from configuracoes where chave = 'fediverso'), '') = 'true'
$$;

/** Um recurso decidido pelo painel (interno.recursos_vivos): true, false ou nulo (sem decisão, ou a tabela ainda não existe). */
create or replace function interno.rede_fed_recurso_vivo(p_nome text) returns boolean language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v boolean;
begin
  if to_regclass('interno.recursos_vivos') is null then return null; end if;
  execute 'select ligado from interno.recursos_vivos where nome = $1' into v using p_nome;
  return v;
end $$;

/** O modo total ("fediverso-total") está ligado? Desligado no painel desliga sempre; sem decisão do painel, vale a configuração. */
create or replace function interno.rede_fed_total() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(interno.rede_fed_recurso_vivo('fediverso-total'), interno.rede_fed_config_bool('total'))
$$;

/** As comunidades como Group ("fediverso-grupos")? Só com o modo total ligado. */
create or replace function interno.rede_fed_grupos_ligado() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.rede_fed_total() and coalesce(interno.rede_fed_recurso_vivo('fediverso-grupos'), interno.rede_fed_config_bool('grupos'))
$$;

/** Versão do consentimento da federação: 1 (opt-in de 2026-11-alumia) ou 2 (o item destacado do modo total). Mudou o texto, sobe. */
create or replace function interno.rede_fed_versao() returns integer language sql stable security definer set search_path = interno, pg_temp as $$
  select case when interno.rede_fed_total() then 2 else 1 end
$$;

-- ── 2. Colunas novas nas tabelas que já existem ────────────────────────────────────────────────────────────────────────

-- A pessoa escolhe aparecer em diretórios e buscas de fora (discoverable/indexable). Desligado por padrão.
alter table interno.rede_fed_atores add column if not exists descobrivel boolean not null default false;

-- O rosto e o tipo do ator de fora (Person, Group, Service…), para o cartão e o perfil remoto.
alter table interno.rede_fed_remotos add column if not exists avatar text check (avatar is null or (avatar ~ '^https://' and char_length(avatar) <= 500));
alter table interno.rede_fed_remotos add column if not exists tipo text check (tipo is null or tipo ~ '^[A-Za-z]{2,40}$');

-- A nota de fora completa: HTML já limpo, aviso de conteúdo, visibilidade, fio, mídia (só endereço e metadados) e a ligação com
-- algo daqui (post_local: o post daqui a que ela responde, direta ou indiretamente; apagado o post, a nota vai junto).
alter table interno.rede_fed_recebidos add column if not exists html text check (html is null or char_length(html) <= 20000);
alter table interno.rede_fed_recebidos add column if not exists sensivel boolean not null default false;
alter table interno.rede_fed_recebidos add column if not exists visibilidade text not null default 'publico' check (visibilidade in ('publico', 'nao_listado', 'seguidores'));
alter table interno.rede_fed_recebidos add column if not exists em_resposta_a text check (em_resposta_a is null or char_length(em_resposta_a) <= 500);
alter table interno.rede_fed_recebidos add column if not exists contexto text check (contexto is null or char_length(contexto) <= 500);
alter table interno.rede_fed_recebidos add column if not exists midia jsonb not null default '[]'::jsonb;
alter table interno.rede_fed_recebidos add column if not exists post_local uuid references interno.rede_posts (id) on delete cascade;
alter table interno.rede_fed_recebidos add column if not exists editado_em timestamptz;
create index if not exists rede_fed_recebidos_resposta on interno.rede_fed_recebidos (em_resposta_a) where em_resposta_a is not null;
create index if not exists rede_fed_recebidos_post_local on interno.rede_fed_recebidos (post_local) where post_local is not null;

-- A fila: tipos novos (seção 3.4), entregas da comunidade (Group) e da instância (Flag) sem perfil.
alter table interno.rede_fed_fila add column if not exists comunidade text check (comunidade is null or comunidade ~ '^[a-z0-9-]{2,60}$');
alter table interno.rede_fed_fila alter column perfil drop not null;
do $$
declare r record;
begin
  for r in select conname from pg_constraint where conrelid = 'interno.rede_fed_fila'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) like '%tipo%' and conname <> 'rede_fed_fila_tipo_v2' loop
    execute format('alter table interno.rede_fed_fila drop constraint %I', r.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_fed_fila'::regclass and conname = 'rede_fed_fila_tipo_v2') then
    alter table interno.rede_fed_fila add constraint rede_fed_fila_tipo_v2 check (tipo in ('create', 'update', 'delete', 'accept', 'reject', 'follow', 'undo-follow',
      'like', 'undo-like', 'announce', 'undo-announce', 'flag', 'block', 'undo-block', 'group-announce', 'group-accept'));
  end if;
end $$;

-- Um post daqui que responde a uma nota de fora (sai com inReplyTo para ela).
alter table interno.rede_posts add column if not exists resposta_a_remota text check (resposta_a_remota is null or (resposta_a_remota ~ '^https://' and char_length(resposta_a_remota) <= 500));
create index if not exists rede_posts_resposta_remota on interno.rede_posts (resposta_a_remota) where resposta_a_remota is not null;

-- O item destacado do consentimento de entrada da Alumia: "meus posts públicos também vão para o Fediverso" (D2).
alter table interno.rede_consentimentos add column if not exists fediverso boolean not null default false;
-- A versão do consentimento da federação em vigor quando a pessoa respondeu o item (1 sem a flag, 2 com ela). Só marcado na 2 liga.
alter table interno.rede_consentimentos add column if not exists fediverso_versao smallint;

-- Avisos com gente de fora: o ator remoto (endereço público) e a nota de fora (resposta ou menção).
alter table interno.avisos add column if not exists ator_remoto text check (ator_remoto is null or (ator_remoto ~ '^https://' and char_length(ator_remoto) <= 500));
alter table interno.avisos add column if not exists objeto_remoto text check (objeto_remoto is null or (objeto_remoto ~ '^https://' and char_length(objeto_remoto) <= 500));
alter table interno.avisos drop constraint if exists avisos_tipo;
alter table interno.avisos add constraint avisos_tipo check (tipo is null or tipo in ('resposta', 'mencao', 'citacao', 'seguidor', 'chamado', 'nucleo', 'moderacao', 'apoio',
  'fed_seguidor', 'fed_resposta', 'fed_mencao', 'fed_curtida', 'fed_impulso'));
create unique index if not exists avisos_fed_interacao on interno.avisos (para, tipo, post, ator_remoto) where tipo in ('fed_curtida', 'fed_impulso');
create unique index if not exists avisos_fed_nota on interno.avisos (para, tipo, objeto_remoto) where tipo in ('fed_resposta', 'fed_mencao');
create unique index if not exists avisos_fed_seguidor on interno.avisos (para, ator_remoto) where tipo = 'fed_seguidor';

-- ── 3. Tabelas novas ───────────────────────────────────────────────────────────────────────────────────────────────────

-- Curtir (Like) e impulsionar (Announce). Entrada: alguém de fora num post daqui (post_local) ou o impulso de uma nota de fora por
-- quem alguém daqui segue (objeto_remoto). Saída: alguém daqui numa nota de fora (perfil + objeto_remoto; ator = autor da nota).
create table if not exists interno.fediverso_interacoes (
  id bigserial primary key,
  direcao text not null check (direcao in ('entrada', 'saida')),
  tipo text not null check (tipo in ('like', 'announce')),
  ator text check (ator is null or (ator ~ '^https://' and char_length(ator) <= 500)),
  perfil uuid references interno.perfis (id) on delete cascade,
  post_local uuid references interno.rede_posts (id) on delete cascade,
  objeto_remoto text check (objeto_remoto is null or (objeto_remoto ~ '^https://' and char_length(objeto_remoto) <= 500)),
  atividade_id text check (atividade_id is null or char_length(atividade_id) <= 500),
  criado_em timestamptz not null default now(),
  check ((direcao = 'entrada' and ator is not null and perfil is null and num_nonnulls(post_local, objeto_remoto) = 1)
      or (direcao = 'saida' and perfil is not null and post_local is null and objeto_remoto is not null))
);
create unique index if not exists fediverso_interacoes_local on interno.fediverso_interacoes (tipo, ator, post_local) where direcao = 'entrada' and post_local is not null;
create unique index if not exists fediverso_interacoes_remota on interno.fediverso_interacoes (tipo, ator, objeto_remoto) where direcao = 'entrada' and objeto_remoto is not null;
create unique index if not exists fediverso_interacoes_saida on interno.fediverso_interacoes (tipo, perfil, objeto_remoto) where direcao = 'saida';
create index if not exists fediverso_interacoes_atividade on interno.fediverso_interacoes (ator, atividade_id) where atividade_id is not null;

-- Nota de fora que menciona alguém daqui (só quem tem a federação ligada pode ser mencionado de fora).
create table if not exists interno.fediverso_mencoes (
  nota text not null references interno.rede_fed_recebidos (id) on delete cascade,
  perfil uuid not null references interno.perfis (id) on delete cascade,
  criado_em timestamptz not null default now(),
  primary key (nota, perfil)
);
create index if not exists fediverso_mencoes_perfil on interno.fediverso_mencoes (perfil);

-- O circuito por domínio: 5 falhas de conexão seguidas = domínio "morto" por 1 h, depois 6 h, depois 24 h. Os itens esperam sem
-- gastar tentativa. Um sucesso zera.
create table if not exists interno.fediverso_dominios (
  dominio text primary key check (dominio ~ '^[a-z0-9.-]{3,253}$'),
  falhas smallint not null default 0,
  nivel smallint not null default 0,
  morto_ate timestamptz,
  ultima_falha timestamptz,
  ultimo_ok timestamptz
);

-- Denúncias com o Fediverso. Entrada: a Flag de outra instância (vira também denúncia na fila da mediação, rede_denuncias, para
-- cada post ou perfil daqui que ela aponta). Saída: alguém daqui denuncia uma nota ou um ator de fora; com "encaminhar", a Flag
-- sai assinada pela instância, sem dizer quem denunciou.
create table if not exists interno.fediverso_denuncias (
  id uuid primary key default gen_random_uuid(),
  protocolo text not null unique default upper(substr(md5(gen_random_uuid()::text), 1, 10)),
  direcao text not null check (direcao in ('entrada', 'saida')),
  dominio text not null check (dominio ~ '^[a-z0-9.-]{3,253}$'),
  ator text check (ator is null or (ator ~ '^https://' and char_length(ator) <= 500)),
  alvos jsonb not null default '[]'::jsonb,
  categoria text not null default 'outro' check (categoria in ('menores', 'ameaca', 'exposicao', 'violencia', 'autolesao', 'odio', 'assedio', 'golpe', 'spam', 'outro')),
  conteudo text not null default '' check (char_length(conteudo) <= 2000),
  quem uuid references interno.perfis (id) on delete set null,
  encaminhar boolean not null default false,
  denuncias uuid[] not null default '{}',
  situacao text not null default 'aberta' check (situacao in ('aberta', 'em_analise', 'resolvida', 'descartada')),
  criado_em timestamptz not null default now()
);
create index if not exists fediverso_denuncias_fila on interno.fediverso_denuncias (situacao, criado_em desc);

-- Alguém de fora bloqueou alguém daqui (Block): as relações caem e o que é dele some da linha de quem foi bloqueado.
create table if not exists interno.fediverso_bloqueios_recebidos (
  perfil uuid not null references interno.perfis (id) on delete cascade,
  ator text not null check (ator ~ '^https://' and char_length(ator) <= 500),
  criado_em timestamptz not null default now(),
  primary key (perfil, ator)
);

-- Alguém daqui bloqueou (sai um Block) ou silenciou (só aqui) alguém de fora.
create table if not exists interno.fediverso_filtros (
  usuario uuid not null references interno.perfis (id) on delete cascade,
  ator text not null check (ator ~ '^https://' and char_length(ator) <= 500),
  tipo text not null check (tipo in ('bloqueio', 'silencio')),
  atividade text check (atividade is null or char_length(atividade) <= 500),
  criado_em timestamptz not null default now(),
  primary key (usuario, ator)
);

-- A comunidade como Group (Lemmy, FEP-1b12): o par de chaves (a privada vem cifrada pelo servidor do site) e quem segue de fora.
create table if not exists interno.fediverso_grupos (
  comunidade text primary key references interno.rede_comunidades (slug) on delete cascade on update cascade,
  chave_publica text check (chave_publica is null or char_length(chave_publica) <= 2000),
  chave_privada text check (chave_privada is null or char_length(chave_privada) <= 6000),
  criado_em timestamptz not null default now()
);
create table if not exists interno.fediverso_grupo_seguidores (
  comunidade text not null references interno.rede_comunidades (slug) on delete cascade on update cascade,
  ator text not null check (ator ~ '^https://' and char_length(ator) <= 500),
  inbox text not null check (inbox ~ '^https://' and char_length(inbox) <= 500),
  inbox_compartilhada text check (inbox_compartilhada is null or (inbox_compartilhada ~ '^https://' and char_length(inbox_compartilhada) <= 500)),
  pedido text not null default '' check (char_length(pedido) <= 500),
  criado_em timestamptz not null default now(),
  primary key (comunidade, ator)
);

alter table interno.fediverso_interacoes enable row level security;
alter table interno.fediverso_mencoes enable row level security;
alter table interno.fediverso_dominios enable row level security;
alter table interno.fediverso_denuncias enable row level security;
alter table interno.fediverso_bloqueios_recebidos enable row level security;
alter table interno.fediverso_filtros enable row level security;
alter table interno.fediverso_grupos enable row level security;
alter table interno.fediverso_grupo_seguidores enable row level security;
revoke all on interno.fediverso_interacoes, interno.fediverso_mencoes, interno.fediverso_dominios, interno.fediverso_denuncias,
  interno.fediverso_bloqueios_recebidos, interno.fediverso_filtros, interno.fediverso_grupos, interno.fediverso_grupo_seguidores from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on interno.fediverso_interacoes, interno.fediverso_mencoes, interno.fediverso_dominios, interno.fediverso_denuncias,
      interno.fediverso_bloqueios_recebidos, interno.fediverso_filtros, interno.fediverso_grupos, interno.fediverso_grupo_seguidores from anon, authenticated;
    revoke all on sequence interno.fediverso_interacoes_id_seq from anon, authenticated;
  end if;
end $$;

-- ── 4. Endereços daqui, HTML de fora e avisos ──────────────────────────────────────────────────────────────────────────

/** O domínio deste servidor da federação (o de url_entrega na configuração), ou nulo quando ainda não foi configurado. */
create or replace function interno.rede_fed_host_local() returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.rede_fed_dominio((select valor ->> 'url_entrega' from configuracoes where chave = 'fediverso'))
$$;

/** O id de post daqui num endereço (…/api/fediverso/p/<uuid> ou …/p/<uuid>, no host daqui) ou num uuid solto. Não confere se existe. */
create or replace function interno.rede_fed_uuid_local(p_ref text) returns uuid language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare m text[]; v_host text := interno.rede_fed_host_local();
begin
  if p_ref is null then return null; end if;
  if p_ref ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return p_ref::uuid; end if;
  m := regexp_match(p_ref, '^https://([^/:?#]+)(?::[0-9]+)?/(?:api/fediverso/p|p)/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/?$');
  if m is null or (v_host is not null and lower(m[1]) <> v_host) then return null; end if;
  return m[2]::uuid;
end $$;

/** O @nome daqui num endereço de ator (…/api/fediverso/u/<nome> ou …/@<nome>, no host daqui). */
create or replace function interno.rede_fed_handle_local(p_ref text) returns text language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare m text[]; v_host text := interno.rede_fed_host_local();
begin
  m := regexp_match(coalesce(p_ref, ''), '^https://([^/:?#]+)(?::[0-9]+)?/(?:api/fediverso/u/|@)([a-z0-9_]{3,20})/?$');
  if m is null or (v_host is not null and lower(m[1]) <> v_host) then return null; end if;
  return m[2];
end $$;

/** O post daqui que já saiu para o Fediverso (e não foi retirado) para o qual este endereço aponta; nulo se não há. */
create or replace function interno.rede_fed_post_local(p_ref text) returns uuid language sql stable security definer set search_path = interno, pg_temp as $$
  select e.post from rede_fed_enviados e where e.post = interno.rede_fed_uuid_local(p_ref) and e.apagado_em is null
$$;

/**
 * Segunda tranca do HTML de fora (a primeira é a limpeza do servidor do site, lista permitida igual à do Mastodon 4.2+): só as
 * tags que o Mastodon mantém, nenhum atributo de evento, estilo ou fonte, e link só https, http, mailto, âncora ou caminho.
 * O que não passa é guardado só como texto (a coluna html fica nula).
 */
create or replace function interno.rede_fed_html_ok(p_html text) returns boolean language plpgsql immutable set search_path = interno, pg_temp as $$
declare t text; h text;
begin
  if p_html is null or char_length(p_html) > 20000 then return false; end if;
  if p_html ~ '<!--|<!\[|<\?|<!' then return false; end if;
  for t in select lower(m[1]) from regexp_matches(p_html, '<\s*/?\s*([A-Za-z][A-Za-z0-9:-]*)', 'g') m loop
    if t not in ('p', 'br', 'span', 'a', 'del', 's', 'pre', 'blockquote', 'code', 'b', 'strong', 'u', 'i', 'em', 'ul', 'ol', 'li',
                 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'sub', 'sup') then return false; end if;
  end loop;
  if p_html ~* '[\s"''/](on[a-z]+|style|src|srcset|formaction|action|xmlns|xlink:href|background|lowsrc|dynsrc)\s*=' then return false; end if;
  for h in select btrim(m[1], '"''') from regexp_matches(p_html, 'href\s*=\s*("[^"]*"|''[^'']*''|[^\s>]+)', 'gi') m loop
    if h !~* '^(https?://|mailto:|#|/)' or h ~ '[\s\\]' or h ~ '&#' then return false; end if;
  end loop;
  return true;
end $$;

/** O tipo de aviso de sempre que vale para a preferência de um tipo da federação (curtida = apoio, impulso = citação). */
create or replace function interno.rede_fed_aviso_base(p_tipo text) returns text language sql immutable as $$
  select case p_tipo when 'fed_seguidor' then 'seguidor' when 'fed_resposta' then 'resposta' when 'fed_mencao' then 'mencao'
                     when 'fed_curtida' then 'apoio' when 'fed_impulso' then 'citacao' else p_tipo end
$$;

/** A preferência de uma pessoa (pacote avisos), agora também para os tipos da federação, que seguem o tipo de sempre. */
create or replace function interno.rede3_aviso_pref(p_usuario uuid, p_tipo text, p_canal text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select case when p_tipo = 'moderacao' and p_canal = 'site' then true
    else coalesce((select p.ligado from rede_avisos_prefs p where p.usuario = p_usuario and p.tipo = interno.rede_fed_aviso_base(p_tipo) and p.canal = p_canal), p_canal = 'site') end
$$;

/** A chave que agrupa avisos, agora com os da federação: curtidas, impulsos e respostas de fora do mesmo post juntas; seguidores de fora juntos. */
create or replace function interno.rede3_aviso_chave(p_tipo text, p_post uuid, p_id uuid) returns text language sql immutable as $$
  select case when p_tipo in ('resposta', 'mencao', 'citacao', 'apoio', 'fed_resposta', 'fed_curtida', 'fed_impulso') and p_post is not null then p_tipo || ':' || p_post::text
              when p_tipo in ('seguidor', 'fed_seguidor') then p_tipo
              else 'n:' || p_id::text end
$$;

/**
 * Cria um aviso com gente de fora. Não avisa quem bloqueou ou silenciou esse ator de fora, nem conta suspensa; a preferência "no
 * site" do tipo de sempre vale pelo gatilho interno.rede3_aviso_antes. O texto não leva nada da nota de fora.
 */
create or replace function interno.rede_fed_avisar(p_para uuid, p_tipo text, p_post uuid, p_ator text, p_objeto text default null) returns void
language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if p_para is null or p_tipo not in ('fed_seguidor', 'fed_resposta', 'fed_mencao', 'fed_curtida', 'fed_impulso') or coalesce(p_ator, '') !~ '^https://' then return; end if;
  if not exists (select 1 from perfis where id = p_para and not suspenso) then return; end if;
  if exists (select 1 from fediverso_filtros f where f.usuario = p_para and f.ator = p_ator) then return; end if;
  insert into avisos (para, texto, categoria, tipo, post, ator_remoto, objeto_remoto)
  values (p_para, case p_tipo
      when 'fed_seguidor' then 'Uma pessoa de outro servidor do Fediverso começou a seguir você.'
      when 'fed_resposta' then 'Uma pessoa de outro servidor do Fediverso respondeu ao seu post.'
      when 'fed_mencao' then 'Uma pessoa de outro servidor do Fediverso mencionou você.'
      when 'fed_curtida' then 'Uma pessoa de outro servidor do Fediverso curtiu o seu post.'
      else 'Uma pessoa de outro servidor do Fediverso impulsionou o seu post.' end,
    'rede', p_tipo, p_post, left(p_ator, 500), case when coalesce(p_objeto, '') ~ '^https://' then left(p_objeto, 500) end)
  on conflict do nothing;
end $$;

/** Quem de fora aparece num grupo de avisos (até 2, do mais novo) e a nota de fora mais recente dele. Nulo quando ninguém é de fora. */
create or replace function interno.rede_fed_aviso_remoto(p_ids uuid[]) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  with u as (
    select a.ator_remoto, a.objeto_remoto, a.criado_em from avisos a where a.id = any (coalesce(p_ids, '{}')) and a.ator_remoto is not null
  ), d as (
    select u.ator_remoto, max(u.criado_em) as em from u group by u.ator_remoto order by max(u.criado_em) desc limit 2
  )
  select case when not exists (select 1 from u) then null else jsonb_build_object(
    'atores', (select jsonb_agg(jsonb_build_object('ator', d.ator_remoto, 'handle', r.handle, 'nome', r.nome, 'avatar', r.avatar,
                                                   'servidor', interno.rede_fed_dominio(d.ator_remoto)) order by d.em desc)
               from d left join rede_fed_remotos r on r.ator = d.ator_remoto),
    'objeto', (select u.objeto_remoto from u where u.objeto_remoto is not null order by u.criado_em desc limit 1)) end
$$;

-- rede_aviso_listar passa a devolver quem é de fora (ator_remoto, atores_remotos) e a nota de fora (objeto_remoto). A função é
-- remendada no lugar (como o bloco de nome da Alumia faz), para não reescrever o texto que o pacote avisos e a Alumia já deixaram.
do $$
declare
  v_def text;
  v_marca text := '''post'', n.post, ''alvo'', n.alvo, ''titulo'', n.titulo,';
begin
  v_def := pg_get_functiondef('public.rede_aviso_listar(text, integer)'::regprocedure);
  if position('ator_remoto' in v_def) > 0 then return; end if;
  if position(v_marca in v_def) = 0 then
    raise exception 'public.rede_aviso_listar mudou: o remendo do Fediverso (20261109-fediverso-total.sql) precisa ser revisto';
  end if;
  v_def := replace(v_def, v_marca, v_marca || '
      ''ator_remoto'', interno.rede_fed_aviso_remoto(n.ids) -> ''atores'' -> 0,
      ''atores_remotos'', coalesce(interno.rede_fed_aviso_remoto(n.ids) -> ''atores'', ''[]''::jsonb),
      ''objeto_remoto'', interno.rede_fed_aviso_remoto(n.ids) ->> ''objeto'',');
  execute v_def;
end $$;

-- ── 5. Regras: o que sai, ligar sozinho, o que se vê de fora ───────────────────────────────────────────────────────────

/**
 * A comunidade pode sair para o Fediverso (posts no modo total; Group com "fediverso-grupos")? Só aberta, e só das disciplinas,
 * a não ser que a configuração deixe sair também as abertas de lutas e do instituto ("comunidades_de_luta": D3, à espera da decisão).
 */
create or replace function interno.rede_fed_comunidade_ok(p_slug text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_comunidades c where c.slug = p_slug and c.tipo = 'aberta'
                 and (c.categoria = 'disciplinas' or interno.rede_fed_config_bool('comunidades_de_luta')))
$$;

/** A comunidade responde como Group? Com "fediverso-grupos" ligado e a comunidade podendo sair. */
create or replace function interno.rede_fed_grupo_ok(p_slug text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.rede_fed_grupos_ligado() and interno.rede_fed_comunidade_ok(p_slug)
$$;

/**
 * Este post pode sair para o Fediverso? Sempre: de quem ligou a federação, escrito depois de ligar, @nome igual ao do ator, nunca
 * aviso do instituto, núcleo ou compartilhamento, e resposta só se o post respondido também pode sair.
 * Regra da versão 1 (opt-in, e de quem só consentiu na versão 1): só o que qualquer pessoa lê sem conta ("internet").
 * Regra do modo total (D3), para quem consentiu na versão 2: o post em que a pessoa escolheu "internet" (o público mais aberto),
 * no perfil e nas comunidades abertas que podem sair (interno.rede_fed_comunidade_ok), mesmo que a matriz o rebaixe para "membros"
 * fora das disciplinas (é esse rebaixamento que D3 abre). O "membros" escolhido de propósito ("Membros da Alumia") nunca sai;
 * nunca "seguidores", "comunidade", "nucleo", "equipe", nem retido, oculto ou apagado. Quando a matriz deixa o post em "internet",
 * ele também tem de passar por interno.rede_ve(p, null), como na versão 1; o rebaixado passa pelas mesmas travas da matriz que não
 * dependem do público (comunidade fechada, restrita ou "fechado-…", retido, oculto, apagado).
 */
create or replace function interno.rede_fed_federavel(p interno.rede_posts, p_nivel integer default 0) returns boolean
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare a rede_fed_atores; pai rede_posts; v_pub text;
begin
  if p.id is null or p.autor is null or p_nivel > 8 then return false; end if;
  select * into a from rede_fed_atores where perfil = p.autor;
  if not found or not a.ligado or a.ligado_em is null or p.criado_em < a.ligado_em then return false; end if;
  if interno.rede_fed_impedimento(p.autor) is not null then return false; end if;
  if (select rede_handle from perfis where id = p.autor) is distinct from a.handle then return false; end if;
  if p.tipo = 'aviso' or p.nucleo is not null or p.repost_de is not null then return false; end if;
  if interno.rede_fed_total() and coalesce(a.consentimento_versao, 0) >= 2 then
    if p.oculto or p.retido or p.apagado_em is not null then return false; end if;
    if p.comunidade is not null and p.comunidade like 'fechado-%' then return false; end if;
    -- A escolha da pessoa (o mesmo cálculo de interno.rede2_publico antes do rebaixamento): só "internet" sai.
    if coalesce(p.publico, case p.alcance when 'seguidores' then 'seguidores' when 'equipe' then 'equipe' else 'internet' end) <> 'internet' then
      return false;
    end if;
    v_pub := interno.rede2_publico(p);
    if v_pub not in ('internet', 'membros') then return false; end if;
    if v_pub = 'internet' and not interno.rede_ve(p, null) then return false; end if;
    if p.comunidade is not null and not interno.rede_fed_comunidade_ok(p.comunidade) then return false; end if;
  else
    if coalesce(p.publico, 'internet') <> 'internet' then return false; end if;
    if interno.rede2_publico(p) <> 'internet' or not interno.rede_ve(p, null) then return false; end if;
  end if;
  if p.resposta_a is not null then
    select * into pai from rede_posts where id = p.resposta_a;
    if not found or not interno.rede_fed_federavel(pai, p_nivel + 1) then return false; end if;
  end if;
  return true;
end $$;

/**
 * Quem de fora (já conhecido, com caixa, de instância não bloqueada) este post daqui menciona: @nome@servidor no título, no texto
 * ou no corpo, mais o autor da nota de fora que ele responde (resposta_a_remota). Post nulo: ninguém.
 */
create or replace function interno.rede_fed_mencionados(p interno.rede_posts) returns setof interno.rede_fed_remotos
language sql stable security definer set search_path = interno, pg_temp as $$
  select r.* from rede_fed_remotos r
  where p.id is not null and r.inbox is not null and not interno.rede_fed_bloqueado(r.ator)
    and (lower(r.handle) in (select lower(m[1] || '@' || m[2]) from regexp_matches(coalesce(p.titulo, '') || ' ' || coalesce(p.texto, '') || ' ' || coalesce(p.corpo, ''),
                               '@([A-Za-z0-9_.-]{1,100})@([A-Za-z0-9.-]{1,200}\.[A-Za-z]{2,})', 'g') m)
         or r.ator = (select c.ator from rede_fed_recebidos c where c.id = p.resposta_a_remota))
$$;

/**
 * O post como sai para o Fediverso. Além do de sempre: a mídia (id, tipo, texto alternativo, tamanho e blurhash; o caminho do
 * arquivo NÃO sai: o servidor pede pela ação "midia"), as menções a gente de fora já conhecida (@nome@servidor no texto, mais o
 * autor da nota respondida), a visibilidade (sempre pública: D5), a nota de fora respondida e a raiz da conversa.
 */
create or replace function interno.rede_fed_post_json(p interno.rede_posts) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', p.id, 'tipo', p.tipo, 'titulo', p.titulo, 'texto', p.texto, 'corpo', p.corpo, 'aviso', p.aviso,
    'criado_em', p.criado_em, 'editado_em', p.editado_em, 'resposta_a', p.resposta_a, 'comunidade', p.comunidade,
    'handle', (select handle from rede_fed_atores where perfil = p.autor),
    'raiz', coalesce(p.root_id, p.id),
    'visibilidade', 'publico',
    'resposta_a_remota', p.resposta_a_remota,
    'midia', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'tipo', m.tipo, 'alt', m.alt, 'largura', m.largura, 'altura', m.altura,
                                                           'blurhash', m.blurhash, 'ordem', m.ordem) order by m.ordem), '[]'::jsonb)
              from rede_midia m where m.post = p.id),
    'mencoes', (select coalesce(jsonb_agg(jsonb_build_object('handle', r.handle, 'ator', r.ator, 'inbox', r.inbox) order by r.handle), '[]'::jsonb)
                from interno.rede_fed_mencionados(p) r))
$$;

/**
 * Entrega um Create, Update ou Delete de um post daqui também a quem ele menciona lá fora e ao autor da nota de fora que ele
 * responde (p_antes: a versão anterior do post, para que quem saiu das menções numa edição também receba a mudança). Vai para a
 * caixa compartilhada (ou a própria) de cada um; não repete o destino que os seguidores já recebem (rede_fed_espalhar), nem o que
 * já está na fila para o mesmo post e tipo; nunca para instância bloqueada, para quem a pessoa bloqueou ou para quem a bloqueou lá
 * fora. Só no modo total. Devolve quantas entregas pôs na fila.
 */
-- Sem valor padrão no p_antes: no Postgres do Supabase, parâmetro do tipo linha com valor padrão impede acrescentar coluna com valor
-- padrão em rede_posts. Se a versão antiga (com o valor padrão) estiver no banco, sai antes, porque o "create or replace" não tira valor padrão.
do $$
begin
  if exists (select 1 from pg_proc where oid = to_regprocedure('interno.rede_fed_entregar_mencionados(interno.rede_posts, text, uuid, interno.rede_posts)') and pronargdefaults > 0) then
    drop function interno.rede_fed_entregar_mencionados(interno.rede_posts, text, uuid, interno.rede_posts);
  end if;
end $$;
create or replace function interno.rede_fed_entregar_mencionados(p interno.rede_posts, p_tipo text, p_perfil uuid, p_antes interno.rede_posts) returns integer
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_n integer;
begin
  if p.id is null or p_perfil is null or not interno.rede_fed_total() then return 0; end if;
  insert into rede_fed_fila (perfil, tipo, objeto, destino)
  select distinct p_perfil, p_tipo, p.id::text, d.destino
  from (select r.ator, coalesce(r.inbox_compartilhada, r.inbox) as destino from interno.rede_fed_mencionados(p) r
        union
        select r.ator, coalesce(r.inbox_compartilhada, r.inbox) from interno.rede_fed_mencionados(p_antes) r where p_antes.id is not null) d
  where d.destino is not null
    and not interno.rede_fed_bloqueado(d.destino)
    and not exists (select 1 from fediverso_filtros f where f.usuario = p_perfil and f.ator = d.ator and f.tipo = 'bloqueio')
    and not exists (select 1 from fediverso_bloqueios_recebidos b where b.perfil = p_perfil and b.ator = d.ator)
    and not exists (select 1 from rede_fed_seguidores s where s.perfil = p_perfil and coalesce(s.inbox_compartilhada, s.inbox) = d.destino)
    and not exists (select 1 from rede_fed_fila q where q.feito_em is null and q.tipo = p_tipo and q.objeto = p.id::text and q.destino = d.destino);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

/**
 * Um post mudou: sai (Create), muda (Update) ou é retirado (Delete) do Fediverso, conforme pode ou não sair agora. Com
 * "fediverso-grupos", o post de uma comunidade também vai para quem segue a comunidade (Group) de fora, como Announce do grupo.
 */
create or replace function interno.rede_fed_post_mudou() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_p rede_posts; v_antes rede_posts; v_fed boolean := false; v_env rede_fed_enviados; v_atividade text;
begin
  -- O caminho rápido: ninguém ligou a federação e nada foi enviado. Custa uma consulta a uma tabela quase sempre vazia.
  if not exists (select 1 from rede_fed_atores) then return null; end if;
  if tg_op = 'DELETE' then v_p := old; else v_p := new; v_fed := interno.rede_fed_federavel(new); end if;
  select * into v_env from rede_fed_enviados where post = v_p.id;
  if v_fed and (v_env.post is null or v_env.apagado_em is not null) then
    insert into rede_fed_enviados (post, perfil) values (v_p.id, v_p.autor) on conflict (post) do update set apagado_em = null, enviado_em = now();
    perform interno.rede_fed_espalhar(v_p.autor, 'create', v_p.id::text);
    v_atividade := 'create';
  elsif v_fed and tg_op = 'UPDATE' and (new.texto, coalesce(new.titulo, ''), coalesce(new.corpo, ''), new.aviso) is distinct from (old.texto, coalesce(old.titulo, ''), coalesce(old.corpo, ''), old.aviso) then
    perform interno.rede_fed_espalhar(v_p.autor, 'update', v_p.id::text);
    v_atividade := 'update';
  elsif not v_fed and v_env.post is not null and v_env.apagado_em is null then
    update rede_fed_enviados set apagado_em = now() where post = v_p.id;
    perform interno.rede_fed_espalhar(v_env.perfil, 'delete', v_p.id::text);
    v_atividade := 'delete';
  end if;
  -- Modo total: quem foi mencionado lá fora (e o autor da nota respondida) recebe também, mesmo sem seguir a pessoa.
  if v_atividade is not null then
    if tg_op = 'UPDATE' then v_antes := old; end if;
    perform interno.rede_fed_entregar_mencionados(v_p, v_atividade, case when v_atividade = 'delete' then v_env.perfil else v_p.autor end, v_antes);
  end if;
  if v_atividade is not null and v_p.comunidade is not null and v_p.resposta_a is null
     and (v_atividade = 'delete' or interno.rede_fed_grupo_ok(v_p.comunidade)) then
    insert into rede_fed_fila (perfil, comunidade, tipo, objeto, destino, extra)
    select distinct null::uuid, s.comunidade, 'group-announce', v_p.id::text, coalesce(s.inbox_compartilhada, s.inbox), jsonb_build_object('atividade', v_atividade)
    from fediverso_grupo_seguidores s where s.comunidade = v_p.comunidade and not interno.rede_fed_bloqueado(s.inbox);
  end if;
  return null;
end $$;

/** Liga a federação de uma pessoa com o consentimento da versão em vigor (o mesmo que rede_fed_ligar faz). Devolve se ligou. */
create or replace function interno.rede_fed_ligar_perfil(p_perfil uuid) returns boolean language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_handle text;
begin
  if interno.rede_fed_impedimento(p_perfil) is not null then return false; end if;
  v_handle := (select rede_handle from perfis where id = p_perfil);
  if exists (select 1 from rede_fed_atores where handle = v_handle and ligado and perfil <> p_perfil) then return false; end if;
  insert into rede_fed_atores (perfil, handle, ligado, consentimento_versao, ligado_em, desligado_em)
  values (p_perfil, v_handle, true, interno.rede_fed_versao(), now(), null)
  on conflict (perfil) do update set
    ligado_em = case when rede_fed_atores.ligado and rede_fed_atores.handle = excluded.handle then rede_fed_atores.ligado_em else now() end,
    chave_publica = case when rede_fed_atores.handle = excluded.handle then rede_fed_atores.chave_publica end,
    chave_privada = case when rede_fed_atores.handle = excluded.handle then rede_fed_atores.chave_privada end,
    handle = excluded.handle, ligado = true, consentimento_versao = excluded.consentimento_versao, desligado_em = null;
  return true;
end $$;

/**
 * Desliga a federação de uma pessoa (o de sempre: Delete de cada post que saiu, Reject para quem seguia, Undo do que ela seguia) e,
 * agora, desfaz também o que ela curtiu e impulsionou lá fora (Undo) e apaga esses registros.
 */
create or replace function interno.rede_fed_desligar(p_perfil uuid) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare e record; v_p rede_posts;
begin
  if not exists (select 1 from rede_fed_atores where perfil = p_perfil and ligado) then return; end if;
  for e in select post from rede_fed_enviados where perfil = p_perfil and apagado_em is null loop
    perform interno.rede_fed_espalhar(p_perfil, 'delete', e.post::text);
    -- Quem foi mencionado lá fora (modo total) recebeu o Create; recebe também a retirada.
    select * into v_p from rede_posts where id = e.post;
    if found then perform interno.rede_fed_entregar_mencionados(v_p, 'delete', p_perfil, null); end if;
  end loop;
  update rede_fed_enviados set apagado_em = now() where perfil = p_perfil and apagado_em is null;
  insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
  select p_perfil, 'reject', s.ator, s.inbox, jsonb_build_object('pedido', s.pedido) from rede_fed_seguidores s
  where s.perfil = p_perfil and s.pedido <> '' and not interno.rede_fed_bloqueado(s.inbox);
  insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
  select p_perfil, 'undo-follow', s.ator, coalesce(r.inbox, s.ator), jsonb_build_object('pedido', s.pedido)
  from rede_fed_seguindo s join rede_fed_remotos r on r.ator = s.ator
  where s.perfil = p_perfil and r.inbox is not null and not interno.rede_fed_bloqueado(r.inbox);
  insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
  select p_perfil, 'undo-' || i.tipo, i.objeto_remoto, r.inbox, jsonb_build_object('atividade', i.atividade_id, 'ator_objeto', i.ator)
  from fediverso_interacoes i join rede_fed_remotos r on r.ator = i.ator
  where i.direcao = 'saida' and i.perfil = p_perfil and r.inbox is not null and not interno.rede_fed_bloqueado(r.inbox);
  delete from fediverso_interacoes where direcao = 'saida' and perfil = p_perfil;
  delete from rede_fed_seguidores where perfil = p_perfil;
  delete from rede_fed_seguindo where perfil = p_perfil;
  update rede_fed_atores set ligado = false, desligado_em = now() where perfil = p_perfil;
end $$;

/**
 * O item "meus posts públicos também vão para o Fediverso" do consentimento de entrada (D2). Marcado, com o modo total ligado, liga
 * a federação; desmarcado, desliga (retira o que saiu). Revogar o consentimento da rede já desliga (interno.rede_fed_consentimento_mudou).
 */
create or replace function interno.rede_fed_consentimento_fediverso() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if new.revogado_em is not null then return null; end if;
  -- Só o item marcado na versão 2 (com a flag ligada) liga: quem marcou na versão 1 é pedido de novo (cabeçalho, item 2).
  if new.fediverso and coalesce(new.fediverso_versao, 1) >= 2 and interno.rede_fed_total() then
    if not exists (select 1 from rede_fed_atores where perfil = new.usuario and ligado and consentimento_versao >= interno.rede_fed_versao()) then
      perform interno.rede_fed_ligar_perfil(new.usuario);
    end if;
  elsif not new.fediverso and tg_op = 'UPDATE' and old.fediverso then
    perform interno.rede_fed_desligar(new.usuario);
  end if;
  return null;
end $$;

drop trigger if exists fediverso_consentimento on interno.rede_consentimentos;
create trigger fediverso_consentimento after insert or update of fediverso, fediverso_versao on interno.rede_consentimentos
  for each row execute function interno.rede_fed_consentimento_fediverso();

/**
 * Esta pessoa pode ver esta nota de fora? Precisa de conta; nunca de instância bloqueada, de quem ela bloqueou, nem de quem a
 * bloqueou lá fora. Só-seguidores: só quem segue o autor (com o pedido aceito). Silenciar esconde da linha, não do fio.
 */
create or replace function interno.rede_fed_nota_ve(c interno.rede_fed_recebidos, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select c.id is not null and p_quem is not null
    and not interno.rede_fed_bloqueado(c.ator)
    and not exists (select 1 from fediverso_filtros f where f.usuario = p_quem and f.ator = c.ator and f.tipo = 'bloqueio')
    and not exists (select 1 from fediverso_bloqueios_recebidos b where b.perfil = p_quem and b.ator = c.ator)
    and (c.visibilidade <> 'seguidores' or exists (select 1 from rede_fed_seguindo s where s.perfil = p_quem and s.ator = c.ator and s.aceito))
$$;

/**
 * A nota de fora no MESMO formato de cartão que interno.rede_post_v2 (as mesmas chaves, com os valores neutros onde não se aplica),
 * mais: origem 'fediverso', ator_remoto, handle_remoto, nome_remoto, avatar, servidor, url (o original), html (limpo), sensivel,
 * visibilidade, curti, impulsionei, post_local (o post daqui a que a conversa pertence) e impulsionado_por (quando veio por impulso).
 */
create or replace function interno.rede_fed_cartao(c interno.rede_fed_recebidos, p_quem uuid, p_impulso jsonb default null) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', c.id, 'origem', 'fediverso', 'tipo', 'post', 'titulo', null, 'texto', c.texto, 'html', c.html,
    'corpo', null, 'longo', false, 'comunidade', null, 'flair', null,
    'publico', case when c.visibilidade = 'seguidores' then 'seguidores' else 'internet' end, 'visibilidade', c.visibilidade,
    'criado_em', coalesce(c.publicado, c.recebido_em), 'editado_em', c.editado_em,
    'fixado', false, 'travado', false, 'aceita', null, 'verificada', false,
    'resposta_a', c.em_resposta_a, 'raiz', coalesce(c.contexto, c.id), 'nivel', 0,
    'aviso', c.aviso, 'sensivel', c.sensivel or c.aviso <> '', 'cita', null, 'chamado', null,
    'meu', false, 'retido', false, 'motivo', '', 'modero', false) || jsonb_build_object(
    'autor', jsonb_build_object('id', null, 'codinome', coalesce(nullif(r.nome, ''), r.handle, interno.rede_fed_dominio(c.ator)),
                                'handle', r.handle, 'perfil', false, 'equipe', false, 'remoto', true),
    'ator_remoto', c.ator, 'handle_remoto', r.handle, 'nome_remoto', r.nome, 'avatar', r.avatar,
    'servidor', interno.rede_fed_dominio(c.ator), 'url', coalesce(c.url, c.id),
    'respostas', (select count(*)::integer from rede_fed_recebidos x where x.em_resposta_a = c.id and interno.rede_fed_nota_ve(x, p_quem))
               + (select count(*)::integer from rede_posts l where l.resposta_a_remota = c.id and interno.rede_ve(l, p_quem)),
    'na_conversa', null, 'util', 0, 'util_eu', false, 'apoios', null,
    'curti', p_quem is not null and exists (select 1 from fediverso_interacoes i where i.direcao = 'saida' and i.tipo = 'like' and i.perfil = p_quem and i.objeto_remoto = c.id),
    'impulsionei', p_quem is not null and exists (select 1 from fediverso_interacoes i where i.direcao = 'saida' and i.tipo = 'announce' and i.perfil = p_quem and i.objeto_remoto = c.id),
    'apoiei', p_quem is not null and exists (select 1 from fediverso_interacoes i where i.direcao = 'saida' and i.tipo = 'like' and i.perfil = p_quem and i.objeto_remoto = c.id),
    'salvei', false, 'vou', null, 'vou_eu', false,
    'midia', c.midia, 'citado', null, 'post_local', c.post_local, 'impulsionado_por', p_impulso)
  from (select 1) u left join rede_fed_remotos r on r.ator = c.ator
$$;

-- ── 6. O que a pessoa chama (com a sessão dela) ────────────────────────────────────────────────────────────────────────

/**
 * Entrar na Alumia com o item destacado do Fediverso (D2): o mesmo rede_aderir de sempre, mais a escolha "meus posts públicos
 * também vão para o Fediverso" (marcada por padrão na tela, mas é a pessoa que decide). Com o modo total ligado, marcar liga a
 * federação (gatilho em rede_consentimentos); desmarcar desliga. Sem o modo total, a escolha só fica guardada, como versão 1: não liga
 * nada quando a flag ligar depois (a tela pede de novo: pedir_fediverso em rede_fed_situacao).
 */
create or replace function public.rede_aderir(p_maior boolean, p_versao integer, p_fediverso boolean) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_res jsonb;
begin
  v_res := public.rede_aderir(p_maior, p_versao);
  -- fediverso_versao: a versão do item respondido (1 sem a flag, 2 com ela), marcado ou não. Marcar de novo na versão 2 é aceite novo.
  update rede_consentimentos set fediverso = coalesce(p_fediverso, false), fediverso_versao = interno.rede_fed_versao()
  where usuario = v and revogado_em is null and versao = (select rede_consentimento from perfis where id = v)
    and (fediverso, fediverso_versao) is distinct from (coalesce(p_fediverso, false), interno.rede_fed_versao()::smallint);
  return v_res || jsonb_build_object('fediverso', public.rede_fed_situacao());
end $$;

/** A situação da federação para quem está na sessão (a de sempre, mais: modo total, descoberta e o item do consentimento). */
create or replace function public.rede_fed_situacao() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); a rede_fed_atores;
begin
  if v is null then return jsonb_build_object('logado', false, 'ligado', false, 'pode', false, 'motivo', 'entre_primeiro', 'versao', interno.rede_fed_versao(), 'total', interno.rede_fed_total()); end if;
  select * into a from rede_fed_atores where perfil = v;
  return jsonb_build_object(
    'logado', true,
    'handle', (select rede_handle from perfis where id = v),
    'motivo', interno.rede_fed_impedimento(v),
    'pode', interno.rede_fed_impedimento(v) is null,
    'ligado', coalesce(a.ligado, false),
    'desde', case when a.ligado then a.ligado_em end,
    'seguidores', (select count(*)::integer from rede_fed_seguidores where perfil = v),
    'seguindo', (select count(*)::integer from rede_fed_seguindo where perfil = v),
    'versao', interno.rede_fed_versao(),
    'total', interno.rede_fed_total(),
    'consentimento_versao', case when a.ligado then a.consentimento_versao end,
    'descobrivel', coalesce(a.ligado and a.descobrivel, false),
    -- A tela pede o item do Fediverso (de novo) para quem pode federar e ainda não aceitou a versão 2: inclusive quem marcou o
    -- item com a flag desligada (versão 1), que não é ligado sozinho, e quem está ligado só na versão 1. Quem já respondeu o item
    -- na versão 2 (marcado ou não) e quem desligou no perfil não são pedidos (decidiram; religam no perfil quando quiserem).
    'pedir_fediverso', interno.rede_fed_total() and interno.rede_fed_impedimento(v) is null
      and (a.perfil is null or (a.ligado and coalesce(a.consentimento_versao, 1) < 2))
      and not exists (select 1 from rede_consentimentos c where c.usuario = v and c.revogado_em is null and c.fediverso_versao >= 2));
end $$;

/** Aparecer (ou não) em diretórios e buscas de fora (discoverable/indexable no ator). Só com a federação ligada. */
create or replace function public.rede_fed_descoberta(p_sim boolean) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede_fed_ligar', 10, 60);
  update rede_fed_atores set descobrivel = coalesce(p_sim, false) where perfil = v and ligado;
  if not found then perform interno.erro('fediverso_desligado'); end if;
  return public.rede_fed_situacao();
end $$;

/**
 * Quem está pedindo, para as rotas do servidor que agem em nome da pessoa. Confere a sessão, a adesão à rede e o limite por
 * pessoa; devolve o perfil e o estado da federação. Ações: buscar, seguir, interagir, responder, remoto, denunciar.
 */
create or replace function public.rede_fed_eu(p_acao text) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); a rede_fed_atores;
begin
  perform interno.aberta('comunidade');
  if p_acao is null or p_acao not in ('buscar', 'seguir', 'interagir', 'responder', 'remoto', 'denunciar') then perform interno.erro('invalido:acao'); end if;
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('rede_fed_' || p_acao, case p_acao when 'buscar' then 30 when 'seguir' then 20 when 'interagir' then 120
                                                           when 'responder' then 30 when 'remoto' then 120 else 10 end, 60);
  select * into a from rede_fed_atores where perfil = v;
  return jsonb_build_object('perfil', v, 'handle', (select rede_handle from perfis where id = v), 'ligado', coalesce(a.ligado, false), 'total', interno.rede_fed_total());
end $$;

/**
 * A mediação bloqueia (ou desbloqueia) uma instância inteira: nada entra dela, nada sai para ela, e o que havia dela some (agora
 * também curtidas, impulsos, avisos, seguidores das comunidades e bloqueios dela). Domínio vazio e p_sim nulo: só a lista.
 */
create or replace function public.rede_fed_bloquear(p_dominio text, p_sim boolean, p_motivo text default '') returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_d text := lower(btrim(coalesce(p_dominio, '')));
begin
  if not (interno.media() or interno.cuida()) then perform interno.erro('sem_permissao'); end if;
  if v_d = '' and p_sim is null then
    return coalesce((select jsonb_agg(jsonb_build_object('dominio', dominio, 'motivo', motivo, 'desde', criado_em) order by dominio) from rede_fed_bloqueados), '[]'::jsonb);
  end if;
  if v_d !~ '^[a-z0-9.-]{3,253}$' or v_d !~ '\.' then perform interno.erro('invalido:dominio'); end if;
  if coalesce(p_sim, true) then
    insert into rede_fed_bloqueados (dominio, motivo, por) values (v_d, left(coalesce(p_motivo, ''), 300), v)
    on conflict (dominio) do update set motivo = excluded.motivo, por = excluded.por, criado_em = now();
    delete from rede_fed_seguidores where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_seguindo where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_recebidos where interno.rede_fed_bloqueado(ator);
    delete from rede_fed_remotos where interno.rede_fed_bloqueado(ator);
    delete from fediverso_interacoes where interno.rede_fed_bloqueado(ator) or interno.rede_fed_bloqueado(objeto_remoto);
    delete from fediverso_grupo_seguidores where interno.rede_fed_bloqueado(ator);
    delete from fediverso_bloqueios_recebidos where interno.rede_fed_bloqueado(ator);
    delete from avisos where ator_remoto is not null and interno.rede_fed_bloqueado(ator_remoto);
    update rede_fed_fila set feito_em = now(), erro = 'instancia_bloqueada' where feito_em is null and interno.rede_fed_bloqueado(destino);
  else
    delete from rede_fed_bloqueados where dominio = v_d;
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('dominio', dominio, 'motivo', motivo, 'desde', criado_em) order by dominio) from rede_fed_bloqueados), '[]'::jsonb);
end $$;

/**
 * A linha de fora para juntar à linha local (rede_linha) por data, sem aba à parte: as notas de primeiro nível de quem a pessoa
 * segue lá fora e os impulsos (Announce) que essas pessoas fizeram de notas de fora. No MESMO formato de cartão (rede_fed_cartao);
 * criado_em é a hora que ordena (no impulso, a hora do impulso; a da nota fica em publicado_em). Cursor = "<criado_em>|<chave>".
 * Nunca: instância bloqueada, quem a pessoa bloqueou ou silenciou, quem a bloqueou lá fora, palavra silenciada. Modo total
 * desligado: vazia.
 */
create or replace function public.rede_fed_linha_mista(p_cursor text default null, p_limite integer default 20) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_limite integer := least(greatest(coalesce(p_limite, 20), 1), 50);
  v_t timestamptz; v_k text;
  v_itens jsonb := '[]'::jsonb; v_n integer := 0; v_proximo text;
  v_linha record; v_nota rede_fed_recebidos; v_impulso jsonb;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  if not interno.rede_fed_total() then return jsonb_build_object('itens', '[]'::jsonb, 'proximo', null); end if;
  if nullif(p_cursor, '') is not null then
    if position('|' in p_cursor) = 0 then perform interno.erro('invalido:cursor'); end if;
    begin
      v_t := split_part(p_cursor, '|', 1)::timestamptz;
    exception when others then
      perform interno.erro('invalido:cursor');
    end;
    v_k := substr(p_cursor, position('|' in p_cursor) + 1);
  end if;
  for v_linha in
    select x.nota, x.quando, x.chave, x.quem from (
      select c.id as nota, coalesce(c.publicado, c.recebido_em) as quando, c.id as chave, null::text as quem
      from rede_fed_recebidos c
      where c.em_resposta_a is null and exists (select 1 from rede_fed_seguindo s where s.perfil = v and s.ator = c.ator and s.aceito)
      union all
      select c.id, i.criado_em, c.id || '#' || i.id::text, i.ator
      from fediverso_interacoes i join rede_fed_recebidos c on c.id = i.objeto_remoto
      where i.direcao = 'entrada' and i.tipo = 'announce' and c.visibilidade <> 'seguidores'
        and exists (select 1 from rede_fed_seguindo s where s.perfil = v and s.ator = i.ator and s.aceito)
    ) x join rede_fed_recebidos c on c.id = x.nota
    where (v_t is null or (x.quando, x.chave) < (v_t, v_k))
      and interno.rede_fed_nota_ve(c, v)
      and not exists (select 1 from fediverso_filtros f where f.usuario = v and (f.ator = c.ator or f.ator = x.quem))
      and (x.quem is null or (not interno.rede_fed_bloqueado(x.quem) and not exists (select 1 from fediverso_bloqueios_recebidos b where b.perfil = v and b.ator = x.quem)))
      and not exists (select 1 from rede_silenciados s where s.usuario = v and s.palavra is not null and (s.ate is null or s.ate > now())
                      and position(interno.normal(s.palavra) in interno.normal(c.texto || ' ' || c.aviso)) > 0)
    order by x.quando desc, x.chave desc
    limit v_limite + 1
  loop
    v_n := v_n + 1;
    if v_n > v_limite then exit; end if;
    select * into v_nota from rede_fed_recebidos where id = v_linha.nota;
    v_impulso := null;
    if v_linha.quem is not null then
      select jsonb_build_object('ator', v_linha.quem, 'handle', q.handle, 'nome', q.nome, 'avatar', q.avatar, 'em', v_linha.quando)
      into v_impulso from (select 1) u left join rede_fed_remotos q on q.ator = v_linha.quem;
    end if;
    v_itens := v_itens || jsonb_build_array(interno.rede_fed_cartao(v_nota, v, v_impulso)
      || jsonb_build_object('criado_em', v_linha.quando, 'publicado_em', coalesce(v_nota.publicado, v_nota.recebido_em), 'chave', v_linha.chave));
    v_proximo := v_linha.quando::text || '|' || v_linha.chave;
  end loop;
  return jsonb_build_object('itens', v_itens, 'proximo', case when v_n > v_limite then v_proximo end);
end $$;

/** O perfil de alguém de fora como a Alumia o conhece (só o que é público e já foi buscado) e as últimas notas dele que a pessoa pode ver. */
create or replace function public.rede_fed_perfil_remoto(p_ator text) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_r rede_fed_remotos; v_s rede_fed_seguindo;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede_fed_remoto', 120, 60);
  select * into v_r from rede_fed_remotos where ator = left(btrim(coalesce(p_ator, '')), 500);
  if not found or interno.rede_fed_bloqueado(v_r.ator) or exists (select 1 from fediverso_bloqueios_recebidos b where b.perfil = v and b.ator = v_r.ator) then
    perform interno.erro('nao_encontrado');
  end if;
  select * into v_s from rede_fed_seguindo where perfil = v and ator = v_r.ator;
  return jsonb_build_object('ator', v_r.ator, 'handle', v_r.handle, 'nome', v_r.nome, 'resumo', v_r.resumo, 'url', v_r.url, 'avatar', v_r.avatar,
    'tipo', v_r.tipo, 'servidor', interno.rede_fed_dominio(v_r.ator),
    'seguindo', case when v_s.ator is null then 'nao' when v_s.aceito then 'sim' else 'pedido' end,
    'segue_voce', exists (select 1 from rede_fed_seguidores x where x.perfil = v and x.ator = v_r.ator),
    'bloqueado', exists (select 1 from fediverso_filtros f where f.usuario = v and f.ator = v_r.ator and f.tipo = 'bloqueio'),
    'silenciado', exists (select 1 from fediverso_filtros f where f.usuario = v and f.ator = v_r.ator and f.tipo = 'silencio'),
    'posts', coalesce((select jsonb_agg(interno.rede_fed_cartao(c, v) order by coalesce(c.publicado, c.recebido_em) desc)
                       from rede_fed_recebidos c where c.id in (
                         select y.id from rede_fed_recebidos y where y.ator = v_r.ator and interno.rede_fed_nota_ve(y, v)
                         order by coalesce(y.publicado, y.recebido_em) desc limit 20)), '[]'::jsonb));
end $$;

/**
 * O fio de uma nota de fora: a nota, o que vem acima (até 10 níveis: notas de fora guardadas ou o post daqui que começou a
 * conversa) e as respostas (de fora e daqui), cada uma pela regra de quem pode ver.
 */
create or replace function public.rede_fed_fio_remoto(p_id text) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_c rede_fed_recebidos; v_x rede_fed_recebidos; v_l rede_posts; v_acima jsonb := '[]'::jsonb; v_ref text; v_n integer := 0;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  select * into v_c from rede_fed_recebidos where id = left(coalesce(p_id, ''), 500);
  if not found or not interno.rede_fed_nota_ve(v_c, v) then perform interno.erro('nao_encontrado'); end if;
  v_ref := v_c.em_resposta_a;
  while v_ref is not null and v_n < 10 loop
    v_n := v_n + 1;
    select * into v_x from rede_fed_recebidos where id = v_ref;
    if found then
      if not interno.rede_fed_nota_ve(v_x, v) then exit; end if;
      v_acima := jsonb_build_array(interno.rede_fed_cartao(v_x, v)) || v_acima;
      v_ref := v_x.em_resposta_a;
    else
      select * into v_l from rede_posts where id = interno.rede_fed_post_local(v_ref);
      if found and interno.rede_ve(v_l, v) then v_acima := jsonb_build_array(interno.rede_post_v2(v_l, v)) || v_acima; end if;
      exit;
    end if;
  end loop;
  return jsonb_build_object('post', interno.rede_fed_cartao(v_c, v), 'acima', v_acima,
    'respostas', coalesce((select jsonb_agg(z.j order by z.q) from (
        select interno.rede_fed_cartao(c, v) as j, coalesce(c.publicado, c.recebido_em) as q
        from rede_fed_recebidos c where c.em_resposta_a = v_c.id and interno.rede_fed_nota_ve(c, v)
        union all
        select interno.rede_post_v2(p, v), p.criado_em
        from rede_posts p where p.resposta_a_remota = v_c.id and interno.rede_ve(p, v) and not interno.rede_silenciado(p, v)
        order by 2 limit 200) z), '[]'::jsonb));
end $$;

/**
 * As respostas de fora a um post daqui ("tudo no mesmo fio"): as notas de fora da conversa desse post (post_local, direta ou
 * indiretamente), no formato de cartão (rede_fed_cartao, com resposta_a para a tela encaixar no fio), da mais antiga para a mais
 * nova, cada uma pela regra de quem pode ver (interno.rede_fed_nota_ve: só-seguidores só para quem segue o autor). O post daqui
 * passa antes pela matriz (interno.rede_ve). Cursor = "<criado_em>|<id>"; total = quantas a pessoa pode ver. Sem o modo total: vazia.
 * rede_post_v2 e rede_fio não mudam (são da linha local): a tela chama esta junto e junta por data.
 */
create or replace function public.rede_fed_respostas_de(p_post uuid, p_cursor text default null, p_limite integer default 50) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); v_p rede_posts; v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 100);
  v_t timestamptz; v_k text; v_itens jsonb; v_n integer; v_total integer; v_prox text;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  select * into v_p from rede_posts where id = p_post;
  if not found or not interno.rede_ve(v_p, v) then perform interno.erro('nao_encontrado'); end if;
  if not interno.rede_fed_total() then return jsonb_build_object('itens', '[]'::jsonb, 'proximo', null, 'total', 0); end if;
  if nullif(p_cursor, '') is not null then
    if position('|' in p_cursor) = 0 then perform interno.erro('invalido:cursor'); end if;
    begin
      v_t := split_part(p_cursor, '|', 1)::timestamptz;
    exception when others then
      perform interno.erro('invalido:cursor');
    end;
    v_k := substr(p_cursor, position('|' in p_cursor) + 1);
  end if;
  select count(*)::integer into v_total from rede_fed_recebidos c where c.post_local = p_post and interno.rede_fed_nota_ve(c, v);
  with lista as (
    select c, coalesce(c.publicado, c.recebido_em) as q, c.id as k from rede_fed_recebidos c
    where c.post_local = p_post and interno.rede_fed_nota_ve(c, v)
      and (v_t is null or (coalesce(c.publicado, c.recebido_em), c.id) > (v_t, v_k))
    order by 2, 3 limit v_limite + 1
  ), numerada as (select l.*, row_number() over (order by l.q, l.k) as n from lista l)
  select coalesce(jsonb_agg(interno.rede_fed_cartao(x.c, v) order by x.n) filter (where x.n <= v_limite), '[]'::jsonb), count(*)::integer
  into v_itens, v_n from numerada x;
  if v_n > v_limite then
    select z.q::text || '|' || z.k into v_prox from (select coalesce(c.publicado, c.recebido_em) as q, c.id as k from rede_fed_recebidos c
      where c.post_local = p_post and interno.rede_fed_nota_ve(c, v) and (v_t is null or (coalesce(c.publicado, c.recebido_em), c.id) > (v_t, v_k))
      order by 1, 2 limit v_limite) z order by z.q desc, z.k desc limit 1;
  end if;
  return jsonb_build_object('itens', v_itens, 'proximo', v_prox, 'total', v_total);
end $$;

/**
 * Curtir (like) ou impulsionar (announce) uma nota de fora, ou desfazer (p_sim = false). Põe na fila a atividade para a caixa do
 * autor (e, no impulso, também para quem segue a pessoa). Precisa do modo total e da federação ligada (a atividade sai assinada).
 * Impulsionar só-seguidores não pode (como no Mastodon).
 */
create or replace function public.rede_fed_interagir(p_post_remoto text, p_tipo text, p_sim boolean default true) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_c rede_fed_recebidos; v_r rede_fed_remotos; v_i fediverso_interacoes; v_ativ text;
begin
  perform interno.aberta('comunidade');
  if p_tipo is null or p_tipo not in ('like', 'announce') then perform interno.erro('invalido:tipo'); end if;
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if not interno.rede_fed_total() or interno.rede_fed_impedimento(v) is not null or not exists (select 1 from rede_fed_atores where perfil = v and ligado) then
    perform interno.erro('fediverso_desligado');
  end if;
  perform interno.limite('rede_fed_interagir', 300, 60);
  select * into v_c from rede_fed_recebidos where id = left(coalesce(p_post_remoto, ''), 500);
  if not found or not interno.rede_fed_nota_ve(v_c, v) then perform interno.erro('nao_encontrado'); end if;
  if p_tipo = 'announce' and v_c.visibilidade = 'seguidores' then perform interno.erro('sem_permissao'); end if;
  select * into v_r from rede_fed_remotos where ator = v_c.ator;
  if v_r.inbox is null then perform interno.erro('nao_encontrado'); end if;
  if coalesce(p_sim, true) then
    v_ativ := gen_random_uuid()::text;
    insert into fediverso_interacoes (direcao, tipo, ator, perfil, objeto_remoto, atividade_id) values ('saida', p_tipo, v_c.ator, v, v_c.id, v_ativ)
    on conflict do nothing returning * into v_i;
  else
    delete from fediverso_interacoes where direcao = 'saida' and tipo = p_tipo and perfil = v and objeto_remoto = v_c.id returning * into v_i;
  end if;
  if v_i.id is not null then
    insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
    values (v, case when coalesce(p_sim, true) then p_tipo else 'undo-' || p_tipo end, v_c.id, v_r.inbox, jsonb_build_object('atividade', v_i.atividade_id, 'ator_objeto', v_c.ator));
    if p_tipo = 'announce' then
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select distinct v, case when coalesce(p_sim, true) then 'announce' else 'undo-announce' end, v_c.id, coalesce(s.inbox_compartilhada, s.inbox),
             jsonb_build_object('atividade', v_i.atividade_id, 'ator_objeto', v_c.ator)
      from rede_fed_seguidores s where s.perfil = v and not interno.rede_fed_bloqueado(s.inbox) and coalesce(s.inbox_compartilhada, s.inbox) <> v_r.inbox;
    end if;
  end if;
  return jsonb_build_object('ok', true,
    'curti', exists (select 1 from fediverso_interacoes i where i.direcao = 'saida' and i.tipo = 'like' and i.perfil = v and i.objeto_remoto = v_c.id),
    'impulsionei', exists (select 1 from fediverso_interacoes i where i.direcao = 'saida' and i.tipo = 'announce' and i.perfil = v and i.objeto_remoto = v_c.id));
end $$;

/**
 * Responder a uma nota de fora: cria o post daqui pelo rede_publicar de sempre (todas as regras: adesão, limite, dado pessoal),
 * guarda a nota respondida (resposta_a_remota, que sai como inReplyTo) e garante a entrega na caixa do autor da nota. Nota só para
 * seguidores não se responde daqui (a resposta sairia pública).
 */
create or replace function public.rede_fed_responder_remoto(p_post_remoto text, p_texto text, p_aviso text default '') returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_c rede_fed_recebidos; v_p rede_posts; v_res jsonb; v_id uuid; v_fed boolean;
begin
  perform interno.aberta('comunidade');
  if not interno.rede_fed_total() or interno.rede_fed_impedimento(v) is not null or not exists (select 1 from rede_fed_atores where perfil = v and ligado) then
    perform interno.erro('fediverso_desligado');
  end if;
  select * into v_c from rede_fed_recebidos where id = left(coalesce(p_post_remoto, ''), 500);
  if not found or not interno.rede_fed_nota_ve(v_c, v) then perform interno.erro('nao_encontrado'); end if;
  if v_c.visibilidade = 'seguidores' then perform interno.erro('sem_permissao'); end if;
  v_res := public.rede_publicar(jsonb_build_object('tipo', 'post', 'texto', p_texto, 'aviso', coalesce(p_aviso, '')));
  v_id := (v_res ->> 'id')::uuid;
  -- Responder a uma nota de fora é falar no Fediverso: o público escolhido é "internet" (rede_publicar só o aceita nas
  -- disciplinas, então ele é posto aqui, depois). Com isso o gatilho manda o Create aos seguidores e ao autor da nota
  -- (interno.rede_fed_entregar_mencionados); o Update e o Delete depois seguem o mesmo caminho.
  update rede_posts set resposta_a_remota = v_c.id, publico = 'internet' where id = v_id returning * into v_p;
  v_fed := exists (select 1 from rede_fed_enviados e where e.post = v_id and e.apagado_em is null);
  if v_fed then perform interno.rede_fed_entregar_mencionados(v_p, 'create', v, null); end if;
  return v_res || jsonb_build_object('resposta_a_remota', v_c.id, 'federado', v_fed);
end $$;

/**
 * Denunciar uma nota ou um ator de fora. Fica na mediação daqui (fediverso_denuncias, saída). Com p_encaminhar (e o modo total), a Flag vai para a
 * instância de lá, assinada pela instância daqui: leva os alvos e o comentário, nunca quem denunciou (LGPD art. 6º, III).
 */
create or replace function public.rede_fed_denunciar_remoto(p_alvo text, p_categoria text, p_texto text default '', p_encaminhar boolean default false) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); v_c rede_fed_recebidos; v_r rede_fed_remotos; v_alvo text := left(btrim(coalesce(p_alvo, '')), 500);
  v_ator text; v_alvos jsonb; v_d fediverso_denuncias; v_destino text; v_texto text := interno.txt(coalesce(p_texto, ''), 'texto', 0, 1000);
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if p_categoria is null or p_categoria not in ('menores', 'ameaca', 'exposicao', 'violencia', 'autolesao', 'odio', 'assedio', 'golpe', 'spam', 'outro') then perform interno.erro('invalido:categoria'); end if;
  select * into v_c from rede_fed_recebidos where id = v_alvo;
  if found then
    if not interno.rede_fed_nota_ve(v_c, v) then perform interno.erro('nao_encontrado'); end if;
    v_ator := v_c.ator; v_alvos := jsonb_build_array(v_c.ator, v_c.id);
  else
    select * into v_r from rede_fed_remotos where ator = v_alvo;
    if not found then perform interno.erro('nao_encontrado'); end if;
    v_ator := v_r.ator; v_alvos := jsonb_build_array(v_r.ator);
  end if;
  if interno.rede_fed_bloqueado(v_ator) then perform interno.erro('instancia_bloqueada'); end if;
  select * into v_d from fediverso_denuncias where direcao = 'saida' and quem = v and alvos = v_alvos and situacao in ('aberta', 'em_analise') limit 1;
  if found then return jsonb_build_object('protocolo', v_d.protocolo, 'encaminhada', v_d.encaminhar, 'ja', true); end if;
  perform interno.rede2_limite('denunciar');
  insert into fediverso_denuncias (direcao, dominio, ator, alvos, categoria, conteudo, quem, encaminhar)
  values ('saida', interno.rede_fed_dominio(v_ator), v_ator, v_alvos, p_categoria, v_texto, v, coalesce(p_encaminhar, false) and interno.rede_fed_total())
  returning * into v_d;
  if v_d.encaminhar then
    select coalesce(q.inbox_compartilhada, q.inbox) into v_destino from rede_fed_remotos q where q.ator = v_ator;
    if v_destino is not null then
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      values (null, 'flag', v_ator, v_destino, jsonb_build_object('alvos', v_alvos, 'conteudo', v_texto, 'denuncia', v_d.protocolo));
    end if;
  end if;
  if interno.rede2_prioridade(p_categoria) = 1 then
    insert into avisos (para, texto)
    select distinct p.usuario, left('Denúncia prioritária ' || v_d.protocolo || ' sobre conteúdo de outro servidor do Fediverso (' || p_categoria || '). Abra a mediação de instâncias.', 500)
    from papeis p where p.papel in ('coordenacao', 'vice', 'mediacao') and p.usuario <> v;
  end if;
  return jsonb_build_object('protocolo', v_d.protocolo, 'encaminhada', v_d.encaminhar and v_destino is not null, 'ja', false);
end $$;

/**
 * Bloquear (ou desbloquear) alguém de fora: some da linha, dos avisos e do fio; deixa de seguir e de ser seguido; com a federação
 * ligada, sai um Block (e um Undo dele ao desbloquear).
 */
create or replace function public.rede_fed_bloquear_pessoa(p_ator text, p_sim boolean default true) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); v_ator text := left(btrim(coalesce(p_ator, '')), 500); v_f fediverso_filtros; v_inbox text; v_ativ text;
  v_ligado boolean := interno.rede_fed_total() and exists (select 1 from rede_fed_atores where perfil = v and ligado);
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede_fed_filtro', 60, 60);
  if v_ator !~ '^https://[^\s]+$' then perform interno.erro('invalido:ator'); end if;
  select inbox into v_inbox from rede_fed_remotos where ator = v_ator;
  select * into v_f from fediverso_filtros where usuario = v and ator = v_ator;
  if coalesce(p_sim, true) then
    if v_f.tipo is distinct from 'bloqueio' then
      v_ativ := case when v_ligado and v_inbox is not null and not interno.rede_fed_bloqueado(v_inbox) then gen_random_uuid()::text end;
      insert into fediverso_filtros (usuario, ator, tipo, atividade) values (v, v_ator, 'bloqueio', v_ativ)
      on conflict (usuario, ator) do update set tipo = 'bloqueio', atividade = excluded.atividade, criado_em = now();
      if v_ativ is not null then
        insert into rede_fed_fila (perfil, tipo, objeto, destino, extra) values (v, 'block', v_ator, v_inbox, jsonb_build_object('atividade', v_ativ));
      end if;
    end if;
    delete from avisos where para = v and ator_remoto = v_ator;
    delete from rede_fed_seguidores where perfil = v and ator = v_ator;
    if v_ligado and v_inbox is not null then
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select v, 'undo-follow', s.ator, v_inbox, jsonb_build_object('pedido', s.pedido) from rede_fed_seguindo s where s.perfil = v and s.ator = v_ator;
    end if;
    delete from rede_fed_seguindo where perfil = v and ator = v_ator;
  elsif v_f.tipo = 'bloqueio' then
    delete from fediverso_filtros where usuario = v and ator = v_ator;
    if v_f.atividade is not null and v_ligado and v_inbox is not null then
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra) values (v, 'undo-block', v_ator, v_inbox, jsonb_build_object('atividade', v_f.atividade));
    end if;
  end if;
  return jsonb_build_object('ok', true, 'bloqueado', exists (select 1 from fediverso_filtros f where f.usuario = v and f.ator = v_ator and f.tipo = 'bloqueio'));
end $$;

/** Silenciar (ou não) alguém de fora: some da linha e dos avisos, só aqui (nada sai). Quem está bloqueado continua bloqueado. */
create or replace function public.rede_fed_silenciar_pessoa(p_ator text, p_sim boolean default true) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_ator text := left(btrim(coalesce(p_ator, '')), 500);
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede_fed_filtro', 60, 60);
  if v_ator !~ '^https://[^\s]+$' then perform interno.erro('invalido:ator'); end if;
  if coalesce(p_sim, true) then
    insert into fediverso_filtros (usuario, ator, tipo) values (v, v_ator, 'silencio') on conflict (usuario, ator) do nothing;
  else
    delete from fediverso_filtros where usuario = v and ator = v_ator and tipo = 'silencio';
  end if;
  return jsonb_build_object('ok', true, 'silenciado', exists (select 1 from fediverso_filtros f where f.usuario = v and f.ator = v_ator and f.tipo = 'silencio'));
end $$;

/** A mediação lê as denúncias com o Fediverso (as que chegaram de fora e as que saem daqui). Sem o nome de quem denunciou. */
create or replace function public.rede_fed_denuncias_listar(p_situacao text default 'aberta') returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not (interno.media() or interno.cuida()) then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'protocolo', d.protocolo, 'direcao', d.direcao, 'dominio', d.dominio, 'ator', d.ator,
      'alvos', d.alvos, 'categoria', d.categoria, 'conteudo', d.conteudo, 'encaminhar', d.encaminhar, 'situacao', d.situacao,
      'denuncias', to_jsonb(d.denuncias), 'criado_em', d.criado_em) order by d.criado_em desc)
    from (select * from fediverso_denuncias where p_situacao is null or situacao = p_situacao order by criado_em desc limit 200) d), '[]'::jsonb);
end $$;

/** A mediação decide uma denúncia com o Fediverso. */
create or replace function public.rede_fed_denuncia_decidir(p_id uuid, p_situacao text) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not (interno.media() or interno.cuida()) then perform interno.erro('sem_permissao'); end if;
  if p_situacao is null or p_situacao not in ('aberta', 'em_analise', 'resolvida', 'descartada') then perform interno.erro('invalido:situacao'); end if;
  update fediverso_denuncias set situacao = p_situacao where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  perform interno.registrar('rede_fed_denuncia', p_id::text, jsonb_build_object('situacao', p_situacao));
  return jsonb_build_object('ok', true);
end $$;

-- ── 7. O que o servidor do site chama (com o segredo da federação) ─────────────────────────────────────────────────────

/**
 * As ações do servidor do site, numa função só, todas atrás do segredo (interno.rede_fed_segredo). As de 2026-11-alumia continuam
 * iguais (ator, chaves, instancia, outbox, post, seguidores, seguidor, remoto, remoto_salvar, resposta_follow, ator_apagado,
 * recebido, recebido_apagado, seguir, fila_pegar, fila_feito, contagem, bloqueado), com estas mudanças e as novas (seção 3.1):
 *   ator {handle}               → também {avatar_url, capa_url, discoverable, trancado, total, consentimento_versao}
 *   post {id}                   → também {midia, mencoes, visibilidade, resposta_a_remota, raiz} (rede_fed_post_json)
 *   seguidor                    → no modo total, avisa a pessoa (fed_seguidor); recusa quem ela bloqueou
 *   remoto_salvar               → também {avatar, tipo}
 *   seguindo_publico {handle}   → {total}  (só o número de quem a pessoa segue lá fora)
 *   interacao {tipo: like|announce, ator, atividade_id, post_local | objeto_remoto, sim} → {ok, perfil_autor} (avisa o autor;
 *                  sim=false desfaz). post_local = endereço de um post daqui; objeto_remoto = nota de fora impulsionada
 *   ator: trancado é sempre false (perfil trancado não federa: rede_fed_impedimento); 'ligado' só para quem tem o consentimento
 *   nota_recebida {id, ator, url, html_limpo, texto, aviso, sensivel, publicado, em_resposta_a, contexto, visibilidade,
 *                  mencoes_locais, midia} → {guardado, motivo}
 *   denuncia_recebida {ator_instancia, alvos, conteudo} → {protocolo}
 *   bloqueio_recebido {ator, alvo_handle, sim} → {ok}
 *   fila_pegar {limite ≤ 200}   → pula domínio morto; cada item diz quem assina (pessoa, grupo ou instância)
 *   fila_feito {id, ok, definitivo, erro, status, dominio, espera} → 410 apaga o seguidor, 429 respeita a espera, circuito por domínio
 *   dominio_estado {dominio}    → {morto_ate, falhas}
 *   midia {id}                  → {caminho, tipo, alt} da mídia de um post que pode sair (para a rota pública da mídia)
 *   contagem_ativos             → {mes, semestre} (NodeInfo: activeMonth, activeHalfyear)
 *   comunidade {slug}, comunidade_chaves {slug, publica, privada}, comunidade_seguidores {slug},
 *   comunidade_seguidor {slug, ator, inbox, compartilhada, pedido, sim}, comunidade_outbox {slug, antes, limite} (Group)
 */
create or replace function public.rede_fed_servidor(p_segredo text, p_acao text, p jsonb default '{}'::jsonb) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  a rede_fed_atores;
  f perfis;
  x rede_posts;
  v_limite integer;
  v_antes timestamptz;
  v_res jsonb;
  v_n integer;
  v_t smallint;
  v_ator text := left(coalesce(p ->> 'ator', ''), 500);
  v_q rede_fed_fila;
  v_d fediverso_dominios;
  v_i fediverso_interacoes;
  v_g fediverso_grupos;
  v_com rede_comunidades;
  v_tipo text; v_sim boolean; v_id text; v_ref text; v_vis text; v_html text; v_midia jsonb; v_dom text; v_slug text; v_prot text; v_texto text;
  v_post uuid; v_resp_local uuid; v_post_local uuid; v_autor uuid; v_perfil uuid; v_uuid uuid;
  v_segue boolean; v_resp_nota boolean; v_novo boolean; v_conexao boolean;
  v_mencoes uuid[]; v_den uuid[];
  v_publicado timestamptz; v_status integer; v_espera integer;
begin
  perform interno.rede_fed_segredo(p_segredo);
  p := coalesce(p, '{}'::jsonb);
  if v_ator <> '' and v_ator !~ '^https://[^\s]+$' then perform interno.erro('invalido:ator'); end if;

  case p_acao
  when 'ator' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) order by ligado desc, desligado_em desc nulls first limit 1;
    if not found then return jsonb_build_object('estado', 'inexistente'); end if;
    select * into f from perfis where id = a.perfil;
    if a.ligado and interno.rede_fed_impedimento(a.perfil) is null then
      return jsonb_build_object('estado', 'ligado', 'perfil', a.perfil, 'handle', a.handle, 'nome', coalesce(nullif(f.rede_codinome, ''), a.handle),
        'bio', case when f.rede_codinome_ok then left(coalesce(f.rede_bio, ''), 500) else '' end, 'ligado_em', a.ligado_em,
        'chave_publica', a.chave_publica, 'chave_privada', a.chave_privada,
        -- Só o rosto e a capa da galeria (arquivos públicos do site). A imagem enviada pela pessoa só aparece para quem tem conta
        -- (rede_perfil_imagem): não sai para fora sem um consentimento próprio (LGPD art. 6º, III).
        'avatar_url', case when f.rede_avatar ~ '^a(0[1-9]|1[0-9]|2[0-4])$' then '/rede/avatares/' || f.rede_avatar || '.svg' end,
        'capa_url', case when f.rede_capa ~ '^c0[1-8]$' then '/rede/capas/' || f.rede_capa || '.svg' end,
        -- Perfil trancado não federa (rede_fed_impedimento, que o plano manda não mudar): aqui ele nunca chega, então trancado é
        -- sempre false e manuallyApprovesFollowers também. Abrir o trancado com aprovação manual é decisão à parte.
        'discoverable', a.descobrivel, 'trancado', false,
        'total', interno.rede_fed_total(), 'consentimento_versao', a.consentimento_versao);
    end if;
    -- Desligado com entregas ainda na fila (as retiradas): o ator continua com a chave, sem nada mais.
    if exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null) and a.chave_publica is not null then
      return jsonb_build_object('estado', 'saindo', 'perfil', a.perfil, 'handle', a.handle, 'chave_publica', a.chave_publica, 'chave_privada', a.chave_privada);
    end if;
    return jsonb_build_object('estado', 'desligado');

  when 'chaves' then
    if coalesce(p ->> 'publica', '') !~ '^-----BEGIN PUBLIC KEY-----' or char_length(coalesce(p ->> 'privada', '')) < 100 then perform interno.erro('invalido:chave'); end if;
    update rede_fed_atores set chave_publica = p ->> 'publica', chave_privada = p ->> 'privada'
    where perfil = (p ->> 'perfil')::uuid and chave_publica is null;
    select * into a from rede_fed_atores where perfil = (p ->> 'perfil')::uuid;
    return jsonb_build_object('chave_publica', a.chave_publica, 'chave_privada', a.chave_privada);

  when 'instancia' then
    if (p ->> 'publica') is not null then
      if (p ->> 'publica') !~ '^-----BEGIN PUBLIC KEY-----' or char_length(coalesce(p ->> 'privada', '')) < 100 then perform interno.erro('invalido:chave'); end if;
      insert into configuracoes (chave, valor) values ('fediverso_instancia', jsonb_build_object('publica', p ->> 'publica', 'privada', p ->> 'privada'))
      on conflict (chave) do nothing;
    end if;
    return coalesce((select valor from configuracoes where chave = 'fediverso_instancia'), '{}'::jsonb);

  when 'outbox' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found then return jsonb_build_object('total', 0, 'itens', '[]'::jsonb); end if;
    v_limite := least(greatest(coalesce((p ->> 'limite')::integer, 20), 1), 40);
    v_antes := nullif(p ->> 'antes', '')::timestamptz;
    select count(*)::integer into v_n from rede_fed_enviados e where e.perfil = a.perfil and e.apagado_em is null;
    select coalesce(jsonb_agg(interno.rede_fed_post_json(r) order by r.criado_em desc), '[]'::jsonb) into v_res
    from (select r.* from rede_fed_enviados e join rede_posts r on r.id = e.post
          where e.perfil = a.perfil and e.apagado_em is null and (v_antes is null or r.criado_em < v_antes) and interno.rede_fed_federavel(r)
          order by r.criado_em desc limit v_limite) r;
    return jsonb_build_object('total', v_n, 'itens', v_res);

  when 'post' then
    begin
      select * into x from rede_posts where id = (p ->> 'id')::uuid;
    exception when others then
      return 'null'::jsonb;
    end;
    if not found or not interno.rede_fed_federavel(x) then
      -- Já saiu e foi retirado: a federação responde 410 (Gone) em vez de 404.
      if exists (select 1 from rede_fed_enviados e where e.post::text = p ->> 'id' and e.apagado_em is not null) then return jsonb_build_object('apagado', true); end if;
      return 'null'::jsonb;
    end if;
    return interno.rede_fed_post_json(x);

  when 'midia' then
    begin
      v_uuid := (p ->> 'id')::uuid;
    exception when others then
      return 'null'::jsonb;
    end;
    select * into x from rede_posts where id = (select m.post from rede_midia m where m.id = v_uuid);
    if not found or not interno.rede_fed_federavel(x) then return 'null'::jsonb; end if;
    return (select jsonb_build_object('caminho', m.caminho, 'tipo', m.tipo, 'alt', m.alt, 'largura', m.largura, 'altura', m.altura) from rede_midia m where m.id = v_uuid);

  when 'seguidores' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found then return jsonb_build_object('total', 0); end if;
    return jsonb_build_object('total', (select count(*)::integer from rede_fed_seguidores where perfil = a.perfil));

  when 'seguindo_publico' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found then return jsonb_build_object('total', 0); end if;
    return jsonb_build_object('total', (select count(*)::integer from rede_fed_seguindo where perfil = a.perfil and aceito));

  when 'seguidor' then
    select * into a from rede_fed_atores where handle = lower(coalesce(p ->> 'handle', '')) and ligado;
    if not found or interno.rede_fed_impedimento(a.perfil) is not null then return jsonb_build_object('ok', false, 'motivo', 'desligado'); end if;
    if interno.rede_fed_bloqueado(v_ator) or interno.rede_fed_bloqueado(p ->> 'inbox') then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    if coalesce((p ->> 'sim')::boolean, true) then
      if exists (select 1 from fediverso_filtros ff where ff.usuario = a.perfil and ff.ator = v_ator and ff.tipo = 'bloqueio') then
        return jsonb_build_object('ok', false, 'motivo', 'bloqueado');
      end if;
      if coalesce(p ->> 'inbox', '') !~ '^https://[^\s]+$' or interno.rede_fed_dominio(p ->> 'inbox') <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:inbox'); end if;
      v_novo := null;
      insert into rede_fed_seguidores (perfil, ator, inbox, inbox_compartilhada, pedido)
      values (a.perfil, v_ator, p ->> 'inbox',
              case when coalesce(p ->> 'compartilhada', '') ~ '^https://[^\s]+$' and interno.rede_fed_dominio(p ->> 'compartilhada') = interno.rede_fed_dominio(v_ator) then p ->> 'compartilhada' end,
              left(coalesce(p ->> 'pedido', ''), 500))
      on conflict (perfil, ator) do update set inbox = excluded.inbox, inbox_compartilhada = excluded.inbox_compartilhada, pedido = excluded.pedido
      returning (xmax = 0) into v_novo;
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra) values (a.perfil, 'accept', v_ator, p ->> 'inbox', jsonb_build_object('pedido', left(coalesce(p ->> 'pedido', ''), 500)));
      delete from fediverso_bloqueios_recebidos where perfil = a.perfil and ator = v_ator;
      if coalesce(v_novo, false) and interno.rede_fed_total() then perform interno.rede_fed_avisar(a.perfil, 'fed_seguidor', null, v_ator, null); end if;
    else
      delete from rede_fed_seguidores where perfil = a.perfil and ator = v_ator;
      delete from avisos where para = a.perfil and tipo = 'fed_seguidor' and ator_remoto = v_ator;
    end if;
    return jsonb_build_object('ok', true, 'perfil', a.perfil);

  when 'remoto' then
    return coalesce((select to_jsonb(r) from rede_fed_remotos r where r.ator = v_ator or r.chave_id = left(coalesce(p ->> 'chave_id', ''), 600) limit 1), 'null'::jsonb);

  when 'remoto_salvar' then
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if interno.rede_fed_bloqueado(v_ator) then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    insert into rede_fed_remotos (ator, chave_id, chave_publica, inbox, inbox_compartilhada, handle, nome, resumo, url, avatar, tipo, buscado_em)
    values (v_ator, left(p ->> 'chave_id', 600), left(p ->> 'chave_publica', 4000),
            case when coalesce(p ->> 'inbox', '') ~ '^https://[^\s]+$' then left(p ->> 'inbox', 500) end,
            case when coalesce(p ->> 'compartilhada', '') ~ '^https://[^\s]+$' then left(p ->> 'compartilhada', 500) end,
            left(p ->> 'handle', 200), left(p ->> 'nome', 200), left(p ->> 'resumo', 1000),
            case when coalesce(p ->> 'url', '') ~ '^https://[^\s]+$' then left(p ->> 'url', 500) end,
            case when coalesce(p ->> 'avatar', '') ~ '^https://[^\s"''<>]+$' and char_length(p ->> 'avatar') <= 500 then p ->> 'avatar' end,
            case when coalesce(p ->> 'tipo', '') ~ '^[A-Za-z]{2,40}$' then p ->> 'tipo' end, now())
    on conflict (ator) do update set chave_id = excluded.chave_id, chave_publica = excluded.chave_publica, inbox = excluded.inbox,
      inbox_compartilhada = excluded.inbox_compartilhada, handle = excluded.handle, nome = excluded.nome, resumo = excluded.resumo,
      url = excluded.url, avatar = coalesce(excluded.avatar, case when p ? 'avatar' then null else rede_fed_remotos.avatar end),
      tipo = coalesce(excluded.tipo, rede_fed_remotos.tipo), buscado_em = now();
    return jsonb_build_object('ok', true);

  when 'resposta_follow' then
    if coalesce((p ->> 'aceito')::boolean, false) then
      update rede_fed_seguindo set aceito = true where ator = v_ator and (pedido = coalesce(p ->> 'pedido', '') or coalesce(p ->> 'pedido', '') = '');
    else
      delete from rede_fed_seguindo where ator = v_ator and (pedido = coalesce(p ->> 'pedido', '') or coalesce(p ->> 'pedido', '') = '');
    end if;
    get diagnostics v_n = row_count;
    return jsonb_build_object('ok', v_n > 0);

  when 'ator_apagado' then
    delete from rede_fed_seguidores where ator = v_ator;
    delete from rede_fed_seguindo where ator = v_ator;
    delete from rede_fed_recebidos where ator = v_ator;
    delete from rede_fed_remotos where ator = v_ator;
    delete from fediverso_interacoes where direcao = 'entrada' and ator = v_ator;
    delete from fediverso_grupo_seguidores where ator = v_ator;
    delete from fediverso_bloqueios_recebidos where ator = v_ator;
    delete from avisos where ator_remoto = v_ator;
    return jsonb_build_object('ok', true);

  when 'recebido' then
    if not exists (select 1 from rede_fed_seguindo s where s.ator = v_ator and s.aceito) or interno.rede_fed_bloqueado(v_ator) then
      return jsonb_build_object('guardado', false);
    end if;
    if coalesce(p ->> 'id', '') !~ '^https://[^\s]+$' or interno.rede_fed_dominio(p ->> 'id') <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:id'); end if;
    insert into rede_fed_recebidos (id, ator, url, texto, aviso, publicado)
    values (left(p ->> 'id', 500), v_ator, case when coalesce(p ->> 'url', '') ~ '^https://[^\s]+$' then left(p ->> 'url', 500) end,
            left(coalesce(p ->> 'texto', ''), 3000), left(coalesce(p ->> 'aviso', ''), 200),
            least(coalesce(nullif(p ->> 'publicado', '')::timestamptz, now()), now()))
    on conflict (id) do update set texto = excluded.texto, aviso = excluded.aviso;
    return jsonb_build_object('guardado', true);

  when 'nota_recebida' then
    v_id := left(coalesce(p ->> 'id', ''), 500);
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if interno.rede_fed_bloqueado(v_ator) then return jsonb_build_object('guardado', false, 'motivo', 'bloqueado'); end if;
    if v_id !~ '^https://[^\s]+$' or interno.rede_fed_dominio(v_id) <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:id'); end if;
    v_vis := coalesce(nullif(p ->> 'visibilidade', ''), 'publico');
    -- Direto ou limitado: nunca guardado (a Alumia não tem DM federada); quem mandou recebe 202 do mesmo jeito.
    if v_vis not in ('publico', 'nao_listado', 'seguidores') then return jsonb_build_object('guardado', false, 'motivo', 'direto'); end if;
    v_segue := exists (select 1 from rede_fed_seguindo s where s.ator = v_ator and s.aceito);
    v_ref := nullif(left(coalesce(p ->> 'em_resposta_a', ''), 500), '');
    v_resp_local := null; v_post_local := null; v_resp_nota := false; v_mencoes := '{}';
    if interno.rede_fed_total() then
      v_resp_local := interno.rede_fed_post_local(v_ref);
      v_post_local := v_resp_local;
      if v_resp_local is null and v_ref is not null then
        select true, rc.post_local into v_resp_nota, v_post_local from rede_fed_recebidos rc where rc.id = v_ref;
        v_resp_nota := coalesce(v_resp_nota, false);
      end if;
      select coalesce(array_agg(distinct ra.perfil), '{}') into v_mencoes
      from jsonb_array_elements_text(case when jsonb_typeof(p -> 'mencoes_locais') = 'array' then p -> 'mencoes_locais' else '[]'::jsonb end) with ordinality h (nome, o)
      join rede_fed_atores ra on ra.handle = lower(split_part(btrim(h.nome, ' @'), '@', 1)) and ra.ligado
      where h.o <= 50 and interno.rede_fed_impedimento(ra.perfil) is null
        and not exists (select 1 from fediverso_bloqueios_recebidos b where b.perfil = ra.perfil and b.ator = v_ator);
    end if;
    -- Só-seguidores: só se alguém daqui segue o autor (e só essa pessoa vê: interno.rede_fed_nota_ve).
    if v_vis = 'seguidores' and not v_segue then return jsonb_build_object('guardado', false, 'motivo', 'sem_seguidor'); end if;
    if not (v_segue or v_post_local is not null or v_resp_nota or cardinality(v_mencoes) > 0) then
      return jsonb_build_object('guardado', false, 'motivo', 'sem_ligacao');
    end if;
    v_html := left(p ->> 'html_limpo', 20000);
    if not interno.rede_fed_html_ok(v_html) then v_html := null; end if;
    v_midia := coalesce((select jsonb_agg(jsonb_build_object(
        'url', e ->> 'url', 'tipo', e ->> 'tipo', 'alt', left(coalesce(e ->> 'alt', ''), 1500),
        'largura', case when coalesce(e ->> 'largura', '') ~ '^[0-9]{1,5}$' then (e ->> 'largura')::integer end,
        'altura', case when coalesce(e ->> 'altura', '') ~ '^[0-9]{1,5}$' then (e ->> 'altura')::integer end,
        'blurhash', case when coalesce(e ->> 'blurhash', '') ~ '^[^\s"''<>\\]{6,100}$' then e ->> 'blurhash' end) order by o)
      from jsonb_array_elements(case when jsonb_typeof(p -> 'midia') = 'array' then p -> 'midia' else '[]'::jsonb end) with ordinality m (e, o)
      where o <= 4 and jsonb_typeof(e) = 'object' and coalesce(e ->> 'url', '') ~ '^https://[^\s"''<>\\]+$' and char_length(e ->> 'url') <= 500
        and coalesce(e ->> 'tipo', '') ~ '^(image|video|audio)/[a-z0-9.+-]{1,60}$'), '[]'::jsonb);
    begin
      v_publicado := least(coalesce(nullif(p ->> 'publicado', '')::timestamptz, now()), now());
    exception when others then
      v_publicado := now();
    end;
    v_novo := null;
    insert into rede_fed_recebidos (id, ator, url, texto, aviso, publicado, html, sensivel, visibilidade, em_resposta_a, contexto, midia, post_local)
    values (v_id, v_ator, case when coalesce(p ->> 'url', '') ~ '^https://[^\s]+$' then left(p ->> 'url', 500) end,
            left(coalesce(p ->> 'texto', ''), 3000), left(coalesce(p ->> 'aviso', ''), 200), v_publicado,
            v_html, coalesce(p ->> 'sensivel', '') = 'true', v_vis, v_ref,
            case when coalesce(p ->> 'contexto', '') ~ '^https://[^\s]+$' then left(p ->> 'contexto', 500) end, v_midia, v_post_local)
    on conflict (id) do update set texto = excluded.texto, aviso = excluded.aviso, html = excluded.html, sensivel = excluded.sensivel,
      midia = excluded.midia, editado_em = now()
    where rede_fed_recebidos.ator = excluded.ator
    returning (xmax = 0) into v_novo;
    if v_novo is null then return jsonb_build_object('guardado', false, 'motivo', 'outro_ator'); end if;
    insert into fediverso_mencoes (nota, perfil) select v_id, u from unnest(v_mencoes) u on conflict do nothing;
    if v_novo then
      if v_resp_local is not null then
        select autor into v_autor from rede_posts where id = v_resp_local;
        -- Só-seguidores: só avisa (e só entrega o endereço da nota) a quem pode vê-la, como nas menções (interno.rede_fed_nota_ve).
        if v_vis <> 'seguidores' or exists (select 1 from rede_fed_seguindo s where s.perfil = v_autor and s.ator = v_ator and s.aceito) then
          perform interno.rede_fed_avisar(v_autor, 'fed_resposta', v_resp_local, v_ator, v_id);
        end if;
      end if;
      perform interno.rede_fed_avisar(u, 'fed_mencao', null, v_ator, v_id) from unnest(v_mencoes) u
      where u is distinct from v_autor
        and (v_vis <> 'seguidores' or exists (select 1 from rede_fed_seguindo s where s.perfil = u and s.ator = v_ator and s.aceito));
    end if;
    return jsonb_build_object('guardado', true, 'novo', v_novo,
      'motivo', case when v_resp_local is not null then 'resposta' when cardinality(v_mencoes) > 0 then 'mencao' when v_post_local is not null or v_resp_nota then 'fio' else 'segue' end);

  when 'recebido_apagado' then
    delete from rede_fed_recebidos where id = left(coalesce(p ->> 'id', ''), 500) and ator = v_ator;
    delete from fediverso_interacoes where direcao = 'entrada' and objeto_remoto = left(coalesce(p ->> 'id', ''), 500);
    delete from avisos where objeto_remoto = left(coalesce(p ->> 'id', ''), 500) and ator_remoto = v_ator;
    return jsonb_build_object('ok', true);

  when 'interacao' then
    v_tipo := nullif(p ->> 'tipo', '');
    v_sim := coalesce(p ->> 'sim', 'true') <> 'false';
    if (v_sim or v_tipo is not null) and (v_tipo is null or v_tipo not in ('like', 'announce')) then perform interno.erro('invalido:tipo'); end if;
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if not interno.rede_fed_total() then return jsonb_build_object('ok', false, 'motivo', 'desligado'); end if;
    if interno.rede_fed_bloqueado(v_ator) then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    v_id := nullif(left(coalesce(p ->> 'atividade_id', ''), 500), '');
    -- objeto_remoto: a nota de fora impulsionada; post_local: o post daqui (aceito também para a nota de fora, por compatibilidade).
    v_ref := nullif(left(coalesce(nullif(p ->> 'objeto_remoto', ''), p ->> 'post_local', ''), 500), '');
    v_post := interno.rede_fed_post_local(v_ref);
    if v_post is not null then select autor into v_autor from rede_posts where id = v_post; end if;
    if v_sim then
      if v_post is not null then
        if exists (select 1 from fediverso_filtros ff where ff.usuario = v_autor and ff.ator = v_ator and ff.tipo = 'bloqueio') then
          return jsonb_build_object('ok', false, 'motivo', 'bloqueado');
        end if;
        v_i := null;
        insert into fediverso_interacoes (direcao, tipo, ator, post_local, atividade_id) values ('entrada', v_tipo, v_ator, v_post, v_id)
        on conflict do nothing returning * into v_i;
        if v_i.id is not null then
          perform interno.rede_fed_avisar(v_autor, case v_tipo when 'like' then 'fed_curtida' else 'fed_impulso' end, v_post, v_ator, null);
        end if;
        return jsonb_build_object('ok', true, 'perfil_autor', v_autor);
      elsif v_tipo = 'announce' and coalesce(v_ref, '') ~ '^https://[^\s]+$' and not interno.rede_fed_bloqueado(v_ref)
            and exists (select 1 from rede_fed_seguindo s where s.ator = v_ator and s.aceito) then
        -- Impulso de uma nota de fora por quem alguém daqui segue: entra na linha como impulso (rede_fed_linha_mista).
        insert into fediverso_interacoes (direcao, tipo, ator, objeto_remoto, atividade_id) values ('entrada', 'announce', v_ator, v_ref, v_id)
        on conflict do nothing;
        return jsonb_build_object('ok', true, 'perfil_autor', null);
      end if;
      return jsonb_build_object('ok', false, 'motivo', 'sem_ligacao');
    end if;
    -- Undo: pelo post, pela nota impulsionada ou pelo id da atividade desfeita.
    with apagadas as (
      delete from fediverso_interacoes fi
      where fi.direcao = 'entrada' and fi.ator = v_ator and (v_tipo is null or fi.tipo = v_tipo)
        and ((v_post is not null and fi.post_local = v_post) or (v_ref is not null and fi.objeto_remoto = v_ref) or (v_id is not null and fi.atividade_id = v_id))
      returning fi.post_local, fi.tipo
    )
    delete from avisos av using apagadas d
    where av.ator_remoto = v_ator and av.post = d.post_local and av.tipo = case d.tipo when 'like' then 'fed_curtida' else 'fed_impulso' end;
    return jsonb_build_object('ok', true, 'perfil_autor', v_autor);

  when 'denuncia_recebida' then
    -- Flag de fora: só no modo total (com a flag desligada nada novo entra; cabeçalho, item 7).
    if not interno.rede_fed_total() then return jsonb_build_object('protocolo', null, 'ok', false, 'motivo', 'desligado'); end if;
    v_ref := left(coalesce(nullif(p ->> 'ator_instancia', ''), v_ator), 500);
    if v_ref !~ '^https://[^\s]+$' then perform interno.erro('invalido:ator'); end if;
    if interno.rede_fed_bloqueado(v_ref) then return jsonb_build_object('protocolo', null, 'ok', false, 'motivo', 'bloqueado'); end if;
    v_dom := interno.rede_fed_dominio(v_ref);
    -- Freio por instância: até 30 Flags por hora.
    if (select count(*) from fediverso_denuncias fd where fd.direcao = 'entrada' and fd.dominio = v_dom and fd.criado_em > now() - interval '1 hour') >= 30 then
      return jsonb_build_object('protocolo', null, 'ok', false, 'motivo', 'muitos_pedidos');
    end if;
    v_res := coalesce((select jsonb_agg(left(e, 500) order by o) from jsonb_array_elements_text(case when jsonb_typeof(p -> 'alvos') = 'array' then p -> 'alvos' else '[]'::jsonb end) with ordinality z (e, o)
                       where o <= 20 and e ~ '^https://[^\s]+$'), '[]'::jsonb);
    v_texto := left('Denúncia recebida de outro servidor do Fediverso (' || v_dom || '): ' || left(coalesce(p ->> 'conteudo', ''), 1800), 2000);
    v_den := '{}';
    -- Cada post e cada perfil daqui apontado vira uma denúncia na fila da mediação (rede_denuncias), sem autor (veio de fora).
    for v_uuid in
      select distinct e.post from jsonb_array_elements_text(v_res) z (u) join rede_fed_enviados e on e.post = interno.rede_fed_uuid_local(z.u)
      join rede_posts rp on rp.id = e.post
    loop
      insert into rede_denuncias (alvo_tipo, alvo, categoria, prioridade, texto, quem) values ('post', v_uuid::text, 'outro', 3, v_texto, null) returning id into v_post;
      v_den := v_den || v_post;
    end loop;
    for v_uuid in
      select distinct ra.perfil from jsonb_array_elements_text(v_res) z (u) join rede_fed_atores ra on ra.handle = interno.rede_fed_handle_local(z.u)
      join perfis pf on pf.id = ra.perfil
    loop
      insert into rede_denuncias (alvo_tipo, alvo, categoria, prioridade, texto, quem) values ('perfil', v_uuid::text, 'outro', 3, v_texto, null) returning id into v_post;
      v_den := v_den || v_post;
    end loop;
    insert into fediverso_denuncias (direcao, dominio, ator, alvos, conteudo, denuncias)
    values ('entrada', v_dom, v_ref, v_res, left(coalesce(p ->> 'conteudo', ''), 2000), v_den)
    returning protocolo into v_prot;
    return jsonb_build_object('protocolo', v_prot, 'ok', true, 'locais', cardinality(v_den));

  when 'bloqueio_recebido' then
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if not interno.rede_fed_total() then return jsonb_build_object('ok', false, 'motivo', 'desligado'); end if;
    v_ref := coalesce(interno.rede_fed_handle_local(p ->> 'alvo_handle'), lower(split_part(btrim(coalesce(p ->> 'alvo_handle', ''), ' @'), '@', 1)));
    select ra.perfil into v_perfil from rede_fed_atores ra where ra.handle = v_ref order by ra.ligado desc limit 1;
    if v_perfil is null or not exists (select 1 from perfis where id = v_perfil) then return jsonb_build_object('ok', false, 'motivo', 'inexistente'); end if;
    if coalesce(p ->> 'sim', 'true') <> 'false' then
      insert into fediverso_bloqueios_recebidos (perfil, ator) values (v_perfil, v_ator) on conflict do nothing;
      delete from rede_fed_seguidores where perfil = v_perfil and ator = v_ator;
      delete from rede_fed_seguindo where perfil = v_perfil and ator = v_ator;
      delete from avisos where para = v_perfil and ator_remoto = v_ator;
    else
      delete from fediverso_bloqueios_recebidos where perfil = v_perfil and ator = v_ator;
    end if;
    return jsonb_build_object('ok', true);

  when 'seguir' then
    select * into a from rede_fed_atores where perfil = (p ->> 'perfil')::uuid and ligado;
    if not found then perform interno.erro('fediverso_desligado'); end if;
    if interno.rede_fed_bloqueado(v_ator) then perform interno.erro('instancia_bloqueada'); end if;
    if coalesce((p ->> 'sim')::boolean, true) then
      if not exists (select 1 from rede_fed_remotos r where r.ator = v_ator and r.inbox is not null) then perform interno.erro('nao_encontrado'); end if;
      if (select count(*) from rede_fed_seguindo where perfil = a.perfil) >= 2000 then perform interno.erro('muitos_pedidos'); end if;
      insert into rede_fed_seguindo (perfil, ator, pedido) values (a.perfil, v_ator, left(coalesce(p ->> 'pedido', ''), 500))
      on conflict (perfil, ator) do update set pedido = excluded.pedido, aceito = false;
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select a.perfil, 'follow', v_ator, r.inbox, jsonb_build_object('pedido', left(coalesce(p ->> 'pedido', ''), 500)) from rede_fed_remotos r where r.ator = v_ator;
    else
      insert into rede_fed_fila (perfil, tipo, objeto, destino, extra)
      select a.perfil, 'undo-follow', v_ator, r.inbox, jsonb_build_object('pedido', s.pedido)
      from rede_fed_seguindo s join rede_fed_remotos r on r.ator = s.ator where s.perfil = a.perfil and s.ator = v_ator and r.inbox is not null;
      delete from rede_fed_seguindo where perfil = a.perfil and ator = v_ator;
    end if;
    return jsonb_build_object('ok', true);

  when 'fila_pegar' then
    -- Até 200 por chamada no modo total; sem a flag, o teto de antes (100).
    v_limite := least(greatest(coalesce((p ->> 'limite')::integer, 20), 1), case when interno.rede_fed_total() then 200 else 100 end);
    if random() < 0.05 then perform interno.rede_fed_limpar(); end if;
    -- Domínio morto (circuito aberto): os itens dele esperam sem gastar tentativa.
    with escolhidos as (
      select q.id from rede_fed_fila q
      where q.feito_em is null and q.proxima <= now()
        and not (interno.rede_fed_total() and exists (select 1 from fediverso_dominios d where d.dominio = interno.rede_fed_dominio(q.destino) and d.morto_ate > now()))
      order by q.proxima, q.id limit v_limite for update skip locked
    ), reservados as (
      update rede_fed_fila q set proxima = now() + interval '3 minutes', tentativas = q.tentativas + 1 from escolhidos e where q.id = e.id returning q.*
    )
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'tipo', r.tipo, 'objeto', r.objeto, 'destino', r.destino, 'extra', r.extra,
      'tentativas', r.tentativas, 'handle', t.handle, 'comunidade', r.comunidade,
      'assinante', case when r.perfil is not null then 'pessoa' when r.comunidade is not null then 'grupo' else 'instancia' end,
      'chave_publica', coalesce(t.chave_publica, g.chave_publica), 'chave_privada', coalesce(t.chave_privada, g.chave_privada)) order by r.id), '[]'::jsonb)
    into v_res from reservados r left join rede_fed_atores t on t.perfil = r.perfil left join fediverso_grupos g on g.comunidade = r.comunidade
    where (r.perfil is not null and t.perfil is not null) or (r.perfil is null and r.comunidade is not null and g.comunidade is not null)
       or (r.perfil is null and r.comunidade is null);
    return v_res;

  when 'fila_feito' then
    select * into v_q from rede_fed_fila where id = (p ->> 'id')::bigint;
    if not found then return jsonb_build_object('ok', true); end if;
    v_t := v_q.tentativas;
    -- Sem a flag, o de antes: sem circuito por domínio, sem tratar 410 e 429 à parte.
    if not interno.rede_fed_total() then p := p - 'status'; end if;
    v_status := case when coalesce(p ->> 'status', '') ~ '^[0-9]{1,3}$' then (p ->> 'status')::integer end;
    v_dom := coalesce(case when lower(coalesce(p ->> 'dominio', '')) ~ '^[a-z0-9.-]{3,253}$' then lower(p ->> 'dominio') end, interno.rede_fed_dominio(v_q.destino));
    if coalesce((p ->> 'ok')::boolean, false) then
      update rede_fed_fila set feito_em = now(), erro = '' where id = v_q.id;
      update fediverso_dominios set falhas = 0, nivel = 0, morto_ate = null, ultimo_ok = now() where dominio = v_dom;
      return jsonb_build_object('ok', true);
    end if;
    if v_status = 410 then
      -- A caixa não existe mais (Gone): quem seguia por ela sai.
      update rede_fed_fila set feito_em = now(), erro = left(coalesce(p ->> 'erro', 'http_410'), 300) where id = v_q.id;
      delete from rede_fed_seguidores where inbox = v_q.destino or inbox_compartilhada = v_q.destino;
      delete from fediverso_grupo_seguidores where inbox = v_q.destino or inbox_compartilhada = v_q.destino;
      return jsonb_build_object('ok', true);
    end if;
    if v_status = 429 then
      v_espera := least(greatest(case when coalesce(p ->> 'espera', '') ~ '^[0-9]{1,6}$' then (p ->> 'espera')::integer else 600 end, 30), 43200);
      update rede_fed_fila set erro = left(coalesce(p ->> 'erro', 'http_429'), 300), proxima = now() + make_interval(secs => v_espera),
        tentativas = greatest(tentativas - 1, 0) where id = v_q.id;
      return jsonb_build_object('ok', true);
    end if;
    v_conexao := p ? 'status' and (v_status is null or v_status = 0 or v_status in (502, 503, 504, 520, 521, 522, 523, 524, 525, 526, 530));
    if v_conexao and v_dom is not null then
      insert into fediverso_dominios (dominio, falhas, ultima_falha) values (v_dom, 1, now())
      on conflict (dominio) do update set falhas = fediverso_dominios.falhas + 1, ultima_falha = now()
      returning * into v_d;
      if v_d.falhas >= 5 then
        update fediverso_dominios set morto_ate = now() + case nivel when 0 then interval '1 hour' when 1 then interval '6 hours' else interval '24 hours' end,
          nivel = least(nivel + 1, 2), falhas = 0
        where dominio = v_dom returning * into v_d;
        update rede_fed_fila set proxima = greatest(proxima, v_d.morto_ate) where feito_em is null and interno.rede_fed_dominio(destino) = v_dom;
        update rede_fed_fila set erro = left(coalesce(p ->> 'erro', 'dominio_fora_do_ar'), 300), tentativas = greatest(tentativas - 1, 0) where id = v_q.id;
        return jsonb_build_object('ok', true, 'morto_ate', v_d.morto_ate);
      end if;
    end if;
    if coalesce((p ->> 'definitivo')::boolean, false) or coalesce(v_t, 0) >= 8 then
      update rede_fed_fila set feito_em = now(), erro = left(coalesce(p ->> 'erro', 'falha'), 300) where id = v_q.id;
    else
      update rede_fed_fila set erro = left(coalesce(p ->> 'erro', 'falha'), 300),
        proxima = now() + least(interval '12 hours', interval '1 minute' * power(2, greatest(coalesce(v_t, 1), 1)))
      where id = v_q.id;
    end if;
    return jsonb_build_object('ok', true);

  when 'dominio_estado' then
    select * into v_d from fediverso_dominios where dominio = lower(coalesce(p ->> 'dominio', ''));
    return jsonb_build_object('morto_ate', case when v_d.morto_ate > now() then v_d.morto_ate end, 'falhas', coalesce(v_d.falhas, 0));

  when 'contagem' then
    return jsonb_build_object('usuarios', (select count(*)::integer from rede_fed_atores where ligado),
                              'posts', (select count(*)::integer from rede_fed_enviados where apagado_em is null));

  when 'contagem_ativos' then
    return jsonb_build_object(
      'mes', (select count(distinct e.perfil)::integer from rede_fed_enviados e join rede_fed_atores t on t.perfil = e.perfil and t.ligado where e.enviado_em > now() - interval '30 days'),
      'semestre', (select count(distinct e.perfil)::integer from rede_fed_enviados e join rede_fed_atores t on t.perfil = e.perfil and t.ligado where e.enviado_em > now() - interval '180 days'));

  when 'bloqueado' then
    return to_jsonb(interno.rede_fed_bloqueado(coalesce(p ->> 'url', '')));

  when 'comunidade' then
    v_slug := lower(coalesce(p ->> 'slug', ''));
    if not interno.rede_fed_grupo_ok(v_slug) then return jsonb_build_object('estado', 'inexistente'); end if;
    select * into v_com from rede_comunidades where slug = v_slug;
    select * into v_g from fediverso_grupos where comunidade = v_slug;
    return jsonb_build_object('estado', 'ligado', 'slug', v_com.slug, 'nome', v_com.nome, 'descricao', v_com.descricao, 'categoria', v_com.categoria,
      'criada_em', v_com.criada_em, 'chave_publica', v_g.chave_publica, 'chave_privada', v_g.chave_privada,
      -- Só os moderadores que têm a própria federação ligada aparecem lá fora (attributedTo / moderators).
      'moderadores', coalesce((select jsonb_agg(ra.handle order by ra.handle) from rede_comunidade_membros m join rede_fed_atores ra on ra.perfil = m.usuario and ra.ligado
                               where m.comunidade = v_slug and m.papel = 'moderacao' and m.situacao = 'ativo' and interno.rede_fed_impedimento(ra.perfil) is null), '[]'::jsonb),
      'seguidores', (select count(*)::integer from fediverso_grupo_seguidores s where s.comunidade = v_slug));

  when 'comunidade_chaves' then
    v_slug := lower(coalesce(p ->> 'slug', ''));
    if not interno.rede_fed_grupo_ok(v_slug) then perform interno.erro('nao_encontrado'); end if;
    if coalesce(p ->> 'publica', '') !~ '^-----BEGIN PUBLIC KEY-----' or char_length(coalesce(p ->> 'privada', '')) < 100 then perform interno.erro('invalido:chave'); end if;
    insert into fediverso_grupos (comunidade, chave_publica, chave_privada) values (v_slug, p ->> 'publica', p ->> 'privada')
    on conflict (comunidade) do update set chave_publica = excluded.chave_publica, chave_privada = excluded.chave_privada where fediverso_grupos.chave_publica is null;
    select * into v_g from fediverso_grupos where comunidade = v_slug;
    return jsonb_build_object('chave_publica', v_g.chave_publica, 'chave_privada', v_g.chave_privada);

  when 'comunidade_seguidores' then
    v_slug := lower(coalesce(p ->> 'slug', ''));
    if not interno.rede_fed_grupo_ok(v_slug) then return jsonb_build_object('total', 0); end if;
    return jsonb_build_object('total', (select count(*)::integer from fediverso_grupo_seguidores s where s.comunidade = v_slug));

  when 'comunidade_seguidor' then
    v_slug := lower(coalesce(p ->> 'slug', ''));
    if not interno.rede_fed_grupo_ok(v_slug) then return jsonb_build_object('ok', false, 'motivo', 'desligado'); end if;
    if v_ator = '' then perform interno.erro('invalido:ator'); end if;
    if interno.rede_fed_bloqueado(v_ator) or interno.rede_fed_bloqueado(p ->> 'inbox') then return jsonb_build_object('ok', false, 'motivo', 'bloqueado'); end if;
    if coalesce((p ->> 'sim')::boolean, true) then
      if coalesce(p ->> 'inbox', '') !~ '^https://[^\s]+$' or interno.rede_fed_dominio(p ->> 'inbox') <> interno.rede_fed_dominio(v_ator) then perform interno.erro('invalido:inbox'); end if;
      insert into fediverso_grupo_seguidores (comunidade, ator, inbox, inbox_compartilhada, pedido)
      values (v_slug, v_ator, p ->> 'inbox',
              case when coalesce(p ->> 'compartilhada', '') ~ '^https://[^\s]+$' and interno.rede_fed_dominio(p ->> 'compartilhada') = interno.rede_fed_dominio(v_ator) then p ->> 'compartilhada' end,
              left(coalesce(p ->> 'pedido', ''), 500))
      on conflict (comunidade, ator) do update set inbox = excluded.inbox, inbox_compartilhada = excluded.inbox_compartilhada, pedido = excluded.pedido;
      insert into rede_fed_fila (perfil, comunidade, tipo, objeto, destino, extra)
      values (null, v_slug, 'group-accept', v_ator, p ->> 'inbox', jsonb_build_object('pedido', left(coalesce(p ->> 'pedido', ''), 500)));
    else
      delete from fediverso_grupo_seguidores where comunidade = v_slug and ator = v_ator;
    end if;
    return jsonb_build_object('ok', true);

  when 'comunidade_outbox' then
    v_slug := lower(coalesce(p ->> 'slug', ''));
    if not interno.rede_fed_grupo_ok(v_slug) then return jsonb_build_object('total', 0, 'itens', '[]'::jsonb); end if;
    v_limite := least(greatest(coalesce((p ->> 'limite')::integer, 20), 1), 40);
    v_antes := nullif(p ->> 'antes', '')::timestamptz;
    select count(*)::integer into v_n from rede_fed_enviados e join rede_posts r on r.id = e.post
    where e.apagado_em is null and r.comunidade = v_slug and r.resposta_a is null;
    select coalesce(jsonb_agg(interno.rede_fed_post_json(r) order by r.criado_em desc), '[]'::jsonb) into v_res
    from (select r.* from rede_fed_enviados e join rede_posts r on r.id = e.post
          where e.apagado_em is null and r.comunidade = v_slug and r.resposta_a is null and (v_antes is null or r.criado_em < v_antes)
            and interno.rede_fed_federavel(r)
          order by r.criado_em desc limit v_limite) r;
    return jsonb_build_object('total', v_n, 'itens', v_res);

  else
    perform interno.erro('invalido:acao');
  end case;
  return null;
end $$;

/**
 * A faxina da federação. Agora: nota de fora sem ligação com nada daqui sai em 30 dias; a que responde a um post daqui (post_local),
 * menciona alguém daqui ou foi respondida daqui fica enquanto essa ligação existir (LGPD art. 15 e 16). Impulsos de notas que já
 * saíram, domínios sem falha há 30 dias e entregas sem quem as assine também saem.
 */
create or replace function interno.rede_fed_limpar() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_fed_fila where feito_em is not null and feito_em < now() - interval '14 days';
  delete from rede_fed_recebidos c where c.recebido_em < now() - interval '30 days' and c.post_local is null
    and not exists (select 1 from fediverso_mencoes m where m.nota = c.id)
    and not exists (select 1 from rede_posts l where l.resposta_a_remota = c.id);
  delete from fediverso_interacoes i where i.direcao = 'entrada' and i.objeto_remoto is not null
    and not exists (select 1 from rede_fed_recebidos c where c.id = i.objeto_remoto);
  delete from rede_fed_remotos r where r.buscado_em < now() - interval '60 days'
    and not exists (select 1 from rede_fed_seguidores s where s.ator = r.ator) and not exists (select 1 from rede_fed_seguindo s where s.ator = r.ator)
    and not exists (select 1 from rede_fed_recebidos c where c.ator = r.ator) and not exists (select 1 from fediverso_grupo_seguidores g where g.ator = r.ator);
  -- Chaves de quem desligou e já não tem nada na fila: apagadas (religar gera um par novo).
  update rede_fed_atores a set chave_publica = null, chave_privada = null
  where not a.ligado and a.chave_privada is not null and a.desligado_em < now() - interval '1 day'
    and not exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null);
  -- Conta apagada (interno.rede_fed_conta_apagada): as retiradas já saíram ou desistiram; a linha e a fila dela somem.
  delete from rede_fed_atores a where not exists (select 1 from perfis f where f.id = a.perfil)
    and not exists (select 1 from rede_fed_fila q where q.perfil = a.perfil and q.feito_em is null);
  delete from rede_fed_fila q where q.feito_em is not null and q.perfil is not null and not exists (select 1 from perfis f where f.id = q.perfil);
  -- Entrega de pessoa sem ator (nunca vai ser assinada): encerrada.
  update rede_fed_fila q set feito_em = now(), erro = 'sem_assinante'
  where q.feito_em is null and q.perfil is not null and not exists (select 1 from rede_fed_atores a where a.perfil = q.perfil);
  delete from fediverso_dominios where (morto_ate is null or morto_ate < now()) and coalesce(ultima_falha, 'epoch'::timestamptz) < now() - interval '30 days';
end $$;

-- ── 8. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────
-- Nenhuma função interna é chamável de fora. As da pessoa pedem conta (cada uma confere a sessão); a do servidor continua só com o segredo.
do $$
declare
  v_internas text[] := array['rede_fed_config_bool(text)', 'rede_fed_recurso_vivo(text)', 'rede_fed_total()', 'rede_fed_grupos_ligado()', 'rede_fed_versao()',
    'rede_fed_host_local()', 'rede_fed_uuid_local(text)', 'rede_fed_handle_local(text)', 'rede_fed_post_local(text)', 'rede_fed_html_ok(text)',
    'rede_fed_aviso_base(text)', 'rede3_aviso_pref(uuid, text, text)', 'rede3_aviso_chave(text, uuid, uuid)', 'rede_fed_avisar(uuid, text, uuid, text, text)',
    'rede_fed_aviso_remoto(uuid[])', 'rede_fed_comunidade_ok(text)', 'rede_fed_grupo_ok(text)', 'rede_fed_federavel(interno.rede_posts, integer)',
    'rede_fed_mencionados(interno.rede_posts)', 'rede_fed_entregar_mencionados(interno.rede_posts, text, uuid, interno.rede_posts)',
    'rede_fed_post_json(interno.rede_posts)', 'rede_fed_post_mudou()', 'rede_fed_ligar_perfil(uuid)', 'rede_fed_desligar(uuid)',
    'rede_fed_consentimento_fediverso()', 'rede_fed_nota_ve(interno.rede_fed_recebidos, uuid)',
    'rede_fed_cartao(interno.rede_fed_recebidos, uuid, jsonb)', 'rede_fed_limpar()'];
  v_publicas text[] := array['rede_aderir(boolean, integer, boolean)', 'rede_fed_descoberta(boolean)', 'rede_fed_eu(text)',
    'rede_fed_bloquear(text, boolean, text)', 'rede_fed_linha_mista(text, integer)', 'rede_fed_perfil_remoto(text)', 'rede_fed_fio_remoto(text)', 'rede_fed_respostas_de(uuid, text, integer)',
    'rede_fed_interagir(text, text, boolean)', 'rede_fed_responder_remoto(text, text, text)', 'rede_fed_denunciar_remoto(text, text, text, boolean)',
    'rede_fed_bloquear_pessoa(text, boolean)', 'rede_fed_silenciar_pessoa(text, boolean)', 'rede_fed_denuncias_listar(text)',
    'rede_fed_denuncia_decidir(uuid, text)'];
  v_f text;
  v_papeis boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach v_f in array v_internas loop
    execute format('revoke all on function interno.%s from public', v_f);
    if v_papeis then execute format('revoke all on function interno.%s from anon, authenticated', v_f); end if;
  end loop;
  foreach v_f in array v_publicas || array['rede_fed_situacao()', 'rede_fed_servidor(text, text, jsonb)'] loop
    execute format('revoke all on function public.%s from public', v_f);
    if v_papeis then execute format('revoke all on function public.%s from anon, authenticated', v_f); end if;
  end loop;
  if v_papeis then
    foreach v_f in array v_publicas loop
      execute format('grant execute on function public.%s to authenticated, service_role', v_f);
    end loop;
    grant execute on function public.rede_fed_situacao(), public.rede_fed_servidor(text, text, jsonb) to anon, authenticated, service_role;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F0 · o contrato comum (09/11/2026) ═══════════════════════════
-- Nome do arquivo: 20261109 (a data em que a F0 foi refeita), e não 20261108 como na lista do plano (§5/§8): as migrações da
-- Onda 5 seguem o padrão supabase/migracoes/20261109-alumia-<frente>.sql. O integrador cola na ordem F0→F9 do mesmo jeito.
-- docs/plano-2026-11/PLANO-ALUMIA.md, seções 1, 5 (F0), 6 e 8. Idempotente: pode rodar duas vezes sem estrago (o teste
-- scripts/testar-alumia-rota.mjs roda duas vezes no banco local). NÃO está no install.sql: o integrador cola no fim, antes das
-- migrações F1..F9. NÃO rodar em produção sem o Jonathan.
--
-- O que muda:
--   1. rede_posts ganha três colunas, só colunas (a lógica é de cada frente): expira_em (F6, posts que somem), ato (F2, a linha ao
--      vivo de um ato) e como (F4/F6, a identidade ou organização que publicou, que é SEMPRE o próprio autor: o dono da
--      identidade nunca fica gravado no post).
--   2. Checks ampliados: os alvos novos de denúncia e de moderação, e os tipos novos de preferência de aviso.
--   3. interno.rede_identidades (dono → identidade/organização) e interno.rede_age_como: o vínculo fica SÓ aqui (§6.6).
--   4. public.rede_alumia_versao(): o número do contrato (a tela mostra "banco desatualizado" quando faltar).
--   5. O catálogo de recursos ganha as flags da Onda 5 (todas só pelo nome).
--   6. A rota mudou para /alumia: o link do resumo semanal e a ponte da página /denunciar (que aceita os dois caminhos).
--
-- Leis (conferidas no texto, leis-do-brasil): LGPD (Lei 13.709/2018) art. 5º, II e art. 11 — opinião política e filiação são
-- dado pessoal sensível: por isso nenhuma função nova devolve lista de pessoas e o vínculo dono↔identidade não sai do banco; art.
-- 6º, III (necessidade): rede_identidades guarda só a DATA da criação, sem hora, para não permitir cruzar o horário com a
-- atividade do dono; art. 46 (segurança): RLS ligada e nenhuma permissão para anon/authenticated nas tabelas novas.

-- ── 1. rede_posts: colunas do contrato ────────────────────────────────────────────────────────────────────────────────────
alter table interno.rede_posts add column if not exists expira_em timestamptz;
alter table interno.rede_posts add column if not exists ato uuid;
alter table interno.rede_posts add column if not exists como uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_posts'::regclass and conname = 'rede_posts_ato_fk') then
    alter table interno.rede_posts add constraint rede_posts_ato_fk foreign key (ato) references interno.rede_posts (id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_posts'::regclass and conname = 'rede_posts_como_fk') then
    alter table interno.rede_posts add constraint rede_posts_como_fk foreign key (como) references interno.perfis (id) on delete cascade;
  end if;
  -- "como" é a identidade que publicou e ela É o autor do post: gravar outra pessoa aqui revelaria o dono da identidade.
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_posts'::regclass and conname = 'rede_posts_como_autor') then
    alter table interno.rede_posts add constraint rede_posts_como_autor check (como is null or como = autor);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_posts'::regclass and conname = 'rede_posts_ato_nao_ele') then
    alter table interno.rede_posts add constraint rede_posts_ato_nao_ele check (ato is null or ato <> id);
  end if;
end $$;
create index if not exists rede_posts_ato on interno.rede_posts (ato, criado_em) where ato is not null;
create index if not exists rede_posts_expira on interno.rede_posts (expira_em) where expira_em is not null;

-- ── 2. Checks ampliados ───────────────────────────────────────────────────────────────────────────────────────────────────
-- Denúncia: os alvos de antes + os das frentes novas (stories, notas, organizações, consultas, perguntas da plenária, arquivos
-- do núcleo, wiki, figurinhas, petições). Tudo cai na mesma fila (PLANO-ALUMIA §7.1). O laço derruba só o check da LISTA de
-- alvos (o Postgres guarda "alvo_tipo in (...)" como "alvo_tipo = ANY (ARRAY[...])"), e não outro check que só cite a coluna.
do $$
declare r record;
begin
  for r in select conname from pg_constraint where conrelid = 'interno.rede_denuncias'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) ~* '\(\(?alvo_tipo = ANY|alvo_tipo IN \(' loop
    execute format('alter table interno.rede_denuncias drop constraint %I', r.conname);
  end loop;
  alter table interno.rede_denuncias add constraint rede_denuncias_alvo_tipo_v5 check (alvo_tipo in (
    'post', 'perfil', 'comunidade',
    'story', 'nota', 'org', 'consulta', 'pergunta', 'arquivo', 'wiki', 'figurinha', 'peticao'));
end $$;
-- Registro de moderação (continua só de inserção): os mesmos alvos novos.
do $$
declare r record;
begin
  for r in select conname from pg_constraint where conrelid = 'interno.rede_moderacao'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) ~* '\(\(?alvo_tipo = ANY|alvo_tipo IN \(' loop
    execute format('alter table interno.rede_moderacao drop constraint %I', r.conname);
  end loop;
  alter table interno.rede_moderacao add constraint rede_moderacao_alvo_tipo_v5 check (alvo_tipo in (
    'post', 'perfil', 'comunidade', 'nucleo',
    'story', 'nota', 'org', 'consulta', 'pergunta', 'arquivo', 'wiki', 'figurinha', 'peticao'));
end $$;
-- Preferências de aviso: as de antes + os tipos novos das frentes. O que a pessoa já escolheu fica.
do $$
declare r record;
begin
  for r in select conname from pg_constraint where conrelid = 'interno.rede_avisos_prefs'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) ~* '\(\(?tipo = ANY|[^_]tipo IN \(' loop
    execute format('alter table interno.rede_avisos_prefs drop constraint %I', r.conname);
  end loop;
  alter table interno.rede_avisos_prefs add constraint rede_avisos_prefs_tipo_v5 check (tipo in (
    'resposta', 'mencao', 'citacao', 'seguidor', 'chamado', 'nucleo', 'moderacao', 'apoio', 'resumo',
    'ato_mudou', 'consulta', 'plenaria', 'org_postou', 'story_resposta', 'estou_bem', 'detido', 'marcacao', 'lembrete', 'conversa_seguida'));
end $$;

-- ── 3. Identidades e contas de organização ────────────────────────────────────────────────────────────────────────────────
-- Uma identidade (ou conta de organização) é OUTRO usuário em auth.users, sem senha, criado pelo servidor (lib/rede/contas-extra.ts).
-- O único lugar que diz de quem ela é: esta tabela. Nenhuma função devolve esse vínculo a outra pessoa nem à moderação comum; só
-- a coordenação, por "quebra de vidro" registrada em rede_moderacao e com ordem judicial (PLANO-ALUMIA §6.6). Risco que fica
-- (documentar na tela): um vazamento do banco inteiro revela o vínculo.
create table if not exists interno.rede_identidades (
  dono uuid not null references interno.perfis (id) on delete cascade,
  identidade uuid not null unique references interno.perfis (id) on delete cascade,
  tipo text not null check (tipo in ('identidade', 'org')),
  -- Só a data (LGPD art. 6º, III): a hora exata ajudaria a ligar a conta nova ao dono pelo horário de atividade.
  criada_em date not null default current_date,
  check (dono <> identidade)
);
create index if not exists rede_identidades_dono on interno.rede_identidades (dono);
alter table interno.rede_identidades enable row level security;
revoke all on table interno.rede_identidades from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_identidades from anon, authenticated;
  end if;
end $$;

/**
 * `p_quem` pode agir como `p_como`? Sim quando é ele mesmo ou quando `p_como` é uma identidade/organização dele. As frentes
 * (F4: gestores da organização; F6: troca de identidade) estendem esta regra com create or replace, sem mudar a assinatura.
 */
create or replace function interno.rede_age_como(p_quem uuid, p_como uuid) returns boolean
language sql stable security definer set search_path = interno, pg_temp as $$
  select p_quem is not null and p_como is not null
    and (p_quem = p_como or exists (select 1 from rede_identidades i where i.dono = p_quem and i.identidade = p_como))
$$;
revoke all on function interno.rede_age_como(uuid, uuid) from public;

/**
 * Liga uma conta recém-criada (sem senha) ao dono. Só o servidor (chave de serviço) chama, logo depois de criar o usuário em
 * auth.users (lib/rede/contas-extra.ts). Regras: dono e identidade existem e são diferentes; uma identidade não tem dono duas
 * vezes; quem já é identidade não vira dono (sem cadeia); no máximo 5 identidades e 5 organizações por dono. Devolve só "ok".
 */
create or replace function public.rede_identidade_ligar(p_dono uuid, p_identidade uuid, p_tipo text) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if p_dono is null or p_identidade is null or p_dono = p_identidade then perform interno.erro('invalido:identidade'); end if;
  if p_tipo is null or p_tipo not in ('identidade', 'org') then perform interno.erro('invalido:tipo'); end if;
  if not exists (select 1 from perfis where id = p_dono) or not exists (select 1 from perfis where id = p_identidade) then
    perform interno.erro('nao_encontrado');
  end if;
  if exists (select 1 from rede_identidades where identidade = p_dono) then perform interno.erro('invalido:dono'); end if;
  if exists (select 1 from rede_identidades where dono = p_identidade) then perform interno.erro('invalido:identidade'); end if;
  if exists (select 1 from rede_identidades where identidade = p_identidade) then perform interno.erro('invalido:identidade'); end if;
  if (select count(*) from rede_identidades where dono = p_dono and tipo = p_tipo) >= 5 then perform interno.erro('limite_identidades'); end if;
  insert into rede_identidades (dono, identidade, tipo) values (p_dono, p_identidade, p_tipo);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.rede_identidade_ligar(uuid, uuid, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.rede_identidade_ligar(uuid, uuid, text) from anon, authenticated;
    revoke all on function interno.rede_age_como(uuid, uuid) from anon, authenticated;
    grant execute on function public.rede_identidade_ligar(uuid, uuid, text) to service_role;
  end if;
end $$;

-- ── 4. O número do contrato ───────────────────────────────────────────────────────────────────────────────────────────────
/** A versão do contrato da Alumia no banco (1 = F0). A tela compara com a que espera e mostra "banco desatualizado" se faltar. */
create or replace function public.rede_alumia_versao() returns integer language sql immutable set search_path = interno, pg_temp as $$
  select 1
$$;
revoke all on function public.rede_alumia_versao() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant execute on function public.rede_alumia_versao() to anon, authenticated, service_role;
  end if;
end $$;

-- ── 5. Catálogo de recursos: as flags da Onda 5 (lib/recursos.ts), todas só pelo nome ───────────────────────────────────────
-- As mesmas linhas já estão no PRIMEIRO insert do catálogo no install.sql e em 2026-11-backend-1.sql (o teste
-- scripts/testar-backend-1.mjs compara aquele bloco com lib/recursos.ts). Esta cópia serve ao banco que já existe.
insert into interno.recursos_catalogo (nome, so_pelo_nome) values
  ('alumia-2', true), ('alumia-stories', true), ('alumia-modo-ato', true), ('alumia-org', true), ('alumia-chat-grupo', true)
on conflict (nome) do update set so_pelo_nome = excluded.so_pelo_nome;

-- ── 6. A rota mudou para /alumia (lib/rede/rota-alumia.ts) ──────────────────────────────────────────────────────────────────
-- As mesmas funções de antes, com o caminho novo: o link do resumo semanal leva a /pt/alumia/avisos, e a ponte da página
-- /denunciar reconhece um post pelos dois caminhos (/comunidade/p/<id>, dos links antigos, e /alumia/p/<id>).
-- Ficam DE PROPÓSITO no caminho antigo: os links '/comunidade?t=<id>' que o gatilho dos tópicos grava na linha do tempo da
-- coordenação (interno.atividade_nova, no install.sql). São de tópicos do fórum de antes, já gravados em linhas antigas e
-- conferidos por scripts/testar-banco.mjs; o proxy leva '/comunidade?t=' ao destino num salto só (lib/rede/alumia.ts).
create or replace function interno.rede3_aviso_resumo(p_usuario uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  r record; v_n integer := 0; v_linhas text := ''; v_titulos text := ''; v_lista text[] := '{}'; v_t text;
begin
  for r in select g.tipo, sum(g.total)::integer as n from interno.rede3_aviso_grupos(p_usuario, now() - interval '7 days') g where not g.lido group by g.tipo order by 2 desc loop
    v_n := v_n + r.n;
    v_linhas := v_linhas || format(E'- %s %s\n', r.n, case coalesce(r.tipo, '')
      when 'resposta' then case when r.n = 1 then 'resposta' else 'respostas' end
      when 'mencao' then case when r.n = 1 then 'menção' else 'menções' end
      when 'citacao' then case when r.n = 1 then 'citação' else 'citações' end
      when 'seguidor' then case when r.n = 1 then 'novo seguidor' else 'novos seguidores' end
      when 'apoio' then case when r.n = 1 then 'apoio' else 'apoios' end
      when 'chamado' then case when r.n = 1 then 'novidade em chamado' else 'novidades em chamados' end
      when 'nucleo' then case when r.n = 1 then 'novidade em núcleo' else 'novidades em núcleos' end
      when 'moderacao' then case when r.n = 1 then 'aviso da moderação' else 'avisos da moderação' end
      else case when r.n = 1 then 'aviso da conta' else 'avisos da conta' end end);
  end loop;
  if v_n = 0 then return null; end if;
  for r in
    select distinct on (g.post) g.post, g.titulo from interno.rede3_aviso_grupos(p_usuario, now() - interval '7 days') g
    join rede_posts p on p.id = g.post
    where not g.lido and g.tipo in ('resposta', 'mencao', 'citacao') and g.titulo is not null
      and interno.rede2_publico(p) = 'internet' and not p.oculto and not p.retido and p.apagado_em is null
    order by g.post limit 5 loop
    v_t := left(interno.sem_link(r.titulo), 80);
    if v_t <> '' then v_lista := v_lista || v_t; end if;
  end loop;
  if cardinality(v_lista) > 0 then
    v_titulos := E'\n\nConversas públicas com novidade:\n' || (select string_agg('- ' || t, E'\n') from unnest(v_lista) t);
  end if;
  return jsonb_build_object('n', v_n, 'assunto', 'Seu resumo da semana na Alumia',
    'texto', format(E'Nesta semana você teve %s %s na Alumia:\n%s%s\n\nAbrir os avisos:\n\n%s\n\nVocê recebe este resumo porque ligou, em Avisos → Preferências, a opção "Resumo semanal por e-mail". Ele leva só contagens e títulos de conversas públicas, nunca o texto de um post. Para desligar, entre em Avisos → Preferências.',
      v_n, case when v_n = 1 then 'aviso novo' else 'avisos novos' end, v_linhas, v_titulos, interno.endereco() || '/pt/alumia/avisos'));
end $$;

create or replace function interno.rede3_aviso_resumo_semanal() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare r record; v_res jsonb; v_n integer := 0; v_email text;
begin
  for r in select f.id from perfis f
           where not f.suspenso and interno.rede3_aviso_pref(f.id, 'resumo', 'email') and exists (select 1 from rede_avisos_prefs p where p.usuario = f.id and p.tipo = 'resumo' and p.canal = 'email' and p.ligado)
           order by f.id limit 2000 loop
    if not interno.rede2_membro(r.id) then continue; end if;
    v_email := lower(coalesce(interno.email_da_conta(r.id), ''));
    if v_email = '' or exists (select 1 from emails e where e.para = v_email and e.tipo = 'rede_resumo' and e.criado_em > now() - interval '6 days') then continue; end if;
    v_res := interno.rede3_aviso_resumo(r.id);
    if v_res is null then continue; end if;
    if interno.email(v_email, 'rede_resumo', v_res ->> 'assunto', v_res ->> 'texto', interno.endereco() || '/pt/alumia/avisos', 1) then v_n := v_n + 1; end if;
  end loop;
  delete from avisos where categoria = 'rede' and lido and criado_em < now() - interval '120 days';
  return v_n;
end $$;

create or replace function interno.rede3_mod_ponte_denuncia() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_id text := substring(new.alvo from '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})'); x rede_posts; v_cat text;
begin
  if v_id is null or (new.alvo !~ '/(comunidade|alumia)/p/' and new.alvo !~ 'post=') then return new; end if;
  select * into x from rede_posts where id = v_id::uuid;
  if not found or not interno.rede_ve(x, new.autor) or x.autor is not distinct from new.autor then return new; end if;
  v_cat := interno.rede3_mod_categoria(new.motivo);
  if new.autor is not null and exists (select 1 from rede_denuncias d where d.quem = new.autor and d.alvo_tipo = 'post' and d.alvo = v_id and d.situacao in ('aberta', 'em_analise')) then return new; end if;
  insert into rede_denuncias (alvo_tipo, alvo, categoria, prioridade, texto, quem) values ('post', v_id, v_cat, interno.rede2_prioridade(v_cat), left(new.detalhes, 2000), new.autor);
  return new;
exception when others then
  return new;
end $$;

-- ═══════════════════════════ fim da F0 ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F1 · o back-end mínimo da cara nova (09/11/2026) ═══════════════════════════
-- docs/plano-2026-11/PLANO-ALUMIA.md, seções 5 (F1), 6 e 8. Roda DEPOIS da F0 (20261109-alumia-f0-contrato.sql). Idempotente:
-- pode rodar duas vezes sem estrago (scripts/testar-alumia-f1-banco.mjs roda duas vezes no banco local). NÃO está no install.sql:
-- o integrador cola no fim, na ordem F0→F9. NÃO rodar em produção sem o Jonathan.
--
-- O que a tela da F1 precisa para cada função funcionar de verdade:
--   1. Repostar (rede_repostagens): o post aparece na aba Seguindo de quem segue quem repostou. Só o próprio estado volta; a
--      lista de quem repostou e o total nunca saem do banco.
--   2. Rascunho no servidor (rede_rascunhos): só o dono lê, guarda e apaga; até 20 por pessoa; some em 30 dias.
--   3. Desfazer envio: o atraso de 10 s é do aparelho; esta função cobre o toque em "Desfazer" que chega quando o pedido já
--      saiu (até 30 s depois de publicado, só o autor, e nunca o que a triagem segurou).
--   4. Emblemas do menu: quantos avisos não lidos, conversas com novidade e atos confirmados que a PRÓPRIA pessoa tem.
--
-- Tudo em `interno` com RLS ligada e nenhuma permissão direta para anon/authenticated: só pelas funções abaixo (security
-- definer, search_path fixo, quem chama conferido, limites de uso por interno.limite).
--
-- Leis (conferidas no texto, leis-do-brasil): LGPD (Lei 13.709/2018) art. 5º, II e art. 11 — repostar é manifestação de opinião
-- política (dado sensível): por isso nenhuma função devolve QUEM repostou nem quantas pessoas repostaram; quem segue vê o post
-- na própria linha sem o nome de quem repostou. Art. 6º, III (necessidade) e art. 15, I (término do tratamento quando a
-- finalidade acaba): o rascunho guarda só texto e escolhas (nada de arquivo) e é apagado em 30 dias. Art. 18, VI (eliminação a
-- pedido): apagar rascunho e desfazer repost apagam a linha, não marcam. Art. 46 (segurança): RLS e nenhuma permissão direta.
-- ECA (Lei 8.069/1990) art. 17 (preservação da imagem e da identidade): a Rede só aceita quem confirmou 18 anos
-- (interno.rede2_membro); estas funções exigem a mesma regra para escrever.

-- ── 1. Repostar ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.rede_repostagens (
  quem uuid not null references interno.perfis (id) on delete cascade,
  post uuid not null references interno.rede_posts (id) on delete cascade,
  criado_em timestamptz not null default now(),
  primary key (quem, post)
);
create index if not exists rede_repostagens_post on interno.rede_repostagens (post);
create index if not exists rede_repostagens_tempo on interno.rede_repostagens (quem, criado_em desc);
alter table interno.rede_repostagens enable row level security;
revoke all on table interno.rede_repostagens from public;

/**
 * Este post pode ser repostado por p_quem? Só post de primeiro nível, visível a quem reposta, que não é dele, que não some
 * sozinho (F6) e cujo público é amplo (internet ou quem está na Alumia): repostar o que foi escrito para um grupo pequeno
 * (seguidores, comunidade, núcleo, equipe) espalharia o recado para fora de onde a autora quis.
 */
create or replace function interno.rede_alumia_repostavel(p interno.rede_posts, p_quem uuid) returns boolean
language sql stable security definer set search_path = interno, pg_temp as $$
  select p.id is not null and p_quem is not null and p.autor is distinct from p_quem
    and p.resposta_a is null and p.expira_em is null
    and not p.oculto and not p.retido and p.apagado_em is null
    and interno.rede2_publico(p) in ('internet', 'membros')
    and interno.rede_ve(p, p_quem)
$$;
revoke all on function interno.rede_alumia_repostavel(interno.rede_posts, uuid) from public;

/** Repostar (p_sim = true) ou desfazer. Devolve só o próprio estado: { repostei }. Desfazer vale sempre, mesmo se o post sumiu. */
create or replace function public.rede_pub_repostar(p_post uuid, p_sim boolean) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('alumia_repostar', 120, 60);
  if coalesce(p_sim, false) then
    select * into x from rede_posts where id = p_post;
    if not found or not interno.rede_ve(x, v) or x.oculto or x.retido or x.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
    if not interno.rede_alumia_repostavel(x, v) then perform interno.erro('sem_permissao'); end if;
    insert into rede_repostagens (quem, post) values (v, p_post) on conflict do nothing;
  else
    delete from rede_repostagens where quem = v and post = p_post;
  end if;
  return jsonb_build_object('repostei', exists (select 1 from rede_repostagens r where r.quem = v and r.post = p_post));
end $$;

/** Dos posts pedidos (até 50), quais EU repostei. Visitante: lista vazia. Nunca diz nada de outra pessoa. */
create or replace function public.rede_pub_repostados(p_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  if v is null or p_ids is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(r.post order by r.post) from rede_repostagens r where r.quem = v and r.post = any (p_ids[1:50])), '[]'::jsonb);
end $$;

/**
 * Os posts que quem eu sigo repostou, com o momento do repost mais recente em (p_desde, p_ate] (até 50, do mais novo ao mais
 * antigo), para a tela misturar na aba Seguindo na ordem de chegada. Cada post vem uma vez, com `repostado_em`, e SEM dizer
 * quem repostou nem quantos. Fora: o que eu mesma escrevi, o que eu não posso ver, o que silenciei, repost de quem eu bloqueei
 * ou me bloqueou, e de conta suspensa.
 */
create or replace function public.rede_pub_repostes(p_ate timestamptz default null, p_desde timestamptz default null, p_limite integer default 20) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_lim integer := least(greatest(coalesce(p_limite, 20), 1), 50);
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('rede2_ler', 600, 60);
  return coalesce((
    select jsonb_agg(interno.rede_post_v2(p, v) || jsonb_build_object('repostado_em', z.quando) order by z.quando desc, p.id desc)
    from (
      select r.post, max(r.criado_em) as quando
      from rede_repostagens r
      join rede_seguindo s on s.quem = v and s.segue = r.quem
      join perfis f on f.id = r.quem and not f.suspenso
      where (p_ate is null or r.criado_em <= p_ate) and (p_desde is null or r.criado_em > p_desde)
        and not interno.rede_bloqueado(v, r.quem)
      group by r.post
      order by 2 desc
      limit v_lim * 2
    ) z
    join rede_posts p on p.id = z.post
    where p.autor is distinct from v and interno.rede_alumia_repostavel(p, v) and not interno.rede_silenciado(p, v)
  ), '[]'::jsonb);
end $$;

-- ── 2. Rascunho no servidor ─────────────────────────────────────────────────────────────────────────────────────────────────
-- Só texto e escolhas (o "pedido" do compositor, com as chaves conferidas uma a uma); arquivo nunca.
create table if not exists interno.rede_rascunhos (
  id uuid primary key default gen_random_uuid(),
  autor uuid not null references interno.perfis (id) on delete cascade,
  pedido jsonb not null,
  atualizado_em timestamptz not null default now(),
  check (jsonb_typeof(pedido) = 'object' and pg_column_size(pedido) <= 65536)
);
create index if not exists rede_rascunhos_autor on interno.rede_rascunhos (autor, atualizado_em desc);
create index if not exists rede_rascunhos_tempo on interno.rede_rascunhos (atualizado_em);
alter table interno.rede_rascunhos enable row level security;
revoke all on table interno.rede_rascunhos from public;

/** Apaga os rascunhos com mais de 30 dias (de todo mundo). Roda de vez em quando, dentro das funções abaixo. */
create or replace function interno.rede_rascunhos_faxina() returns integer
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_n integer;
begin
  delete from rede_rascunhos where atualizado_em < now() - interval '30 days';
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function interno.rede_rascunhos_faxina() from public;

/**
 * Confere e limpa o pedido de um rascunho. Só estas chaves ficam: tipo, texto, titulo, corpo, comunidade, publico,
 * responde_quem (qualquer outra é descartada). Tamanhos e listas como no compositor; nada escrito → 'invalido:vazio'.
 */
create or replace function interno.rede_rascunho_limpo(p jsonb) returns jsonb
language plpgsql stable set search_path = interno, pg_temp as $$
declare
  v_tipo text; v_texto text; v_titulo text; v_corpo text; v_com text; v_publico text; v_responde text;
begin
  if p is null or jsonb_typeof(p) <> 'object' then perform interno.erro('invalido:rascunho'); end if;
  v_tipo := coalesce(nullif(p ->> 'tipo', ''), 'post');
  v_texto := coalesce(p ->> 'texto', '');
  v_titulo := coalesce(p ->> 'titulo', '');
  v_corpo := coalesce(p ->> 'corpo', '');
  v_com := nullif(p ->> 'comunidade', '');
  v_publico := coalesce(nullif(p ->> 'publico', ''), 'membros');
  v_responde := coalesce(nullif(p ->> 'responde_quem', ''), 'todos');
  if v_tipo not in ('post', 'ato', 'enquete', 'longo', 'aviso') then perform interno.erro('invalido:tipo'); end if;
  if char_length(v_texto) > 2000 or char_length(v_titulo) > 300 or char_length(v_corpo) > 20000 then perform interno.erro('invalido:tamanho'); end if;
  if v_com is not null and v_com !~ '^[a-z0-9-]{2,60}$' then perform interno.erro('invalido:comunidade'); end if;
  if v_publico not in ('internet', 'membros', 'seguidores', 'comunidade', 'nucleo', 'equipe') then perform interno.erro('invalido:publico'); end if;
  if v_responde not in ('todos', 'seguindo', 'mencionados', 'ninguem') then perform interno.erro('invalido:responde_quem'); end if;
  if btrim(v_texto) = '' and btrim(v_titulo) = '' and btrim(v_corpo) = '' then perform interno.erro('invalido:vazio'); end if;
  return jsonb_build_object('tipo', v_tipo, 'texto', v_texto, 'titulo', v_titulo, 'corpo', v_corpo, 'comunidade', v_com,
    'publico', v_publico, 'responde_quem', v_responde);
end $$;
revoke all on function interno.rede_rascunho_limpo(jsonb) from public;

/**
 * Guarda (com p.id de um rascunho MEU, atualiza; sem id ou com id que não é meu ou já sumiu, cria) e devolve { id, atualizado_em }.
 * Novo além do 20º: 'limite_rascunhos' (a tela avisa que fica só no aparelho).
 */
create or replace function public.rede_pub_rascunho_salvar(p jsonb) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_pedido jsonb; v_id uuid; r rede_rascunhos;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('alumia_rascunho', 600, 60);
  v_pedido := interno.rede_rascunho_limpo(p);
  delete from rede_rascunhos where autor = v and atualizado_em < now() - interval '30 days';
  if random() < 0.02 then perform interno.rede_rascunhos_faxina(); end if;
  begin
    v_id := nullif(p ->> 'id', '')::uuid;
  exception when others then
    v_id := null;
  end;
  if v_id is not null then
    update rede_rascunhos set pedido = v_pedido, atualizado_em = now() where id = v_id and autor = v returning * into r;
    if found then return jsonb_build_object('id', r.id, 'atualizado_em', r.atualizado_em); end if;
  end if;
  -- Um por vez por pessoa: dois salvamentos ao mesmo tempo não passam juntos do teto.
  perform pg_advisory_xact_lock(hashtextextended('rede_rascunhos:' || v::text, 0));
  if (select count(*) from rede_rascunhos where autor = v) >= 20 then perform interno.erro('limite_rascunhos'); end if;
  insert into rede_rascunhos (autor, pedido) values (v, v_pedido) returning * into r;
  return jsonb_build_object('id', r.id, 'atualizado_em', r.atualizado_em);
end $$;

/** Os MEUS rascunhos dos últimos 30 dias, do mais novo ao mais antigo (no máximo 20). Nunca os de outra pessoa. */
create or replace function public.rede_pub_rascunhos() returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.limite('alumia_rascunhos_ler', 240, 60);
  delete from rede_rascunhos where autor = v and atualizado_em < now() - interval '30 days';
  return coalesce((
    select jsonb_agg(z.pedido || jsonb_build_object('id', z.id, 'atualizado_em', z.atualizado_em) order by z.atualizado_em desc)
    from (select * from rede_rascunhos where autor = v order by atualizado_em desc limit 20) z
  ), '[]'::jsonb);
end $$;

/** Apaga um rascunho MEU. O de outra pessoa (ou que não existe) dá { apagado: false }, sem dizer qual dos dois. */
create or replace function public.rede_pub_rascunho_apagar(p_id uuid) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.limite('alumia_rascunho_apagar', 300, 60);
  delete from rede_rascunhos where id = p_id and autor = v;
  return jsonb_build_object('apagado', found);
end $$;

-- ── 3. Desfazer envio ───────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * Desfaz um post que acabou de sair: só o autor, até 30 s depois de publicado. Apaga de vez (o post, o que pendurou nele e, se
 * já tinha ido ao Fediverso, o gatilho da federação manda o Delete). Não desfaz o que a triagem segurou para revisão ou
 * bloqueou (a moderação precisa ver), nem o que já tem resposta de outra pessoa. Devolve { desfeito: true } ou um erro:
 * 'nao_encontrado' (não é meu ou não existe), 'prazo_passou', 'sem_permissao'.
 */
create or replace function public.rede_pub_desfazer(p_post uuid) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('alumia_desfazer', 30, 60);
  select * into x from rede_posts where id = p_post and autor = v for update;
  if not found or x.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
  if x.criado_em < now() - interval '30 seconds' then perform interno.erro('prazo_passou'); end if;
  if x.retido or x.oculto or coalesce(x.avaliacao, 'publicada') in ('revisao', 'bloqueada') then perform interno.erro('sem_permissao'); end if;
  if exists (select 1 from rede_posts r where r.resposta_a = x.id and r.autor is distinct from v) then perform interno.erro('sem_permissao'); end if;
  delete from rede_posts where id = x.id;
  return jsonb_build_object('desfeito', true);
end $$;

-- ── 4. Emblemas do menu ─────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * Os números dos emblemas do menu, todos da PRÓPRIA pessoa (nada de outra): avisos não lidos (mesma conta de rede_aviso_contar),
 * conversas com novidade (pedidos esperando + conversas com mensagem nova, a mesma regra de rede_dm_situacao) e atos que ela
 * confirmou ("Eu vou") e ainda vão acontecer. Visitante ou quem não é da Rede: tudo zero.
 */
create or replace function public.rede_alumia_emblemas() returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_avisos integer := 0; v_conversas integer := 0; v_atos integer := 0;
begin
  if v is null or not interno.rede2_membro(v) or exists (select 1 from perfis where id = v and suspenso) then
    return jsonb_build_object('avisos', 0, 'conversas', 0, 'atos', 0);
  end if;
  perform interno.limite('rede_avisos_n', 600, 60);
  v_avisos := (select count(*)::integer from interno.rede3_aviso_grupos(v) g where not g.lido);
  v_conversas := (select count(*)::integer from rede_dm_conversas c
    where (c.a = v or c.b = v) and (
      (c.situacao = 'pedido' and c.pediu <> v and not interno.rede_bloqueado(v, c.pediu))
      or (c.situacao = 'aberta' and exists (select 1 from rede_dm_mensagens m where m.conversa = c.id and m.autor <> v and m.expira_em > now()
            and m.criado_em > coalesce(case when c.a = v then c.a_leu_em else c.b_leu_em end, '-infinity'::timestamptz)))));
  begin
    v_atos := (select count(*)::integer from rede_vou o join rede_posts p on p.id = o.post
      where o.usuario = v and p.chamado is not null and p.apagado_em is null and not p.oculto
        and (p.chamado ->> 'quando') ~ '^\d{4}-\d{2}-\d{2}' and (p.chamado ->> 'quando')::timestamptz > now());
  exception when others then
    v_atos := 0;
  end;
  return jsonb_build_object('avisos', v_avisos, 'conversas', v_conversas, 'atos', v_atos);
end $$;

-- ── 5. Permissões ───────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function public.rede_pub_repostar(uuid, boolean), public.rede_pub_repostados(uuid[]), public.rede_pub_repostes(timestamptz, timestamptz, integer),
  public.rede_pub_rascunho_salvar(jsonb), public.rede_pub_rascunhos(), public.rede_pub_rascunho_apagar(uuid), public.rede_pub_desfazer(uuid),
  public.rede_alumia_emblemas() from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_repostagens, interno.rede_rascunhos from anon, authenticated;
    revoke all on function interno.rede_alumia_repostavel(interno.rede_posts, uuid), interno.rede_rascunhos_faxina(), interno.rede_rascunho_limpo(jsonb) from anon, authenticated;
    revoke all on function public.rede_pub_repostar(uuid, boolean), public.rede_pub_repostados(uuid[]), public.rede_pub_repostes(timestamptz, timestamptz, integer),
      public.rede_pub_rascunho_salvar(jsonb), public.rede_pub_rascunhos(), public.rede_pub_rascunho_apagar(uuid), public.rede_pub_desfazer(uuid),
      public.rede_alumia_emblemas() from anon;
    -- Tudo aqui é da própria conta: só quem entrou (e a chave de serviço, para o servidor).
    grant execute on function public.rede_pub_repostar(uuid, boolean), public.rede_pub_repostados(uuid[]), public.rede_pub_repostes(timestamptz, timestamptz, integer),
      public.rede_pub_rascunho_salvar(jsonb), public.rede_pub_rascunhos(), public.rede_pub_rascunho_apagar(uuid), public.rede_pub_desfazer(uuid),
      public.rede_alumia_emblemas() to authenticated, service_role;
    grant execute on function interno.rede_rascunhos_faxina() to service_role;
  end if;
end $$;

-- ═══════════════════════════ fim da F1 ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F2 · atos (back-end mínimo, 09/11/2026) ═══════════════════════════
-- docs/plano-2026-11/PLANO-ALUMIA.md, seções 5 (F2), 6 e 8. O contrato é o de lib/rede/tipos-atos.ts (as telas já usam o dublê
-- com estes nomes). Idempotente: pode rodar duas vezes (scripts/testar-alumia-f2.mjs roda duas vezes no banco local). Vem DEPOIS
-- da F0 (20261109-alumia-f0-contrato.sql). NÃO está no install.sql: o integrador cola. NÃO rodar em produção sem o Jonathan.
--
-- O que faz (só o mínimo para cada função da tela funcionar de verdade; tarefas, caronas, álbum, petição e mapa ficam para depois):
--   1. Reaproveita o chamado que já existe: interno.rede_chamados ganha situacao (confirmado/adiado/cancelado, migrado de
--      `cancelado`), inicio_anterior ("era 12/11"), titulo, palavra (a do mosaico, ^[A-Z ]{2,14}$), meta, link_apoio (só https),
--      motivo e mudado_em. Os chamados da Rede de hoje (o JSON rede_posts.chamado) ganham a linha deles em rede_chamados, sem
--      perder nada: o JSON e a coluna `cancelado` continuam lá e continuam certos. "Eu vou" é o mesmo rede_vou de sempre.
--   2. Funções (todas security definer, search_path fixo, com a checagem de quem chama, limite de uso e a matriz de visibilidade
--      interno.rede_ve): rede_ato_publicar, rede_atos, rede_ato, rede_ato_proximo, rede_ato_vou e rede_ato_mudar.
--
-- Privacidade (LGPD, Lei 13.709/2018, conferida no texto: art. 5º, II e art. 11 — ir a um ato revela opinião política, dado
-- pessoal sensível; art. 6º, III — necessidade; art. 46 — segurança):
--   - nenhuma função devolve quem confirmou; o mosaico recebe só a PROPORÇÃO (passos de 10 %, nula abaixo de 3 confirmações);
--   - o número exato de confirmações sai só para quem organizou (como já era no rede_vou de hoje);
--   - "Perto" é a cidade ESCRITA (texto), nunca posição do aparelho; o ato traz só o ponto público dele;
--   - o aviso de mudança vai só a quem confirmou, e nunca diz a ninguém quem mais confirmou;
--   - os limites de uso guardam a chave por conta ou pelo endereço CIFRADO (interno.origem), nunca o IP cru.
-- ECA (Lei 8.069/1990) e ECA Digital (Lei 15.211/2025): a Alumia é só 18+ (interno.rede2_membro exige rede_18), então confirmar
-- presença e chamar ato só existem para membro adulto; visitante só LÊ o que já é público na internet.

-- ── 1. Tabela do chamado ────────────────────────────────────────────────────────────────────────────────────────────────────
alter table interno.rede_chamados add column if not exists situacao text not null default 'confirmado';
alter table interno.rede_chamados add column if not exists inicio_anterior timestamptz;
alter table interno.rede_chamados add column if not exists titulo text;
alter table interno.rede_chamados add column if not exists palavra text;
alter table interno.rede_chamados add column if not exists meta smallint;
alter table interno.rede_chamados add column if not exists link_apoio text;
alter table interno.rede_chamados add column if not exists motivo text not null default '';
alter table interno.rede_chamados add column if not exists mudado_em timestamptz;
-- Os chamados da Rede de hoje não pediam cidade: sem ela o ato só não entra em "Perto" (o check de tamanho continua valendo).
alter table interno.rede_chamados alter column cidade drop not null;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_situacao') then
    alter table interno.rede_chamados add constraint rede_chamados_situacao check (situacao in ('confirmado', 'adiado', 'cancelado'));
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_palavra') then
    alter table interno.rede_chamados add constraint rede_chamados_palavra check (palavra is null or palavra ~ '^[A-Z ]{2,14}$');
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_titulo') then
    alter table interno.rede_chamados add constraint rede_chamados_titulo check (titulo is null or char_length(titulo) between 2 and 60);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_meta') then
    alter table interno.rede_chamados add constraint rede_chamados_meta check (meta is null or meta between 3 and 30000);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_link_apoio') then
    alter table interno.rede_chamados add constraint rede_chamados_link_apoio check (link_apoio is null or (link_apoio ~ '^https://[^\s<>"'']{4,}$' and char_length(link_apoio) <= 300));
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_motivo') then
    alter table interno.rede_chamados add constraint rede_chamados_motivo check (char_length(motivo) <= 140);
  end if;
  -- Só adiado guarda a data de antes junto com uma data nova.
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_chamados'::regclass and conname = 'rede_chamados_anterior') then
    alter table interno.rede_chamados add constraint rede_chamados_anterior check (inicio_anterior is null or inicio_anterior <> inicio);
  end if;
end $$;
alter table interno.rede_chamados enable row level security;
revoke all on table interno.rede_chamados from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_chamados from anon, authenticated;
    revoke all on table interno.rede_vou from anon, authenticated;
  end if;
end $$;
create index if not exists rede_chamados_inicio on interno.rede_chamados (inicio, post);
create index if not exists rede_vou_usuario on interno.rede_vou (usuario);

-- ── 2. Regras puras ─────────────────────────────────────────────────────────────────────────────────────────────────────────

/** A palavra do mosaico: a MESMA regra de lib/rede/mosaico.ts (normalizarPalavra): maiúsculas sem acento, só A–Z e espaço, até 14. */
create or replace function interno.rede_ato_palavra(p_texto text) returns text language sql immutable set search_path = interno, pg_temp as $$
  select btrim(left(btrim(regexp_replace(regexp_replace(upper(translate(coalesce(p_texto, ''),
    'áàâãäåéèêëíìîïóòôõöúùûüçñýÿÁÀÂÃÄÅÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝ',
    'aaaaaaeeeeiiiiooooouuuucnyyAAAAAAEEEEIIIIOOOOOUUUUCNY')), '[^A-Z ]', ' ', 'g'), '\s+', ' ', 'g')), 14))
$$;

/** A chave da cidade para "Perto": minúsculas, sem acento e com espaços simples ("São  Paulo" = "sao paulo"). Nada de posição. */
create or replace function interno.rede_ato_cidade(p_texto text) returns text language sql immutable set search_path = interno, pg_temp as $$
  select nullif(lower(btrim(regexp_replace(translate(coalesce(p_texto, ''),
    'áàâãäåéèêëíìîïóòôõöúùûüçñýÿÁÀÂÃÄÅÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝ',
    'aaaaaaeeeeiiiiooooouuuucnyyAAAAAAEEEEIIIIOOOOOUUUUCNY'), '\s+', ' ', 'g'))), '')
$$;
create index if not exists rede_chamados_cidade on interno.rede_chamados (interno.rede_ato_cidade(cidade), inicio);

/**
 * A proporção acesa do mosaico: a MESMA regra de lib/rede/mosaico.ts (proporcaoDoMosaico). Nula abaixo de 3 confirmações (agregado
 * só a partir de 3, docs/rede/PRIVACIDADE.md §8); senão confirmados ÷ max(30, meta), PARA BAIXO em passos de 10 %, entre 10 % e 100 %.
 */
create or replace function interno.rede_ato_proporcao(p_confirmados bigint, p_meta integer) returns numeric language sql immutable set search_path = interno, pg_temp as $$
  select case when p_confirmados is null or p_confirmados < 3 then null
    else round(least(10, greatest(1, floor(p_confirmados::numeric * 10 / greatest(30, coalesce(p_meta, 0)))))::numeric / 10, 1) end
$$;

-- ── 3. O chamado de antes ganha a linha dele (sem perder dado) ──────────────────────────────────────────────────────────────
-- (a) quem já estava marcado como cancelado vira situacao 'cancelado' (a coluna `cancelado` continua lá e certa);
update interno.rede_chamados set situacao = 'cancelado' where cancelado and situacao = 'confirmado';
-- (b) os chamados da Rede de hoje (o JSON no post) entram em rede_chamados com a data, o ponto e o tipo deles. O que não cabe nas
--     regras (sem data, ponto curto) fica só no JSON, como sempre esteve. A cidade fica vazia (a Rede de hoje não perguntava).
insert into interno.rede_chamados (post, inicio, ponto, tipo)
select p.id, (p.chamado ->> 'quando')::timestamptz, left(btrim(p.chamado ->> 'onde'), 140),
       case when p.chamado ->> 'tipo' in ('ato', 'assembleia', 'roda', 'mutirao', 'aula', 'outro') then p.chamado ->> 'tipo' else 'ato' end
  from interno.rede_posts p
 where p.chamado is not null and jsonb_typeof(p.chamado) = 'object'
   and coalesce(p.chamado ->> 'quando', '') ~ '^\d{4}-\d{2}-\d{2}'
   and char_length(btrim(coalesce(p.chamado ->> 'onde', ''))) >= 3
   and not exists (select 1 from interno.rede_chamados c where c.post = p.id)
on conflict (post) do nothing;

-- ── 4. O ato como a tela recebe (lib/rede/tipos-atos.ts, Ato) ───────────────────────────────────────────────────────────────

/**
 * O ato em JSON para quem lê (p_quem; nulo = visitante). Quem chama JÁ conferiu que p_quem vê o post. Nunca a lista de quem
 * confirmou: `acesos` é a proporção e `total` só sai para quem organizou (ou para quem age como a organização, interno.rede_age_como).
 */
create or replace function interno.rede_ato_json(p interno.rede_posts, c interno.rede_chamados, p_quem uuid) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  v_titulo text := coalesce(c.titulo, nullif(p.titulo, ''), left(btrim(split_part(p.texto, E'\n', 1)), 60));
  v_palavra text := coalesce(c.palavra, nullif(interno.rede_ato_palavra(v_titulo), ''));
  v_n bigint := (select count(*) from rede_vou v where v.post = p.id);
  v_meu boolean := p_quem is not null and interno.rede_age_como(p_quem, p.autor);
  f perfis;
  k rede_comunidades;
begin
  select * into f from perfis where id = p.autor;
  if p.comunidade is not null then select * into k from rede_comunidades where slug = p.comunidade; end if;
  if v_palavra is null or char_length(replace(v_palavra, ' ', '')) < 2 then v_palavra := 'ATO'; end if;
  return jsonb_build_object(
    'id', p.id,
    'titulo', coalesce(nullif(v_titulo, ''), v_palavra),
    'palavra', v_palavra,
    'comunidade', case when p.comunidade is null then null else jsonb_build_object('slug', p.comunidade, 'nome', coalesce(k.nome, p.comunidade), 'cor', null) end,
    -- Só o @nome público (ou o codinome, se o perfil é invisível); nunca o nome civil.
    'chamado_por', case when f.id is null then null
                        when coalesce(f.rede_modo = 'invisivel' or f.rede_invisivel, false) or f.rede_handle is null then interno.rede_nome(p.autor)
                        else f.rede_handle end,
    'inicio', c.inicio,
    'inicio_anterior', c.inicio_anterior,
    'onde', c.ponto,
    'cidade', coalesce(c.cidade, ''),
    'descricao', p.texto,
    'situacao', c.situacao,
    'motivo', coalesce(c.motivo, ''),
    'acesos', interno.rede_ato_proporcao(v_n, c.meta),
    'total', case when v_meu then v_n end,
    'vou_eu', p_quem is not null and exists (select 1 from rede_vou v where v.post = p.id and v.usuario = p_quem),
    'meu', v_meu,
    'respostas', interno.rede2_respostas_visiveis(p.id, p_quem),
    'link_apoio', c.link_apoio);
end $$;

/** O ato, se esta pessoa pode vê-lo (matriz interno.rede_ve: bloqueio, público, comunidade fechada, retido, apagado). */
create or replace function interno.rede_ato_achar(p_id uuid, p_quem uuid) returns interno.rede_posts
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare p rede_posts;
begin
  select * into p from rede_posts where id = p_id;
  if not found or not exists (select 1 from rede_chamados c where c.post = p_id) or not interno.rede_ve(p, p_quem)
     or (p.apagado_em is not null and p.autor is distinct from p_quem) then
    perform interno.erro('nao_encontrado');
  end if;
  return p;
end $$;

-- ── 5. Chamar um ato ────────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Chama um ato. Publica o post pelo rede_publicar de sempre (todas as conferências dele valem: membro 18+, consentimento, codinome,
 * limite, dado pessoal, comunidade, público, triagem) e, na MESMA transação, grava o chamado. Campos de p: titulo (2–60), palavra
 * (opcional; sai do título pela regra do mosaico), inicio (ISO, no futuro, até 365 dias), onde (3–140, o ponto PÚBLICO), cidade
 * (2–80), descricao (1–500, o texto do post), comunidade, publico, tipo ('ato' padrão; 'assembleia', 'roda', 'mutirao'), meta
 * (3–30000, opcional), link_apoio (só https, opcional). Devolve o Ato.
 */
create or replace function public.rede_ato_publicar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_titulo text; v_palavra text; v_inicio timestamptz; v_ponto text; v_cidade text; v_link text; v_meta integer;
  v_tipo text := coalesce(nullif(btrim(p ->> 'tipo'), ''), 'ato');
  v_post jsonb; v_tri jsonb; x rede_posts; c rede_chamados;
begin
  perform interno.aberta('comunidade');
  if p is null or jsonb_typeof(p) is distinct from 'object' then perform interno.erro('invalido:ato'); end if;
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if v_tipo not in ('ato', 'assembleia', 'roda', 'mutirao') then perform interno.erro('invalido:tipo'); end if;
  v_titulo := regexp_replace(interno.txt(p ->> 'titulo', 'titulo', 2, 60), '\s+', ' ', 'g');
  v_palavra := interno.rede_ato_palavra(coalesce(nullif(btrim(p ->> 'palavra'), ''), v_titulo));
  if v_palavra !~ '^[A-Z ]{2,14}$' or char_length(replace(v_palavra, ' ', '')) < 2 then perform interno.erro('invalido:palavra'); end if;
  begin
    v_inicio := (p ->> 'inicio')::timestamptz;
    v_meta := nullif(p ->> 'meta', '')::integer;
  exception when others then perform interno.erro('invalido:inicio');
  end;
  if v_inicio is null or v_inicio <= now() or v_inicio > now() + interval '365 days' then perform interno.erro('invalido:inicio'); end if;
  if v_meta is not null and v_meta not between 3 and 30000 then perform interno.erro('invalido:meta'); end if;
  v_ponto := regexp_replace(interno.txt(p ->> 'onde', 'onde', 3, 140), '\s+', ' ', 'g');
  v_cidade := regexp_replace(interno.txt(p ->> 'cidade', 'cidade', 2, 80), '\s+', ' ', 'g');
  v_link := nullif(btrim(coalesce(p ->> 'link_apoio', '')), '');
  if v_link is not null and (v_link !~ '^https://[^\s<>"'']{4,}$' or char_length(v_link) > 300) then perform interno.erro('invalido:link_apoio'); end if;
  -- Dado pessoal no nome, no ponto e na cidade (CPF, telefone, e-mail). O ponto PODE ter número: é o endereço público do ato.
  if interno.rede3_pub_dado_pessoal(v_titulo || ' ' || v_cidade)
     or (v_ponto || ' ' || coalesce(v_link, '')) ~ '\d{3}\.?\d{3}\.?\d{3}-?\d{2}|\(?\d{2}\)?\s?9\d{4}[-\s]?\d{4}'
     or v_ponto ~* '[a-z0-9._%+-]+@[a-z0-9-]+\.[a-z.]{2,}' then
    perform interno.erro('dado_pessoal');
  end if;
  perform interno.limite('alumia_ato_chamar', 10, 1440);

  v_post := public.rede_publicar(jsonb_strip_nulls(jsonb_build_object('tipo', 'post', 'texto', p ->> 'descricao',
    'comunidade', nullif(btrim(coalesce(p ->> 'comunidade', '')), ''), 'publico', nullif(btrim(coalesce(p ->> 'publico', '')), ''))));
  select * into x from rede_posts where id = (v_post ->> 'id')::uuid and autor = v;
  if not found then perform interno.erro('invalido:ato'); end if;

  -- A triagem também lê o nome e o ponto; um veredito mais duro que o do texto retém o post (nunca afrouxa o que o texto já reteve).
  v_tri := interno.rede_triagem(v_titulo || ' ' || v_ponto || ' ' || v_cidade, v);
  -- O JSON de antes continua sendo escrito: a Rede de hoje (flags desligadas) segue mostrando o chamado como sempre mostrou.
  update rede_posts set tipo = 'chamado', titulo = v_titulo,
         chamado = jsonb_build_object('tipo', v_tipo, 'quando', v_inicio, 'onde', v_ponto),
         oculto = oculto or (v_tri ->> 'veredito') <> 'publicar',
         retido = retido or (v_tri ->> 'veredito') = 'revisar',
         motivo = case when not (oculto or retido) and (v_tri ->> 'veredito') <> 'publicar' then coalesce(v_tri ->> 'motivo', '') else motivo end
   where id = x.id returning * into x;
  insert into rede_chamados (post, inicio, cidade, ponto, tipo, link, titulo, palavra, meta, link_apoio)
  values (x.id, v_inicio, v_cidade, v_ponto, v_tipo, null, v_titulo, v_palavra, v_meta, v_link)
  returning * into c;
  return interno.rede_ato_json(x, c, v);
end $$;

-- ── 6. Ler ──────────────────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Uma página de atos, do mais próximo no tempo para o mais longe (só os que não acabaram: começo há menos de 6 h). Filtros:
 * 'perto' (pela cidade ESCRITA em p_cidade; sem cidade, página vazia), 'seguindo' (de quem a pessoa segue, das comunidades em que
 * está ou que segue, e os que ela confirmou; pede conta). p_comunidade (opcional) restringe a uma comunidade. Visitante só vê o
 * que já é público na internet. Cursor = "<início ISO>|<id>". Devolve {itens, proximo}.
 */
create or replace function public.rede_atos(p_filtro text, p_cidade text default null, p_comunidade text default null, p_cursor text default null, p_limite integer default 20)
returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := auth.uid();
  v_lim integer := least(greatest(coalesce(p_limite, 20), 1), 40);
  v_cidade text := interno.rede_ato_cidade(left(p_cidade, 80));
  v_com text := nullif(btrim(coalesce(p_comunidade, '')), '');
  v_c_inicio timestamptz; v_c_id uuid;
  v_ids uuid[]; v_itens jsonb; u rede_chamados;
begin
  perform interno.aberta('comunidade');
  if v is not null and exists (select 1 from perfis where id = v and suspenso) then perform interno.erro('conta_suspensa'); end if;
  if p_filtro is null or p_filtro not in ('perto', 'seguindo') then perform interno.erro('invalido:filtro'); end if;
  if p_filtro = 'seguindo' and v is null and v_com is null then perform interno.erro('entre_primeiro'); end if;
  if v_com is not null and v_com !~ '^[a-z0-9-]{2,60}$' then perform interno.erro('invalido:comunidade'); end if;
  perform interno.limite('alumia_atos_ler', 300, 60);
  if nullif(p_cursor, '') is not null then
    begin
      v_c_inicio := split_part(p_cursor, '|', 1)::timestamptz;
      v_c_id := split_part(p_cursor, '|', 2)::uuid;
    exception when others then perform interno.erro('invalido:cursor');
    end;
  end if;
  if p_filtro = 'perto' and v_cidade is null and v_com is null then return jsonb_build_object('itens', '[]'::jsonb, 'proximo', null); end if;

  select array_agg(z.post order by z.inicio, z.post) into v_ids from (
    select c.post, c.inicio
      from rede_chamados c join rede_posts p on p.id = c.post
     where c.inicio > now() - interval '6 hours'
       and (v_c_inicio is null or (c.inicio, c.post) > (v_c_inicio, v_c_id))
       and (v_com is null or p.comunidade = v_com)
       and (p_filtro <> 'perto' or v_com is not null or interno.rede_ato_cidade(c.cidade) = v_cidade)
       and (p_filtro <> 'seguindo' or v_com is not null or p.autor = v
            or exists (select 1 from rede_seguindo s where s.quem = v and s.segue = p.autor and not s.pendente)
            or (p.comunidade is not null and (interno.rede2_na_comunidade(p.comunidade, v)
                or exists (select 1 from rede_comunidades_seguidas g where g.usuario = v and g.comunidade = p.comunidade)))
            or exists (select 1 from rede_vou o where o.post = p.id and o.usuario = v))
       and p.apagado_em is null
       and interno.rede_ve(p, v)
       and not interno.rede_silenciado(p, v)
     order by c.inicio, c.post
     limit v_lim + 1) z;

  select coalesce(jsonb_agg(interno.rede_ato_json(p, c, v) order by c.inicio, c.post), '[]'::jsonb) into v_itens
    from rede_chamados c join rede_posts p on p.id = c.post
   where c.post = any (coalesce(v_ids[1:v_lim], '{}'::uuid[]));
  if coalesce(cardinality(v_ids), 0) > v_lim then
    select * into u from rede_chamados where post = v_ids[v_lim];
    return jsonb_build_object('itens', v_itens, 'proximo', to_char(u.inicio at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') || '|' || u.post::text);
  end if;
  return jsonb_build_object('itens', v_itens, 'proximo', null);
end $$;

/** Um ato (a página do ato). Visitante só se o post é público na internet. */
create or replace function public.rede_ato(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); p rede_posts; c rede_chamados;
begin
  perform interno.aberta('comunidade');
  if v is not null and exists (select 1 from perfis where id = v and suspenso) then perform interno.erro('conta_suspensa'); end if;
  perform interno.limite('alumia_atos_ler', 300, 60);
  p := interno.rede_ato_achar(p_id, v);
  select * into c from rede_chamados where post = p_id;
  return interno.rede_ato_json(p, c, v);
end $$;

/**
 * O próximo ato da pessoa (a faixa PRÓXIMO ATO): o primeiro que ela confirmou e não foi cancelado; senão, o primeiro de quem ela
 * segue ou das comunidades dela. Nulo para visitante e quando não há.
 */
create or replace function public.rede_ato_proximo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); p rede_posts; c rede_chamados;
begin
  if v is null or not interno.rede2_membro(v) then return null; end if;
  perform interno.aberta('comunidade');
  perform interno.limite('alumia_atos_ler', 300, 60);
  select pp.* into p from rede_chamados cc join rede_posts pp on pp.id = cc.post
   where cc.situacao <> 'cancelado' and cc.inicio > now() - interval '2 hours' and pp.apagado_em is null
     and exists (select 1 from rede_vou o where o.post = pp.id and o.usuario = v)
     and interno.rede_ve(pp, v)
   order by cc.inicio, cc.post limit 1;
  if not found then
    select pp.* into p from rede_chamados cc join rede_posts pp on pp.id = cc.post
     where cc.situacao <> 'cancelado' and cc.inicio > now() and pp.apagado_em is null
       and (pp.autor = v or exists (select 1 from rede_seguindo s where s.quem = v and s.segue = pp.autor and not s.pendente)
            or (pp.comunidade is not null and (interno.rede2_na_comunidade(pp.comunidade, v)
                or exists (select 1 from rede_comunidades_seguidas g where g.usuario = v and g.comunidade = pp.comunidade))))
       and interno.rede_ve(pp, v) and not interno.rede_silenciado(pp, v)
     order by cc.inicio, cc.post limit 1;
    if not found then return null; end if;
  end if;
  select * into c from rede_chamados where post = p.id;
  return interno.rede_ato_json(p, c, v);
end $$;

-- ── 7. "Você vai" ───────────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Confirma (p_sim true) ou desfaz. Só membro da Rede (18+, consentimento) que vê o ato; ato cancelado ou que já passou não recebe
 * confirmação nova (desfazer sempre pode). Devolve {vou_eu, acesos, total}: a proporção nova e, só para quem organizou, o total.
 */
create or replace function public.rede_ato_vou(p_id uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); p rede_posts; c rede_chamados; v_n bigint;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede2_limite('reagir');
  p := interno.rede_ato_achar(p_id, v);
  select * into c from rede_chamados where post = p_id for update;
  if coalesce(p_sim, true) then
    if c.situacao = 'cancelado' then perform interno.erro('ato_cancelado'); end if;
    if c.inicio < now() - interval '6 hours' then perform interno.erro('ato_passou'); end if;
    if p.oculto or p.retido or p.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
    insert into rede_vou (post, usuario) values (p_id, v) on conflict do nothing;
  else
    delete from rede_vou where post = p_id and usuario = v;
  end if;
  select count(*) into v_n from rede_vou where post = p_id;
  return jsonb_build_object('vou_eu', coalesce(p_sim, true), 'acesos', interno.rede_ato_proporcao(v_n, c.meta),
    'total', case when interno.rede_age_como(v, p.autor) then v_n end);
end $$;

-- ── 8. Adiar, cancelar, confirmar de novo ───────────────────────────────────────────────────────────────────────────────────

/**
 * Só quem organizou (ou quem age como a organização). 'adiado' pede p_inicio (no futuro, até 365 dias, diferente da data atual) e
 * guarda a data de ANTES ("era 12/11": a primeira, se adiar duas vezes); 'cancelado' e 'confirmado' mantêm a data. p_motivo até 140
 * (sem dado pessoal). Quando muda alguma coisa, avisa SÓ quem confirmou (tipo 'chamado' nos avisos; quem desligou "ato_mudou" no
 * site não recebe), com um texto sem o nome de ninguém. Devolve o Ato.
 */
create or replace function public.rede_ato_mudar(p_id uuid, p_situacao text, p_inicio timestamptz default null, p_motivo text default '')
returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); p rede_posts; c rede_chamados; d rede_chamados;
  v_motivo text := regexp_replace(btrim(coalesce(p_motivo, '')), '\s+', ' ', 'g');
  v_texto text; r record;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  p := interno.rede_ato_achar(p_id, v);
  if not interno.rede_age_como(v, p.autor) then perform interno.erro('so_quem_organizou'); end if;
  if p_situacao is null or p_situacao not in ('confirmado', 'adiado', 'cancelado') then perform interno.erro('invalido:situacao'); end if;
  if char_length(v_motivo) > 140 then perform interno.erro('invalido:motivo'); end if;
  if interno.rede3_pub_dado_pessoal(v_motivo) then perform interno.erro('dado_pessoal'); end if;
  perform interno.limite('alumia_ato_mudar', 20, 60);
  select * into c from rede_chamados where post = p_id for update;

  if p_situacao = 'adiado' then
    if p_inicio is null or p_inicio <= now() or p_inicio > now() + interval '365 days' or p_inicio = c.inicio then perform interno.erro('invalido:inicio'); end if;
    update rede_chamados set situacao = 'adiado', inicio_anterior = coalesce(inicio_anterior, inicio), inicio = p_inicio,
           cancelado = false, motivo = v_motivo, mudado_em = now()
     where post = p_id returning * into d;
    -- Se a data nova é a mesma "de antes", não sobra "era …" para mostrar.
    if d.inicio_anterior = d.inicio then update rede_chamados set inicio_anterior = null where post = p_id returning * into d; end if;
    update rede_posts set chamado = jsonb_set(coalesce(chamado, '{}'::jsonb), '{quando}', to_jsonb(p_inicio)) where id = p_id;
  elsif p_situacao = 'cancelado' then
    update rede_chamados set situacao = 'cancelado', cancelado = true, motivo = v_motivo, mudado_em = now() where post = p_id returning * into d;
  else
    update rede_chamados set situacao = 'confirmado', cancelado = false, motivo = '', mudado_em = now() where post = p_id returning * into d;
  end if;

  if d.situacao is distinct from c.situacao or d.inicio is distinct from c.inicio then
    v_texto := case d.situacao when 'adiado' then 'Um ato que você confirmou mudou de data.'
                               when 'cancelado' then 'Um ato que você confirmou foi cancelado.'
                               else 'Um ato que você confirmou está confirmado de novo.' end;
    for r in select o.usuario from rede_vou o where o.post = p_id and o.usuario <> p.autor and o.usuario <> v loop
      if interno.rede2_membro(r.usuario) and interno.rede3_aviso_pref(r.usuario, 'ato_mudou', 'site') and interno.rede_ve(p, r.usuario) then
        perform interno.rede3_aviso_criar(r.usuario, 'chamado', p_id, null, null, v_texto);
      end if;
    end loop;
  end if;
  select * into p from rede_posts where id = p_id;
  return interno.rede_ato_json(p, d, v);
end $$;

-- ── 9. Permissões ───────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.rede_ato_palavra(text), interno.rede_ato_cidade(text), interno.rede_ato_proporcao(bigint, integer),
  interno.rede_ato_json(interno.rede_posts, interno.rede_chamados, uuid), interno.rede_ato_achar(uuid, uuid) from public;
revoke all on function public.rede_ato_publicar(jsonb), public.rede_atos(text, text, text, text, integer), public.rede_ato(uuid),
  public.rede_ato_proximo(), public.rede_ato_vou(uuid, boolean), public.rede_ato_mudar(uuid, text, timestamptz, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_ato_palavra(text), interno.rede_ato_cidade(text), interno.rede_ato_proporcao(bigint, integer),
      interno.rede_ato_json(interno.rede_posts, interno.rede_chamados, uuid), interno.rede_ato_achar(uuid, uuid) from anon, authenticated;
    revoke all on function public.rede_ato_publicar(jsonb), public.rede_ato_vou(uuid, boolean), public.rede_ato_mudar(uuid, text, timestamptz, text) from anon;
    -- Ler: visitante também (a função só devolve o que é público na internet para quem não entrou).
    grant execute on function public.rede_atos(text, text, text, text, integer), public.rede_ato(uuid), public.rede_ato_proximo() to anon, authenticated, service_role;
    grant execute on function public.rede_ato_publicar(jsonb), public.rede_ato_vou(uuid, boolean), public.rede_ato_mudar(uuid, text, timestamptz, text) to authenticated, service_role;
  end if;
end $$;

-- ═══════════════════════════ fim da F2 (atos, back-end mínimo) ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F3 · o back-end mínimo das telas novas (09/11/2026) ═══════════════════════════
-- docs/plano-2026-11/PLANO-ALUMIA.md, seções 5 (F3), 6 e 8 (F3). O que as telas da F3 (comunidade, conversa e "Comunidades
-- ativas") precisam para funcionar de verdade, e nada além:
--   1. "N posts esta semana" na página da comunidade (rede_alumia_com_pagina): o que rede_com_pagina já devolve (com o post
--      "Fixado pela moderação", que só a moderação fixa por rede_com_fixar) + a contagem agregada dos últimos 7 dias.
--   2. "Comunidades ativas" da coluna (rede_alumia_ativas): as com mais posts na semana, sem algoritmo e sem patrocínio.
--   3. "ajudou a autora" (rede_alumia_ajudou): SÓ quem abriu a conversa marca (a moderação não; a regra antiga de "resolveu" da
--      dúvida, rede_conv_aceitar, continua como está para a rede de hoje). Uma por conversa, em tabela própria.
--   4. Reações com emoji (rede_alumia_reagir, rede_alumia_reacoes): lista FECHADA de 8, só o total por emoji, nunca quem.
--   5. A conversa da tela nova (rede_alumia_conversa): rede_conv_arvore + a marca "ajudou", quem pode marcar, os pronomes de
--      quem abriu (para o selo não errar o gênero de ninguém) e as reações do post aberto.
--
-- Regras (PLANO-ALUMIA §5): tabelas novas em interno com RLS e sem nenhuma permissão para anon/authenticated; acesso só pelas
-- funções security definer abaixo (search_path = interno, pg_temp), que conferem quem chama, bloqueio, visibilidade
-- (interno.rede_ve, a mesma matriz de toda a Rede) e limite de uso (interno.rede2_limite / interno.limite).
--
-- Leis (conferidas no texto, leis-do-brasil): LGPD (Lei 13.709/2018) art. 5º, II e art. 11 — opinião política e filiação são
-- dado pessoal sensível. Por isso: nenhuma função devolve quem reagiu, quem escreveu na semana ou quem marcou; todo total de
-- pessoas ou de posts só aparece a partir de 3 (abaixo, nulo = "poucas"/"poucos", docs/rede/PRIVACIDADE.md §8); art. 6º, III
-- (necessidade): a reação guarda só post, pessoa, emoji e data, e some com a conta (cascata) ou com o post; art. 46 (segurança):
-- RLS ligada e nenhuma permissão direta. ECA (Lei 8.069/1990) e ECA Digital: a Rede segue só para 18+ confirmado
-- (interno.rede2_membro), e só membro reage ou marca.
--
-- Idempotente: pode rodar duas vezes sem estrago (scripts/testar-alumia-f3-banco.mjs roda duas vezes no banco local). NÃO está
-- no install.sql: o integrador cola no fim, na ordem F0→F9. NÃO rodar em produção sem o Jonathan.

-- ── 1. Tabelas ────────────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Reação com emoji: uma linha por (post, pessoa, emoji). A lista fechada é a mesma de lib/rede/tipos-conversa.ts (REACOES), na
 * mesma ordem: ✊ ❤️ 🔥 👏 🤔 😢 😡 📚. Nada de emoji livre (PLANO-ALUMIA §6.3 e §12).
 */
create table if not exists interno.rede_reacoes_emoji (
  post uuid not null references interno.rede_posts (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  emoji text not null check (emoji in ('✊', '❤️', '🔥', '👏', '🤔', '😢', '😡', '📚')),
  criado_em timestamptz not null default now(),
  primary key (post, usuario, emoji)
);
create index if not exists rede_reacoes_emoji_usuario on interno.rede_reacoes_emoji (usuario);
alter table interno.rede_reacoes_emoji enable row level security;

/** "ajudou a autora": a resposta que quem abriu a conversa marcou. Uma por conversa (raiz). */
create table if not exists interno.rede_ajudou (
  raiz uuid primary key references interno.rede_posts (id) on delete cascade,
  resposta uuid not null references interno.rede_posts (id) on delete cascade,
  marcado_em timestamptz not null default now()
);
create index if not exists rede_ajudou_resposta on interno.rede_ajudou (resposta);
alter table interno.rede_ajudou enable row level security;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_reacoes_emoji, interno.rede_ajudou from anon, authenticated;
  end if;
end $$;

-- ── 2. Contas internas ────────────────────────────────────────────────────────────────────────────────────────────────────

/** A ordem da lista fechada (a tela mostra nesta ordem). */
create or replace function interno.rede_alumia_emojis() returns text[] language sql immutable as $$
  select array['✊', '❤️', '🔥', '👏', '🤔', '😢', '😡', '📚']::text[]
$$;

/** Total que pode sair: nulo abaixo de 3 (PLANO-ALUMIA §6.1). */
create or replace function interno.rede_alumia_agregado(p_n integer) returns integer language sql immutable as $$
  select case when p_n >= 3 then p_n end
$$;

/**
 * As reações de um post como a tela mostra: [{emoji, total, minha}] na ordem da lista, só os emojis com alguém (ou a minha).
 * total nulo abaixo de 3. NUNCA quem reagiu, nem para quem escreveu o post. Quem chama esta conta já conferiu que p_quem vê o post.
 */
create or replace function interno.rede_alumia_reacoes_de(p_post uuid, p_quem uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('emoji', z.emoji, 'total', interno.rede_alumia_agregado(z.n), 'minha', z.minha)
                            order by array_position(interno.rede_alumia_emojis(), z.emoji)), '[]'::jsonb)
  from (
    select r.emoji, count(*)::integer as n, bool_or(p_quem is not null and r.usuario = p_quem) as minha
    from rede_reacoes_emoji r where r.post = p_post group by r.emoji) z
$$;

/** Posts da comunidade nos últimos 7 dias (sem removido, retido nem apagado). Só a conta; quem decide se sai é quem chama. */
create or replace function interno.rede_alumia_posts_7d(p_slug text) returns integer language sql stable security definer set search_path = interno, pg_temp as $$
  select count(*)::integer from rede_posts p
  where p.comunidade = p_slug and p.criado_em > now() - interval '7 days' and not p.oculto and not p.retido and p.apagado_em is null
$$;

revoke all on function interno.rede_alumia_emojis(), interno.rede_alumia_agregado(integer), interno.rede_alumia_reacoes_de(uuid, uuid),
  interno.rede_alumia_posts_7d(text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_alumia_emojis(), interno.rede_alumia_agregado(integer), interno.rede_alumia_reacoes_de(uuid, uuid),
      interno.rede_alumia_posts_7d(text) from anon, authenticated;
  end if;
end $$;

-- ── 3. Comunidade: "N posts esta semana" e "Comunidades ativas" ───────────────────────────────────────────────────────────

/**
 * A página da comunidade na tela nova: tudo o que rede_com_pagina devolve (que já confere a comunidade fechada, a amostra de
 * visitante e os fixados que a pessoa pode ver) + posts_7d, nulo abaixo de 3. Nunca quantos membros nem quem escreveu.
 */
create or replace function public.rede_alumia_com_pagina(p_slug text) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v_base jsonb; c rede_comunidades;
begin
  perform interno.limite('rede2_ler', 600, 60);
  v_base := public.rede_com_pagina(p_slug);
  c := interno.rede3_com_achar(p_slug);
  return v_base || jsonb_build_object('posts_7d', interno.rede_alumia_agregado(interno.rede_alumia_posts_7d(c.slug)));
end $$;

/**
 * "Comunidades ativas" (prancha computador-inicio): até p_quantas (1 a 10, padrão 4) com mais posts nos últimos 7 dias; no empate,
 * o nome. Entra só comunidade que a pessoa poderia abrir e com 3 posts ou mais na semana (abaixo disso, a conta poderia apontar
 * quem escreveu). Visitante só vê as disciplinas (das lutas e do Instituto, visitante vê só a amostra, sem contagem: T32).
 */
create or replace function public.rede_alumia_ativas(p_quantas integer default 4) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_n integer := least(greatest(coalesce(p_quantas, 4), 1), 10);
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  if v is not null and exists (select 1 from perfis f where f.id = v and f.suspenso) then perform interno.erro('conta_suspensa'); end if;
  return jsonb_build_object('regra', 'posts_7d', 'itens', (
    select coalesce(jsonb_agg(jsonb_build_object('slug', x.slug, 'nome', x.nome, 'descricao', x.descricao, 'categoria', x.categoria,
             'tipo', x.tipo, 'icone', x.icone, 'cor', x.cor, 'situacao', interno.rede3_com_situacao(x.slug, v), 'posts_7d', x.n)
             order by x.n desc, x.nome), '[]'::jsonb)
    from (
      select c.*, interno.rede_alumia_posts_7d(c.slug) as n
      from rede_comunidades c
      where c.slug not like 'fechado-%'
        and (c.tipo <> 'fechada' or interno.rede2_na_comunidade(c.slug, v))
        and (v is not null or c.categoria = 'disciplinas')
      order by n desc, c.nome
      limit v_n) x
    where x.n >= 3));
end $$;

-- ── 4. Reações com emoji ──────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Reage (p_sim = true) ou tira a reação (false) com um emoji da lista fechada. Só membro da Rede (18+ e consentimento), que vê o
 * post, sem bloqueio entre as duas pessoas (rede_ve já recusa nos dois sentidos) e que não foi banido da comunidade do post.
 * Devolve {reacoes} do post (totais, nunca quem).
 */
create or replace function public.rede_alumia_reagir(p_post uuid, p_emoji text, p_sim boolean default true) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  if p_emoji is null or not (p_emoji = any (interno.rede_alumia_emojis())) then perform interno.erro('invalido:emoji'); end if;
  select * into x from rede_posts where id = p_post;
  if not found or not interno.rede_ve(x, v) or x.oculto or x.retido or x.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
  if interno.rede_bloqueado(v, x.autor) then perform interno.erro('nao_encontrado'); end if;
  if x.comunidade is not null and interno.rede3_com_situacao(x.comunidade, v) = 'banido' then perform interno.erro('sem_permissao'); end if;
  perform interno.rede2_limite('reagir');
  if coalesce(p_sim, true) then
    insert into rede_reacoes_emoji (post, usuario, emoji) values (x.id, v, p_emoji) on conflict do nothing;
  else
    delete from rede_reacoes_emoji where post = x.id and usuario = v and emoji = p_emoji;
  end if;
  return jsonb_build_object('reacoes', interno.rede_alumia_reacoes_de(x.id, v));
end $$;

/**
 * As reações de vários posts de uma vez (até 50): {itens: [{post, reacoes}]}. Post que a pessoa não pode ver não volta (nem
 * o id). Visitante só lê o que é aberto à internet (a mesma matriz).
 */
create or replace function public.rede_alumia_reacoes(p_posts uuid[]) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  if coalesce(cardinality(p_posts), 0) > 50 then perform interno.erro('invalido:posts'); end if;
  if v is not null and exists (select 1 from perfis f where f.id = v and f.suspenso) then perform interno.erro('conta_suspensa'); end if;
  return jsonb_build_object('itens', (
    select coalesce(jsonb_agg(jsonb_build_object('post', x.id, 'reacoes', interno.rede_alumia_reacoes_de(x.id, v))), '[]'::jsonb)
    from rede_posts x
    where x.id = any (coalesce(p_posts, '{}'::uuid[])) and interno.rede_ve(x, v) and not x.oculto and not x.retido and x.apagado_em is null));
end $$;

-- ── 5. "ajudou a autora" ──────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Marca (p_sim = true) ou desmarca a resposta que ajudou quem abriu a conversa. SÓ quem abriu a conversa marca: nem a moderação
 * (a marca diz o que ajudou a autora, e só ela sabe). A resposta tem de ser da conversa, visível para ela e de outra pessoa. Uma
 * por conversa: marcar outra troca a marca. Avisa quem escreveu a resposta (sem avisar se há bloqueio). Devolve {ajudou}.
 */
create or replace function public.rede_alumia_ajudou(p_resposta uuid, p_sim boolean default true) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r rede_posts; v_raiz rede_posts; v_antes uuid;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  select * into r from rede_posts where id = p_resposta;
  if not found or r.resposta_a is null or not interno.rede_ve(r, v) or r.oculto or r.retido or r.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
  v_raiz := interno.rede3_conv_raiz(r);
  if v_raiz.id is null or not interno.rede_ve(v_raiz, v) then perform interno.erro('nao_encontrado'); end if;
  if v_raiz.autor is distinct from v then perform interno.erro('sem_permissao'); end if;
  if r.autor = v then perform interno.erro('invalido:propria'); end if;
  perform interno.rede2_limite('reagir');
  select resposta into v_antes from rede_ajudou where rede_ajudou.raiz = v_raiz.id;
  if coalesce(p_sim, true) then
    insert into rede_ajudou (raiz, resposta) values (v_raiz.id, r.id)
    on conflict (raiz) do update set resposta = excluded.resposta, marcado_em = now();
    -- Na dúvida, a marca da autora também é a "resolveu" da rede de hoje (que a autora já podia marcar): as duas telas concordam.
    if v_raiz.tipo = 'duvida' then update rede_posts set aceita = r.id where id = v_raiz.id; end if;
    if v_antes is distinct from r.id and r.autor is not null and not interno.rede_bloqueado(v, r.autor) then
      perform interno.avisar_em(r.autor, format('Sua resposta ajudou quem abriu a conversa “%s” na Alumia.', left(coalesce(v_raiz.titulo, v_raiz.texto), 80)), 'rede');
    end if;
    return jsonb_build_object('ajudou', r.id);
  end if;
  delete from rede_ajudou where rede_ajudou.raiz = v_raiz.id and resposta = r.id;
  if v_raiz.tipo = 'duvida' and v_raiz.aceita = r.id then update rede_posts set aceita = null where id = v_raiz.id; end if;
  return jsonb_build_object('ajudou', coalesce((select resposta from rede_ajudou where rede_ajudou.raiz = v_raiz.id),
    (select aceita from rede_posts where id = v_raiz.id and tipo = 'duvida')));
end $$;

-- ── 6. A conversa da tela nova ────────────────────────────────────────────────────────────────────────────────────────────

/**
 * rede_conv_arvore (a mesma matriz, ordem e limite) + o que a tela nova usa: ajudou (a resposta marcada, só se quem lê pode vê-la;
 * na dúvida sem marca nova, vale a "resolveu" de hoje), pode_ajudou (só quem abriu a conversa), pronomes_da_raiz (o que a pessoa
 * escreveu no perfil, quando a coluna da F4 existir; senão nulo) e as reações do post aberto (post.reacoes).
 */
create or replace function public.rede_alumia_conversa(p_id uuid, p_ordem text default 'antigas') returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_arv jsonb; v_raiz rede_posts; v_ajudou uuid; v_pron text; f perfis;
begin
  v_arv := public.rede_conv_arvore(p_id, p_ordem);
  select * into v_raiz from rede_posts where id = (v_arv ->> 'raiz')::uuid;
  select a.resposta into v_ajudou from rede_ajudou a join rede_posts r on r.id = a.resposta
  where a.raiz = v_raiz.id and interno.rede_ve(r, v) and not r.oculto and not r.retido and r.apagado_em is null;
  if v_ajudou is null and v_raiz.tipo = 'duvida' then v_ajudou := v_raiz.aceita; end if;
  select * into f from perfis where id = v_raiz.autor;
  -- Pronomes: só de perfil visível (o invisível não mostra nada de si). A coluna é da F4; to_jsonb lê sem quebrar antes dela.
  if f.id is not null and not coalesce(f.rede_modo = 'invisivel' or f.rede_invisivel, false) then
    v_pron := nullif(btrim(left(to_jsonb(f) ->> 'rede_pronomes', 30)), '');
  end if;
  return jsonb_set(v_arv, '{post,reacoes}', interno.rede_alumia_reacoes_de(p_id, v))
    || jsonb_build_object(
      'ajudou', v_ajudou,
      'pode_ajudou', v is not null and v_raiz.autor = v and interno.rede2_membro(v),
      'pronomes_da_raiz', v_pron);
end $$;

-- ── 7. Permissões ─────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function public.rede_alumia_com_pagina(text), public.rede_alumia_ativas(integer), public.rede_alumia_reagir(uuid, text, boolean),
  public.rede_alumia_reacoes(uuid[]), public.rede_alumia_ajudou(uuid, boolean), public.rede_alumia_conversa(uuid, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.rede_alumia_com_pagina(text), public.rede_alumia_ativas(integer), public.rede_alumia_reagir(uuid, text, boolean),
      public.rede_alumia_reacoes(uuid[]), public.rede_alumia_ajudou(uuid, boolean), public.rede_alumia_conversa(uuid, text) from anon, authenticated;
    -- Leitura: visitante lê o que a matriz deixa (disciplinas e posts abertos à internet). Escrita: só quem entrou.
    grant execute on function public.rede_alumia_com_pagina(text), public.rede_alumia_ativas(integer), public.rede_alumia_reacoes(uuid[]),
      public.rede_alumia_conversa(uuid, text) to anon, authenticated, service_role;
    grant execute on function public.rede_alumia_reagir(uuid, text, boolean), public.rede_alumia_ajudou(uuid, boolean) to authenticated, service_role;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F4 · organizações e perfis (09/11/2026) ═══════════════════════════
-- docs/plano-2026-11/PLANO-ALUMIA.md §4.3, §5 (F4), §6, §7 e §8 (F4). O back-end MÍNIMO para cada função das telas da F4
-- funcionar: conta de organização (criada sem senha por lib/rede/contas-extra.ts), pedido do selo e a fila no painel, gestores
-- (o vínculo não aparece para ninguém), "Como votamos", consultas à base com voto secreto (só quem é de um núcleo da organização
-- vota; quórum; simples ou ranqueada por segundo turno instantâneo), plenárias com fila por ordem de chegada que não reordena,
-- núcleos da organização, o sininho e os extras do perfil de pessoa (status, pronomes, campos).
--
-- Idempotente: pode rodar duas vezes (scripts/testar-alumia-f4.mjs roda duas vezes no banco local). Depende da F0
-- (20261109-alumia-f0-contrato.sql: rede_identidades e rede_age_como). NÃO está no install.sql (o integrador cola depois da F0) e
-- NÃO rodar em produção sem o Jonathan.
--
-- Regras (§5): tudo em `interno` com RLS ligada e nenhuma permissão para anon/authenticated nas tabelas; acesso só por função
-- security definer com search_path = interno, pg_temp; cada função confere quem chama (membro da Rede, bloqueio, gestor,
-- coordenação) e o limite de uso (interno.limite).
--
-- Leis (conferidas no texto, leis-do-brasil):
--  - LGPD (Lei 13.709/2018) art. 5º, II e art. 11: filiação a organização política e opinião política são dado pessoal SENSÍVEL.
--    Por isso: nenhuma função devolve lista de quem segue, liga o sininho, votou, é de um núcleo ou está numa plenária; contagens
--    de pessoas só a partir de 3 (nulo abaixo); o voto da consulta é secreto POR CONSTRUÇÃO (quem votou e o que votou ficam em
--    tabelas separadas, sem chave comum nem hora); o vínculo organização↔gestor nunca sai do banco (só "eu gerencio", para mim).
--  - LGPD art. 6º, III (necessidade): o pedido do selo guarda só documento PÚBLICO da organização (CNPJ, registro do partido,
--    diploma, ata), nunca CPF/RG de pessoa, e não guarda quem pediu; datas de vínculo guardam só o dia.
--  - LGPD art. 46 (segurança): RLS ligada, nenhuma permissão direta; limites de uso em toda escrita.
--  - ECA (Lei 8.069/1990) e ECA Digital (Lei 15.211/2025) art. 9º § 1º: a Alumia é só para maiores; toda ação exige ser membro da
--    Rede (rede_18 + consentimento), e o pedido do selo exige a declaração de 18 anos de quem cuida da conta.

-- ── 1. Tabelas ────────────────────────────────────────────────────────────────────────────────────────────────────────────

-- A organização é um perfil (conta extra sem senha, em auth.users) com estes dados a mais.
create table if not exists interno.rede_orgs (
  perfil uuid primary key references interno.perfis (id) on delete cascade,
  tipo text not null check (tipo in ('partido', 'mandato', 'sindicato', 'movimento', 'coletivo', 'gremio', 'dce', 'outro')),
  cidade text not null default '' check (char_length(cidade) <= 60),
  palavra text not null default 'ORG' check (palavra ~ '^[A-Z ]{2,14}$'),
  -- O documento PÚBLICO conferido (tipo e número/link). Só aparece no perfil depois do selo.
  documento_tipo text not null default '' check (char_length(documento_tipo) <= 60),
  documento_publico text not null default '' check (char_length(documento_publico) <= 200),
  verificada_em timestamptz,
  verificada_por uuid references interno.perfis (id) on delete set null,
  criada_em date not null default current_date
);
alter table interno.rede_orgs enable row level security;

-- Quem age como a organização. NUNCA volta em função nenhuma a outra pessoa (só o "gerencio" de quem pergunta sobre si).
create table if not exists interno.rede_org_gestores (
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  gestor uuid not null references interno.perfis (id) on delete cascade,
  papel text not null default 'gestor' check (papel in ('dono', 'gestor')),
  desde date not null default current_date,
  primary key (org, gestor),
  check (org <> gestor)
);
create index if not exists rede_org_gestores_gestor on interno.rede_org_gestores (gestor);
alter table interno.rede_org_gestores enable row level security;

-- A fila do selo. Não guarda quem pediu (a organização é quem pede).
create table if not exists interno.rede_org_pedidos (
  id uuid primary key default gen_random_uuid(),
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  documento_tipo text not null check (char_length(btrim(documento_tipo)) between 2 and 60),
  documento text not null check (char_length(btrim(documento)) between 2 and 200),
  sobre text not null check (char_length(btrim(sobre)) between 2 and 280),
  situacao text not null default 'esperando' check (situacao in ('esperando', 'aceito', 'recusado')),
  motivo text not null default '' check (char_length(motivo) <= 500),
  criado_em timestamptz not null default now(),
  decidido_em timestamptz,
  decidido_por uuid references interno.perfis (id) on delete set null
);
create unique index if not exists rede_org_pedidos_um_esperando on interno.rede_org_pedidos (org) where situacao = 'esperando';
alter table interno.rede_org_pedidos enable row level security;

-- "Como votamos": a prestação de contas, sempre com a fonte pública.
create table if not exists interno.rede_org_votacoes (
  id uuid primary key default gen_random_uuid(),
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  data date not null,
  projeto text not null check (char_length(btrim(projeto)) between 2 and 200),
  voto text not null check (voto in ('sim', 'nao', 'abstencao', 'obstrucao', 'ausente')),
  porque text not null default '' check (char_length(porque) <= 500),
  resultado text not null default '' check (char_length(resultado) <= 120),
  fonte text not null check (fonte ~ '^https?://[^\s]{3,}$' and char_length(fonte) <= 500),
  criado_em timestamptz not null default now()
);
create index if not exists rede_org_votacoes_org on interno.rede_org_votacoes (org, data desc);
alter table interno.rede_org_votacoes enable row level security;

-- Núcleos da organização: os núcleos de sempre, com o dono-organização, quando se encontram e a cor.
alter table interno.rede_nucleos add column if not exists org uuid;
alter table interno.rede_nucleos add column if not exists org_quando text not null default '';
alter table interno.rede_nucleos add column if not exists org_cor smallint not null default 1;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_nucleos'::regclass and conname = 'rede_nucleos_org_fk') then
    alter table interno.rede_nucleos add constraint rede_nucleos_org_fk foreign key (org) references interno.rede_orgs (perfil) on delete cascade;
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_nucleos'::regclass and conname = 'rede_nucleos_org_quando') then
    alter table interno.rede_nucleos add constraint rede_nucleos_org_quando check (char_length(org_quando) <= 60);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.rede_nucleos'::regclass and conname = 'rede_nucleos_org_cor') then
    alter table interno.rede_nucleos add constraint rede_nucleos_org_cor check (org_cor between 1 and 5);
  end if;
end $$;
create index if not exists rede_nucleos_org on interno.rede_nucleos (org) where org is not null;

-- Pedidos para entrar num núcleo da organização (só a mediação do núcleo e os gestores veem).
create table if not exists interno.rede_org_nucleo_pedidos (
  nucleo uuid not null references interno.rede_nucleos (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  criado_em date not null default current_date,
  primary key (nucleo, usuario)
);
alter table interno.rede_org_nucleo_pedidos enable row level security;

-- Consultas à base.
create table if not exists interno.rede_consultas (
  id uuid primary key default gen_random_uuid(),
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  -- Os núcleos que votam (vazio = todos os núcleos da organização).
  nucleos uuid[] not null default '{}',
  pergunta text not null check (char_length(btrim(pergunta)) between 5 and 280),
  metodo text not null check (metodo in ('simples', 'ranqueada')),
  quorum integer check (quorum is null or quorum between 3 and 1000000),
  prazo timestamptz not null,
  compromisso text not null check (char_length(btrim(compromisso)) between 10 and 500),
  criado_em timestamptz not null default now()
);
create index if not exists rede_consultas_org on interno.rede_consultas (org, prazo desc);
alter table interno.rede_consultas enable row level security;

create table if not exists interno.rede_consulta_opcoes (
  id uuid primary key default gen_random_uuid(),
  consulta uuid not null references interno.rede_consultas (id) on delete cascade,
  ordem smallint not null,
  texto text not null check (char_length(btrim(texto)) between 1 and 120),
  unique (consulta, ordem)
);
alter table interno.rede_consulta_opcoes enable row level security;

-- Voto secreto por construção: QUEM votou (para não votar duas vezes) e O QUE foi votado (a cédula) ficam em tabelas separadas,
-- sem chave comum e sem hora. A cédula tem um id aleatório; nada nela aponta para a pessoa.
create table if not exists interno.rede_consulta_votantes (
  consulta uuid not null references interno.rede_consultas (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  primary key (consulta, usuario)
);
alter table interno.rede_consulta_votantes enable row level security;
create table if not exists interno.rede_consulta_cedulas (
  id uuid primary key default gen_random_uuid(),
  consulta uuid not null references interno.rede_consultas (id) on delete cascade,
  ranking uuid[] not null check (cardinality(ranking) between 1 and 8)
);
create index if not exists rede_consulta_cedulas_consulta on interno.rede_consulta_cedulas (consulta);
alter table interno.rede_consulta_cedulas enable row level security;

-- Plenárias e a fila de perguntas (ordem de chegada: `seq`, que ninguém muda).
create table if not exists interno.rede_plenarias (
  id uuid primary key default gen_random_uuid(),
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  titulo text not null check (char_length(btrim(titulo)) between 3 and 120),
  descricao text not null default '' check (char_length(descricao) <= 500),
  inicio timestamptz not null,
  sala text check (sala is null or (sala ~ '^https://[^\s]{3,}$' and char_length(sala) <= 300)),
  situacao text not null default 'marcada' check (situacao in ('marcada', 'ao_vivo', 'encerrada')),
  criado_em timestamptz not null default now()
);
create index if not exists rede_plenarias_org on interno.rede_plenarias (org, inicio desc);
create index if not exists rede_plenarias_ao_vivo on interno.rede_plenarias (situacao) where situacao = 'ao_vivo';
alter table interno.rede_plenarias enable row level security;

create table if not exists interno.rede_plenaria_perguntas (
  id uuid primary key default gen_random_uuid(),
  plenaria uuid not null references interno.rede_plenarias (id) on delete cascade,
  seq bigint generated always as identity,
  autor uuid references interno.perfis (id) on delete set null,
  mostrar boolean not null default false,
  texto text not null check (char_length(btrim(texto)) between 2 and 280),
  criado_em timestamptz not null default now(),
  respondida_em timestamptz,
  retirada_em timestamptz,
  retirada_motivo text check (retirada_motivo is null or retirada_motivo in ('ofensa', 'dado_pessoal', 'fora_do_tema', 'repetida'))
);
create index if not exists rede_plenaria_perguntas_fila on interno.rede_plenaria_perguntas (plenaria, seq);
alter table interno.rede_plenaria_perguntas enable row level security;

/** A fila não reordena: a ordem (seq, criado_em), a plenária, o texto e quem perguntou não mudam depois de entrar. */
create or replace function interno.alumia_fila_fixa() returns trigger language plpgsql as $$
begin
  if new.seq is distinct from old.seq or new.criado_em is distinct from old.criado_em or new.plenaria is distinct from old.plenaria
     or new.texto is distinct from old.texto or (new.autor is distinct from old.autor and new.autor is not null) then
    raise exception 'fila_fixa' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists alumia_fila_fixa on interno.rede_plenaria_perguntas;
create trigger alumia_fila_fixa before update on interno.rede_plenaria_perguntas for each row execute function interno.alumia_fila_fixa();

-- O sininho ("avisar quando a organização postar").
create table if not exists interno.rede_org_sinos (
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  primary key (org, usuario)
);
create index if not exists rede_org_sinos_usuario on interno.rede_org_sinos (usuario);
alter table interno.rede_org_sinos enable row level security;

-- Extras do perfil de pessoa: status curto (com prazo), pronomes e até 4 campos.
alter table interno.perfis add column if not exists rede_status_tipo text;
alter table interno.perfis add column if not exists rede_status_texto text;
alter table interno.perfis add column if not exists rede_status_ate timestamptz;
alter table interno.perfis add column if not exists rede_pronomes text;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'interno.perfis'::regclass and conname = 'perfis_rede_status_tipo') then
    alter table interno.perfis add constraint perfis_rede_status_tipo check (rede_status_tipo is null or rede_status_tipo in ('greve', 'ato', 'estudando', 'cuidando', 'ferias'));
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.perfis'::regclass and conname = 'perfis_rede_status_texto') then
    alter table interno.perfis add constraint perfis_rede_status_texto check (rede_status_texto is null or char_length(rede_status_texto) <= 60);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'interno.perfis'::regclass and conname = 'perfis_rede_pronomes') then
    alter table interno.perfis add constraint perfis_rede_pronomes check (rede_pronomes is null or char_length(rede_pronomes) <= 30);
  end if;
end $$;
create table if not exists interno.rede_perfil_campos (
  usuario uuid not null references interno.perfis (id) on delete cascade,
  ordem smallint not null check (ordem between 1 and 4),
  rotulo text not null check (char_length(btrim(rotulo)) between 1 and 30),
  valor text not null check (char_length(btrim(valor)) between 1 and 80),
  primary key (usuario, ordem)
);
alter table interno.rede_perfil_campos enable row level security;

-- Nenhuma permissão direta nas tabelas novas.
do $$
declare t text;
begin
  foreach t in array array['rede_orgs', 'rede_org_gestores', 'rede_org_pedidos', 'rede_org_votacoes', 'rede_org_nucleo_pedidos', 'rede_consultas',
    'rede_consulta_opcoes', 'rede_consulta_votantes', 'rede_consulta_cedulas', 'rede_plenarias', 'rede_plenaria_perguntas', 'rede_org_sinos', 'rede_perfil_campos'] loop
    execute format('revoke all on table interno.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on table interno.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- ── 2. Ajudas internas ────────────────────────────────────────────────────────────────────────────────────────────────────

/** A organização pelo @ (nula se o @ não é de organização, ou se a conta está suspensa). */
create or replace function interno.alumia_org_de(p_handle text) returns uuid language sql stable security definer set search_path = interno, pg_temp as $$
  select o.perfil from rede_orgs o join perfis f on f.id = o.perfil
  where f.rede_handle = lower(btrim(coalesce(p_handle, ''), ' @')) and not f.suspenso
$$;

/** `p_quem` gerencia `p_org`? (dono ou gestor) */
create or replace function interno.alumia_org_gere(p_quem uuid, p_org uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_quem is not null and p_org is not null and exists (select 1 from rede_org_gestores g where g.org = p_org and g.gestor = p_quem)
$$;

/** Contagem de PESSOAS para mostrar: nula abaixo de 3 (PLANO-ALUMIA §6.1). */
create or replace function interno.alumia_pessoas(p_n bigint) returns integer language sql immutable as $$
  select case when p_n >= 3 then p_n::integer end
$$;

/** A organização pelo @, para quem gerencia: confere membro, gestor e limite. Devolve o id. */
create or replace function interno.alumia_org_gestor(p_handle text, p_acao text, p_max integer, p_min integer) returns uuid language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  v_org := interno.alumia_org_de(p_handle);
  if v_org is null or not interno.alumia_org_gere(v, v_org) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite(p_acao, p_max, p_min);
  return v_org;
end $$;

/** A palavra da capa (A–Z, 2 a 14) a partir do codinome. */
create or replace function interno.alumia_palavra(p_codinome text) returns text language sql immutable as $$
  select case when char_length(w) >= 2 then w else 'ORG' end
  from (select btrim(left(regexp_replace(upper(translate(coalesce(p_codinome, ''), 'áàâãäéèêëíìîïóòôõöúùûüçñÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑ', 'aaaaaeeeeiiiiooooouuuucnAAAAAEEEEIIIIOOOOOUUUUCN')), '[^A-Z ]', '', 'g'), 14)) as w) x
$$;

/**
 * A F0 diz que a pessoa age como ela mesma ou como as identidades/organizações dela (rede_identidades). A F4 acrescenta: quem é
 * gestor da organização também age como ela. Mesma assinatura (create or replace).
 */
create or replace function interno.rede_age_como(p_quem uuid, p_como uuid) returns boolean
language sql stable security definer set search_path = interno, pg_temp as $$
  select p_quem is not null and p_como is not null
    and (p_quem = p_como
      or exists (select 1 from rede_identidades i where i.dono = p_quem and i.identidade = p_como)
      or exists (select 1 from rede_org_gestores g where g.gestor = p_quem and g.org = p_como))
$$;

/**
 * Apura uma consulta (as mesmas regras de lib/rede/org/apuracao.ts, que é a referência e o teste). Simples: conta a primeira
 * opção. Ranqueada: segundo turno instantâneo; empate na eliminação olha as rodadas anteriores e, se persistir, sai a última na
 * ordem das opções. Só entram cédulas (nunca pessoas). Devolve {cedulas, vencedora, proporcoes: {opcao: 0..1}} da última rodada.
 */
create or replace function interno.alumia_apurar(p_consulta uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  v_metodo text; v_opcoes uuid[]; v_vivas uuid[]; v_n integer; v_votos jsonb; v_rodadas jsonb := '[]'::jsonb; v_total integer;
  v_lider uuid; v_min integer; v_empatadas uuid[]; v_menor integer; r integer; o uuid; v_venc uuid; v_ultima jsonb;
begin
  select metodo into v_metodo from rede_consultas where id = p_consulta;
  select array_agg(id order by ordem) into v_opcoes from rede_consulta_opcoes where consulta = p_consulta;
  select count(*) into v_n from rede_consulta_cedulas where consulta = p_consulta;
  v_vivas := coalesce(v_opcoes, '{}');
  loop
    -- Votos de cada opção viva: cada cédula conta para a sua opção viva mais bem colocada.
    select coalesce(jsonb_object_agg(x.o::text, x.n), '{}'::jsonb), coalesce(sum(x.n), 0)::integer into v_votos, v_total from (
      select vv.o, count(e.escolha)::integer as n
      from unnest(v_vivas) vv(o)
      left join (
        select (select u.x from unnest(case when v_metodo = 'simples' then c.ranking[1:1] else c.ranking end) with ordinality u(x, i)
                where u.x = any (v_vivas) order by u.i limit 1) as escolha
        from rede_consulta_cedulas c where c.consulta = p_consulta) e on e.escolha = vv.o
      group by vv.o) x;
    if v_metodo = 'simples' then
      select max((v_votos ->> k::text)::integer) into v_min from unnest(v_vivas) k;
      select array_agg(k order by array_position(v_opcoes, k)) into v_empatadas from unnest(v_vivas) k where (v_votos ->> k::text)::integer = v_min;
      v_venc := case when coalesce(v_min, 0) > 0 and cardinality(v_empatadas) = 1 then v_empatadas[1] end;
      v_rodadas := v_rodadas || jsonb_build_array(v_votos);
      exit;
    end if;
    if v_total = 0 then v_rodadas := v_rodadas || jsonb_build_array(v_votos); v_venc := null; exit; end if;
    v_lider := null;
    foreach o in array v_opcoes loop
      if o = any (v_vivas) and (v_votos ->> o::text)::integer * 2 > v_total then v_lider := o; exit; end if;
    end loop;
    if v_lider is not null or cardinality(v_vivas) = 1 then
      v_rodadas := v_rodadas || jsonb_build_array(v_votos);
      v_venc := coalesce(v_lider, v_vivas[1]);
      exit;
    end if;
    select min((v_votos ->> k::text)::integer) into v_min from unnest(v_vivas) k;
    select array_agg(k order by array_position(v_opcoes, k)) into v_empatadas from unnest(v_vivas) k where (v_votos ->> k::text)::integer = v_min;
    r := jsonb_array_length(v_rodadas) - 1;
    while r >= 0 and cardinality(v_empatadas) > 1 loop
      select min(coalesce((v_rodadas -> r ->> k::text)::integer, 0)) into v_menor from unnest(v_empatadas) k;
      select array_agg(k order by array_position(v_opcoes, k)) into v_empatadas from unnest(v_empatadas) k where coalesce((v_rodadas -> r ->> k::text)::integer, 0) = v_menor;
      r := r - 1;
    end loop;
    v_rodadas := v_rodadas || jsonb_build_array(v_votos);
    v_vivas := array_remove(v_vivas, v_empatadas[cardinality(v_empatadas)]);
    if cardinality(v_vivas) = 0 then v_venc := null; exit; end if;
  end loop;
  v_ultima := v_rodadas -> (jsonb_array_length(v_rodadas) - 1);
  select coalesce(sum(value::integer), 0) into v_total from jsonb_each_text(v_ultima);
  return jsonb_build_object('cedulas', v_n, 'vencedora', v_venc, 'rodadas', jsonb_array_length(v_rodadas),
    'proporcoes', (select coalesce(jsonb_object_agg(k::text, case when v_total > 0 then coalesce((v_ultima ->> k::text)::numeric, 0) / v_total else 0 end), '{}'::jsonb)
                   from unnest(coalesce(v_opcoes, '{}')) k));
end $$;

/** A consulta como o perfil mostra (para quem olha: p_quem nulo = visitante). */
create or replace function interno.alumia_consulta_json(c interno.rede_consultas, p_quem uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  v_fechada boolean := c.prazo <= now(); v_votantes integer; v_ap jsonb; v_mostra boolean; v_nucleos uuid[];
  v_posso boolean; v_votei boolean;
begin
  v_nucleos := case when cardinality(c.nucleos) > 0 then c.nucleos else coalesce((select array_agg(id) from rede_nucleos where org = c.org), '{}') end;
  select count(*) into v_votantes from rede_consulta_votantes where consulta = c.id;
  v_votei := p_quem is not null and exists (select 1 from rede_consulta_votantes where consulta = c.id and usuario = p_quem);
  v_posso := p_quem is not null and not v_fechada and not v_votei and interno.rede2_membro(p_quem) and not interno.rede_bloqueado(p_quem, c.org)
    and exists (select 1 from rede_nucleo_membros m where m.usuario = p_quem and m.nucleo = any (v_nucleos));
  -- O resultado só sai com a consulta fechada e com 3 votos ou mais (com 1 ou 2 daria para saber o voto de alguém).
  v_mostra := v_fechada and v_votantes >= 3;
  if v_mostra then v_ap := interno.alumia_apurar(c.id); end if;
  return jsonb_build_object(
    'id', c.id, 'pergunta', c.pergunta, 'metodo', c.metodo, 'prazo', c.prazo, 'compromisso', c.compromisso, 'quorum', c.quorum,
    'situacao', case when v_fechada then 'fechada' else 'aberta' end,
    'votantes', case when v_fechada then interno.alumia_pessoas(v_votantes) end,
    'quorumAtingido', case when v_fechada then (c.quorum is null or v_votantes >= c.quorum) end,
    'possoVotar', v_posso, 'votei', v_votei,
    'nucleos', coalesce((select jsonb_agg(n.nome order by n.nome) from rede_nucleos n where n.id = any (v_nucleos)), '[]'::jsonb),
    'opcoes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'texto', o.texto,
                'proporcao', case when v_mostra then round((v_ap -> 'proporcoes' ->> o.id::text)::numeric, 4) end) order by o.ordem)
              from rede_consulta_opcoes o where o.consulta = c.id), '[]'::jsonb));
end $$;

/** A plenária como o perfil mostra. Visitante não vê a fila (só quantas perguntas esperam). */
create or replace function interno.alumia_plenaria_json(p interno.rede_plenarias, p_quem uuid, p_com_fila boolean) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', p.id, 'org', jsonb_build_object('handle', f.rede_handle, 'codinome', f.rede_codinome),
    'titulo', p.titulo, 'descricao', p.descricao, 'inicio', p.inicio, 'aoVivo', p.situacao = 'ao_vivo',
    'sala', case when p.situacao = 'ao_vivo' then p.sala end,
    -- Não guardamos quem entra na sala (nenhum registro de presença): o número de pessoas na sala não existe.
    'naSala', null,
    'naFila', (select count(*) from rede_plenaria_perguntas q where q.plenaria = p.id and q.respondida_em is null and q.retirada_em is null),
    'pergunteiEu', p_quem is not null and exists (select 1 from rede_plenaria_perguntas q where q.plenaria = p.id and q.autor = p_quem),
    'fila', case when p_com_fila then coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'handle', case when q.mostrar then a.rede_handle end, 'texto', q.texto,
                                          'criadaEm', q.criado_em, 'respondida', q.respondida_em is not null) order by q.seq)
      from (select * from rede_plenaria_perguntas where plenaria = p.id and retirada_em is null order by seq limit 30) q
      left join perfis a on a.id = q.autor and not a.suspenso and not a.rede_invisivel and a.rede_modo <> 'invisivel'), '[]'::jsonb)
      else '[]'::jsonb end)
  from perfis f where f.id = p.org
$$;

revoke all on function interno.alumia_org_de(text), interno.alumia_org_gere(uuid, uuid), interno.alumia_pessoas(bigint),
  interno.alumia_org_gestor(text, text, integer, integer), interno.alumia_palavra(text), interno.alumia_apurar(uuid),
  interno.alumia_consulta_json(interno.rede_consultas, uuid), interno.alumia_plenaria_json(interno.rede_plenarias, uuid, boolean),
  interno.alumia_fila_fixa(), interno.rede_age_como(uuid, uuid) from public;

-- ── 3. O perfil da organização e o "Ao vivo agora" ────────────────────────────────────────────────────────────────────────

/**
 * O perfil público de uma organização pelo @ (OrgPublica, lib/rede/tipos-org.ts); nulo se o @ não é de organização, se há
 * bloqueio entre quem olha e a organização, ou (para visitante) se a organização ainda não tem o selo. Sem contagem de
 * seguidores, sem lista de gestores, de membros de núcleo, de quem votou ou de quem liga o sininho.
 */
create or replace function public.rede_org_perfil(p_handle text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_org uuid; o rede_orgs; f perfis; v_membro boolean;
begin
  perform interno.limite('alumia_org_ler', 300, 10);
  v_org := interno.alumia_org_de(p_handle);
  if v_org is null then return null; end if;
  select * into o from rede_orgs where perfil = v_org;
  select * into f from perfis where id = v_org;
  if interno.rede_bloqueado(v, v_org) then return null; end if;
  v_membro := interno.rede2_membro(v);
  if not v_membro and o.verificada_em is null then return null; end if;
  return jsonb_build_object(
    'handle', f.rede_handle, 'codinome', coalesce(f.rede_codinome, ''), 'tipo', o.tipo, 'bio', coalesce(f.rede_bio, ''),
    'cidade', nullif(o.cidade, ''), 'verificadaEm', o.verificada_em,
    'documento', case when o.verificada_em is not null then nullif(o.documento_tipo, '') end,
    'palavra', o.palavra,
    'sigo', v is not null and exists (select 1 from rede_seguindo s where s.quem = v and s.segue = v_org and not s.pendente),
    'sino', v is not null and exists (select 1 from rede_org_sinos s where s.org = v_org and s.usuario = v),
    'gerencio', interno.alumia_org_gere(v, v_org),
    'nucleos', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'nome', n.nome, 'cor', n.org_cor, 'quando', n.org_quando,
                  'onde', nullif(n.cidade, ''),
                  'sou', v is not null and exists (select 1 from rede_nucleo_membros m where m.nucleo = n.id and m.usuario = v),
                  'pedi', v is not null and exists (select 1 from rede_org_nucleo_pedidos q where q.nucleo = n.id and q.usuario = v)) order by n.nome)
                from rede_nucleos n where n.org = v_org), '[]'::jsonb),
    'votacoes', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'data', x.data, 'projeto', x.projeto, 'voto', x.voto, 'porque', x.porque,
                  'resultado', x.resultado, 'fonte', x.fonte) order by x.data desc, x.criado_em desc)
                from (select * from rede_org_votacoes where org = v_org order by data desc, criado_em desc limit 30) x), '[]'::jsonb),
    'consultas', coalesce((select jsonb_agg(interno.alumia_consulta_json(c, v) order by c.prazo desc)
                from (select * from rede_consultas where org = v_org order by prazo desc limit 10) c), '[]'::jsonb),
    'plenarias', coalesce((select jsonb_agg(interno.alumia_plenaria_json(p, v, v_membro) order by (p.situacao = 'ao_vivo') desc, p.inicio)
                from (select * from rede_plenarias where org = v_org and situacao <> 'encerrada' order by inicio limit 5) p), '[]'::jsonb));
end $$;

/** "Ao vivo agora": plenárias acontecendo das organizações que sigo ou com selo. Visitante: só das com selo. Até 10. */
create or replace function public.rede_org_ao_vivo() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  perform interno.limite('alumia_org_ler', 300, 10);
  return coalesce((
    select jsonb_agg(interno.alumia_plenaria_json(p, v, false) - 'fila' - 'pergunteiEu' order by p.inicio desc)
    from (
      select p.* from rede_plenarias p join rede_orgs o on o.perfil = p.org join perfis f on f.id = p.org
      where p.situacao = 'ao_vivo' and not f.suspenso and not interno.rede_bloqueado(v, p.org)
        and (o.verificada_em is not null or (v is not null and exists (select 1 from rede_seguindo s where s.quem = v and s.segue = p.org and not s.pendente)))
      order by p.inicio desc limit 10) p), '[]'::jsonb);
end $$;

-- ── 4. Ações de quem é membro da Rede ─────────────────────────────────────────────────────────────────────────────────────

/** O sininho. Ninguém vê quem ligou (nem a organização). */
create or replace function public.rede_org_sino(p_handle text, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  v_org := interno.alumia_org_de(p_handle);
  if v_org is null or interno.rede_bloqueado(v, v_org) then perform interno.erro('nao_encontrado'); end if;
  perform interno.limite('alumia_org_sino', 60, 60);
  if coalesce(p_sim, false) then insert into rede_org_sinos (org, usuario) values (v_org, v) on conflict do nothing;
  else delete from rede_org_sinos where org = v_org and usuario = v; end if;
  return jsonb_build_object('sino', exists (select 1 from rede_org_sinos where org = v_org and usuario = v));
end $$;

/** Pedir para entrar num núcleo da organização. Quem já é do núcleo fica como está. */
create or replace function public.rede_org_nucleo_entrar(p_nucleo uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); n rede_nucleos;
begin
  perform interno.rede3_perfil_exige_membro(v);
  select * into n from rede_nucleos where id = p_nucleo and org is not null;
  if not found or interno.rede_bloqueado(v, n.org) or exists (select 1 from perfis where id = n.org and suspenso) then perform interno.erro('nao_encontrado'); end if;
  perform interno.limite('alumia_org_nucleo_entrar', 20, 1440);
  if not exists (select 1 from rede_nucleo_membros m where m.nucleo = n.id and m.usuario = v) then
    insert into rede_org_nucleo_pedidos (nucleo, usuario) values (n.id, v) on conflict do nothing;
  end if;
  return jsonb_build_object('sou', exists (select 1 from rede_nucleo_membros m where m.nucleo = n.id and m.usuario = v),
                            'pedi', exists (select 1 from rede_org_nucleo_pedidos q where q.nucleo = n.id and q.usuario = v));
end $$;

/**
 * Votar numa consulta aberta. Só quem é de um dos núcleos que votam. `p_ranking`: a ordem de preferência (na simples, uma opção).
 * O voto é secreto: grava "votou" numa tabela e a cédula noutra, sem ligação; nada volta além de "votei". Não dá para mudar.
 */
create or replace function public.rede_org_consulta_votar(p_consulta uuid, p_ranking uuid[]) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c rede_consultas; v_nucleos uuid[]; v_opcoes uuid[];
begin
  perform interno.rede3_perfil_exige_membro(v);
  select * into c from rede_consultas where id = p_consulta;
  if not found or interno.rede_bloqueado(v, c.org) then perform interno.erro('nao_encontrado'); end if;
  if c.prazo <= now() then perform interno.erro('consulta_fechada'); end if;
  v_nucleos := case when cardinality(c.nucleos) > 0 then c.nucleos else coalesce((select array_agg(id) from rede_nucleos where org = c.org), '{}') end;
  if not exists (select 1 from rede_nucleo_membros m where m.usuario = v and m.nucleo = any (v_nucleos)) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('alumia_org_votar', 30, 60);
  select array_agg(id) into v_opcoes from rede_consulta_opcoes where consulta = c.id;
  if p_ranking is null or cardinality(p_ranking) = 0 or cardinality(p_ranking) > cardinality(v_opcoes)
     or (c.metodo = 'simples' and cardinality(p_ranking) <> 1)
     or exists (select 1 from unnest(p_ranking) x where x is null or not x = any (v_opcoes))
     or (select count(distinct x) from unnest(p_ranking) x) <> cardinality(p_ranking) then
    perform interno.erro('invalido:ranking');
  end if;
  insert into rede_consulta_votantes (consulta, usuario) values (c.id, v) on conflict do nothing;
  if not found then perform interno.erro('ja_votou'); end if;
  insert into rede_consulta_cedulas (consulta, ranking) values (c.id, p_ranking);
  return jsonb_build_object('votei', true);
end $$;

/** Mandar pergunta para a fila (entra no fim). Uma por pessoa e plenária; `p_mostrar` decide se o @ aparece na fila. */
create or replace function public.rede_org_plenaria_perguntar(p_plenaria uuid, p_texto text, p_mostrar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); p rede_plenarias; v_texto text := btrim(coalesce(p_texto, ''));
begin
  perform interno.rede3_perfil_exige_membro(v);
  select * into p from rede_plenarias where id = p_plenaria;
  if not found or interno.rede_bloqueado(v, p.org) or exists (select 1 from perfis where id = p.org and suspenso) then perform interno.erro('nao_encontrado'); end if;
  if p.situacao = 'encerrada' then perform interno.erro('plenaria_encerrada'); end if;
  if char_length(v_texto) < 2 or char_length(v_texto) > 280 then perform interno.erro('invalido:texto'); end if;
  perform interno.limite('alumia_org_perguntar', 10, 60);
  if exists (select 1 from rede_plenaria_perguntas q where q.plenaria = p.id and q.autor = v) then perform interno.erro('ja_perguntou'); end if;
  insert into rede_plenaria_perguntas (plenaria, autor, mostrar, texto) values (p.id, v, coalesce(p_mostrar, false), v_texto);
  return jsonb_build_object('ok', true, 'naFila', (select count(*) from rede_plenaria_perguntas q where q.plenaria = p.id and q.respondida_em is null and q.retirada_em is null));
end $$;

-- ── 5. Conta da organização e o selo ──────────────────────────────────────────────────────────────────────────────────────

/** Confere o pedido do selo (as mesmas regras de lib/rede/org/pedido.ts). Devolve o motivo ou nulo. */
create or replace function interno.alumia_pedido_falta(p jsonb) returns text language plpgsql immutable as $$
declare v_doc text := btrim(coalesce(p ->> 'documento', ''));
begin
  if char_length(btrim(coalesce(p ->> 'codinome', ''))) not between 2 and 60 then return 'codinome'; end if;
  if coalesce(p ->> 'handle', '') !~ '^[a-z0-9_]{3,20}$' then return 'handle'; end if;
  if coalesce(p ->> 'tipo', '') not in ('partido', 'mandato', 'sindicato', 'movimento', 'coletivo', 'gremio', 'dce', 'outro') then return 'tipo'; end if;
  if char_length(btrim(coalesce(p ->> 'cidade', ''))) not between 1 and 60 then return 'cidade'; end if;
  if char_length(btrim(coalesce(p ->> 'documentoTipo', ''))) not between 2 and 60 then return 'documentoTipo'; end if;
  if char_length(v_doc) not between 2 and 200 then return 'documento'; end if;
  -- CPF (11 dígitos) é documento de PESSOA: recusado (LGPD art. 6º, III). CNPJ tem 14 e passa.
  if v_doc ~ '^\d{3}\.?\d{3}\.?\d{3}-?\d{2}$' then return 'docPessoal'; end if;
  if char_length(btrim(coalesce(p ->> 'sobre', ''))) not between 2 and 280 then return 'sobre'; end if;
  if coalesce((p ->> 'maior')::boolean, false) is not true then return 'maior'; end if;
  return null;
end $$;
revoke all on function interno.alumia_pedido_falta(jsonb) from public;

/**
 * Pedir o selo. Se o @ já é de uma organização que eu gerencio: o pedido entra na fila (um esperando por vez). Se o @ está livre:
 * devolve {criar: true, dono} e o servidor (app/api/rede/org/selo) cria a conta sem senha e chama rede_org_criar. `dono` é o
 * próprio id de quem chama (vem da sessão, não do pedido). Recusa @ de outra pessoa ou de organização que não é minha.
 */
create or replace function public.rede_org_pedir_selo(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_falta text; v_handle text; v_org uuid; v_id uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  v_falta := interno.alumia_pedido_falta(p);
  if v_falta is not null then perform interno.erro('invalido:' || lower(v_falta)); end if;
  perform interno.limite('alumia_org_selo', 6, 1440);
  v_handle := p ->> 'handle';
  select perfil into v_org from rede_orgs o join perfis f on f.id = o.perfil where f.rede_handle = v_handle;
  if v_org is not null then
    if not interno.alumia_org_gere(v, v_org) then perform interno.erro('handle_usado'); end if;
    if exists (select 1 from rede_org_pedidos where org = v_org and situacao = 'esperando') then perform interno.erro('ja_pedido'); end if;
    if exists (select 1 from rede_orgs where perfil = v_org and verificada_em is not null) then perform interno.erro('ja_verificada'); end if;
    insert into rede_org_pedidos (org, documento_tipo, documento, sobre) values (v_org, btrim(p ->> 'documentoTipo'), btrim(p ->> 'documento'), btrim(p ->> 'sobre'))
    returning id into v_id;
    return jsonb_build_object('id', v_id, 'situacao', 'esperando');
  end if;
  if not interno.rede2_handle_ok(v_handle, v) or exists (select 1 from perfis where rede_handle = v_handle) then
    perform interno.erro(case when v_handle ~ '(instituto|lucia|equipe|coordena|modera|admin|suporte|oficial)' then 'handle_reservado' else 'handle_usado' end);
  end if;
  if (select count(*) from rede_org_gestores where gestor = v and papel = 'dono') >= 5 then perform interno.erro('limite_identidades'); end if;
  return jsonb_build_object('criar', true, 'dono', v);
end $$;

/**
 * Só o servidor (chave de serviço), logo depois de lib/rede/contas-extra.ts criar a conta sem senha e ligá-la ao dono em
 * rede_identidades: transforma o perfil novo em organização, põe o dono como gestor e o pedido na fila. Confere tudo de novo.
 */
create or replace function public.rede_org_criar(p_dono uuid, p_org uuid, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_falta text := interno.alumia_pedido_falta(p); v_handle text := p ->> 'handle'; v_id uuid;
begin
  if v_falta is not null then perform interno.erro('invalido:' || lower(v_falta)); end if;
  if not exists (select 1 from rede_identidades i where i.dono = p_dono and i.identidade = p_org and i.tipo = 'org') then perform interno.erro('sem_permissao'); end if;
  if not interno.rede2_membro(p_dono) then perform interno.erro('consentimento'); end if;
  if exists (select 1 from rede_orgs where perfil = p_org) then perform interno.erro('ja_pedido'); end if;
  if not interno.rede2_handle_ok(v_handle, p_org) then perform interno.erro('handle_usado'); end if;
  update perfis set rede_handle = v_handle, rede_codinome = btrim(p ->> 'codinome'), rede_codinome_ok = true, rede_bio = btrim(p ->> 'sobre')
  where id = p_org;
  insert into rede_orgs (perfil, tipo, cidade, palavra) values (p_org, p ->> 'tipo', btrim(p ->> 'cidade'), interno.alumia_palavra(p ->> 'codinome'));
  insert into rede_org_gestores (org, gestor, papel) values (p_org, p_dono, 'dono');
  insert into rede_org_pedidos (org, documento_tipo, documento, sobre) values (p_org, btrim(p ->> 'documentoTipo'), btrim(p ->> 'documento'), btrim(p ->> 'sobre'))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'situacao', 'esperando');
end $$;

/** A fila do selo (painel; só a coordenação). Mostra a organização e o documento público; nunca quem pediu nem os gestores. */
create or replace function public.rede_org_selo_fila() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'codinome', f.rede_codinome, 'handle', f.rede_handle, 'tipo', o.tipo, 'cidade', o.cidade,
      'documentoTipo', x.documento_tipo, 'documento', x.documento, 'sobre', x.sobre, 'maior', true, 'criadoEm', x.criado_em, 'situacao', x.situacao,
      'motivo', x.motivo) order by (x.situacao = 'esperando') desc, x.criado_em)
    from (select * from rede_org_pedidos where situacao = 'esperando' or criado_em > now() - interval '60 days' order by criado_em desc limit 100) x
    join rede_orgs o on o.perfil = x.org join perfis f on f.id = x.org), '[]'::jsonb);
end $$;

/** Dar ou recusar o selo (só a coordenação; recusar pede motivo de 10 letras). Os gestores recebem o aviso. Registrado. */
create or replace function public.rede_org_selo_decidir(p_id uuid, p_aceitar boolean, p_motivo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_org_pedidos; v_motivo text := left(btrim(coalesce(p_motivo, '')), 500); g record; v_nome text;
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into x from rede_org_pedidos where id = p_id for update;
  if not found or x.situacao <> 'esperando' then perform interno.erro('nao_encontrado'); end if;
  if not coalesce(p_aceitar, false) and char_length(v_motivo) < 10 then perform interno.erro('invalido:motivo'); end if;
  v_nome := interno.rede_nome(x.org);
  update rede_org_pedidos set situacao = case when p_aceitar then 'aceito' else 'recusado' end, motivo = v_motivo, decidido_em = now(), decidido_por = v where id = x.id;
  if p_aceitar then
    update rede_orgs set verificada_em = now(), verificada_por = v, documento_tipo = x.documento_tipo, documento_publico = x.documento where perfil = x.org;
  end if;
  for g in select gestor from rede_org_gestores where org = x.org loop
    perform interno.avisar_em(g.gestor, case when p_aceitar then format('A organização “%s” recebeu o selo da Alumia.', v_nome)
      else format('O pedido do selo de “%s” não foi aceito: %s', v_nome, v_motivo) end, 'rede');
  end loop;
  perform interno.registrar(case when p_aceitar then 'alumia_selo_dar' else 'alumia_selo_recusar' end, x.org::text, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end $$;

/** Tirar o selo (só a coordenação, com motivo; os gestores são avisados e podem pedir de novo). Registrado (PLANO-ALUMIA §7.6). */
create or replace function public.rede_org_selo_tirar(p_handle text, p_motivo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_org uuid; v_motivo text := left(btrim(coalesce(p_motivo, '')), 500); g record;
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if char_length(v_motivo) < 10 then perform interno.erro('invalido:motivo'); end if;
  v_org := interno.alumia_org_de(p_handle);
  if v_org is null then perform interno.erro('nao_encontrado'); end if;
  update rede_orgs set verificada_em = null, verificada_por = null where perfil = v_org;
  for g in select gestor from rede_org_gestores where org = v_org loop
    perform interno.avisar_em(g.gestor, format('O selo de “%s” foi retirado: %s', interno.rede_nome(v_org), v_motivo), 'rede');
  end loop;
  perform interno.registrar('alumia_selo_tirar', v_org::text, jsonb_build_object('motivo', v_motivo));
  return jsonb_build_object('ok', true);
end $$;

-- ── 6. Gestores (o vínculo nunca volta: só "ok") ──────────────────────────────────────────────────────────────────────────

/** O dono põe outra pessoa (membro da Rede) como gestora. Responde só "ok". */
create or replace function public.rede_org_gestor_adicionar(p_org text, p_handle text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid := interno.alumia_org_de(p_org); v_quem uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  if v_org is null or not exists (select 1 from rede_org_gestores where org = v_org and gestor = v and papel = 'dono') then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('alumia_org_gestor', 10, 1440);
  select id into v_quem from perfis where rede_handle = lower(btrim(coalesce(p_handle, ''), ' @')) and not suspenso;
  if v_quem is null or v_quem = v_org or not interno.rede2_membro(v_quem) or interno.rede_bloqueado(v, v_quem) or interno.rede_bloqueado(v_org, v_quem)
     or exists (select 1 from rede_orgs where perfil = v_quem) or exists (select 1 from rede_identidades where identidade = v_quem) then
    perform interno.erro('nao_encontrado');
  end if;
  if (select count(*) from rede_org_gestores where org = v_org) >= 10 then perform interno.erro('limite_gestores'); end if;
  insert into rede_org_gestores (org, gestor, papel) values (v_org, v_quem, 'gestor') on conflict do nothing;
  perform interno.avisar_em(v_quem, format('Você agora ajuda a cuidar da conta “%s” na Alumia. Se não quiser, saia pela página da organização.', interno.rede_nome(v_org)), 'rede');
  return jsonb_build_object('ok', true);
end $$;

/** O dono tira uma pessoa da gestão. Responde "ok" mesmo se ela não era (não serve para descobrir quem é). */
create or replace function public.rede_org_gestor_remover(p_org text, p_handle text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid := interno.alumia_org_de(p_org);
begin
  if v_org is null or not exists (select 1 from rede_org_gestores where org = v_org and gestor = v and papel = 'dono') then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('alumia_org_gestor', 10, 1440);
  delete from rede_org_gestores g using perfis f where g.org = v_org and g.papel = 'gestor' and f.id = g.gestor and f.rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  return jsonb_build_object('ok', true);
end $$;

/** Eu saio da gestão (o dono não sai: a conta ficaria sem ninguém). */
create or replace function public.rede_org_gestor_sair(p_org text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid := interno.alumia_org_de(p_org);
begin
  delete from rede_org_gestores where org = v_org and gestor = v and papel = 'gestor';
  return jsonb_build_object('ok', true);
end $$;

-- ── 7. O que só quem gerencia faz ─────────────────────────────────────────────────────────────────────────────────────────

/** Registrar um voto em "Como votamos" (com a fonte pública obrigatória). */
create or replace function public.rede_org_votacao_registrar(p_handle text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_org uuid := interno.alumia_org_gestor(p_handle, 'alumia_org_votacao', 30, 1440); x rede_org_votacoes; v_data date;
begin
  begin v_data := (p ->> 'data')::date; exception when others then perform interno.erro('invalido:data'); end;
  if v_data is null or v_data > current_date or v_data < date '1988-10-05' then perform interno.erro('invalido:data'); end if;
  if coalesce(p ->> 'fonte', '') !~ '^https?://[^\s]{3,}$' then perform interno.erro('invalido:fonte'); end if;
  begin
    insert into rede_org_votacoes (org, data, projeto, voto, porque, resultado, fonte)
    values (v_org, v_data, btrim(coalesce(p ->> 'projeto', '')), p ->> 'voto', btrim(coalesce(p ->> 'porque', '')), btrim(coalesce(p ->> 'resultado', '')), btrim(p ->> 'fonte'))
    returning * into x;
  exception when check_violation or not_null_violation then perform interno.erro('invalido:votacao');
  end;
  return jsonb_build_object('id', x.id, 'data', x.data, 'projeto', x.projeto, 'voto', x.voto, 'porque', x.porque, 'resultado', x.resultado, 'fonte', x.fonte);
end $$;

/** Criar um núcleo da organização. */
create or replace function public.rede_org_nucleo_criar(p_handle text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_org uuid := interno.alumia_org_gestor(p_handle, 'alumia_org_nucleo', 10, 1440); v_id uuid;
begin
  if (select count(*) from rede_nucleos where org = v_org) >= 50 then perform interno.erro('limite_nucleos'); end if;
  begin
    insert into rede_nucleos (nome, cidade, criado_por, org, org_quando, org_cor)
    values (btrim(coalesce(p ->> 'nome', '')), btrim(coalesce(p ->> 'onde', '')), v_org, v_org, btrim(coalesce(p ->> 'quando', '')),
            coalesce(nullif(p ->> 'cor', '')::smallint, 1))
    returning id into v_id;
  exception when check_violation or invalid_text_representation or numeric_value_out_of_range then perform interno.erro('invalido:nucleo');
  end;
  -- Quem cria entra como mediação (para receber e decidir pedidos). Não aparece em lista nenhuma.
  insert into rede_nucleo_membros (nucleo, usuario, papel) values (v_id, v, 'mediacao') on conflict do nothing;
  return jsonb_build_object('id', v_id);
end $$;

/** Os pedidos para entrar nos núcleos da organização (só gestores e a mediação do núcleo): codinome e @, nada mais. */
create or replace function public.rede_org_nucleo_pedidos(p_handle text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid := interno.alumia_org_de(p_handle); v_gere boolean;
begin
  perform interno.rede3_perfil_exige_membro(v);
  if v_org is null then perform interno.erro('sem_permissao'); end if;
  v_gere := interno.alumia_org_gere(v, v_org);
  if not v_gere and not exists (select 1 from rede_nucleo_membros m join rede_nucleos n on n.id = m.nucleo where n.org = v_org and m.usuario = v and m.papel = 'mediacao') then
    perform interno.erro('sem_permissao');
  end if;
  perform interno.limite('alumia_org_ler', 300, 10);
  return coalesce((
    select jsonb_agg(jsonb_build_object('nucleo', n.id, 'nucleoNome', n.nome, 'handle', f.rede_handle, 'codinome', f.rede_codinome) order by q.criado_em, f.rede_handle)
    from rede_org_nucleo_pedidos q join rede_nucleos n on n.id = q.nucleo join perfis f on f.id = q.usuario
    where n.org = v_org and not f.suspenso
      and (v_gere or exists (select 1 from rede_nucleo_membros m where m.nucleo = n.id and m.usuario = v and m.papel = 'mediacao'))), '[]'::jsonb);
end $$;

/** Aceitar ou recusar um pedido para entrar no núcleo (gestor ou mediação do núcleo). Recusar só apaga o pedido. */
create or replace function public.rede_org_nucleo_decidir(p_nucleo uuid, p_handle text, p_aceitar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); n rede_nucleos; v_quem uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  select * into n from rede_nucleos where id = p_nucleo and org is not null;
  if not found or not (interno.alumia_org_gere(v, n.org) or exists (select 1 from rede_nucleo_membros m where m.nucleo = n.id and m.usuario = v and m.papel = 'mediacao')) then
    perform interno.erro('sem_permissao');
  end if;
  perform interno.limite('alumia_org_decidir', 200, 60);
  select q.usuario into v_quem from rede_org_nucleo_pedidos q join perfis f on f.id = q.usuario where q.nucleo = n.id and f.rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  if v_quem is null then perform interno.erro('nao_encontrado'); end if;
  delete from rede_org_nucleo_pedidos where nucleo = n.id and usuario = v_quem;
  if coalesce(p_aceitar, false) and interno.rede2_membro(v_quem) and not interno.rede_bloqueado(v_quem, n.org) then
    insert into rede_nucleo_membros (nucleo, usuario, papel) values (n.id, v_quem, 'membro') on conflict do nothing;
    perform interno.avisar_em(v_quem, format('Você entrou no núcleo “%s”.', n.nome), 'rede');
  end if;
  return jsonb_build_object('ok', true);
end $$;

/**
 * Abrir uma consulta à base. A pergunta, as opções (2 a 8), o método, o quórum, os núcleos que votam e o compromisso ficam
 * escritos ANTES e não mudam depois (ninguém troca a regra no meio). Prazo entre 1 hora e 60 dias.
 */
create or replace function public.rede_org_consulta_abrir(p_handle text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_org uuid := interno.alumia_org_gestor(p_handle, 'alumia_org_consulta', 10, 1440); v_id uuid; v_prazo timestamptz; v_nucleos uuid[] := '{}';
  v_opcoes text[]; i integer;
begin
  begin v_prazo := (p ->> 'prazo')::timestamptz; exception when others then perform interno.erro('invalido:prazo'); end;
  if v_prazo is null or v_prazo < now() + interval '1 hour' or v_prazo > now() + interval '60 days' then perform interno.erro('invalido:prazo'); end if;
  select coalesce(array_agg(btrim(x)), '{}') into v_opcoes from jsonb_array_elements_text(coalesce(p -> 'opcoes', '[]'::jsonb)) x where btrim(x) <> '';
  if cardinality(v_opcoes) not between 2 and 8 or (select count(distinct lower(x)) from unnest(v_opcoes) x) <> cardinality(v_opcoes) then perform interno.erro('invalido:opcoes'); end if;
  if jsonb_typeof(p -> 'nucleos') = 'array' then
    select coalesce(array_agg(x::uuid), '{}') into v_nucleos from jsonb_array_elements_text(p -> 'nucleos') x;
    if exists (select 1 from unnest(v_nucleos) k where not exists (select 1 from rede_nucleos n where n.id = k and n.org = v_org)) then perform interno.erro('invalido:nucleos'); end if;
  end if;
  if not exists (select 1 from rede_nucleos n where n.org = v_org and (cardinality(v_nucleos) = 0 or n.id = any (v_nucleos))) then perform interno.erro('sem_nucleos'); end if;
  begin
    insert into rede_consultas (org, nucleos, pergunta, metodo, quorum, prazo, compromisso)
    values (v_org, v_nucleos, btrim(coalesce(p ->> 'pergunta', '')), p ->> 'metodo', nullif(p ->> 'quorum', '')::integer, v_prazo, btrim(coalesce(p ->> 'compromisso', '')))
    returning id into v_id;
  exception when check_violation or not_null_violation or invalid_text_representation then perform interno.erro('invalido:consulta');
  end;
  for i in 1 .. cardinality(v_opcoes) loop
    begin
      insert into rede_consulta_opcoes (consulta, ordem, texto) values (v_id, i, v_opcoes[i]);
    exception when check_violation then perform interno.erro('invalido:opcoes');
    end;
  end loop;
  return jsonb_build_object('id', v_id);
end $$;

/** Marcar uma plenária. */
create or replace function public.rede_org_plenaria_abrir(p_handle text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_org uuid := interno.alumia_org_gestor(p_handle, 'alumia_org_plenaria', 10, 1440); v_id uuid; v_inicio timestamptz;
begin
  begin v_inicio := (p ->> 'inicio')::timestamptz; exception when others then perform interno.erro('invalido:inicio'); end;
  if v_inicio is null or v_inicio < now() - interval '1 day' or v_inicio > now() + interval '180 days' then perform interno.erro('invalido:inicio'); end if;
  begin
    insert into rede_plenarias (org, titulo, descricao, inicio, sala)
    values (v_org, btrim(coalesce(p ->> 'titulo', '')), btrim(coalesce(p ->> 'descricao', '')), v_inicio, nullif(btrim(coalesce(p ->> 'sala', '')), ''))
    returning id into v_id;
  exception when check_violation then perform interno.erro('invalido:plenaria');
  end;
  return jsonb_build_object('id', v_id);
end $$;

/** Pôr no ar, encerrar ou trocar o link da sala (só https). */
create or replace function public.rede_org_plenaria_mudar(p_id uuid, p_situacao text, p_sala text default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_plenarias;
begin
  perform interno.rede3_perfil_exige_membro(v);
  select * into x from rede_plenarias where id = p_id;
  if not found or not interno.alumia_org_gere(v, x.org) then perform interno.erro('sem_permissao'); end if;
  if p_situacao not in ('marcada', 'ao_vivo', 'encerrada') or x.situacao = 'encerrada' then perform interno.erro('invalido:situacao'); end if;
  perform interno.limite('alumia_org_plenaria_mudar', 60, 60);
  begin
    update rede_plenarias set situacao = p_situacao, sala = coalesce(nullif(btrim(coalesce(p_sala, '')), ''), sala) where id = x.id;
  exception when check_violation then perform interno.erro('invalido:sala');
  end;
  return jsonb_build_object('ok', true);
end $$;

/** Marcar a pergunta como respondida (a ordem da fila não muda). */
create or replace function public.rede_org_plenaria_responder(p_pergunta uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid;
begin
  select p.org into v_org from rede_plenaria_perguntas q join rede_plenarias p on p.id = q.plenaria where q.id = p_pergunta;
  if v_org is null or not interno.alumia_org_gere(v, v_org) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('alumia_org_plenaria_mudar', 60, 60);
  update rede_plenaria_perguntas set respondida_em = coalesce(respondida_em, now()) where id = p_pergunta;
  return jsonb_build_object('ok', true);
end $$;

/**
 * Tirar uma pergunta da fila só por regra escrita (ofensa, dado pessoal, fora do tema, repetida), com registro (PLANO-ALUMIA §7.4).
 * A pergunta não é apagada nem reordenada: fica marcada, fora da lista.
 */
create or replace function public.rede_org_plenaria_retirar(p_pergunta uuid, p_motivo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_org uuid;
begin
  select p.org into v_org from rede_plenaria_perguntas q join rede_plenarias p on p.id = q.plenaria where q.id = p_pergunta;
  if v_org is null or not interno.alumia_org_gere(v, v_org) then perform interno.erro('sem_permissao'); end if;
  if p_motivo is null or p_motivo not in ('ofensa', 'dado_pessoal', 'fora_do_tema', 'repetida') then perform interno.erro('invalido:motivo'); end if;
  perform interno.limite('alumia_org_plenaria_mudar', 60, 60);
  update rede_plenaria_perguntas set retirada_em = now(), retirada_motivo = p_motivo where id = p_pergunta and retirada_em is null;
  -- O registro leva a organização e o motivo, não quem do time tirou (o vínculo gestor↔organização não sai do banco).
  insert into auditoria (quem, nome, acao, alvo, detalhes) values (v_org, '', 'alumia_pergunta_retirar', p_pergunta::text, jsonb_build_object('motivo', p_motivo));
  return jsonb_build_object('ok', true);
end $$;

-- ── 8. O sininho avisa quando a organização posta ────────────────────────────────────────────────────────────────────────

/** Post novo (não resposta) de uma organização: avisa quem ligou o sininho e pode ver o post (sem trecho do texto). */
create or replace function interno.alumia_org_postou() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare s record; v_nome text;
begin
  if new.resposta_a is not null or new.autor is null or not exists (select 1 from rede_orgs where perfil = new.autor) then return new; end if;
  v_nome := interno.rede_nome(new.autor);
  for s in select usuario from rede_org_sinos where org = new.autor limit 5000 loop
    if interno.rede2_membro(s.usuario) and not interno.rede_bloqueado(s.usuario, new.autor) and interno.rede2_pode_ver(new, s.usuario)
       and interno.rede3_aviso_pref(s.usuario, 'org_postou', 'site') then
      perform interno.avisar_em(s.usuario, format('“%s” publicou na Alumia.', v_nome), 'rede');
    end if;
  end loop;
  return new;
exception when others then
  return new;
end $$;
revoke all on function interno.alumia_org_postou() from public;
drop trigger if exists alumia_org_postou on interno.rede_posts;
create trigger alumia_org_postou after insert on interno.rede_posts for each row execute function interno.alumia_org_postou();

-- ── 9. Extras do perfil de pessoa ─────────────────────────────────────────────────────────────────────────────────────────

/** Status (só enquanto vale), pronomes e campos de uma pessoa. Mesma regra de quem pode ver o perfil (invisível/bloqueio = nada). */
create or replace function public.rede_perfil_extras(p_handle text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); f perfis;
begin
  select * into f from perfis where rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  if not found or f.suspenso or ((f.rede_modo = 'invisivel' or f.rede_invisivel) and f.id is distinct from v) or interno.rede_bloqueado(v, f.id) then return null; end if;
  if v is null and not exists (select 1 from rede_orgs where perfil = f.id and verificada_em is not null) then return null; end if;
  return jsonb_build_object(
    'status', case when f.rede_status_tipo is not null and (f.rede_status_ate is null or f.rede_status_ate > now())
                then jsonb_build_object('tipo', f.rede_status_tipo, 'texto', coalesce(f.rede_status_texto, ''), 'ate', f.rede_status_ate) end,
    'pronomes', nullif(f.rede_pronomes, ''),
    'campos', coalesce((select jsonb_agg(jsonb_build_object('rotulo', c.rotulo, 'valor', c.valor) order by c.ordem) from rede_perfil_campos c where c.usuario = f.id), '[]'::jsonb),
    'destaques', '[]'::jsonb);
end $$;

/** Editar os meus extras. Campos: até 4 (substitui todos). Status: some sozinho depois de `horas` (1 a 720). */
create or replace function public.rede_perfil_extras_editar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c jsonb; i integer := 0;
begin
  perform interno.rede3_perfil_exige_membro(v);
  perform interno.limite('alumia_perfil_extras', 30, 60);
  if p ? 'status' then
    if jsonb_typeof(p -> 'status') = 'object' then
      if coalesce(p -> 'status' ->> 'tipo', '') not in ('greve', 'ato', 'estudando', 'cuidando', 'ferias')
         or char_length(coalesce(p -> 'status' ->> 'texto', '')) > 60
         or coalesce((p -> 'status' ->> 'horas')::integer, 0) not between 1 and 720 then
        perform interno.erro('invalido:status');
      end if;
      update perfis set rede_status_tipo = p -> 'status' ->> 'tipo', rede_status_texto = btrim(coalesce(p -> 'status' ->> 'texto', '')),
        rede_status_ate = now() + make_interval(hours => (p -> 'status' ->> 'horas')::integer) where id = v;
    else
      update perfis set rede_status_tipo = null, rede_status_texto = null, rede_status_ate = null where id = v;
    end if;
  end if;
  if p ? 'pronomes' then
    if char_length(coalesce(p ->> 'pronomes', '')) > 30 then perform interno.erro('invalido:pronomes'); end if;
    update perfis set rede_pronomes = nullif(btrim(coalesce(p ->> 'pronomes', '')), '') where id = v;
  end if;
  if jsonb_typeof(p -> 'campos') = 'array' then
    if jsonb_array_length(p -> 'campos') > 4 then perform interno.erro('invalido:campos'); end if;
    delete from rede_perfil_campos where usuario = v;
    for c in select value from jsonb_array_elements(p -> 'campos') loop
      i := i + 1;
      begin
        insert into rede_perfil_campos (usuario, ordem, rotulo, valor) values (v, i, btrim(coalesce(c ->> 'rotulo', '')), btrim(coalesce(c ->> 'valor', '')));
      exception when check_violation then perform interno.erro('invalido:campos');
      end;
    end loop;
  end if;
  return public.rede_perfil_extras((select rede_handle from perfis where id = v));
end $$;

-- ── 10. Permissões das funções ────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare f text;
begin
  foreach f in array array[
    'public.rede_org_perfil(text)', 'public.rede_org_ao_vivo()', 'public.rede_org_sino(text, boolean)', 'public.rede_org_nucleo_entrar(uuid)',
    'public.rede_org_consulta_votar(uuid, uuid[])', 'public.rede_org_plenaria_perguntar(uuid, text, boolean)', 'public.rede_org_pedir_selo(jsonb)',
    'public.rede_org_criar(uuid, uuid, jsonb)', 'public.rede_org_selo_fila()', 'public.rede_org_selo_decidir(uuid, boolean, text)',
    'public.rede_org_selo_tirar(text, text)', 'public.rede_org_gestor_adicionar(text, text)', 'public.rede_org_gestor_remover(text, text)',
    'public.rede_org_gestor_sair(text)', 'public.rede_org_votacao_registrar(text, jsonb)', 'public.rede_org_nucleo_criar(text, jsonb)',
    'public.rede_org_nucleo_pedidos(text)', 'public.rede_org_nucleo_decidir(uuid, text, boolean)', 'public.rede_org_consulta_abrir(text, jsonb)',
    'public.rede_org_plenaria_abrir(text, jsonb)', 'public.rede_org_plenaria_mudar(uuid, text, text)', 'public.rede_org_plenaria_responder(uuid)',
    'public.rede_org_plenaria_retirar(uuid, text)', 'public.rede_perfil_extras(text)', 'public.rede_perfil_extras_editar(jsonb)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon, authenticated', f);
    end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    -- Visitante: só o que a matriz deixa ver (perfil com selo, ao vivo das com selo, extras de organização com selo).
    grant execute on function public.rede_org_perfil(text), public.rede_org_ao_vivo(), public.rede_perfil_extras(text) to anon;
    grant execute on function public.rede_org_perfil(text), public.rede_org_ao_vivo(), public.rede_org_sino(text, boolean), public.rede_org_nucleo_entrar(uuid),
      public.rede_org_consulta_votar(uuid, uuid[]), public.rede_org_plenaria_perguntar(uuid, text, boolean), public.rede_org_pedir_selo(jsonb),
      public.rede_org_selo_fila(), public.rede_org_selo_decidir(uuid, boolean, text), public.rede_org_selo_tirar(text, text),
      public.rede_org_gestor_adicionar(text, text), public.rede_org_gestor_remover(text, text), public.rede_org_gestor_sair(text),
      public.rede_org_votacao_registrar(text, jsonb), public.rede_org_nucleo_criar(text, jsonb), public.rede_org_nucleo_pedidos(text),
      public.rede_org_nucleo_decidir(uuid, text, boolean), public.rede_org_consulta_abrir(text, jsonb), public.rede_org_plenaria_abrir(text, jsonb),
      public.rede_org_plenaria_mudar(uuid, text, text), public.rede_org_plenaria_responder(uuid), public.rede_org_plenaria_retirar(uuid, text),
      public.rede_perfil_extras(text), public.rede_perfil_extras_editar(jsonb) to authenticated;
    -- Só o servidor transforma a conta nova em organização.
    grant execute on function public.rede_org_criar(uuid, uuid, jsonb) to service_role;
  end if;
end $$;

-- ═══════════════════════════ fim da F4 ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda 5 · F5 · stories de 24 h (09/11/2026) ═══════════════════════════
-- docs/plano-2026-11/PLANO-ALUMIA.md, seções 5 (F5), 6.4, 7.2 e 8 (F5). O back-end mínimo para cada função da tela funcionar de
-- verdade: publicar, a faixa, abrir, apagar, responder, reagir, votar na enquete, "me avise", os atos da contagem e denunciar; o
-- depósito privado rede-stories; e a faxina de 15 em 15 minutos (pg_cron → Edge Function supabase/functions/faxina-stories).
-- As funções têm os nomes que o front-end já chama (lib/rede/cliente-stories.ts).
--
-- Depende da F0 (20261109-alumia-f0-contrato.sql: alvo 'story' nas denúncias e na moderação, aviso 'story_resposta').
-- Idempotente: pode rodar duas vezes (scripts/testar-alumia-f5.mjs roda duas vezes no banco local). NÃO está no install.sql (o
-- integrador cola depois da F4) e NÃO roda em produção sem o Jonathan.
--
-- Regras (PLANO §5): tudo em `interno`, RLS ligada e nenhuma permissão direta para anon/authenticated; acesso só por função
-- security definer com search_path = interno, pg_temp, que confere quem chama (interno.eu, rede2_membro, bloqueio) e limita o uso
-- (interno.limite / rede2_limite).
--
-- Privacidade (leis conferidas no texto, leis-do-brasil):
--   * LGPD (Lei 13.709/2018) art. 5º, II e art. 11: o que alguém viu, votou ou a que reagiu numa rede militante revela opinião
--     política, dado sensível. Por isso NÃO existe tabela, coluna nem contagem de quem viu (nem "quantos viram"); o voto da enquete
--     é secreto e a autora vê só a soma, a partir de 3 votos; a reação chega à autora sem o nome de quem reagiu.
--   * LGPD art. 6º, III (necessidade): o voto não guarda hora; a resposta e a reação somem com o story (cascata, e o aviso que
--     levou a resposta sai junto); o arquivo sai do depósito pela faxina; nada de GPS (o aparelho refaz a imagem sem EXIF e a
--     faxina confere de novo no servidor, tirando EXIF/XMP/texto que tenha sobrado).
--   * ECA (Lei 8.069/1990) e ECA Digital (Lei 15.211/2025) art. 9º § 1º: a Alumia é só 18+; só membro (rede2_membro: 18 anos
--     declarados e consentimento em vigor) publica, vê, responde ou vota. Denúncia de "menores" retém o story na hora.
--   * Marco Civil (Lei 12.965/2014) art. 15: nada aqui grava IP. A prova de um story denunciado fica no banco e no depósito
--     privado até a decisão da moderação, mesmo depois das 24 h (PLANO §7.2); decidida a denúncia, a faxina apaga.
--   * Stories nunca federam (PLANO §6.8): nada daqui entra nas tabelas rede_fed_*.

-- ── 1. Tabelas ────────────────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.rede_stories (
  id uuid primary key default gen_random_uuid(),
  autor uuid not null references interno.perfis (id) on delete cascade,
  -- A identidade que publicou é SEMPRE a própria autora (o dono de uma identidade nunca fica gravado aqui, PLANO §6.6).
  como uuid references interno.perfis (id) on delete cascade,
  publico text not null default 'seguidores' check (publico in ('seguidores', 'membros', 'proximos')),
  fundo text not null default 'listras' check (fundo in ('listras', 'mosaico', 'imagem')),
  cor text not null default 'azul' check (cor in ('azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite')),
  texto text not null default '' check (char_length(texto) <= 140),
  legenda text check (legenda is null or char_length(legenda) between 1 and 80),
  -- "<uid>/<id>.<ext>" no depósito privado rede-stories; o arquivo só é lido por rede_story_pode (a mesma regra da tela).
  midia_caminho text unique check (midia_caminho is null or midia_caminho ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f-]{32,36}\.(webp|png|jpg)$'),
  alt text check (alt is null or char_length(alt) <= 200),
  post_ref uuid references interno.rede_posts (id) on delete set null,
  -- Retido por denúncia urgente: some para todos menos a autora e a faxina guarda a prova até a decisão.
  retido boolean not null default false,
  -- A faxina já conferiu o arquivo no servidor (sem EXIF/XMP). Story só de texto nasce conferido.
  conferido boolean not null default false,
  expira_em timestamptz not null default now() + interval '24 hours',
  criado_em timestamptz not null default now(),
  constraint rede_stories_como_autor check (como is null or como = autor),
  constraint rede_stories_imagem check ((fundo = 'imagem') = (midia_caminho is not null)),
  constraint rede_stories_24h check (expira_em <= criado_em + interval '24 hours')
);
create index if not exists rede_stories_autor on interno.rede_stories (autor, expira_em);
create index if not exists rede_stories_expira on interno.rede_stories (expira_em);

-- No máximo 3 figurinhas por story (ordem 0..2); os dados já vêm limpos pela função de publicar.
create table if not exists interno.rede_story_figurinhas (
  story uuid not null references interno.rede_stories (id) on delete cascade,
  ordem smallint not null check (ordem between 0 and 2),
  tipo text not null check (tipo in ('contagem', 'pergunta', 'enquete', 'link')),
  dados jsonb not null default '{}'::jsonb check (jsonb_typeof(dados) = 'object' and pg_column_size(dados) <= 2048),
  primary key (story, ordem)
);

-- Resposta: vai SÓ para a autora (num aviso dela) e some com o story; `aviso` liga a resposta ao aviso para os dois sumirem juntos.
create table if not exists interno.rede_story_respostas (
  id uuid primary key default gen_random_uuid(),
  story uuid not null references interno.rede_stories (id) on delete cascade,
  quem uuid not null references interno.perfis (id) on delete cascade,
  texto text not null check (char_length(texto) between 1 and 500),
  aviso uuid references interno.avisos (id) on delete set null,
  criado_em timestamptz not null default now()
);
create index if not exists rede_story_respostas_story on interno.rede_story_respostas (story);
create index if not exists rede_story_respostas_quem on interno.rede_story_respostas (quem, criado_em);

-- Reação do conjunto fechado (PLANO §6.3): uma por pessoa e story; a autora recebe "Alguém reagiu…", sem o nome.
create table if not exists interno.rede_story_reacoes (
  story uuid not null references interno.rede_stories (id) on delete cascade,
  quem uuid not null references interno.perfis (id) on delete cascade,
  reacao text not null check (reacao in ('punho', 'chama', 'coracao')),
  aviso uuid references interno.avisos (id) on delete set null,
  primary key (story, quem)
);

-- Voto secreto na enquete (uma por story): sem hora (LGPD art. 6º, III); ninguém lê a linha, só a soma sai, e só para a autora.
create table if not exists interno.rede_story_votos (
  story uuid not null references interno.rede_stories (id) on delete cascade,
  quem uuid not null references interno.perfis (id) on delete cascade,
  opcao smallint not null check (opcao in (0, 1)),
  primary key (story, quem)
);

-- "Me avise quando começar": um lembrete MEU do ato (nem a autora do story nem quem organiza o ato sabe quem pediu).
create table if not exists interno.rede_story_lembretes (
  ato uuid not null references interno.rede_posts (id) on delete cascade,
  quem uuid not null references interno.perfis (id) on delete cascade,
  primary key (ato, quem)
);

do $$
declare t text;
begin
  foreach t in array array['rede_stories', 'rede_story_figurinhas', 'rede_story_respostas', 'rede_story_reacoes', 'rede_story_votos', 'rede_story_lembretes'] loop
    execute format('alter table interno.%I enable row level security', t);
    execute format('revoke all on table interno.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on table interno.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- O aviso que levou a resposta (ou a reação) sai quando a resposta sai: apagar o story, a faxina ou a conta de quem respondeu.
create or replace function interno.rede5_story_tirar_aviso() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if old.aviso is not null then delete from avisos where id = old.aviso; end if;
  return null;
end $$;
drop trigger if exists rede5_story_tirar_aviso on interno.rede_story_respostas;
create trigger rede5_story_tirar_aviso after delete on interno.rede_story_respostas for each row execute function interno.rede5_story_tirar_aviso();
drop trigger if exists rede5_story_tirar_aviso on interno.rede_story_reacoes;
create trigger rede5_story_tirar_aviso after delete on interno.rede_story_reacoes for each row execute function interno.rede5_story_tirar_aviso();

-- ── 2. Regras internas ────────────────────────────────────────────────────────────────────────────────────────────────────

/** A coordenação desligou os stories pelo painel? (A flag da montagem só esconde a tela; esta trava vale também para a API.) */
create or replace function interno.rede5_story_ligado() returns void language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if exists (select 1 from recursos_vivos where nome in ('rede-v2', 'alumia-2', 'alumia-stories') and not ligado) then
    perform interno.erro('recurso_desligado');
  end if;
end $$;

/**
 * Esta pessoa pode ver este story? Uma regra só, para a tela, o depósito e cada ação (responder, reagir, votar, denunciar).
 * A autora vê o seu enquanto está no ar (retido também). Os outros: membro da Alumia, autora ainda membro, sem bloqueio em
 * nenhum sentido, no ar, não retido, e o público: seguidores (segue aceito), membros (quem é da Alumia) ou próximos (seguem um ao
 * outro). Visitante nunca vê (nenhum público é "internet").
 */
create or replace function interno.rede5_story_ve(s interno.rede_stories, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select s.id is not null and p_quem is not null and s.expira_em > now() and (
    s.autor = p_quem
    or (not s.retido
        and interno.rede2_membro(p_quem) and interno.rede2_membro(s.autor)
        and not interno.rede_bloqueado(p_quem, s.autor)
        and case s.publico
          when 'membros' then true
          when 'seguidores' then exists (select 1 from rede_seguindo g where g.quem = p_quem and g.segue = s.autor and not g.pendente)
          when 'proximos' then exists (select 1 from rede_seguindo g where g.quem = p_quem and g.segue = s.autor and not g.pendente)
                           and exists (select 1 from rede_seguindo g where g.quem = s.autor and g.segue = p_quem and not g.pendente)
          else false end))
$$;

/** A autora como aparece: @handle, codinome (nunca nome civil) e uma cor de 1 a 5 tirada do id (não diz nada sobre ela). */
create or replace function interno.rede5_story_autora(p_autor uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('handle', f.rede_handle, 'nome', interno.rede_nome(f.id), 'cor', (abs(hashtext(f.id::text)) % 5) + 1)
  from perfis f where f.id = p_autor
$$;

/** Uma figurinha como `p_quem` a vê (a soma da enquete só para a autora, e só a partir de 3 votos). */
create or replace function interno.rede5_story_figurinha(f interno.rede_story_figurinhas, s interno.rede_stories, p_quem uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_ato uuid; p rede_posts; v_n0 integer; v_n1 integer;
begin
  if f.tipo = 'contagem' then
    begin v_ato := (f.dados ->> 'ato')::uuid; exception when others then v_ato := null; end;
    if v_ato is not null then
      select * into p from rede_posts where id = v_ato;
      if not found or not interno.rede2_pode_ver(p, p_quem) then v_ato := null; end if;
    end if;
    return jsonb_build_object('tipo', 'contagem', 'ato', v_ato, 'titulo', f.dados ->> 'titulo', 'inicio', f.dados ->> 'inicio',
      'avisar', v_ato is not null and exists (select 1 from rede_story_lembretes l where l.ato = v_ato and l.quem = p_quem));
  elsif f.tipo = 'pergunta' then
    return jsonb_build_object('tipo', 'pergunta', 'texto', f.dados ->> 'texto');
  elsif f.tipo = 'enquete' then
    if s.autor = p_quem then
      select count(*) filter (where opcao = 0)::integer, count(*) filter (where opcao = 1)::integer into v_n0, v_n1 from rede_story_votos where story = s.id;
    end if;
    return jsonb_build_object('tipo', 'enquete', 'pergunta', f.dados ->> 'pergunta', 'opcoes', f.dados -> 'opcoes',
      'meu_voto', (select v.opcao from rede_story_votos v where v.story = s.id and v.quem = p_quem and s.autor <> p_quem),
      'soma', case when s.autor = p_quem and v_n0 + v_n1 >= 3 then jsonb_build_array(v_n0, v_n1) end);
  else
    return jsonb_build_object('tipo', 'link', 'url', f.dados ->> 'url', 'rotulo', f.dados ->> 'rotulo');
  end if;
end $$;

/** O story inteiro como `p_quem` o vê. O caminho da imagem volta cru: o aparelho pede o endereço assinado ao depósito. */
create or replace function interno.rede5_story_json(s interno.rede_stories, p_quem uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', s.id, 'autora', interno.rede5_story_autora(s.autor), 'criado_em', s.criado_em, 'expira_em', s.expira_em, 'publico', s.publico,
    'fundo', case when s.fundo = 'imagem' then jsonb_build_object('tipo', 'imagem', 'cor', s.cor, 'caminho', s.midia_caminho, 'url', '', 'alt', coalesce(s.alt, ''))
                  else jsonb_build_object('tipo', s.fundo, 'cor', s.cor) end,
    'texto', s.texto, 'legenda', s.legenda, 'meu', s.autor = p_quem,
    'figurinhas', coalesce((select jsonb_agg(interno.rede5_story_figurinha(f, s, p_quem) order by f.ordem) from rede_story_figurinhas f where f.story = s.id), '[]'::jsonb))
$$;

/** O story vai ficar como prova? (há denúncia ainda aberta sobre ele: a faxina não apaga, PLANO §7.2) */
create or replace function interno.rede5_story_em_prova(p_id uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_denuncias d where d.alvo_tipo = 'story' and d.alvo = p_id::text and d.situacao in ('aberta', 'em_analise'))
$$;

/** Um story que esta pessoa vê, ou o erro "nao_encontrado" (o mesmo para "não existe" e "não pode ver": não confirma nada). */
create or replace function interno.rede5_story_visivel(p_id uuid, p_quem uuid) returns interno.rede_stories language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare s rede_stories;
begin
  select * into s from rede_stories where id = p_id;
  if not found or not interno.rede5_story_ve(s, p_quem) then perform interno.erro('nao_encontrado'); end if;
  return s;
end $$;

/** Quem chama é membro da Alumia (18+, consentimento em vigor) e os stories estão ligados. Devolve o id. */
create or replace function interno.rede5_story_membro() returns uuid language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.aberta('comunidade');
  perform interno.rede5_story_ligado();
  if not interno.rede2_membro(v) then perform interno.erro('sem_permissao'); end if;
  return v;
end $$;

-- ── 3. Leitura ────────────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * As bolinhas do alto da linha: os ids dos MEUS stories no ar e, de quem eu sigo, os que eu posso ver (até 60 pessoas, a mais
 * nova primeiro). Abrir não grava nada: o "já vi" fica só no aparelho. Visitante recebe a faixa vazia.
 */
create or replace function public.rede_story_faixa() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  if v is null or not interno.rede2_membro(v) then return jsonb_build_object('meus', '[]'::jsonb, 'grupos', '[]'::jsonb); end if;
  perform interno.rede5_story_ligado();
  return jsonb_build_object(
    'meus', coalesce((select jsonb_agg(s.id order by s.criado_em) from rede_stories s where s.autor = v and s.expira_em > now()), '[]'::jsonb),
    'grupos', coalesce((
      select jsonb_agg(jsonb_build_object('autora', interno.rede5_story_autora(g.autor), 'ids', g.ids, 'ultimo_em', g.ultimo) order by g.ultimo desc)
      from (
        select s.autor, jsonb_agg(s.id order by s.criado_em) as ids, max(s.criado_em) as ultimo
        from rede_seguindo seg join rede_stories s on s.autor = seg.segue
        join perfis f on f.id = s.autor and f.rede_handle is not null
        where seg.quem = v and not seg.pendente and interno.rede5_story_ve(s, v)
        group by s.autor order by max(s.criado_em) desc limit 60) g), '[]'::jsonb));
end $$;

/** Os stories no ar de uma pessoa (@handle), do mais antigo ao mais novo, só os que eu posso ver. Leitura pura (nada de "visto"). */
create or replace function public.rede_story_abrir(p_handle text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_autor uuid;
begin
  if v is null or not interno.rede2_membro(v) then return '[]'::jsonb; end if;
  perform interno.rede5_story_ligado();
  if coalesce(p_handle, '') !~ '^[a-z0-9_]{3,20}$' then perform interno.erro('invalido:handle'); end if;
  select id into v_autor from perfis where rede_handle = p_handle;
  if not found then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(interno.rede5_story_json(s, v) order by s.criado_em)
    from rede_stories s where s.autor = v_autor and interno.rede5_story_ve(s, v)), '[]'::jsonb);
end $$;

/** Os MEUS stories no ar (retido também, com a soma das enquetes a partir de 3). */
create or replace function public.rede_story_meus() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  perform interno.rede5_story_ligado();
  return coalesce((select jsonb_agg(interno.rede5_story_json(s, v) order by s.criado_em) from rede_stories s where s.autor = v and s.expira_em > now()), '[]'::jsonb);
end $$;

/** Os próximos atos que eu organizo ou confirmei e que posso pôr numa contagem (sem número de ninguém). */
create or replace function public.rede_story_atos() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro();
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'titulo', x.titulo, 'inicio', x.inicio) order by x.inicio)
    from (select p.id, left(coalesce(nullif(btrim(p.titulo), ''), btrim(p.texto)), 60) as titulo, c.inicio
          from rede_chamados c join rede_posts p on p.id = c.post
          where c.inicio > now() and not c.cancelado and interno.rede2_pode_ver(p, v)
            and (p.autor = v or exists (select 1 from rede_vou u where u.post = p.id and u.usuario = v))
          order by c.inicio limit 20) x), '[]'::jsonb);
end $$;

-- ── 4. Publicar e apagar ──────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Publica um story (o pedido de lib/rede/tipos-stories.ts, PedidoDeStory). Confere tudo de novo: público, fundo, tamanhos, dado
 * pessoal (CPF, telefone, e-mail, endereço: LGPD art. 6º, III), até 3 figurinhas (uma enquete e uma contagem no máximo; link só
 * https; a contagem só com ato que eu organizo ou confirmei, e o título e a hora vêm do ato, não do pedido), a imagem só da
 * minha pasta, já enviada, em WEBP/PNG/JPEG e até 3 MB, e o post do "Pôr no story" só se eu o vejo. 20 stories por dia.
 */
create or replace function public.rede_story_publicar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.rede5_story_membro();
  v_publico text := coalesce(p ->> 'publico', 'seguidores');
  v_fundo text := coalesce(p -> 'fundo' ->> 'tipo', 'listras');
  v_cor text := coalesce(p -> 'fundo' ->> 'cor', 'azul');
  v_texto text; v_legenda text; v_alt text; v_imagem text := nullif(btrim(coalesce(p ->> 'imagem', '')), '');
  v_post uuid; pr rede_posts; v_figs jsonb := coalesce(p -> 'figurinhas', '[]'::jsonb);
  f jsonb; v_tipo text; v_limpas jsonb := '[]'::jsonb; v_tudo text := ''; v_ato uuid; v_titulo text; v_inicio timestamptz;
  v_url text; v_rotulo text; v_perg text; v_op0 text; v_op1 text; v_enquetes integer := 0; v_contagens integer := 0;
  v_tam bigint; v_mime text; s rede_stories; i integer := 0;
begin
  if p is null or jsonb_typeof(p) is distinct from 'object' then perform interno.erro('invalido:pedido'); end if;
  if v_publico not in ('seguidores', 'membros', 'proximos') then perform interno.erro('invalido:publico'); end if;
  if v_fundo not in ('listras', 'mosaico', 'imagem') then perform interno.erro('invalido:fundo'); end if;
  if v_cor not in ('azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite') then perform interno.erro('invalido:cor'); end if;
  if not exists (select 1 from perfis where id = v and rede_handle is not null) then perform interno.erro('sem_handle'); end if;
  v_texto := interno.txt(p ->> 'texto', 'texto', 0, 140);
  v_legenda := nullif(interno.txt(p ->> 'legenda', 'legenda', 0, 80), '');
  v_alt := nullif(interno.txt(p ->> 'alt', 'alt', 0, 200), '');
  if jsonb_typeof(v_figs) is distinct from 'array' or jsonb_array_length(v_figs) > 3 then perform interno.erro('invalido:figurinhas'); end if;

  -- A imagem: o fundo "imagem" exige o caminho, e o caminho só vale com fundo "imagem".
  if (v_fundo = 'imagem') <> (v_imagem is not null) then perform interno.erro('invalido:imagem'); end if;
  if v_imagem is not null then
    if v_imagem !~ ('^' || v::text || '/[0-9a-f-]{32,36}\.(webp|png|jpg)$') then perform interno.erro('invalido:imagem'); end if;
    if exists (select 1 from rede_stories where midia_caminho = v_imagem) then perform interno.erro('invalido:imagem'); end if;
    if to_regclass('storage.objects') is not null then
      execute 'select (metadata ->> ''size'')::bigint, metadata ->> ''mimetype'' from storage.objects where bucket_id = ''rede-stories'' and name = $1'
        into v_tam, v_mime using v_imagem;
      if v_mime is null then perform interno.erro('invalido:imagem'); end if;
      if v_mime not in ('image/webp', 'image/png', 'image/jpeg') or coalesce(v_tam, 0) > 3145728 then perform interno.erro('invalido:imagem'); end if;
    end if;
  else
    v_alt := null;
  end if;

  -- "Pôr no story": só um post que eu vejo.
  if nullif(p ->> 'post_ref', '') is not null then
    begin v_post := (p ->> 'post_ref')::uuid; exception when others then perform interno.erro('invalido:post'); end;
    select * into pr from rede_posts where id = v_post;
    if not found or not interno.rede2_pode_ver(pr, v) then perform interno.erro('nao_encontrado'); end if;
  end if;

  for f in select * from jsonb_array_elements(v_figs) loop
    v_tipo := f ->> 'tipo';
    if v_tipo = 'contagem' then
      v_contagens := v_contagens + 1;
      begin v_ato := (f ->> 'ato')::uuid; exception when others then v_ato := null; end;
      if v_ato is null then perform interno.erro('invalido:contagem'); end if;
      select left(coalesce(nullif(btrim(x.titulo), ''), btrim(x.texto)), 60), c.inicio into v_titulo, v_inicio
      from rede_chamados c join rede_posts x on x.id = c.post
      where c.post = v_ato and c.inicio > now() and not c.cancelado and interno.rede2_pode_ver(x, v)
        and (x.autor = v or exists (select 1 from rede_vou u where u.post = x.id and u.usuario = v));
      if not found then perform interno.erro('invalido:contagem'); end if;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'contagem', 'dados', jsonb_build_object('ato', v_ato, 'titulo', v_titulo, 'inicio', v_inicio));
    elsif v_tipo = 'pergunta' then
      v_perg := interno.txt(f ->> 'texto', 'pergunta', 1, 90);
      v_tudo := v_tudo || E'\n' || v_perg;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'pergunta', 'dados', jsonb_build_object('texto', v_perg));
    elsif v_tipo = 'enquete' then
      v_enquetes := v_enquetes + 1;
      if jsonb_typeof(f -> 'opcoes') is distinct from 'array' or jsonb_array_length(f -> 'opcoes') <> 2 then perform interno.erro('invalido:enquete'); end if;
      v_perg := interno.txt(f ->> 'pergunta', 'pergunta', 1, 90);
      v_op0 := interno.txt(f -> 'opcoes' ->> 0, 'opcao', 1, 24);
      v_op1 := interno.txt(f -> 'opcoes' ->> 1, 'opcao', 1, 24);
      if lower(v_op0) = lower(v_op1) then perform interno.erro('invalido:opcao'); end if;
      v_tudo := v_tudo || E'\n' || v_perg || E'\n' || v_op0 || E'\n' || v_op1;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'enquete', 'dados', jsonb_build_object('pergunta', v_perg, 'opcoes', jsonb_build_array(v_op0, v_op1)));
    elsif v_tipo = 'link' then
      v_url := btrim(coalesce(f ->> 'url', ''));
      if v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(:[0-9]{2,5})?(/[^\s<>"]*)?$' or char_length(v_url) > 300 then perform interno.erro('invalido:link'); end if;
      v_rotulo := interno.txt(f ->> 'rotulo', 'rotulo', 1, 40);
      v_tudo := v_tudo || E'\n' || v_rotulo;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'link', 'dados', jsonb_build_object('url', v_url, 'rotulo', v_rotulo));
    else
      perform interno.erro('invalido:figurinha');
    end if;
  end loop;
  if v_enquetes > 1 or v_contagens > 1 then perform interno.erro('invalido:figurinhas'); end if;
  if v_texto = '' and v_imagem is null and jsonb_array_length(v_limpas) = 0 then perform interno.erro('invalido:vazio'); end if;
  if interno.rede3_pub_dado_pessoal(v_texto || E'\n' || coalesce(v_legenda, '') || v_tudo) then perform interno.erro('dado_pessoal'); end if;

  perform interno.limite('rede5_story_publicar', 20, 1440);
  insert into rede_stories (autor, publico, fundo, cor, texto, legenda, midia_caminho, alt, post_ref, conferido)
  values (v, v_publico, v_fundo, v_cor, v_texto, v_legenda, v_imagem, v_alt, v_post, v_imagem is null)
  returning * into s;
  for f in select * from jsonb_array_elements(v_limpas) loop
    insert into rede_story_figurinhas (story, ordem, tipo, dados) values (s.id, i, f ->> 'tipo', f -> 'dados');
    i := i + 1;
  end loop;
  return jsonb_build_object('id', s.id, 'expira_em', s.expira_em);
end $$;

/**
 * Apagar o meu story: some na hora para todo mundo, com as respostas e as reações (e os avisos que as levaram). Se há denúncia
 * aberta sobre ele, a linha e o arquivo ficam guardados como prova até a decisão (PLANO §7.2), mas já fora do ar.
 */
create or replace function public.rede_story_apagar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); s rede_stories;
begin
  perform interno.rede5_story_ligado();
  perform interno.limite('rede5_story_apagar', 60, 60);
  select * into s from rede_stories where id = p_id and autor = v;
  if not found then perform interno.erro('nao_encontrado'); end if;
  delete from avisos a where a.id in (select r.aviso from rede_story_respostas r where r.story = s.id and r.aviso is not null
                                      union select x.aviso from rede_story_reacoes x where x.story = s.id and x.aviso is not null);
  if s.retido or interno.rede5_story_em_prova(s.id) then
    update rede_stories set expira_em = least(expira_em, now()) where id = s.id;
  else
    -- A linha sai agora; o arquivo, sem dono, sai do depósito na próxima faxina (e ninguém mais o lê: rede_story_pode).
    delete from rede_stories where id = s.id;
  end if;
  return jsonb_build_object('apagado', true);
end $$;

-- ── 5. Responder, reagir, votar, "me avise" e denunciar ──────────────────────────────────────────────────────────────────

/** Resposta (texto livre ou à figurinha de pergunta): vai SÓ para a autora, num aviso dela, e some com o story. */
create or replace function public.rede_story_responder(p_id uuid, p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); s rede_stories; v_texto text := interno.txt(p_texto, 'texto', 1, 500); v_aviso uuid;
begin
  s := interno.rede5_story_visivel(p_id, v);
  if s.autor = v then perform interno.erro('sem_permissao'); end if;
  perform interno.rede2_limite('responder');
  perform interno.limite('rede5_story_responder', 10, 60);
  -- A autora desligou "respostas a stories" no site: a resposta não vira aviso nem fica guardada.
  if not interno.rede3_aviso_pref(s.autor, 'story_resposta', 'site') then return jsonb_build_object('ok', true); end if;
  insert into avisos (para, texto, categoria, ator)
  values (s.autor, left('Resposta ao seu story: “' || v_texto || '”', 500), 'rede', v) returning id into v_aviso;
  insert into rede_story_respostas (story, quem, texto, aviso) values (s.id, v, v_texto, v_aviso);
  return jsonb_build_object('ok', true);
end $$;

/** Reação do conjunto fechado: a autora recebe "Alguém reagiu…", sem o nome; reagir de novo troca a reação (sem somar avisos). */
create or replace function public.rede_story_reagir(p_id uuid, p_reacao text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); s rede_stories; r rede_story_reacoes; v_aviso uuid; v_texto text;
begin
  if p_reacao is null or p_reacao not in ('punho', 'chama', 'coracao') then perform interno.erro('invalido:reacao'); end if;
  s := interno.rede5_story_visivel(p_id, v);
  if s.autor = v then perform interno.erro('sem_permissao'); end if;
  perform interno.rede2_limite('reagir');
  v_texto := 'Alguém reagiu ao seu story com ' || case p_reacao when 'punho' then 'um punho erguido' when 'chama' then 'uma chama' else 'um coração' end || '.';
  select * into r from rede_story_reacoes where story = s.id and quem = v;
  if found then
    if r.reacao <> p_reacao then
      update rede_story_reacoes set reacao = p_reacao where story = s.id and quem = v;
      if r.aviso is not null then update avisos set texto = v_texto, lido = false where id = r.aviso; end if;
    end if;
    return jsonb_build_object('ok', true);
  end if;
  if interno.rede3_aviso_pref(s.autor, 'story_resposta', 'site') then
    insert into avisos (para, texto, categoria) values (s.autor, v_texto, 'rede') returning id into v_aviso;
  end if;
  insert into rede_story_reacoes (story, quem, reacao, aviso) values (s.id, v, p_reacao, v_aviso);
  return jsonb_build_object('ok', true);
end $$;

/** Voto secreto na enquete (um por pessoa; não muda depois). Devolve a figurinha como eu passo a ver (sem soma: só a autora vê). */
create or replace function public.rede_story_votar(p_id uuid, p_opcao integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); s rede_stories; f rede_story_figurinhas;
begin
  if p_opcao is null or p_opcao not in (0, 1) then perform interno.erro('invalido:opcao'); end if;
  s := interno.rede5_story_visivel(p_id, v);
  if s.autor = v then perform interno.erro('sem_permissao'); end if;
  select * into f from rede_story_figurinhas where story = s.id and tipo = 'enquete';
  if not found then perform interno.erro('nao_encontrado'); end if;
  perform interno.rede2_limite('votar');
  insert into rede_story_votos (story, quem, opcao) values (s.id, v, p_opcao) on conflict (story, quem) do nothing;
  return interno.rede5_story_figurinha(f, s, v);
end $$;

/** "Me avise quando começar": liga ou desliga o MEU lembrete do ato da figurinha de contagem. Ninguém sabe quem pediu. */
create or replace function public.rede_story_avisar(p_id uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); s rede_stories; v_ato uuid; p rede_posts;
begin
  s := interno.rede5_story_visivel(p_id, v);
  select (f.dados ->> 'ato')::uuid into v_ato from rede_story_figurinhas f where f.story = s.id and f.tipo = 'contagem';
  if v_ato is null then perform interno.erro('nao_encontrado'); end if;
  select * into p from rede_posts where id = v_ato;
  if not found or not interno.rede2_pode_ver(p, v) then perform interno.erro('nao_encontrado'); end if;
  perform interno.rede2_limite('salvar');
  if coalesce(p_sim, false) then
    if not exists (select 1 from rede_chamados c where c.post = v_ato and c.inicio > now() and not c.cancelado) then perform interno.erro('invalido:ato'); end if;
    insert into rede_story_lembretes (ato, quem) values (v_ato, v) on conflict do nothing;
  else
    delete from rede_story_lembretes where ato = v_ato and quem = v;
  end if;
  return jsonb_build_object('avisar', exists (select 1 from rede_story_lembretes where ato = v_ato and quem = v));
end $$;

/**
 * Denunciar um story que eu vejo. Quem denuncia nunca é revelado. Mesma pessoa e story com denúncia aberta: o mesmo protocolo.
 * Menores, ameaça e exposição (PLANO §7.2) retêm na hora: some para todos menos a autora, que é avisada e pode recorrer; e a prova
 * fica guardada até a decisão, mesmo depois das 24 h. O freio tem teto por conta (5 por dia), para a denúncia não virar arma.
 */
create or replace function public.rede_story_denunciar(p_id uuid, p_categoria text, p_texto text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.rede5_story_membro(); s rede_stories; d rede_denuncias; v_pri smallint; v_retido boolean := false;
  v_texto text := interno.txt(coalesce(p_texto, ''), 'texto', 0, 2000);
begin
  if p_categoria is null or p_categoria not in ('menores', 'ameaca', 'exposicao', 'violencia', 'autolesao', 'odio', 'assedio', 'golpe', 'spam', 'outro') then
    perform interno.erro('invalido:categoria');
  end if;
  -- A mesma pessoa denunciando de novo recebe o mesmo protocolo, mesmo que o story já tenha sido retido (e ela não o veja mais).
  select * into d from rede_denuncias where quem = v and alvo_tipo = 'story' and alvo = p_id::text and situacao in ('aberta', 'em_analise') limit 1;
  if found then return jsonb_build_object('protocolo', d.protocolo, 'retido', coalesce((select retido from rede_stories where id = p_id), false), 'ja', true); end if;
  s := interno.rede5_story_visivel(p_id, v);
  if s.autor = v then perform interno.erro('sem_permissao'); end if;
  perform interno.rede2_limite('denunciar');
  v_pri := interno.rede2_prioridade(p_categoria);
  insert into rede_denuncias (alvo_tipo, alvo, categoria, prioridade, texto, quem) values ('story', s.id::text, p_categoria, v_pri, v_texto, v) returning * into d;
  if p_categoria in ('menores', 'ameaca', 'exposicao') and not s.retido then
    begin
      perform interno.limite('rede5_story_precaucao', 5, 1440);
      update rede_stories set retido = true where id = s.id;
      perform interno.rede3_mod_registrar('reter', 'story', s.id::text, 'precaucao', 'Story retido por precaução até a moderação ler a denúncia ' || d.protocolo || '.', d.id, true);
      perform interno.rede3_mod_avisar_afetado(s.autor, 'Um story seu ficou retido por precaução enquanto a moderação lê uma denúncia (decisão automática, ainda sem leitura de uma pessoa). Só você o vê. Você pode recorrer em até 30 dias, em Denúncias e recursos.');
      v_retido := true;
    exception when others then
      v_retido := false;
    end;
  end if;
  if v_pri = 1 then
    insert into avisos (para, texto)
    select distinct pa.usuario, left('Denúncia prioritária ' || d.protocolo || ' (story, ' || p_categoria || '). Abra a fila de moderação da Rede.', 500)
    from papeis pa where pa.papel in ('coordenacao', 'vice', 'mediacao') and pa.usuario <> v;
  end if;
  return jsonb_build_object('protocolo', d.protocolo, 'retido', v_retido, 'ja', false);
end $$;

-- ── 6. Depósito privado rede-stories ──────────────────────────────────────────────────────────────────────────────────────

/** Regra de leitura do depósito: o arquivo deste caminho é de um story que quem pede pode ver (a mesma regra da tela). */
create or replace function public.rede_story_pode(p_caminho text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_stories s where s.midia_caminho = p_caminho and interno.rede5_story_ve(s, auth.uid()))
$$;

/** Regra de envio: membro da Alumia, stories ligados, e no máximo 30 arquivos nas últimas 24 h na própria pasta. */
create or replace function public.rede_story_pode_enviar() returns boolean language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_n integer := 0;
begin
  if v is null or not interno.rede2_membro(v) then return false; end if;
  if exists (select 1 from recursos_vivos where nome in ('rede-v2', 'alumia-2', 'alumia-stories') and not ligado) then return false; end if;
  if to_regclass('storage.objects') is not null then
    execute 'select count(*)::integer from storage.objects where bucket_id = ''rede-stories'' and name like $1 and created_at > now() - interval ''24 hours'''
      into v_n using v::text || '/%';
  end if;
  return v_n < 30;
end $$;

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') and to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('rede-stories', 'rede-stories', false, 3145728, array['image/webp', 'image/png', 'image/jpeg'])
    on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
    execute 'drop policy if exists "rede_stories_envio" on storage.objects';
    execute 'create policy "rede_stories_envio" on storage.objects for insert to authenticated with check (bucket_id = ''rede-stories'' and (storage.foldername(name))[1] = auth.uid()::text and public.rede_story_pode_enviar())';
    execute 'drop policy if exists "rede_stories_leitura" on storage.objects';
    execute 'create policy "rede_stories_leitura" on storage.objects for select to authenticated using (bucket_id = ''rede-stories'' and ((storage.foldername(name))[1] = auth.uid()::text or public.rede_story_pode(name)))';
    execute 'drop policy if exists "rede_stories_remocao" on storage.objects';
    execute 'create policy "rede_stories_remocao" on storage.objects for delete to authenticated using (bucket_id = ''rede-stories'' and (storage.foldername(name))[1] = auth.uid()::text)';
  end if;
end $$;

-- ── 7. Faxina (de 15 em 15 minutos) ───────────────────────────────────────────────────────────────────────────────────────
-- O que o banco faz sozinho: tira da tabela os stories vencidos SEM arquivo (que não estejam em prova) e manda os lembretes de
-- ato. O que tem arquivo precisa da Edge Function faxina-stories, que apaga o arquivo pela API do Storage e só DEPOIS a linha
-- (apagar só a linha de storage.objects por SQL deixaria o arquivo no depósito, como a doc do Supabase avisa); ela também
-- confere as imagens novas (tira EXIF/XMP que tenha sobrado) e leva os arquivos sem story (envio abandonado há mais de 1 hora).
-- O endereço da função fica nas configurações, como o dos e-mails (interno.emails_disparar), definido uma vez pelo Jonathan:
--   insert into interno.configuracoes (chave, valor) values ('stories', '{"funcao": "https://SEU-PROJETO.supabase.co/functions/v1/faxina-stories", "chave_publica": "eyJ...", "segredo": "..."}')
--   on conflict (chave) do update set valor = excluded.valor;
-- Sem o endereço, ou sem pg_net, as funções de leitura continuam filtrando expira_em > now(): nada vencido aparece, só fica guardado.

/** Os lembretes de "me avise": ato começando em até 1 hora vira aviso (e o lembrete sai); ato cancelado ou já começado, só sai. */
create or replace function interno.rede5_story_lembretes() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare r record; v_n integer := 0;
begin
  for r in select l.ato, l.quem from rede_story_lembretes l join rede_chamados c on c.post = l.ato
           where c.inicio > now() and c.inicio <= now() + interval '1 hour' and not c.cancelado limit 2000 loop
    perform interno.rede3_aviso_criar(r.quem, 'chamado', r.ato, null, null, 'Um ato que você pediu para lembrar começa em menos de 1 hora.');
    delete from rede_story_lembretes where ato = r.ato and quem = r.quem;
    v_n := v_n + 1;
  end loop;
  delete from rede_story_lembretes l using rede_chamados c where c.post = l.ato and (c.inicio <= now() or c.cancelado);
  delete from rede_story_lembretes l where not exists (select 1 from rede_chamados c where c.post = l.ato);
  return v_n;
end $$;

/** A rodada do banco (pg_cron): lembretes, vencidos sem arquivo e, se há trabalho com arquivo, chama a Edge Function. */
create or replace function interno.rede5_story_faxina() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_lembretes integer; v_texto integer;
  v_url text := (select valor ->> 'funcao' from configuracoes where chave = 'stories');
  v_chave text := coalesce((select valor ->> 'chave_publica' from configuracoes where chave = 'stories'), '');
  v_segredo text := coalesce((select valor ->> 'segredo' from configuracoes where chave = 'stories'), '');
  v_chamou boolean := false;
begin
  v_lembretes := interno.rede5_story_lembretes();
  with fora as (delete from rede_stories s where s.expira_em <= now() and s.midia_caminho is null and not interno.rede5_story_em_prova(s.id) returning 1)
  select count(*)::integer into v_texto from fora;
  if coalesce(v_url, '') ~ '^https://[a-z0-9.-]+/functions/v1/faxina-stories$' and exists (select 1 from pg_extension where extname = 'pg_net')
     and (exists (select 1 from rede_stories s where s.midia_caminho is not null and (not s.conferido or s.expira_em <= now())) or to_regclass('storage.objects') is not null) then
    execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := $2, timeout_milliseconds := 60000)'
      using v_url, jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_chave, 'apikey', v_chave, 'x-lucia-segredo', v_segredo);
    v_chamou := true;
  end if;
  return jsonb_build_object('lembretes', v_lembretes, 'apagados', v_texto, 'chamou', v_chamou);
end $$;

/**
 * Só a Edge Function (chave de serviço): o que ela tem a fazer. `apagar`: vencidos com arquivo, fora de prova. `conferir`: imagens
 * ainda não conferidas no servidor. `orfaos`: arquivos do depósito sem story há mais de 1 hora (envio abandonado ou story apagado).
 */
create or replace function public.rede_story_faxina_lista(p_limite integer default 200) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_lim integer := greatest(1, least(coalesce(p_limite, 200), 500)); v_orfaos jsonb := '[]'::jsonb;
begin
  if to_regclass('storage.objects') is not null then
    execute 'select coalesce(jsonb_agg(o.name), ''[]''::jsonb) from (select name from storage.objects o where o.bucket_id = ''rede-stories''
               and o.created_at < now() - interval ''1 hour'' and not exists (select 1 from interno.rede_stories s where s.midia_caminho = o.name)
               order by o.created_at limit $1) o'
      into v_orfaos using v_lim;
  end if;
  return jsonb_build_object(
    'apagar', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'caminho', x.midia_caminho)) from (
      select s.id, s.midia_caminho from rede_stories s where s.expira_em <= now() and s.midia_caminho is not null and not interno.rede5_story_em_prova(s.id)
      order by s.expira_em limit v_lim) x), '[]'::jsonb),
    'conferir', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'caminho', x.midia_caminho)) from (
      select s.id, s.midia_caminho from rede_stories s where s.midia_caminho is not null and not s.conferido and s.expira_em > now()
      order by s.criado_em limit least(v_lim, 50)) x), '[]'::jsonb),
    'orfaos', v_orfaos);
end $$;

/**
 * Só a Edge Function: o que ela fez. `p_apagados`: os arquivos já saíram do depósito; a linha sai agora (se ainda vencida e fora
 * de prova). `p_conferidos`: imagem conferida (e limpa, se precisou). `p_ruins`: o arquivo não era imagem que se lê: o story sai do ar.
 */
create or replace function public.rede_story_faxina_feito(p_apagados uuid[], p_conferidos uuid[], p_ruins uuid[]) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_a integer; v_c integer; v_r integer;
begin
  with fora as (delete from rede_stories s where s.id = any (coalesce(p_apagados, '{}')) and s.expira_em <= now() and not interno.rede5_story_em_prova(s.id) returning 1)
  select count(*)::integer into v_a from fora;
  update rede_stories set conferido = true where id = any (coalesce(p_conferidos, '{}')) and not conferido;
  get diagnostics v_c = row_count;
  update rede_stories set expira_em = least(expira_em, now()), conferido = true where id = any (coalesce(p_ruins, '{}'));
  get diagnostics v_r = row_count;
  return jsonb_build_object('apagados', v_a, 'conferidos', v_c, 'ruins', v_r);
end $$;

do $$
begin
  create extension if not exists pg_cron;
exception when others then null;
end $$;
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('alumia-faxina-stories', '*/15 * * * *', 'select interno.rede5_story_faxina()');
  end if;
exception when others then null;
end $$;

-- ── 8. Permissões ─────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.rede5_story_tirar_aviso(), interno.rede5_story_ligado(), interno.rede5_story_ve(interno.rede_stories, uuid),
  interno.rede5_story_autora(uuid), interno.rede5_story_figurinha(interno.rede_story_figurinhas, interno.rede_stories, uuid),
  interno.rede5_story_json(interno.rede_stories, uuid), interno.rede5_story_em_prova(uuid), interno.rede5_story_visivel(uuid, uuid),
  interno.rede5_story_membro(), interno.rede5_story_lembretes(), interno.rede5_story_faxina() from public;
revoke all on function public.rede_story_faixa(), public.rede_story_abrir(text), public.rede_story_meus(), public.rede_story_atos(),
  public.rede_story_publicar(jsonb), public.rede_story_apagar(uuid), public.rede_story_responder(uuid, text), public.rede_story_reagir(uuid, text),
  public.rede_story_votar(uuid, integer), public.rede_story_avisar(uuid, boolean), public.rede_story_denunciar(uuid, text, text),
  public.rede_story_pode(text), public.rede_story_pode_enviar(), public.rede_story_faxina_lista(integer), public.rede_story_faxina_feito(uuid[], uuid[], uuid[]) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede5_story_tirar_aviso(), interno.rede5_story_ligado(), interno.rede5_story_ve(interno.rede_stories, uuid),
      interno.rede5_story_autora(uuid), interno.rede5_story_figurinha(interno.rede_story_figurinhas, interno.rede_stories, uuid),
      interno.rede5_story_json(interno.rede_stories, uuid), interno.rede5_story_em_prova(uuid), interno.rede5_story_visivel(uuid, uuid),
      interno.rede5_story_membro(), interno.rede5_story_lembretes(), interno.rede5_story_faxina() from anon, authenticated;
    revoke all on function public.rede_story_faixa(), public.rede_story_abrir(text), public.rede_story_meus(), public.rede_story_atos(),
      public.rede_story_publicar(jsonb), public.rede_story_apagar(uuid), public.rede_story_responder(uuid, text), public.rede_story_reagir(uuid, text),
      public.rede_story_votar(uuid, integer), public.rede_story_avisar(uuid, boolean), public.rede_story_denunciar(uuid, text, text),
      public.rede_story_pode(text), public.rede_story_pode_enviar(), public.rede_story_faxina_lista(integer), public.rede_story_faxina_feito(uuid[], uuid[], uuid[]) from anon, authenticated;
    -- Leitura que visitante pode chamar (volta vazia para ele): a faixa e abrir.
    grant execute on function public.rede_story_faixa(), public.rede_story_abrir(text) to anon, authenticated, service_role;
    -- Com conta.
    grant execute on function public.rede_story_meus(), public.rede_story_atos(), public.rede_story_publicar(jsonb), public.rede_story_apagar(uuid),
      public.rede_story_responder(uuid, text), public.rede_story_reagir(uuid, text), public.rede_story_votar(uuid, integer),
      public.rede_story_avisar(uuid, boolean), public.rede_story_denunciar(uuid, text, text),
      public.rede_story_pode(text), public.rede_story_pode_enviar() to authenticated, service_role;
    -- Só a Edge Function da faxina.
    grant execute on function public.rede_story_faxina_lista(integer), public.rede_story_faxina_feito(uuid[], uuid[], uuid[]) to service_role;
  end if;
end $$;

-- ═══════════════════════════ fim da F5 ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda A · stories com vídeo e destaques (10/11/2026) ═══════════════════════════
-- docs/plano-2026-11/ALUMIA-ATE-O-FIM.md (A7: "stories como os do Instagram, com vídeo") e PLANO-ALUMIA §6.4, §7.2, §12.
-- Por cima da F5 (20261109-alumia-f5.sql), sem tirar nada dela:
--   1. VÍDEO: fundo "video" (até 60 s), arquivo .mp4/.webm no mesmo depósito privado rede-stories, até 20 MB; a duração e o "som"
--      (a autora pode publicar sem som: aí o áudio nem sai do aparelho) ficam na linha. O aparelho regrava o vídeo (MediaRecorder,
--      720p, taxa limitada), o que joga fora todo metadado do arquivo original (GPS, modelo, data); a faxina confere de novo.
--   2. ESTILO DO TEXTO: fonte, cor da letra, alinhamento e caixa atrás do texto, só valores de uma lista fechada (nunca CSS livre).
--   3. FIGURINHA "comunidade" (menção a uma comunidade da Alumia): o nome vem da comunidade, não do pedido; comunidade fechada só
--      se a autora é membro ativa.
--   4. DESTAQUES no perfil: a autora guarda stories em até 6 destaques. Story num destaque não some em 24 h (escolha dela, com aviso
--      na tela "vai ficar no seu perfil"); continua com o MESMO público (seguidores, membros ou próximos), bloqueio vale, retido
--      some, e nunca federa. Tirar do destaque (ou apagar o destaque) devolve o story vencido à faxina.
-- Idempotente (scripts/testar-alumia-stories-video.mjs roda duas vezes no banco local). NÃO roda em produção sem o Jonathan.
--
-- Privacidade (leis conferidas no texto, leis-do-brasil):
--   * LGPD (Lei 13.709/2018) art. 5º, II e art. 11: continua NÃO existindo tabela, coluna nem contagem de quem viu, nem nos destaques;
--     o destaque mostra só o número de stories dele, nunca de pessoas.
--   * LGPD art. 6º, III (necessidade): o vídeo sai do aparelho já sem metadado; sem som, o áudio nem é enviado; nada de GPS.
--   * ECA Digital (Lei 15.211/2025) art. 9º § 1º: só membro 18+ publica ou vê (as mesmas regras da F5).
--   * Stories e destaques nunca federam (PLANO §6.8): nada daqui entra nas tabelas rede_fed_*.

-- ── 1. Colunas e regras novas em rede_stories ────────────────────────────────────────────────────────────────────────────
alter table interno.rede_stories add column if not exists duracao_ms integer;
alter table interno.rede_stories add column if not exists som boolean not null default false;
alter table interno.rede_stories add column if not exists estilo jsonb not null default '{}'::jsonb;

alter table interno.rede_stories drop constraint if exists rede_stories_fundo_check;
alter table interno.rede_stories add constraint rede_stories_fundo_check check (fundo in ('listras', 'mosaico', 'imagem', 'video'));
alter table interno.rede_stories drop constraint if exists rede_stories_midia_caminho_check;
alter table interno.rede_stories add constraint rede_stories_midia_caminho_check check (midia_caminho is null
  or midia_caminho ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f-]{32,36}\.(webp|png|jpg|mp4|webm)$');
alter table interno.rede_stories drop constraint if exists rede_stories_imagem;
alter table interno.rede_stories add constraint rede_stories_imagem check ((fundo in ('imagem', 'video')) = (midia_caminho is not null));
alter table interno.rede_stories drop constraint if exists rede_stories_video;
alter table interno.rede_stories add constraint rede_stories_video check (
  ((fundo = 'video') = (duracao_ms is not null))
  and (duracao_ms is null or duracao_ms between 300 and 60500)
  and (fundo = 'video' or not som)
  and (midia_caminho is null or (fundo = 'video') = (midia_caminho ~ '\.(mp4|webm)$')));
alter table interno.rede_stories drop constraint if exists rede_stories_estilo;
alter table interno.rede_stories add constraint rede_stories_estilo check (jsonb_typeof(estilo) = 'object' and pg_column_size(estilo) <= 512);

alter table interno.rede_story_figurinhas drop constraint if exists rede_story_figurinhas_tipo_check;
alter table interno.rede_story_figurinhas add constraint rede_story_figurinhas_tipo_check check (tipo in ('contagem', 'pergunta', 'enquete', 'link', 'comunidade'));

-- ── 2. Destaques ──────────────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.rede_story_destaques (
  id uuid primary key default gen_random_uuid(),
  autor uuid not null references interno.perfis (id) on delete cascade,
  titulo text not null check (char_length(titulo) between 1 and 24),
  cor text not null default 'vermelho' check (cor in ('azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite')),
  criado_em timestamptz not null default now()
);
create index if not exists rede_story_destaques_autor on interno.rede_story_destaques (autor, criado_em);

create table if not exists interno.rede_story_no_destaque (
  destaque uuid not null references interno.rede_story_destaques (id) on delete cascade,
  story uuid not null references interno.rede_stories (id) on delete cascade,
  posto_em timestamptz not null default now(),
  primary key (destaque, story)
);
create index if not exists rede_story_no_destaque_story on interno.rede_story_no_destaque (story);

do $$
declare t text;
begin
  foreach t in array array['rede_story_destaques', 'rede_story_no_destaque'] loop
    execute format('alter table interno.%I enable row level security', t);
    execute format('revoke all on table interno.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on table interno.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- ── 3. Quem vê (a regra sem o prazo, para os destaques) ─────────────────────────────────────────────────────────────────
/** A regra de público da F5, sem o "no ar": a mesma para o story vivo e para o story guardado num destaque. */
create or replace function interno.rede5_story_regra(s interno.rede_stories, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select s.id is not null and p_quem is not null and (
    s.autor = p_quem
    or (not s.retido
        and interno.rede2_membro(p_quem) and interno.rede2_membro(s.autor)
        and not interno.rede_bloqueado(p_quem, s.autor)
        and case s.publico
          when 'membros' then true
          when 'seguidores' then exists (select 1 from rede_seguindo g where g.quem = p_quem and g.segue = s.autor and not g.pendente)
          when 'proximos' then exists (select 1 from rede_seguindo g where g.quem = p_quem and g.segue = s.autor and not g.pendente)
                           and exists (select 1 from rede_seguindo g where g.quem = s.autor and g.segue = p_quem and not g.pendente)
          else false end))
$$;

/** O story vivo (F5): a regra e as 24 h. */
create or replace function interno.rede5_story_ve(s interno.rede_stories, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select s.expira_em > now() and interno.rede5_story_regra(s, p_quem)
$$;

/** Está guardado em algum destaque? */
create or replace function interno.rede5_story_no_destaque(p_id uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_story_no_destaque d where d.story = p_id)
$$;

/** O story num destaque: a mesma regra de público, sem prazo (retido continua escondido, bloqueio continua valendo). */
create or replace function interno.rede5_story_ve_destaque(s interno.rede_stories, p_quem uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.rede5_story_no_destaque(s.id) and interno.rede5_story_regra(s, p_quem)
$$;

/** A faxina não leva: prova de denúncia aberta (F5) ou story guardado num destaque. */
create or replace function interno.rede5_story_guardado(p_id uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.rede5_story_em_prova(p_id) or interno.rede5_story_no_destaque(p_id)
$$;

/** Um story que esta pessoa vê (vivo, ou guardado num destaque), ou "nao_encontrado" (o mesmo erro para os dois casos). */
create or replace function interno.rede5_story_visivel(p_id uuid, p_quem uuid) returns interno.rede_stories language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare s rede_stories;
begin
  select * into s from rede_stories where id = p_id;
  if not found or not (interno.rede5_story_ve(s, p_quem) or interno.rede5_story_ve_destaque(s, p_quem)) then perform interno.erro('nao_encontrado'); end if;
  return s;
end $$;

/** Regra de leitura do depósito: o arquivo é de um story que quem pede vê, vivo ou num destaque. */
create or replace function public.rede_story_pode(p_caminho text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from rede_stories s where s.midia_caminho = p_caminho
                 and (interno.rede5_story_ve(s, auth.uid()) or interno.rede5_story_ve_destaque(s, auth.uid())))
$$;

-- ── 4. O story como a tela recebe ─────────────────────────────────────────────────────────────────────────────────────────
/** Uma figurinha como `p_quem` a vê (a F5, mais a menção de comunidade com o nome atual dela). */
create or replace function interno.rede5_story_figurinha(f interno.rede_story_figurinhas, s interno.rede_stories, p_quem uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_ato uuid; p rede_posts; v_n0 integer; v_n1 integer; c rede_comunidades;
begin
  if f.tipo = 'contagem' then
    begin v_ato := (f.dados ->> 'ato')::uuid; exception when others then v_ato := null; end;
    if v_ato is not null then
      select * into p from rede_posts where id = v_ato;
      if not found or not interno.rede2_pode_ver(p, p_quem) then v_ato := null; end if;
    end if;
    return jsonb_build_object('tipo', 'contagem', 'ato', v_ato, 'titulo', f.dados ->> 'titulo', 'inicio', f.dados ->> 'inicio',
      'avisar', v_ato is not null and exists (select 1 from rede_story_lembretes l where l.ato = v_ato and l.quem = p_quem));
  elsif f.tipo = 'pergunta' then
    return jsonb_build_object('tipo', 'pergunta', 'texto', f.dados ->> 'texto');
  elsif f.tipo = 'enquete' then
    if s.autor = p_quem then
      select count(*) filter (where opcao = 0)::integer, count(*) filter (where opcao = 1)::integer into v_n0, v_n1 from rede_story_votos where story = s.id;
    end if;
    return jsonb_build_object('tipo', 'enquete', 'pergunta', f.dados ->> 'pergunta', 'opcoes', f.dados -> 'opcoes',
      'meu_voto', (select v.opcao from rede_story_votos v where v.story = s.id and v.quem = p_quem and s.autor <> p_quem),
      'soma', case when s.autor = p_quem and v_n0 + v_n1 >= 3 then jsonb_build_array(v_n0, v_n1) end);
  elsif f.tipo = 'comunidade' then
    select * into c from rede_comunidades where slug = f.dados ->> 'slug';
    if not found then return jsonb_build_object('tipo', 'comunidade', 'slug', null, 'nome', f.dados ->> 'nome'); end if;
    -- Comunidade que não é aberta: quem não é membro vê o nome, sem o atalho para ela.
    if c.tipo <> 'aberta' and not exists (select 1 from rede_comunidade_membros m where m.comunidade = c.slug and m.usuario = p_quem and m.situacao = 'ativo') then
      return jsonb_build_object('tipo', 'comunidade', 'slug', null, 'nome', c.nome);
    end if;
    return jsonb_build_object('tipo', 'comunidade', 'slug', c.slug, 'nome', c.nome);
  else
    return jsonb_build_object('tipo', 'link', 'url', f.dados ->> 'url', 'rotulo', f.dados ->> 'rotulo');
  end if;
end $$;

/** O story inteiro como `p_quem` o vê. Vídeo: caminho cru, duração e se tem som. A autora vê em quais destaques ele está. */
create or replace function interno.rede5_story_json(s interno.rede_stories, p_quem uuid) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object(
    'id', s.id, 'autora', interno.rede5_story_autora(s.autor), 'criado_em', s.criado_em, 'expira_em', s.expira_em, 'publico', s.publico,
    'fundo', case
      when s.fundo = 'imagem' then jsonb_build_object('tipo', 'imagem', 'cor', s.cor, 'caminho', s.midia_caminho, 'url', '', 'alt', coalesce(s.alt, ''))
      when s.fundo = 'video' then jsonb_build_object('tipo', 'video', 'cor', s.cor, 'caminho', s.midia_caminho, 'url', '', 'alt', coalesce(s.alt, ''),
                                                     'duracao', s.duracao_ms, 'som', s.som)
      else jsonb_build_object('tipo', s.fundo, 'cor', s.cor) end,
    'texto', s.texto, 'legenda', s.legenda, 'meu', s.autor = p_quem, 'estilo', s.estilo,
    'destaques', case when s.autor = p_quem then coalesce((select jsonb_agg(d.destaque) from rede_story_no_destaque d where d.story = s.id), '[]'::jsonb) end,
    'figurinhas', coalesce((select jsonb_agg(interno.rede5_story_figurinha(f, s, p_quem) || jsonb_strip_nulls(jsonb_build_object('pos', f.dados -> 'pos')) order by f.ordem) from rede_story_figurinhas f where f.story = s.id), '[]'::jsonb))
$$;

/** O estilo do texto, limpo: só chaves e valores da lista fechada (nunca CSS livre). Valor fora da lista é recusado. */
create or replace function interno.rede5_story_estilo(p jsonb) returns jsonb language plpgsql immutable security definer set search_path = interno, pg_temp as $$
declare
  v_fonte text := coalesce(p ->> 'fonte', 'condensada');
  v_cor text := nullif(p ->> 'cor_texto', '');
  v_alinhar text := coalesce(p ->> 'alinhar', 'esq');
  v_caixa text := coalesce(p ->> 'caixa', 'nenhuma');
begin
  if p is null or jsonb_typeof(p) = 'null' then return '{}'::jsonb; end if;
  if jsonb_typeof(p) <> 'object' then perform interno.erro('invalido:estilo'); end if;
  if exists (select 1 from jsonb_object_keys(p) k where k not in ('fonte', 'cor_texto', 'alinhar', 'caixa')) then perform interno.erro('invalido:estilo'); end if;
  if v_fonte not in ('condensada', 'serifa', 'maquina', 'marcador') then perform interno.erro('invalido:estilo'); end if;
  if v_cor is not null and v_cor not in ('papel', 'azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite') then perform interno.erro('invalido:estilo'); end if;
  if v_alinhar not in ('esq', 'centro', 'dir') then perform interno.erro('invalido:estilo'); end if;
  if v_caixa not in ('nenhuma', 'caixa') then perform interno.erro('invalido:estilo'); end if;
  return jsonb_strip_nulls(jsonb_build_object('fonte', v_fonte, 'cor_texto', v_cor, 'alinhar', v_alinhar, 'caixa', v_caixa));
end $$;

-- ── 5. Publicar (a F5, com vídeo, estilo e a menção de comunidade) ────────────────────────────────────────────────────────
/**
 * Onde a figurinha fica na tela, como a autora a deixou no "criar": x e y de 0 a 1 (o centro dela na tela do story), o giro em
 * graus (até 45 para cada lado, para continuar legível) e o tamanho (0,5 a 1,6). Só números; fora disso, nulo (a tela escolhe).
 */
create or replace function interno.rede5_story_pos(p jsonb) returns jsonb language plpgsql immutable set search_path = interno, pg_temp as $$
declare x numeric; y numeric; g numeric := 0; e numeric := 1;
begin
  if p is null or jsonb_typeof(p) is distinct from 'object' then return null; end if;
  if jsonb_typeof(p -> 'x') is distinct from 'number' or jsonb_typeof(p -> 'y') is distinct from 'number' then return null; end if;
  x := (p ->> 'x')::numeric;
  y := (p ->> 'y')::numeric;
  if jsonb_typeof(p -> 'giro') = 'number' then g := (p ->> 'giro')::numeric; end if;
  if jsonb_typeof(p -> 'escala') = 'number' then e := (p ->> 'escala')::numeric; end if;
  return jsonb_build_object('x', round(least(0.95, greatest(0.05, x)), 4), 'y', round(least(0.95, greatest(0.05, y)), 4),
    'giro', round(least(45, greatest(-45, g)), 1), 'escala', round(least(1.6, greatest(0.5, e)), 3));
end $$;

/**
 * Publica um story (PedidoDeStory de lib/rede/tipos-stories.ts). Tudo da F5 continua: público, fundo, tamanhos, dado pessoal,
 * até 3 figurinhas (uma enquete e uma contagem no máximo), link só https, contagem só de ato meu ou confirmado, 20 por dia. Novo:
 * vídeo (.mp4/.webm, até 20 MB, 0,3 a 60 s; sem som = o arquivo nem tem áudio, o aparelho garante e a tela respeita), o estilo
 * do texto e a menção de comunidade. O texto do link passa a ser opcional (a tela mostra o domínio).
 */
create or replace function public.rede_story_publicar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.rede5_story_membro();
  v_publico text := coalesce(p ->> 'publico', 'seguidores');
  v_fundo text := coalesce(p -> 'fundo' ->> 'tipo', 'listras');
  v_cor text := coalesce(p -> 'fundo' ->> 'cor', 'azul');
  v_texto text; v_legenda text; v_alt text; v_imagem text := nullif(btrim(coalesce(p ->> 'imagem', '')), '');
  v_post uuid; pr rede_posts; v_figs jsonb := coalesce(p -> 'figurinhas', '[]'::jsonb);
  f jsonb; v_tipo text; v_limpas jsonb := '[]'::jsonb; v_tudo text := ''; v_ato uuid; v_titulo text; v_inicio timestamptz;
  v_url text; v_rotulo text; v_perg text; v_op0 text; v_op1 text; v_enquetes integer := 0; v_contagens integer := 0; v_comunidades integer := 0;
  v_tam bigint; v_mime text; s rede_stories; i integer := 0; v_duracao integer; v_som boolean := false; v_estilo jsonb; c rede_comunidades;
begin
  if p is null or jsonb_typeof(p) is distinct from 'object' then perform interno.erro('invalido:pedido'); end if;
  if v_publico not in ('seguidores', 'membros', 'proximos') then perform interno.erro('invalido:publico'); end if;
  if v_fundo not in ('listras', 'mosaico', 'imagem', 'video') then perform interno.erro('invalido:fundo'); end if;
  if v_cor not in ('azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite') then perform interno.erro('invalido:cor'); end if;
  if not exists (select 1 from perfis where id = v and rede_handle is not null) then perform interno.erro('sem_handle'); end if;
  v_texto := interno.txt(p ->> 'texto', 'texto', 0, 140);
  v_legenda := nullif(interno.txt(p ->> 'legenda', 'legenda', 0, 80), '');
  v_alt := nullif(interno.txt(p ->> 'alt', 'alt', 0, 200), '');
  v_estilo := interno.rede5_story_estilo(p -> 'estilo');
  if jsonb_typeof(v_figs) is distinct from 'array' or jsonb_array_length(v_figs) > 3 then perform interno.erro('invalido:figurinhas'); end if;

  -- A mídia: imagem ou vídeo exigem o caminho, e o caminho só vale com um dos dois.
  if (v_fundo in ('imagem', 'video')) <> (v_imagem is not null) then perform interno.erro('invalido:imagem'); end if;
  if v_fundo = 'video' then
    begin v_duracao := round((p -> 'video' ->> 'duracao_ms')::numeric)::integer; exception when others then v_duracao := null; end;
    if v_duracao is null or v_duracao not between 300 and 60500 then perform interno.erro('invalido:video'); end if;
    v_som := coalesce((p -> 'video' ->> 'som')::boolean, false);
  end if;
  if v_imagem is not null then
    if v_fundo = 'imagem' and v_imagem !~ ('^' || v::text || '/[0-9a-f-]{32,36}\.(webp|png|jpg)$') then perform interno.erro('invalido:imagem'); end if;
    if v_fundo = 'video' and v_imagem !~ ('^' || v::text || '/[0-9a-f-]{32,36}\.(mp4|webm)$') then perform interno.erro('invalido:video'); end if;
    if exists (select 1 from rede_stories where midia_caminho = v_imagem) then perform interno.erro('invalido:imagem'); end if;
    if to_regclass('storage.objects') is not null then
      execute 'select (metadata ->> ''size'')::bigint, metadata ->> ''mimetype'' from storage.objects where bucket_id = ''rede-stories'' and name = $1'
        into v_tam, v_mime using v_imagem;
      if v_mime is null then perform interno.erro('invalido:imagem'); end if;
      if v_fundo = 'imagem' and (v_mime not in ('image/webp', 'image/png', 'image/jpeg') or coalesce(v_tam, 0) > 3145728) then perform interno.erro('invalido:imagem'); end if;
      if v_fundo = 'video' and (v_mime not in ('video/mp4', 'video/webm') or coalesce(v_tam, 0) > 20971520) then perform interno.erro('invalido:video'); end if;
    end if;
  else
    v_alt := null;
  end if;

  -- "Pôr no story": só um post que eu vejo.
  if nullif(p ->> 'post_ref', '') is not null then
    begin v_post := (p ->> 'post_ref')::uuid; exception when others then perform interno.erro('invalido:post'); end;
    select * into pr from rede_posts where id = v_post;
    if not found or not interno.rede2_pode_ver(pr, v) then perform interno.erro('nao_encontrado'); end if;
  end if;

  for f in select * from jsonb_array_elements(v_figs) loop
    v_tipo := f ->> 'tipo';
    if v_tipo = 'contagem' then
      v_contagens := v_contagens + 1;
      begin v_ato := (f ->> 'ato')::uuid; exception when others then v_ato := null; end;
      if v_ato is null then perform interno.erro('invalido:contagem'); end if;
      select left(coalesce(nullif(btrim(x.titulo), ''), btrim(x.texto)), 60), ch.inicio into v_titulo, v_inicio
      from rede_chamados ch join rede_posts x on x.id = ch.post
      where ch.post = v_ato and ch.inicio > now() and not ch.cancelado and interno.rede2_pode_ver(x, v)
        and (x.autor = v or exists (select 1 from rede_vou u where u.post = x.id and u.usuario = v));
      if not found then perform interno.erro('invalido:contagem'); end if;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'contagem', 'dados', jsonb_build_object('ato', v_ato, 'titulo', v_titulo, 'inicio', v_inicio));
    elsif v_tipo = 'pergunta' then
      v_perg := interno.txt(f ->> 'texto', 'pergunta', 1, 90);
      v_tudo := v_tudo || E'\n' || v_perg;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'pergunta', 'dados', jsonb_build_object('texto', v_perg));
    elsif v_tipo = 'enquete' then
      v_enquetes := v_enquetes + 1;
      if jsonb_typeof(f -> 'opcoes') is distinct from 'array' or jsonb_array_length(f -> 'opcoes') <> 2 then perform interno.erro('invalido:enquete'); end if;
      v_perg := interno.txt(f ->> 'pergunta', 'pergunta', 1, 90);
      v_op0 := interno.txt(f -> 'opcoes' ->> 0, 'opcao', 1, 24);
      v_op1 := interno.txt(f -> 'opcoes' ->> 1, 'opcao', 1, 24);
      if lower(v_op0) = lower(v_op1) then perform interno.erro('invalido:opcao'); end if;
      v_tudo := v_tudo || E'\n' || v_perg || E'\n' || v_op0 || E'\n' || v_op1;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'enquete', 'dados', jsonb_build_object('pergunta', v_perg, 'opcoes', jsonb_build_array(v_op0, v_op1)));
    elsif v_tipo = 'link' then
      v_url := btrim(coalesce(f ->> 'url', ''));
      if v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(:[0-9]{2,5})?(/[^\s<>"]*)?$' or char_length(v_url) > 300 then perform interno.erro('invalido:link'); end if;
      v_rotulo := interno.txt(coalesce(f ->> 'rotulo', ''), 'rotulo', 0, 40);
      v_tudo := v_tudo || E'\n' || v_rotulo;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'link', 'dados', jsonb_build_object('url', v_url, 'rotulo', v_rotulo));
    elsif v_tipo = 'comunidade' then
      v_comunidades := v_comunidades + 1;
      select * into c from rede_comunidades where slug = coalesce(f ->> 'slug', '');
      -- Comunidade restrita ou fechada só pela autora que é membro ativa (a menção não revela que a comunidade existe para quem não pode saber).
      if not found or (c.tipo <> 'aberta' and not exists (select 1 from rede_comunidade_membros m where m.comunidade = c.slug and m.usuario = v and m.situacao = 'ativo')) then
        perform interno.erro('invalido:comunidade');
      end if;
      v_limpas := v_limpas || jsonb_build_object('tipo', 'comunidade', 'dados', jsonb_build_object('slug', c.slug, 'nome', c.nome));
    else
      perform interno.erro('invalido:figurinha');
    end if;
    -- O lugar na tela (opcional): só o que passa em rede5_story_pos.
    if interno.rede5_story_pos(f -> 'pos') is not null then
      v_limpas := jsonb_set(v_limpas, array[(jsonb_array_length(v_limpas) - 1)::text, 'dados', 'pos'], interno.rede5_story_pos(f -> 'pos'));
    end if;
  end loop;
  if v_enquetes > 1 or v_contagens > 1 or v_comunidades > 1 then perform interno.erro('invalido:figurinhas'); end if;
  if v_texto = '' and v_imagem is null and jsonb_array_length(v_limpas) = 0 then perform interno.erro('invalido:vazio'); end if;
  if interno.rede3_pub_dado_pessoal(v_texto || E'\n' || coalesce(v_legenda, '') || E'\n' || coalesce(v_alt, '') || v_tudo) then perform interno.erro('dado_pessoal'); end if;

  perform interno.limite('rede5_story_publicar', 20, 1440);
  insert into rede_stories (autor, publico, fundo, cor, texto, legenda, midia_caminho, alt, post_ref, conferido, duracao_ms, som, estilo)
  values (v, v_publico, v_fundo, v_cor, v_texto, v_legenda, v_imagem, v_alt, v_post, v_imagem is null, v_duracao, v_som, v_estilo)
  returning * into s;
  for f in select * from jsonb_array_elements(v_limpas) loop
    insert into rede_story_figurinhas (story, ordem, tipo, dados) values (s.id, i, f ->> 'tipo', f -> 'dados');
    i := i + 1;
  end loop;
  return jsonb_build_object('id', s.id, 'expira_em', s.expira_em);
end $$;

/** As comunidades que posso mencionar num story: as minhas (membro ativa), até 30, pelo nome. Sem número de membros. */
create or replace function public.rede_story_comunidades() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro();
begin
  return coalesce((select jsonb_agg(jsonb_build_object('slug', x.slug, 'nome', x.nome) order by x.nome)
    from (select c.slug, c.nome from rede_comunidades c join rede_comunidade_membros m on m.comunidade = c.slug
          where m.usuario = v and m.situacao = 'ativo' order by c.nome limit 30) x), '[]'::jsonb);
end $$;

-- ── 6. Destaques ──────────────────────────────────────────────────────────────────────────────────────────────────────────
/**
 * Os destaques de alguém (@handle), como eu os vejo: só os que têm algum story que eu posso ver, com quantos stories (nunca
 * pessoas) e a capa (a cor e o caminho do primeiro story com mídia, que o aparelho troca por um endereço assinado). A dona vê
 * todos, inclusive os vazios. Visitante e quem não é da Alumia recebem a lista vazia. Leitura pura: nada é gravado.
 */
create or replace function public.rede_story_destaques(p_handle text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_autor uuid;
begin
  if v is null or not interno.rede2_membro(v) then return '[]'::jsonb; end if;
  perform interno.rede5_story_ligado();
  if coalesce(p_handle, '') !~ '^[a-z0-9_]{3,20}$' then perform interno.erro('invalido:handle'); end if;
  select id into v_autor from perfis where rede_handle = p_handle;
  if not found then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', d.id, 'titulo', d.titulo, 'cor', d.cor, 'n', x.n,
             'capa', case when x.capa is not null then jsonb_build_object('caminho', x.capa, 'tipo', x.capa_tipo) end) order by d.criado_em)
    from rede_story_destaques d
    cross join lateral (
      select count(*)::integer as n,
             (array_agg(s.midia_caminho order by nd.posto_em) filter (where s.midia_caminho is not null and s.fundo = 'imagem'))[1] as capa,
             'imagem'::text as capa_tipo
      from rede_story_no_destaque nd join rede_stories s on s.id = nd.story
      where nd.destaque = d.id and interno.rede5_story_regra(s, v)) x
    where d.autor = v_autor and (x.n > 0 or d.autor = v)), '[]'::jsonb);
end $$;

/** Os stories de um destaque, do mais antigo ao mais novo, só os que eu posso ver (a mesma regra de público, sem o prazo). */
create or replace function public.rede_story_destaque_abrir(p_id uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  if v is null or not interno.rede2_membro(v) then return '[]'::jsonb; end if;
  perform interno.rede5_story_ligado();
  return coalesce((select jsonb_agg(interno.rede5_story_json(s, v) order by s.criado_em)
    from rede_story_no_destaque nd join rede_stories s on s.id = nd.story
    where nd.destaque = p_id and interno.rede5_story_ve_destaque(s, v)), '[]'::jsonb);
end $$;

/**
 * Guardar um story meu num destaque (novo, se p_destaque é nulo; até 6 destaques e 60 stories em cada) e/ou renomear e trocar a
 * cor de um destaque meu. O story precisa ser meu e estar no ar (ou já guardado). Título passa pela checagem de dado pessoal.
 */
create or replace function public.rede_story_destaque_salvar(p_destaque uuid, p_titulo text, p_story uuid, p_cor text default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); d rede_story_destaques; s rede_stories; v_titulo text;
begin
  perform interno.limite('rede5_story_destaque', 60, 60);
  if p_cor is not null and p_cor not in ('azul', 'vermelho', 'dourado', 'verde', 'rosa', 'noite') then perform interno.erro('invalido:cor'); end if;
  if p_titulo is not null then
    v_titulo := interno.txt(p_titulo, 'titulo', 1, 24);
    if interno.rede3_pub_dado_pessoal(v_titulo) then perform interno.erro('dado_pessoal'); end if;
  end if;
  if p_story is not null then
    select * into s from rede_stories where id = p_story and autor = v;
    if not found or not (s.expira_em > now() or interno.rede5_story_no_destaque(s.id)) then perform interno.erro('nao_encontrado'); end if;
  end if;
  if p_destaque is null then
    if v_titulo is null then perform interno.erro('invalido:titulo'); end if;
    if (select count(*) from rede_story_destaques where autor = v) >= 6 then perform interno.erro('limite:destaques'); end if;
    insert into rede_story_destaques (autor, titulo, cor) values (v, v_titulo, coalesce(p_cor, 'vermelho')) returning * into d;
  else
    select * into d from rede_story_destaques where id = p_destaque and autor = v;
    if not found then perform interno.erro('nao_encontrado'); end if;
    update rede_story_destaques set titulo = coalesce(v_titulo, titulo), cor = coalesce(p_cor, cor) where id = d.id returning * into d;
  end if;
  if p_story is not null then
    if (select count(*) from rede_story_no_destaque where destaque = d.id) >= 60 then perform interno.erro('limite:destaque'); end if;
    insert into rede_story_no_destaque (destaque, story) values (d.id, s.id) on conflict do nothing;
  end if;
  return jsonb_build_object('id', d.id, 'titulo', d.titulo, 'cor', d.cor);
end $$;

/** Tirar um story meu de um destaque meu. Vencido e fora de todo destaque, ele volta para a faxina. */
create or replace function public.rede_story_destaque_tirar(p_destaque uuid, p_story uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro();
begin
  perform interno.limite('rede5_story_destaque', 60, 60);
  if not exists (select 1 from rede_story_destaques where id = p_destaque and autor = v) then perform interno.erro('nao_encontrado'); end if;
  delete from rede_story_no_destaque where destaque = p_destaque and story = p_story;
  return jsonb_build_object('ok', true);
end $$;

/** Apagar um destaque meu (os stories vencidos dele voltam para a faxina; os que estão no ar seguem até as 24 h). */
create or replace function public.rede_story_destaque_apagar(p_destaque uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.rede5_story_membro(); v_n integer;
begin
  perform interno.limite('rede5_story_destaque', 60, 60);
  delete from rede_story_destaques where id = p_destaque and autor = v;
  get diagnostics v_n = row_count;
  if v_n = 0 then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('apagado', true);
end $$;

-- ── 7. Faxina: não leva o que está num destaque ───────────────────────────────────────────────────────────────────────────
create or replace function interno.rede5_story_faxina() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v_lembretes integer; v_texto integer;
  v_url text := (select valor ->> 'funcao' from configuracoes where chave = 'stories');
  v_chave text := coalesce((select valor ->> 'chave_publica' from configuracoes where chave = 'stories'), '');
  v_segredo text := coalesce((select valor ->> 'segredo' from configuracoes where chave = 'stories'), '');
  v_chamou boolean := false;
begin
  v_lembretes := interno.rede5_story_lembretes();
  with fora as (delete from rede_stories s where s.expira_em <= now() and s.midia_caminho is null and not interno.rede5_story_guardado(s.id) returning 1)
  select count(*)::integer into v_texto from fora;
  if coalesce(v_url, '') ~ '^https://[a-z0-9.-]+/functions/v1/faxina-stories$' and exists (select 1 from pg_extension where extname = 'pg_net')
     and (exists (select 1 from rede_stories s where s.midia_caminho is not null and (not s.conferido or s.expira_em <= now())) or to_regclass('storage.objects') is not null) then
    execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := $2, timeout_milliseconds := 60000)'
      using v_url, jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_chave, 'apikey', v_chave, 'x-lucia-segredo', v_segredo);
    v_chamou := true;
  end if;
  return jsonb_build_object('lembretes', v_lembretes, 'apagados', v_texto, 'chamou', v_chamou);
end $$;

create or replace function public.rede_story_faxina_lista(p_limite integer default 200) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_lim integer := greatest(1, least(coalesce(p_limite, 200), 500)); v_orfaos jsonb := '[]'::jsonb;
begin
  if to_regclass('storage.objects') is not null then
    execute 'select coalesce(jsonb_agg(o.name), ''[]''::jsonb) from (select name from storage.objects o where o.bucket_id = ''rede-stories''
               and o.created_at < now() - interval ''1 hour'' and not exists (select 1 from interno.rede_stories s where s.midia_caminho = o.name)
               order by o.created_at limit $1) o'
      into v_orfaos using v_lim;
  end if;
  return jsonb_build_object(
    'apagar', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'caminho', x.midia_caminho)) from (
      select s.id, s.midia_caminho from rede_stories s where s.expira_em <= now() and s.midia_caminho is not null and not interno.rede5_story_guardado(s.id)
      order by s.expira_em limit v_lim) x), '[]'::jsonb),
    'conferir', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'caminho', x.midia_caminho)) from (
      select s.id, s.midia_caminho from rede_stories s where s.midia_caminho is not null and not s.conferido and (s.expira_em > now() or interno.rede5_story_no_destaque(s.id))
      order by s.criado_em limit least(v_lim, 50)) x), '[]'::jsonb),
    'orfaos', v_orfaos);
end $$;

create or replace function public.rede_story_faxina_feito(p_apagados uuid[], p_conferidos uuid[], p_ruins uuid[]) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_a integer; v_c integer; v_r integer;
begin
  with fora as (delete from rede_stories s where s.id = any (coalesce(p_apagados, '{}')) and s.expira_em <= now() and not interno.rede5_story_guardado(s.id) returning 1)
  select count(*)::integer into v_a from fora;
  update rede_stories set conferido = true where id = any (coalesce(p_conferidos, '{}')) and not conferido;
  get diagnostics v_c = row_count;
  -- Arquivo ruim: sai do ar E de todo destaque (senão o destaque o guardaria para sempre).
  delete from rede_story_no_destaque where story = any (coalesce(p_ruins, '{}'));
  update rede_stories set expira_em = least(expira_em, now()), conferido = true where id = any (coalesce(p_ruins, '{}'));
  get diagnostics v_r = row_count;
  return jsonb_build_object('apagados', v_a, 'conferidos', v_c, 'ruins', v_r);
end $$;

-- ── 8. O depósito aceita vídeo (até 20 MB; a função de publicar limita a imagem a 3 MB) ─────────────────────────────────────
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') and to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('rede-stories', 'rede-stories', false, 20971520, array['image/webp', 'image/png', 'image/jpeg', 'video/mp4', 'video/webm'])
    on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  end if;
end $$;

-- ── 9. Permissões (a versão da Alumia, public.rede_alumia_versao, sobe na migração final da onda, pelo integrador) ────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.rede5_story_regra(interno.rede_stories, uuid), interno.rede5_story_no_destaque(uuid),
  interno.rede5_story_ve_destaque(interno.rede_stories, uuid), interno.rede5_story_guardado(uuid), interno.rede5_story_estilo(jsonb), interno.rede5_story_pos(jsonb) from public;
revoke all on function public.rede_story_comunidades(), public.rede_story_destaques(text), public.rede_story_destaque_abrir(uuid),
  public.rede_story_destaque_salvar(uuid, text, uuid, text), public.rede_story_destaque_tirar(uuid, uuid), public.rede_story_destaque_apagar(uuid) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede5_story_regra(interno.rede_stories, uuid), interno.rede5_story_no_destaque(uuid),
      interno.rede5_story_ve_destaque(interno.rede_stories, uuid), interno.rede5_story_guardado(uuid), interno.rede5_story_estilo(jsonb), interno.rede5_story_pos(jsonb) from anon, authenticated;
    revoke all on function public.rede_story_comunidades(), public.rede_story_destaques(text), public.rede_story_destaque_abrir(uuid),
      public.rede_story_destaque_salvar(uuid, text, uuid, text), public.rede_story_destaque_tirar(uuid, uuid), public.rede_story_destaque_apagar(uuid) from anon, authenticated;
    -- Leitura só com conta (visitante não vê story nenhum: a F5 só deixa a ele a faixa e o abrir, que voltam vazios).
    grant execute on function public.rede_story_destaques(text), public.rede_story_destaque_abrir(uuid) to authenticated, service_role;
    -- Com conta.
    grant execute on function public.rede_story_comunidades(), public.rede_story_destaque_salvar(uuid, text, uuid, text),
      public.rede_story_destaque_tirar(uuid, uuid), public.rede_story_destaque_apagar(uuid) to authenticated, service_role;
    -- As da F5 que foram refeitas aqui mantêm as permissões (create or replace não muda o grant), mas confirma:
    grant execute on function public.rede_story_publicar(jsonb), public.rede_story_pode(text) to authenticated, service_role;
  end if;
end $$;

-- ═══════════════════════════ fim de stories com vídeo e destaques ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Perfil livre (10/11/2026) ═══════════════════════════
-- docs/plano-2026-11/ALUMIA-ATE-O-FIM.md (A5) e ALUMIA-FUNCOES-E-IDEIAS.md §3.1 e §6 (Onda A, F4). "Liberdade pro usuário editar o
-- perfil dele como quiser", com segurança: a aparência do perfil é um jsonb em perfis.rede_aparencia em que CADA chave é uma
-- escolha entre valores conhecidos ou um valor conferido por expressão regular (cor "#rrggbb", rosto de 64 dígitos, palavra A–Z).
-- Nunca CSS, HTML ou URL livre: o link de "tocando agora" é https, sem usuário/senha e sem parâmetro de rastreio. Também: campos
-- do perfil até 6 (eram 4), posts fixados (até 3, só da própria pessoa), destaques (post ou ato da própria pessoa, até 6) e
-- organizações que a pessoa ESCOLHE mostrar (só com selo). E o Tear de encaminhamentos das organizações (Onda A, F4): cada
-- deliberação vira um fio com uma FUNÇÃO responsável (nunca uma pessoa), prazo e estado; o público vê só o agregado.
--
-- Idempotente: scripts/testar-alumia-perfil.mjs roda duas vezes no banco local. Depende da F4 (20261109-alumia-f4.sql). NÃO rodar
-- em produção sem o Jonathan.
--
-- Leis (conferidas no texto, leis-do-brasil):
--  - LGPD (Lei 13.709/2018) art. 5º, II e art. 11: filiação a organização política é dado SENSÍVEL. Por isso "organizações no
--    perfil" é opt-in, a pessoa escreve uma a uma, e nada é deduzido de seguir, de núcleo ou de voto.
--  - LGPD art. 6º, III (necessidade): a aparência não guarda nada sobre a pessoa além do que ela escolheu mostrar; "tocando agora" é
--    só texto e um link, a Alumia não liga em serviço de música (sem rastreio) e o texto some sozinho no prazo.
--  - LGPD art. 46 (segurança): RLS ligada, nenhuma permissão direta nas tabelas; acesso só por função security definer.
--  - ECA Digital (Lei 15.211/2025) art. 9º § 1º: editar exige ser membro da Rede (18+ e consentimento), como o resto da F4.

-- ── 1. Colunas e tabelas ──────────────────────────────────────────────────────────────────────────────────────────────────
alter table interno.perfis add column if not exists rede_aparencia jsonb not null default '{}'::jsonb;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'perfis_rede_aparencia_tamanho') then
    alter table interno.perfis add constraint perfis_rede_aparencia_tamanho check (pg_column_size(rede_aparencia) <= 8192);
  end if;
  -- Campos do perfil: até 6 (o Mastodon dá 4; aqui a pessoa pediu mais liberdade).
  if exists (select 1 from pg_constraint where conname = 'rede_perfil_campos_ordem_check') then
    alter table interno.rede_perfil_campos drop constraint rede_perfil_campos_ordem_check;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'rede_perfil_campos_ordem_6') then
    alter table interno.rede_perfil_campos add constraint rede_perfil_campos_ordem_6 check (ordem between 1 and 6);
  end if;
end $$;

-- O Tear de encaminhamentos: um fio por deliberação. `funcao` é o NOME DA FUNÇÃO (tesouraria, comunicação), nunca uma pessoa.
create table if not exists interno.rede_org_encaminhamentos (
  id uuid primary key default gen_random_uuid(),
  org uuid not null references interno.rede_orgs (perfil) on delete cascade,
  texto text not null check (char_length(btrim(texto)) between 3 and 200),
  funcao text not null check (char_length(btrim(funcao)) between 2 and 40),
  prazo date not null,
  estado text not null default 'aberto' check (estado in ('aberto', 'cumprido', 'retirado')),
  -- Só o dia (LGPD art. 6º, III): nada de hora nem de quem marcou.
  criado_dia date not null default current_date,
  cumprido_dia date
);
create index if not exists rede_org_encaminhamentos_org on interno.rede_org_encaminhamentos (org, criado_dia desc);
alter table interno.rede_org_encaminhamentos enable row level security;
do $$
begin
  revoke all on table interno.rede_org_encaminhamentos from public;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_org_encaminhamentos from anon, authenticated;
  end if;
end $$;

-- ── 2. A aparência: conferir e arrumar ────────────────────────────────────────────────────────────────────────────────────

/**
 * Confere a aparência pedida por `p_dono` e devolve a forma guardada. Recusa (erro 'invalido:<chave>') o que não for um dos
 * valores conhecidos; chave desconhecida também é recusada (ninguém guarda nada fora da lista). Espelho de lib/rede/aparencia.ts.
 */
create or replace function interno.alumia_aparencia_valida(p jsonb, p_dono uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  k text; r jsonb := '{}'::jsonb; x jsonb; v text; i integer; n integer;
  paleta constant text[] := array['vermelho', 'dourado', 'azul', 'verde', 'rosa', 'laranja', 'turquesa', 'roxo'];
  abas constant text[] := array['posts', 'respostas', 'midia', 'atos', 'destaques', 'organizacoes', 'escola'];
  rastreio constant text := '(^|[?&])(utm_[a-z_]+|fbclid|gclid|dclid|gbraid|wbraid|msclkid|mc_[a-z]+|igshid|igsh|si|ref_src|ref_url|_hsenc|_hsmi|yclid|twclid|ttclid|s_cid|mkt_tok)=';
  vistos text[];
begin
  if p is null or jsonb_typeof(p) <> 'object' then perform interno.erro('invalido:aparencia'); end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('acento', 'tema', 'layout', 'faixa', 'rosto', 'capa', 'abas', 'fixados', 'destaques', 'orgs', 'tocando') then
      perform interno.erro('invalido:aparencia');
    end if;
  end loop;

  -- Cor: nome da paleta ou "#rrggbb" (o contraste é garantido na tela, que clareia ou escurece até 4,5:1 em cada fundo).
  if p ? 'acento' then
    v := p ->> 'acento';
    if v is null or not (v = any (paleta) or v ~ '^#[0-9a-f]{6}$') then perform interno.erro('invalido:acento'); end if;
    r := r || jsonb_build_object('acento', v);
  end if;
  if p ? 'tema' then
    if coalesce(p ->> 'tema', '') not in ('brasa', 'tingido', 'papel', 'noite') then perform interno.erro('invalido:tema'); end if;
    r := r || jsonb_build_object('tema', p ->> 'tema');
  end if;
  if p ? 'layout' then
    if coalesce(p ->> 'layout', '') not in ('classico', 'centro', 'cartaz') then perform interno.erro('invalido:layout'); end if;
    r := r || jsonb_build_object('layout', p ->> 'layout');
  end if;
  -- Faixa: 11 fios, cada um um índice de 0 a 9.
  if p ? 'faixa' then
    x := p -> 'faixa';
    if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) <> 11 then perform interno.erro('invalido:faixa'); end if;
    for i in 0 .. 10 loop
      if jsonb_typeof(x -> i) <> 'number' or (x ->> i) !~ '^[0-9]$' then perform interno.erro('invalido:faixa'); end if;
    end loop;
    r := r || jsonb_build_object('faixa', x);
  end if;
  -- Rosto de pixels: 64 dígitos, ao menos 6 cheios; ou nulo.
  if p ? 'rosto' then
    if jsonb_typeof(p -> 'rosto') = 'null' then r := r || jsonb_build_object('rosto', null);
    else
      v := p ->> 'rosto';
      if jsonb_typeof(p -> 'rosto') <> 'string' or v !~ '^[0-9]{64}$' or char_length(replace(v, '0', '')) < 6 then perform interno.erro('invalido:rosto'); end if;
      r := r || jsonb_build_object('rosto', v);
    end if;
  end if;
  -- Capa em mosaico: palavra A–Z/0–9/espaço até 10 e semente 0..9999; ou nula.
  if p ? 'capa' then
    x := p -> 'capa';
    if jsonb_typeof(x) = 'null' then r := r || jsonb_build_object('capa', null);
    else
      if jsonb_typeof(x) <> 'object' or (x ->> 'tipo') is distinct from 'mosaico' or coalesce(x ->> 'palavra', '~') !~ '^[A-Z0-9 ]{0,10}$'
         or jsonb_typeof(x -> 'semente') <> 'number' or (x ->> 'semente') !~ '^[0-9]{1,4}$'
         or (select count(*) from jsonb_object_keys(x)) <> 3 then
        perform interno.erro('invalido:capa');
      end if;
      r := r || jsonb_build_object('capa', jsonb_build_object('tipo', 'mosaico', 'palavra', x ->> 'palavra', 'semente', (x ->> 'semente')::integer));
    end if;
  end if;
  -- Abas: só as conhecidas, sem repetir, com "posts".
  if p ? 'abas' then
    x := p -> 'abas';
    if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) > 7 then perform interno.erro('invalido:abas'); end if;
    vistos := '{}';
    for v in select value #>> '{}' from jsonb_array_elements(x) loop
      if v is null or not (v = any (abas)) or v = any (vistos) then perform interno.erro('invalido:abas'); end if;
      vistos := vistos || v;
    end loop;
    if not ('posts' = any (vistos)) then perform interno.erro('invalido:abas'); end if;
    r := r || jsonb_build_object('abas', to_jsonb(vistos));
  end if;
  -- Fixados: até 3 posts DA PRÓPRIA PESSOA, que não sejam repost nem estejam retidos/ocultos.
  if p ? 'fixados' then
    x := p -> 'fixados';
    if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) > 3 then perform interno.erro('invalido:fixados'); end if;
    vistos := '{}';
    for v in select value #>> '{}' from jsonb_array_elements(x) loop
      if v is null or v !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or v = any (vistos)
         or not exists (select 1 from rede_posts where id = v::uuid and autor = p_dono and repost_de is null and not oculto and not retido) then
        perform interno.erro('invalido:fixados');
      end if;
      vistos := vistos || v;
    end loop;
    r := r || jsonb_build_object('fixados', to_jsonb(vistos));
  end if;
  -- Destaques: até 6, post ou ato da própria pessoa, título 1..40, cor da paleta.
  if p ? 'destaques' then
    x := p -> 'destaques';
    if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) > 6 then perform interno.erro('invalido:destaques'); end if;
    vistos := '{}';
    for i in 0 .. jsonb_array_length(x) - 1 loop
      if jsonb_typeof(x -> i) <> 'object' or (select count(*) from jsonb_object_keys(x -> i)) <> 4
         or coalesce(x -> i ->> 'tipo', '') not in ('post', 'ato') or coalesce(x -> i ->> 'cor', '') <> all (paleta)
         or char_length(btrim(coalesce(x -> i ->> 'titulo', ''))) not between 1 and 40 or (x -> i ->> 'titulo') ~ '[\x00-\x1f<>]'
         or coalesce(x -> i ->> 'ref', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or (x -> i ->> 'ref') = any (vistos)
         or not exists (select 1 from rede_posts where id = (x -> i ->> 'ref')::uuid and autor = p_dono and not oculto and not retido
                        and ((x -> i ->> 'tipo') = 'post' or chamado is not null)) then
        perform interno.erro('invalido:destaques');
      end if;
      vistos := vistos || (x -> i ->> 'ref');
    end loop;
    r := r || jsonb_build_object('destaques', (select coalesce(jsonb_agg(jsonb_build_object('tipo', e ->> 'tipo', 'ref', e ->> 'ref', 'titulo', btrim(e ->> 'titulo'), 'cor', e ->> 'cor') order by o), '[]'::jsonb) from jsonb_array_elements(x) with ordinality as t(e, o)));
  end if;
  -- Organizações que a pessoa escolhe mostrar: até 6 @ de organizações COM SELO (opt-in, LGPD art. 11).
  if p ? 'orgs' then
    x := p -> 'orgs';
    if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) > 6 then perform interno.erro('invalido:orgs'); end if;
    vistos := '{}';
    for v in select value #>> '{}' from jsonb_array_elements(x) loop
      if v is null or v !~ '^[a-z0-9_]{3,20}$' or v = any (vistos)
         or not exists (select 1 from rede_orgs o join perfis f on f.id = o.perfil where f.rede_handle = v and o.verificada_em is not null) then
        perform interno.erro('invalido:orgs');
      end if;
      vistos := vistos || v;
    end loop;
    r := r || jsonb_build_object('orgs', to_jsonb(vistos));
  end if;
  -- "Tocando agora": texto até 80, link https limpo (ou nulo) e prazo entre agora e 30 dias.
  if p ? 'tocando' then
    x := p -> 'tocando';
    if jsonb_typeof(x) = 'null' then r := r || jsonb_build_object('tocando', null);
    else
      if jsonb_typeof(x) <> 'object' or char_length(btrim(coalesce(x ->> 'texto', ''))) not between 1 and 80 or (x ->> 'texto') ~ '[\x00-\x1f<>]' then
        perform interno.erro('invalido:tocando');
      end if;
      v := nullif(x ->> 'link', '');
      if v is not null and (char_length(v) > 200 or v !~ '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s<>"''`]*)?$' or v ~* rastreio) then
        perform interno.erro('invalido:tocando');
      end if;
      begin
        if (x ->> 'ate')::timestamptz <= now() or (x ->> 'ate')::timestamptz > now() + interval '30 days 1 minute' then perform interno.erro('invalido:tocando'); end if;
      exception when invalid_datetime_format or datetime_field_overflow or invalid_text_representation then perform interno.erro('invalido:tocando');
      end;
      r := r || jsonb_build_object('tocando', jsonb_build_object('texto', btrim(x ->> 'texto'), 'link', v, 'ate', (x ->> 'ate')::timestamptz));
    end if;
  end if;
  return r;
end $$;

-- ── 3. Ler e editar ───────────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * A aparência do perfil de alguém: a mesma matriz de rede_perfil_extras (invisível, bloqueado ou suspenso = nulo; visitante só
 * vê de organização com selo). "Tocando agora" vencido some; fixados e destaques que não servem mais (post apagado, retido,
 * oculto) somem; organizações que perderam o selo somem. Os fixados vão só como id: o post vem por rede_post, que confere quem vê.
 */
create or replace function public.rede_perfil_aparencia(p_handle text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); f perfis; a jsonb;
begin
  select * into f from perfis where rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  if not found or f.suspenso or ((f.rede_modo = 'invisivel' or f.rede_invisivel) and f.id is distinct from v) or interno.rede_bloqueado(v, f.id) then return null; end if;
  if v is null and not exists (select 1 from rede_orgs where perfil = f.id and verificada_em is not null) then return null; end if;
  a := coalesce(f.rede_aparencia, '{}'::jsonb);
  if a ? 'tocando' and jsonb_typeof(a -> 'tocando') = 'object' and (a -> 'tocando' ->> 'ate')::timestamptz <= now() then
    a := a || jsonb_build_object('tocando', null);
  end if;
  if jsonb_typeof(a -> 'fixados') = 'array' then
    a := a || jsonb_build_object('fixados', (select coalesce(jsonb_agg(e order by o), '[]'::jsonb) from jsonb_array_elements_text(a -> 'fixados') with ordinality as t(e, o)
      where exists (select 1 from rede_posts p where p.id = e::uuid and p.autor = f.id and not p.oculto and not p.retido)));
  end if;
  if jsonb_typeof(a -> 'destaques') = 'array' then
    a := a || jsonb_build_object('destaques', (select coalesce(jsonb_agg(e order by o), '[]'::jsonb) from jsonb_array_elements(a -> 'destaques') with ordinality as t(e, o)
      where exists (select 1 from rede_posts p where p.id = (e ->> 'ref')::uuid and p.autor = f.id and not p.oculto and not p.retido)));
  end if;
  if jsonb_typeof(a -> 'orgs') = 'array' then
    a := a || jsonb_build_object('orgs', (select coalesce(jsonb_agg(jsonb_build_object('handle', g.rede_handle, 'codinome', coalesce(g.rede_codinome, g.rede_handle)) order by o), '[]'::jsonb)
      from jsonb_array_elements_text(a -> 'orgs') with ordinality as t(e, o) join perfis g on g.rede_handle = e join rede_orgs ro on ro.perfil = g.id and ro.verificada_em is not null));
  end if;
  return a;
end $$;

/** Editar a minha aparência: só as chaves que vierem mudam (as outras ficam). Devolve a aparência inteira guardada. */
create or replace function public.rede_perfil_aparencia_editar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r jsonb;
begin
  perform interno.rede3_perfil_exige_membro(v);
  perform interno.limite('alumia_perfil_aparencia', 40, 60);
  r := interno.alumia_aparencia_valida(p, v);
  update perfis set rede_aparencia = coalesce(rede_aparencia, '{}'::jsonb) || r where id = v;
  return public.rede_perfil_aparencia((select rede_handle from perfis where id = v));
end $$;

/** Editar os meus extras (troca a da F4): campos até 6 (substitui todos). Status: some sozinho depois de `horas` (1 a 720). */
create or replace function public.rede_perfil_extras_editar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c jsonb; i integer := 0;
begin
  perform interno.rede3_perfil_exige_membro(v);
  perform interno.limite('alumia_perfil_extras', 30, 60);
  if p ? 'status' then
    if jsonb_typeof(p -> 'status') = 'object' then
      if coalesce(p -> 'status' ->> 'tipo', '') not in ('greve', 'ato', 'estudando', 'cuidando', 'ferias')
         or char_length(coalesce(p -> 'status' ->> 'texto', '')) > 60
         or coalesce(p -> 'status' ->> 'horas', '') !~ '^[0-9]{1,3}$' or (p -> 'status' ->> 'horas')::integer not between 1 and 720 then
        perform interno.erro('invalido:status');
      end if;
      update perfis set rede_status_tipo = p -> 'status' ->> 'tipo', rede_status_texto = btrim(coalesce(p -> 'status' ->> 'texto', '')),
        rede_status_ate = now() + make_interval(hours => (p -> 'status' ->> 'horas')::integer) where id = v;
    else
      update perfis set rede_status_tipo = null, rede_status_texto = null, rede_status_ate = null where id = v;
    end if;
  end if;
  if p ? 'pronomes' then
    if char_length(coalesce(p ->> 'pronomes', '')) > 30 then perform interno.erro('invalido:pronomes'); end if;
    update perfis set rede_pronomes = nullif(btrim(coalesce(p ->> 'pronomes', '')), '') where id = v;
  end if;
  if jsonb_typeof(p -> 'campos') = 'array' then
    if jsonb_array_length(p -> 'campos') > 6 then perform interno.erro('invalido:campos'); end if;
    delete from rede_perfil_campos where usuario = v;
    for c in select value from jsonb_array_elements(p -> 'campos') loop
      i := i + 1;
      -- Link no campo: só https e sem parâmetro de rastreio (o resto é texto).
      if coalesce(c ->> 'valor', '') ~* '^https?://' and (coalesce(c ->> 'valor', '') !~ '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s<>"''`]*)?$'
         or (c ->> 'valor') ~* '(^|[?&])(utm_[a-z_]+|fbclid|gclid|msclkid|igshid|igsh|si|mc_[a-z]+)=') then
        perform interno.erro('invalido:campos');
      end if;
      begin
        insert into rede_perfil_campos (usuario, ordem, rotulo, valor) values (v, i, btrim(coalesce(c ->> 'rotulo', '')), btrim(coalesce(c ->> 'valor', '')));
      exception when check_violation then perform interno.erro('invalido:campos');
      end;
    end loop;
  end if;
  return public.rede_perfil_extras((select rede_handle from perfis where id = v));
end $$;

-- ── 4. Tear de encaminhamentos (organização) ──────────────────────────────────────────────────────────────────────────────

/**
 * O tear de uma organização com selo. Todos veem o texto das deliberações e o agregado ("decidimos 12, cumprimos 9"); a FUNÇÃO
 * responsável e o prazo só quem gerencia ou é de um núcleo da organização vê (o público vê o agregado e o texto).
 */
create or replace function public.rede_org_tear(p_handle text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); o uuid; dentro boolean;
begin
  select ro.perfil into o from rede_orgs ro join perfis f on f.id = ro.perfil where f.rede_handle = lower(btrim(coalesce(p_handle, ''), ' @')) and ro.verificada_em is not null;
  if o is null or interno.rede_bloqueado(v, o) then return null; end if;
  dentro := v is not null and (interno.alumia_org_gere(v, o) or exists (
    select 1 from rede_nucleos n join rede_nucleo_membros m on m.nucleo = n.id where n.org = o and m.usuario = v));
  return jsonb_build_object(
    'decididos', (select count(*) from rede_org_encaminhamentos where org = o and estado <> 'retirado'),
    'cumpridos', (select count(*) from rede_org_encaminhamentos where org = o and estado = 'cumprido'),
    'dentro', dentro,
    'gerencio', v is not null and interno.alumia_org_gere(v, o),
    'fios', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'texto', e.texto, 'estado', e.estado, 'criado', e.criado_dia,
        'funcao', case when dentro then e.funcao end, 'prazo', case when dentro then e.prazo end,
        'vencido', e.estado = 'aberto' and e.prazo < current_date, 'cumprido', e.cumprido_dia) order by e.criado_dia desc, e.id), '[]'::jsonb)
      from (select * from rede_org_encaminhamentos where org = o and estado <> 'retirado' order by criado_dia desc, id limit 60) e));
end $$;

/** Quem gerencia tece um fio novo (texto, função, prazo) ou muda o estado de um (aberto, cumprido, retirado). */
create or replace function public.rede_org_tear_fio(p_handle text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); o uuid;
begin
  perform interno.rede3_perfil_exige_membro(v);
  o := interno.alumia_org_gestor(p_handle, 'alumia_org_tear', 60, 60);
  if p ? 'id' then
    if coalesce(p ->> 'estado', '') not in ('aberto', 'cumprido', 'retirado') then perform interno.erro('invalido:estado'); end if;
    update rede_org_encaminhamentos set estado = p ->> 'estado', cumprido_dia = case when p ->> 'estado' = 'cumprido' then current_date end
      where id = (p ->> 'id')::uuid and org = o;
    if not found then perform interno.erro('nao_encontrado'); end if;
  else
    begin
      if (p ->> 'prazo')::date < current_date or (p ->> 'prazo')::date > current_date + 730 then perform interno.erro('invalido:prazo'); end if;
    exception when invalid_datetime_format or datetime_field_overflow or invalid_text_representation then perform interno.erro('invalido:prazo');
    end;
    if (select count(*) from rede_org_encaminhamentos where org = o and estado = 'aberto') >= 200 then perform interno.erro('limite'); end if;
    begin
      insert into rede_org_encaminhamentos (org, texto, funcao, prazo) values (o, btrim(coalesce(p ->> 'texto', '')), btrim(coalesce(p ->> 'funcao', '')), (p ->> 'prazo')::date);
    exception when check_violation then perform interno.erro('invalido:fio');
    end;
  end if;
  return public.rede_org_tear(p_handle);
end $$;

-- ── 4b. As abas Respostas, Mídia e Atos do perfil ─────────────────────────────────────────────────────────────────────────

/**
 * Uma aba do perfil de pessoa (o cliente da F4 já chama esta função; faltava no banco): os posts da pessoa que respondem a outro
 * (respostas), que trazem imagem (midia: imagem no corpo em markdown ou link direto de imagem) ou que convocam um ato (atos), na
 * ordem de chegada, com a MESMA matriz da linha (rede_ve, silenciados) e a do perfil (invisível, bloqueado, suspenso = nada).
 */
create or replace function public.rede_perfil_linha(p_handle text, p_aba text, p_cursor text default null) returns jsonb
language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare
  v uuid := auth.uid(); f perfis; v_t timestamptz; v_id uuid; v_itens jsonb; v_n integer; v_ultimo jsonb; v_proximo text;
begin
  perform interno.aberta('comunidade');
  perform interno.limite('rede2_ler', 600, 60);
  if coalesce(p_aba, '') not in ('respostas', 'midia', 'atos') then perform interno.erro('invalido:aba'); end if;
  select * into f from perfis where rede_handle = lower(btrim(coalesce(p_handle, ''), ' @'));
  if not found or f.suspenso or ((f.rede_modo = 'invisivel' or f.rede_invisivel) and f.id is distinct from v) or interno.rede_bloqueado(v, f.id) then
    return jsonb_build_object('itens', '[]'::jsonb, 'proximo', null);
  end if;
  if nullif(p_cursor, '') is not null then
    begin
      v_t := split_part(p_cursor, '|', 1)::timestamptz;
      v_id := split_part(p_cursor, '|', 2)::uuid;
    exception when others then perform interno.erro('invalido:cursor');
    end;
  end if;
  select coalesce(jsonb_agg(interno.rede_post_v2(r, v) order by r.criado_em desc, r.id desc), '[]'::jsonb), count(*)::integer into v_itens, v_n
  from rede_posts r where r.id in (
    select p.id from rede_posts p
    where p.autor = f.id and not p.oculto and p.repost_de is null
      and (v_t is null or (p.criado_em, p.id) < (v_t, v_id))
      and case p_aba
        when 'respostas' then p.resposta_a is not null
        when 'midia' then coalesce(p.corpo, '') ~ '!\[[^\]]*\]\(https://' or p.texto ~* 'https://[^[:space:]]+\.(png|jpe?g|webp|gif|avif)([?#][^[:space:]]*)?([[:space:]]|$)'
        else (p.chamado ->> 'tipo') = 'ato' or p.ato is not null
      end
      and interno.rede_ve(p, v) and not interno.rede_silenciado(p, v)
    order by p.criado_em desc, p.id desc
    limit 21);
  if v_n > 20 then
    select coalesce(jsonb_agg(e.valor order by e.n), '[]'::jsonb) into v_itens from jsonb_array_elements(v_itens) with ordinality e(valor, n) where e.n <= 20;
    v_ultimo := v_itens -> 19;
    v_proximo := (v_ultimo ->> 'criado_em') || '|' || (v_ultimo ->> 'id');
  end if;
  return jsonb_build_object('itens', v_itens, 'proximo', v_proximo);
end $$;

-- ── 5. Permissões das funções ─────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare f text;
begin
  revoke all on function interno.alumia_aparencia_valida(jsonb, uuid) from public;
  foreach f in array array['public.rede_perfil_aparencia(text)', 'public.rede_perfil_aparencia_editar(jsonb)', 'public.rede_perfil_extras_editar(jsonb)',
    'public.rede_org_tear(text)', 'public.rede_org_tear_fio(text, jsonb)', 'public.rede_perfil_linha(text, text, text)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon, authenticated', f);
    end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.alumia_aparencia_valida(jsonb, uuid) from anon, authenticated;
    grant execute on function public.rede_perfil_aparencia(text), public.rede_org_tear(text), public.rede_perfil_linha(text, text, text) to anon;
    grant execute on function public.rede_perfil_aparencia(text), public.rede_perfil_aparencia_editar(jsonb), public.rede_perfil_extras_editar(jsonb),
      public.rede_org_tear(text), public.rede_org_tear_fio(text, jsonb), public.rede_perfil_linha(text, text, text) to authenticated;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════════════ Alumia · Onda A · atos: Farol do ato e Corrente de solidariedade (10/11/2026) ═══════════════════════════
-- docs/plano-2026-11/ALUMIA-FUNCOES-E-IDEIAS.md §2.1 (ideias 1 e 7) e PLANO-ALUMIA §6. Vem DEPOIS da F2
-- (20261109-alumia-f2.sql) e da F4 (20261109-alumia-f4.sql: rede_orgs, rede_org_gestores, rede_age_como). Idempotente: o teste
-- (scripts/testar-alumia-atos-banco.mjs) roda duas vezes no banco local. NÃO rodar em produção sem o Jonathan.
--
-- 1. FAROL DO ATO. Quem coordena o ato (quem age como quem chamou: a própria conta, uma identidade dela ou os gestores da
--    organização) acende um de quatro estados: tranquilo, atencao, dispersar, ponto2 (com o texto do novo ponto). A mudança só
--    vale quando DUAS pessoas diferentes da coordenação pedem o mesmo estado em até 15 minutos (a segunda confirma). Quem confirmou
--    presença recebe um aviso SEM o estado no texto ("o farol mudou"); a tela busca o estado. O registro da moderação guarda cada
--    mudança (interno.registrar), contra uso indevido. Quem recebeu não fica registrado.
-- 2. CORRENTE DE SOLIDARIEDADE. Uma organização com selo abre "precisamos de N pessoas às 5h na ocupação X" para uma CIDADE
--    ESCRITA (nunca posição). As pessoas respondem "vou"; a barra de elos fecha em passos de 10 %, só a partir de 3 respostas.
--    Quando a meta é atingida, a corrente fecha e para de aparecer. Limite: 2 correntes por organização por semana.
--
-- Privacidade (LGPD, Lei 13.709/2018: art. 5º, II e art. 11 — ir a um ato revela opinião política, dado sensível; art. 6º, III —
-- necessidade): nenhuma função devolve quem confirmou, quem respondeu "vou" ou quem pediu o farol; a corrente mostra só a
-- proporção (nula abaixo de 3) e o total exato só a quem age como a organização que abriu; o vínculo pessoa↔organização nunca
-- volta para ninguém. ECA (Lei 8.069/1990) e ECA Digital (Lei 15.211/2025): tudo exige membro 18+ (interno.rede2_membro).

-- ── 1. Tabelas ──────────────────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.rede_ato_farol (
  post uuid primary key references interno.rede_posts (id) on delete cascade,
  estado text not null default 'tranquilo' check (estado in ('tranquilo', 'atencao', 'dispersar', 'ponto2')),
  texto text not null default '' check (char_length(texto) <= 140),
  mudado_em timestamptz not null default now()
);
-- Um pedido esperando a segunda pessoa por ato. Guarda quem pediu SÓ para impedir que a mesma pessoa confirme o próprio pedido;
-- nenhuma função devolve esse campo (só "o pedido é seu?").
create table if not exists interno.rede_ato_farol_pedidos (
  post uuid primary key references interno.rede_posts (id) on delete cascade,
  estado text not null check (estado in ('tranquilo', 'atencao', 'dispersar', 'ponto2')),
  texto text not null default '' check (char_length(texto) <= 140),
  pedido_por uuid not null references interno.perfis (id) on delete cascade,
  pedido_em timestamptz not null default now()
);
create table if not exists interno.rede_correntes (
  id uuid primary key default gen_random_uuid(),
  autor uuid not null references interno.perfis (id) on delete cascade,
  texto text not null check (char_length(texto) between 10 and 140),
  cidade text not null check (char_length(cidade) between 2 and 80),
  meta smallint not null check (meta between 3 and 5000),
  quando timestamptz,
  criada_em timestamptz not null default now(),
  expira_em timestamptz not null,
  fechada_em timestamptz
);
create index if not exists rede_correntes_cidade on interno.rede_correntes (interno.rede_ato_cidade(cidade), expira_em);
create index if not exists rede_correntes_autor on interno.rede_correntes (autor, criada_em);
create table if not exists interno.rede_corrente_vou (
  corrente uuid not null references interno.rede_correntes (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  primary key (corrente, usuario)
);
create index if not exists rede_corrente_vou_usuario on interno.rede_corrente_vou (usuario);
alter table interno.rede_ato_farol enable row level security;
alter table interno.rede_ato_farol_pedidos enable row level security;
alter table interno.rede_correntes enable row level security;
alter table interno.rede_corrente_vou enable row level security;
revoke all on table interno.rede_ato_farol, interno.rede_ato_farol_pedidos, interno.rede_correntes, interno.rede_corrente_vou from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_ato_farol, interno.rede_ato_farol_pedidos, interno.rede_correntes, interno.rede_corrente_vou from anon, authenticated;
  end if;
end $$;

-- ── 2. Farol ────────────────────────────────────────────────────────────────────────────────────────────────────────────────

/** O farol como a tela recebe (FarolDoAto em lib/rede/tipos-atos.ts). `coordena` diz se quem lê pode pedir mudança. */
create or replace function interno.rede_ato_farol_json(p_id uuid, p_quem uuid, p_coordena boolean) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare f rede_ato_farol; q rede_ato_farol_pedidos;
begin
  select * into f from rede_ato_farol where post = p_id;
  if p_coordena then
    select * into q from rede_ato_farol_pedidos where post = p_id and pedido_em > now() - interval '15 minutes';
  end if;
  return jsonb_build_object(
    'estado', coalesce(f.estado, 'tranquilo'),
    'texto', coalesce(f.texto, ''),
    'mudado_em', f.mudado_em,
    'coordena', p_coordena,
    'pendente', case when q.post is null then null else jsonb_build_object('estado', q.estado, 'texto', q.texto,
      'meu', q.pedido_por = p_quem, 'expira_em', q.pedido_em + interval '15 minutes') end);
end $$;

/**
 * O farol de um ato. Só para quem confirmou presença ou coordena (os outros recebem nulo: o farol é para quem está indo).
 * Visitante: nulo.
 */
create or replace function public.rede_ato_farol(p_id uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); p rede_posts; v_coord boolean;
begin
  perform interno.aberta('comunidade');
  if v is null or not interno.rede2_membro(v) then return null; end if;
  p := interno.rede_ato_achar(p_id, v);
  v_coord := interno.rede_age_como(v, p.autor);
  if not v_coord and not exists (select 1 from rede_vou o where o.post = p_id and o.usuario = v) then return null; end if;
  return interno.rede_ato_farol_json(p_id, v, v_coord);
end $$;

/**
 * Pedir (ou confirmar) um estado do farol. Só quem coordena. Se já existe um pedido de OUTRA pessoa com o mesmo estado e texto,
 * nos últimos 15 minutos, esta chamada é a confirmação: o farol muda, o pedido some, quem confirmou presença recebe o aviso sem o
 * estado no texto e a mudança vai ao registro. Senão, este passa a ser o pedido esperando a segunda pessoa (os outros gestores da
 * organização recebem "confirme no ato", sem o nome de quem pediu). A mesma pessoa repetir o próprio pedido não confirma nada.
 */
create or replace function public.rede_ato_farol_pedir(p_id uuid, p_estado text, p_texto text default '') returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); p rede_posts; c rede_chamados; q rede_ato_farol_pedidos; g record;
  v_texto text := regexp_replace(btrim(coalesce(p_texto, '')), '\s+', ' ', 'g');
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  p := interno.rede_ato_achar(p_id, v);
  if not interno.rede_age_como(v, p.autor) then perform interno.erro('so_coordenacao'); end if;
  if p_estado is null or p_estado not in ('tranquilo', 'atencao', 'dispersar', 'ponto2') then perform interno.erro('invalido:estado'); end if;
  if p_estado <> 'ponto2' then v_texto := ''; end if;
  if p_estado = 'ponto2' and char_length(v_texto) < 3 then perform interno.erro('invalido:texto'); end if;
  if char_length(v_texto) > 140 then perform interno.erro('invalido:texto'); end if;
  if interno.rede3_pub_dado_pessoal(v_texto) then perform interno.erro('dado_pessoal'); end if;
  select * into c from rede_chamados where post = p_id;
  if c.situacao = 'cancelado' then perform interno.erro('ato_cancelado'); end if;
  perform interno.limite('alumia_ato_farol', 20, 60);

  select * into q from rede_ato_farol_pedidos where post = p_id for update;
  if q.post is not null and q.pedido_em > now() - interval '15 minutes' and q.pedido_por <> v
     and q.estado = p_estado and q.texto = v_texto then
    -- A segunda pessoa confirmou: vale.
    insert into rede_ato_farol (post, estado, texto, mudado_em) values (p_id, p_estado, v_texto, now())
    on conflict (post) do update set estado = excluded.estado, texto = excluded.texto, mudado_em = excluded.mudado_em;
    delete from rede_ato_farol_pedidos where post = p_id;
    perform interno.registrar('alumia_ato_farol', p_id::text, jsonb_build_object('estado', p_estado, 'texto', v_texto));
    for g in select o.usuario from rede_vou o where o.post = p_id and o.usuario <> v loop
      if interno.rede2_membro(g.usuario) and interno.rede_ve(p, g.usuario) and not interno.rede_age_como(g.usuario, p.autor) then
        perform interno.rede3_aviso_criar(g.usuario, 'chamado', p_id, null, null, 'O farol de um ato que você confirmou mudou. Abra o ato.');
      end if;
    end loop;
  else
    insert into rede_ato_farol_pedidos (post, estado, texto, pedido_por, pedido_em) values (p_id, p_estado, v_texto, v, now())
    on conflict (post) do update set estado = excluded.estado, texto = excluded.texto, pedido_por = excluded.pedido_por, pedido_em = excluded.pedido_em;
    for g in select gs.gestor from rede_org_gestores gs where gs.org = p.autor and gs.gestor <> v loop
      perform interno.avisar_em(g.gestor, 'Alguém da coordenação pediu para mudar o farol de um ato. Abra o ato para confirmar.', 'rede');
    end loop;
  end if;
  return interno.rede_ato_farol_json(p_id, v, true);
end $$;

-- ── 3. Corrente de solidariedade ────────────────────────────────────────────────────────────────────────────────────────────

/** Elos fechados: a MESMA regra do mosaico (nula abaixo de 3; passos de 10 %, para baixo; 100 % quando bate a meta). */
create or replace function interno.rede_corrente_elos(p_n bigint, p_meta integer) returns numeric language sql immutable set search_path = interno, pg_temp as $$
  select case when p_n is null or p_n < 3 then null
    else round(least(10, greatest(1, floor(p_n::numeric * 10 / greatest(3, coalesce(p_meta, 3)))))::numeric / 10, 1) end
$$;

create or replace function interno.rede_corrente_json(k interno.rede_correntes, p_quem uuid) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare f perfis; v_n bigint := (select count(*) from rede_corrente_vou o where o.corrente = k.id);
begin
  select * into f from perfis where id = k.autor;
  return jsonb_build_object(
    'id', k.id, 'texto', k.texto, 'cidade', k.cidade, 'meta', k.meta, 'quando', k.quando, 'expira_em', k.expira_em,
    'org', jsonb_build_object('handle', f.rede_handle, 'nome', interno.rede_nome(k.autor)),
    'elos', interno.rede_corrente_elos(v_n, k.meta),
    'fechada', k.fechada_em is not null,
    'vou_eu', p_quem is not null and exists (select 1 from rede_corrente_vou o where o.corrente = k.id and o.usuario = p_quem),
    'total', case when p_quem is not null and interno.rede_age_como(p_quem, k.autor) then v_n end);
end $$;

/** As organizações COM SELO que esta pessoa gerencia (para o "Abrir corrente"). Só sobre si mesma. */
create or replace function public.rede_corrente_posso() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  if v is null or not interno.rede2_membro(v) then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', o.perfil, 'handle', f.rede_handle, 'nome', interno.rede_nome(o.perfil)) order by f.rede_handle)
    from rede_orgs o join perfis f on f.id = o.perfil
   where o.verificada_em is not null and interno.rede_age_como(v, o.perfil)), '[]'::jsonb);
end $$;

/**
 * Abrir uma corrente (como uma organização com selo que a pessoa gerencia). p: org (uuid), texto (10–140), cidade (2–80), meta
 * (3–5000), quando (ISO, opcional, até 30 dias). Some sozinha 6 h depois de `quando` (ou em 3 dias sem hora). 2 por semana.
 */
create or replace function public.rede_corrente_abrir(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); k rede_correntes;
  v_org uuid; v_texto text; v_cidade text; v_meta integer; v_quando timestamptz;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  begin
    v_org := (p ->> 'org')::uuid;
  exception when others then
    perform interno.erro('invalido:org');
  end;
  if v_org is null or not exists (select 1 from rede_orgs o where o.perfil = v_org and o.verificada_em is not null)
     or not interno.rede_age_como(v, v_org) then perform interno.erro('so_org_verificada'); end if;
  v_texto := interno.txt(regexp_replace(coalesce(p ->> 'texto', ''), '\s+', ' ', 'g'), 'texto', 10, 140);
  v_cidade := interno.txt(regexp_replace(coalesce(p ->> 'cidade', ''), '\s+', ' ', 'g'), 'cidade', 2, 80);
  if interno.rede3_pub_dado_pessoal(v_texto) then perform interno.erro('dado_pessoal'); end if;
  begin
    v_meta := (p ->> 'meta')::integer;
  exception when others then
    perform interno.erro('invalido:meta');
  end;
  if v_meta is null or v_meta < 3 or v_meta > 5000 then perform interno.erro('invalido:meta'); end if;
  if coalesce(p ->> 'quando', '') <> '' then
    begin
      v_quando := (p ->> 'quando')::timestamptz;
    exception when others then
      perform interno.erro('invalido:quando');
    end;
    if v_quando <= now() or v_quando > now() + interval '30 days' then perform interno.erro('invalido:quando'); end if;
  end if;
  if (select count(*) from rede_correntes where autor = v_org and criada_em > now() - interval '7 days') >= 2 then
    perform interno.erro('muitos_pedidos');
  end if;
  perform interno.limite('alumia_corrente', 6, 60);
  insert into rede_correntes (autor, texto, cidade, meta, quando, expira_em)
  values (v_org, v_texto, v_cidade, v_meta, v_quando, coalesce(v_quando + interval '6 hours', now() + interval '3 days'))
  returning * into k;
  perform interno.registrar('alumia_corrente_abrir', k.id::text, jsonb_build_object('org', v_org, 'cidade', v_cidade));
  return interno.rede_corrente_json(k, v);
end $$;

/** As correntes abertas da cidade ESCRITA (texto; nada de posição). Só para membro (visitante recebe lista vazia). Até 10. */
create or replace function public.rede_correntes(p_cidade text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_cidade text := interno.rede_ato_cidade(left(coalesce(p_cidade, ''), 80));
begin
  perform interno.aberta('comunidade');
  if v is null or not interno.rede2_membro(v) or v_cidade is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(interno.rede_corrente_json(k, v) order by k.criada_em desc)
    from (select * from rede_correntes k
           where interno.rede_ato_cidade(k.cidade) = v_cidade and k.fechada_em is null and k.expira_em > now()
             and not exists (select 1 from rede_bloqueios b where (b.quem = k.autor and b.bloqueado = v) or (b.quem = v and b.bloqueado = k.autor))
           order by k.criada_em desc limit 10) k), '[]'::jsonb);
end $$;

/** "Vou" (ou desfazer) numa corrente aberta. Quando bate a meta, a corrente fecha (e deixa de aparecer na lista). */
create or replace function public.rede_corrente_vou(p_id uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); k rede_correntes; v_n bigint;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  perform interno.rede2_limite('reagir');
  select * into k from rede_correntes where id = p_id for update;
  if not found or exists (select 1 from rede_bloqueios b where (b.quem = k.autor and b.bloqueado = v) or (b.quem = v and b.bloqueado = k.autor)) then
    perform interno.erro('nao_encontrado');
  end if;
  if coalesce(p_sim, true) then
    if k.fechada_em is not null or k.expira_em <= now() then perform interno.erro('corrente_fechada'); end if;
    insert into rede_corrente_vou (corrente, usuario) values (p_id, v) on conflict do nothing;
  else
    delete from rede_corrente_vou where corrente = p_id and usuario = v;
  end if;
  select count(*) into v_n from rede_corrente_vou where corrente = p_id;
  if k.fechada_em is null and v_n >= k.meta then
    update rede_correntes set fechada_em = now() where id = p_id returning * into k;
  else
    select * into k from rede_correntes where id = p_id;
  end if;
  return interno.rede_corrente_json(k, v);
end $$;

-- ── 4. Permissões ───────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.rede_ato_farol_json(uuid, uuid, boolean), interno.rede_corrente_elos(bigint, integer),
  interno.rede_corrente_json(interno.rede_correntes, uuid) from public;
revoke all on function public.rede_ato_farol(uuid), public.rede_ato_farol_pedir(uuid, text, text), public.rede_corrente_posso(),
  public.rede_corrente_abrir(jsonb), public.rede_correntes(text), public.rede_corrente_vou(uuid, boolean) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_ato_farol_json(uuid, uuid, boolean), interno.rede_corrente_elos(bigint, integer),
      interno.rede_corrente_json(interno.rede_correntes, uuid) from anon, authenticated;
    revoke all on function public.rede_ato_farol_pedir(uuid, text, text), public.rede_corrente_abrir(jsonb), public.rede_corrente_vou(uuid, boolean) from anon;
    grant execute on function public.rede_ato_farol(uuid), public.rede_correntes(text), public.rede_corrente_posso() to anon, authenticated, service_role;
    grant execute on function public.rede_ato_farol_pedir(uuid, text, text), public.rede_corrente_abrir(jsonb), public.rede_corrente_vou(uuid, boolean)
      to authenticated, service_role;
  end if;
end $$;

-- ═══════════════════════════ fim dos atos da Onda A (Farol e Corrente) ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
--
-- ═══════════════════ Alumia · polimento da comunidade e da conversa · seguir conversa e #tema (10/11/2026) ═══════════════════
-- docs/plano-2026-11/ALUMIA-FUNCOES-E-IDEIAS.md (Onda B: "seguir conversa" e "seguir hashtag") e PLANO-ALUMIA.md §6 e §12.
--   1. Seguir a conversa (rede_alumia_seguir_conversa): o sininho na barra "CONVERSA". Quem segue recebe aviso de resposta
--      nova na conversa inteira, AGRUPADO pela conversa (o mesmo grupo "resposta:<raiz>" de rede3_aviso_grupos), respeitando a
--      preferência "respostas" da pessoa, o bloqueio e a matriz de visibilidade.
--   2. Seguir um #tema (rede_alumia_seguir_tag, rede_alumia_tags_seguidas): a lista dos #temas que a PRÓPRIA pessoa segue,
--      mostrada no Explorar e na página do #tema. Não muda ordem de nada (sem algoritmo) e não gera aviso (sem ruído).
--   3. rede_alumia_seguindo: se a pessoa segue esta conversa e/ou este #tema (só ela pergunta sobre ela mesma).
--
-- Regras (PLANO-ALUMIA §5): tabelas em interno, RLS ligada e nenhuma permissão para anon/authenticated; acesso só pelas funções
-- security definer abaixo. Nenhuma função devolve QUEM segue nem QUANTOS seguem (nem o total agregado: seguir é sinal de
-- interesse político, e uma contagem por conversa viraria métrica de engajamento, PLANO-ALUMIA §12).
--
-- Leis (conferidas no texto): LGPD (Lei 13.709/2018) art. 5º, II e art. 11 — opinião política é dado sensível: o que alguém segue
-- só ela vê; art. 6º, III (necessidade): guarda só pessoa, conversa/tema e data, e some com a conta ou com o post (cascata);
-- art. 18, VI: deixar de seguir apaga a linha; art. 46: RLS e nenhuma permissão direta. ECA (Lei 8.069/1990) e ECA Digital (Lei
-- 15.211/2025): só membro da Rede (18+ confirmado, interno.rede2_membro) segue.
--
-- Idempotente (scripts/testar-alumia-comunidade.mjs roda duas vezes no banco local). Roda depois da F0..F5 e do Fediverso.
-- NÃO rodar em produção sem o Jonathan.

-- ── 1. Tabelas ────────────────────────────────────────────────────────────────────────────────────────────────────────────

create table if not exists interno.rede_alumia_seguir_conversa (
  raiz uuid not null references interno.rede_posts (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  criado_em timestamptz not null default now(),
  primary key (raiz, usuario)
);
create index if not exists rede_alumia_seguir_conversa_usuario on interno.rede_alumia_seguir_conversa (usuario);
alter table interno.rede_alumia_seguir_conversa enable row level security;

create table if not exists interno.rede_alumia_seguir_tag (
  usuario uuid not null references interno.perfis (id) on delete cascade,
  tag text not null check (tag ~ '^[a-z0-9_]{2,40}$' and tag ~ '[a-z_]'),
  criado_em timestamptz not null default now(),
  primary key (usuario, tag)
);
alter table interno.rede_alumia_seguir_tag enable row level security;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on table interno.rede_alumia_seguir_conversa, interno.rede_alumia_seguir_tag from anon, authenticated;
  end if;
end $$;

-- ── 2. Seguir a conversa ──────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Segue (p_sim = true) ou deixa de seguir a conversa do post p_post (sempre pela raiz). Só membro, que vê a raiz e o post, sem
 * bloqueio com quem abriu a conversa e não banido da comunidade. Até 500 conversas seguidas por pessoa. Devolve {seguindo}.
 */
create or replace function public.rede_alumia_seguir_conversa(p_post uuid, p_sim boolean default true) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts; r rede_posts;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  select * into x from rede_posts where id = p_post;
  if not found or not interno.rede_ve(x, v) or x.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
  r := interno.rede3_conv_raiz(x);
  if r.id is null or not interno.rede_ve(r, v) or r.oculto or r.retido or r.apagado_em is not null then perform interno.erro('nao_encontrado'); end if;
  if not coalesce(p_sim, true) then
    delete from rede_alumia_seguir_conversa where raiz = r.id and usuario = v;
    return jsonb_build_object('seguindo', false);
  end if;
  if r.autor is not null and interno.rede_bloqueado(v, r.autor) then perform interno.erro('nao_encontrado'); end if;
  if r.comunidade is not null and interno.rede3_com_situacao(r.comunidade, v) = 'banido' then perform interno.erro('sem_permissao'); end if;
  perform interno.rede2_limite('seguir');
  if not exists (select 1 from rede_alumia_seguir_conversa where raiz = r.id and usuario = v)
     and (select count(*) from rede_alumia_seguir_conversa where usuario = v) >= 500 then
    perform interno.erro('invalido:muitas');
  end if;
  insert into rede_alumia_seguir_conversa (raiz, usuario) values (r.id, v) on conflict do nothing;
  return jsonb_build_object('seguindo', true);
end $$;

-- ── 3. Seguir um #tema ────────────────────────────────────────────────────────────────────────────────────────────────────

/** Segue (p_sim = true) ou deixa de seguir um #tema (com ou sem #, com ou sem acento). Até 100 por pessoa. Devolve {seguindo}. */
create or replace function public.rede_alumia_seguir_tag(p_tag text, p_sim boolean default true) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_tag text;
begin
  perform interno.aberta('comunidade');
  if not interno.rede2_membro(v) then perform interno.erro('consentimento'); end if;
  v_tag := interno.rede3_desc_tag_norm(p_tag);
  if not coalesce(p_sim, true) then
    delete from rede_alumia_seguir_tag where usuario = v and tag = v_tag;
    return jsonb_build_object('seguindo', false);
  end if;
  perform interno.rede2_limite('seguir');
  if not exists (select 1 from rede_alumia_seguir_tag where usuario = v and tag = v_tag)
     and (select count(*) from rede_alumia_seguir_tag where usuario = v) >= 100 then
    perform interno.erro('invalido:muitas');
  end if;
  insert into rede_alumia_seguir_tag (usuario, tag) values (v, v_tag) on conflict do nothing;
  return jsonb_build_object('seguindo', true);
end $$;

/** Os #temas que a própria pessoa segue, em ordem alfabética: {tags}. Visitante recebe a lista vazia. */
create or replace function public.rede_alumia_tags_seguidas() returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  perform interno.aberta('comunidade');
  if v is null then return jsonb_build_object('tags', '[]'::jsonb); end if;
  return jsonb_build_object('tags', (select coalesce(jsonb_agg(tag order by tag), '[]'::jsonb) from rede_alumia_seguir_tag where usuario = v));
end $$;

/**
 * Se a pessoa segue a conversa de p_post e/ou o #tema p_tag: {conversa, tag}. Nulo no que não foi perguntado; visitante recebe
 * nulo nos dois (a tela não mostra o botão). Post que ela não vê responde como não seguido (sem confirmar que existe).
 */
create or replace function public.rede_alumia_seguindo(p_post uuid default null, p_tag text default null) returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); x rede_posts; v_conv boolean; v_tag boolean;
begin
  perform interno.aberta('comunidade');
  if v is null then return jsonb_build_object('conversa', null, 'tag', null); end if;
  perform interno.limite('rede2_ler', 600, 60);
  if p_post is not null then
    select * into x from rede_posts where id = p_post;
    v_conv := found and interno.rede_ve(x, v) and exists (select 1 from rede_alumia_seguir_conversa s where s.raiz = coalesce(x.root_id, x.id) and s.usuario = v);
  end if;
  if nullif(btrim(coalesce(p_tag, '')), '') is not null then
    v_tag := exists (select 1 from rede_alumia_seguir_tag s where s.usuario = v and s.tag = interno.rede3_desc_tag_norm(p_tag));
  end if;
  return jsonb_build_object('conversa', v_conv, 'tag', v_tag);
end $$;

-- ── 4. O aviso agrupado de quem segue a conversa ──────────────────────────────────────────────────────────────────────────

/**
 * Resposta nova numa conversa: avisa quem segue (menos quem escreveu e quem recebeu a resposta, que a fundação já avisa), só se
 * essa pessoa pode ver a resposta. O aviso entra no grupo "resposta:<raiz>" (rede3_aviso_grupos): várias respostas viram UMA linha
 * "N respostas". rede3_aviso_criar confere bloqueio, conta suspensa e a preferência "respostas" no site. Até 500 por resposta.
 */
create or replace function interno.rede_alumia_aviso_seguidores() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_raiz uuid := coalesce(new.root_id, new.id); v_pai uuid; s record;
begin
  if new.resposta_a is null or new.oculto or new.retido or new.apagado_em is not null then return null; end if;
  if not exists (select 1 from rede_alumia_seguir_conversa where raiz = v_raiz) then return null; end if;
  select autor into v_pai from rede_posts where id = new.resposta_a;
  for s in
    select usuario from rede_alumia_seguir_conversa
     where raiz = v_raiz and usuario is distinct from new.autor and usuario is distinct from v_pai
     order by criado_em limit 500
  loop
    if interno.rede_ve(new, s.usuario) then
      perform interno.rede3_aviso_criar(s.usuario, 'resposta', v_raiz, new.id, new.autor, 'Há respostas novas numa conversa que você segue na Alumia.');
    end if;
  end loop;
  return null;
end $$;
drop trigger if exists rede_alumia_aviso_seguidores on interno.rede_posts;
create trigger rede_alumia_aviso_seguidores after insert on interno.rede_posts for each row execute function interno.rede_alumia_aviso_seguidores();

-- ── 5. Permissões ─────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.rede_alumia_aviso_seguidores() from public;
revoke all on function public.rede_alumia_seguir_conversa(uuid, boolean), public.rede_alumia_seguir_tag(text, boolean),
  public.rede_alumia_tags_seguidas(), public.rede_alumia_seguindo(uuid, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function interno.rede_alumia_aviso_seguidores() from anon, authenticated;
    revoke all on function public.rede_alumia_seguir_conversa(uuid, boolean), public.rede_alumia_seguir_tag(text, boolean),
      public.rede_alumia_tags_seguidas(), public.rede_alumia_seguindo(uuid, text) from anon, authenticated;
    grant execute on function public.rede_alumia_tags_seguidas(), public.rede_alumia_seguindo(uuid, text) to anon, authenticated, service_role;
    grant execute on function public.rede_alumia_seguir_conversa(uuid, boolean), public.rede_alumia_seguir_tag(text, boolean) to authenticated, service_role;
  end if;
end $$;

-- ═══════════════════════════ fim da Alumia · comunidade (seguir conversa e #tema) ═══════════════════════════

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
-- Gaveta Aberta sem conta (09/11/2026): qualquer pessoa envia por link; o envio cai na fila de aprovação do painel. O PDF
-- no depósito continua pedindo conta. Quem enviou sem conta não recebe aviso (não há para quem avisar).

alter table interno.gaveta alter column autor drop not null;

create or replace function public.gaveta_enviar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid; v_id uuid; v_tipo text := coalesce(p ->> 'tipo', ''); v_licenca text := coalesce(nullif(p ->> 'licenca', ''), 'CC BY 4.0');
  v_link text := btrim(coalesce(p ->> 'link', '')); v_arquivo text := btrim(coalesce(p ->> 'arquivo', '')); v_ano smallint;
  v_titulo text; v_comentario text; v_curso text; v_instituicao text; v_credito text; v_termo_nome text; v_disciplina text;
  v_exercicio uuid;
begin
  perform interno.aberta('gaveta');
  -- Sem conta também se envia (09/11/2026), só por link: o PDF no depósito continua pedindo conta (a pasta é da pessoa).
  -- Sem conta, o limite é por origem e menor; tudo cai na mesma fila de aprovação do painel.
  if auth.uid() is null then
    if btrim(coalesce(p ->> 'arquivo', '')) <> '' then perform interno.erro('entre_primeiro'); end if;
    perform interno.limite('gaveta_sem_conta', 2, 1440);
  else
    v := interno.eu();
    perform interno.limite('gaveta', 5, 1440);
  end if;
  if not coalesce((p ->> 'termo')::boolean, false) or coalesce(p ->> 'termo_versao', '') <> interno.gaveta_termo_versao() then perform interno.erro('falta_termo'); end if;
  if v_tipo not in ('tcc', 'monografia', 'dissertacao', 'artigo', 'projeto', 'relatorio', 'apostila', 'codigo', 'apresentacao', 'outro') then perform interno.erro('invalido:tipo'); end if;
  if v_licenca not in ('CC BY 4.0', 'CC BY-SA 4.0', 'CC0 1.0') then perform interno.erro('invalido:licenca'); end if;
  v_disciplina := interno.disciplina_ok(p ->> 'disciplina');
  if v_disciplina is null then perform interno.erro('invalido:disciplina'); end if;
  v_titulo := interno.txt(p ->> 'titulo', 'titulo', 5, 160);
  v_comentario := interno.txt(p ->> 'comentario', 'comentario', 40, 2000);
  v_curso := interno.txt(p ->> 'curso', 'curso', 0, 120);
  v_instituicao := interno.txt(p ->> 'instituicao', 'instituicao', 0, 160);
  v_credito := interno.txt(p ->> 'credito', 'credito', 2, 120);
  v_termo_nome := interno.txt(p ->> 'termo_nome', 'termo_nome', 5, 160);
  if coalesce(p ->> 'ano', '') <> '' then
    if (p ->> 'ano') !~ '^[0-9]{4}$' or (p ->> 'ano')::int < 1950 or (p ->> 'ano')::int > extract(year from now())::int then perform interno.erro('invalido:ano'); end if;
    v_ano := (p ->> 'ano')::smallint;
  end if;
  if (v_link = '') = (v_arquivo = '') then perform interno.erro('invalido:arquivo'); end if;
  if v_link <> '' and (v_link !~ '^https://[^[:space:]]+$' or char_length(v_link) > 500) then perform interno.erro('invalido:link'); end if;
  -- O PDF tem de estar na pasta da própria pessoa; onde o depósito existe, confere que o arquivo chegou mesmo.
  if v_arquivo <> '' then
    if v_arquivo !~ ('^' || v::text || '/[0-9a-f-]{36}[.]pdf$') then perform interno.erro('invalido:arquivo'); end if;
    if to_regclass('storage.objects') is not null then
      if not exists (select 1 from storage.objects where bucket_id = 'gaveta' and name = v_arquivo) then perform interno.erro('invalido:arquivo'); end if;
    end if;
  end if;
  if interno.vetado(v_titulo || ' ' || v_comentario || ' ' || v_curso || ' ' || v_instituicao || ' ' || v_credito) then perform interno.erro('conteudo_recusado'); end if;
  -- Entrega de um exercício de prática: o exercício tem de existir, estar ativo e ser da mesma disciplina.
  if coalesce(p ->> 'exercicio', '') <> '' then
    if (p ->> 'exercicio') !~ '^[0-9a-f-]{36}$' then perform interno.erro('invalido:exercicio'); end if;
    v_exercicio := (p ->> 'exercicio')::uuid;
    if not exists (select 1 from exercicios_pratica where id = v_exercicio and ativo and disciplina = v_disciplina) then perform interno.erro('invalido:exercicio'); end if;
  end if;
  insert into gaveta (autor, titulo, tipo, disciplina, curso, instituicao, ano, comentario, link, arquivo, licenca, credito, termo_nome, termo_versao, exercicio)
  values (v, v_titulo, v_tipo, v_disciplina, v_curso, v_instituicao, v_ano, v_comentario, v_link, v_arquivo, v_licenca, v_credito, v_termo_nome, interno.gaveta_termo_versao(), v_exercicio)
  returning id into v_id;
  if v_exercicio is not null then
    perform interno.avisar(p2.usuario, 'Chegou uma entrega do exercício "' || left(x.titulo, 80) || '". Veja em Exercícios de prática.')
    from exercicios_pratica x join papeis p2 on p2.papel in ('educacao', 'educacao_secundaria') and p2.disciplina = x.disciplina
    where x.id = v_exercicio;
  end if;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.gaveta_decidir(p_id uuid, p_aprovar boolean, p_nota text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); g gaveta; v_nota text := interno.txt(p_nota, 'nota', 0, 1000); v_aprovar boolean := coalesce(p_aprovar, false);
begin
  if not interno.media() then perform interno.erro('sem_permissao'); end if;
  select * into g from gaveta where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if g.status not in ('pendente', 'aprovado', 'recusado') then perform interno.erro('ja_decidida'); end if;
  if not v_aprovar and char_length(v_nota) < 5 then perform interno.erro('invalido:nota'); end if;
  update gaveta set status = case when v_aprovar then 'aprovado' else 'recusado' end, nota = v_nota, decidido_por = v, decidido_em = now() where id = p_id;
  perform interno.registrar(case when v_aprovar then 'gaveta_aprovada' else 'gaveta_recusada' end, g.titulo);
  if g.autor is not null then perform interno.avisar(g.autor, case when v_aprovar then 'Seu trabalho "' || left(g.titulo, 80) || '" foi publicado na Gaveta Aberta.'
    else 'Seu trabalho "' || left(g.titulo, 80) || '" não foi publicado na Gaveta Aberta: ' || left(v_nota, 300) end); end if;
  return jsonb_build_object('ok', true);
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
-- O cartão público do educador com aprovação (09/11/2026). No painel (Minha conta, Faixa de e-mail, "Visão pública"),
-- o voluntário pede a foto, a biografia e as redes do cartão que aparece no fim das aulas; a coordenação aprova ou
-- recusa com motivo. Só depois da aprovação o cartão muda. A foto vem já reduzida pelo navegador (WebP, até 150 KB),
-- fica no banco e sai para o site por /api/educador-foto/<id>, com cache; a lista de educadores leva só o endereço.

-- 1. A foto aprovada e os pedidos ─────────────────────────────────────────────────────────────────────────────────────────
alter table interno.perfis add column if not exists foto_publica text not null default '';
-- A bio e as redes APROVADAS do cartão ficam em colunas próprias: a bio do perfil (que a pessoa muda quando quiser, na
-- Alumia e em Minha conta) não vai mais para o cartão sem passar pela coordenação. Quem ainda não pediu cartão novo
-- continua com o que já estava no ar (a bio e as redes do perfil) até o primeiro pedido aprovado.
alter table interno.perfis add column if not exists cartao_bio text check (cartao_bio is null or char_length(cartao_bio) <= 500);
alter table interno.perfis add column if not exists cartao_curriculo jsonb check (cartao_curriculo is null or jsonb_typeof(cartao_curriculo) = 'object');
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'perfis_foto_publica_formato') then
    alter table interno.perfis add constraint perfis_foto_publica_formato
      check (foto_publica = '' or (foto_publica ~ '^data:image/webp;base64,[A-Za-z0-9+/=]+$' and char_length(foto_publica) <= 210000));
  end if;
end $$;

create table if not exists interno.cartao_publico_pedidos (
  id uuid primary key default gen_random_uuid(),
  usuario uuid not null references interno.perfis (id) on delete cascade,
  bio text not null default '' check (char_length(bio) <= 500),
  curriculo jsonb not null default '{}'::jsonb check (jsonb_typeof(curriculo) = 'object'),
  foto text not null default '' check (foto = '' or (foto ~ '^data:image/webp;base64,[A-Za-z0-9+/=]+$' and char_length(foto) <= 210000)),
  tirar_foto boolean not null default false,
  status text not null default 'pendente' check (status in ('pendente', 'aprovado', 'recusado', 'substituido')),
  nota text not null default '' check (char_length(nota) <= 1000),
  criado_em timestamptz not null default now(),
  decidido_por uuid references interno.perfis (id) on delete set null,
  decidido_em timestamptz
);
create index if not exists cartao_publico_pendentes on interno.cartao_publico_pedidos (criado_em) where status = 'pendente';
alter table interno.cartao_publico_pedidos enable row level security;
revoke all on interno.cartao_publico_pedidos from public;

-- 2. As redes, conferidas como em perfil_curriculo ────────────────────────────────────────────────────────────────────────
create or replace function interno.cartao_redes(p jsonb) returns jsonb language plpgsql immutable set search_path = interno, pg_temp as $$
declare k text; u text; v_novo jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(coalesce(p, '{}'::jsonb)) <> 'object' then perform interno.erro('invalido:curriculo'); end if;
  foreach k in array array['portfolio', 'lattes', 'site', 'instagram', 'youtube', 'linkedin', 'github'] loop
    u := btrim(coalesce(p ->> k, ''));
    if u <> '' then
      if char_length(u) > 300 or u !~ '^https://[^\s]{3,}$' then perform interno.erro('invalido:' || k); end if;
      v_novo := v_novo || jsonb_build_object(k, u);
    end if;
  end loop;
  u := btrim(coalesce(p ->> 'formacao', ''));
  if u <> '' then v_novo := v_novo || jsonb_build_object('formacao', left(u, 160)); end if;
  return v_novo;
end $$;

-- 3. Pedir, ver o próprio, a fila e decidir ───────────────────────────────────────────────────────────────────────────────
/** O educador pede o cartão novo (foto opcional; "tirar_foto" volta ao cartão sem foto). O pedido anterior pendente é substituído. */
create or replace function public.cartao_publico_pedir(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_foto text := btrim(coalesce(p ->> 'foto', '')); v_id uuid;
begin
  if not exists (select 1 from papeis where usuario = v and papel in ('educacao', 'educacao_secundaria')) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('cartao_publico', 10, 1440);
  if v_foto <> '' and (v_foto !~ '^data:image/webp;base64,[A-Za-z0-9+/=]+$' or char_length(v_foto) > 210000) then perform interno.erro('invalido:foto'); end if;
  update cartao_publico_pedidos set status = 'substituido' where usuario = v and status = 'pendente';
  insert into cartao_publico_pedidos (usuario, bio, curriculo, foto, tirar_foto)
  values (v, interno.txt(p ->> 'bio', 'bio', 0, 500), interno.cartao_redes(p -> 'curriculo'), v_foto, coalesce((p ->> 'tirar_foto')::boolean, false))
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end $$;

/** O cartão no ar e o último pedido da própria pessoa (com a nota da coordenação, se recusado). */
create or replace function public.cartao_publico_meu() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); f perfis; c cartao_publico_pedidos;
begin
  select * into f from perfis where id = v;
  select * into c from cartao_publico_pedidos where usuario = v and status <> 'substituido' order by criado_em desc limit 1;
  return jsonb_build_object(
    'no_ar', jsonb_build_object('bio', coalesce(f.cartao_bio, f.bio, ''), 'curriculo', coalesce(f.cartao_curriculo, f.curriculo, '{}'::jsonb), 'foto', f.foto_publica),
    'pedido', case when c.id is null then null else jsonb_build_object('id', c.id, 'status', c.status, 'nota', c.nota, 'criado_em', c.criado_em,
      'bio', c.bio, 'curriculo', c.curriculo, 'foto', c.foto, 'tirar_foto', c.tirar_foto) end);
end $$;

/** A fila da coordenação: os pedidos pendentes, com o nome de quem pediu e o cartão que está no ar hoje. */
create or replace function public.cartao_publico_fila() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'nome', f.nome, 'criado_em', c.criado_em, 'bio', c.bio, 'curriculo', c.curriculo,
      'foto', c.foto, 'tirar_foto', c.tirar_foto, 'bio_atual', coalesce(f.cartao_bio, f.bio, ''), 'foto_atual', f.foto_publica) order by c.criado_em)
    from cartao_publico_pedidos c join perfis f on f.id = c.usuario where c.status = 'pendente'), '[]'::jsonb);
end $$;

/** Aprovar copia o pedido para o cartão no ar; recusar pede um motivo de pelo menos 5 letras. Quem pediu é avisado. */
create or replace function public.cartao_publico_decidir(p_id uuid, p_aprovar boolean, p_nota text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c cartao_publico_pedidos; v_nota text := interno.txt(p_nota, 'nota', 0, 1000); v_aprovar boolean := coalesce(p_aprovar, false);
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  select * into c from cartao_publico_pedidos where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if c.status <> 'pendente' then perform interno.erro('ja_decidida'); end if;
  if not v_aprovar and char_length(v_nota) < 5 then perform interno.erro('invalido:nota'); end if;
  update cartao_publico_pedidos set status = case when v_aprovar then 'aprovado' else 'recusado' end, nota = v_nota, decidido_por = v, decidido_em = now() where id = p_id;
  if v_aprovar then
    update perfis set cartao_bio = c.bio, cartao_curriculo = c.curriculo,
      foto_publica = case when c.tirar_foto then '' when c.foto <> '' then c.foto else foto_publica end
    where id = c.usuario;
  end if;
  perform interno.registrar(case when v_aprovar then 'cartao_publico_aprovado' else 'cartao_publico_recusado' end, c.usuario::text);
  perform interno.avisar(c.usuario, case when v_aprovar then 'Seu cartão de educador foi aprovado e já aparece no site.'
    else 'Seu cartão de educador não foi aprovado: ' || left(v_nota, 300) end);
  return jsonb_build_object('ok', true);
end $$;

/** A foto aprovada de um educador (só de quem ensina e não está suspenso), para a rota /api/educador-foto/<id>. */
create or replace function public.educador_foto(p_id uuid) returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select nullif(f.foto_publica, '') from perfis f
  where f.id = p_id and not f.suspenso and exists (select 1 from papeis p where p.usuario = f.id and p.papel in ('educacao', 'educacao_secundaria'))
$$;

/** A lista de educadores, agora com o endereço da foto aprovada (a foto em si vai pela rota, com cache). */
create or replace function public.educadores() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', f.nome, 'bio', coalesce(f.cartao_bio, f.bio), 'avatar', f.avatar,
           'curriculo', coalesce(f.cartao_curriculo, f.curriculo, '{}'::jsonb),
           'foto', case when f.foto_publica <> '' then '/api/educador-foto/' || f.id::text || '?v=' || substr(md5(f.foto_publica), 1, 8) else '' end,
           'disciplinas', (select jsonb_agg(distinct p.disciplina) from papeis p where p.usuario = f.id and p.papel in ('educacao', 'educacao_secundaria') and p.disciplina is not null))
           order by f.nome), '[]'::jsonb)
  from perfis f
  where not f.suspenso and exists (select 1 from papeis p where p.usuario = f.id and p.papel in ('educacao', 'educacao_secundaria'))
$$;

-- 4. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.cartao_redes(jsonb) from public;
revoke all on function public.cartao_publico_pedir(jsonb), public.cartao_publico_meu(), public.cartao_publico_fila(),
  public.cartao_publico_decidir(uuid, boolean, text), public.educador_foto(uuid) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant execute on function public.cartao_publico_pedir(jsonb), public.cartao_publico_meu(), public.cartao_publico_fila(),
      public.cartao_publico_decidir(uuid, boolean, text), public.educador_foto(uuid), public.educadores() to anon, authenticated, service_role;
  end if;
end $$;

-- Instituto Lúcia — © Jonathan Santos. Licença: AGPL-3.0-or-later (veja LICENSE).
-- Os parceiros nos seus territórios (09/11/2026). Os coletivos parceiros já têm o departamento de participação
-- "parcerias"; aqui cada pessoa parceira fica ligada ao território do seu coletivo (o slug de content/territorios.json),
-- e quem está ligado posta as novidades do território. As postagens aparecem na página do território e na seção
-- "Dos territórios" do Jornal. Vão ao ar na hora (a coordenação confiou o vínculo) e a coordenação, ou quem postou,
-- tira do ar com motivo; o filtro de palavras do site vale também aqui.

-- 1. Quem é parceiro de qual território ──────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.territorio_parceiros (
  territorio text not null check (territorio ~ '^[a-z0-9-]{2,60}$'),
  usuario uuid not null references interno.perfis (id) on delete cascade,
  incluido_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  primary key (territorio, usuario)
);
alter table interno.territorio_parceiros enable row level security;
revoke all on interno.territorio_parceiros from public;

-- 2. As postagens ────────────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists interno.territorio_posts (
  id uuid primary key default gen_random_uuid(),
  territorio text not null check (territorio ~ '^[a-z0-9-]{2,60}$'),
  autor uuid references interno.perfis (id) on delete set null,
  titulo text not null check (char_length(titulo) between 5 and 140),
  texto text not null check (char_length(texto) between 20 and 4000),
  link text not null default '' check (link = '' or (link ~ '^https://[^[:space:]]+$' and char_length(link) <= 500)),
  criado_em timestamptz not null default now(),
  oculto boolean not null default false,
  oculto_por uuid references interno.perfis (id) on delete set null,
  oculto_motivo text not null default '' check (char_length(oculto_motivo) <= 300)
);
create index if not exists territorio_posts_no_ar on interno.territorio_posts (territorio, criado_em desc) where not oculto;
alter table interno.territorio_posts enable row level security;
revoke all on interno.territorio_posts from public;

create or replace function interno.territorio_post_json(x interno.territorio_posts) returns jsonb language sql stable as $$
  select jsonb_build_object('id', x.id, 'territorio', x.territorio, 'titulo', x.titulo, 'texto', x.texto, 'link', x.link, 'criado_em', x.criado_em)
$$;

-- 3. Funções ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
/** Ligar (ou desligar, com p_ligar false) uma pessoa a um território. Só a coordenação. Ligar põe a pessoa em Parcerias. */
create or replace function public.territorio_parceiro_definir(p_usuario uuid, p_territorio text, p_ligar boolean default true) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_territorio, '') !~ '^[a-z0-9-]{2,60}$' then perform interno.erro('invalido:territorio'); end if;
  if not exists (select 1 from perfis where id = p_usuario) then perform interno.erro('nao_encontrado'); end if;
  if coalesce(p_ligar, true) then
    insert into territorio_parceiros (territorio, usuario, incluido_por) values (p_territorio, p_usuario, v) on conflict do nothing;
    insert into departamento_membros (departamento, usuario, incluido_por) values ('parcerias', p_usuario, v) on conflict do nothing;
    perform interno.avisar(p_usuario, 'Você agora posta as novidades do seu território no site. Abra a página do território para escrever.');
  else
    delete from territorio_parceiros where territorio = p_territorio and usuario = p_usuario;
  end if;
  perform interno.registrar(case when coalesce(p_ligar, true) then 'territorio_parceiro_ligado' else 'territorio_parceiro_desligado' end, p_usuario::text, jsonb_build_object('territorio', p_territorio));
  return jsonb_build_object('ok', true);
end $$;

/** Os vínculos (coordenação): quem posta em cada território. */
create or replace function public.territorio_parceiros_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object('territorio', t.territorio, 'usuario', t.usuario, 'nome', f.nome, 'criado_em', t.criado_em) order by t.territorio, f.nome)
    from territorio_parceiros t join perfis f on f.id = t.usuario), '[]'::jsonb);
end $$;

/** Os territórios em que a própria pessoa posta (vazio para quem não é parceiro). */
create or replace function public.territorio_meus() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid();
begin
  if v is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(territorio order by territorio) from territorio_parceiros where usuario = v), '[]'::jsonb);
end $$;

/** Postar uma novidade do território (só quem está ligado a ele). */
create or replace function public.territorio_postar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_t text := coalesce(p ->> 'territorio', ''); v_titulo text; v_texto text; v_link text := btrim(coalesce(p ->> 'link', '')); v_id uuid;
begin
  if not exists (select 1 from territorio_parceiros where territorio = v_t and usuario = v) then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('territorio_postar', 20, 1440);
  v_titulo := interno.txt(p ->> 'titulo', 'titulo', 5, 140);
  v_texto := interno.txt(p ->> 'texto', 'texto', 20, 4000);
  if v_link <> '' and (v_link !~ '^https://[^[:space:]]+$' or char_length(v_link) > 500) then perform interno.erro('invalido:link'); end if;
  if interno.vetado(v_titulo || ' ' || v_texto) then perform interno.erro('conteudo_recusado'); end if;
  insert into territorio_posts (territorio, autor, titulo, texto, link) values (v_t, v, v_titulo, v_texto, v_link) returning id into v_id;
  return jsonb_build_object('id', v_id);
end $$;

/** Tirar uma postagem do ar: a coordenação ou quem postou. */
create or replace function public.territorio_post_ocultar(p_id uuid, p_motivo text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x territorio_posts;
begin
  select * into x from territorio_posts where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not (interno.coord() or x.autor = v) then perform interno.erro('sem_permissao'); end if;
  update territorio_posts set oculto = true, oculto_por = v, oculto_motivo = interno.txt(p_motivo, 'motivo', 0, 300) where id = p_id;
  perform interno.registrar('territorio_post_oculto', x.territorio, jsonb_build_object('post', p_id));
  return jsonb_build_object('ok', true);
end $$;

/** As postagens de um território (público). Quem é parceiro dele vê também o botão de tirar do ar (campo "minha"). */
create or replace function public.territorio_posts(p_territorio text, p_limite integer default 20) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(interno.territorio_post_json(x) || jsonb_build_object('minha', x.autor is not null and x.autor = auth.uid()) order by x.criado_em desc), '[]'::jsonb)
  from (select * from territorio_posts where territorio = p_territorio and not oculto order by criado_em desc limit least(greatest(coalesce(p_limite, 20), 1), 50)) x
$$;

/** As últimas postagens de todos os territórios, para a seção "Dos territórios" do Jornal (público). */
create or replace function public.territorio_posts_recentes(p_limite integer default 6) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(interno.territorio_post_json(x) order by x.criado_em desc), '[]'::jsonb)
  from (select * from territorio_posts where not oculto order by criado_em desc limit least(greatest(coalesce(p_limite, 6), 1), 24)) x
$$;

-- 4. Permissões ──────────────────────────────────────────────────────────────────────────────────────────────────────────
revoke all on function interno.territorio_post_json(interno.territorio_posts) from public;
revoke all on function public.territorio_parceiro_definir(uuid, text, boolean), public.territorio_parceiros_listar(), public.territorio_meus(),
  public.territorio_postar(jsonb), public.territorio_post_ocultar(uuid, text), public.territorio_posts(text, integer), public.territorio_posts_recentes(integer) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant execute on function public.territorio_parceiro_definir(uuid, text, boolean), public.territorio_parceiros_listar(), public.territorio_meus(),
      public.territorio_postar(jsonb), public.territorio_post_ocultar(uuid, text), public.territorio_posts(text, integer), public.territorio_posts_recentes(integer)
      to anon, authenticated, service_role;
  end if;
end $$;

